window.REG_DATA={"families":[{"id":"hoechik","cat":"회칙","short":"학생회칙","versions":[{"id":"hoechik-20181012","date":"2018.10.12","kind":"전부개정","title":"고려대학교 자유전공학부 학생회칙","subtitle":null,"history":[["2009. 03.","제정"],["2011. 05. 11.","일부개정"],["2013. 10. 30.","일부개정"],["2014. 03. 26.","일부개정"],["2014. 09. 22.","일부개정"],["2015. 03. 24.","일부개정"],["2015. 09. 22.","일부개정"],["2016. 08. 29.","전부개정"],["2017. 03. 02.","일부개정"],["2017. 05. 27.","전부개정"],["2017. 08. 19.","전부개정"],["2018. 10. 12.","전부개정"]],"pdf":"pdf/hoechik-20181012.pdf","pdfName":"고려대학교_자유전공학부_학생회칙(2018.10.12_전부개정).pdf","blocks":[{"t":"pre","title":"전문","paras":["정의를 추구하는 고려대학교의 역사적 사명과 함께 공동체를 선도하고 연대하는 자유전공학부는 창설 이래 이어져 온 민주적 전통과 자유·정의·진리를 좇는 본교의 교육 이념, 학문 및 사상에 대한 창조적 탐구 정신을 이어받아 자유전공학부의 주체적이고 자율적이며 민주적인 활동을 다짐하는 바이다. 이에 2009년 3월 제정되고 11차에 걸쳐 개정된 자유전공학부 학생회칙을 자유전공학부 학생대표자회의의 의결을 거쳐 개정한다."],"date":null},{"t":"h","lv":2,"text":"제1장 총 칙"},{"t":"art","id":"a1","label":"제1조","title":"명칭","paras":[{"k":"line","x":"본회는 고려대학교 자유전공학부 학생회라 칭한다."}],"num":1,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a2","label":"제2조","title":"목적","paras":[{"k":"hang","x":"① 본회는 민주적이고 자율적인 학생자치활동을 통하여 회원 간의 결속을 강화하고 회원의 권익 신장을 도모하며 자유로운 진리의 탐구와 창조적이고 진보적인 대학문화의 건설을 추구하여 사회발전에 능동적으로 기여한다."},{"k":"hang","x":"② 본회는 시대의 불의에 맞서 사회적 연대를 구축하고 침해된 정의의 회복을 위해 대내외에서 주체적으로 행동한다."},{"k":"hang","x":"③ 본회는 본회의 자산 및 자치공간과 회원이 지닌 권리를 보호한다."},{"k":"hang","x":"④ 본회는 법률적 기초소양 및 다양한 영역에서의 복합적 전문성을 갖춘 공적 영역의 선도적 지도자를 양성한다는 교육목적을 달성하기 위해 노력하며, 제1전공이 다른 회원들 간의 교류를 장려한다."}],"num":2,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a3","label":"제3조","title":"위치","paras":[{"k":"line","x":"본회는 서울특별시 성북구 안암동 고려대학교 법학관(구관), 법학관(신관) 및 CJ법학관에 위치한다."}],"num":3,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a4","label":"제4조","title":"회원","paras":[{"k":"hang","x":"① 본회의 회원은 입학ㆍ재입학ㆍ편입학ㆍ소속변경 등으로 고려대학교 자유전공학부 소속이 된 자를 원칙으로 한다."},{"k":"hang","x":"② 졸업, 자퇴, 퇴학 등으로 고려대학교 서울캠퍼스 학부과정 소속이 아니게 된 자 및 총학생회 제명으로 인해 총학생회 회원 직을 박탈당한 자는 그 즉시 회원 자격을 잃으며 정학 등의 사유로 등교가 정지된 자는 그 기간 회원 자격이 정지된다."},{"k":"hang","x":"③ 제2항의 경우 회원의 자격이 부당하게 정지, 박탈된 자는 학부운영위원회의 출석 3분의 2 이상에 해당하는 결의로 회원 지위를 회복할 수 있다."},{"k":"hang","x":"④ 본회의 회원 중 재학 중인 자는 다음 각호의 기간 동안 본회의 정회원이 된다. 단, 재학 중 휴학 한 자는 그 즉시 정회원 자격을 상실하고 휴학생 회원이 된다."},{"k":"ho","x":"1. 1학기 재학생 : 1학기 개강일로부터 2학기 개강일 전일"},{"k":"ho","x":"2. 2학기 재학생 : 2학기 개강일로부터 이듬해 1학기 개강일 전일"},{"k":"hang","x":"⑤ 본회의 회원 중 휴학한 자는 휴학생 회원이라고 하며, 선거권을 지닐 수 없다."},{"k":"hang","x":"⑥ 본회의 회원 중에서 다음 각호의 요건을 모두 충족하는 회원은 고학번 회원이라고 한다."},{"k":"ho","x":"1. 고려대학교에 입학한 지 4학기 이상이 지난 회원"},{"k":"ho","x":"2. 신입회원과 두 학번 이상 차이가 나는 회원"},{"k":"hang","x":"⑦ 본회의 회원 중에서 다음 각호에 해당하는 회원은 신입생 회원이라고 한다."},{"k":"ho","x":"1. 고려대학교에 입학한 지 2학기가 지나지 않은 회원"},{"k":"ho","x":"2. 편입학ㆍ소속변경 등으로 자유전공학부 재학생이 된 지 2학기가 지나지 않은 회원"},{"k":"hang","x":"⑧ 회원 여부에 시비가 있을 시 자유전공학부 운영위원회는 자유전공학부 행정실을 통해 확인한 재학생 명단, 휴학생 명단, 타 학부 학생 중에서 본회의 회원으로 등록한 명단을 참고하여 회원 여부를 판단한다."}],"num":4,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a5","label":"제5조","title":"회원의 권리","paras":[{"k":"hang","x":"① 본회의 회원은 성별ㆍ연령ㆍ장애ㆍ병력ㆍ피부색ㆍ용모 등 신체조건, 인종ㆍ언어ㆍ출신 국가ㆍ출신 민족ㆍ출신 지역 등 출생지, 혼인상태ㆍ출산 형태 등 가족 형태, 종교ㆍ정치적 견해ㆍ성적지향ㆍ성별 정체성ㆍ출신학교ㆍ학력ㆍ전공ㆍ재산 등 사회적 신분에 의하여 차별을 받지 아니한다."},{"k":"hang","x":"② 본회의 회원은 본회의 모든 자치활동에 참여할 권리와 회칙에 근거한 선거권, 피선거권을 가진다."},{"k":"hang","x":"③ 본회의 회원은 회칙에 따라 본회의 활동과 운영 전반에 관하여 의견을 개진할 권리와 본회를 부인하거나 정당한 학생자치활동을 침해하는 것에 대해 저항할 권리를 가진다."},{"k":"hang","x":"④ 본회의 회원은 집회ㆍ결사의 자유 및 자유로운 종교ㆍ정치 활동에 대한 권리를 가진다."},{"k":"hang","x":"⑤ 본회의 회원은 본회의 모든 활동 및 재정 운영에 대해 보고를 받을 권리를 가진다."},{"k":"hang","x":"⑥ 본회의 회원은 본회가 지니는 급부를 적절한 시기에 제공받을 권리를 가진다."},{"k":"hang","x":"⑦ 본회의 회원은 자치공간 및 본회 자산을 향유할 권리를 가진다."},{"k":"hang","x":"⑧ 본회와 본회의 각 기구는 고학번 회원의 본회와 본회의 각 기구 활동 참여를 보장해야 하며, 회원 간 원활한 교류를 위해 노력해야 한다."},{"k":"hang","x":"⑨ 본회와 본회의 각 기구는 신입생 회원이 학번ㆍ연령으로 인해 부당한 대우를 받지 않도록 노력해야 한다."},{"k":"hang","x":"⑩ 본회와 본회의 각 기구는 본조에 열거된 회원의 권리가 대내외적으로 침해받지 않도록 항상 노력하여야 하며, 회원의 권리가 침해될 때 이를 적극적으로 수호하여야 한다."}],"num":5,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a6","label":"제6조","title":"회원의 의무","paras":[{"k":"hang","x":"① 본회의 회원은 회칙을 준수할 의무를 지닌다."},{"k":"hang","x":"② 본회의 회원은 본회가 결정한 사항을 준수할 의무를 지닌다."},{"k":"hang","x":"③ 본회의 회원은 회비를 납부할 의무를 지닌다."},{"k":"hang","x":"④ 본회의 회원은 본회의 자산을 보호할 의무를 지닌다."}],"num":6,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a7","label":"제7조","title":"구성","paras":[{"k":"hang","x":"① 본회는 민주적이고 효율적인 운영을 통한 학생자치의 실현을 위하여 다음 각호의 의결기구, 집행기구, 산하기구, 독립기구를 둔다."},{"k":"ho","x":"1. 의결기구: 학생총회, 학생대표자회, 학부운영위원회, 비상대책위원회"},{"k":"ho","x":"2. 집행기구: 학부 학생회장단, 집행위원회"},{"k":"ho","x":"3. 산하기구: 반 학생회, 자치단체연합회, 자치단체, 특별위원회"},{"k":"ho","x":"4. 독립기구: 선거관리위원회, 투표관리위원회, 장학금위원회, 학생홍보대사, 전공자협의회 , 소수자인권위원회"}],"num":7,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a8","label":"제8조","title":"학교운영 참여","paras":[{"k":"hang","x":"① 본회의 활동과 관련하여 학교 당국과의 협의 또는 조정이 필요한 경우 본회의 각 기구는 학교운영에 적극적으로 참여하며 필요시 학교 당국에 자료제출을 요청할 수 있다."},{"k":"hang","x":"② 본회는 다음 각호의 경우 학교의 운영에 적극 참여하여 의견을 개진하고 관련 진행 상황 및 결정 사항을 회원에게 공고하여야 한다."},{"k":"ho","x":"1. 본회의 활동과 관계된 회원의 징계 사항에 관해 회원을 변호할 필요가 있는 경우"},{"k":"ho","x":"2. 본회의 회원의 자치활동과 권익 보호가 필요한 경우"},{"k":"ho","x":"3. 자유전공학부 발전 방향 설정, 학제개편, 학칙개정 등의 임박하거나 이미 결정된 학교의 정책 및 결정사항이 본회 회원의 이익에 중대한 변화를 야기할 경우"},{"k":"ho","x":"4. 그 밖에 본회의 목적과 관련된 중요 사항"}],"num":8,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a9","label":"제9조","title":"대표자의 책임","paras":[{"k":"line","x":"학생회장단, 학부운영위원, 학생대표자 대의원은 본회의 대표자로서 본회의 민주적이고 효율적인 운영과 각 기구의 협력을 통해 그 운영 목적을 달성할 수 있도록 주어진 역할을 책임 있게 수행하여야 한다."}],"num":9,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a10","label":"제10조","title":"겸직 금지","paras":[{"k":"hang","x":"① 본회의 회원은 다음 각호의 직을 동시에 2개 이상 가질 수 없다. 단, 제3호와 제4호의 겸직의 경우, 학부운영위원회의 출석 과반수에 해당하는 결의가 있으면 겸직이 허용된다."},{"k":"ho","x":"1. 학부 학생회장과 부학생회장"},{"k":"ho","x":"2. 반 학생회장과 부학생회장"},{"k":"ho","x":"3. 고학번 대표 및 신입생 대표"},{"k":"ho","x":"4. 각 자치단체장"},{"k":"ho","x":"5. 그 밖에 학부운영위원회 위원 자격이 부여되는 직책"},{"k":"hang","x":"② 집행위원은 반 학생회장의 직을 겸직하기 위해서는 학생대표자회의 출석 과반수에 해당하는 결의로 인준을 받아야 한다."},{"k":"hang","x":"③ 제１항 각호의 직을 동시에 2개 이상 갖게 되었을 시 즉시 마지막에 갖게 된 직을 제외한 나머지 직에서는 해임된 것으로 본다."}],"num":10,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a11","label":"제11조","title":"사무 처리","paras":[{"k":"hang","x":"① 본회 각 기구의 사무 처리는 간소화ㆍ표준화와 정보화를 통해 효율적으로 이루어져야 한다."},{"k":"hang","x":"② 정확과 신속을 기하고 책임의 소재를 명백히 밝히기 위하여 본회의 사무 처리와 대표자의 행위는 문서로써 함을 원칙으로 한다."},{"k":"hang","x":"③ 본회에서 장기간에 걸쳐 반복적으로 사용하는 문서로서 정형화할 수 있는 문서는 특별한 사유가 없으면 서식으로 정하여 사용한다."},{"k":"hang","x":"④ 회칙에서 공고하도록 한 사항은 회원들이 해당 공고를 쉽게 접할 수 있도록 법학관(구관)의 대표 게시판과 자유전공학부 행정실 게시판, 자유전공학부 홈페이지 학생회 온라인 게시판에 게시하여야 하며, 가시성이 확보되도록 공고의 모양을 정하여야 한다."},{"k":"hang","x":"⑤ 그 밖에 사무 처리에 관한 세부적인 사항은 학부운영위원회의 출석 과반수에 해당하는 결의로 ｢고려대학교 총학생회 사무처리세칙｣을 준용한다."}],"num":11,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a12","label":"제12조","title":"기록물 관리","paras":[{"k":"hang","x":"① 본회의 모든 활동은 기록되고, 기록물이 각 활동의 근거가 되는 것을 원칙으로 한다."},{"k":"hang","x":"② 본회는 지속적이고 체계적인 기록물 관리를 위해 적극 노력해야 하며, 기록물 관리기관이 효율적으로 기록물을 관리할 수 있도록 지원해야 한다."},{"k":"hang","x":"③ 다음 각호에 해당하는 기록물의 생산ㆍ수집 이후에는 임의로 수정할 수 없으며 훼손하거나 폐기할 수 없다. 단, 각호에 해당하는 경우 각호에서 정한 목적의 제한된 범위 내에서 게시물을 수정할 수 있다."},{"k":"ho","x":"1. 속기록의 내용이 실제 발언과 부합하지 않은 것을 7일 이내에 발견했을 시"},{"k":"ho","x":"2. 학생회 페이지, 그룹, 자유전공학부 홈페이지 게시판 등에 올린 게시물의 탈ㆍ오자 수정이 필요할 시"},{"k":"ho","x":"3. 학생회 페이지, 그룹, 자유전공학부 홈페이지 게시판 등에 올린 게시물의 내용에 중대한 하자를 발견하여 하자의 치유를 위한 수정 및 비공개 조치가 필요할 시"},{"k":"ho","x":"4. 같은 시각에 중복게시물을 올려 비공개 조치가 필요할 시"},{"k":"hang","x":"④ 본회가 생산ㆍ수집하는 모든 기록물은 회원들에게 공개되어야 하고 본회의 행정 사무와 의사 결정, 학술 연구 등의 활동을 위해 언제든지 참고할 수 있도록 투명하게 관리되어야 한다."},{"k":"hang","x":"⑤ 본회는 회원의 개인정보를 보호해야 할 의무가 있다. 본회가 수집한 개인정보는 당사자의 동의를 얻었거나 명확한 근거를 가진 정당한 목적을 있을 때만 열람ㆍ활용할 수 있다."},{"k":"hang","x":"⑥ 본회의 회원과 학술적 목적과 공익을 위해 본회의 기록물을 활용하려는 자는 본회의 모든 기록물에 대한 접근권이 있으며 정보공개청구로 기록물을 열람ㆍ활용할 수 있다."},{"k":"hang","x":"⑦ 본회의 각 기구는 본회의 회원과 학술적 목적과 공익을 위해 본회의 기록물을 활용하려는 자의 정보공개청구를 거부할 수 없다. 단, 다음 각호에 해당할 때는 학부운영위원회의 출석 과반수에 해당하는 결의로 일부만 공개하도록 할 수 있다."},{"k":"ho","x":"1. 본회의 회원이 아닌 자가 정보공개를 청구한 때"},{"k":"ho","x":"2. 정보의 공개로 인해 특정 회원의 개인정보 유출이 우려될 때"},{"k":"ho","x":"3. 정보의 공개가 본회 회원의 이익의 심각한 감소를 초래할 때"},{"k":"ho","x":"4. 기타 공익적 목적이 있을 때"},{"k":"hang","x":"⑧ 그 밖에 기록물 관리에 관한 세부적인 사항은 학부운영위원회의 출석 과반수에 해당하는 결의로 ｢고려대학교 총학생회 기록물관리세칙｣을 준용한다."}],"num":12,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a13","label":"제13조","title":"준용","paras":[{"k":"hang","x":"① 본회는 본회의 상위기구의 회칙, 세칙 및 규칙을 준용할 수 있다."},{"k":"hang","x":"② 제1항에 해당하는 결정은 준용에 관해 특별한 요건이 없는 경우, 학생총회의 출석 과반수 또는 학생대표자회의 출석 과반수에 해당하는 결의로 한다."}],"num":13,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a14","label":"제14조","title":"세칙","paras":[{"k":"line","x":"본회는 회칙에 의거해 세칙을 제정 및 개정한다."}],"num":14,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제2장 의결기구"},{"t":"h","lv":3,"text":"제１절 통 칙"},{"t":"art","id":"a15","label":"제15조","title":"기본이념","paras":[{"k":"line","x":"본회의 의결기구는 본회를 대표하는 의사를 결정하는 기구로서 민주적이고 공정하며 효율적인 절차에 따라 운영되어야 한다."}],"num":15,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a16","label":"제16조","title":"의결기구의 위계","paras":[{"k":"hang","x":"① 본회의 의결기구는 학생총회, 학생대표자회, 학부운영위원회 순으로 위계를 지닌다."},{"k":"hang","x":"② 다른 위계에 속한 의결기구 간의 의사결정 내용이 상이할시 하위 의결기구의 의사결정 내용은 상위 의결기구의 의사결정 내용과 합치되는 범위 내에서 효력을 지닌다."},{"k":"hang","x":"③ 하위 의결기구에서 의결할 수 있도록 한 사항은 해당 의결기구보다 상위 의결기구에서도 의결할 수 있다."}],"num":16,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a17","label":"제17조","title":"회기","paras":[{"k":"line","x":"본회 의결기구의 회기는 다음 각호의 기간으로 나눈다."},{"k":"ho","x":"1. 제1회기: 2학기 종강일 다음 날부터 1학기 개강일 전날까지"},{"k":"ho","x":"2. 제2회기: 1학기 개강일부터 1학기 종강일까지"},{"k":"ho","x":"3. 제3회기: 1학기 종강일 다음 날부터 2학기 개강일 전날까지"},{"k":"ho","x":"4. 제4회기: 2학기 개강일부터 2학기 종강일까지"}],"num":17,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a18","label":"제18조","title":"의장","paras":[{"k":"hang","x":"① 본회 의결기구의 의장은 학부 학생회장으로 함을 원칙으로 한다. 단, 학부 학생회장 사고 시 학부 부학생회장이 그 직을 대신하며, 학부 학생회장과 학부 부학생회장이 모두 사고이거나, 학부 학생회장단 모두 또는 그 중 한 명에 대한 탄핵 안건, 탄핵안 학생총투표 발의 안건이 상정된 의결기구는 학생회장단을 제외한 학부운영위원 중 한 명이 그 직을 대신한다."},{"k":"hang","x":"② 의장은 본회 의결기구를 대표하고 의사를 정리하며 질서를 유지하고 사무를 감독한다."},{"k":"hang","x":"③ 의장은 본회 절차에 따라 공정하고 효율적으로 회의를 진행하여야 한다."}],"num":18,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a19","label":"제19조","title":"사무ㆍ재정","paras":[{"k":"hang","x":"① 의결기구의 사무 처리는 집행위원회가 담당하며 학부운영위원회는 의결기구의 원활한 사무 처리를 감시ㆍ감독할 의무를 지닌다."},{"k":"hang","x":"② 본회는 의결기구의 원활한 운영을 위한 재원을 마련해야 한다."},{"k":"hang","x":"③ 집행위원회는 속기의 방법으로 회의록을 작성하고 다음 사항을 기재해야 한다."},{"k":"ho","x":"1. 회의 장소"},{"k":"ho","x":"2. 개회, 회의 중지와 산회의 일시"},{"k":"ho","x":"3. 개회 당시와 안건 의결 당시의 출석 대의원 명단"},{"k":"ho","x":"4. 부의 안건의 제목 및 내용"},{"k":"ho","x":"5. 의사 표명의 내용"},{"k":"ho","x":"6. 표결 결과 (기명투표의 경우 각 대의원의 표결 사항을 기재)"},{"k":"ho","x":"7. 의장 또는 학부운영위원회가 필요하다고 인정하는 사항"},{"k":"hang","x":"④ 의장은 개의일로부터 3일 이내에 제3항의 회의록을 공개하고 회의결과를 공고하여야 한다."}],"num":19,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a20","label":"제20조","title":"긴급한 사항","paras":[{"k":"hang","x":"① “긴급한 사항”이란 회의 소집 과정을 생략해서라도 긴급하게 의사를 결정해야 할 사항을 의미한다."},{"k":"hang","x":"② 긴급한 사항에 대한 해석은 각호의 목적 사항으로 제한한다."},{"k":"ho","x":"1. 본회의 활동과 관계된 회원의 징계 사항에 관해 변호가 필요할 경우"},{"k":"ho","x":"2. 본회 회원의 이익에 중대한 변화를 야기하는 자유전공학부 발전 방향 설정, 학제개편, 학칙개정 등의 학교 결정이 임박해 있거나 이미 결정된 경우"},{"k":"ho","x":"3. 그 밖에 본회의 목적과 관련된 중요 사항"},{"k":"hang","x":"③ 긴급한 사항이 있을 시 본회 의결기구 의장의 소집요구 없이도 학부운영위원회의 출석 과반수에 해당하는 결의로 임시학생총회를 소집할 수 있다."}],"num":20,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a21","label":"제21조","title":"안건의 발의","paras":[{"k":"hang","x":"① 안건 발의는 각 의결기구에서 정한 발의 요건에 따른다."},{"k":"hang","x":"② 안건 발의는 소집요구와 함께 이루어져야 한다. 단, 소집공고부터 산회 전까지 발의된 추가 안건에 대해서는 재적 구성원 과반수의 출석과 출석 구성원 과반수에 해당하는 결의로 한다."}],"num":21,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a22","label":"제22조","title":"안건의 의결","paras":[{"k":"hang","x":"① 각 의결기구의 재적 구성원 과반수의 출석과 출석 구성원 과반수에 해당하는 결의로 안건을 의결한다. 가부동수 및 찬성이 과반에 미치지 못할 경우 부결된 것으로 본다."},{"k":"hang","x":"② 안건의 의결 시 의결요건을 정하는 기준이 되는 출석 구성원 수는 각 안건의 의결 당시 집계된 구성원 명단을 기준으로 계산한다."},{"k":"hang","x":"③ 의결기구의 의결권은 구성원이 평등하게 가지며 직접 출석하여 행사하여야 한다."}],"num":22,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a23","label":"제23조","title":"안건의 표결","paras":[{"k":"hang","x":"① 표결은 기명으로 함을 원칙으로 한다."},{"k":"hang","x":"② 중요한 안건으로써 의장 또는 회원이 제의하고 의결 기구 재적 구성원 3분의 2 이상에 해당하는 결의가 있으면 무기명으로 표결할 수 있다."},{"k":"hang","x":"③ 다음 각호의 사항에 관한 의결은 반드시 기명투표로 표결하여야 한다."},{"k":"ho","x":"1. 제40조 제１항의 회칙 개정에 관한 사항"},{"k":"ho","x":"2. 제40조 제２항의 세칙 제정ㆍ개정ㆍ폐지에 관한 사항"},{"k":"hang","x":"④ 다음 각호의 사항에 관한 의결은 반드시 무기명투표로 표결하여야 한다."},{"k":"ho","x":"1. 제35조 학부 학생회장단 탄핵안에 관한 사항"},{"k":"ho","x":"2. 제36조 제2항 집행위원 해임에 관한 사항"},{"k":"ho","x":"3. 제38조의 징계에 관한 사항"},{"k":"ho","x":"4. 제39조 제1항 및 제２항의 학부 학생회비 지급에 관한 사항"},{"k":"hang","x":"⑤ 의장은 안건에 대한 이의의 유무를 물어서 이의가 없다고 인정한 때에는 가결되었음을 선포할 수 있다. 그러나 이의가 있는 안건일 경우 또는 무기명표결을 요하는 안건의 경우 반드시 표결하여야 한다."},{"k":"hang","x":"⑥ 의장 또는 회원의 제의와 출석 과반수의 찬성으로 전자투표에 의한 기록표결을 시행할 수 있다."}],"num":23,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a24","label":"제24조","title":"방청ㆍ발언권","paras":[{"k":"hang","x":"① 본회의 회원은 각 의결기구를 방청할 수 있다."},{"k":"hang","x":"② 본회의 회원은 각 의결기구에서 발언할 수 있는 권리를 가진다."},{"k":"hang","x":"③ 의장은 질서 유지 및 효율적인 의사 진행을 위해 방청인 수를 제한하거나 회원의 발언권을 제한할 수 있으며, 회의장 안의 질서를 현저히 방해하는 방청인의 경우 퇴장을 명할 수 있다."},{"k":"hang","x":"④ 의결기구의 구성원석과 방청인석은 구분이 되도록 배치한다."}],"num":24,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a25","label":"제25조","title":"회의진행세칙","paras":[{"k":"line","x":"그 밖에 의결기구의 회의 진행에 관한 사항은 학부운영위원회의 출석 과반수에 해당하는 결의로 ｢고려대학교 총학생회 회의진행세칙｣을 준용한다."}],"num":25,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제２절 학생총회"},{"t":"art","id":"a26","label":"제26조","title":"지위 및 구성","paras":[{"k":"line","x":"학생총회는 본회의 최고의결기구로 본회의 회원 전원으로 구성한다."}],"num":26,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a27","label":"제27조","title":"소집요건","paras":[{"k":"hang","x":"① 학생총회 임시회는 다음 각호 중 하나에 의해 의장이 소집한다."},{"k":"ho","x":"1. 학부운영위원회의 소집요구"},{"k":"ho","x":"2. 학생대표자회의 소집요구"},{"k":"ho","x":"3. 회원 50명 이상의 연서에 따른 소집요구"},{"k":"ho","x":"4. 제90조에 따라 발의된 학부 학생회장단 사퇴 허가 요청"},{"k":"ho","x":"5. 제91조에 따른 학부 학생회장단 탄핵 발의"},{"k":"ho","x":"6. 제175조에 따른 회칙 개정안 발의"},{"k":"hang","x":"② 연서에 따른 소집요구는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식에 의하여야 하며, ｢고려대학교 총학생회 사무처리세칙｣에서 정한 사항이 포함되어야 한다."},{"k":"hang","x":"③ 연서에 따른 소집요구가 있으면 학부운영위원회는 지체 없이 학생총회 개의일을 결정한다. 이 때 개의일은 소집요구 서식에 기재된 개의 희망일로 함을 원칙으로 하되 변경할 때는 학부운영위원의 출석 3분의 2 이상에 해당하는 결의로 한다. 단, 이 경우에도 개의 희망일과 2주 이상 차이가 나서는 안 된다."}],"num":27,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a28","label":"제28조","title":"소집 공고","paras":[{"k":"hang","x":"① 학생총회 의장은 학생총회의 소집을 개의일 7일 전에 공고하여야 한다."},{"k":"hang","x":"② 공고문에는 다음 각호의 사항을 명시하여야 한다."},{"k":"ho","x":"1. 회의 시작 일시"},{"k":"ho","x":"2. 회의 장소"},{"k":"ho","x":"3. 안건과 안건에 대한 설명"}],"num":28,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a29","label":"제29조","title":"자료의 사전 배포","paras":[{"k":"line","x":"학생총회 의장은 학생총회 정기회의 개의 5일 전까지 제출된 안건과 그에 관한 설명, 집행위원회 등의 보고ㆍ인준 사항, 각 기구의 학생회비 예산안ㆍ결산 등이 포함된 자료집을 회원들을 대상으로 배포하여야 한다. 배포는 책자 형태로 제작하여 비치하는 방법과 전산화된 형태의 문서로 제작하여 온라인에 게시하는 방법으로 한다."}],"num":29,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a30","label":"제30조","title":"개의ㆍ의결요건","paras":[{"k":"hang","x":"① 학생총회는 회원 7분의 1 이상의 출석으로 개의하고, 출석 과반수에 해당하는 결의로 의결한다."},{"k":"hang","x":"② 다음 각호의 사항은 재적 회원 7분의 1 이상의 출석 및 출석 회원 3분의 2 이상에 해당하는 결의로 의결한다."},{"k":"ho","x":"1. 제35조의 학부 학생회장단 탄핵안에 관한 사항"},{"k":"ho","x":"2. 제38조의 징계에 관한 사항"},{"k":"ho","x":"3. 제39조 제３항의 학부 학생회비 인상ㆍ인하에 관한 사항"},{"k":"ho","x":"4. 제40조 제１항의 회칙 개정에 관한 사항"}],"num":30,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a31","label":"제31조","title":"안건","paras":[{"k":"hang","x":"① 학생총회의 안건은 다음 각호의 방법으로 상정할 수 있다."},{"k":"ho","x":"1. 학부운영위원회의 출석 과반수에 해당하는 결의"},{"k":"ho","x":"2. 학생대표자회의 출석 과반수에 해당하는 결의"},{"k":"ho","x":"3. 회원 50명 이상의 연서에 따른 임시회의 소집요구와 함께 발의"},{"k":"ho","x":"4. 제90조에 따라 발의된 학부 학생회장단 사퇴 허가 요청"},{"k":"ho","x":"5. 제91조에 따른 학부 학생회장단 탄핵 발의"},{"k":"ho","x":"6. 제175조에 따른 회칙 개정안 발의"},{"k":"hang","x":"② 학생총회는 다음 각호의 안건을 심의ㆍ의결한다."},{"k":"ho","x":"1. 학부운영위원회가 소집요구와 함께 상정한 안건"},{"k":"ho","x":"2. 회원 50명 이상의 연서에 따른 소집요구와 함께 발의된 안건"},{"k":"ho","x":"3. 제90조에 따라 발의된 학부 학생회장단 사퇴 허가 안건"},{"k":"ho","x":"4. 제91조에 따른 학부 학생회장단 탄핵 안건"},{"k":"ho","x":"5. 제36조 제2항에 따른 집행위원 해임 안건"},{"k":"ho","x":"6. 제175조에 따라 발의된 회칙 개정안건"},{"k":"ho","x":"7. 본회의 활동에 필요한 각종 세칙 제정ㆍ개정안건"},{"k":"ho","x":"8. 회비의 인상ㆍ인하에 관한 안건"},{"k":"ho","x":"9. 본회의 사업계획과 정책의 기본방향에 대한 논의 안건"},{"k":"ho","x":"10. 본회의 예산·결산의 심의 및 승인에 관한 안건"},{"k":"ho","x":"11. 본회의 회계 및 사업 전반에 대한 감사에 관한 안건"},{"k":"ho","x":"12. 학생활동 및 학생신분에 관한 학칙 개정 요구안에 관한 안건"},{"k":"ho","x":"13. 제36조 제1항에 따른 집행위원장 및 집행위원 인준에 관한 안건"},{"k":"ho","x":"14. 회원 전체 명의로 소송을 진행할 경우 해당 소송에 관한 안건"},{"k":"ho","x":"15. 자유전공학부의 자치공간과 기타물품 회수 및 분배에 관한 안건"},{"k":"ho","x":"16. 학생총투표 실시 및 안건 상정에 관한 안건"},{"k":"ho","x":"17. 회원 징계에 관한 안건"},{"k":"ho","x":"18. 의결기구 산하의 특별위원회 설립에 관한 안건"},{"k":"ho","x":"29. 제107조 제1항, 제2항에 따른 자치단체 인준에 관한 안건"},{"k":"hang","x":"③ 학생총회는 본회를 폐지하는 결의를 할 수 없다."}],"num":31,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a32","label":"제32조","title":"안건 위임","paras":[{"k":"hang","x":"① 학생총회는 회기 중 처리하지 못한 안건은 출석 인원의 3분의 2 이상의 찬성으로 학생대표자회의에 위임할 수 있다. 단, 학생총회가 개의되지 않아 처리하지 못한 안건은 자동으로 학생대표자회에 위임된다."},{"k":"hang","x":"② 제31조 제2항 제4호, 제35조에서 규정하고 있는 학부 학생회장단 탄핵 안건은 하위기구로 위임할 수 없으며, 학생총회에 의하지 않고서는 오직 학생총투표로서만 처리할 수 있다."}],"num":32,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a33","label":"제33조","title":"결정ㆍ집행 사항 변경에 관한 사항","paras":[{"k":"line","x":"학생총회는 산하 학부ㆍ반 운영위원회, 학부ㆍ반 학생회장단과 학부ㆍ반 집행위원회의 결정ㆍ집행 사항을 변경 또는 취소할 수 있다."}],"num":33,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a34","label":"제34조","title":"학부 학생회장단 사퇴 허가에 관한 사항","paras":[{"k":"line","x":"학생총회는 학부 학생회장 또는 학부 부학생회장이 제90조에 따라 사퇴의 허가를 요청할 때 학생총회는 허가 여부를 심의ㆍ의결한다."}],"num":34,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a35","label":"제35조","title":"학부 학생회장단 탄핵에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 학부 학생회장단에 대한 탄핵안이 상정될 경우 학부 학생회장단에 대한 탄핵을 결정할 수 있다."},{"k":"hang","x":"② 학생총회는 학생회장단 탄핵과 관련된 절차가 준수되었는지, 탄핵 이유가 사실에 기반하고 있는지 성실히 심사할 의무를 지닌다."},{"k":"hang","x":"③ 학생총회는 출석 3분의 2 이상에 해당하는 결의로 학부 학생회장단 탄핵 결정 대신 동일 안건을 학생총투표 안건으로 상정할 수 있다."},{"k":"hang","x":"④ 학부 학생회장단 탄핵안 발의에 관한 절차는 제91조를 따른다."}],"num":35,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a36","label":"제36조","title":"집행위원회에 관한 사항","paras":[{"k":"hang","x":"① 집행위원회는 다음 각호의 사항에 관하여 학부운영위원회의 사전 인준을 거친 후 학생총회에 보고하여 인준받아야 한다. 단, 제２호와 제３호의 사항에 관하여 학부운영위원회의 사전 인준이 있으면 해당 안건을 학생총회에서 심의하기 전까지 해당 결정은 효력을 지닌다."},{"k":"ho","x":"1. 사업계획과 정책의 기본방향"},{"k":"ho","x":"2. 집행위원장과 집행위원의 임명"},{"k":"ho","x":"3. 산하 국서의 신설ㆍ폐지와 변경"},{"k":"hang","x":"② 학생총회는 집행위원에 대한 해임을 의결할 수 있다."}],"num":36,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a37","label":"제37조","title":"감사에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 본회 집행기구, 산하기구, 독립기구의 사업 전반에 대하여 감사를 시행할 수 있다."},{"k":"hang","x":"② 학생총회는 감사에 필요하다고 인정될 때 해당 기구의 대표자 혹은 사업담당자를 출석시켜 진술을 청취할 수 있다. 또한 관련 자료의 제출을 요구할 수 있다."},{"k":"hang","x":"③ 학생총회는 특정 집행기구, 산하기구의 감사를 목적으로 하는 감사위원회를 학생총회 산하에 설치할 수 있다. 감사위원회는 학생총회의 결정에 따라 감사 활동을 진행한 후 그 결과를 우선적으로 학부운영위원회에 보고한 후, 학생총회에 최종 보고하여야 한다."}],"num":37,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a38","label":"제38조","title":"징계에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 회원, 집행위원, 학부운영위원회 위원, 학생대표자회 대의원, 독립기구 및 산하기구가 본 회칙ㆍ세칙ㆍ규칙을 위반할 때 징계할 수 있다."},{"k":"hang","x":"② 회원에 대한 징계는 다음 각호 중 하나로 하며, 제２호 및 제3호는 그 기간을 정할 수 있다."},{"k":"ho","x":"1. 공개 경고와 사과문 게재 요구"},{"k":"ho","x":"2. 선거권ㆍ피선거권의 박탈"},{"k":"ho","x":"3. 제명"},{"k":"hang","x":"③ 집행위원에 대한 징계는 다음 각호 중 하나로 하며, 제2호, 제3호, 제4호 및 제5호는 그 기간을 정할 수 있다."},{"k":"ho","x":"1. 학생총회 또는 학생대표자회 공개회의에서의 경고와 사과 요구"},{"k":"ho","x":"2. 특정 사안에 대한 직무 정지"},{"k":"ho","x":"3. 집행위원회 출석 정지"},{"k":"ho","x":"4. 위원 자격 정지"},{"k":"ho","x":"5. 위원 제명"},{"k":"hang","x":"④ 학생대표자회 대의원 및 학부운영위원회 위원에 대한 징계는 다음 각호 중 하나로 하며, 제２호, 제３호, 제4호 및 제5호는 그 기간을 정할 수 있다."},{"k":"ho","x":"1. 학생총회 또는 학생대표자회 공개회의에서의 경고와 사과 요구"},{"k":"ho","x":"2. 특정 사안에 대한 직무 정지"},{"k":"ho","x":"3. 학생대표자회 및 운영위원회 출석 정지"},{"k":"ho","x":"4. 위원 자격 정지"},{"k":"ho","x":"5. 위원 제명"},{"k":"hang","x":"⑤ 산하기구 및 독립기구에 대한 징계는 다음 각호 중 하나로 하며, 제2호, 제３호 및 제5호는 그 기간을 정할 수 있다."},{"k":"ho","x":"1. 공개 경고와 사과문 게재 요구"},{"k":"ho","x":"2. 예산의 삭감 또는 지급 유보"},{"k":"ho","x":"3. 특정 사안에 대한 활동 금지"},{"k":"ho","x":"4. 기구장에 대한 사퇴 권고"},{"k":"ho","x":"5. 산하기구 및 독립기구 자격 박탈"},{"k":"hang","x":"⑥ 현직 학부 학생회장단인 자에게는 제２항 제2호부터 제3호와 제3항 제3호부터 제4호, 제4항 제3호부터 제5호까지의 징계를 할 수 없다."},{"k":"hang","x":"⑦ 학생총회가 징계를 의결하기 위해서는 의결 전에 징계의 대상이 되는 자 혹은 기구에 충분한 소명의 기회를 주어야 하며, 징계절차는 총학생회의 절차에 따라 진행되어야 한다."},{"k":"hang","x":"⑧ 중대한 인권침해 사건 또는 총학생회 차원의 징계 절차가 개시된 사안의 경우, 재적 과반수에 해당하는 결의로 총학생회에 징계를 위임할 수 있다."},{"k":"hang","x":"⑨ 학생총회가 징계를 의결하면 집행위원회는 징계의 대상, 사유, 종류, 기간을 공고한다."},{"k":"hang","x":"⑩ 본회는 정기 학생총회의 개의 7일 전까지 7일 이상의 인권침해사건 신고 기간을 두고, 본회 회원을 대상으로 한 인권침해 사건이 있었는지 조사하여야 한다."}],"num":38,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a39","label":"제39조","title":"재정에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 학부운영위원회의 심의를 거친 학부ㆍ반 학생회비 결산보고서ㆍ예산안을 심의하여 승인한다."},{"k":"hang","x":"② 학생총회는 제1항 심의에서 불승인된 기구에는 제163조에 따라 해당 학기의 학부 학생회비를 지급하지 않거나 지급을 보류하도록 결정할 수 있다. 그 밖에 자세한 사항은 ｢총학생회 재정운용세칙｣을 따른다."},{"k":"hang","x":"③ 학생총회는 학부학생회비의 인상ㆍ인하를 결정할 수 있다."}],"num":39,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a40","label":"제40조","title":"회칙ㆍ세칙ㆍ규칙에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 회칙을 개정할 수 있다."},{"k":"hang","x":"② 학생총회는 세칙을 제정ㆍ개정ㆍ폐지할 수 있다."},{"k":"hang","x":"③ 학생총회는 규칙ㆍ자치규칙이 회칙ㆍ세칙에 부합하는지 여부에 대해 심사할 수 있으며, 출석 과반수에 해당하는 결의로 부합하지 않다고 의결할시, 해당 기구에 개정을 권고할 수 있다. 회칙ㆍ세칙에 반하는 규칙ㆍ자치규칙은 의결 즉시 효력이 부인된다. 효력 부인의 소급효에 관해 논란이 있을시, 회칙해석위원회의 결정에 따른다."}],"num":40,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a41","label":"제41조","title":"대외활동에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 본회 차원의 상설적 연대 단체 가입ㆍ탈퇴에 대한 동의권을 가진다."},{"k":"hang","x":"② 회원 전체의 명의로 소송을 진행할 필요가 있는 문제가 발생할 때 학생총회는 학부운영위원회에 소송권을 위임할 수 있다."}],"num":41,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a42","label":"제42조","title":"재소집","paras":[{"k":"line","x":"학생총회의 개의가 불가하거나 논의를 마치지 못하고 산회한 경우 의장의 재량에 따라 10일 이내에 재소집할 수 있다."}],"num":42,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제３절 학생총투표"},{"t":"art","id":"a43","label":"제43조","title":"지위","paras":[{"k":"line","x":"학생총투표를 통한 의결은 학생총회의 의결과 같은 효력이 있다."}],"num":43,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a44","label":"제44조","title":"투표권","paras":[{"k":"line","x":"정회원은 학생총투표의 투표권이 있다."}],"num":44,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a45","label":"제45조","title":"투표관리위원회","paras":[{"k":"hang","x":"① 투표관리위원회는 학부운영위원 및 제63조 제5항에 의해 의결권을 가질 수 있는 자 전원으로 구성한다. 단, 학부 학생회장단은 제91조에 따른 학부 학생회장단 탄핵안에 대한 학생총투표에 대해서는 투표관리위원이 될 수 없다."},{"k":"hang","x":"② 투표관리위원회는 학생총투표와 관련된 모든 업무를 총괄한다."},{"k":"hang","x":"③ 집행위원장 및 집행위원회는 투표관리위원회의 결정에 따라 학생총투표 시행준비를 성실히 보조한다."},{"k":"hang","x":"④ 그 밖에 투표관리위원회에 관한 사항은 투표관리위원회의 출석 과반수에 해당하는 결의로 ｢총학생회 선거시행세칙｣의 선거관리위원회에 관한 규정을 준용할 수 있다."}],"num":45,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a46","label":"제46조","title":"성립ㆍ의결요건","paras":[{"k":"hang","x":"① 학생총투표의 개시는 학생총회 또는 학생대표자회의 출석 과반수에 해당하는 결의로만 가능하다."},{"k":"hang","x":"② 학생총투표는 정회원 4분의 1 이상의 투표로 성립하고, 유효투표의 과반수 찬성으로 의결한다."},{"k":"hang","x":"③ 성립 여부를 판단하기 위한 투표율의 계산은 명부상 총 투표자 수를 기준으로 한다."}],"num":46,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a47","label":"제47조","title":"시행","paras":[{"k":"line","x":"학생총투표는 학생총회 혹은 학생대표자회의 시행 결정에 따라 투표관리위원장이 실행한다."}],"num":47,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a48","label":"제48조","title":"시행 공고","paras":[{"k":"hang","x":"① 학생총회 의장은 학생총투표의 시행을 시행 7일 전에 공고하여야 한다."},{"k":"hang","x":"② 공고문에는 다음 각호의 사항을 명시하여야 한다."},{"k":"ho","x":"1. 학생총투표 시행 일시"},{"k":"ho","x":"2. 학생총투표 투표소 설치 장소"},{"k":"ho","x":"3. 안건과 안건에 대한 설명"}],"num":48,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a49","label":"제49조","title":"투표 기간","paras":[{"k":"hang","x":"① 투표 기간은 3일의 범위에서 투표관리위원회가 정한다."},{"k":"hang","x":"② 투표 기간이 종료하였음에도 투표율이 25%를 넘지 않았으면 투표관리위원회의 결정에 따라 투표 기간을 2일의 범위에서 1회 연장할 수 있다."}],"num":49,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a50","label":"제50조","title":"투표 방법","paras":[{"k":"hang","x":"① 투표는 기표방법으로 함을 원칙으로 한다."},{"k":"hang","x":"② 회원들의 쉬운 투표 참여 혹은 부재중인 자의 투표 참여를 위하여 우편, 온라인, 모바일 그 밖에 특수한 투표방법을 병행할 수 있다. 특수한 투표방법에 대한 결정은 투표관리위원회의 출석 3분의 2 이상에 해당하는 결의로 한다."},{"k":"hang","x":"③ 특수한 투표방법의 시행 여부, 대상, 방식, 운영 등에 관하여서는 ｢자유전공학부 선거시행세칙｣의 특수한 투표방법에 대한 규정을 준용한다."}],"num":50,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a51","label":"제51조","title":"결과 공고","paras":[{"k":"line","x":"학생총투표가 종료되어 개표가 완료되면 개표종료 시부터 24시간 이내에 투표관리위원회가 투표율과 결과를 공고한다. 이때 최종 투표율은 총투표용지 수를 기준으로 계산한다."}],"num":51,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a52","label":"제52조","title":"무효처리","paras":[{"k":"hang","x":"① 한 투표소의 명부상 투표자 수와 투표함의 투표용지 수의 차이가 명부상 투표자 수 대비 5%를 넘으면 해당 투표함의 결과는 무효가 되며, 해당 투표함의 투표용지 수만큼 무효표로 처리한다."},{"k":"hang","x":"② 명부상 총 투표자 수와 총투표용지 수의 차이가 명부상 총 투표자 수 대비 5%를 넘으면 해당 학생총투표는 무효가 된다."}],"num":52,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a53","label":"제53조","title":"준용","paras":[{"k":"line","x":"그 밖에 학생총투표 관련 세부 사항은 투표관리위원회의 출석 3분의 2 이상에 해당하는 결의로 ｢선거시행세칙｣의 투표ㆍ개표 관련 규정을 준용한다."}],"num":53,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제4절 학생대표자회"},{"t":"art","id":"a54","label":"제54조","title":"지위","paras":[{"k":"line","x":"학생대표자회는 학생총회 다음의 위계에 있는 의결기구이다."}],"num":54,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a55","label":"제55조","title":"구성","paras":[{"k":"hang","x":"① 학생대표자회는 각호에 있는 본회 및 본회 산하기구의 대표자를 대의원으로 한다."},{"k":"ho","x":"1. 학부 학생회장 및 부학생회장"},{"k":"ho","x":"2. 각 반 학생회 반 운영위원 중 학생회장, 부학생회장, 신입생 대표, 고학번 대표 4인"},{"k":"ho","x":"3. 각 자치단체장"},{"k":"hang","x":"② 비상대책위원회 체제의 산하기구의 장은 궐위로 본다."},{"k":"hang","x":"③ 궐위 대의원은 재적 대의원에서 제외한다."},{"k":"hang","x":"④ 학생대표자회는 필요할 경우, 출석 3분의 2 이상에 해당하는 결의로 대의원이 아닌 자에게 해당 회기에 한해 임시적으로 대의원 자격을 부여할 수 있다."}],"num":55,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a56","label":"제56조","title":"학생대표자회 대의원의 의무","paras":[{"k":"hang","x":"① 학생대표자회 대의원은 학생대표자회의 품위를 유지하여야 한다."},{"k":"hang","x":"② 학생대표자회 대의원은 회칙을 준수하여야 한다."},{"k":"hang","x":"③ 학생대표자회 대의원은 자신이 소속된 기구의 의사를 충분히 수렴하여 의결 과정 전반에서 소속된 기구를 대표하는 의사를 표명해야 한다."},{"k":"hang","x":"④ 학생대표자회 대의원은 본회를 대표하여 활동하는 자로서 양심에 따라 직무를 행하고 회의에 성실히 참여하여야 한다."}],"num":56,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a57","label":"제57조","title":"개의ㆍ의결요건","paras":[{"k":"hang","x":"① 학생대표자회는 재적 대의원 과반수 출석으로 개의하고, 출석 대의원 과반수에 해당하는 결의로 의결한다."},{"k":"hang","x":"② 다음 각호의 사항은 출석 3분의 2 이상에 해당하는 결의로 의결한다."},{"k":"ho","x":"1. 제60조의 학부 학생회장단 탄핵안 학생총투표 발의에 관한 사항"},{"k":"ho","x":"2. 제36조의 집행위원 해임에 관한 사항"},{"k":"ho","x":"3. 제38조의 징계에 관한 사항"},{"k":"ho","x":"4. 제39조 제３항의 학부 학생회비 인상ㆍ인하에 관한 사항"},{"k":"ho","x":"5. 제40조 제１항의 회칙 개정에 관한 사항"}],"num":57,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a58","label":"제58조","title":"안건","paras":[{"k":"hang","x":"① 학생대표자회의 안건은 다음 각호의 방법으로 상정할 수 있다."},{"k":"ho","x":"1. 학부운영위원회의 출석 과반수에 해당하는 결의"},{"k":"ho","x":"2. 회원 50명 이상의 연서에 따른 임시회의 소집요구와 함께 발의"},{"k":"ho","x":"3. 제90조에 따라 발의된 학부 학생회장단 사퇴 허가 요청"},{"k":"ho","x":"4. 제91조에 따른 학부 학생회장단 탄핵 발의"},{"k":"ho","x":"5. 제175조에 따른 회칙 개정안 발의"},{"k":"hang","x":"② 학생대표자회는 다음 각호의 안건을 심의ㆍ의결한다."},{"k":"ho","x":"1. 제31조 제2항 제4호, 제35조의 학부 학생회장 탄핵안건을 제외한 안건 중 학생총회에서 다룰 수 있는 안건 및 학생총회의 위임을 받은 안건"},{"k":"ho","x":"2. 학부 학생회장단 탄핵안 학생총투표 발의 안건"},{"k":"ho","x":"3. 임시 학생총회 소집 및 안건상정에 관한 안건"},{"k":"ho","x":"4. 학생총투표 실시 및 안건 상정에 관한 안건"}],"num":58,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a59","label":"제59조","title":"안건 위임","paras":[{"k":"line","x":"회기 중 처리하지 못한 안건은 출석 인원의 3분의 2 이상의 찬성으로 학부운영위원회의에 위임할 수 있다. 단, 제58조 제2항 및 제60조의 탄핵안 학생총투표 발의에 관한 안건, 제175조 회칙 개정안건, 세칙 제정ㆍ개정안건, 그 밖의 본회의 목적과 관련된 본질적으로 중대한 결정사항은 위임할 수 없다."}],"num":59,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a60","label":"제60조","title":"탄핵안 학생총투표 발의","paras":[{"k":"hang","x":"① 학생대표자회는 학부 학생회장단 탄핵안을 학생총투표에 붙일 수 있다."},{"k":"hang","x":"② 학부 학생회장단 탄핵안 학생총투표 발의에 관한 절차는 제60조를 따른다."}],"num":60,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a61","label":"제61조","title":"준용","paras":[{"k":"hang","x":"① 소집요건에 관한 사항은 제27조를 준용한다. 단, 제27조 제1항 제2호는 적용하지 아니한다."},{"k":"hang","x":"② 소집공고에 관한 사항은 제28조를 준용한다."},{"k":"hang","x":"③ 자료의 사전 배포에 관한 사항은 제29조를 준용한다."},{"k":"hang","x":"④ 산하기구의 결정ㆍ집행사항 변경에 관한 사항은 제33조를 준용한다."},{"k":"hang","x":"⑤ 학부 학생회장단 사퇴 허가에 관한 사항 사항은 제34조를 준용한다."},{"k":"hang","x":"⑥ 집행위원회에 관한 사항은 제36조를 준용한다."},{"k":"hang","x":"⑦ 감사에 관한 사항은 제37조를 준용한다."},{"k":"hang","x":"⑧ 징계에 관한 사항은 제38조를 준용한다."},{"k":"hang","x":"⑨ 재정에 관한 사항은 제39조를 준용한다."},{"k":"hang","x":"⑩ 회칙ㆍ세칙ㆍ규칙에 관한 사항은 제40조를 준용한다."},{"k":"hang","x":"⑪ 대외활동에 관한 사항은 제41조를 준용한다."},{"k":"hang","x":"⑫ 재소집에 관한 사항은 제42조를 준용한다."}],"num":61,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제5절 학부운영위원회"},{"t":"art","id":"a62","label":"제62조","title":"지위","paras":[{"k":"line","x":"학부운영위원회는 본회의 신속하고 민주적인 결정을 위하여 학생총회가 일정 권한을 위임한 상설적인 의결기구이다."}],"num":62,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a63","label":"제63조","title":"구성","paras":[{"k":"hang","x":"① 다음 각호 중 하나에 해당되는 자는 학부 운영위원이 된다."},{"k":"ho","x":"1. 학부 학생회장과 부학생회장"},{"k":"ho","x":"2. 반 학생회장"},{"k":"hang","x":"② 비상대책위원회 체제의 산하기구의 장은 궐위로 본다."},{"k":"hang","x":"③ 궐위 대의원은 재적 대의원에서 제외한다."},{"k":"hang","x":"④ 학부운영위원회는 필요할 경우, 학부운영위원회 출석 3분의 2 이상에 해당하는 결의로 해당 회기에 한해 한시적으로 위원 자격을 부여할 수 있다."},{"k":"hang","x":"⑤ 제1항 제2호, 제1항 제3호의 학부운영위원이 학부운영위원회에 정당한 사유로 출석하지 못할 때는 개의 직후에 인준을 받아 부회장이 대신 의결권을 가질 수 있다."}],"num":63,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a64","label":"제64조","title":"학부운영위원의 의무","paras":[{"k":"line","x":"학부운영위원의 의무에 관해서는 제57조를 준용한다."}],"num":64,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a65","label":"제65조","title":"정기회의","paras":[{"k":"hang","x":"① 학부운영위원회 정기회의는 매주 1회 개의함을 원칙으로 한다. 단, 학부운영위원회의 출석 과반수에 해당하는 결의로 정기회의의 일정을 조정 할 수 있다."},{"k":"hang","x":"② 의장은 학부운영위원회 정기회의의 개의 요일과 시각을 학부운영위원들과 협의하여 결정한 후 이를 공고하여야 한다."},{"k":"hang","x":"③ 의장은 매월 말 다음 달의 학부운영위원회 정기회의 일정을 학부운영위원들과 협의하여 결정하여야 한다."}],"num":65,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a66","label":"제66조","title":"임시회의","paras":[{"k":"hang","x":"① 학부운영위원회 임시회의는 다음 각호 중 하나에 의해 의장이 소집한다."},{"k":"ho","x":"1. 의장의 소집요구"},{"k":"ho","x":"2. 학부운영위원회 재적 위원 3분의 1 이상의 연서에 따른 소집요구"},{"k":"ho","x":"3. 정회원 20명 이상의 연서에 따른 소집요구"},{"k":"hang","x":"② 연서에 따른 소집요구는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식을 준용하며 서식에는 ｢고려대학 교 총학생회 사무처리세칙｣에서 정한 사항이 포함되어야 한다."},{"k":"hang","x":"③ 연서에 따른 소집요구가 있으면 학부운영위원회 의장은 지체 없이 학부운영위원회 개의일을 결정한다. 이때 개의일은 소집요구 서식에 기재된 개의 희망일로 함을 원칙으로 하되 변경할 때는 학부운영위원의 출석 3분의 2 이상에 해당하는 결의로 한다. 단, 이 경우에도 개의 희망일과 3일 이상 차이가 나서는 안 된다."}],"num":66,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a67","label":"제67조","title":"소집 공고","paras":[{"k":"hang","x":"① 의장은 학부운영위원회의 소집을 개의일 2일 전에 공고하여야 한다."},{"k":"hang","x":"② 공고문에는 다음 각호의 사항을 명시하여야 한다."},{"k":"ho","x":"1. 회의 시작 일시"},{"k":"ho","x":"2. 회의 장소"},{"k":"ho","x":"3. 안건과 안건에 대한 설명"}],"num":67,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a68","label":"제68조","title":"안건지의 사전 배포","paras":[{"k":"line","x":"학부운영위원회 의장은 학부운영위원회 정기회의 개의 1일 전까지 제출된 안건과 그에 관한 설명, 집행위원회 등의 보고ㆍ인준 사항, 등이 포함된 안건지를 학부운영위원을 대상으로 배포하여야 한다. 배포는 유인물 형태로 제작하여 비치하는 방법과 전산화된 형태의 문서로 제작하여 온라인에 게시하는 방법으로 한다."}],"num":68,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a69","label":"제69조","title":"개의ㆍ의결요건","paras":[{"k":"line","x":"학부운영위원회는 재적 위원 과반수 출석으로 개의하고, 출석 위원 과반수 찬성으로 의결한다."}],"num":69,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a70","label":"제70조","title":"안건","paras":[{"k":"hang","x":"① 학부운영위원회의 안건은 다음 각호의 방법으로 상정할 수 있다."},{"k":"ho","x":"1. 학부운영위원이 발의한 안건"},{"k":"ho","x":"2. 학부운영위원회 재적 위원 3분의 1 이상의 연서에 따른 소집요구와 함께 발의한 안건"},{"k":"ho","x":"3. 회원 20명 이상의 연서에 따른 소집요구 연서에 따른 소집요구와 함께 발의한 안건"},{"k":"hang","x":"② 학부운영위원회는 다음 각호의 안건을 심의ㆍ의결한다."},{"k":"ho","x":"1. 제60조 탄핵안 학생총투표 발의에 관한 안건, 제175조 회칙 개정안건, 세칙 제정ㆍ개정안건 등 본회의 목적과 관련된 본질적으로 중대한 결정사항을 제외한 안건 중 학생대표자회에서 위임을 받은 안건"},{"k":"ho","x":"2. 임시학생총회 소집 및 안건 상정에 관한 건"},{"k":"ho","x":"3. 임시학생대표자회 소집 및 안건 상정에 관한 건"},{"k":"ho","x":"4. 학생회 제반 사업에 대한 논의 안건"},{"k":"ho","x":"5. 예산 및 결산에 대한 사전 심의·검토 안건"},{"k":"ho","x":"6. 각 반 학생회 사업 보고 및 공유에 관한 안건"},{"k":"ho","x":"7. 반 학생회장단 선거관리위원회 구성에 관한 안건"},{"k":"ho","x":"8. 특별위원회 설립에 관한 안건"},{"k":"ho","x":"9. 공간배정위원회 소집 및 안건 상정에 관한 건"},{"k":"ho","x":"10. 산하기구 감사에 관한 건"},{"k":"ho","x":"11. 학생대표자회 대표자 명단 확정 및 대표자 지위 심의에 관한 건"},{"k":"ho","x":"12. 기타 학생총회 및 학생대표자회의 의결을 요하지 않는 결정사항에 대한 안건"}],"num":70,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a71","label":"제71조","title":"학부운영위원회 내 위원회","paras":[{"k":"hang","x":"① 학부운영위원회는 안건을 효율적으로 처리하기 위하여 학부운영위원회의 출석 과반수에 해당하는 결의로 학부운영위원회 내에 위원회를 설치할 수 있다."},{"k":"hang","x":"② 학부운영위원회는 다음 각호의 사항을 제외하고는 그 권한을 위원회에 위임할 수 있다."},{"k":"ho","x":"1. 학생총회 또는 학생대표자회의 결정 및 승인을 요하는 사항"},{"k":"ho","x":"2. 위원회의 설치와 그 위원의 선임 및 해임"},{"k":"ho","x":"3. 그 밖에 기타 학부운영위원회의 본질적인 업무"},{"k":"hang","x":"③ 위원회는 2인 이상의 학부운영위원으로 구성한다."},{"k":"hang","x":"④ 위원회는 학부운영위원회로부터 위임받은 사항에 대해서만 의결할 수 있다."},{"k":"hang","x":"⑤ 위원회는 결의된 사항을 각 학부운영위원에게 통지하여야 한다. 이 경우 이를 통지받은 학부운영위원은 임시학부운영위원회의 소집을 요구할 수 있으며, 학부운영위원회는 위원회가 결의한 사항에 대하여 다시 결의할 수 있다."}],"num":71,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a72","label":"제72조","title":"의결기구에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 학생총회의 소집을 요구할 수 있으며 학생총회에 안건을 발의할 수 있다."},{"k":"hang","x":"② 학부운영위원회는 학생대표자회의 소집을 요구할 수 있으며 학생대표자회에 안건을 발의할 수 있다."},{"k":"hang","x":"③ 학부운영위원회는 학생총회 및 학생대표자회의 개의에 관한 세부 문제를 논의하고 결정한다."},{"k":"hang","x":"④ 학부운영위원회는 학생총회에 대하여 연서에 따른 소집요구가 있으면 학생총회의 개의일을 결정한다."},{"k":"hang","x":"⑤ 학부운영위원회는 학생대표자회 개의 전 산하기구의 대표자가 민주적 선거에 의해 당선되었는지, 실질적으로 기구를 대표하고 있는지 등 대표자 지위에 대한 심사를 진행하여야 하며, 이를 기준으로 대의원 명단을 확정 지어야 한다."}],"num":72,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a73","label":"제73조","title":"집행기구에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 제95조 제2항, 제96조 제2항에 따라 집행위원장과 집행위원회 각국서의 국장과 국원을 임명한다."},{"k":"hang","x":"② 학부운영위원회는 학생총회 및 학생대표자회 보고 사항을 사전 심의한다."},{"k":"hang","x":"③ 학부운영위원회는 학부 학생회장단과 집행위원회의 사업 계획과 진행 상황, 결과에 대한 보고를 받고 이를 심의하고 조정한다. 단, 학부 학생회장단과 집행위원회의 효율적인 집행을 보장하기 위하여 학부 학생회장단이 사전 집행이 불가피하다고 판단하여 집행한 사업에 대하여는 사후에 보고하고 심의 절차를 이행할 수 있다. 집행위원회는 불승인된 사업에 대해서는 의결 즉시 원상회복을 위해 노력해야 한다."},{"k":"hang","x":"④ 학부운영위원회는 학부 학생회장단과 집행위원회의 결정과 집행 사항을 변경 또는 취소할 수 있다."},{"k":"hang","x":"⑤ 학부운영위원회는 학부 학생회장단에 대한 탄핵안이 발의되면 탄핵안이 제91조 제1항, 제2항, 제3항에서 규정하고 있는 발의 요건을 충족하고 있는지 지체 없이 심의해야 하며 제91조 제4항에 따라 학생총회 또는 학생대표자회를 소집해야 한다."}],"num":73,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a74","label":"제74조","title":"감사에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 본회 집행기구, 산하기구의 사업 전반에 대하여 감사를 시행할 수 있다."},{"k":"hang","x":"② 학부운영위원회는 감사에 필요하다고 인정될 때 해당 기구의 대표자 혹은 사업담당자를 출석시켜 진술을 청취할 수 있다. 또한 관련 자료의 제출을 요구할 수 있다."}],"num":74,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a75","label":"제75조","title":"선거에 관한 사항","paras":[{"k":"line","x":"학부운영위원회는 반 학생회장단 동시선거 일정을 결정하고 반 학생회 동시 선거관리위원회를 구성할 수 있다. 그 밖에 자세한 사항은 ｢자유전공학부 선거시행세칙｣을 따른다."}],"num":75,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a76","label":"제76조","title":"재정에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 제161조에 따라 학생회비를 사용하는 학부ㆍ반 집행위원회 등의 예산안과 결산을 사전 심의한 후 학생총회 및 학생대표자회에 상정한다."},{"k":"hang","x":"② 학부운영위원회는 제163조 제8항에 따라 집행기구 자산의 취득, 보관, 사용, 처분 행위를 취소할 수 있다."}],"num":76,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a77","label":"제77조","title":"회칙ㆍ세칙ㆍ규칙에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 제175조에 따라 회칙 개정안과 세칙 제정안ㆍ개정안ㆍ폐지안을 발의할 수 있다. 학부운영위원회는 회칙 개정안을 발의하면 제177조 제１항에 따라 학부운영위원회에서 회칙 개정안에 대해 사전 심의한다."},{"k":"hang","x":"② 세칙에 관련 규정이 있으면 학부운영위원회는 해당 세칙에 부수되는 규칙을 제정ㆍ개정ㆍ폐지할 수 있다. 이에 관하여서는 해당 세칙을 따른다."},{"k":"hang","x":"③ 학부운영위원회는 일반규칙을 제정ㆍ개정ㆍ폐지할 수 있다."}],"num":77,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a78","label":"제78조","title":"대외활동에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 본회의 대외적 활동에 대하여 동의 및 승인권을 갖는다."},{"k":"hang","x":"② 학부운영위원회는 직전 두 분기의 학부 학생회비 5%를 초과하는 재정적 지출을 수반하거나, 본회의 회원에게 중대한 영향을 미치는 학부 학생회장단 또는 집행위원회 차원의 대외활동에 대하여 동의권을 갖는다. 단, 학부 학생회장단과 집행위원회의 효율적인 대외활동을 보장하기 위하여 학부 학생회장단이 사전 집행이 불가피하다고 판단하여 집행한 사업에 대하여는 사후에 보고하고 승인 절차를 이행할 수 있다. 집행위원회는 부동의된 대외활동에 대해서는 의결 즉시 원상회복을 위해 노력해야 한다."}],"num":78,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제6절 비상대책위원회"},{"t":"art","id":"a79","label":"제79조","title":"비상대책위원회","paras":[{"k":"hang","x":"① 비상대책위원회는 다음 각호에 해당할 때 해당 사항의 공고 시로부터 48시간 후 구성된다. 단, 임기 종료일이 확정되지 않았을 때 잔여 임기의 계산을 위한 임기 종료일은 11월 30일로 한다."},{"k":"ho","x":"1. 학부 학생회장단 선거가 무산될 때"},{"k":"ho","x":"2. 학부 학생회장단 두 명 모두가 사퇴하거나 탄핵되고, 해당 학부 학생회장단의 잔여 임기가 180일이 넘지 않을 때"},{"k":"hang","x":"② 제１항에 따라 비상대책위원회가 구성되면 다음 각호에 해당하는 자는 비상대책위원이 된다."},{"k":"ho","x":"1. 각 반 학생회장 및 부학생회장"},{"k":"ho","x":"2. 자치단체연합회장 및 부회장"},{"k":"ho","x":"3. 학생대표자회 대의원 중 학생대표자회의 승인을 받은 자"}],"num":79,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a80","label":"제80조","title":"권한ㆍ업무","paras":[{"k":"hang","x":"① 비상대책위원회는 의결기구에 준하는 권한을 갖는다."},{"k":"hang","x":"② 비상대책위원회는 학부 학생회장단의 궐위 기간 동안 학부운영위원회의 상시적 업무를 담당한다."}],"num":80,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a81","label":"제81조","title":"비상대책위원장","paras":[{"k":"hang","x":"① 비상대책위원장은 비상대책위원회의 출석 과반수에 해당하는 결의로 선출하며, 선출이 무산될 경우 호선에 의한다. 비상대책위원장은 학생총회 또는 학생대표자회의 인준을 받아야 한다."},{"k":"hang","x":"② 비상대책위원장은 학부 학생회장에 준하는 권한을 갖는다."},{"k":"hang","x":"③ 비상대책위원장의 의무에 관해서는 제56조와 제88조를 준용한다."}],"num":81,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a82","label":"제82조","title":"제한","paras":[{"k":"hang","x":"① 비상대책위원회는 학생회장단 및 집행위원회가 가지는 사전 집행ㆍ사후 학부운영위원회 승인 방식의 재정지출이 허용되지 않는다."},{"k":"hang","x":"② 비상대책위원회는 학생회장단 및 집행위원회가 가지는 사전 집행ㆍ사후 학부운영위원회 승인 방식의 대외활동이 허용되지 않는다."},{"k":"hang","x":"③ 비상대책위원회는 직전 두 분기의 학부 학생회비 30%를 초과하는 재정지출이 허용되지 않는다."}],"num":82,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a83","label":"제83조","title":"흠결의 보충","paras":[{"k":"line","x":"비상대책위원회 관련 회칙의 흠결로 비상대책위원회 및 비상대책위원장의 권한, 의무의 범위를 확정 짓기 어려울시, 학부운영위원회의 출석 과반수에 해당하는 결의로 해당 회기에 한해 한시적으로 흠결을 보충할 수 있다. 단, 권한의 범위는 학부 학생회장과 집행위원회의 권한 내로 제한되며, 의무의 범위는 학부 학생회장단과 집행위원회의 의무 내로 제한된다."}],"num":83,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제３장 집행기구"},{"t":"h","lv":3,"text":"제１절 학부 학생회장단"},{"t":"art","id":"a84","label":"제84조","title":"지위","paras":[{"k":"hang","x":"① 학부 학생회장은 본회를 대표하며, 학생총회, 학생대표자회, 학부운영위원회의 의장이 된다."},{"k":"hang","x":"② 학부 학생회장은 총학생회 중앙운영위원 및 전체학생대표자회 대의원이 된다."},{"k":"hang","x":"③ 부학생회장은 학부 학생회장을 보좌하고 학부 학생회장이 권한을 위임하거나 사고인 때에 학부 학생회장의 직무를 대행한다."}],"num":84,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a85","label":"제85조","title":"의결기구 관련 권한","paras":[{"k":"line","x":"학부 학생회장은 학생총회, 학생대표자회, 학부운영위원회 등 의결기구를 운영한다."}],"num":85,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a86","label":"제86조","title":"집행기구 관련 권한","paras":[{"k":"hang","x":"① 학부 학생회장은 본회 사무의 집행을 총괄한다."},{"k":"hang","x":"② 학부 학생회장은 집행위원회의 구성권을 가진다."},{"k":"hang","x":"③ 학부 학생회장은 집행위원회 산하 국서의 국장과 국원에 대한 임면권을 가진다."},{"k":"hang","x":"④ 학부 학생회장은 집행위원회와 산하 국서를 지휘ㆍ감독한다."},{"k":"hang","x":"⑤ 학부 학생회장은 집행위원회의 결정ㆍ집행 사항을 변경 또는 취소할 수 있다."},{"k":"hang","x":"⑥ 학부 학생회장은 필요하다고 인정한 사안의 효율적 업무 집행을 위하여 직속 자문위원회를 설치할 수 있다. 직속 자문위원회와 그 위원에 관하여서는 본조 제３항, 제4항, 제5항을 준용한다."}],"num":86,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a87","label":"제87조","title":"대외활동 관련 권한","paras":[{"k":"hang","x":"① 학부 학생회장은 학생자치활동에 관계되는 학교 행정의 문제에 대해 회원의 의사를 대변하고 학교 당국에 의사를 개진하며, 관련 단체 및 회의에 참여할 수 있다."},{"k":"hang","x":"② 학부 학생회장은 본회와 본회 회원과 관련된 문제에 관하여 본회를 대표하여 대외적으로 입장을 표명하는 등의 대외활동을 할 수 있다. 단, 본회 차원의 연대 단체 가입과 대외적 협의, 본회의 재정적 지출을 수반하거나, 본회의 회원에게 중대한 영향을 미치는 학부 학생회장단 차원의 대외활동은 제78조에 따라 학부운영위원회의 동의를 받아야 한다."}],"num":87,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a88","label":"제88조","title":"의무","paras":[{"k":"hang","x":"① 학부 학생회장은 회원들의 의사를 반영하여 민주적 절차에 따라 직무를 수행해야 한다."},{"k":"hang","x":"② 학부 학생회장은 본회의 의결기구에 성실하게 본회의 활동 사항을 보고해야 한다."},{"k":"hang","x":"③ 학부 학생회장은 본회의 지속적ㆍ장기적 발전을 위하여 노력해야 한다."},{"k":"hang","x":"④ 학부 학생회장단은 본회와 본회 산하기구의 각종 선거에 대한 부당한 영향력의 행사 등 선거 결과에 직ㆍ간접적인 영향을 미치는 행위를 일체 하여서는 아니 된다."},{"k":"hang","x":"⑤ 학부 학생회장단은 후임 학부 학생회장단의 선출과 후임 학부 학생회장단으로의 인수인계가 원활하게 이루어질 수 있도록 노력해야 한다."},{"k":"hang","x":"⑥ 학부 학생회장은 본회의 대표로 학교 기구의 위원이 될 때 의결권 행사 등에 관하여 학부운영위원회와 협의하여야 한다."}],"num":88,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a89","label":"제89조","title":"임기ㆍ삼선 금지","paras":[{"k":"hang","x":"① 학부 학생회장단의 임기는 당선 공고일로부터 48시간 이후부터 후임 학부 학생회장단 임기 시작 전까지로 한다. 단, 후임 학부 학생회장단 선거가 무산되는 경우 후임 학부 학생회장단 선거 개표 예정일로부터 48시간이 도과하면 임기가 종료되는 것으로 본다."},{"k":"hang","x":"② 학부 학생회장은 후임 학부 학생회장단 선거에서 학부 학생회장 후보로 입후보할 수 있다. 단, 학생회장을 2회 역임한 경우, 차기 선거에서 학부 학생회장 및 부학생회장 후보로 입후보할 수 없다."}],"num":89,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a90","label":"제90조","title":"사퇴","paras":[{"k":"hang","x":"① 학부 학생회장 또는 학부 부학생회장이 사퇴하고자 할 때는 학생총회 또는 학생대표자회의 허가가 있어야 한다. 단, 사망 등으로 인하여 당사자가 허가를 받을 수 없으면 그러하지 아니하다."},{"k":"hang","x":"② 제1항의 사퇴요청이 접수일로부터 20일 이내에 학생총회 또는 학생대표자회의 결정이 없으면 사퇴를 승인한 것으로 본다."},{"k":"hang","x":"③ 학부 학생회장이 사퇴하거나 탄핵되면 학부 부학생회장이 그 직을 승계한다."}],"num":90,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a91","label":"제91조","title":"탄핵","paras":[{"k":"hang","x":"① 회원은 학부 학생회장단이 다음 각호 중 하나에 해당할 시 학부 학생회장단의 탄핵안을 발의할 수 있다. 회장과 부회장 중 한 명만 다음 각호 중 하나에 해당하는 경우, 회장과 부회장 중 한 명을 대상으로 한 탄핵안을 발의할 수 있다. 탄핵안의 경우 반드시 학생총회 또는 학생총투표의 방법 중 하나를 정해 발의해야 한다."},{"k":"ho","x":"1. 회칙의 중대한 위반을 저질렀을 시"},{"k":"ho","x":"2. 상당한 기간 동안 회장단의 업무를 해태하고 있을 시"},{"k":"ho","x":"3. 실정법 위반으로 벌금형 이상의 실형을 선고받은 경우"},{"k":"ho","x":"4. 회원으로부터 현저히 신임을 잃었을 때"},{"k":"ho","x":"5. 본회의 회원에서 제명된 경우"},{"k":"hang","x":"② 탄핵안의 상정은 다음 각호의 요건 중 하나를 충족시켜야 한다."},{"k":"ho","x":"1. 학부운영위원회의 재적 3분의 2 이상에 해당하는 연서"},{"k":"ho","x":"2. 학생대표자회의 재적 3분의 2 이상에 해당하는 연서"},{"k":"ho","x":"3. 본회 회원 10분의 1 이상에 해당하는 연서"},{"k":"hang","x":"③ 연서에 따른 발의는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식에 의하여야 한다."},{"k":"hang","x":"④ 학부운영위원회는 탄핵안이 발의되면 즉시 탄핵안이 본조 제1항, 제2항, 제3항의 발의 요건을 충족시켰는지 심의하여야 하며, 중대한 하자가 없으면 탄핵안 제출일로부터 7일 이내에 학생총회 또는 학생총투표를 소집한다. 총회 및 학생총투표 방법에 관한 탄핵 안건이 모두 상정된 경우, 학부운영위원회의 출석 과반수에 해당하는 결의로 방법을 정한다. 단, 두 방법 모두 출석 과반수에 해당하는 결의가 성립되지 않으면, 탄핵안을 학생총투표에 상정하는 것으로 한다."}],"num":91,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a92","label":"제92조","title":"인수위원회","paras":[{"k":"hang","x":"① 학부 학생회장단 당선자는 학부 학생회장단 및 집행위원회의 업무 인수를 위해 당선 공고일로부터 48시간 이후부터 자유전공학부 학생회 인수위원회를 설치할 수 있다. 단, 재선거보ᆞ 궐선거로 당선되었을 경우 설치하지 아니한다."},{"k":"hang","x":"② 인수위원회는 다음 각호의 직무를 수행한다."},{"k":"ho","x":"1. 집행위원회의 조직ᆞ 기능 및 예산 현황의 파악"},{"k":"ho","x":"2. 전임 학부 학생회장단과 집행위원회의 주요 사업 분석"},{"k":"ho","x":"3. 기타 학부 학생회장단과 중앙집행위원회 업무의 인수에 필요한 사항"},{"k":"hang","x":"③ 인수위원장은 당선된 선거운동본부의 본부장으로 함을 원칙으로 한다."},{"k":"hang","x":"④ 인수위원회는 설치한 시간으로부터 7일 후 해산한다."}],"num":92,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제２절 집행위원회"},{"t":"art","id":"a93","label":"제93조","title":"지위","paras":[{"k":"line","x":"집행위원회는 본회의 최고집행기구이다."}],"num":93,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a94","label":"제94조","title":"구성","paras":[{"k":"line","x":"집행위원회는 집행위원장을 둘 수 있으며 집행위원회 산하 각국서의 국장ㆍ국원으로 구성한다."}],"num":94,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a95","label":"제95조","title":"집행위원장","paras":[{"k":"hang","x":"① 집행위원장은 학생회장단을 보좌하며, 본회 사무의 집행에 관하여 학부 학생회장단의 지시에 따라 각국서를 관리ㆍ감독한다."},{"k":"hang","x":"② 집행위원장은 학부 학생회장이 임명하고, 학부운영위원회의 사전 인준(임명)으로 업무를 개시한다. 집행위원장의 임명에 관하여서는 학생총회 또는 학생대표자회의의 사후 인준을 받아야 한다."}],"num":95,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a96","label":"제96조","title":"국서","paras":[{"k":"hang","x":"① 집행위원회는 원활한 업무 집행을 위하여 산하에 국서를 둘 수 있다."},{"k":"hang","x":"② 각국서의 국장과 국원은 학부 학생회장이 임명하고, 학부운영위원회의 사전 인준(임명)으로 업무를 개시한다. 각국서의 국장과 국원의 임명에 관하여서는 학생총회 또는 학생대표자회의 사후 인준을 받아야 한다."}],"num":96,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a97","label":"제97조","title":"업무","paras":[{"k":"hang","x":"① 집행위원회는 본회의 사업 집행 전반을 담당한다."},{"k":"hang","x":"② 집행위원회는 학생총회, 학부운영위원회가 결정한 업무를 집행한다."},{"k":"hang","x":"③ 집행위원회는 학부 학생회장단이 결정한 업무를 집행한다."},{"k":"hang","x":"④ 집행위원회는 각호의 사안에 대한 관리 권한을 갖는다. 관리 권한이라 함은 각 사안의 원활한 운영을 위하여 배타적인 권리행사 및 집행을 할 수 있는 권원을 의미한다."},{"k":"ho","x":"1. ｢학생회관리 권한등기부｣에 등기된 것"},{"k":"ho","x":"2. 학생회 자치 공간 분배 및 회수"},{"k":"ho","x":"3. 사물함 분배, 회수, 철거"},{"k":"hang","x":"⑤ 집행위원회는 학생총회, 학생총투표, 학부운영위원회의 개의ㆍ시행을 준비하고, 이에 사용되는 각종 서식을 ｢고려대학교 총학생회 사무처리세칙｣을 준용하여 제작한다."},{"k":"hang","x":"⑥ 집행위원회는 학생총회, 학부운영위원회에 본회의 운영 사항을 보고해야 한다."},{"k":"hang","x":"⑦ 집행위원회는 본회의 결산보고서ㆍ예산안을 작성하여 학생총회 또는 학생대표자회와 학부운영위원회에 보고해야 한다."},{"k":"hang","x":"⑧ 집행위원장 및 각 국장은 필요시 제55조 제5항에서 규정하는 절차를 거쳐 학부운영위원이 될 수 있다."}],"num":97,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a98","label":"제98조","title":"집행회의","paras":[{"k":"hang","x":"① 집행위원장은 집행위원회의 업무에 속하는 사안을 심의하기 위하여 집행회의를 소집할 수 있다. 이 경우 집행회의의 의장은 집행위원장이 된다."},{"k":"hang","x":"② 집행회의의 구성, 업무와 권한, 운영 등에 관하여서는 규칙으로 정한다."},{"k":"hang","x":"③ 집행위원장이 궐위일 경우 집행회의의 의장은 학생회장이 된다."}],"num":98,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a99","label":"제99조","title":"계열회의","paras":[{"k":"line","x":"집행위원회는 원활한 업무 집행을 위하여 특정 국서의 국장과 각 반 학생회, 동아리 등의 동종 업무 담당 국장 혹은 이에 준하는 자가 참가하는 계열회의를 개최할 수 있다. 계열회의의 구성, 업무와 권한, 운영 등에 관하여서는 규칙으로 정한다."}],"num":99,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제4장 산하기구"},{"t":"h","lv":3,"text":"제１절 반 학생회"},{"t":"art","id":"a100","label":"제100조","title":"지위","paras":[{"k":"line","x":"반 학생회는 고려대학교 자유전공학부 학생회원 중 A반부터 D반까지의 네 반을 기준으로 분류된 각 반의 회원들로 구성되며 반 학생회원들의 단결 및 권리와 이익 보장을 위해 자치활동을 하는 자유전공학부 학생회 산하기구이다."}],"num":100,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a101","label":"제101조","title":"회원","paras":[{"k":"hang","x":"① 자유전공학부 학생회원의 반 학생회별 분류는 다음 각호에 따른다."},{"k":"ho","x":"1. A반 소속 자유전공학부 학생회 회원은 A반 학생회원이 된다."},{"k":"ho","x":"2. B반 소속 자유전공학부 학생회 회원은 B반 학생회원이 된다."},{"k":"ho","x":"3. C반 소속 자유전공학부 학생회 회원은 C반 학생회원이 된다."},{"k":"ho","x":"4. D반 소속 자유전공학부 학생회 회원은 D반 학생회원이 된다."},{"k":"hang","x":"② 2학기 입학, 편입 등으로 반이 확정되지 않은 채로 회원이 된 경우, 해당 회원의 반은 학부운영위원회의 출석 과반수에 해당하는 결의로 결정한다."},{"k":"hang","x":"③ 반 학생회의 회원은 해당 반 학생회 회장단 선거의 선거권과 피선거권을 가진다."},{"k":"hang","x":"④ 반 학생회의 회원은 해당 반 학생회 사업을 향유할 권리를 지닌다."},{"k":"hang","x":"⑤ 회원의 권리 및 의무에 관한 사항은 각 반 학생회칙으로 정한다."}],"num":101,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a102","label":"제102조","title":"반 학생회장단","paras":[{"k":"hang","x":"① 반 학생회장단은 반 학생회칙에 따라 보통ㆍ평등ㆍ직접ㆍ비밀선거로 선출한다."},{"k":"hang","x":"② 반 학생회장단의 임기는 당선 공고 후 시작되며 다음 반 학생회장단의 당선 공고 전까지로 한다."},{"k":"hang","x":"③ 반 학생회장단의 권한ㆍ의무 사항에 대해서는 각 반 학생회칙으로 정한다."},{"k":"hang","x":"④ 반 학생회장은 해당 반을 대표하며 학생대표자회 대의원 및 학부운영위원회 위원이 된다."},{"k":"hang","x":"⑤ 반 학생회장은 총학생회 전체학생대표자회의의 대의원이 된다."}],"num":102,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a103","label":"제103조","title":"운영","paras":[{"k":"hang","x":"① 반 학생회의 최고 의결 기관은 반 학생총회이다."},{"k":"hang","x":"② 반 학생회는 정기적으로 반 학생총회 및 반 운영위원회를 개의해야 한다."},{"k":"hang","x":"③ 다음 각호 중 하나에 해당하는 자는 반 운영위원이 되며, 반 학생회장과 부학생회장을 제외한 반 운영위원의 선출ㆍ권한ㆍ의무 및 그 밖의 사항은 반 학생회칙으로 정한다."},{"k":"ho","x":"1. 반 학생회장과 부학생회장"},{"k":"ho","x":"2. 신입생 대표"},{"k":"ho","x":"3. 고학번 대표"},{"k":"ho","x":"4. 각 반 학생회칙으로 정한 이에 준하는 자"},{"k":"hang","x":"④ 반 학생회의 최고집행기관은 각 반 학생회의 집행위원회이며 반 학생회 집행위원회는 반 운영위원회에 사업을 성실히 보고하여야 한다."},{"k":"hang","x":"⑤ 반 학생회의 모든 기관과 기구의 권한과 업무는 각 반 학생회칙으로 정한다."}],"num":103,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a104","label":"제104조","title":"권리","paras":[{"k":"hang","x":"① 반 학생회는 학부 학생회로부터 재정 지원과 공간 지원을 받을 수 있다."},{"k":"hang","x":"② 반 학생회는 학부 학생회로부터 집행 인원을 지원받을 수 있다."},{"k":"hang","x":"③ 반 학생회는 법학관(신관), CJ법학관, 해송법학도서관 강의실을 대관할 수 있다."},{"k":"hang","x":"④ 반 학생회는 학생회 페이스북 페이지, 카카오톡 공지방, 행정실 게시판을 활용할 수 있다."}],"num":104,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a105","label":"제105조","title":"의무","paras":[{"k":"hang","x":"① 반 학생회는 매 학기 학생총회 또는 학생대표자회에서 예결산안에 대한 심의ㆍ승인 절차를 거쳐야 한다."},{"k":"hang","x":"② 반 학생회는 다른 반 학생회와 교류하고, 학생회 사업에 협력해야 한다."}],"num":105,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a106","label":"제106조","title":"위계","paras":[{"k":"hang","x":"① 반 학생회의 회칙 및 결정사항이 회칙ㆍ세칙과 충돌 할 시, 본회의 회칙ㆍ세칙과 합치될 수 있는 내용을 제외한 모든 내용은 무효로 한다. 단, 본회 회칙ㆍ세칙의 개정 및 신설로 인해 기존의 반 학생회 회칙 및 결정사항과 충돌이 생겼을 시, 소급효는 인정하지 않는다."},{"k":"hang","x":"② 반 학생회의 결정이 본회 의결기구의 결정과 충돌 할 시, 본회의 결정과 합치될 수 있는 내용을 제외한 모든 내용은 그 즉시 무효로 한다."},{"k":"hang","x":"③ 본조 제1항과 제2항의 회칙ㆍ세칙 및 결정 합치ㆍ불합치에 대한 판단은 제185조의 회칙 해석위원회의 결정에 따른다."}],"num":106,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제３절 자치단체"},{"t":"art","id":"a107","label":"제107조","title":"지위","paras":[{"k":"hang","x":"① 자치단체는 특정한 분야에서 특정한 목적을 가지고 활동하는 단체 중 자유전공학부 학생회에 등록절차를 마치고 매년 자유전공학부 학생회의 인준을 받아 활동하는 단체로 한다."},{"k":"hang","x":"② 본회 자치단체로의 등록은 학생총회 혹은 학생대표자회의에서 각호와 같은 사유에 해당될 때에만 거절될 수 있다. 단 아래의 사유는 각 단체의 특수한 목적을 고려하여 논의되어야 한다."},{"k":"ho","x":"1. 단체의 존속 가능성이 불분명한 경우"},{"k":"ho","x":"2. 단체의 활동과 목적이 본회가 추구하는 가치에 명백히 반하는 경우"},{"k":"ho","x":"3. 당해 모집 기간 이후에도 명부상 10명 이하의 회원만이 활동하는 것으로 판단되는 경우"},{"k":"ho","x":"4. 명부상 자유전공학부 회원이 구성원의 1/2 미만일 경우"},{"k":"ho","x":"5. 사회상규에 비추어 본회로의 등록이 용인되기 힘든 수준의 사유를 지닐 경우"},{"k":"hang","x":"③ 자치단체는 본회의 회원들의 관심사에 따른 자발적인 참여를 보장해야 하며, 본회 회원의 결속 및 학생회의 발전에 기여해야 한다."}],"num":107,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a108","label":"제108조","title":"회원","paras":[{"k":"hang","x":"① 각 자치단체에 소속된 본회의 회원은 해당 자치단체의 회원이 된다."},{"k":"hang","x":"② 자치단체의 회원은 해당 자치단체장 선거의 선거권과 피선거권을 가진다."},{"k":"hang","x":"③ 자치단체의 회원은 해당 자치단체의 사업을 향유할 권리를 지닌다."},{"k":"hang","x":"④ 본회의 회원에 해당하지 않는 자치단체 회원은 자치단체에 관한 회칙의 적용에 한해서는 본회의 회원으로 본다. 이 경우, 적용에 관해 이견이 있으면 제185조 회칙해석위원회의 결정에 따른다."}],"num":108,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a109","label":"제109조","title":"자치단체장","paras":[{"k":"hang","x":"① 자치단체장은 자치단체의 자치규칙에 따라 회원의 보통ㆍ평등ㆍ직접ㆍ비밀선거로 선출한다."},{"k":"hang","x":"② 자치단체장은 해당 자치단체를 대표하며 학생대표자회의 대의원이 된다."},{"k":"hang","x":"③ 자치단체 및 자치단체장의 권한ㆍ업무 등에 관하여서는 각 자치단체의 자치규칙으로 정한다."}],"num":109,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a110","label":"제110조","title":"권리","paras":[{"k":"hang","x":"① 자치단체는 학부 학생회로부터 집행 인원을 지원받을 수 있다."},{"k":"hang","x":"② 자치단체는 법학관(신관), CJ법학관, 해송법학도서관 강의실을 대관할 수 있다."},{"k":"hang","x":"③ 자치단체는 학생회 페이스북 페이지, 카카오톡 공지방, 행정실 게시판을 활용할 수 있다."}],"num":110,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a111","label":"제111조","title":"의무","paras":[{"k":"hang","x":"① 자치단체는 본회의 목표에 맞게 성실히 활동하며 창조적 대학 문화 창달을 위해 노력해야 한다."},{"k":"hang","x":"② 자치단체는 매년 1학기 학생총회 또는 학생대표자회의에서 인준 절차를 거쳐야 한다. 등록, 인준은 신청서에 의하며, 인준의 요건은 107조 2항을 준용한다."},{"k":"hang","x":"③ 인준받지 못한 자치단체는 2학기 학생총회 또는 학생대표자회의에서 재인준 절차를 거쳐야 하며, 재인준받지 못할 경우, 재인준에 관한 안건이 결의된 학생총회 또는 학생대표자회의의 종료일을 기준으로 30일 이내에 자치공간 및 본회 자산을 반납하여야 한다."},{"k":"hang","x":"④ 자치단체는 다른 자치단체와 교류하고, 학생회 사업에 협력해야 한다."}],"num":111,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a112","label":"제112조","title":"위계","paras":[{"k":"hang","x":"① 자치단체의 결정 및 자치규약과 학부 학생회의 결정 및 회칙과의 위계에 관해서는 제106조를 준용한다."},{"k":"hang","x":"② 자치단체의 결정 및 자치규약과 반 학생회의 결정 및 회칙과의 위계에 관해서는 제106조를 준용한다."}],"num":112,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제4절 특별위원회"},{"t":"art","id":"a113","label":"제113조","title":"목적","paras":[{"k":"line","x":"감찰, 조사, 프로젝트 등 특수한 목적 달성을 위해 학생대표자회 혹은 학부운영위원회 산하에 한시적으로 특별위원회를 둘 수 있다."}],"num":113,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a114","label":"제114조","title":"구성","paras":[{"k":"hang","x":"① 특별위원회는 학생대표자회 혹은 학부운영위원회에서 임명한 위원장 1인과 위원으로 구성한다."},{"k":"hang","x":"② 특별위원회의 위원장과 위원은 공개모집을 원칙으로 하되 필요한 경우 학부운영위원회의 출석 과반수에 해당하는 결의로 집행위원만으로 구성할 수 있다."},{"k":"hang","x":"③ 특별위원회는 구체적인 활동 목적을 가지고 구성되어야 하며, 특별위원회 구성에 대한 안건에는 반드시 특별위원회의 구체적인 활동 목적과 활동 범위가 명시되어야 한다. 조사, 감찰의 경우 대상자를 특정할 수 있는 경우에는 안건에 함께 기재해야 한다."}],"num":114,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a115","label":"제115조","title":"인준","paras":[{"k":"line","x":"특별위원회의 위원장과 위원은 학부운영위원회의 사전 동의로 활동을 개시하며 소속된 의결기구에서 사후 인준을 받아야 한다."}],"num":115,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a116","label":"제116조","title":"활동","paras":[{"k":"hang","x":"① 특별위원회는 활동 목적에 직ㆍ간접적으로 필요하다고 판단될 경우, 학부운영위원회의 출석 3분의 2 이상에 해당하는 결의로 구체적 활동 범위를 벗어난 활동을 할 수 있다. 이 경우, 필요한 이유 및 재설정한 활동 범위를 소속된 의결기구에 보고하여야 하며, 소속된 의결기구는 언제든지 출석 과반수에 해당하는 결의로 학부운영위원회의 해당 결정을 취소할 수 있다."},{"k":"hang","x":"② 특별위원회의 활동 기간은 최단 7일, 최장 60일까지이다. 단, 1회에 한해 30일을 연장할 수 있 다."},{"k":"hang","x":"③ 특별위원회의 활동 목적이 새내기새로배움터 준비인 경우, 제2항을 적용하지 아니한다."},{"k":"hang","x":"④ 특별위원회는 활동 목적에 따라 회원 및 단체에 위원회 출석 및 자료 제출을 요청할 수 있다."}],"num":116,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a117","label":"제117조","title":"해산 및 폐지","paras":[{"k":"hang","x":"① 다음 각호에 해당하는 경우 특별위원회는 해산한다."},{"k":"ho","x":"1. 활동 목적이 달성된 경우"},{"k":"ho","x":"2. 활동 기간이 종료된 경우"},{"k":"hang","x":"② 특별위원회는 언제든지 소속된 의결기구의 출석 3분의 2 이상에 해당하는 결의로 폐지할 수 있다. 단, 특별위원회의 목적이 감찰 및 조사에 해당하는 경우, 감찰 및 조사의 대상이 되는 회원은 의결기구에서 의결권을 행사할 수 없다."}],"num":117,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제５장 독립기구"},{"t":"art","id":"a118","label":"제118조","title":"지위","paras":[{"k":"hang","x":"① 독립기구는 특수한 영역과 기능을 담당하기 위하여 설치된 상설기구이다."},{"k":"hang","x":"② 독립기구는 자유전공학부 학생회의 물적·인적 지원을 받으며 학부 학생회장단으로부터 그 업무의 감독을 받는다. 다만, 자유전공학부 집행위원회로부터는 독립적인 위상을 보장받는다."},{"k":"hang","x":"③ 전항에도 불구하고 독립기구의 업무가 학부 학생회장단으로부터의 독립의 필요성이 인정되는 범위 내에서 그 독립성이 보장된다."}],"num":118,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a119","label":"제119조","title":"성립 요건","paras":[{"k":"hang","x":"① 독립기구는 다음 각호 중 하나 이상의 요건을 갖추어 설치가 필요하다고 인정될 때에 설치된다."},{"k":"ho","x":"1. 본회 회원의 권익 보호를 위한 전문적 활동을 꾸준히 수행하여 독립기구로서의 정체성이 확보되어 있는 단체"},{"k":"ho","x":"2. 본회 차원의 포괄적, 대외적 사업이 필요한 분야에 관련된 단체"}],"num":119,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제1절 선거관리위원회"},{"t":"art","id":"a120","label":"제120조","title":"목적","paras":[{"k":"line","x":"선거관리위원회는 민주적이고 공정한 절차에 입각해 선거를 효율적으로 진행하는 데 그 목적을 둔다."}],"num":120,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a121","label":"제121조","title":"구성","paras":[{"k":"hang","x":"① 선거관리위원회는 학부 학생회장단을 제외한 학부운영위원 및 학생회칙 제55조 제5항에 의해 의결권을 가질 수 있는 자 전원을 기본으로 구성하며, 나머지 인원은 공개 모집함을 원칙으로 한다. 단, 반 학생회장단 동시선거의 경우, 해당 선거를 진행하는 선거관리위원회는 학부운영위원 및 학생회칙 제55조 제5항에 의해 의결권을 가질 수 있는 자 전원을 기본으로 구성하며, 나머지 인원은 공개 모집함을 원칙으로 한다."},{"k":"hang","x":"② 선거관리위원회는 학부운영위원회 회의에서 인준받은 8인 이상 12인 이하의 선거관리위원으로 구성된다."}],"num":121,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a122","label":"제122조","title":"대표자 선출","paras":[{"k":"line","x":"선거관리위원회의 위원장은 학부 학생회장단을 제외한 학부운영위원 중 1인으로 한다. 단, 반 학생회장 동시선거의 경우, 해당 선거를 진행하는 선거관리위원회의 위원장은 학부 학생회장으로 한다."}],"num":122,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a123","label":"제123조","title":"활동 내용","paras":[{"k":"hang","x":"① 선거관리위원회는 제6장 선거에서 규정하는 선거에 관한 절차를 성실히 이행한다."},{"k":"hang","x":"② 선거관리위원회는 제6장 선거에서 규정하는 절차에 관해 최고 해석권 및 결정권을 가지며, 본회의 어떠한 의결기구도 회칙에 따라 진행된 선거 절차상의 해석 및 결정을 번복ㆍ철회ㆍ변경할 수 없다."},{"k":"hang","x":"③ 선거관리위원은 선거기간 동안 징계할 수 없으며, 선거관리위원회의 출석 3분의 2 이상에 해당하는 결의로만 해임할 수 있다."}],"num":123,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a124","label":"제124조","title":"의무","paras":[{"k":"hang","x":"① 선거관리위원회의 결정은 표결로서 진행하며, 표결은 기명으로 진행한다."},{"k":"hang","x":"② 선거관리위원회는 결정 사항 및 선거의 진행 상황을 정기적으로 공고해야 한다."},{"k":"hang","x":"③ 선거관리위원은 중립성을 지켜야 하며, 선거에 부당한 영향을 미치는 활동을 할 수 없다."}],"num":124,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a125","label":"제125조","title":"집행위원회에 대한 사항","paras":[{"k":"hang","x":"① 선거관리위원회는 선거 사무의 처리에 관해 집행위원회의 협조를 얻을 수 있다."},{"k":"hang","x":"② 선거관리위원회는 선거의 원활한 진행을 위해 집행위원회에 사무의 처리를 요청할 수 있다."}],"num":125,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a126","label":"제126조","title":"학부 학생회장단에 대한 사항","paras":[{"k":"hang","x":"① 학부 학생회장단은 학부 학생회장단 선거관리위원회의 결정 및 집행에 일체 개입할 수 없다."},{"k":"hang","x":"② 학부 학생회장단 선거 진행에 학부 학생회장단의 부당한 영향력 행사가 있을시, 선거관리위원회는 선거 기간 동안 기간을 정해 한시적으로 학부 학생회장단의 해당 직무 및 활동을 정지ㆍ취소할 수 있다."}],"num":126,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a127","label":"제127조","title":"재정","paras":[{"k":"line","x":"본회는 선거관리위원회의 원활한 운영을 위한 재원을 마련해야 한다."}],"num":127,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 투표관리위원회"},{"t":"art","id":"a128","label":"제128조","title":"목적","paras":[{"k":"line","x":"투표관리위원회는 민주적이고 공정한 절차에 입각해 학생총투표를 효율적으로 진행하는 데 그 목적을 둔다."}],"num":128,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a129","label":"제129조","title":"투표관리위원회","paras":[{"k":"hang","x":"① 투표관리위원회는 학부운영위원 및 제55조 제5항에 의해 의결권을 가질 수 있는 자 전원으로 구성한다. 단, 학부 학생회장단은 제60조에 따른 학부 학생회장단 탄핵안에 대한 학생총투표에 대해서는 투표관리위원이 될 수 없다."}],"num":129,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a130","label":"제130조","title":"대표자 선출","paras":[{"k":"line","x":"투표관리위원회의 위원장은 학부 학생회장단을 제외한 학부운영위원 중 1인으로 한다."}],"num":130,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a131","label":"제131조","title":"활동 내용","paras":[{"k":"hang","x":"① 투표관리위원회는 제2장 제3절 학생총투표에서 규정하는 학생총투표에 관한 절차를 성실히 이행한다."},{"k":"hang","x":"② 투표관리위원회는 제2장 제3절 학생총투표에서 규정하는 절차에 관해 최고 해석권 및 결정권을 가지며, 본회의 어떠한 의결기구도 회칙에 따라 진행된 투표 절차상의 해석 및 결정을 번복ㆍ철회ㆍ변경할 수 없다."}],"num":131,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a132","label":"제132조","title":"준용","paras":[{"k":"hang","x":"① 의무에 관해서는 제124조를 준용한다."},{"k":"hang","x":"② 집행위원회에 대한 사항에 대해서는 제125조를 준용한다."},{"k":"hang","x":"③ 학부 학생회장단에 대한 사항에 대해서는 제126조를 준용한다."},{"k":"hang","x":"④ 재정에 관해서는 제127조를 준용한다."}],"num":132,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제3절 학생자치장학금위원회"},{"t":"art","id":"a133","label":"제133조","title":"위계","paras":[{"k":"line","x":"학생자치장학금의 집행 및 운영에 관하여 회칙ㆍ세칙에 규정이 없으면 학생자치장학금 내규에 의하고 내규가 없으면 장학금위원회의 결정사항에 의한다."}],"num":133,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a134","label":"제134조","title":"구성","paras":[{"k":"hang","x":"① 학생자치장학금위원회는 장학금운영위원회와 장학금집행위원회로 구성된다."},{"k":"hang","x":"② 장학금운영위원회는 학부운영위원회 전원으로 구성한다."},{"k":"hang","x":"③ 장학금집행위원회는 공개모집하여야 한다."},{"k":"hang","x":"④ 학생자치장학금위원회 위원은 자유전공학부 학생회 회원 중 징계를 받지 아니한 자로 한다."}],"num":134,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a135","label":"제135조","title":"목적","paras":[{"k":"hang","x":"① 장학금운영위원회는 본 장학금에 관련된 제반 사항을 감시·감독하고 보고받는 데 그 목적을 둔다."},{"k":"hang","x":"② 장학금집행위원회는 본 장학금에 관한 사항을 집행하는 데 그 목적을 둔다."}],"num":135,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a136","label":"제136조","title":"대표자 선출","paras":[{"k":"hang","x":"① 장학금운영위원회의 위원장은 학부 학생회장으로 한다."},{"k":"hang","x":"② 장학금집행위원회의 대표는 장학금집행위원회에서 보통⋅평등⋅직접⋅비밀선거로 선출한다."}],"num":136,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a1397","label":"제1397조","title":"활동 내용","paras":[{"k":"hang","x":"① 장학금운영위원회는 각호의 업무를 수행한다."},{"k":"ho","x":"1. 장학금 운영사항에 관련된 감독"},{"k":"ho","x":"2. 장학금 지급, 장학금집행위원 및 장학금집행위원회 활동에 대한 감사"},{"k":"ho","x":"3. 장학금 운영 전반에 관련된 정보공개청구"},{"k":"ho","x":"4. 장학금집행위원회 위원 임면"},{"k":"ho","x":"5. 학생자치장학금 내규 개정"},{"k":"ho","x":"6. 장학금집행위원회 운영목적에 부합하는 필수적 활동이 이뤄지지 않는 경우, 이러한 활동에 대한 촉구, 지시 혹은 활동 그 자체. 단, 활동의 집행은 가급적 자제한다."},{"k":"hang","x":"② 장학금집행위원회는 다음 각호의 업무를 수행한다."},{"k":"ho","x":"1. 장학금 명칭 및 세부사항에 관한 결정"},{"k":"ho","x":"2. 장학금 지급 규모에 관한 결정"},{"k":"ho","x":"3. 장학금 관련 일정 결정"},{"k":"ho","x":"4 장학금 지급 관련 모든 회계업무"},{"k":"ho","x":"5. 이외에 기타 필요하다고 인정되는 사무"}],"num":1397,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a138","label":"제138조","title":"준용","paras":[{"k":"hang","x":"① 장학금운영위원회의 의무에 관해서는 제124조를 준용한다. 단, 제124조 제3항은 준용하지 아니한다."},{"k":"hang","x":"② 재정에 관해서는 제127조를 준용한다"},{"k":"hang","x":"③ 장학금운영위원회 회의의 진행에 관한 절차는 출석 과반수에 해당하는 결의로 학부운영위원회의 절차를 준용할 수 있다."}],"num":138,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a139","label":"제139조","title":"중요활동에 관한 사항","paras":[{"k":"line","x":"장학금운영위원회는 회원에게 중대한 영향을 미치는 장학금집행위원회의 활동에 대하여 동의권을 갖는다. 단, 장학금집행위원회의 효율적인 활동을 보장하기 위하여 장학금집행위원회 대표가 사전 집행이 불가피하다고 판단하여 집행한 사업에 대하여는 사후에 보고하고 동의 절차를 이행할 수 있다. 장학금집행위원회는 부동의 된 대외활동에 대해서는 의결 즉시 원상회복을 위해 노력해야 한다."}],"num":139,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제4절 학생홍보대사"},{"t":"art","id":"a140","label":"제140조","title":"목적","paras":[{"k":"line","x":"학생홍보대사는 대외적으로 자유전공학부를 홍보하고, 자유전공학부의 가치 제고 및 위상을 높이는 데 목적을 둔다."}],"num":140,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a1431","label":"제1431조","title":"구성","paras":[{"k":"hang","x":"① 학생홍보대사는 공개 모집하여야 한다."},{"k":"hang","x":"② 학생홍보대사는 자유전공학부 학생회 회원 중 징계를 받지 아니한 자로 한다."}],"num":1431,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a142","label":"제142조","title":"대표자 선출","paras":[{"k":"line","x":"학생홍보대사의 대표는 보통ㆍ평등ㆍ직접ㆍ비밀선거로 선출한다."}],"num":142,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a1453","label":"제1453조","title":"활동 내용","paras":[{"k":"line","x":"학생홍보대사의 활동은 다음 각호로 정한다."},{"k":"ho","x":"1. 자유전공학부 홍보 활동 진행"},{"k":"ho","x":"2. 모교 방문 자유전공학부 홍보 행사 진행"},{"k":"ho","x":"3. 학생 초청 자유전공학부 홍보 행사 진행"}],"num":1453,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a144","label":"제144조","title":"권리","paras":[{"k":"hang","x":"① 학생홍보대사는 본회로부터 공간을 지원받을 수 있다."},{"k":"hang","x":"② 학생홍보대사는 법학관(신관), CJ법학관, 해송법학도서관 강의실을 대관할 수 있다."},{"k":"hang","x":"③ 학생홍보대사는 학생회 페이스북 페이지, 카카오톡 공지방, 행정실 게시판을 활용할 수 있다."}],"num":144,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a145","label":"제145조","title":"재정","paras":[{"k":"line","x":"본회는 학생홍보대사의 원활한 운영을 위한 재원을 마련해야 한다."}],"num":145,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제5절 소수자인권위원회"},{"t":"art","id":"a146","label":"제146조","title":"목적","paras":[{"k":"line","x":"소수자인권위원회는 본회 내 소수자의 인권을 증진하는 데 목적을 둔다."}],"num":146,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a147","label":"제147조","title":"구성","paras":[{"k":"hang","x":"① 소수자인권위원회는 공개 모집하여야 한다."},{"k":"hang","x":"② 소수자인권위원회는 자유전공학부 학생회 회원 중 징계를 받지 아니한 자로 한다."}],"num":147,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a148","label":"제148조","title":"대표자 선출","paras":[{"k":"line","x":"소수자인권위원회의 대표는 보통ㆍ평등ㆍ직접ㆍ비밀선거로 선출한다."}],"num":148,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a149","label":"제149조","title":"활동 내용","paras":[{"k":"line","x":"소수자인권위원회의 활동은 다음 각호로 정한다."},{"k":"ho","x":"1. 인권 담론의 공고화 및 확장"},{"k":"ho","x":"2. 인권침해의 발생 방지 노력"},{"k":"ho","x":"3. 인권침해 피해자에 대한 보호"},{"k":"ho","x":"4. 인권 관련 전문 역량의 확보"}],"num":149,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a150","label":"제150조","title":"권리","paras":[{"k":"hang","x":"① 소수자인권위원회는 본회로부터 공간을 지원받을 수 있다."},{"k":"hang","x":"② 소수자인권위원회는 법학관(신관), CJ법학관, 해송법학도서관 강의실을 대관할 수 있다."},{"k":"hang","x":"③ 소수자인권위원회는 학생회 페이스북 페이지, 카카오톡 공지방, 행정실 게시판을 활용할 수 있다."}],"num":150,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a151","label":"제151조","title":"재정","paras":[{"k":"line","x":"본회는 소수자인권위원회의 원활한 운영을 위한 재원을 마련해야 한다."}],"num":151,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제6장 선거"},{"t":"h","lv":3,"text":"제1절 학부 학생회장단 선거"},{"t":"art","id":"a152","label":"제152조","title":"선거 방식","paras":[{"k":"hang","x":"① 학부 학생회장단은 회원의 보통ㆍ평등ㆍ직접ㆍ비밀 선거로 선출한다."},{"k":"hang","x":"② 학부 학생회장단 선거에는 학부 학생회장 후보 단독으로 출마하거나 학부 학생회장 후보와 학부 부학생회장 후보 각 한 명씩이 조를 이루어 입후보할 수 있다."},{"k":"hang","x":"③ 학부 학생회장단 선거에서 최다 득표한 조가 학부 학생회장단으로 당선된다."},{"k":"hang","x":"④ 학부 학생회장단 후보가 한 조일 때는 찬성이 기권과 반대의 합보다 많아야 당선된다."}],"num":152,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a153","label":"제153조","title":"시기","paras":[{"k":"line","x":"학부 학생회장단 선거는 매년 11월에 시행함을 그 원칙으로 한다. 세부 일정은 학부운영위원회에서 정한다."}],"num":153,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a154","label":"제154조","title":"선거권ㆍ피선거권","paras":[{"k":"hang","x":"① 본회 정회원은 학부 학생회장단 선거의 선거권이 있다."},{"k":"hang","x":"② 본회의 회원인 자는 학부 학생회장단 선거의 피선거권이 있다."},{"k":"hang","x":"③ 학부 학생회장단 선거에 학부 학생회장 후보 단독으로 출마한 경우 그 후보는 3학기 이상 등록자이어야 한다. 단, 학부 학생회장 후보와 학부 부학생회장 후보 각 한 명이 조를 이루어 입후보한 경우 둘 중 한 명만 3학기 이상 등록자인 경우도 피선거권이 있다."},{"k":"hang","x":"④ 징계로서 선거권과 피선거권을 박탈당한 자는 선거의 선거권과 피선거권이 없다."}],"num":154,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a155","label":"제155조","title":"선거관리위원회","paras":[{"k":"hang","x":"① 학부 학생회장단 선거를 공정하게 민주적으로 관리하기 위하여 선거관리위원회를 둔다."},{"k":"hang","x":"② 선거관리위원회는 회칙과 ｢자유전공학부 선거시행세칙｣에 따라 학부 학생회장단 선거에 관련된 모든 사항을 결정한다."},{"k":"hang","x":"③ 선거 기간 동안 학부 학생회장단과 집행위원회가 사업 집행, 의견 표명 등을 하기 위해서는 선거관리위원회의 사전 허가를 받아야 한다. 학생회장단과 집행위원회의 특정 행위가 선거에 영향을 미칠 수 있다고 판단되면 선거관리위원회는 해당 행위를 허가하지 않을 수 있다."},{"k":"hang","x":"④ 이 밖에 선거관리위원회의 운영에 관한 절차는 제5장 제1절 선거관리위원회 규정에 따른다."}],"num":155,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a156","label":"제156조","title":"보궐선거","paras":[{"k":"hang","x":"① 학생회장단이 탄핵 등의 이유로 궐위된 때 잔여 임기가 180일이 넘으면 궐위된 날로부터 10일 이내에 학부운영위원회는 보궐선거의 시행 일정을 결정하여야 한다. 단, 임기 종료일이 확정되지 않았을 때는 잔여 임기의 계산을 위한 임기 종료일은 11월 30일로 한다."},{"k":"hang","x":"② 잔여 임기가 180일이 넘지 않은 경우에도 학부운영위원회는 선거의 필요성, 선거 시기, 잔여 임기 등 본회의 제반 사정을 고려하여 보궐선거의 시행을 결정할 수 있다."},{"k":"hang","x":"③ 학부운영위원회가 보궐선거 시행 일정을 확정한 날로부터 20일 이내에 보궐선거를 시행하여야 한다."}],"num":156,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a157","label":"제157조","title":"선거시행세칙","paras":[{"k":"line","x":"그 밖에 선거에 관한 사항은 ｢자유전공학부 선거시행세칙｣으로 정한다."}],"num":157,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 반 학생회장단 동시선거"},{"t":"art","id":"a158","label":"제158조","title":"반 학생회장단 동시선거","paras":[{"k":"hang","x":"① 학부 학생회장단 선거관리위원회는 학부운영위원회의 출석 과반수에 해당하는 결의로 반 학생회장단 동시선거를 진행할 수 있다."},{"k":"hang","x":"② 제1항에서 규정하는 동시선거를 진행하지 않는 경우, 각 반 학생회장단 선거에 관한 제반 사항은 각 반 학생회칙이 정하는 바에 의한다."},{"k":"hang","x":"③반 학생회장단 동시선거가 결정되면, 본회의 회칙이 규정하는 절차에 따라 반 학생회장단 선거를 진행한다."}],"num":158,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a159","label":"제159조","title":"준용","paras":[{"k":"hang","x":"① 선거방식에 관해서는 제152조를 준용한다."},{"k":"hang","x":"② 선거 시기에 관해서는 제153조를 준용한다."},{"k":"hang","x":"③ 선거권에 관해서는 제154조를 준용한다."},{"k":"hang","x":"④ 선거관리위원회에 관해서는 제155조를 준용한다."},{"k":"hang","x":"⑤ 보궐선거에 관해서는 제156조를 준용한다."},{"k":"hang","x":"⑥ ｢선거시행세칙｣에 관해서는 제157조를 준용한다."}],"num":159,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제7장 재정"},{"t":"h","lv":3,"text":"제１절 통 칙"},{"t":"art","id":"a160","label":"제160조","title":"원칙","paras":[{"k":"line","x":"본회의 각 기구는 재정을 효율적이고 투명하게 운용하여야 한다."}],"num":160,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a161","label":"제161조","title":"재정운용세칙","paras":[{"k":"line","x":"그 밖에 재정 운용에 관한 사항은 ｢고려대학교 총학생회 재정운용세칙｣으로 정한다."}],"num":161,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제２절 자산ㆍ배분"},{"t":"art","id":"a162","label":"제162조","title":"자산","paras":[{"k":"hang","x":"① 본회는 유ㆍ무형의 동산, 부동산, 권리 등을 소유할 수 있으며, 이를 본회의 자산이라 한다."},{"k":"hang","x":"② 본회의 자산은 각 기구가 독립하여 취득, 보관, 사용, 처분함을 원칙으로 한다."},{"k":"hang","x":"③ 집행기구는 제작, 구매, 증여받음 등의 방법으로 자산을 취득한다. 다음 각호 중 어느 하나에 해당하는 것은 집행기구의 자산으로 본다."},{"k":"ho","x":"1. ｢학생회자산등기부｣에 등기된 것"},{"k":"ho","x":"2. 취득 과정에서 본회의 자산이 투입된 것"},{"k":"ho","x":"3. 학부 학생회장단, 집행위원과 이에 준하는 자가 그 직으로써 취득한 것"},{"k":"ho","x":"4. 본회 집행기구의 사업 또는 사무 집행을 위하여 취득하거나, 사업 집행의 결과물로 취득한 것"},{"k":"ho","x":"5. 1호 내지 4호에 해당하는 자산으로부터 파생된 것"}],"num":162,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a163","label":"제163조","title":"자산의 관리","paras":[{"k":"hang","x":"① 집행기구는 자산을 항상 사용하거나 처분할 수 있도록 선량한 관리자의 주의로써 보관하여야 한다."},{"k":"hang","x":"② 집행기구 자산은 본회 사업과 사무의 집행을 위하여 사용함을 원칙으로 한다."},{"k":"hang","x":"③ 집행기구 자산은 대여를 목적으로 한 자산이거나 대여하여도 사업 또는 사무에 지장이 없다고 인정되는 자산일 때만 대여할 수 있다. 또한, 집행기구 자산은 본회 기구와 회원에게 우선적으로 대여되어야 한다."},{"k":"hang","x":"④ 집행기구는 자산의 취득, 보관, 사용, 처분이 본회의 이익을 위하여 적정하고 효율적으로 이루어질 수 있도록 하여야 한다."},{"k":"hang","x":"⑤ 집행기구는 자산의 중대한 변화를 야기하는 집행에 대해 학부운영위원회의 인준을 받아야 한다. 이 경우, 사전에 집행에 대한 예고를 해야 하며, 집행 후 자산 변화를 공고해야 한다."},{"k":"hang","x":"⑥ 집행위원회는 집행기구 자산 중 고정자산의 목록을 작성하여 매 학기 정기학생총회 또는 정기학생대표자회에 보고한다. 고정자산에 포함되는 자산의 종류에 관하여서는 ｢고려대학교 총학생회 재정운용세칙｣으로 정한다."},{"k":"hang","x":"⑦ 집행기구는 사용할 필요가 없거나 사용할 수 없는 자산을 교환, 매각, 증여, 폐기 등의 방법으로 처분할 수 있다."},{"k":"hang","x":"⑧ 의결기구는 집행기구의 자산 취득, 보관, 사용, 처분이 본회의 이익을 위한 것이 아니거나, 적정성 또는 효율성이 없다고 판단되면 이를 허가하지 않거나, 취소할 수 있다."}],"num":163,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a164","label":"제164조","title":"수입","paras":[{"k":"line","x":"본회 재정의 수입은 학생회비, 학교 지원금, 사업별 후원금, 그 밖에 수익금으로 한다."}],"num":164,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a165","label":"제165조","title":"학생회비","paras":[{"k":"hang","x":"① 학생회비는 일시납부·1회 납부를 원칙으로 한다. 단, 일시납부 하지 못할 경제적·사회적 또는 그 밖의 중대한 사유가 있는 경우 분할납부를 할 수 있다."},{"k":"hang","x":"② 집행위원회는 학생회비의 수입 지출과 관련된 집행내역을 매달 날짜를 정하여 공고하여야 한다."},{"k":"hang","x":"③ 학부 학생회비의 수입 중 반 학생회비에 할당되는 금액은 반 학생회 소속 학생회비 납부자 1인당 40,000원으로 한다."},{"k":"hang","x":"④ 학생총회 또는 학생대표자회는 매년 2학기 정기회의에서 학부 학생회비의 조정에 관하여 논의하며, 필요할 때는 인상ㆍ인하를 결정할 수 있다."},{"k":"hang","x":"⑤ 그 밖에 학생회비의 배분과 관련된 사항은 ｢고려대학교 총학생회재정운용세칙｣으로 정한다."}],"num":165,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제３절 회계ㆍ심의"},{"t":"art","id":"a166","label":"제166조","title":"회계연도","paras":[{"k":"line","x":"본회의 재정은 다음 각호의 기간으로 나누어 집행하고 결산한다."},{"k":"ho","x":"1. 제1분기: 2학기 종강일 다음 날부터 1학기 개강일 전날까지"},{"k":"ho","x":"2. 제2분기: 1학기 개강일부터 1학기 종강일까지"},{"k":"ho","x":"3. 제3분기: 1학기 종강일 다음 날부터 2학기 개강일 전날까지"},{"k":"ho","x":"4. 제4분기: 2학기 개강일부터 2학기 종강일까지"}],"num":166,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a167","label":"제167조","title":"학부운영위원회 심의","paras":[{"k":"hang","x":"① 학생회비를 사용하는 집행위원회 및 독립기구 등은 다음 각호에 따라 예산안ㆍ결산을 작성하여 학생총회 또는 학생대표자회 개의 예정일 7일 전까지 학부운영위원회에 제출하여야 한다."},{"k":"ho","x":"1. 1학기 정기회의: 작년도 4분기, 금년도 1분기의 결산과 금년도 2분기ㆍ3분기의 예산안"},{"k":"ho","x":"2. 2학기 정기회의: 금년도 2분기ㆍ3분기의 결산과 금년도 4분기, 익년도 1분기의 예산안"},{"k":"hang","x":"② 학부운영위원회는 제１항에 따라 제출된 예산안ㆍ결산을 심의한다."},{"k":"hang","x":"③ 학부운영위원회는 제１항에 따른 예산안ㆍ결산 제출기한을 정하여 공고하고 예산안ㆍ결산 보고의 의무가 있는 기구에 개별적으로 통보하여야 한다."}],"num":167,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a168","label":"제168조","title":"승인","paras":[{"k":"hang","x":"① 학생회비를 사용하는 집행위원회 및 독립기구 등은 제167조 제1항에 따라 학부운영위원회의 심의를 거친 예산안ㆍ결산을 학생총회 또는 학생대표자회에 보고한다."},{"k":"hang","x":"② 학생대표자회 또는 학생총회는 제１항에 따라 보고된 예산안ㆍ결산을 승인한다."},{"k":"hang","x":"③ 학생대표자회 또는 학생총회에서 승인된 예산안ㆍ결산은 공개되어야 한다."},{"k":"hang","x":"④ 각 기구는 학생총회 또는 학생대표자회 출석 구성원의 과반수에 해당하는 동의가 있으면 예산안ㆍ결산을 현장에서 수정 발의하여 재상정할 수 있다."}],"num":168,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a169","label":"제169조","title":"재심의","paras":[{"k":"hang","x":"① 다음 각호에 해당하는 경우, 학생총회 또는 학생대표자회는 출석 과반수의 찬성으로 해당 기구에의 학생회비 지급을 유보하고 학부운영위원회에서 재심의를 받도록 해야 한다. 재심의에서의 승인은 학부운영위원회 출석 3분의 2 이상의 결의에 의한다."},{"k":"ho","x":"1. 예산안ㆍ결산이 승인되지 못한 경우"},{"k":"ho","x":"2. 예산안ㆍ결산에 중대한 하자가 있는 경우"},{"k":"ho","x":"3. 심의 과정 중 절차상 문제가 발견된 경우"},{"k":"ho","x":"4. 판단자료 미비로 예산안ㆍ결산에 대한 심의가 불가능하거나 예산안ㆍ결산을 신뢰할 수 없을 경우"},{"k":"hang","x":"② 제１항에 해당하는 기구는 학생총회 또는 학생대표자회 개의일로부터 10일 이내에 수정안을 작성하여 학부운영위원회에 제출해야 한다."},{"k":"hang","x":"③ 학부운영위원회는 수정안을 지체 없이 심의하여 학부 총회 개의일로부터 15일 이내에 결과를 공고한다."},{"k":"hang","x":"④ 제１항에 해당함에도 수정안을 학부운영위원회에 제출하지 않은 기구 혹은 제기된 문제를 개선하지 않은 채 수정안을 작성하여 제출한 기구는 책임자에 따라 각호 중 하나의 징계를 한다. 책임자란 불승인 결정에 직 · 간접적인 책임이 있는 대표자 및 기구의 구성원을 의미한다."},{"k":"ho","x":"1. 책임자가 현직일 때: 예산 지급액의 50% 삭감과 사과문ㆍ경위서 게재"},{"k":"ho","x":"2. 책임자가 전직일 때: 책임자의 사과문ㆍ경위서 게재"},{"k":"hang","x":"⑤ 배임, 횡령 사안 등 문제의 정도가 심각한 경우 학부운영위원회는 제4항의 징계와 함께 다음 각호의 조치를 함께 결정할 수 있다. 제3호의 경우 책임자와 학생회비가 불법하게 사용될 당시 대표자가 연대하여 책임을 져야 한다."},{"k":"ho","x":"1. 기구가 가지고 있는 학생회비 잔금 사용 중지"},{"k":"ho","x":"2. 기구가 가지고 있는 학생회비 잔금 전액 환수"},{"k":"ho","x":"3. 기구가 불법하게 사용한 학생회비 전액 반환"},{"k":"ho","x":"4. 제38조에 따른 책임자에 대한 징계안 발의"}],"num":169,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제8장 자치공간"},{"t":"h","lv":3,"text":"제1절 자치공간 관리"},{"t":"art","id":"a170","label":"제170조","title":"목적","paras":[{"k":"line","x":"본회의 자치공간은 본회의 자치활동의 기초가 되는 토대로서, 회원의 교류 및 결속을 공고히 하고 회원을 보호하며 안정을 보장해주는 역할을 통해 창조적이고 진보적인 대학문화를 건설하는 데 기여함을 목적으로 한다."}],"num":170,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a171","label":"제171조","title":"자치공간","paras":[{"k":"hang","x":"① 본회의 자치공간은 다음 각호로 정한다."},{"k":"ho","x":"1. ｢자치공간등기부｣에 등기된 공간"},{"k":"ho","x":"2. 학부 학생회실"},{"k":"ho","x":"3. 법학관(구관) 각 반 학생회실, 각 자치단체실, 학생회창고"},{"k":"ho","x":"4. 법학관(신관) 사물함보관실 B102호, B103호"},{"k":"ho","x":"5. 기타 본회의 노력으로 확보 · 명도 받은 공간"},{"k":"hang","x":"② 본회는 대내·외적으로 자치공간을 이용, 분배, 회수, 보수, 개조할 관리 권한을 갖는다. 관리 권한이라 함은 각 사안의 원활한 운영을 위하여 배타적인 권리행사 및 집행을 할 수 있는 권원을 의미한다."}],"num":171,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a172","label":"제172조","title":"준자치공간","paras":[{"k":"hang","x":"① 본회의 지배 · 관리하에 있지 않지만, 학교의 승인을 얻어 본회 회원의 자유로운 이용이 보장된 공간을 준자치공간이라고 한다."},{"k":"hang","x":"② 준자치공간은 다음 각호로 정한다."},{"k":"ho","x":"1. CJ법학관 남학생 휴게실"},{"k":"ho","x":"2. CJ법학관 여학생 휴게실"},{"k":"ho","x":"3. CJ법학관 및 해송법학도서관 라운지"},{"k":"ho","x":"4. CJ법학관 및 해송법학도서관 스터디룸"},{"k":"ho","x":"5. 법학관(구관), 법학관(신관), CJ법학관 강의실"},{"k":"ho","x":"6. 그 밖의 기타 학생 편의시설"}],"num":172,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a173","label":"제173조","title":"의무","paras":[{"k":"line","x":"본회는 자치공간에 대해 다음 각호의 의무가 있다."},{"k":"ho","x":"1. 자치공간에 대한 본회의 자치권이 침해받지 않도록 수호"},{"k":"ho","x":"2. 자치공간의 안전 및 청결 유지"},{"k":"ho","x":"3. 자치공간 이용과 관련한 갈등 해결"},{"k":"ho","x":"4. 회원의 자치공간 이용 기회보장"}],"num":173,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a174","label":"제174조","title":"자치공간운영세칙","paras":[{"k":"line","x":"그 밖의 자치공간에 관한 자세한 내용은 「자유전공학부 자치공간운영세칙」으로 정한다."}],"num":174,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제9장 회칙ㆍ세칙ㆍ규칙"},{"t":"h","lv":3,"text":"제１절 회칙 개정"},{"t":"art","id":"a175","label":"제175조","title":"개정안 발의","paras":[{"k":"hang","x":"① 회칙 개정안은 다음 각호 중 하나에 따라 발의된다."},{"k":"ho","x":"1. 학부운영위원회의 출석 과반수에 해당하는 발의"},{"k":"ho","x":"2. 학부운영위원회 재적 위원 과반수의 연서에 따른 발의"},{"k":"ho","x":"3. 회원 10분의 1의 연서에 따른 발의"},{"k":"hang","x":"② 연서에 따른 소집요구는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식을 준용하며, ｢고려대학교 총학생회 사무처리세칙｣에서 정한 사항이 포함되어야 한다."}],"num":175,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a176","label":"제176조","title":"개정안 공고","paras":[{"k":"line","x":"회칙 개정안이 발의되면 학부 학생회장은 다음 각호의 사항을 7일 이상 공고하여야 한다."},{"k":"ho","x":"1. 회칙 개정안의 제안이유와 주요 내용"},{"k":"ho","x":"2. 신ㆍ구조문 대비표"},{"k":"ho","x":"3. 제175조에 따른 회칙 개정안 발의자 명단"}],"num":176,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a177","label":"제177조","title":"개정안 심의","paras":[{"k":"hang","x":"① 제175조 제１항 제１호에 경우 회칙 개정을 위한 학생총회 또는 학생대표자회 개의에 앞서 학부운영위원회에서 개정안을 심의하거나, 별도의 공청회를 개최하여 개정안을 심의한다."},{"k":"hang","x":"② 개정안 심의 과정에는 축조심사와 찬반 토론이 포함되어야 한다."}],"num":177,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a178","label":"제178조","title":"개정 의결","paras":[{"k":"hang","x":"① 회칙 개정안이 발의되었을 때 본회 의결기구의 의장은 지체 없이 학생총회 또는 학생대표자회를 소집하여 회칙 개정안을 심의ㆍ의결한다."},{"k":"hang","x":"② 회칙 개정의 의결은 제23조 제３항에 따라 기명투표로 표결한다."},{"k":"hang","x":"③ 회칙 개정은 제30조 제２항 및 제57조에 따른다."}],"num":178,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a179","label":"제179조","title":"개정안 정리","paras":[{"k":"line","x":"회칙 개정의 의결이 있은 후 저촉되는 조항ㆍ자구ㆍ숫자 그 밖에의 기타 정리가 필요한 경우 학부운영위원회는 회칙 개정의 공포 전까지 이를 검토하여 정리할 수 있다. 단 정리로서 개정 의결된 회칙의 내용이나 취지를 변경하는 것은 허용되지 아니한다."}],"num":179,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a180","label":"제180조","title":"공포","paras":[{"k":"hang","x":"① 회칙 개정이 의결되면 학부 학생회장은 이를 지체 없이 공포한다."},{"k":"hang","x":"② 회칙의 공포문에는 다음 각호의 사항이 포함되어야 한다."},{"k":"ho","x":"1. 회칙 개정안의 제안이유와 주요 내용"},{"k":"ho","x":"2. 신ㆍ구조문 대비표"},{"k":"ho","x":"3. 제175조에 따른 회칙 개정안 발의자 명단"},{"k":"ho","x":"4. 회칙 개정 찬성자 명단"},{"k":"hang","x":"③ 본조는 세칙과 규칙의 제정ㆍ개정ㆍ폐지에도 준용한다. 단, 세칙 제정의 공포 시에는 세칙의 제정 순서에 따라 번호를 붙여서 공포하며, 규칙 제정의 공포 시에는 제정의 근거가 되는 세칙별로 규칙의 제정 순서에 따라 번호를 붙여서 공포한다."}],"num":180,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제２절 세칙ㆍ규칙"},{"t":"art","id":"a181","label":"제181조","title":"세칙ㆍ규칙","paras":[{"k":"hang","x":"① 본회는 회칙에 따라 세칙을 제정ㆍ개정하고, 세칙에 따라 규칙을 제정ㆍ개정한다. 단, 일반규칙은 세칙에 근거를 두지 않고 제정ㆍ개정할 수 있다."},{"k":"hang","x":"② 회칙에 위반되는 세칙과 세칙에 위반되는 규칙은 그 위반되는 부분에 한정하여 효력이 없다."},{"k":"hang","x":"③ 회칙에 위반되는 산하기구의 자치규칙은 성립하지 아니하고, 그 위반되는 부분에 한하여 효력이 없다."}],"num":181,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a182","label":"제182조","title":"세칙의 제정ㆍ개정ㆍ폐지","paras":[{"k":"hang","x":"① 세칙은 회칙에서 위임한 사항과 회칙을 시행하기 위한 사항을 정하기 위하여 제정한다."},{"k":"hang","x":"② 세칙은 학생총회 또는 학생대표자회가 제정ㆍ개정ㆍ폐지를 의결한다."},{"k":"hang","x":"③ 세칙의 제정ㆍ개정ㆍ폐지는 제175조에 따른다."},{"k":"hang","x":"④ 세칙 개정안의 정리에 관하여서는 제179조를 준용한다."}],"num":182,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a183","label":"제183조","title":"세칙에 부수된 규칙의 제정ㆍ개정ㆍ폐지","paras":[{"k":"hang","x":"① 세칙에 부수된 규칙은 해당 세칙에서 위임한 사항과 해당 세칙을 시행하기 위한 사항을 정하기 위하여 제정한다."},{"k":"hang","x":"② 세칙에 부수된 규칙은 해당 세칙의 근거 규정에 따라 제정ㆍ개정ㆍ폐지된다."}],"num":183,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a184","label":"제184조","title":"일반규칙의 제정ㆍ개정ㆍ폐지","paras":[{"k":"hang","x":"① 일반규칙은 다음 각호의 사항을 규율하기 위해 제정한다."},{"k":"ho","x":"1. 의결기구에 관한 사항"},{"k":"ho","x":"2. 집행기구에 관한 사항"},{"k":"ho","x":"3. 산하기구에 관한 사항"},{"k":"ho","x":"4. 독립기구에 관한 사항"},{"k":"ho","x":"5. 본회의 정기사업ㆍ비정기사업에 관한 사항"},{"k":"ho","x":"6. 회원의 권리ㆍ의무에 관한 사항"},{"k":"ho","x":"7. 자치단체에 관한 사항"},{"k":"ho","x":"8. 학교 시설 사용 등에 대한 회원 전체의 합의에 관한 사항"},{"k":"ho","x":"9. 학교 당국과의 합의에 관한 사항"},{"k":"ho","x":"10. 본회와 학내 각 단체 간의 합의에 관한 사항"},{"k":"ho","x":"11. 본회와 외부단체와의 합의에 관한 사항"},{"k":"ho","x":"12. 회칙의 특정 조문에 관한 추가적인 사항"},{"k":"ho","x":"13. 그 밖에 규칙으로 명문화하는 것이 필요하다고 인정되는 사항"},{"k":"hang","x":"② 일반규칙은 제40조 제３항에 따라 학부운영위원회가 제정ㆍ개정ㆍ폐지를 의결한다."}],"num":184,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제３절 해 석"},{"t":"art","id":"a185","label":"제185조","title":"회칙 해석의 원칙과 절차","paras":[{"k":"hang","x":"① 회칙을 해석ㆍ적용함에 있어서는 해당 조항의 문맥적 의미와 회칙 전체의 논리적 체계성에 비추어 본회의 민주적 운영이 저해되거나 회원의 권리가 부당하게 침해되지 않도록 주의하여야 한다."},{"k":"hang","x":"② 회칙의 해석이 필요한 경우 의결기구의 의장은 회칙해석위원회를 소집한다. 회칙해석위원회의 구성과 운영에 관한 절차는 제2장 제5절 학부운영위원회의 절차를 준용한다."},{"k":"hang","x":"③ 회칙해석위원회의 소집은 소집일로부터 3일 전에 공고되어야 하며, 이때 해석에 이견이 발생한 회칙 조항과 그 조항의 해석에 관한 각 측의 주장이 공개되어야 한다. 단, 긴급한 사항은 회칙해석위원 재적 3분의 2의 동의로 공고절차를 생략하고 즉시 진행할 수 있다."},{"k":"hang","x":"④ 회칙해석위원회 의장은 심의안건과 관련하여 필요할 때 혹은 위원의 요청이 있을 때 전문가를 위원회에 출석시켜 발언하게 하거나, 전문가 명의의 소명자료의 제출을 요청할 수 있다."},{"k":"hang","x":"⑤ 본회의 중요 사항과 회원의 권리ㆍ의무에 중대한 변화를 야기하는 회칙의 해석은 회원들을 상대로 의견을 수렴하기 위한 공청회를 개최할 수 있다."},{"k":"hang","x":"⑥ 회칙해석위원회가 조항에 대한 해석을 의결하면, 회의의 논의 과정과 해석 내용을 회칙 후단에 첨부하여 항상 회칙과 함께 열람할 수 있도록 하여야 한다."},{"k":"hang","x":"⑦ 세칙ㆍ규칙에 관하여서도 본조를 적용한다."}],"num":185,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"부칙","bu":true,"id":"bu1"},{"t":"free","paras":[{"k":"line","x":"이 회칙은 공포 후 2016년 10월 01일부터 시행한다."},{"k":"line","x":"이 회칙은 공포 후 2017년 6월 01일부터 시행한다. (2017. 5. 27. 개정)"},{"k":"line","x":"이 회칙은 공포 후 2018년 10월 20일부터 시행한다. (2018. 10. 12. 개정)"}]}],"note":null},{"id":"hoechik-20211113","date":"2021.11.13","kind":"전부개정","title":"고려대학교 자유전공학부 학생회칙","subtitle":null,"history":[["2009. 03.","제정"],["2011. 05. 11.","일부개정"],["2013. 10. 30.","일부개정"],["2014. 03. 26.","일부개정"],["2014. 09. 22.","일부개정"],["2015. 03. 24.","일부개정"],["2015. 09. 22.","일부개정"],["2016. 08. 29.","전부개정"],["2017. 03. 02.","일부개정"],["2017. 05. 27.","전부개정"],["2017. 08. 19.","전부개정"],["2018. 10. 12.","전부개정"],["2021. 11. 13.","전부개정"]],"pdf":"pdf/hoechik-20211113.pdf","pdfName":"고려대학교_자유전공학부_학생회칙(2021.11.13_전부개정).pdf","blocks":[{"t":"pre","title":"전문","paras":["정의를 추구하는 고려대학교의 역사적 사명과 함께 공동체를 선도하고 연대하는 자유전공학부는 창설 이래 이어져 온 민주적 전통과 자유·정의·진리를 좇는 본교의 교육 이념, 학문 및 사상에 대한 창조적 탐구 정신을 이어받아 자유전공학부의 주체적이고 자율적이며 민주적인 활동을 다짐하는 바이다. 이에 2009년 3월 제정되고 12차에 걸쳐 개정된 자유전공학부 학생회칙을 자유전공학부 학생대표자회의의 의결을 거쳐 개정한다."],"date":null},{"t":"h","lv":2,"text":"제1장 총칙"},{"t":"art","id":"a1","label":"제1조","title":"명칭","paras":[{"k":"line","x":"본회는 고려대학교 자유전공학부 학생회라 칭한다."}],"num":1,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a2","label":"제2조","title":"목적","paras":[{"k":"hang","x":"① 본회는 민주적이고 자율적인 학생자치활동을 통하여 회원 간의 결속을 강화하고 회원의 권익 신장을 도모하며 자유로운 진리의 탐구와 창조적이고 진보적인 대학문화의 건설을 추구하여 사회발전에 능동적으로 기여한다."},{"k":"hang","x":"② 본회는 시대의 불의에 맞서 사회적 연대를 구축하고 침해된 정의의 회복을 위해 대내외에서 주체적으로 행동한다."},{"k":"hang","x":"③ 본회는 본회의 자산 및 자치공간과 회원이 지닌 권리를 보호한다."},{"k":"hang","x":"④ 본회는 법률적 기초소양 및 다양한 영역에서의 복합적 전문성을 갖춘 공적 영역의 선도적 지도자를 양성한다는 교육목적을 달성하기 위해 노력하며, 제1전공이 다른 회원들 간의 교류를 장려한다."}],"num":2,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a3","label":"제3조","title":"위치","paras":[{"k":"line","x":"본회는 서울특별시 성북구 안암동 고려대학교 법학관(구관), 법학관(신관) 및 CJ법학관에 위치한다."}],"num":3,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a4","label":"제4조","title":"회원","paras":[{"k":"hang","x":"① 본회의 회원은 입학·재입학·편입학·소속변경 등으로 고려대학교 자유전공학부 소속이 된 자를 원칙으로 한다."},{"k":"hang","x":"② 졸업, 자퇴, 퇴학 등으로 고려대학교 서울캠퍼스 학부과정 소속이 아니게 된 자 및 총학생회 제명으로 인해 총학생회 회원 직을 박탈당한 자는 그 즉시 회원 자격을 잃으며 정학 등의 사유로 등교가 정지된 자는 그 기간 회원 자격이 정지된다."},{"k":"hang","x":"③ 제2항의 경우 회원의 자격이 부당하게 정지, 박탈된 자는 학부운영위원회의 출석 3분의 2 이상에 해당하는 결의로 회원 지위를 회복할 수 있다."},{"k":"hang","x":"④ 본회의 회원 중 재학 중인 자는 다음 각호의 기간 동안 본회의 정회원이 된다. 단, 재학 중 휴학 한 자는 그 즉시 정회원 자격을 상실하고 휴학생 회원이 된다."},{"k":"ho","x":"1. 1학기 재학생 : 1학기 개강일로부터 2학기 개강일 전일"},{"k":"ho","x":"2. 2학기 재학생 : 2학기 개강일로부터 이듬해 1학기 개강일 전일"},{"k":"hang","x":"⑤ 본회의 회원 중 휴학한 자는 휴학생 회원, 수료한 자는 수료생 회원이라고 하며, 선거권을 지닐 수 없다. 단, 휴학생 회원과 수료생 회원 중에서 다음 각호의 등록기간에 등록 절차를 이행한 자는 남은 기간 정회원이 된다. 자유전공학부 학부·반 학생회장단 선거의 특수성을 고려하여 선거 후보자 등록 마감일 다음 날부터 당선 공고일까지는 정회원 등록을 할 수 없다. 그 밖에 정회원 등록에 관한 사항은 규칙으로 정한다."},{"k":"ho","x":"1. 1학기 정회원 등록기간: 1학기 개강일부터 2학기 개강일 전날까지"},{"k":"ho","x":"2. 2학기 정회원 등록기간: 2학기 개강일부터 이듬해 1학기 개강일 전날까지"},{"k":"hang","x":"⑥ 본회의 회원 중에서 신입생 회원과 두 학번 이상 차이가 나는 회원은 고학번 회원이라고 한다."},{"k":"hang","x":"⑦ 본회의 회원 중에서 다음 각호에 해당하는 회원은 신입생 회원이라고 한다."},{"k":"ho","x":"1. 고려대학교에 입학한 지 2학기가 지나지 않은 회원"},{"k":"ho","x":"2. 편입학·소속변경 등으로 자유전공학부 재학생이 된 지 2학기가 지나지 않은 회원"},{"k":"hang","x":"⑧ 회원 여부에 시비가 있을 시 자유전공학부 학부운영위원회는 자유전공학부 행정실을 통해 확인한 재학생 명단, 휴학생 명단을 참고하여 회원 여부를 판단한다."}],"num":4,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a5","label":"제5조","title":"회원의 권리와 의무","paras":[{"k":"hang","x":"① 본회의 회원은 성별·연령·장애·병력·피부색·용모 등 신체조건, 인종·언어·출신국가·출신민족·출신지역 등 출생지, 혼인상태·출산형태 등 가족 형태, 종교·정치적견해·성적지향·성별정체성·출신학교·학력·전공·재산 등 사회적 신분에 의하여 차별을 받지 아니한다."},{"k":"hang","x":"② 본회의 회원은 본회의 모든 자치활동에 참여할 권리와 회칙에 근거한 선거권, 피선거권을 가진다."},{"k":"hang","x":"③ 본회의 회원은 회칙에 따라 본회의 활동과 운영 전반에 관하여 의견을 개진할 권리와 본회를 부인하거나 정당한 학생자치활동을 침해하는 것에 대해 저항할 권리를 가진다."},{"k":"hang","x":"④ 본회의 회원은 집회·결사의 자유 및 자유로운 종교·정치 활동에 대한 권리를 가진다."},{"k":"hang","x":"⑤ 본회의 회원은 본회의 모든 활동 및 재정 운영에 대해 보고를 받을 권리를 가진다."},{"k":"hang","x":"⑥ 본회의 회원은 본회가 지니는 급부를 적절한 시기에 제공받을 권리를 가진다."},{"k":"hang","x":"⑦ 본회의 회원은 자치공간 및 본회 자산을 향유할 권리를 가진다."},{"k":"hang","x":"⑧ 본회의 회원은 회칙을 준수할 의무를 지닌다."},{"k":"hang","x":"⑨ 본회의 회원은 본회가 결정한 사항을 준수할 의무를 지닌다."},{"k":"hang","x":"⑩ 본회의 회원은 회비를 납부할 의무를 지닌다."},{"k":"hang","x":"⑪ 본회의 회원은 본회의 자산을 보호할 의무를 지닌다."}],"num":5,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a6","label":"제6조","title":"본회와 각 기구의 의무","paras":[{"k":"hang","x":"① 본회와 본회의 각 기구는 고학번 회원의 본회와 본회의 각 기구 활동 참여를 보장해야 하며, 회원 간 원활한 교류를 위해 노력해야 한다."},{"k":"hang","x":"② 본회와 본회의 각 기구는 신입생 회원이 학번·연령으로 인해 부당한 대우를 받지 않도록 노력해야 한다."},{"k":"hang","x":"③ 본회와 본회의 각 기구는 전조에 열거된 회원의 권리가 대내외적으로 침해받지 않도록 항상 노력하여야 하며, 회원의 권리가 침해될 때 이를 적극적으로 수호하여야 한다."},{"k":"hang","x":"④ 본회와 본회의 각 기구는 본회와 각 기구의 자산 및 자치공간을 보호·관리하여야 한다."}],"num":6,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a7","label":"제7조","title":"구성","paras":[{"k":"line","x":"본회는 민주적이고 효율적인 운영을 통한 학생자치의 실현을 위하여 다음 각호의 의결기구, 집행기구, 산하기구, 독립기구를 둔다."},{"k":"ho","x":"1. 의결기구: 학생총회, 학생대표자회, 학부운영위원회, 비상대책위원회"},{"k":"ho","x":"2. 집행기구: 학부 학생회장단, 집행위원회"},{"k":"ho","x":"3. 산하기구: 반 학생회, 자치단체, 특별위원회"},{"k":"ho","x":"4. 독립기구: 선거관리위원회, 투표관리위원회, 학생자치장학금위원회, 학생홍보대사, 소수자인권위원회"}],"num":7,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a8","label":"제8조","title":"학교운영 참여","paras":[{"k":"hang","x":"① 본회의 활동과 관련하여 학교 당국과의 협의 또는 조정이 필요한 경우 본회의 각 기구는 학교운영에 적극적으로 참여하며 필요 시 학교 당국에 자료제출을 요청할 수 있다."},{"k":"hang","x":"② 본회는 다음 각호의 경우 학교의 운영에 적극 참여하여 의견을 개진하고 관련 진행 상황 및 결정 사항을 회원에게 공고하여야 한다."},{"k":"ho","x":"1. 본회의 활동과 관계된 회원의 징계 사항에 관해 회원을 변호할 필요가 있는 경우"},{"k":"ho","x":"2. 본회의 회원의 자치활동과 권익 보호가 필요한 경우"},{"k":"ho","x":"3. 자유전공학부 발전 방향 설정, 학제개편, 학칙개정 등의 임박하거나 이미 결정된 학교의 정책 및 결정사항이 본회 회원의 이익에 중대한 변화를 야기할 경우"},{"k":"ho","x":"4. 그 밖에 본회의 목적과 관련된 중요 사항"}],"num":8,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a9","label":"제9조","title":"대표자의 책임","paras":[{"k":"line","x":"학생회장단, 학부운영위원, 학생대표자회 대의원은 본회의 대표자로서 본회의 민주적이고 효율적인 운영과 각 기구의 협력을 통해 그 운영 목적을 달성할 수 있도록 주어진 역할을 책임 있게 수행하여야 한다."}],"num":9,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a10","label":"제10조","title":"겸직 금지","paras":[{"k":"hang","x":"① 본회의 회원은 다음 각호의 직을 동시에 2개 이상 가질 수 없다."},{"k":"ho","x":"1. 학부 학생회장과 부학생회장"},{"k":"ho","x":"2. 반 학생회장과 부학생회장"},{"k":"ho","x":"3. 고학번 대표 및 신입생 대표"},{"k":"ho","x":"4. 각 자치단체장"},{"k":"ho","x":"5. 그 밖에 학부운영위원 자격이 부여되는 직책"},{"k":"hang","x":"② 집행위원은 반 학생회장의 직을 겸직하기 위해서는 학생대표자회의 출석 과반수에 해당하는 결의로 인준을 받아야 한다."},{"k":"hang","x":"③ 제１항 각호의 직을 동시에 2개 이상 갖게 되었을 시 즉시 마지막에 갖게 된 직을 제외한 나머지 직에서는 해임된 것으로 본다. 단, 제1항 제1호의 직은 선후관계를 불문하고 그 직을 유지하는 것으로 본다."}],"num":10,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a11","label":"제11조","title":"사무 처리","paras":[{"k":"hang","x":"① 본회 각 기구의 사무 처리는 간소화·표준화·정보화를 통해 효율적으로 이루어져야 한다."},{"k":"hang","x":"② 정확과 신속을 기하고 책임의 소재를 명백히 밝히기 위하여 본회의 사무 처리와 대표자의 행위는 문서로써 함을 원칙으로 한다."},{"k":"hang","x":"③ 본회에서 장기간에 걸쳐 반복적으로 사용하는 문서로서 정형화할 수 있는 문서는 특별한 사유가 없으면 서식으로 정하여 사용한다."},{"k":"hang","x":"④ 회칙에서 공고하도록 한 사항은 회원들이 해당 공고를 쉽게 접할 수 있도록 구법학관 자유전공학부 학생회 게시판, 신법학관 자유전공학부 행정실 게시판 등 오프라인 게시판과, 자유전공학부 홈페이지 학생회 게시판 등 각종 온라인 게시판에 게시하여야 하며, 가시성이 확보되도록 공고의 모양을 정하여야 한다."},{"k":"hang","x":"⑤ 그 밖에 사무 처리에 관한 세부적인 사항은 학부운영위원회의 출석 과반수에 해당하는 결의로 ｢고려대학교 총학생회 사무처리세칙｣을 준용한다."}],"num":11,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a12","label":"제12조","title":"기록물 관리","paras":[{"k":"hang","x":"① 본회의 모든 활동은 기록되고, 기록물이 각 활동의 근거가 되는 것을 원칙으로 한다."},{"k":"hang","x":"② 본회는 지속적이고 체계적인 기록물 관리를 위해 적극 노력해야 하며, 기록물 관리기관이 효율적으로 기록물을 관리할 수 있도록 지원해야 한다."},{"k":"hang","x":"③ 기록물의 생산·수집 이후에는 임의로 수정할 수 없으며 훼손하거나 폐기할 수 없다. 단, 각호에 해당하는 경우 각호에서 정한 목적의 제한된 범위 내에서 게시물을 수정할 수 있다."},{"k":"ho","x":"1. 속기록의 내용이 실제 발언과 부합하지 않은 것을 7일 이내에 발견했을 시"},{"k":"ho","x":"2. 학생회 페이지, 그룹, 자유전공학부 홈페이지 게시판 등에 올린 게시물의 탈·오자 수정이 필요할 시"},{"k":"ho","x":"3. 학생회 페이지, 그룹, 자유전공학부 홈페이지 게시판 등에 올린 게시물의 내용에 중대한 하자를 발견하여 하자의 치유를 위한 수정 및 비공개 조치가 필요할 시"},{"k":"ho","x":"4. 같은 시각에 중복게시물을 올려 비공개 조치가 필요할 시"},{"k":"hang","x":"④ 본회가 생산·수집하는 모든 기록물은 회원들에게 공개되어야 하고 본회의 행정 사무와 의사 결정, 학술 연구 등의 활동을 위해 언제든지 참고할 수 있도록 투명하게 관리되어야 한다."},{"k":"hang","x":"⑤ 본회는 회원의 개인정보를 보호해야 할 의무가 있다. 본회가 수집한 개인정보는 당사자의 동의를 얻었거나 명확한 근거를 가진 정당한 목적이 있을 때만 열람·활용할 수 있다."},{"k":"hang","x":"⑥ 본회의 회원 또는 학술적 목적과 공익을 위해 본회의 기록물을 활용하려는 자는 본회의 모든 기록물에 대한 접근권이 있으며 정보공개청구로 기록물을 열람·활용할 수 있다."},{"k":"hang","x":"⑦ 본회의 각 기구는 본회의 회원 또는 학술적 목적과 공익을 위해 본회의 기록물을 활용하려는 자의 정보공개청구를 거부할 수 없다. 단, 다음 각호에 해당할 때는 학부운영위원회의 출석 과반수에 해당하는 결의로 일부만 공개하도록 할 수 있다."},{"k":"ho","x":"1. 본회의 회원이 아닌 자가 정보공개를 청구한 때"},{"k":"ho","x":"2. 정보의 공개로 인해 특정 회원의 개인정보 유출이 우려될 때"},{"k":"ho","x":"3. 정보의 공개가 본회 회원의 이익의 심각한 감소를 초래할 때"},{"k":"ho","x":"4. 기타 공익적 목적이 있을 때"},{"k":"hang","x":"⑧ 그 밖에 기록물 관리에 관한 세부적인 사항은 학부운영위원회의 출석 과반수에 해당하는 결의로 ｢고려대학교 총학생회 기록물관리세칙｣을 준용한다."}],"num":12,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a13","label":"제13조","title":"준용","paras":[{"k":"hang","x":"① 본회는 본회의 상위기구의 회칙, 세칙 및 규칙을 준용할 수 있다."},{"k":"hang","x":"② 제1항에 해당하는 결정은 준용에 관해 특별한 요건이 없는 경우, 학생총회의 출석 과반수, 학생대표자회의 출석 과반수 또는 학부운영위원회의 출석 과반수에 해당하는 결의로 한다."}],"num":13,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a14","label":"제14조","title":"세칙","paras":[{"k":"line","x":"본회는 회칙에 의거해 세칙을 제정 및 개정한다."}],"num":14,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제2장 의결기구"},{"t":"h","lv":3,"text":"제１절 통칙"},{"t":"art","id":"a15","label":"제15조","title":"기본이념","paras":[{"k":"line","x":"본회의 의결기구는 본회를 대표하는 의사를 결정하는 기구로서 민주적이고 공정하며 효율적인 절차에 따라 운영되어야 한다."}],"num":15,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a16","label":"제16조","title":"의결기구의 위계","paras":[{"k":"hang","x":"① 본회의 의결기구는 학생총회, 학생대표자회, 학부운영위원회 순으로 위계를 지닌다."},{"k":"hang","x":"② 다른 위계에 속한 의결기구 간의 의사결정 내용이 상이할 시 하위 의결기구의 의사결정 내용은 상위 의결기구의 의사결정 내용과 합치되는 범위 내에서 효력을 지닌다."},{"k":"hang","x":"③ 하위 의결기구에서 의결할 수 있도록 한 사항은 해당 의결기구보다 상위 의결기구에서도 의결할 수 있다."}],"num":16,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a17","label":"제17조","title":"회기","paras":[{"k":"line","x":"본회 의결기구의 회기는 다음 각호의 기간으로 나눈다."},{"k":"ho","x":"1. 제1회기: 2학기 종강일 다음 날부터 1학기 개강일 전날까지"},{"k":"ho","x":"2. 제2회기: 1학기 개강일부터 1학기 종강일까지"},{"k":"ho","x":"3. 제3회기: 1학기 종강일 다음 날부터 2학기 개강일 전날까지"},{"k":"ho","x":"4. 제4회기: 2학기 개강일부터 2학기 종강일까지"}],"num":17,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a18","label":"제18조","title":"의장","paras":[{"k":"hang","x":"① 본회 의결기구의 의장은 학부 학생회장으로 함을 원칙으로 한다. 단, 학부 학생회장 사고 시 학부 부학생회장이 그 직을 대신하며, 학부 학생회장과 학부 부학생회장이 모두 사고이거나, 학부 학생회장단 모두 또는 그중 한 명에 대한 탄핵 안건, 탄핵안 학생총투표 발의 안건이 상정된 경우 또는 기타 학부 학생회장단의 신상과 밀접한 관련이 있는 경우 학생회장단을 제외한 학부운영위원 중 한 명이 그 직을 대신한다."},{"k":"hang","x":"② 의장은 본회 의결기구를 대표하고 의사를 정리하며 질서를 유지하고 사무를 감독한다."},{"k":"hang","x":"③ 의장은 본회 절차에 따라 공정하고 효율적으로 회의를 진행하여야 한다."}],"num":18,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a19","label":"제19조","title":"사무·재정","paras":[{"k":"hang","x":"① 의결기구의 사무 처리는 집행위원회가 담당하며 학부운영위원회는 집행기구의 원활한 사무 처리를 감시·감독할 의무를 지닌다."},{"k":"hang","x":"② 본회는 의결기구의 원활한 운영을 위한 재원을 마련해야 한다."},{"k":"hang","x":"③ 집행위원회는 속기의 방법으로 회의록을 작성하고 다음 사항을 기재해야 한다."},{"k":"ho","x":"1. 회의 장소"},{"k":"ho","x":"2. 개회, 회의 중지와 산회의 일시"},{"k":"ho","x":"3. 개회 당시와 안건 의결 당시의 출석 대의원 명단"},{"k":"ho","x":"4. 부의 안건의 제목 및 내용"},{"k":"ho","x":"5. 발언자와 의사 표명의 내용"},{"k":"ho","x":"6. 표결 결과 (기명투표의 경우 각 대의원의 표결 사항을 기재)"},{"k":"ho","x":"7. 의장 또는 각 의결기구가 필요하다고 인정하는 사항"},{"k":"hang","x":"④ 의장은 개의일로부터 3일 이내에 제3항의 회의록을 공개하고 회의결과를 공고함을 원칙으로 한다. 단, 필요한 경우 그 기한을 7일까지 연장할 수 있다."}],"num":19,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a20","label":"제20조","title":"긴급한 사항","paras":[{"k":"hang","x":"① “긴급한 사항”이란 회의 소집 과정을 생략해서라도 긴급하게 의사를 결정해야 할 사항을 의미한다."},{"k":"hang","x":"② 긴급한 사항에 대한 해석은 각호의 목적 사항으로 제한한다."},{"k":"ho","x":"1. 본회의 활동과 관계된 회원의 징계 사항에 관해 변호가 필요할 경우"},{"k":"ho","x":"2. 본회 회원의 이익에 중대한 변화를 야기하는 자유전공학부 발전 방향 설정, 학제개편, 학칙개정 등의 학교 결정이 임박해 있거나 이미 결정된 경우"},{"k":"ho","x":"3. 그 밖에 본회의 목적과 관련된 중요 사항"},{"k":"hang","x":"③ 긴급한 사항이 있을 시 본회 의결기구 의장의 소집요구 없이도 학부운영위원회의 출석 과반수에 해당하는 결의로 임시학생총회 또는 임시학생대표자회를 소집할 수 있다."}],"num":20,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a21","label":"제21조","title":"안건의 발의","paras":[{"k":"hang","x":"① 안건 발의는 각 의결기구에서 정한 발의 요건에 따른다."},{"k":"hang","x":"② 안건 발의는 소집요구와 함께 이루어져야 한다. 단, 소집공고부터 산회 전까지 발의된 추가 안건에 대해서는 재적 구성원 과반수의 출석과 출석 구성원 과반수에 해당하는 결의로 한다."}],"num":21,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a22","label":"제22조","title":"안건의 의결","paras":[{"k":"hang","x":"① 각 의결기구의 재적 구성원 과반수의 출석과 출석 구성원 과반수에 해당하는 결의로 안건을 의결한다. 가부동수 및 찬성이 과반에 미치지 못할 경우 부결된 것으로 본다."},{"k":"hang","x":"② 안건의 의결 시 의결요건을 정하는 기준이 되는 출석 구성원 수는 각 안건의 의결 당시 집계된 구성원 명단을 기준으로 계산한다."},{"k":"hang","x":"③ 의결기구의 의결권은 구성원이 평등하게 가지며 직접 출석하여 행사하여야 한다."}],"num":22,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a23","label":"제23조","title":"안건의 표결","paras":[{"k":"hang","x":"① 표결은 기명으로 함을 원칙으로 한다."},{"k":"hang","x":"② 중요한 안건으로써 의장 또는 회원이 제의하고 의결기구 재적 구성원 3분의 2 이상에 해당하는 결의가 있으면 무기명으로 표결할 수 있다."},{"k":"hang","x":"③ 다음 각호의 사항에 관한 의결은 반드시 기명투표로 표결하여야 한다."},{"k":"ho","x":"1. 제40조 제１항의 회칙 개정에 관한 사항"},{"k":"ho","x":"2. 제40조 제２항의 세칙 제정·개정·폐지에 관한 사항"},{"k":"hang","x":"④ 다음 각호의 사항에 관한 의결은 반드시 무기명투표로 표결하여야 한다."},{"k":"ho","x":"1. 제35조 학부 학생회장단 탄핵에 관한 사항"},{"k":"ho","x":"2. 제36조 제2항 집행위원 해임에 관한 사항"},{"k":"ho","x":"3. 제39조 제1항 및 제２항의 학부 학생회비 지급에 관한 사항"},{"k":"hang","x":"⑤ 의장은 안건에 대한 이의의 유무를 물어서 이의가 없다고 인정한 때에는 가결되었음을 선포할 수 있다. 그러나 이의가 있는 안건일 경우 또는 무기명표결을 요하는 안건의 경우 반드시 표결하여야 한다."},{"k":"hang","x":"⑥ 의장 또는 회원의 제의와 출석 과반수의 찬성으로 전자투표에 의한 기록표결을 시행할 수 있다."}],"num":23,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a24","label":"제24조","title":"방청·발언권","paras":[{"k":"hang","x":"① 본회의 회원은 각 의결기구를 방청할 수 있다."},{"k":"hang","x":"② 본회의 회원은 각 의결기구에서 발언할 수 있는 권리를 가진다."},{"k":"hang","x":"③ 의장은 질서 유지 및 효율적인 의사 진행을 위해 방청인 수를 제한하거나 회원의 발언권을 제한할 수 있으며, 회의장 안의 질서를 현저히 방해하는 방청인의 경우 퇴장을 명할 수 있다."},{"k":"hang","x":"④ 의결기구의 구성원석과 방청인석은 구분이 되도록 배치한다."}],"num":24,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a25","label":"제25조","title":"회의진행세칙","paras":[{"k":"line","x":"그 밖에 의결기구의 회의 진행에 관한 사항은 각 의결기구의 출석 과반수에 해당하는 결의로 ｢고려대학교 총학생회 회의진행세칙｣을 준용한다."}],"num":25,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제２절 학생총회"},{"t":"art","id":"a26","label":"제26조","title":"지위 및 구성","paras":[{"k":"line","x":"학생총회는 본회의 최고의결기구로 본회의 회원 전원으로 구성한다."}],"num":26,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a27","label":"제27조","title":"소집요건","paras":[{"k":"hang","x":"① 학생총회 임시회는 다음 각호 중 하나에 의해 의장이 소집한다."},{"k":"ho","x":"1. 학부운영위원회의 소집요구"},{"k":"ho","x":"2. 학생대표자회의 소집요구"},{"k":"ho","x":"3. 회원 50명 이상의 연서에 따른 소집요구"},{"k":"ho","x":"4. 제90조에 따라 발의된 학부 학생회장단 사퇴 허가 요청"},{"k":"ho","x":"5. 제91조에 따른 학부 학생회장단 탄핵 발의"},{"k":"ho","x":"6. 제175조에 따른 회칙 개정안 발의"},{"k":"hang","x":"② 연서에 따른 소집요구는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식에 의하여야 하며, ｢고려대학교 총학생회 사무처리세칙｣에서 정한 사항이 포함되어야 한다."},{"k":"hang","x":"③ 연서에 따른 소집요구가 있으면 학부운영위원회는 지체 없이 학생총회 개의일을 결정한다. 이때 개의일은 소집요구 서식에 기재된 개의 희망일로 함을 원칙으로 하되 변경할 때는 학부운영위원의 출석 3분의 2 이상에 해당하는 결의로 한다. 단, 이 경우에도 개의 희망일과 2주 이상 차이가 나서는 안 된다."}],"num":27,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a28","label":"제28조","title":"소집 공고","paras":[{"k":"hang","x":"① 학생총회 의장은 학생총회의 소집을 개의일 7일 전에 공고하여야 한다."},{"k":"hang","x":"② 공고문에는 다음 각호의 사항을 명시하여야 한다."},{"k":"ho","x":"1. 회의 시작 일시"},{"k":"ho","x":"2. 회의 장소"},{"k":"ho","x":"3. 안건과 안건에 대한 설명"}],"num":28,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a29","label":"제29조","title":"자료의 사전 배포","paras":[{"k":"line","x":"학생총회 의장은 학생총회 회의 개의 5일 전까지 제출된 안건과 그에 관한 설명, 집행위원회 등의 보고·인준 사항, 각 기구의 학생회비 예산안·결산 등이 포함된 자료집을 회원들을 대상으로 배포하여야 한다. 배포는 책자 형태로 제작하여 비치하는 방법과 전산화된 형태의 문서로 제작하여 온라인에 게시하는 방법으로 한다."}],"num":29,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a30","label":"제30조","title":"개의·의결요건","paras":[{"k":"hang","x":"① 학생총회는 회원 7분의 1 이상의 출석으로 개의하고, 출석 과반수에 해당하는 결의로 의결한다."},{"k":"hang","x":"② 다음 각호의 사항은 재적 회원 7분의 1 이상의 출석 및 출석 회원 3분의 2 이상에 해당하는 결의로 의결한다."},{"k":"ho","x":"1. 제35조의 학부 학생회장단 탄핵안에 관한 사항"},{"k":"ho","x":"2. 제39조 제３항의 학부 학생회비 인상·인하에 관한 사항"},{"k":"ho","x":"3. 제40조 제１항의 회칙 개정에 관한 사항"},{"k":"hang","x":"③ 본회는 학생총회의 개의 7일 전까지 7일 이상의 인권침해사건 신고 기간을 두고, 본회 회원을 대상으로 한 인권침해 사건이 있었는지 조사하여야 한다."}],"num":30,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a31","label":"제31조","title":"안건","paras":[{"k":"hang","x":"① 학생총회의 안건은 다음 각호의 방법으로 상정할 수 있다."},{"k":"ho","x":"1. 학부운영위원회의 출석 과반수에 해당하는 결의"},{"k":"ho","x":"2. 학생대표자회의 출석 과반수에 해당하는 결의"},{"k":"ho","x":"3. 회원 50명 이상의 연서에 따른 임시회의 소집요구와 함께 발의"},{"k":"ho","x":"4. 제90조에 따라 발의된 학부 학생회장단 사퇴 허가 요청"},{"k":"ho","x":"5. 제91조에 따른 학부 학생회장단 탄핵 발의"},{"k":"ho","x":"6. 제175조에 따른 회칙 개정안 발의"},{"k":"hang","x":"② 학생총회는 다음 각호의 안건을 심의·의결한다."},{"k":"ho","x":"1. 학부운영위원회가 소집요구와 함께 상정한 안건"},{"k":"ho","x":"2. 회원 50명 이상의 연서에 따른 소집요구와 함께 발의된 안건"},{"k":"ho","x":"3. 제90조에 따라 발의된 학부 학생회장단 사퇴 허가 안건"},{"k":"ho","x":"4. 제91조에 따른 학부 학생회장단 탄핵 안건"},{"k":"ho","x":"5. 제36조 제2항에 따른 집행위원 해임 안건"},{"k":"ho","x":"6. 제175조에 따라 발의된 회칙 개정안건"},{"k":"ho","x":"7. 본회의 활동에 필요한 각종 세칙 제정·개정안건"},{"k":"ho","x":"8. 회비의 인상·인하에 관한 안건"},{"k":"ho","x":"9. 본회의 사업계획과 정책의 기본방향에 대한 논의 안건"},{"k":"ho","x":"10. 본회의 예산·결산의 심의 및 승인에 관한 안건"},{"k":"ho","x":"11. 본회의 회계 및 사업 전반에 대한 감사에 관한 안건"},{"k":"ho","x":"12. 학생활동 및 학생신분에 관한 학칙 개정 요구안에 관한 안건"},{"k":"ho","x":"13. 제36조 제1항에 따른 집행위원장 및 집행위원 인준에 관한 안건"},{"k":"ho","x":"14. 회원 전체 명의로 소송을 진행할 경우 해당 소송에 관한 안건"},{"k":"ho","x":"15. 자유전공학부의 자치공간과 기타물품 회수 및 분배에 관한 안건"},{"k":"ho","x":"16. 학생총투표 실시 및 안건 상정에 관한 안건"},{"k":"ho","x":"17. 의결기구 산하의 특별위원회 설립에 관한 안건"},{"k":"ho","x":"18. 제107조에 따른 자치단체 인준에 관한 안건"},{"k":"ho","x":"19. 제169조 제4항 및 제5항에 의한 징계에 관한 안건"},{"k":"hang","x":"③ 학생총회는 본회를 폐지하는 결의를 할 수 없다."}],"num":31,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a32","label":"제32조","title":"안건 위임","paras":[{"k":"hang","x":"① 학생총회는 회기 중 처리하지 못한 안건은 출석 인원의 3분의 2 이상의 찬성으로 학생대표자회의에 위임할 수 있다. 단, 학생총회가 개의되지 않아 처리하지 못한 안건은 자동으로 학생대표자회에 위임된다."},{"k":"hang","x":"② 제31조 제2항 제4호, 제35조에서 규정하고 있는 학부 학생회장단 탄핵 안건은 하위기구로 위임할 수 없으며, 학생총회에 의하지 않고서는 오직 학생총투표로서만 처리할 수 있다."}],"num":32,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a33","label":"제33조","title":"결정·집행 사항 변경에 관한 사항","paras":[{"k":"line","x":"학생총회는 산하 학부·반 운영위원회, 학부·반 학생회장단과 학부·반 집행위원회의 결정·집행 사항을 변경 또는 취소할 수 있다."}],"num":33,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a34","label":"제34조","title":"학부 학생회장단 사퇴 허가에 관한 사항","paras":[{"k":"line","x":"학생총회는 학부 학생회장 또는 학부 부학생회장이 제90조에 따라 사퇴의 허가를 요청할 때 허가 여부를 심의·의결한다."}],"num":34,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a35","label":"제35조","title":"학부 학생회장단 탄핵에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 학부 학생회장단에 대한 탄핵안이 상정될 경우 학부 학생회장단에 대한 탄핵을 결정할 수 있다."},{"k":"hang","x":"② 학생총회는 학생회장단 탄핵과 관련된 절차가 준수되었는지, 탄핵 이유가 사실에 기반하고 있는지 성실히 심사할 의무를 지닌다."},{"k":"hang","x":"③ 학생총회는 출석 3분의 2 이상에 해당하는 결의로 학부 학생회장단 탄핵 결정 대신 동일 안건을 학생총투표 안건으로 상정할 수 있다."},{"k":"hang","x":"④ 학부 학생회장단 탄핵안 발의에 관한 절차는 제91조를 따른다."}],"num":35,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a36","label":"제36조","title":"집행위원회에 관한 사항","paras":[{"k":"hang","x":"① 집행위원회는 다음 각호의 사항에 관하여 학부운영위원회의 사전 인준을 거친 후 학생총회에 보고하여 인준받아야 한다. 단, 제２호와 제３호의 사항에 관하여 학부운영위원회의 사전 인준이 있으면 해당 안건을 학생총회에서 심의하기 전까지 해당 결정은 효력을 지닌다."},{"k":"ho","x":"1. 사업계획과 정책의 기본방향"},{"k":"ho","x":"2. 집행위원장과 집행위원의 임명"},{"k":"ho","x":"3. 산하 국서의 신설·폐지와 변경"},{"k":"hang","x":"② 학생총회는 집행위원의 해임을 의결할 수 있다."}],"num":36,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a37","label":"제37조","title":"감사에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 본회 집행기구, 산하기구, 독립기구의 사업 전반에 대하여 감사를 시행할 수 있다."},{"k":"hang","x":"② 학생총회는 감사에 필요하다고 인정될 때 해당 기구의 대표자 혹은 사업담당자를 출석시켜 진술을 청취할 수 있다. 또한, 관련 자료의 제출을 요구할 수 있다."},{"k":"hang","x":"③ 학생총회는 특정 집행기구, 산하기구의 감사를 목적으로 하는 감사위원회를 학생총회 산하에 설치할 수 있다. 감사위원회는 학생총회의 결정에 따라 감사 활동을 진행한 후 그 결과를 우선적으로 학부운영위원회에 보고한 후, 학생총회에 최종 보고하여야 한다."}],"num":37,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a38","label":"제38조","title":"징계에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 회원, 집행위원, 학부운영위원회 위원, 학생대표자회 대의원, 독립기구 및 산하기구가 본 회칙·세칙·규칙을 위반할 때 징계할 수 있다."},{"k":"hang","x":"② 회원의 징계에 대한 자세한 사항은 ｢고려대학교 자유전공학부 징계 세칙｣을 따른다."}],"num":38,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a39","label":"제39조","title":"재정에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 학부운영위원회의 심의를 거친 학부·반 학생회비 예산안·결산을 심의하여 승인한다."},{"k":"hang","x":"② 학생총회는 제1항의 심의에서 불승인된 기구에는 제163조에 따라 해당 학기의 학부 학생회비를 지급하지 않거나 지급을 보류하도록 결정할 수 있다. 그 밖에 자세한 사항은 ｢총학생회 재정운용세칙｣을 따른다."},{"k":"hang","x":"③ 학생총회는 학부학생회비의 인상·인하를 결정할 수 있다."}],"num":39,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a40","label":"제40조","title":"회칙·세칙·규칙에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 회칙을 개정할 수 있다."},{"k":"hang","x":"② 학생총회는 세칙을 제정·개정·폐지할 수 있다."},{"k":"hang","x":"③ 학생총회는 규칙·자치규칙이 회칙·세칙에 부합하는지 여부에 대해 심사할 수 있으며, 출석 과반수에 해당하는 결의로 부합하지 않다고 의결할시, 회칙·세칙에 반하는 규칙·자치규칙은 의결 즉시 효력이 부인된다."}],"num":40,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a41","label":"제41조","title":"대외활동에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 본회 차원의 상설적 연대 단체 가입·탈퇴에 대한 동의권을 가진다."},{"k":"hang","x":"② 회원 전체의 명의로 소송을 진행할 필요가 있는 문제가 발생할 때 학생총회는 학부운영위원회에 소송권을 위임할 수 있다."}],"num":41,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a42","label":"제42조","title":"재소집","paras":[{"k":"line","x":"학생총회의 개의가 불가하거나 논의를 마치지 못하고 산회한 경우 의장의 재량에 따라 10일 이내에 재소집할 수 있다."}],"num":42,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제３절 학생총투표"},{"t":"art","id":"a43","label":"제43조","title":"지위","paras":[{"k":"line","x":"학생총투표를 통한 의결은 학생총회의 의결과 같은 효력이 있다."}],"num":43,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a44","label":"제44조","title":"투표권","paras":[{"k":"line","x":"정회원은 학생총투표의 투표권이 있다."}],"num":44,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a45","label":"제45조","title":"투표관리위원회","paras":[{"k":"hang","x":"① 투표관리위원회는 학부운영위원 및 제63조 제4항에 의해 의결권을 가질 수 있는 자 전원으로 구성한다. 단, 학부 학생회장단은 제60조에 따른 학부 학생회장단 탄핵안에 대한 학생총투표에 대해서는 투표관리위원이 될 수 없다."},{"k":"hang","x":"② 투표관리위원회는 학생총투표와 관련된 모든 업무를 총괄한다."},{"k":"hang","x":"③ 집행위원장 및 집행위원회는 투표관리위원회의 결정에 따라 학생총투표 시행준비를 성실히 보조한다."},{"k":"hang","x":"④ 그 밖에 투표관리위원회에 관한 사항은 투표관리위원회의 출석 과반수에 해당하는 결의로 ｢고려대학교 총학생회 선거시행세칙｣의 선거관리위원회에 관한 규정을 준용할 수 있다."}],"num":45,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a46","label":"제46조","title":"성립·의결요건","paras":[{"k":"hang","x":"① 학생총투표의 개시는 학생총회 또는 학생대표자회의 출석 과반수에 해당하는 결의로만 가능하다."},{"k":"hang","x":"② 학생총투표는 정회원 4분의 1 이상의 투표로 성립하고, 유효투표의 과반수 찬성으로 의결한다."},{"k":"hang","x":"③ 성립 여부를 판단하기 위한 투표율의 계산은 명부상 총 투표자 수를 기준으로 한다."}],"num":46,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a47","label":"제47조","title":"시행","paras":[{"k":"line","x":"학생총투표는 학생총회 혹은 학생대표자회의 시행 결정에 따라 투표관리위원장이 시행한다."}],"num":47,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a48","label":"제48조","title":"시행 공고","paras":[{"k":"hang","x":"① 학생총회 의장은 학생총투표의 시행을 시행 7일 전에 공고하여야 한다."},{"k":"hang","x":"② 공고문에는 다음 각호의 사항을 명시하여야 한다."},{"k":"ho","x":"1. 학생총투표 시행 일시"},{"k":"ho","x":"2. 학생총투표 투표소 설치 장소"},{"k":"ho","x":"3. 안건과 안건에 대한 설명"}],"num":48,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a49","label":"제49조","title":"투표 기간","paras":[{"k":"hang","x":"① 투표 기간은 3일의 범위에서 투표관리위원회가 정한다."},{"k":"hang","x":"② 투표 기간이 종료하였음에도 투표율이 25%를 넘지 않았으면 투표관리위원회의 결정에 따라 투표 기간을 2일의 범위에서 1회 연장할 수 있다."}],"num":49,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a50","label":"제50조","title":"투표 방법","paras":[{"k":"hang","x":"① 투표는 기표방법으로 함을 원칙으로 한다."},{"k":"hang","x":"② 회원들의 쉬운 투표 참여 혹은 부재중인 자의 투표 참여를 위하여 우편, 온라인, 모바일 그 밖에 특수한 투표방법을 병행할 수 있다. 특수한 투표방법에 대한 결정은 투표관리위원회의 출석 3분의 2 이상에 해당하는 결의로 한다."},{"k":"hang","x":"③ 특수한 투표방법의 시행 여부, 대상, 방식, 운영 등에 관하여서는 ｢자유전공학부 선거시행세칙｣의 특수한 투표방법에 대한 규정을 준용한다."}],"num":50,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a51","label":"제51조","title":"결과 공고","paras":[{"k":"line","x":"학생총투표가 종료되어 개표가 완료되면 개표종료 시부터 24시간 이내에 투표관리위원회가 투표율과 결과를 공고한다. 이때 최종 투표율은 총투표용지 수를 기준으로 계산한다."}],"num":51,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a52","label":"제52조","title":"무효처리","paras":[{"k":"hang","x":"① 한 투표소의 명부상 투표자 수와 투표함의 투표용지 수의 차이가 명부상 투표자 수 대비 5%를 넘으면 해당 투표함의 결과는 무효가 되며, 해당 투표함의 투표용지 수만큼 무효표로 처리한다."},{"k":"hang","x":"② 명부상 총 투표자 수와 총투표용지 수의 차이가 명부상 총 투표자 수 대비 5%를 넘으면 해당 학생총투표는 무효가 된다."}],"num":52,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a53","label":"제53조","title":"준용","paras":[{"k":"line","x":"그 밖에 학생총투표 관련 세부 사항은 투표관리위원회의 출석 3분의 2 이상에 해당하는 결의로 ｢고려대학교 총학생회 선거시행세칙｣의 투표·개표 관련 규정을 준용한다."}],"num":53,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제4절 학생대표자회"},{"t":"art","id":"a54","label":"제54조","title":"지위","paras":[{"k":"line","x":"학생대표자회는 학생총회 다음의 위계에 있는 의결기구이다."}],"num":54,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a55","label":"제55조","title":"구성","paras":[{"k":"hang","x":"① 학생대표자회는 각호의 대표자를 대의원으로 한다."},{"k":"ho","x":"1. 학부 학생회장 및 부학생회장"},{"k":"ho","x":"2. 각 반 학생회 반 운영위원 중 학생회장, 부학생회장, 신입생 대표, 고학번 대표 4인"},{"k":"ho","x":"3. 각 자치단체장"},{"k":"hang","x":"② 비상대책위원회 체제의 산하기구의 장은 궐위로 본다."},{"k":"hang","x":"③ 궐위 대의원은 재적 대의원에서 제외한다."},{"k":"hang","x":"④ 제1항 제3호의 대표자가 학생대표자회에 정당한 사유로 출석하지 못할 때는 개의 직후에 인준을 받아 부대표자가 대신 의결권을 가질 수 있다."}],"num":55,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a56","label":"제56조","title":"학생대표자회 대의원의 의무","paras":[{"k":"hang","x":"① 학생대표자회 대의원은 학생대표자회의 품위를 유지하여야 한다."},{"k":"hang","x":"② 학생대표자회 대의원은 회칙을 준수하여야 한다."},{"k":"hang","x":"③ 학생대표자회 대의원은 자신이 소속된 기구의 의사를 충분히 수렴하여 의결 과정 전반에서 소속된 기구를 대표하는 의사를 표명해야 한다."},{"k":"hang","x":"④ 학생대표자회 대의원은 본회를 대표하여 활동하는 자로서 양심에 따라 직무를 행하고 회의에 성실히 참여하여야 한다."}],"num":56,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a57","label":"제57조","title":"정기회","paras":[{"k":"hang","x":"① 학생대표자회 정기회는 매 학기 1회 개의한다."},{"k":"hang","x":"② 정기회는 각각 5월, 11월에 개의하는 것을 원칙으로 한다."},{"k":"hang","x":"③ 학부 학생회장은 대의원과 협의하여 해당 학기 학생대표자회의 정기회 개의일을 확정 및 공고하여야 한다."}],"num":57,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a57-2","label":"제57조의2","title":"개의·의결요건","paras":[{"k":"hang","x":"① 학생대표자회는 재적 대의원 과반수 출석으로 개의하고, 출석 대의원 과반수에 해당하는 결의로 의결한다."},{"k":"hang","x":"② 다음 각호의 사항은 출석 3분의 2 이상에 해당하는 결의로 의결한다."},{"k":"ho","x":"1. 제36조 제2항의 집행위원 해임에 관한 사항"},{"k":"ho","x":"2. 제39조 제３항의 학부 학생회비 인상·인하에 관한 사항"},{"k":"ho","x":"3. 제40조 제１항의 회칙 개정에 관한 사항"},{"k":"ho","x":"4. 제60조의 학부 학생회장단 탄핵안 학생총투표 발의에 관한 사항"}],"num":57,"sub":2,"bu":false,"bold_title":false},{"t":"art","id":"a58","label":"제58조","title":"안건","paras":[{"k":"hang","x":"① 학생대표자회의 안건은 다음 각호의 방법으로 상정할 수 있다."},{"k":"ho","x":"1. 학부운영위원회의 출석 과반수에 해당하는 결의"},{"k":"ho","x":"2. 회원 50명 이상의 연서에 따른 임시회의 소집요구와 함께 발의"},{"k":"ho","x":"3. 제90조에 따라 발의된 학부 학생회장단 사퇴 허가 요청"},{"k":"ho","x":"4. 제91조에 따른 학부 학생회장단 탄핵 발의"},{"k":"ho","x":"5. 제175조에 따른 회칙 개정안 발의"},{"k":"hang","x":"② 학생대표자회는 다음 각호의 안건을 심의·의결한다."},{"k":"ho","x":"1. 제31조 제2항 제4호, 제35조의 학부 학생회장 탄핵안건을 제외한 안건 중 학생총회에서 다룰 수 있는 안건 및 학생총회의 위임을 받은 안건"},{"k":"ho","x":"2. 학부 학생회장단 탄핵안 학생총투표 발의 안건"},{"k":"ho","x":"3. 임시 학생총회 소집 및 안건상정에 관한 안건"},{"k":"ho","x":"4. 학생총투표 실시 및 안건 상정에 관한 안건"}],"num":58,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a59","label":"제59조","title":"안건 위임","paras":[{"k":"line","x":"회기 중 처리하지 못한 안건은 출석 인원의 3분의 2 이상의 찬성으로 학부운영위원회의에 위임할 수 있다. 단, 제58조 제2항 및 제60조의 탄핵안 학생총투표 발의에 관한 안건, 제175조 회칙 개정안건, 세칙 제정·개정안건, 그 밖의 본회의 목적과 관련된 본질적으로 중대한 결정사항은 위임할 수 없다."}],"num":59,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a60","label":"제60조","title":"탄핵안 학생총투표 발의","paras":[{"k":"hang","x":"① 학생대표자회는 학부 학생회장단 탄핵안을 학생총투표에 붙일 수 있다."},{"k":"hang","x":"② 학부 학생회장단 탄핵안 학생총투표 발의에 관한 절차는 제91조를 따른다."}],"num":60,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a61","label":"제61조","title":"준용","paras":[{"k":"hang","x":"① 소집요건에 관한 사항은 제27조를 준용한다. 단, 제27조 제1항 제2호는 적용하지 아니한다."},{"k":"hang","x":"② 소집공고에 관한 사항은 제28조를 준용한다."},{"k":"hang","x":"③ 자료의 사전 배포에 관한 사항은 제29조를 준용한다."},{"k":"hang","x":"④ 산하기구의 결정·집행사항 변경에 관한 사항은 제33조를 준용한다."},{"k":"hang","x":"⑤ 학부 학생회장단 사퇴 허가에 관한 사항 사항은 제34조를 준용한다."},{"k":"hang","x":"⑥ 집행위원회에 관한 사항은 제36조를 준용한다."},{"k":"hang","x":"⑦ 감사에 관한 사항은 제37조를 준용한다."},{"k":"hang","x":"⑧ 재정에 관한 사항은 제39조를 준용한다."},{"k":"hang","x":"⑨ 회칙·세칙·규칙에 관한 사항은 제40조를 준용한다."},{"k":"hang","x":"⑩ 대외활동에 관한 사항은 제41조를 준용한다."},{"k":"hang","x":"⑪ 재소집에 관한 사항은 제42조를 준용한다."}],"num":61,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제5절 학부운영위원회"},{"t":"art","id":"a62","label":"제62조","title":"지위","paras":[{"k":"line","x":"학부운영위원회는 본회의 신속하고 민주적인 결정을 위하여 학생총회가 일정 권한을 위임한 상설적인 의결기구이다."}],"num":62,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a63","label":"제63조","title":"구성","paras":[{"k":"hang","x":"① 다음 각호 중 하나에 해당되는 자는 학부운영위원이 된다."},{"k":"ho","x":"1. 학부 학생회장과 부학생회장"},{"k":"ho","x":"2. 반 학생회장"},{"k":"hang","x":"② 비상대책위원회 체제인 산하기구의 장은 궐위로 본다."},{"k":"hang","x":"③ 궐위 대의원은 재적 대의원에서 제외한다."},{"k":"hang","x":"④ 제1항 제2호의 학부운영위원이 학부운영위원회에 정당한 사유로 출석하지 못할 때는 개의 직후에 인준을 받아 부회장이 대신 의결권을 가질 수 있다."}],"num":63,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a64","label":"제64조","title":"학부운영위원의 의무","paras":[{"k":"line","x":"학부운영위원의 의무에 관해서는 제56조를 준용한다."}],"num":64,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a65","label":"제65조","title":"정기회의","paras":[{"k":"hang","x":"① 학부운영위원회 정기회의는 매주 1회 개의함을 원칙으로 한다. 단, 학부운영위원회의 출석 과반수에 해당하는 결의로 정기회의의 일정을 조정할 수 있다."},{"k":"hang","x":"② 의장은 학부운영위원회 정기회의의 개의 요일과 시각을 학부운영위원들과 협의하여 결정한 후 이를 공고하여야 한다."},{"k":"hang","x":"③ 의장은 매월 말 다음 달의 학부운영위원회 정기회의 일정을 학부운영위원들과 협의하여 결정하여야 한다."}],"num":65,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a66","label":"제66조","title":"임시회의","paras":[{"k":"hang","x":"① 학부운영위원회 임시회의는 다음 각호 중 하나에 의해 의장이 소집한다."},{"k":"ho","x":"1. 의장의 소집요구"},{"k":"ho","x":"2. 학부운영위원회 재적 위원 3분의 1 이상의 연서에 따른 소집요구"},{"k":"ho","x":"3. 정회원 20명 이상의 연서에 따른 소집요구"},{"k":"hang","x":"② 연서에 따른 소집요구는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식을 준용하며 서식에는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 사항이 포함되어야 한다."},{"k":"hang","x":"③ 연서에 따른 소집요구가 있으면 학부운영위원회 의장은 지체 없이 학부운영위원회 개의일을 결정한다. 이때 개의일은 소집요구 서식에 기재된 개의 희망일로 함을 원칙으로 하되 변경할 때는 학부운영위원의 출석 3분의 2 이상에 해당하는 결의로 한다. 단, 이 경우에도 개의 희망일과 3일 이상 차이가 나서는 안 된다."}],"num":66,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a67","label":"제67조","title":"소집 공고","paras":[{"k":"hang","x":"① 의장은 학부운영위원회의 소집을 개의일 2일 전에 공고하여야 한다."},{"k":"hang","x":"② 공고문에는 다음 각호의 사항을 명시하여야 한다."},{"k":"ho","x":"1. 회의 시작 일시"},{"k":"ho","x":"2. 회의 장소"},{"k":"ho","x":"3. 안건과 안건에 대한 설명"}],"num":67,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a68","label":"제68조","title":"안건지의 사전 배포","paras":[{"k":"line","x":"학부운영위원회 의장은 학부운영위원회 정기회의 개의 1일 전까지 제출된 안건과 그에 관한 설명, 집행위원회 등의 보고·인준 사항 등이 포함된 안건지를 학부운영위원을 대상으로 배포하여야 한다. 배포는 유인물 형태로 제작하여 비치하는 방법과 전산화된 형태의 문서로 제작하여 온라인에 게시하는 방법으로 한다."}],"num":68,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a69","label":"제69조","title":"개의·의결요건","paras":[{"k":"line","x":"학부운영위원회는 재적 위원 과반수 출석으로 개의하고, 출석 위원 과반수 찬성으로 의결한다."}],"num":69,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a70","label":"제70조","title":"안건","paras":[{"k":"hang","x":"① 학부운영위원회의 안건은 다음 각호의 방법으로 상정할 수 있다."},{"k":"ho","x":"1. 학부운영위원이 발의한 안건"},{"k":"ho","x":"2. 회원 20명 이상의 연서에 따른 소집요구와 함께 발의한 안건"},{"k":"hang","x":"② 학부운영위원회는 다음 각호의 안건을 심의·의결한다."},{"k":"ho","x":"1. 제60조 탄핵안 학생총투표 발의에 관한 안건, 제175조 회칙 개정안건, 세칙 제정·개정안건 등 본회의 목적과 관련된 본질적으로 중대한 결정사항을 제외한 안건 중 학생대표자회에서 위임을 받은 안건"},{"k":"ho","x":"2. 임시학생총회 소집 및 안건 상정에 관한 건"},{"k":"ho","x":"3. 임시학생대표자회 소집 및 안건 상정에 관한 건"},{"k":"ho","x":"4. 학생회 제반 사업에 대한 논의 안건"},{"k":"ho","x":"5. 예산 및 결산에 대한 사전 심의·검토 안건"},{"k":"ho","x":"6. 각 반 학생회 사업 보고 및 공유에 관한 안건"},{"k":"ho","x":"7. 반 학생회장단 선거관리위원회 구성에 관한 안건"},{"k":"ho","x":"8. 특별위원회 설립에 관한 안건"},{"k":"ho","x":"9. 공간배정위원회 소집 및 안건 상정에 관한 건"},{"k":"ho","x":"10. 산하기구 감사에 관한 건"},{"k":"ho","x":"11. 학생대표자회 대표자 명단 확정 및 대표자 지위 심의에 관한 건"},{"k":"ho","x":"12. 기타 학생총회 및 학생대표자회의 의결을 요하지 않는 결정사항에 대한 안건"}],"num":70,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a71","label":"제71조","title":"","paras":[{"k":"line","x":"<삭제>"}],"num":71,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a72","label":"제72조","title":"의결기구에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 학생총회의 소집을 요구할 수 있으며 학생총회에 안건을 발의할 수 있다."},{"k":"hang","x":"② 학부운영위원회는 학생대표자회의 소집을 요구할 수 있으며 학생대표자회에 안건을 발의할 수 있다."},{"k":"hang","x":"③ 학부운영위원회는 학생총회 및 학생대표자회의 개의에 관한 세부 문제를 논의하고 결정한다."},{"k":"hang","x":"④ 학부운영위원회는 학생총회에 대하여 연서에 따른 소집요구가 있으면 학생총회의 개의일을 결정한다."},{"k":"hang","x":"⑤ 학부운영위원회는 학생대표자회 개의 전 산하기구의 대표자가 민주적 선거에 의해 당선되었는지, 실질적으로 기구를 대표하고 있는지 등 대표자 지위에 대한 심사를 진행하여야 하며, 이를 기준으로 대의원 명단을 확정 지어야 한다."}],"num":72,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a73","label":"제73조","title":"집행기구에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 제95조 제2항, 제96조 제2항에 따라 집행위원장과 집행위원회 각 국서의 국장과 국원을 사전 인준한다."},{"k":"hang","x":"② 학부운영위원회는 학생총회 및 학생대표자회 보고 사항을 사전 심의한다."},{"k":"hang","x":"③ 학부운영위원회는 학부 학생회장단과 집행위원회의 사업 계획과 진행 상황, 결과에 대한 보고를 받고 이를 심의하고 조정한다. 단, 학부 학생회장단과 집행위원회의 효율적인 집행을 보장하기 위하여 학부 학생회장단이 사전 집행이 불가피하다고 판단하여 집행한 사업에 대하여는 사후에 보고하고 심의 절차를 이행할 수 있다. 집행위원회는 불승인된 사업에 대해서는 의결 즉시 원상회복을 위해 노력해야 한다."},{"k":"hang","x":"④ 학부운영위원회는 학부 학생회장단과 집행위원회의 결정과 집행사항을 변경 또는 취소할 수 있다."},{"k":"hang","x":"⑤ 학부운영위원회는 학부 학생회장단에 대한 탄핵안이 발의되면 탄핵안이 제91조 제1항 내지 제3항에서 규정하고 있는 발의 요건을 충족하고 있는지 지체 없이 심의해야 하며 제91조 제4항에 따라 학생총회 또는 학생대표자회를 소집해야 한다."}],"num":73,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a74","label":"제74조","title":"감사에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 본회 집행기구, 산하기구의 사업 전반에 대하여 감사를 시행할 수 있다."},{"k":"hang","x":"② 학부운영위원회는 감사에 필요하다고 인정될 때 해당 기구의 대표자 혹은 사업담당자를 출석시켜 진술을 청취할 수 있다. 또한 관련 자료의 제출을 요구할 수 있다."}],"num":74,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a75","label":"제75조","title":"선거에 관한 사항","paras":[{"k":"line","x":"학부운영위원회는 반 학생회장단 동시선거 일정을 결정하고 반 학생회 동시 선거관리위원회를 구성할 수 있다. 그 밖에 자세한 사항은 ｢자유전공학부 학부·반 선거시행세칙｣을 따른다."}],"num":75,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a76","label":"제76조","title":"재정에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 제167조에 따라 학생회비를 사용하는 학부·반 집행위원회 등의 예산안과 결산을 사전 심의한 후 학생총회 및 학생대표자회에 상정한다."},{"k":"hang","x":"② 학부운영위원회는 제163조 제8항에 따라 집행기구 자산의 취득, 보관, 사용, 처분 행위를 취소할 수 있다."}],"num":76,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a77","label":"제77조","title":"회칙·세칙·규칙에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 제175조에 따라 회칙 개정안과 제182조에 따라 세칙 제정안·개정안·폐지안을 발의할 수 있다. 학부운영위원회는 회칙 개정안을 발의하면 제177조 제１항에 따라 학부운영위원회에서 회칙 개정안에 대해 사전 심의한다."},{"k":"hang","x":"② 세칙에 관련 규정이 있으면 학부운영위원회는 해당 세칙에 부수되는 규칙을 제정·개정·폐지할 수 있다. 이에 관하여서는 해당 세칙을 따른다."},{"k":"hang","x":"③ 학부운영위원회는 일반규칙을 제정·개정·폐지할 수 있다."}],"num":77,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a78","label":"제78조","title":"대외활동에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 본회의 대외적 활동에 대하여 동의 및 승인권을 갖는다."},{"k":"hang","x":"② 학부운영위원회는 직전 두 분기의 학부 학생회비 5%를 초과하는 재정적 지출을 수반하거나, 본회의 회원에게 중대한 영향을 미치는 학부 학생회장단 또는 집행위원회 차원의 대외활동에 대하여 동의권을 갖는다. 단, 학부 학생회장단과 집행위원회의 효율적인 대외활동을 보장하기 위하여 학부 학생회장단이 사전 집행이 불가피하다고 판단하여 집행한 사업에 대하여는 사후에 보고하고 승인 절차를 이행할 수 있다. 학부 학생회장단과 집행위원회는 부동의된 대외활동에 대해서는 의결 즉시 원상회복을 위해 노력해야 한다."}],"num":78,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제6절 비상대책위원회"},{"t":"art","id":"a79","label":"제79조","title":"비상대책위원회","paras":[{"k":"hang","x":"① 비상대책위원회는 다음 각호에 해당할 때 해당 사항의 공고 시로부터 48시간 후 구성한다. 단, 임기 종료일이 확정되지 않았을 때 잔여 임기의 계산을 위한 임기 종료일은 11월 30일로 한다."},{"k":"ho","x":"1. 학부 학생회장단 선거가 무산될 때"},{"k":"ho","x":"2. 학부 학생회장단 두 명 모두가 사퇴하거나 탄핵되고, 해당 학부 학생회장단의 잔여 임기가 180일이 넘지 않을 때"},{"k":"hang","x":"② 제１항에 따라 비상대책위원회가 구성되면 다음 각호에 해당하는 자는 비상대책위원이 된다."},{"k":"ho","x":"1. 각 반 학생회장 및 부학생회장"},{"k":"ho","x":"2. 학생대표자회 대의원 중 호선된 자"}],"num":79,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a80","label":"제80조","title":"권한·업무","paras":[{"k":"hang","x":"① 비상대책위원회는 의결기구에 준하는 권한을 갖는다."},{"k":"hang","x":"② 비상대책위원회는 학부 학생회장단의 궐위기간 동안 학부운영위원회의 상시적 업무를 담당한다."},{"k":"hang","x":"③ 비상대책위원회는 학부 학생회장단의 궐위기간 동안 집행위원회의 상시적 업무를 담당하기 위하여 임시집행위원회를 구성할 수 있다."}],"num":80,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a81","label":"제81조","title":"비상대책위원장","paras":[{"k":"hang","x":"① 비상대책위원장은 비상대책위원회의 출석 과반수에 해당하는 결의로 선출하며, 선출이 무산될 경우 호선에 의한다. 비상대책위원장은 학생총회 또는 학생대표자회의 인준을 받아야 한다."},{"k":"hang","x":"② 비상대책위원장은 학부 학생회장에 준하는 권한을 갖는다."},{"k":"hang","x":"③ 비상대책위원장의 의무에 관해서는 제56조와 제88조를 준용한다."}],"num":81,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a81-2","label":"제81조의2","title":"임시집행위원회","paras":[{"k":"hang","x":"① 임시집행위원회는 집행위원회에 준하는 권한을 가지며, 학부 학생회장단의 궐위 기간 동안 집행위원회의 상시적 업무를 담당한다."},{"k":"hang","x":"② 임시집행위원은 각 반 학생회에서 두 명씩 추천하며, 그 외 임시집행위원은 공고를 내어 공개 모집함을 원칙으로 한다."},{"k":"hang","x":"③ 비상대책위원장은 임시집행위원장을 둘 수 있으며, 임시집행위원장의 임명에 관하여서는 학생대표자회의 인준을 받아야 한다."},{"k":"hang","x":"④ 각 국서의 국장과 국원은 비상대책위원장이 임명한다. 각 국서의 국장과 국원의 임명에 관하여서는 학생대표자회의 인준을 받아야 한다."}],"num":81,"sub":2,"bu":false,"bold_title":false},{"t":"art","id":"a82","label":"제82조","title":"제한","paras":[{"k":"hang","x":"① 비상대책위원장과 임시집행위원회는 학생회장단 및 집행위원회가 가지는 사전 집행·사후 학부운영위원회 승인 방식의 재정지출이 허용되지 않는다."},{"k":"hang","x":"② 비상대책위원장과 임시집행위원회는 학생회장단 및 집행위원회가 가지는 사전 집행·사후 학부운영위원회 승인 방식의 대외활동이 허용되지 않는다."},{"k":"hang","x":"③ 비상대책위원장과 임시집행위원회는 직전 두 분기의 학부 학생회비 30%를 초과하는 재정지출이 허용되지 않는다."}],"num":82,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a83","label":"제83조","title":"흠결의 보충","paras":[{"k":"line","x":"비상대책위원회 관련 회칙의 흠결로 비상대책위원회 및 비상대책위원장의 권한, 의무의 범위를 확정 짓기 어려울 시, 학부운영위원회의 출석 과반수에 해당하는 결의로 해당 회기에 한해 한시적으로 흠결을 보충할 수 있다. 단, 권한의 범위는 학부 학생회장과 집행위원회의 권한 내로 제한되며, 의무의 범위는 학부 학생회장단과 집행위원회의 의무 내로 제한된다."}],"num":83,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제３장 집행기구"},{"t":"h","lv":3,"text":"제１절 학부 학생회장단"},{"t":"art","id":"a84","label":"제84조","title":"지위","paras":[{"k":"hang","x":"① 학부 학생회장은 본회를 대표하며, 학생총회, 학생대표자회, 학부운영위원회의 의장이 된다."},{"k":"hang","x":"② 학부 학생회장은 총학생회 중앙운영위원 및 전체학생대표자회 대의원이 된다."},{"k":"hang","x":"③ 부학생회장은 학부 학생회장을 보좌하고 학부 학생회장이 권한을 위임하거나 사고인 때에 학부 학생회장의 직무를 대행한다."}],"num":84,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a85","label":"제85조","title":"의결기구 관련 권한","paras":[{"k":"line","x":"학부 학생회장은 학생총회, 학생대표자회, 학부운영위원회 등 의결기구를 운영한다."}],"num":85,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a86","label":"제86조","title":"집행기구 관련 권한","paras":[{"k":"hang","x":"① 학부 학생회장은 본회 사무의 집행을 총괄한다."},{"k":"hang","x":"② 학부 학생회장은 집행위원회의 구성권을 가진다."},{"k":"hang","x":"③ 학부 학생회장은 집행위원회 산하 국서의 국장과 국원에 대한 임면권을 가진다."},{"k":"hang","x":"④ 학부 학생회장은 집행위원회와 산하 국서를 지휘·감독한다."},{"k":"hang","x":"⑤ 학부 학생회장은 집행위원회의 결정·집행 사항을 변경 또는 취소할 수 있다."},{"k":"hang","x":"⑥ 학부 학생회장은 필요하다고 인정한 사안의 효율적 업무 집행을 위하여 직속 자문위원회를 설치할 수 있다. 직속 자문위원회와 그 위원에 관하여서는 제３항 내지 제5항을 준용한다."}],"num":86,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a87","label":"제87조","title":"대외활동 관련 권한","paras":[{"k":"hang","x":"① 학부 학생회장은 학생자치활동에 관계되는 학교 행정의 문제에 대해 회원의 의사를 대변하고 학교 당국에 의사를 개진하며, 관련 단체 및 회의에 참여할 수 있다."},{"k":"hang","x":"② 학부 학생회장은 본회와 본회 회원과 관련된 문제에 관하여 본회를 대표하여 대외적으로 입장을 표명하는 등의 대외활동을 할 수 있다. 단, 본회 차원의 연대 단체 가입과 대외적 협의, 본회의 재정적 지출을 수반는 행위나, 본회의 회원에게 중대한 영향을 미치는 학부 학생회장단 차원의 대외활동은 제78조에 따라 학부운영위원회의 동의를 받아야 한다."}],"num":87,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a88","label":"제88조","title":"의무","paras":[{"k":"hang","x":"① 학부 학생회장은 회원들의 의사를 반영하여 민주적 절차에 따라 직무를 수행해야 한다."},{"k":"hang","x":"② 학부 학생회장은 본회의 의결기구에 성실하게 본회의 활동 사항을 보고해야 한다."},{"k":"hang","x":"③ 학부 학생회장은 본회의 지속적·장기적 발전을 위하여 노력해야 한다."},{"k":"hang","x":"④ 학부 학생회장단은 본회와 본회 산하기구의 각종 선거에 대한 부당한 영향력의 행사 등 선거 결과에 직·간접적인 영향을 미치는 행위를 일체 하여서는 아니 된다."},{"k":"hang","x":"⑤ 학부 학생회장단은 후임 학부 학생회장단의 선출과 후임 학부 학생회장단으로의 인수인계가 원활하게 이루어질 수 있도록 노력해야 한다."},{"k":"hang","x":"⑥ 학부 학생회장은 본회의 대표로 학교 기구의 위원이 될 때 의결권 행사 등에 관하여 학부운영위원회와 협의하여야 한다."}],"num":88,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a89","label":"제89조","title":"임기·삼선 금지","paras":[{"k":"hang","x":"① 학부 학생회장단의 임기는 당선 공고일로부터 48시간 이후부터 후임 학부 학생회장단 임기 시작 전까지로 한다. 단, 후임 학부 학생회장단 선거가 무산되는 경우 후임 학부 학생회장단 선거 개표 예정일로부터 48시간이 도과하면 임기가 종료되는 것으로 본다."},{"k":"hang","x":"② 학부 학생회장은 후임 학부 학생회장단 선거에서 학부 학생회장 후보로 입후보할 수 있다. 단, 학생회장을 2회 역임한 경우, 차기 선거에서 학부 학생회장 및 부학생회장 후보로 입후보할 수 없다."}],"num":89,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a90","label":"제90조","title":"사퇴","paras":[{"k":"hang","x":"① 학부 학생회장 또는 학부 부학생회장이 사퇴하고자 할 때는 학생총회 또는 학생대표자회의 허가가 있어야 한다. 단, 사망 등으로 인하여 당사자가 허가를 받을 수 없으면 그러하지 아니하다."},{"k":"hang","x":"② 제1항의 사퇴요청의 접수일로부터 20일 이내에 학생총회 또는 학생대표자회의 결정이 없으면 사퇴를 승인한 것으로 본다."},{"k":"hang","x":"③ 학부 학생회장이 사퇴하거나 탄핵되면 학부 부학생회장이 그 직을 승계한다."}],"num":90,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a91","label":"제91조","title":"탄핵","paras":[{"k":"hang","x":"① 회원은 학부 학생회장단이 다음 각호 중 하나에 해당할 시 학부 학생회장단의 탄핵안을 발의할 수 있다. 회장과 부회장 중 한 명만 다음 각호 중 하나에 해당하는 경우, 회장과 부회장 중 한 명을 대상으로 한 탄핵안을 발의할 수 있다. 탄핵안의 경우 반드시 학생총회 또는 학생총투표의 방법 중 하나를 정해 발의해야 한다."},{"k":"ho","x":"1. 회칙의 중대한 위반을 저질렀을 경우"},{"k":"ho","x":"2. 상당한 기간 동안 회장단의 업무를 해태하고 있을 경우"},{"k":"ho","x":"3. 실정법 위반으로 벌금형 이상의 실형을 선고받은 경우"},{"k":"ho","x":"4. 회원으로부터 현저히 신임을 잃었을 경우"},{"k":"hang","x":"② 탄핵안의 상정은 다음 각호의 요건 중 하나를 충족시켜야 한다."},{"k":"ho","x":"1. 학부운영위원회의 재적 3분의 2 이상에 해당하는 연서"},{"k":"ho","x":"2. 학생대표자회의 재적 3분의 2 이상에 해당하는 연서"},{"k":"ho","x":"3. 본회 회원 10분의 1 이상에 해당하는 연서"},{"k":"hang","x":"③ 연서에 따른 발의는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식에 의하여야 한다."},{"k":"hang","x":"④ 학부운영위원회는 탄핵안이 발의되면 즉시 탄핵안이 제1항 내지 제3항의 발의 요건을 충족시켰는지 심의하여야 하며, 중대한 하자가 없으면 탄핵안 제출일로부터 7일 이내에 학생총회 소집 또는 학생총투표에 상정한다. 학생총회 및 학생총투표 방법에 관한 탄핵 안건이 모두 상정된 경우, 학부운영위원회의 출석 과반수에 해당하는 결의로 방법을 정한다. 단, 두 방법 모두 출석 과반수에 해당하는 결의가 성립되지 않으면, 탄핵안을 학생총투표에 상정하는 것으로 한다."}],"num":91,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a92","label":"제92조","title":"인수위원회","paras":[{"k":"hang","x":"① 학부 학생회장단 당선자는 학부 학생회장단 및 집행위원회의 업무 인수를 위해 당선 공고일로부터 48시간 이후부터 자유전공학부 학생회 인수위원회를 설치할 수 있다. 단, 보궐선거로 당선되었을 경우 설치하지 아니한다."},{"k":"hang","x":"② 인수위원회는 다음 각호의 직무를 수행한다."},{"k":"ho","x":"1. 집행위원회의 조직ᆞ 기능 및 예산 현황의 파악"},{"k":"ho","x":"2. 전임 학부 학생회장단과 집행위원회의 주요 사업 분석"},{"k":"ho","x":"3. 기타 학부 학생회장단과 집행위원회 업무의 인수에 필요한 사항"},{"k":"hang","x":"③ 인수위원장은 당선된 선거운동본부의 본부장으로 함을 원칙으로 한다."},{"k":"hang","x":"④ 인수위원회는 설치한 날로부터 7일 후 해산한다."}],"num":92,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제２절 집행위원회"},{"t":"art","id":"a93","label":"제93조","title":"지위","paras":[{"k":"line","x":"집행위원회는 본회의 최고집행기구이다."}],"num":93,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a94","label":"제94조","title":"구성","paras":[{"k":"line","x":"집행위원회는 각 국서의 국장과 국원으로 구성한다. 단, 원활한 운영을 위해 집행원장을 둘 수 있다."}],"num":94,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a95","label":"제95조","title":"집행위원장","paras":[{"k":"hang","x":"① 집행위원장은 학생회장단을 보좌하며, 본회 사무의 집행에 관하여 학부 학생회장단의 지시에 따라 각 국서를 관리·감독한다."},{"k":"hang","x":"② 집행위원장은 학부 학생회장이 임명하고, 학부운영위원회의 사전 인준(임명)으로 업무를 개시한다. 집행위원장의 임명에 관하여서는 학생총회 또는 학생대표자회의 사후 인준을 받아야 한다."}],"num":95,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a96","label":"제96조","title":"국서","paras":[{"k":"hang","x":"① 집행위원회는 원활한 업무 집행을 위하여 산하에 국서를 둘 수 있다."},{"k":"hang","x":"② 각 국서의 국장과 국원은 학부 학생회장이 임명하고, 학부운영위원회의 사전 인준(임명)으로 업무를 개시한다. 각 국서의 국장과 국원의 임명에 관하여서는 학생총회 또는 학생대표자회의 사후 인준을 받아야 한다."}],"num":96,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a97","label":"제97조","title":"업무","paras":[{"k":"hang","x":"① 집행위원회는 본회의 사업 집행 전반을 담당한다."},{"k":"hang","x":"② 집행위원회는 학생총회, 학생대표자회 및 학부운영위원회가 결정한 업무를 집행한다."},{"k":"hang","x":"③ 집행위원회는 학부 학생회장단이 결정한 업무를 집행한다."},{"k":"hang","x":"④ 집행위원회는 다음 각호의 사안에 대한 관리 권한을 갖는다. 관리 권한이라 함은 각 사안의 원활한 운영을 위하여 배타적인 권리행사 및 집행을 할 수 있는 권원을 의미한다."},{"k":"ho","x":"1. ｢권한등기부｣에 등기된 것"},{"k":"ho","x":"2. 학생회 자치 공간 분배 및 회수"},{"k":"ho","x":"3. 사물함 분배, 회수, 철거"},{"k":"hang","x":"⑤ 집행위원회는 학생총회, 학생총투표, 학생대표자회 및 학부운영위원회의 개의·시행을 준비하고, 이에 사용되는 각종 서식을 ｢고려대학교 총학생회 사무처리세칙｣을 준용하여 제작한다."},{"k":"hang","x":"⑥ 집행위원회는 학생총회, 학생대표자회 및 학부운영위원회에 본회의 운영 사항을 보고해야 한다."},{"k":"hang","x":"⑦ 집행위원회는 본회의 예산안·결산을 작성하여 학생총회 또는 학생대표자회와 학부운영위원회에 보고해야 한다."}],"num":97,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a98","label":"제98조","title":"집행회의","paras":[{"k":"hang","x":"① 집행위원장은 집행위원회의 업무에 속하는 사안을 심의하기 위하여 집행회의를 소집할 수 있다. 이 경우 집행회의의 의장은 집행위원장이 된다."},{"k":"hang","x":"② 집행회의의 구성, 업무와 권한, 운영 등에 관하여서는 규칙으로 정한다."},{"k":"hang","x":"③ 집행위원장이 궐위일 경우 집행회의의 의장은 학생회장이 된다."}],"num":98,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a99","label":"제99조","title":"계열회의","paras":[{"k":"line","x":"집행위원회는 원활한 업무 집행을 위하여 특정 국서의 국장과 각 반 학생회, 자치단체 및 독립기구 등의 동종 업무 담당 국장 혹은 이에 준하는 자가 참가하는 계열회의를 개최할 수 있다. 계열회의의 구성, 업무와 권한, 운영 등에 관하여서는 규칙으로 정한다."}],"num":99,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제4장 산하기구"},{"t":"h","lv":3,"text":"제１절 반 학생회"},{"t":"art","id":"a100","label":"제100조","title":"지위 및 구성","paras":[{"k":"line","x":"반 학생회는 고려대학교 자유전공학부 학생회원 중 A반부터 D반까지의 네 반을 기준으로 분류된 각 반의 회원들로 구성되며 반 학생회원들의 단결 및 권리와 이익 보장을 위해 자치활동을 하는 자유전공학부 학생회 산하기구이다."}],"num":100,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a101","label":"제101조","title":"회원","paras":[{"k":"hang","x":"① 자유전공학부 학생회원의 반 학생회별 분류는 다음 각호에 따른다."},{"k":"ho","x":"1. A반 소속 자유전공학부 학생회 회원은 A반 학생회원이 된다."},{"k":"ho","x":"2. B반 소속 자유전공학부 학생회 회원은 B반 학생회원이 된다."},{"k":"ho","x":"3. C반 소속 자유전공학부 학생회 회원은 C반 학생회원이 된다."},{"k":"ho","x":"4. D반 소속 자유전공학부 학생회 회원은 D반 학생회원이 된다."},{"k":"hang","x":"② 2학기 입학, 편입 등으로 반이 확정되지 않은 채로 회원이 된 경우, 해당 회원의 반은 학부운영위원회의 출석 과반수에 해당하는 결의로 결정한다."},{"k":"hang","x":"③ 반 학생회의 회원은 해당 반 학생회 회장단 선거의 선거권과 피선거권을 가진다."},{"k":"hang","x":"④ 반 학생회의 회원은 해당 반 학생회 사업을 향유할 권리를 지닌다."},{"k":"hang","x":"⑤ 반 학생회 회원의 권리 및 의무에 관한 사항은 각 반 학생회칙으로 정한다."}],"num":101,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a102","label":"제102조","title":"반 학생회장단","paras":[{"k":"hang","x":"① 반 학생회장단은 상위 규정과 어긋나지 않는 범위에서 반 학생회칙에 따라 회원의 보통ㆍ평등ㆍ직접ㆍ비밀선거로 선출한다."},{"k":"hang","x":"② 반 학생회장단의 임기는 당선 공고 후 시작되며 다음 반 학생회장단의 당선 공고 전까지로 한다."},{"k":"hang","x":"③ 반 학생회장단의 권한·의무 사항에 대해서는 각 반 학생회칙으로 정한다."},{"k":"hang","x":"④ 반 학생회장은 해당 반을 대표하며 학생대표자회 대의원 및 학부운영위원회 위원이 된다."},{"k":"hang","x":"⑤ 반 학생회장은 총학생회 전체학생대표자회의의 대의원이 된다."}],"num":102,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a103","label":"제103조","title":"운영","paras":[{"k":"hang","x":"① 반 학생회의 최고 의결기구는 반 학생총회이다."},{"k":"hang","x":"② 반 학생회는 정기적으로 반 학생총회 및 반 운영위원회를 개의해야 한다."},{"k":"hang","x":"③ 다음 각호 중 하나에 해당하는 자는 반 운영위원이 되며, 반 학생회장과 부학생회장을 제외한 반 운영위원의 선출·권한·의무 및 그 밖의 사항은 반 학생회칙으로 정한다."},{"k":"ho","x":"1. 반 학생회장과 부학생회장"},{"k":"ho","x":"2. 신입생 대표"},{"k":"ho","x":"3. 고학번 대표"},{"k":"ho","x":"4. 각 반 학생회칙으로 정한 이에 준하는 자"},{"k":"hang","x":"④ 반 학생회의 최고집행기구는 각 반 학생회의 집행위원회이며 반 학생회 집행위원회는 반 운영위원회에 사업을 성실히 보고하여야 한다."},{"k":"hang","x":"⑤ 반 학생회의 모든 기구의 권한과 업무는 각 반 학생회칙으로 정한다."}],"num":103,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a104","label":"제104조","title":"권리","paras":[{"k":"hang","x":"① 반 학생회는 학부 학생회로부터 재정 지원과 공간 지원을 받을 수 있다."},{"k":"hang","x":"② 반 학생회는 학부 학생회로부터 집행 인원을 지원받을 수 있다."},{"k":"hang","x":"③ 반 학생회는 법학관(신관), CJ법학관, 해송법학도서관 강의실을 대관할 수 있다."},{"k":"hang","x":"④ 반 학생회는 학생회 페이스북 페이지, 카카오톡 공지방, 행정실 게시판을 활용할 수 있다."}],"num":104,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a105","label":"제105조","title":"의무","paras":[{"k":"hang","x":"① 반 학생회는 매 학기 학생총회 또는 학생대표자회에서 예산안·결산에 대한 심의·승인 절차를 거쳐야 한다."},{"k":"hang","x":"② 반 학생회는 다른 반 학생회와 교류하고, 학부 학생회 사업에 협력해야 한다."}],"num":105,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a106","label":"제106조","title":"위계","paras":[{"k":"hang","x":"① 반 학생회의 회칙 및 결정사항이 본회의 회칙·세칙과 충돌할 시, 본회의 회칙·세칙과 합치될 수 있는 내용을 제외한 모든 내용은 무효로 한다. 단, 본회의 회칙·세칙의 개정 및 신설로 인해 기존의 반 학생회 회칙 및 결정사항과 충돌이 생겼을 시, 소급효는 인정하지 않는다."},{"k":"hang","x":"② 반 학생회의 결정이 본회 의결기구의 결정과 충돌할 시, 본회의 결정과 합치될 수 있는 내용을 제외한 모든 내용은 그 즉시 무효로 한다."}],"num":106,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 자치단체"},{"t":"art","id":"a107","label":"제107조","title":"지위","paras":[{"k":"hang","x":"① 자치단체는 특정한 분야에서 특정한 목적을 가지고 활동하는 단체 중 자유전공학부 학생회에 등록절차를 마치고 매년 자유전공학부 학생회의 인준을 받아 활동하는 단체이다."},{"k":"hang","x":"② 본회 자치단체로의 등록은 학생총회 혹은 학생대표자회의에서 각호와 같은 사유에 해당될 때에만 거절될 수 있다. 단 아래의 사유는 각 단체의 특수한 목적 및 사정을 고려하여 논의되어야 한다."},{"k":"ho","x":"1. 단체의 존속 가능성이 불분명한 경우"},{"k":"ho","x":"2. 단체의 활동과 목적이 본회가 추구하는 가치에 명백히 반하는 경우"},{"k":"ho","x":"3. 당해 모집 기간 이후에도 명부상 10명 이하의 회원만이 활동하는 것으로 판단되는 경우"},{"k":"ho","x":"4. 명부상 자유전공학부 회원이 구성원의 1/2 미만일 경우"},{"k":"ho","x":"5. 사회상규에 비추어 본회로의 등록이 용인되기 힘든 수준의 사유를 지닐 경우"}],"num":107,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a108","label":"제108조","title":"회원","paras":[{"k":"hang","x":"① 각 자치단체에 소속된 본회의 회원은 해당 자치단체의 회원이 된다."},{"k":"hang","x":"② 자치단체의 회원은 해당 자치단체장 선거의 선거권과 피선거권을 가진다."},{"k":"hang","x":"③ 자치단체의 회원은 해당 자치단체의 사업을 향유할 권리를 지닌다."},{"k":"hang","x":"④ 본회의 회원에 해당하지 않는 자치단체 회원은 자치단체에 관한 회칙의 적용에 한해서는 본회의 회원으로 본다."}],"num":108,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a109","label":"제109조","title":"자치단체장","paras":[{"k":"hang","x":"① 자치단체장은 상위 규정과 어긋나지 않는 범위에서 자치단체의 자치규칙에 따라 회원의 보통ㆍ평등ㆍ직접ㆍ비밀선거로 선출한다."},{"k":"hang","x":"② 자치단체장은 해당 자치단체를 대표하며 학생대표자회의 대의원이 된다."},{"k":"hang","x":"③ 자치단체 및 자치단체장의 권한·업무 등에 관하여서는 각 자치단체의 자치규칙으로 정한다."}],"num":109,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a110","label":"제110조","title":"권리","paras":[{"k":"hang","x":"① 자치단체는 학부 학생회로부터 집행 인원을 지원받을 수 있다."},{"k":"hang","x":"② 자치단체는 법학관(신관), CJ법학관, 해송법학도서관 강의실을 대관할 수 있다."},{"k":"hang","x":"③ 자치단체는 학생회 페이스북 페이지, 카카오톡 공지방, 행정실 게시판을 활용할 수 있다."}],"num":110,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a111","label":"제111조","title":"의무","paras":[{"k":"hang","x":"① 자치단체는 본회의 목표에 맞게 성실히 활동하며 창조적 대학 문화 창달을 위해 노력해야 한다."},{"k":"hang","x":"② 자치단체는 매년 1학기 학생총회 또는 학생대표자회에서 인준 절차를 거쳐야 한다. 등록 및 인준은 정해진 양식에 의하며, 인준의 요건은 제107조 제2항을 준용한다."},{"k":"hang","x":"③ 인준받지 못한 자치단체는 2학기 학생총회 또는 학생대표자회에서 재인준 절차를 거쳐야 하며, 재인준받지 못할 경우, 재인준에 관한 안건이 결의된 학생총회 또는 학생대표자회의 종료일을 기준으로 30일 이내에 자치공간 및 본회 자산을 반납하여야 한다."},{"k":"hang","x":"④ 자치단체는 다른 자치단체와 교류하고, 학생회 사업에 협력해야 한다."},{"k":"hang","x":"⑤ 자치단체는 본회의 회원들의 관심사에 따른 자발적인 참여를 보장해야 하며, 본회 회원의 결속 및 학생회의 발전에 기여해야 한다."}],"num":111,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a112","label":"제112조","title":"위계","paras":[{"k":"line","x":"자치단체의 결정 및 자치규약과 학부 학생회의 결정 및 회칙과의 위계에 관해서는 제106조를 준용한다."}],"num":112,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제3절 특별위원회"},{"t":"art","id":"a113","label":"제113조","title":"목적","paras":[{"k":"line","x":"감찰, 조사, 프로젝트 등 특수한 목적 달성을 위해 학생대표자회 혹은 학부운영위원회 산하에 한시적으로 특별위원회를 둘 수 있다."}],"num":113,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a114","label":"제114조","title":"구성","paras":[{"k":"hang","x":"① 특별위원회는 학생총회, 학생대표자회 혹은 학부운영위원회에서 임명한 위원장 1인과 위원으로 구성한다."},{"k":"hang","x":"② 특별위원회의 위원장과 위원은 공개모집을 원칙으로 하되 필요한 경우 학부운영위원회의 출석 과반수에 의한 결의로 집행위원만으로 구성할 수 있다."},{"k":"hang","x":"③ 특별위원회는 구체적인 활동 목적을 가지고 구성되어야 하며, 특별위원회 구성에 대한 안건에는 반드시 특별위원회의 구체적인 활동 목적과 활동 범위가 명시되어야 한다. 조사, 감찰의 경우 대상자를 특정할 수 있는 경우에는 안건에 함께 기재해야 한다."}],"num":114,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a115","label":"제115조","title":"인준","paras":[{"k":"line","x":"특별위원회의 위원장과 위원은 학부운영위원회의 사전 동의로 활동을 개시하며 소속된 의결기구에서 사후 인준을 받아야 한다. 단, 학부운영위원회 소속 특별위원회의 경우에는 사후 인준 절차를 생략한다."}],"num":115,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a116","label":"제116조","title":"활동","paras":[{"k":"hang","x":"① 특별위원회는 활동 목적에 직·간접적으로 필요하다고 판단될 경우, 학부운영위원회의 출석 3분의 2 이상에 의한 결의로 구체적 활동 범위를 벗어난 활동을 할 수 있다. 이 경우, 필요한 이유 및 재설정한 활동 범위를 소속된 의결기구에 보고하여야 하며, 소속된 의결기구는 언제든지 출석 과반수에 의한 결의로 학부운영위원회의 해당 결정을 취소할 수 있다."},{"k":"hang","x":"② 특별위원회의 활동 기간은 최단 7일, 최장 60일까지이다. 단, 1회에 한해 30일을 연장할 수 있 다."},{"k":"hang","x":"③ 특별위원회의 활동 목적이 새내기새로배움터 준비인 경우, 제2항을 적용하지 아니한다."},{"k":"hang","x":"④ 특별위원회는 활동 목적에 따라 회원 및 단체에 위원회 출석 및 자료 제출을 요청할 수 있다."}],"num":116,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a117","label":"제117조","title":"해산 및 폐지","paras":[{"k":"hang","x":"① 다음 각호에 해당하는 경우 특별위원회는 해산한다."},{"k":"ho","x":"1. 활동 목적이 달성된 경우"},{"k":"ho","x":"2. 활동 기간이 종료된 경우"},{"k":"hang","x":"② 특별위원회는 언제든지 소속된 의결기구의 출석 3분의 2 이상에 의한 결의로 폐지할 수 있다. 단, 특별위원회의 목적이 감찰 및 조사에 해당하는 경우, 감찰 및 조사의 대상이 되는 회원은 의결기구에서 의결권을 행사할 수 없다."}],"num":117,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제５장 독립기구"},{"t":"h","lv":3,"text":"제1절 통칙"},{"t":"art","id":"a118","label":"제118조","title":"지위","paras":[{"k":"hang","x":"① 독립기구는 특수한 영역과 기능을 담당하기 위하여 설치된 상설기구이다."},{"k":"hang","x":"② 독립기구는 자유전공학부 학생회의 물적·인적 지원을 받으며 학부 학생회장단으로부터 그 업무의 감독을 받는다. 다만, 자유전공학부 집행위원회로부터는 독립적인 위상을 보장받는다."},{"k":"hang","x":"③ 전항에도 불구하고 독립기구의 업무가 학부 학생회장단으로부터의 독립의 필요성이 인정되는 범위 내에서 그 독립성이 보장된다."}],"num":118,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a119","label":"제119조","title":"성립 요건","paras":[{"k":"line","x":"독립기구는 다음 각호 중 하나 이상의 요건을 갖추어 설치가 필요하다고 인정될 때에 설치된다."},{"k":"ho","x":"1. 본회 회원의 권익 보호를 위한 전문적 활동을 꾸준히 수행하여 독립기구로서의 정체성이 확보되어 있는 단체"},{"k":"ho","x":"2. 본회 차원의 포괄적, 대외적 사업이 필요한 분야에 관련된 단체"}],"num":119,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 선거관리위원회"},{"t":"art","id":"a120","label":"제120조","title":"목적","paras":[{"k":"line","x":"선거관리위원회는 민주적이고 공정한 절차에 입각해 선거를 효율적으로 진행하는 데 그 목적을 둔다."}],"num":120,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a121","label":"제121조","title":"구성","paras":[{"k":"hang","x":"① 선거관리위원회는 학부 학생회장단을 제외한 학부운영위원 및 학생회칙 제55조 제4항에 의해 의결권을 가질 수 있는 자 전원을 기본으로 구성하며, 나머지 인원은 공개 모집함을 원칙으로 한다. 단, 반 학생회장단 동시선거의 경우, 해당 선거를 진행하는 선거관리위원회는 학부운영위원 및 학생회칙 제55조 제4항에 의해 의결권을 가질 수 있는 자 전원을 기본으로 구성하며, 나머지 인원은 공개 모 집함을 원칙으로 한다."},{"k":"hang","x":"② 선거관리위원회는 학부운영위원회에서 인준받은 8인 이상 12인 이하의 선거관리위원으로 구성한다."}],"num":121,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a122","label":"제122조","title":"대표자 선출","paras":[{"k":"line","x":"선거관리위원회의 위원장은 학부 학생회장단을 제외한 학부운영위원 중 1인으로 한다. 단, 반 학생회장단 동시선거의 경우, 해당 선거를 진행하는 선거관리위원회의 위원장은 학부 학생회장으로 한다."}],"num":122,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a123","label":"제123조","title":"활동 내용","paras":[{"k":"hang","x":"① 선거관리위원회는 제6장 선거에서 규정하는 선거에 관한 절차를 성실히 이행한다."},{"k":"hang","x":"② 선거관리위원회는 제6장 선거에서 규정하는 절차에 관해 최고 해석권 및 결정권을 가지며, 본회의 어떠한 의결기구도 회칙에 따라 진행된 선거 절차상의 해석 및 결정을 번복·철회·변경할 수 없다."},{"k":"hang","x":"③ 선거관리위원은 선거기간 동안 징계할 수 없으며, 선거관리위원회의 출석 3분의 2 이상에 의한 결의로만 해임될 수 있다."}],"num":123,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a124","label":"제124조","title":"의무","paras":[{"k":"hang","x":"① 선거관리위원회의 결정은 표결로서 진행하며, 표결은 기명으로 진행한다."},{"k":"hang","x":"② 선거관리위원회는 결정 사항 및 선거의 진행 상황을 정기적으로 공고해야 한다."},{"k":"hang","x":"③ 선거관리위원은 중립성을 지켜야 하며, 선거에 부당한 영향을 미치는 활동을 할 수 없다."}],"num":124,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a125","label":"제125조","title":"집행위원회에 대한 사항","paras":[{"k":"hang","x":"① 선거관리위원회는 선거 사무의 처리에 관해 집행위원회의 협조를 얻을 수 있다."},{"k":"hang","x":"② 선거관리위원회는 선거의 원활한 진행을 위해 집행위원회에 사무의 처리를 요청할 수 있다."}],"num":125,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a126","label":"제126조","title":"학부 학생회장단에 대한 사항","paras":[{"k":"hang","x":"① 학부 학생회장단은 학부 학생회장단 선거관리위원회의 결정 및 집행에 일체 개입할 수 없다."},{"k":"hang","x":"② 학부 학생회장단 선거 진행에 학부 학생회장단의 부당한 영향력 행사가 있을시, 선거관리위원회는 선거 기간 동안 기간을 정해 한시적으로 학부 학생회장단의 해당 직무 및 활동을 정지·취소할 수 있다."}],"num":126,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a127","label":"제127조","title":"재정","paras":[{"k":"line","x":"본회는 선거관리위원회의 원활한 운영을 위한 재원을 마련해야 한다."}],"num":127,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제3절 투표관리위원회"},{"t":"art","id":"a128","label":"제128조","title":"목적","paras":[{"k":"line","x":"투표관리위원회는 민주적이고 공정한 절차에 입각해 학생총투표를 효율적으로 진행하는 데 그 목적을 둔다."}],"num":128,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a129","label":"제129조","title":"구성","paras":[{"k":"line","x":"투표관리위원회는 학부운영위원 및 제55조 제4항에 의해 의결권을 가질 수 있는 자 전원으로 구성한다. 단, 학부 학생회장단은 제60조에 따른 학부 학생회장단 탄핵안에 대한 학생총투표에 대해서는 투표관리위원이 될 수 없다."}],"num":129,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a130","label":"제130조","title":"대표자 선출","paras":[{"k":"line","x":"투표관리위원회의 위원장은 학부운영위원 중 1인으로 한다."}],"num":130,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a131","label":"제131조","title":"활동 내용","paras":[{"k":"hang","x":"① 투표관리위원회는 제2장 제3절 학생총투표에서 규정하는 학생총투표에 관한 절차를 성실히 이행한다."},{"k":"hang","x":"② 투표관리위원회는 제2장 제3절 학생총투표에서 규정하는 절차에 관해 최고 해석권 및 결정권을 가지며, 본회의 어떠한 의결기구도 회칙에 따라 진행된 투표 절차상의 해석 및 결정을 번복·철회·변경할 수 없다."}],"num":131,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a132","label":"제132조","title":"준용","paras":[{"k":"hang","x":"① 의무에 관해서는 제124조를 준용한다."},{"k":"hang","x":"② 집행위원회에 대한 사항에 대해서는 제125조를 준용한다."},{"k":"hang","x":"③ 학부 학생회장단에 대한 사항에 대해서는 제126조를 준용한다."},{"k":"hang","x":"④ 재정에 관해서는 제127조를 준용한다."}],"num":132,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제4절 학생자치장학금위원회"},{"t":"art","id":"a133","label":"제133조","title":"위계","paras":[{"k":"line","x":"학생자치장학금의 집행 및 운영에 관하여 회칙·세칙에 규정이 없으면 학생자치장학금 내규에 의하고 내규가 없으면 장학금위원회의 결정사항에 의한다."}],"num":133,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a134","label":"제134조","title":"구성","paras":[{"k":"hang","x":"① 학생자치장학금위원회는 장학금운영위원회와 장학금집행위원회로 구성한다."},{"k":"hang","x":"② 장학금운영위원회는 학부운영위원회 전원으로 구성한다."},{"k":"hang","x":"③ 장학금집행위원회는 공개모집하여야 한다."},{"k":"hang","x":"④ 학생자치장학금위원회 위원은 자유전공학부 학생회 회원 중 징계를 받지 아니한 자로 한다."}],"num":134,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a135","label":"제135조","title":"목적","paras":[{"k":"hang","x":"① 장학금운영위원회는 본 장학금에 관련된 제반 사항을 감시·감독하고 보고받는 데 그 목적을 둔다."},{"k":"hang","x":"② 장학금집행위원회는 본 장학금에 관한 사항을 집행하는 데 그 목적을 둔다."}],"num":135,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a136","label":"제136조","title":"대표자 선출","paras":[{"k":"hang","x":"① 장학금운영위원회의 위원장은 학부 학생회장으로 한다."},{"k":"hang","x":"② 장학금집행위원회의 대표는 장학금집행위원회에서 보통⋅평등⋅직접⋅비밀선거로 선출한다."}],"num":136,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a137","label":"제137조","title":"활동 내용","paras":[{"k":"hang","x":"① 장학금운영위원회는 다음 각호의 업무를 수행한다."},{"k":"ho","x":"1. 장학금 운영사항에 관련된 감독"},{"k":"ho","x":"2. 장학금 지급, 장학금집행위원 및 장학금집행위원회 활동에 대한 감사"},{"k":"ho","x":"3. 장학금 운영 전반에 관련된 정보공개청구"},{"k":"ho","x":"4. 장학금집행위원 임면"},{"k":"ho","x":"5. 학생자치장학금 내규 개정"},{"k":"hang","x":"② 장학금운영위원회는 장학금집행위원회 운영목적에 부합하는 필수적 활동이 이뤄지지 않는 경우, 이러한 활동에 대한 촉구, 지시 혹은 활동 그 자체를 수행할 수 있다. 단, 장학금집행위원회 고유 활동의 집행은 가급적 자제한다."},{"k":"hang","x":"③ 장학금집행위원회는 다음 각호의 업무를 수행한다."}],"num":137,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a138","label":"제138조","title":"준용","paras":[{"k":"hang","x":"① 장학금운영위원회의 의무에 관해서는 제124조를 준용한다. 단, 제124조 제3항은 준용하지 아니한다."},{"k":"hang","x":"② 재정에 관해서는 제127조를 준용한다"},{"k":"hang","x":"③ 장학금운영위원회 회의의 진행에 관한 절차는 출석 과반수에 의한 결의로 학부운영위원회의 절차를 준용할 수 있다."}],"num":138,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a139","label":"제139조","title":"중요활동에 관한 사항","paras":[{"k":"line","x":"장학금운영위원회는 회원에게 중대한 영향을 미치는 장학금집행위원회의 활동에 대하여 동의권을 갖는다. 단, 장학금집행위원회의 효율적인 활동을 보장하기 위하여 장학금집행위원회 대표가 사전 집행이 불가피하다고 판단하여 집행한 사업에 대하여는 사후에 보고하고 승인 절차를 이행할 수 있다. 장학금집행위원회는 부동의된 대외활동에 대해서는 의결 즉시 원상회복을 위해 노력해야 한다."}],"num":139,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제5절 학생홍보대사"},{"t":"art","id":"a140","label":"제140조","title":"목적","paras":[{"k":"line","x":"학생홍보대사는 대외적으로 자유전공학부를 홍보하고, 자유전공학부의 가치 제고 및 위상을 높이는 데 목적을 둔다."}],"num":140,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a141","label":"제141조","title":"구성","paras":[{"k":"hang","x":"① 학생홍보대사는 공개 모집하여야 한다."},{"k":"hang","x":"② 학생홍보대사는 자유전공학부 학생회 회원 중 징계를 받지 아니한 자로 한다."}],"num":141,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a142","label":"제142조","title":"대표자 선출","paras":[{"k":"line","x":"학생홍보대사의 대표는 학생홍보대사 회원 중 보통·평등·직접·비밀선거로 선출한다."}],"num":142,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a143","label":"제143조","title":"활동 내용","paras":[{"k":"line","x":"학생홍보대사의 활동은 다음 각호로 정한다."},{"k":"ho","x":"1. 자유전공학부 홍보 활동 진행"},{"k":"ho","x":"2. 모교 방문 자유전공학부 홍보 행사 진행"},{"k":"ho","x":"3. 학생 초청 자유전공학부 홍보 행사 진행"}],"num":143,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a144","label":"제144조","title":"권리","paras":[{"k":"hang","x":"① 학생홍보대사는 본회로부터 공간을 지원받을 수 있다."},{"k":"hang","x":"② 학생홍보대사는 법학관(신관), CJ법학관, 해송법학도서관 강의실을 대관할 수 있다."},{"k":"hang","x":"③ 학생홍보대사는 학생회 페이스북 페이지, 카카오톡 공지방, 행정실 게시판을 활용할 수 있다."}],"num":144,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a145","label":"제145조","title":"재정","paras":[{"k":"line","x":"본회는 학생홍보대사의 원활한 운영을 위한 재원을 마련해야 한다."}],"num":145,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제6절 소수자인권위원회"},{"t":"art","id":"a146","label":"제146조","title":"목적","paras":[{"k":"line","x":"소수자인권위원회는 본회 내 소수자의 인권을 증진하는 데 목적을 둔다."}],"num":146,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a147","label":"제147조","title":"구성","paras":[{"k":"hang","x":"① 소수자인권위원회는 공개 모집하여야 한다."},{"k":"hang","x":"② 소수자인권위원회는 자유전공학부 학생회 회원 중 징계를 받지 아니한 자로 한다."}],"num":147,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a148","label":"제148조","title":"대표자 선출","paras":[{"k":"line","x":"소수자인권위원회의 대표는 소수자인권위원회 회원 중 보통·평등·직접·비밀선거로 선출한다."}],"num":148,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a149","label":"제149조","title":"활동 내용","paras":[{"k":"line","x":"소수자인권위원회의 활동은 다음 각호로 정한다."},{"k":"ho","x":"1. 인권 담론의 공고화 및 확장"},{"k":"ho","x":"2. 인권침해의 발생 방지 노력"},{"k":"ho","x":"3. 인권침해 피해자에 대한 보호"},{"k":"ho","x":"4. 인권 관련 전문 역량의 확보"}],"num":149,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a150","label":"제150조","title":"권리","paras":[{"k":"hang","x":"① 소수자인권위원회는 본회로부터 공간을 지원받을 수 있다."},{"k":"hang","x":"② 소수자인권위원회는 법학관(신관), CJ 법학관, 해송법학도서관 강의실을 대관할 수 있다."},{"k":"hang","x":"③ 소수자인권위원회는 학생회 페이스북 페이지, 카카오톡 공지방, 행정실 게시판을 활용할 수 있다."}],"num":150,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a151","label":"제151조","title":"재정","paras":[{"k":"line","x":"본회는 소수자인권위원회의 원활한 운영을 위한 재원을 마련해야 한다."}],"num":151,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제6장 선거"},{"t":"h","lv":3,"text":"제1절 학부 학생회장단 선거"},{"t":"art","id":"a152","label":"제152조","title":"선거 방식","paras":[{"k":"hang","x":"① 학부 학생회장단은 회원의 보통·평등·직접·비밀 선거로 선출한다."},{"k":"hang","x":"② 학부 학생회장단 선거에는 학부 학생회장 후보 단독으로 출마하거나 학부 학생회장 후보와 학부 부학생회장 후보 각 한 명씩이 조를 이루어 입후보할 수 있다."},{"k":"hang","x":"③ 학부 학생회장단 선거 방식에 대한 세부적인 사항은 「자유전공학부 학부·반 선거 시행세칙」으로 정한다."}],"num":152,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a153","label":"제153조","title":"시기","paras":[{"k":"line","x":"학부 학생회장단 선거는 매년 11월에 시행함을 그 원칙으로 한다. 세부 일정은 학부운영위원회에서 정한다."}],"num":153,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a154","label":"제154조","title":"선거권·피선거권","paras":[{"k":"hang","x":"① 본회 정회원은 학부 학생회장단 선거의 선거권이 있다. 단, 휴학생 회원과 수료생 회원의 경우 정회원 등록 절차를 통해 당해 선거에 있어 선거권을 가질 수 있다."},{"k":"hang","x":"② 본회의 회원인 자는 학부 학생회장단 선거의 피선거권이 있다."},{"k":"hang","x":"③ 학부 학생회장단 선거에 출마하려는 후보는 3학기 이상 등록자이어야 한다."},{"k":"hang","x":"④ 징계로서 선거권과 피선거권을 박탈당한 자는 선거의 선거권과 피선거권이 없다."}],"num":154,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a155","label":"제155조","title":"선거관리위원회","paras":[{"k":"hang","x":"① 학부 학생회장단 선거를 공정하게 민주적으로 관리하기 위하여 선거관리위원회를 둔다."},{"k":"hang","x":"② 선거관리위원회는 회칙과 ｢자유전공학부 학부·반 선거시행세칙｣에 따라 학부 학생회장단 선거에 관련된 모든 사항을 결정한다."},{"k":"hang","x":"③ 선거 기간 동안 학부 학생회장단과 집행위원회가 사업 집행, 의견 표명 등을 하기 위해서는 선거 관리위원회의 사전 허가를 받아야 한다. 학생회장단과 집행위원회의 특정 행위가 선거에 영향을 미칠 수 있다고 판단되면 선거관리위원회는 해당 행위를 허가하지 않을 수 있다."},{"k":"hang","x":"④ 이 밖에 선거관리위원회의 운영에 관한 절차는 제5장 제2절 선거관리위원회 규정에 따른다."}],"num":155,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a156","label":"제156조","title":"보궐선거","paras":[{"k":"hang","x":"① 학생회장단이 탄핵 등의 이유로 궐위된 때 잔여 임기가 180일이 넘으면 궐위된 날로부터 10일 이내에 학부운영위원회는 보궐선거의 시행 일정을 결정하여야 한다. 단, 임기 종료일이 확정되지 않았을 때는 잔여 임기의 계산을 위한 임기 종료일은 11월 30일로 한다."},{"k":"hang","x":"② 잔여 임기가 180일이 넘지 않은 경우에도 학부운영위원회는 선거의 필요성, 선거 시기, 잔여 임기 등 본회의 제반 사정을 고려하여 보궐선거의 시행을 결정할 수 있다."},{"k":"hang","x":"③ 학부운영위원회가 보궐선거 시행 일정을 확정한 날로부터 20일 이내에 보궐선거를 시행하여야 한다."}],"num":156,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a157","label":"제157조","title":"선거시행세칙","paras":[{"k":"line","x":"그 밖에 선거에 관한 사항은 ｢자유전공학부 학부·반 선거 시행세칙｣으로 정한다."}],"num":157,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 반 학생회장단 동시선거"},{"t":"art","id":"a158","label":"제158조","title":"반 학생회장단 동시선거","paras":[{"k":"hang","x":"① 학부 학생회장단 선거관리위원회는 학부운영위원회의 출석 과반수에 의한 결의로 반 학생회장단 동시선거를 진행할 수 있다."},{"k":"hang","x":"② 제1항에서 규정하는 동시선거를 진행하지 않는 경우, 각 반 학생회장단 선거에 관한 제반 사항은 각 반 학생회칙이 정하는 바에 의한다."},{"k":"hang","x":"③ 반 학생회장단 동시선거가 결정되면, 본회의 회칙 및 학부·반 선거시행세칙이 규정하는 절차에 따라 반 학생회장단 선거를 진행한다."}],"num":158,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a159","label":"제159조","title":"준용","paras":[{"k":"hang","x":"① 선거 방식에 관해서는 제152조를 준용한다."},{"k":"hang","x":"② 선거 시기에 관해서는 제153조를 준용한다."},{"k":"hang","x":"③ 선거권에 관해서는 제154조를 준용한다."},{"k":"hang","x":"④ 선거관리위원회에 관해서는 제155조를 준용한다."},{"k":"hang","x":"⑤ 보궐선거에 관해서는 제156조를 준용한다."},{"k":"hang","x":"⑥ ｢선거시행세칙｣에 관해서는 제157조를 준용한다."}],"num":159,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제7장 재정"},{"t":"h","lv":3,"text":"제１절 통칙"},{"t":"art","id":"a160","label":"제160조","title":"원칙","paras":[{"k":"line","x":"본회의 각 기구는 재정을 효율적이고 투명하게 운용하여야 한다."}],"num":160,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a160-2","label":"제160조의2","title":"등기부","paras":[{"k":"hang","x":"① 본회는 다음 각호의 등기부를 두어 운용한다. 본회의 회원 또는 기구 간에 관리권한, 자산, 자치공간 등에 대한 분쟁이 있는 경우 등기부에 기재된 사항을 진실한 것으로 추정한다."},{"k":"ho","x":"1. 「관리권한등기부」"},{"k":"ho","x":"2. 「자산등기부」"},{"k":"ho","x":"3. 「자치공간등기부」"},{"k":"hang","x":"② 등기부의 관리는 집행위원회의 사무로 하되, 정정 또는 경정의 청구 기간이 경과하여 확정된 등기부 기재사항에 대하여는 제33조에 따라 변경 또는 취소할 수 없다."},{"k":"hang","x":"③ 등기부는 본회의 회원이 언제나 열람할 수 있도록 유·무형의 공간에 비치하여야 하며, 집행위원회는 기재사항에 변경이 있는 때에는 지체 없이 그 사실을 공고해야 한다."},{"k":"hang","x":"④ 본회의 회원은 등기부의 기재사항에 대하여 전항의 공고가 있은 때로부터 30일 내에 집행위원회에 기재사항에 대한 정정 또는 경정을 청구할 수 있다."},{"k":"hang","x":"⑤ 전항의 청구에 있어서 이해관계자 간의 분쟁이 있는 경우에는 임시 학생대표자회를 개의하여 심의 및 의결한다."}],"num":160,"sub":2,"bu":false,"bold_title":false},{"t":"art","id":"a161","label":"제161조","title":"재정운용세칙","paras":[{"k":"line","x":"그 밖에 재정 운용에 관한 사항은 ｢고려대학교 총학생회 재정운용세칙｣을 준용한다."}],"num":161,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제２절 자산·배분"},{"t":"art","id":"a162","label":"제162조","title":"자산","paras":[{"k":"hang","x":"① 본회는 유·무형의 동산, 부동산, 권리 등을 소유할 수 있으며, 이를 본회의 자산이라 한다."},{"k":"hang","x":"② 본회의 자산은 각 기구가 독립하여 취득, 보관, 사용, 처분함을 원칙으로 한다."},{"k":"hang","x":"③ 집행기구는 제작, 구매, 수증 등의 방법으로 자산을 취득한다. 다음 각호 중 어느 하나에 해당하는 것은 집행기구의 자산으로 본다."},{"k":"ho","x":"1. ｢자산등기부｣에 집행위원회의 자산으로 등기된 것"},{"k":"ho","x":"2. 학부 학생회장단·집행위원과 이에 준하는 자가 그 직으로써 취득한 것"},{"k":"ho","x":"3. 본회 집행기구의 사업 또는 사무 집행을 위하여 취득하거나, 사업 집행의 결과물로 취득한 것"},{"k":"ho","x":"4. 제1호 내지 제3호에 해당하는 자산으로부터 파생된 것"}],"num":162,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a163","label":"제163조","title":"자산의 관리","paras":[{"k":"hang","x":"① 본회의 각 기구는 자산을 항상 사용하거나 처분할 수 있도록 선량한 관리자의 주의로써 보관하여야 한다."},{"k":"hang","x":"② 집행기구의 자산은 본회 사업과 사무의 집행을 위하여 사용함을 원칙으로 한다."},{"k":"hang","x":"③ 집행기구의 자산은 대여를 목적으로 한 자산이거나 대여하여도 사업 또는 사무에 지장이 없다고 인정되는 자산일 때만 대여할 수 있다. 또한, 집행기구의 자산은 본회 기구와 회원에게 우선적으로 대여되어야 한다."},{"k":"hang","x":"④ 집행기구는 자산의 취득, 보관, 사용, 처분이 본회의 이익을 위하여 적정하고 효율적으로 이루어질 수 있도록 하여야 한다."},{"k":"hang","x":"⑤ 집행기구는 자산의 중대한 변화를 야기하는 집행에 대해 학부운영위원회의 인준을 받아야 한다. 이 경우, 사전에 집행에 대한 예고를 해야 하며, 집행 후 자산 변화를 공고해야 한다."},{"k":"hang","x":"⑥ 집행위원회는 집행기구 자산 중 고정자산의 목록을 작성하여 매 학기 정기학생총회 또는 정기학생대표자회에 보고한다."},{"k":"hang","x":"⑦ 본회의 각 기구는 사용할 필요가 없거나 사용할 수 없는 자산을 교환, 매각, 증여, 폐기 등의 방법으로 처분할 수 있다."},{"k":"hang","x":"⑧ 의결기구는 집행기구의 자산 취득, 보관, 사용, 처분이 본회의 이익을 위한 것이 아니거나, 적정성 또는 효율성이 없다고 판단되면 이를 허가하지 않거나, 취소할 수 있다."}],"num":163,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a164","label":"제164조","title":"수입","paras":[{"k":"line","x":"본회 재정의 수입은 학생회비, 학교 지원금, 사업별 후원금, 그 밖에 수익금으로 한다."}],"num":164,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a165","label":"제165조","title":"학생회비","paras":[{"k":"hang","x":"① 학생회비는 일시납부·1회 납부를 원칙으로 한다. 단, 일시납부 하지 못할 경제적·사회적 또는 그 밖의 중대한 사유가 있는 경우 분할납부를 할 수 있다."},{"k":"hang","x":"② 집행위원회는 학생회비의 수입 및 지출과 관련된 집행내역을 매달 날짜를 정하여 공고하여야 한다."},{"k":"hang","x":"③ 학부 학생회비의 수입 중 반 학생회비에 할당되는 금액은 반 학생회 소속 학생회비 납부자 1인당 40,000원으로 한다."},{"k":"hang","x":"④ 학생총회 또는 학생대표자회는 매년 2학기 정기회의에서 학부 학생회비의 조정에 관하여 논의하여, 필요할 때는 인상·인하를 결정할 수 있다."}],"num":165,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제３절 회계·심의"},{"t":"art","id":"a166","label":"제166조","title":"회계연도","paras":[{"k":"line","x":"본회의 재정은 다음 각호의 기간으로 나누어 집행하고 결산한다."},{"k":"ho","x":"1. 제1분기: 2학기 종강일 다음 날부터 1학기 개강일 전날까지"},{"k":"ho","x":"2. 제2분기: 1학기 개강일부터 1학기 종강일까지"},{"k":"ho","x":"3. 제3분기: 1학기 종강일 다음 날부터 2학기 개강일 전날까지"},{"k":"ho","x":"4. 제4분기: 2학기 개강일부터 2학기 종강일까지"}],"num":166,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a167","label":"제167조","title":"학부운영위원회 심의","paras":[{"k":"hang","x":"① 학생회비를 사용하는 집행위원회 및 독립기구 등은 다음 각호에 따라 예산안·결산을 작성하여 학생총회 또는 학생대표자회 개의 예정일 7일 전까지 학부운영위원회에 제출하여야 한다."},{"k":"ho","x":"1. 1학기 정기회의: 작년도 4분기, 금년도 1분기의 결산과 금년도 2분기·3분기의 예산안"},{"k":"ho","x":"2. 2학기 정기회의: 금년도 2분기·3분기의 결산과 금년도 4분기, 익년도 1분기의 예산안"},{"k":"hang","x":"② 학부운영위원회는 제１항에 따른 예산안·결산 제출기한을 정하여 공고하고 예산안·결산 보고의 의무가 있는 기구에 개별적으로 통보하여야 한다."},{"k":"hang","x":"③ 학부운영위원회는 제１항에 따라 제출된 예산안·결산을 심의한다."}],"num":167,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a168","label":"제168조","title":"승인","paras":[{"k":"hang","x":"① 학생회비를 사용하는 집행위원회 및 독립기구 등은 제167조 제1항에 따라 학부운영위원회의 심의를 거친 예산안·결산을 학생총회 또는 학생대표자회에 보고한다."},{"k":"hang","x":"② 학생대표자회 또는 학생총회는 제１항에 따라 보고된 예산안·결산을 승인한다."},{"k":"hang","x":"③ 학생대표자회 또는 학생총회에서 승인된 예산안·결산은 공개되어야 한다."},{"k":"hang","x":"④ 각 기구는 학생총회 또는 학생대표자회 출석 구성원의 과반수에 의한 동의가 있으면 예산안·결산을 현장에서 수정 발의하여 재상정할 수 있다."}],"num":168,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a169","label":"제169조","title":"재심의","paras":[{"k":"hang","x":"① 다음 각호에 해당하는 경우, 학생총회 또는 학생대표자회는 출석 과반수의 찬성으로 해당 기구에의 학생회비 지급을 유보하고 학부운영위원회에서 재심의를 받도록 해야 한다. 재심의에서의 승인은 학부운영위원회 출석 3분의 2 이상의 결의에 의한다."},{"k":"ho","x":"1. 예산안·결산이 승인되지 못한 경우"},{"k":"ho","x":"2. 예산안·결산에 중대한 하자가 있는 경우"},{"k":"ho","x":"3. 심의 과정 중 절차상 문제가 발견된 경우"},{"k":"ho","x":"4. 판단자료 미비로 예산안·결산에 대한 심의가 불가능하거나 예산안·결산을 신뢰할 수 없을 경우"},{"k":"hang","x":"② 제１항에 해당하는 기구는 학생총회 또는 학생대표자회 개의일로부터 10일 이내에 수정안을 작성하여 학부운영위원회에 제출해야 한다."},{"k":"hang","x":"③ 학부운영위원회는 수정안을 지체 없이 심의하여 학생총회 또는 학생대표자회 개의일로부터 15일 이내에 결과를 공고한다."},{"k":"hang","x":"④ 제１항에 해당함에도 수정안을 학부운영위원회에 제출하지 않은 기구 혹은 제기된 문제를 개선하지 않은 채 수정안을 작성하여 제출한 기구는 책임자에 따라 각호 중 하나의 징계를 한다. 책임자란 불승인 결정에 직·간접적인 책임이 있는 대표자 및 기구의 구성원을 의미한다."},{"k":"ho","x":"1. 책임자가 현직일 때: 예산 지급액의 50% 삭감과 사과문·경위서 게재"},{"k":"ho","x":"2. 책임자가 전직일 때: 책임자의 사과문·경위서 게재"},{"k":"hang","x":"⑤ 배임, 횡령 사안 등 문제의 정도가 심각한 경우 학부운영위원회는 제4항의 징계와 함께 다음 각호의 조치를 함께 결정할 수 있다. 제3호의 경우 책임자와 학생회비가 불법하게 사용될 당시 대표자가 연대하여 책임을 져야 한다."},{"k":"ho","x":"1. 기구가 가지고 있는 학생회비 잔금 사용 중지"},{"k":"ho","x":"2. 기구가 가지고 있는 학생회비 잔금 전액 환수"},{"k":"ho","x":"3. 기구가 불법하게 사용한 학생회비 전액 반환"}],"num":169,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제8장 자치공간"},{"t":"art","id":"a170","label":"제170조","title":"목적","paras":[{"k":"line","x":"본회의 자치공간은 본회의 자치활동의 기초가 되는 토대로서, 회원의 교류 및 결속을 공고히 하고 회원을 보호하며 안정을 보장해주는 역할을 통해 창조적이고 진보적인 대학문화를 건설하는 데 기여함을 목적으로 한다."}],"num":170,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a171","label":"제171조","title":"자치공간","paras":[{"k":"hang","x":"① 본회의 자치공간은 다음 각호로 정한다."},{"k":"ho","x":"1. ｢자치공간등기부｣에 등기된 공간"},{"k":"ho","x":"2. 학부 학생회실"},{"k":"ho","x":"3. 법학관(구관) 각 반 학생회실, 각 자치단체실, 학생회창고, 코웍스"},{"k":"ho","x":"4. 기타 본회의 노력으로 확보·명도 받은 공간"},{"k":"hang","x":"② 본회의 각 기구 및 회원은 대내외적으로 자치공간을 이용, 분배, 회수, 보수, 개조할 관리 권한을 갖는다. 관리 권한이라 함은 각 사안의 원활한 운영을 위하여 배타적인 권리행사 및 집행을 할 수 있는 권원을 의미한다."}],"num":171,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a172","label":"제172조","title":"준자치공간","paras":[{"k":"hang","x":"① 본회의 지배·관리하에 있지 않지만, 학교의 승인을 얻어 본회 회원의 자유로운 이용이 보장된 공간을 준자치공간이라고 한다."},{"k":"hang","x":"② 준자치공간은 다음 각호로 정한다."},{"k":"ho","x":"1. CJ법학관 남학생 휴게실"},{"k":"ho","x":"2. CJ법학관 여학생 휴게실"},{"k":"ho","x":"3. CJ법학관 및 해송법학도서관 라운지"},{"k":"ho","x":"4. CJ법학관 및 해송법학도서관 스터디룸"},{"k":"ho","x":"5. 법학관(구관), 법학관(신관), CJ법학관 강의실"},{"k":"ho","x":"6. 그 밖의 기타 학생 편의시설"}],"num":172,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a173","label":"제173조","title":"의무","paras":[{"k":"line","x":"본회는 자치공간에 대해 다음 각호의 의무가 있다."},{"k":"ho","x":"1. 자치공간에 대한 본회의 자치권이 침해받지 않도록 수호"},{"k":"ho","x":"2. 자치공간의 안전 및 청결 유지"},{"k":"ho","x":"3. 자치공간 이용과 관련한 갈등 해결"},{"k":"ho","x":"4. 회원의 자치공간 이용 기회보장"}],"num":173,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a174","label":"제174조","title":"자치공간운영세칙","paras":[{"k":"line","x":"그 밖의 자치공간에 관한 자세한 내용은 「자유전공학부 자치공간운영세칙」으로 정한다."}],"num":174,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제9장 회칙·세칙·규칙"},{"t":"h","lv":3,"text":"제１절 회칙 개정"},{"t":"art","id":"a175","label":"제175조","title":"개정안 발의","paras":[{"k":"hang","x":"① 회칙 개정안은 다음 각호 중 하나에 따라 발의된다."},{"k":"ho","x":"1. 학부운영위원회의 출석 과반수에 의한 발의"},{"k":"ho","x":"2. 학부운영위원회 재적 위원 과반수의 연서에 따른 발의"},{"k":"ho","x":"3. 회원 10분의 1의 연서에 따른 발의"},{"k":"ho","x":"4. 회칙개정특별위원회에 의한 발의"},{"k":"hang","x":"② 연서에 따른 소집요구는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식을 준용하며, ｢고려대학교 총학생회 사무처리세칙｣에서 정한 사항이 포함되어야 한다."}],"num":175,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a176","label":"제176조","title":"개정안 공고","paras":[{"k":"line","x":"회칙 개정안이 발의되면 학부 학생회장은 다음 각호의 사항을 7일 이상 공고하여야 한다."},{"k":"ho","x":"1. 회칙 개정안의 제안이유와 주요 내용"},{"k":"ho","x":"2. 신·구조문 대비표"},{"k":"ho","x":"3. 제175조에 따른 회칙 개정안 발의자 명단"}],"num":176,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a177","label":"제177조","title":"개정안 심의","paras":[{"k":"hang","x":"① 제175조 제１항 제１호의 경우 회칙 개정을 위한 학생총회 또는 학생대표자회 개의에 앞서 학부운영위원회에서 개정안을 심의하거나, 별도의 공청회를 개최하여 개정안을 심의한다."},{"k":"hang","x":"② 개정안 심의 과정에는 축조심사와 찬반 토론이 포함되어야 한다."}],"num":177,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a178","label":"제178조","title":"개정 의결","paras":[{"k":"hang","x":"① 회칙 개정안이 발의되었을 때 본회 의결기구의 의장은 지체 없이 학생총회 또는 학생대표자회를 소집하여 회칙 개정안을 심의·의결한다."},{"k":"hang","x":"② 회칙 개정의 의결은 제23조 제３항에 따라 기명투표로 표결한다."},{"k":"hang","x":"③ 회칙 개정의 의결 요건은 제30조 제２항 및 제57조의2 제2항에 따른다."}],"num":178,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a179","label":"제179조","title":"개정안 정리","paras":[{"k":"line","x":"회칙 개정의 의결이 있은 후 저촉되는 조항·자구·숫자 그 밖의 기타 정리가 필요한 경우 학부운영위원회는 회칙 개정의 공포 전까지 이를 검토하여 정리할 수 있다. 단, 개정 의결된 회칙의 내용이나 취지를 변경하는 것은 허용되지 아니한다."}],"num":179,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a180","label":"제180조","title":"공포","paras":[{"k":"hang","x":"① 회칙 개정이 의결되면 학부 학생회장은 개정안 정리를 거쳐 3일 이내에 공포한다."},{"k":"hang","x":"② 회칙의 공포문에는 다음 각호의 사항이 포함되어야 한다."},{"k":"ho","x":"1. 회칙 개정안의 제안이유와 주요 내용"},{"k":"ho","x":"2. 신·구조문 대비표"},{"k":"ho","x":"3. 제175조에 따른 회칙 개정안 발의자 명단"},{"k":"ho","x":"4. 회칙 개정 찬성자 명단"},{"k":"hang","x":"③ 본조는 세칙과 규칙의 제정·개정·폐지에도 준용한다. 단, 세칙 제정의 공포 시에는 세칙의 제정 순서에 따라 번호를 붙여서 공포하며, 규칙 제정의 공포 시에는 제정의 근거가 되는 세칙별로 규칙의 제정 순서에 따라 번호를 붙여서 공포한다."}],"num":180,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제２절 세칙·규칙"},{"t":"art","id":"a181","label":"제181조","title":"세칙·규칙","paras":[{"k":"hang","x":"① 본회는 회칙에 따라 세칙을 제정·개정하고, 세칙에 따라 규칙을 제정·개정한다. 단, 일반규칙은 세칙에 근거를 두지 않고 제정·개정할 수 있다."},{"k":"hang","x":"② 회칙에 위반되는 세칙과 세칙에 위반되는 규칙은 그 위반되는 부분에 한정하여 효력이 없다."},{"k":"hang","x":"③ 회칙에 위반되는 산하기구의 자치규칙은 성립하지 아니하고, 그 위반되는 부분에 한하여 효력이 없다."}],"num":181,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a182","label":"제182조","title":"세칙의 제정·개정·폐지","paras":[{"k":"hang","x":"① 세칙은 회칙에서 위임한 사항과 회칙을 시행하기 위한 사항을 정하기 위하여 제정한다."},{"k":"hang","x":"② 세칙은 학생총회 또는 학생대표자회에서 제정·개정·폐지를 의결한다."},{"k":"hang","x":"③ 세칙의 제정·개정·폐지는 제175조를 준용한다."},{"k":"hang","x":"④ 세칙 개정안의 정리에 관하여서는 제179조를 준용한다."},{"k":"hang","x":"⑤ 세칙 제정 및 개정의 공포에 관하여서는 제180조를 준용한다."}],"num":182,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a183","label":"제183조","title":"세칙에 부수된 규칙의 제정·개정·폐지","paras":[{"k":"hang","x":"① 세칙에 부수된 규칙은 해당 세칙에서 위임한 사항과 해당 세칙을 시행하기 위한 사항을 정하기 위하여 제정한다."},{"k":"hang","x":"② 세칙에 부수된 규칙은 해당 세칙의 근거 규정에 따라 제정·개정·폐지된다."},{"k":"hang","x":"③ 세칙에 부수된 규칙의 공포에 관하여서는 제180조를 준용한다."}],"num":183,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a184","label":"제184조","title":"일반규칙의 제정·개정·폐지","paras":[{"k":"hang","x":"① 일반규칙은 다음 각호의 사항을 규율하기 위해 제정한다."},{"k":"ho","x":"1. 의결기구에 관한 사항"},{"k":"ho","x":"2. 집행기구에 관한 사항"},{"k":"ho","x":"3. 산하기구에 관한 사항"},{"k":"ho","x":"4. 독립기구에 관한 사항"},{"k":"ho","x":"5. 본회의 정기사업·비정기사업에 관한 사항"},{"k":"ho","x":"6. 회원의 권리·의무에 관한 사항"},{"k":"ho","x":"7. 자치단체에 관한 사항"},{"k":"ho","x":"8. 학교 시설 사용 등에 대한 회원 전체의 합의에 관한 사항"},{"k":"ho","x":"9. 학교 당국과의 합의에 관한 사항"},{"k":"ho","x":"10. 본회와 학내 각 단체 간의 합의에 관한 사항"},{"k":"ho","x":"11. 본회와 외부단체와의 합의에 관한 사항"},{"k":"ho","x":"12. 회칙의 특정 조문에 관한 추가적인 사항"},{"k":"ho","x":"13. 그 밖에 규칙으로 명문화하는 것이 필요하다고 인정되는 사항"},{"k":"hang","x":"② 일반규칙은 학부운영위원회가 제정·개정·폐지를 의결한다."},{"k":"hang","x":"③ 일반규칙의 공포에 관하여서는 제180조를 준용한다."}],"num":184,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제３절 해석"},{"t":"art","id":"a185","label":"제185조","title":"회칙 해석의 원칙","paras":[{"k":"hang","x":"① 회칙을 해석·적용함에 있어서는 해당 조항의 문맥적 의미와 회칙 전체의 논리적 체계성에 비추 어 본회의 민주적 운영이 저해되거나 회원의 권리가 부당하게 침해되지 않도록 주의하여야 한다."},{"k":"hang","x":"② 본회의 중요 사항과 회원의 권리·의무에 중대한 변화를 야기하는 회칙의 해석은 회원들을 상대로 의견을 수렴하기 위한 공청회를 개최할 수 있다."},{"k":"hang","x":"③ 세칙·규칙에 관하여서도 본조를 적용한다."}],"num":185,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"부칙","bu":true,"id":"bu1"},{"t":"free","paras":[{"k":"line","x":"이 회칙은 2021. 11. 13.부터 시행한다."}]}],"note":null},{"id":"hoechik-20230211","date":"2023.02.11","kind":"일부개정","title":"고려대학교 자유전공학부 학생회칙","subtitle":null,"history":[["2009. 03.","제정"],["2011. 05. 11.","일부개정"],["2013. 10. 30.","일부개정"],["2014. 03. 26.","일부개정"],["2014. 09. 22.","일부개정"],["2015. 03. 24.","일부개정"],["2015. 09. 22.","일부개정"],["2016. 08. 29.","전부개정"],["2017. 03. 02.","일부개정"],["2017. 05. 27.","전부개정"],["2017. 08. 19.","전부개정"],["2018. 10. 12.","전부개정"],["2021. 11. 13.","전부개정"],["2023. 02. 11.","일부개정"]],"pdf":"pdf/hoechik-20230211.pdf","pdfName":"고려대학교_자유전공학부_학생회칙(2023.02.11_일부개정).pdf","blocks":[{"t":"pre","title":"전문","paras":["정의를 추구하는 고려대학교의 역사적 사명과 함께 공동체를 선도하고 연대하는 자유전공학부는 창설 이래 이어져 온 민주적 전통과 자유·정의·진리를 좇는 본교의 교육 이념, 학문 및 사상에 대한 창조적 탐구 정신을 이어받아 자유전공학부의 주체적이고 자율적이며 민주적인 활동을 다짐하는 바이다. 이에 2009년 3월 제정되고 12차에 걸쳐 개정된 자유전공학부 학생회칙을 자유전공학부 학생대표자회의의 의결을 거쳐 개정한다."],"date":null},{"t":"h","lv":2,"text":"제1장 총칙"},{"t":"art","id":"a1","label":"제1조","title":"명칭","paras":[{"k":"line","x":"본회는 고려대학교 자유전공학부 학생회라 칭한다."}],"num":1,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a2","label":"제2조","title":"목적","paras":[{"k":"hang","x":"① 본회는 민주적이고 자율적인 학생자치활동을 통하여 회원 간의 결속을 강화하고 회원의 권익 신장을 도모하며 자유로운 진리의 탐구와 창조적이고 진보적인 대학문화의 건설을 추구하여 사회발전에 능동적으로 기여한다."},{"k":"hang","x":"② 본회는 시대의 불의에 맞서 사회적 연대를 구축하고 침해된 정의의 회복을 위해 대내외에서 주체적으로 행동한다."},{"k":"hang","x":"③ 본회는 본회의 자산 및 자치공간과 회원이 지닌 권리를 보호한다."},{"k":"hang","x":"④ 본회는 법률적 기초소양 및 다양한 영역에서의 복합적 전문성을 갖춘 공적 영역의 선도적 지도자를 양성한다는 교육목적을 달성하기 위해 노력하며, 제1전공이 다른 회원들 간의 교류를 장려한다."}],"num":2,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a3","label":"제3조","title":"위치","paras":[{"k":"line","x":"본회는 서울특별시 성북구 안암동 고려대학교 법학관(구관), 법학관(신관) 및 CJ법학관에 위치한다."}],"num":3,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a4","label":"제4조","title":"회원","paras":[{"k":"hang","x":"① 본회의 회원은 입학·재입학·편입학·소속변경 등으로 고려대학교 자유전공학부 소속이 된 자를 원칙으로 한다."},{"k":"hang","x":"② 졸업, 자퇴, 퇴학 등으로 고려대학교 서울캠퍼스 학부과정 소속이 아니게 된 자 및 총학생회 제명으로 인해 총학생회 회원 직을 박탈당한 자는 그 즉시 회원 자격을 잃으며 정학 등의 사유로 등교가 정지된 자는 그 기간 회원 자격이 정지된다."},{"k":"hang","x":"③ 제2항의 경우 회원의 자격이 부당하게 정지, 박탈된 자는 학부운영위원회의 출석 3분의 2 이상에 해당하는 결의로 회원 지위를 회복할 수 있다."},{"k":"hang","x":"④ 본회의 회원 중 재학 중인 자는 다음 각호의 기간 동안 본회의 정회원이 된다. 단, 재학 중 휴학 한 자는 그 즉시 정회원 자격을 상실하고 휴학생 회원이 된다."},{"k":"ho","x":"1. 1학기 재학생 : 1학기 개강일로부터 2학기 개강일 전일"},{"k":"ho","x":"2. 2학기 재학생 : 2학기 개강일로부터 이듬해 1학기 개강일 전일"},{"k":"hang","x":"⑤ 본회의 회원 중 휴학한 자는 휴학생 회원, 수료한 자는 수료생 회원이라고 하며, 선거권을 지닐 수 없다. 단, 휴학생 회원과 수료생 회원 중에서 다음 각호의 등록기간에 등록 절차를 이행한 자는 남은 기간 정회원이 된다. 자유전공학부 학부·반 학생회장단 선거의 특수성을 고려하여 선거 후보자 등록 마감일 다음 날부터 당선 공고일까지는 정회원 등록을 할 수 없다. 그 밖에 정회원 등록에 관한 사항은 규칙으로 정한다."},{"k":"ho","x":"1. 1학기 정회원 등록기간: 1학기 개강일부터 2학기 개강일 전날까지"},{"k":"ho","x":"2. 2학기 정회원 등록기간: 2학기 개강일부터 이듬해 1학기 개강일 전날까지"},{"k":"hang","x":"⑥ 본회의 회원 중에서 신입생 회원과 두 학번 이상 차이가 나는 회원은 고학번 회원이라고 한다."},{"k":"hang","x":"⑦ 본회의 회원 중에서 다음 각호에 해당하는 회원은 신입생 회원이라고 한다."},{"k":"ho","x":"1. 고려대학교에 입학한 지 2학기가 지나지 않은 회원"},{"k":"ho","x":"2. 편입학·소속변경 등으로 자유전공학부 재학생이 된 지 2학기가 지나지 않은 회원"},{"k":"hang","x":"⑧ 회원 여부에 시비가 있을 시 자유전공학부 학부운영위원회는 자유전공학부 행정실을 통해 확인한 재학생 명단, 휴학생 명단을 참고하여 회원 여부를 판단한다."}],"num":4,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a5","label":"제5조","title":"회원의 권리와 의무","paras":[{"k":"hang","x":"① 본회의 회원은 성별·연령·장애·병력·피부색·용모 등 신체조건, 인종·언어·출신국가·출신민족·출신지역 등 출생지, 혼인상태·출산형태 등 가족 형태, 종교·정치적견해·성적지향·성별정체성·출신학교·학력·전공·재산 등 사회적 신분에 의하여 차별을 받지 아니한다."},{"k":"hang","x":"② 본회의 회원은 본회의 모든 자치활동에 참여할 권리와 회칙에 근거한 선거권, 피선거권을 가진다."},{"k":"hang","x":"③ 본회의 회원은 회칙에 따라 본회의 활동과 운영 전반에 관하여 의견을 개진할 권리와 본회를 부인하거나 정당한 학생자치활동을 침해하는 것에 대해 저항할 권리를 가진다."},{"k":"hang","x":"④ 본회의 회원은 집회·결사의 자유 및 자유로운 종교·정치 활동에 대한 권리를 가진다."},{"k":"hang","x":"⑤ 본회의 회원은 본회의 모든 활동 및 재정 운영에 대해 보고를 받을 권리를 가진다."},{"k":"hang","x":"⑥ 본회의 회원은 본회가 지니는 급부를 적절한 시기에 제공받을 권리를 가진다."},{"k":"hang","x":"⑦ 본회의 회원은 자치공간 및 본회 자산을 향유할 권리를 가진다."},{"k":"hang","x":"⑧ 본회의 회원은 회칙을 준수할 의무를 지닌다."},{"k":"hang","x":"⑨ 본회의 회원은 본회가 결정한 사항을 준수할 의무를 지닌다."},{"k":"hang","x":"⑩ 본회의 회원은 회비를 납부할 의무를 지닌다."},{"k":"hang","x":"⑪ 본회의 회원은 본회의 자산을 보호할 의무를 지닌다."}],"num":5,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a6","label":"제6조","title":"본회와 각 기구의 의무","paras":[{"k":"hang","x":"① 본회와 본회의 각 기구는 고학번 회원의 본회와 본회의 각 기구 활동 참여를 보장해야 하며, 회원 간 원활한 교류를 위해 노력해야 한다."},{"k":"hang","x":"② 본회와 본회의 각 기구는 신입생 회원이 학번·연령으로 인해 부당한 대우를 받지 않도록 노력해야 한다."},{"k":"hang","x":"③ 본회와 본회의 각 기구는 전조에 열거된 회원의 권리가 대내외적으로 침해받지 않도록 항상 노력하여야 하며, 회원의 권리가 침해될 때 이를 적극적으로 수호하여야 한다."},{"k":"hang","x":"④ 본회와 본회의 각 기구는 본회와 각 기구의 자산 및 자치공간을 보호·관리하여야 한다."}],"num":6,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a7","label":"제7조","title":"구성","paras":[{"k":"line","x":"본회는 민주적이고 효율적인 운영을 통한 학생자치의 실현을 위하여 다음 각호의 의결기구, 집행기구, 산하기구, 독립기구를 둔다."},{"k":"ho","x":"1. 의결기구: 학생총회, 학생대표자회, 학부운영위원회, 비상대책위원회"},{"k":"ho","x":"2. 집행기구: 학부 학생회장단, 집행위원회"},{"k":"ho","x":"3. 산하기구: 반 학생회, 자치단체, 특별위원회"},{"k":"ho","x":"4. 독립기구: 선거관리위원회, 투표관리위원회, 학생자치장학금위원회, 학생홍보대사, 소수자인권위원회"}],"num":7,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a8","label":"제8조","title":"학교운영 참여","paras":[{"k":"hang","x":"① 본회의 활동과 관련하여 학교 당국과의 협의 또는 조정이 필요한 경우 본회의 각 기구는 학교운영에 적극적으로 참여하며 필요 시 학교 당국에 자료제출을 요청할 수 있다."},{"k":"hang","x":"② 본회는 다음 각호의 경우 학교의 운영에 적극 참여하여 의견을 개진하고 관련 진행 상황 및 결정 사항을 회원에게 공고하여야 한다."},{"k":"ho","x":"1. 본회의 활동과 관계된 회원의 징계 사항에 관해 회원을 변호할 필요가 있는 경우"},{"k":"ho","x":"2. 본회의 회원의 자치활동과 권익 보호가 필요한 경우"},{"k":"ho","x":"3. 자유전공학부 발전 방향 설정, 학제개편, 학칙개정 등의 임박하거나 이미 결정된 학교의 정책 및 결정사항이 본회 회원의 이익에 중대한 변화를 야기할 경우"},{"k":"ho","x":"4. 그 밖에 본회의 목적과 관련된 중요 사항"}],"num":8,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a9","label":"제9조","title":"대표자의 책임","paras":[{"k":"line","x":"학생회장단, 학부운영위원, 학생대표자회 대의원은 본회의 대표자로서 본회의 민주적이고 효율적인 운영과 각 기구의 협력을 통해 그 운영 목적을 달성할 수 있도록 주어진 역할을 책임 있게 수행하여야 한다."}],"num":9,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a10","label":"제10조","title":"겸직 금지","paras":[{"k":"hang","x":"① 본회의 회원은 다음 각호의 직을 동시에 2개 이상 가질 수 없다."},{"k":"ho","x":"1. 학부 학생회장과 부학생회장"},{"k":"ho","x":"2. 반 학생회장과 부학생회장"},{"k":"ho","x":"3. 고학번 대표 및 신입생 대표"},{"k":"ho","x":"4. 각 자치단체장"},{"k":"ho","x":"5. 그 밖에 학부운영위원 자격이 부여되는 직책"},{"k":"hang","x":"② 집행위원은 반 학생회장의 직을 겸직하기 위해서는 학생대표자회의 출석 과반수에 해당하는 결의로 인준을 받아야 한다."},{"k":"hang","x":"③ 제１항 각호의 직을 동시에 2개 이상 갖게 되었을 시 즉시 마지막에 갖게 된 직을 제외한 나머지 직에서는 해임된 것으로 본다. 단, 제1항 제1호의 직은 선후관계를 불문하고 그 직을 유지하는 것으로 본다."}],"num":10,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a11","label":"제11조","title":"사무 처리","paras":[{"k":"hang","x":"① 본회 각 기구의 사무 처리는 간소화·표준화·정보화를 통해 효율적으로 이루어져야 한다."},{"k":"hang","x":"② 정확과 신속을 기하고 책임의 소재를 명백히 밝히기 위하여 본회의 사무 처리와 대표자의 행위는 문서로써 함을 원칙으로 한다."},{"k":"hang","x":"③ 본회에서 장기간에 걸쳐 반복적으로 사용하는 문서로서 정형화할 수 있는 문서는 특별한 사유가 없으면 서식으로 정하여 사용한다."},{"k":"hang","x":"④ 회칙에서 공고하도록 한 사항은 회원들이 해당 공고를 쉽게 접할 수 있도록 구법학관 자유전공학부 학생회 게시판, 신법학관 자유전공학부 행정실 게시판 등 오프라인 게시판과, 자유전공학부 홈페이지 학생회 게시판 등 각종 온라인 게시판에 게시하여야 하며, 가시성이 확보되도록 공고의 모양을 정하여야 한다."},{"k":"hang","x":"⑤ 그 밖에 사무 처리에 관한 세부적인 사항은 학부운영위원회의 출석 과반수에 해당하는 결의로 ｢고려대학교 총학생회 사무처리세칙｣을 준용한다."}],"num":11,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a12","label":"제12조","title":"기록물 관리","paras":[{"k":"hang","x":"① 본회의 모든 활동은 기록되고, 기록물이 각 활동의 근거가 되는 것을 원칙으로 한다."},{"k":"hang","x":"② 본회는 지속적이고 체계적인 기록물 관리를 위해 적극 노력해야 하며, 기록물 관리기관이 효율적으로 기록물을 관리할 수 있도록 지원해야 한다."},{"k":"hang","x":"③ 기록물의 생산·수집 이후에는 임의로 수정할 수 없으며 훼손하거나 폐기할 수 없다. 단, 각호에 해당하는 경우 각호에서 정한 목적의 제한된 범위 내에서 게시물을 수정할 수 있다."},{"k":"ho","x":"1. 속기록의 내용이 실제 발언과 부합하지 않은 것을 7일 이내에 발견했을 시"},{"k":"ho","x":"2. 학생회 페이지, 그룹, 자유전공학부 홈페이지 게시판 등에 올린 게시물의 탈·오자 수정이 필요할 시"},{"k":"ho","x":"3. 학생회 페이지, 그룹, 자유전공학부 홈페이지 게시판 등에 올린 게시물의 내용에 중대한 하자를 발견하여 하자의 치유를 위한 수정 및 비공개 조치가 필요할 시"},{"k":"ho","x":"4. 같은 시각에 중복게시물을 올려 비공개 조치가 필요할 시"},{"k":"hang","x":"④ 본회가 생산·수집하는 모든 기록물은 회원들에게 공개되어야 하고 본회의 행정 사무와 의사 결정, 학술 연구 등의 활동을 위해 언제든지 참고할 수 있도록 투명하게 관리되어야 한다."},{"k":"hang","x":"⑤ 본회는 회원의 개인정보를 보호해야 할 의무가 있다. 본회가 수집한 개인정보는 당사자의 동의를 얻었거나 명확한 근거를 가진 정당한 목적이 있을 때만 열람·활용할 수 있다."},{"k":"hang","x":"⑥ 본회의 회원 또는 학술적 목적과 공익을 위해 본회의 기록물을 활용하려는 자는 본회의 모든 기록물에 대한 접근권이 있으며 정보공개청구로 기록물을 열람·활용할 수 있다."},{"k":"hang","x":"⑦ 본회의 각 기구는 본회의 회원 또는 학술적 목적과 공익을 위해 본회의 기록물을 활용하려는 자의 정보공개청구를 거부할 수 없다. 단, 다음 각호에 해당할 때는 학부운영위원회의 출석 과반수에 해당하는 결의로 일부만 공개하도록 할 수 있다."},{"k":"ho","x":"1. 본회의 회원이 아닌 자가 정보공개를 청구한 때"},{"k":"ho","x":"2. 정보의 공개로 인해 특정 회원의 개인정보 유출이 우려될 때"},{"k":"ho","x":"3. 정보의 공개가 본회 회원의 이익의 심각한 감소를 초래할 때"},{"k":"ho","x":"4. 기타 공익적 목적이 있을 때"},{"k":"hang","x":"⑧ 그 밖에 기록물 관리에 관한 세부적인 사항은 학부운영위원회의 출석 과반수에 해당하는 결의로 ｢고려대학교 총학생회 기록물관리세칙｣을 준용한다."}],"num":12,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a13","label":"제13조","title":"준용","paras":[{"k":"hang","x":"① 본회는 본회의 상위기구의 회칙, 세칙 및 규칙을 준용할 수 있다."},{"k":"hang","x":"② 제1항에 해당하는 결정은 준용에 관해 특별한 요건이 없는 경우, 학생총회의 출석 과반수, 학생대표자회의 출석 과반수 또는 학부운영위원회의 출석 과반수에 해당하는 결의로 한다."}],"num":13,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a14","label":"제14조","title":"세칙","paras":[{"k":"line","x":"본회는 회칙에 의거해 세칙을 제정 및 개정한다."}],"num":14,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제2장 의결기구"},{"t":"h","lv":3,"text":"제１절 통칙"},{"t":"art","id":"a15","label":"제15조","title":"기본이념","paras":[{"k":"line","x":"본회의 의결기구는 본회를 대표하는 의사를 결정하는 기구로서 민주적이고 공정하며 효율적인 절차에 따라 운영되어야 한다."}],"num":15,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a16","label":"제16조","title":"의결기구의 위계","paras":[{"k":"hang","x":"① 본회의 의결기구는 학생총회, 학생대표자회, 학부운영위원회 순으로 위계를 지닌다."},{"k":"hang","x":"② 다른 위계에 속한 의결기구 간의 의사결정 내용이 상이할 시 하위 의결기구의 의사결정 내용은 상위 의결기구의 의사결정 내용과 합치되는 범위 내에서 효력을 지닌다."},{"k":"hang","x":"③ 하위 의결기구에서 의결할 수 있도록 한 사항은 해당 의결기구보다 상위 의결기구에서도 의결할 수 있다."}],"num":16,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a17","label":"제17조","title":"회기","paras":[{"k":"line","x":"본회 의결기구의 회기는 다음 각호의 기간으로 나눈다."},{"k":"ho","x":"1. 제1회기: 2학기 종강일 다음 날부터 1학기 개강일 전날까지"},{"k":"ho","x":"2. 제2회기: 1학기 개강일부터 1학기 종강일까지"},{"k":"ho","x":"3. 제3회기: 1학기 종강일 다음 날부터 2학기 개강일 전날까지"},{"k":"ho","x":"4. 제4회기: 2학기 개강일부터 2학기 종강일까지"}],"num":17,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a18","label":"제18조","title":"의장","paras":[{"k":"hang","x":"① 본회 의결기구의 의장은 학부 학생회장으로 함을 원칙으로 한다. 단, 학부 학생회장 사고 시 학부 부학생회장이 그 직을 대신하며, 학부 학생회장과 학부 부학생회장이 모두 사고이거나, 학부 학생회장단 모두 또는 그중 한 명에 대한 탄핵 안건, 탄핵안 학생총투표 발의 안건이 상정된 경우 또는 기타 학부 학생회장단의 신상과 밀접한 관련이 있는 경우 학생회장단을 제외한 학부운영위원 중 한 명이 그 직을 대신한다."},{"k":"hang","x":"② 의장은 본회 의결기구를 대표하고 의사를 정리하며 질서를 유지하고 사무를 감독한다."},{"k":"hang","x":"③ 의장은 본회 절차에 따라 공정하고 효율적으로 회의를 진행하여야 한다."}],"num":18,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a19","label":"제19조","title":"사무·재정","paras":[{"k":"hang","x":"① 의결기구의 사무 처리는 집행위원회가 담당하며 학부운영위원회는 집행기구의 원활한 사무 처리를 감시·감독할 의무를 지닌다."},{"k":"hang","x":"② 본회는 의결기구의 원활한 운영을 위한 재원을 마련해야 한다."},{"k":"hang","x":"③ 집행위원회는 속기의 방법으로 회의록을 작성하고 다음 사항을 기재해야 한다."},{"k":"ho","x":"1. 회의 장소"},{"k":"ho","x":"2. 개회, 회의 중지와 산회의 일시"},{"k":"ho","x":"3. 개회 당시와 안건 의결 당시의 출석 대의원 명단"},{"k":"ho","x":"4. 부의 안건의 제목 및 내용"},{"k":"ho","x":"5. 발언자와 의사 표명의 내용"},{"k":"ho","x":"6. 표결 결과 (기명투표의 경우 각 대의원의 표결 사항을 기재)"},{"k":"ho","x":"7. 의장 또는 각 의결기구가 필요하다고 인정하는 사항"},{"k":"hang","x":"④ 의장은 개의일로부터 3일 이내에 제3항의 회의록을 공개하고 회의결과를 공고함을 원칙으로 한다. 단, 필요한 경우 그 기한을 7일까지 연장할 수 있다."}],"num":19,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a20","label":"제20조","title":"긴급한 사항","paras":[{"k":"hang","x":"① “긴급한 사항”이란 회의 소집 과정을 생략해서라도 긴급하게 의사를 결정해야 할 사항을 의미한다."},{"k":"hang","x":"② 긴급한 사항에 대한 해석은 각호의 목적 사항으로 제한한다."},{"k":"ho","x":"1. 본회의 활동과 관계된 회원의 징계 사항에 관해 변호가 필요할 경우"},{"k":"ho","x":"2. 본회 회원의 이익에 중대한 변화를 야기하는 자유전공학부 발전 방향 설정, 학제개편, 학칙개정 등의 학교 결정이 임박해 있거나 이미 결정된 경우"},{"k":"ho","x":"3. 그 밖에 본회의 목적과 관련된 중요 사항"},{"k":"hang","x":"③ 긴급한 사항이 있을 시 본회 의결기구 의장의 소집요구 없이도 학부운영위원회의 출석 과반수에 해당하는 결의로 임시학생총회 또는 임시학생대표자회를 소집할 수 있다."}],"num":20,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a21","label":"제21조","title":"안건의 발의","paras":[{"k":"hang","x":"① 안건 발의는 각 의결기구에서 정한 발의 요건에 따른다."},{"k":"hang","x":"② 안건 발의는 소집요구와 함께 이루어져야 한다. 단, 소집공고부터 산회 전까지 발의된 추가 안건에 대해서는 재적 구성원 과반수의 출석과 출석 구성원 과반수에 해당하는 결의로 한다."}],"num":21,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a22","label":"제22조","title":"안건의 의결","paras":[{"k":"hang","x":"① 각 의결기구의 재적 구성원 과반수의 출석과 출석 구성원 과반수에 해당하는 결의로 안건을 의결한다. 가부동수 및 찬성이 과반에 미치지 못할 경우 부결된 것으로 본다."},{"k":"hang","x":"② 안건의 의결 시 의결요건을 정하는 기준이 되는 출석 구성원 수는 각 안건의 의결 당시 집계된 구성원 명단을 기준으로 계산한다."},{"k":"hang","x":"③ 의결기구의 의결권은 구성원이 평등하게 가지며 직접 출석하여 행사하여야 한다."}],"num":22,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a23","label":"제23조","title":"안건의 표결","paras":[{"k":"hang","x":"① 표결은 기명으로 함을 원칙으로 한다."},{"k":"hang","x":"② 중요한 안건으로써 의장 또는 회원이 제의하고 의결기구 재적 구성원 3분의 2 이상에 해당하는 결의가 있으면 무기명으로 표결할 수 있다."},{"k":"hang","x":"③ 다음 각호의 사항에 관한 의결은 반드시 기명투표로 표결하여야 한다."},{"k":"ho","x":"1. 제40조 제１항의 회칙 개정에 관한 사항"},{"k":"ho","x":"2. 제40조 제２항의 세칙 제정·개정·폐지에 관한 사항"},{"k":"hang","x":"④ 다음 각호의 사항에 관한 의결은 반드시 무기명투표로 표결하여야 한다."},{"k":"ho","x":"1. 제35조 학부 학생회장단 탄핵에 관한 사항"},{"k":"ho","x":"2. 제36조 제2항 집행위원 해임에 관한 사항"},{"k":"ho","x":"3. 제39조 제1항 및 제２항의 학부 학생회비 지급에 관한 사항"},{"k":"hang","x":"⑤ 의장은 안건에 대한 이의의 유무를 물어서 이의가 없다고 인정한 때에는 가결되었음을 선포할 수 있다. 그러나 이의가 있는 안건일 경우 또는 무기명표결을 요하는 안건의 경우 반드시 표결하여야 한다."},{"k":"hang","x":"⑥ 의장 또는 회원의 제의와 출석 과반수의 찬성으로 전자투표에 의한 기록표결을 시행할 수 있다."}],"num":23,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a24","label":"제24조","title":"방청·발언권","paras":[{"k":"hang","x":"① 본회의 회원은 각 의결기구를 방청할 수 있다."},{"k":"hang","x":"② 본회의 회원은 각 의결기구에서 발언할 수 있는 권리를 가진다."},{"k":"hang","x":"③ 의장은 질서 유지 및 효율적인 의사 진행을 위해 방청인 수를 제한하거나 회원의 발언권을 제한할 수 있으며, 회의장 안의 질서를 현저히 방해하는 방청인의 경우 퇴장을 명할 수 있다."},{"k":"hang","x":"④ 의결기구의 구성원석과 방청인석은 구분이 되도록 배치한다."}],"num":24,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a25","label":"제25조","title":"회의진행세칙","paras":[{"k":"line","x":"그 밖에 의결기구의 회의 진행에 관한 사항은 각 의결기구의 출석 과반수에 해당하는 결의로 ｢고려대학교 총학생회 회의진행세칙｣을 준용한다."}],"num":25,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제２절 학생총회"},{"t":"art","id":"a26","label":"제26조","title":"지위 및 구성","paras":[{"k":"line","x":"학생총회는 본회의 최고의결기구로 본회의 회원 전원으로 구성한다."}],"num":26,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a27","label":"제27조","title":"소집요건","paras":[{"k":"hang","x":"① 학생총회 임시회는 다음 각호 중 하나에 의해 의장이 소집한다."},{"k":"ho","x":"1. 학부운영위원회의 소집요구"},{"k":"ho","x":"2. 학생대표자회의 소집요구"},{"k":"ho","x":"3. 회원 50명 이상의 연서에 따른 소집요구"},{"k":"ho","x":"4. 제90조에 따라 발의된 학부 학생회장단 사퇴 허가 요청"},{"k":"ho","x":"5. 제91조에 따른 학부 학생회장단 탄핵 발의"},{"k":"ho","x":"6. 제175조에 따른 회칙 개정안 발의"},{"k":"hang","x":"② 연서에 따른 소집요구는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식에 의하여야 하며, ｢고려대학교 총학생회 사무처리세칙｣에서 정한 사항이 포함되어야 한다."},{"k":"hang","x":"③ 연서에 따른 소집요구가 있으면 학부운영위원회는 지체 없이 학생총회 개의일을 결정한다. 이때 개의일은 소집요구 서식에 기재된 개의 희망일로 함을 원칙으로 하되 변경할 때는 학부운영위원의 출석 3분의 2 이상에 해당하는 결의로 한다. 단, 이 경우에도 개의 희망일과 2주 이상 차이가 나서는 안 된다."}],"num":27,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a28","label":"제28조","title":"소집 공고","paras":[{"k":"hang","x":"① 학생총회 의장은 학생총회의 소집을 개의일 7일 전에 공고하여야 한다."},{"k":"hang","x":"② 공고문에는 다음 각호의 사항을 명시하여야 한다."},{"k":"ho","x":"1. 회의 시작 일시"},{"k":"ho","x":"2. 회의 장소"},{"k":"ho","x":"3. 안건과 안건에 대한 설명"}],"num":28,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a29","label":"제29조","title":"자료의 사전 배포","paras":[{"k":"line","x":"학생총회 의장은 학생총회 회의 개의 5일 전까지 제출된 안건과 그에 관한 설명, 집행위원회 등의 보고·인준 사항, 각 기구의 학생회비 예산안·결산 등이 포함된 자료집을 회원들을 대상으로 배포하여야 한다. 배포는 책자 형태로 제작하여 비치하는 방법과 전산화된 형태의 문서로 제작하여 온라인에 게시하는 방법으로 한다."}],"num":29,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a30","label":"제30조","title":"개의·의결요건","paras":[{"k":"hang","x":"① 학생총회는 회원 7분의 1 이상의 출석으로 개의하고, 출석 과반수에 해당하는 결의로 의결한다."},{"k":"hang","x":"② 다음 각호의 사항은 재적 회원 7분의 1 이상의 출석 및 출석 회원 3분의 2 이상에 해당하는 결의로 의결한다."},{"k":"ho","x":"1. 제35조의 학부 학생회장단 탄핵안에 관한 사항"},{"k":"ho","x":"2. 제39조 제３항의 학부 학생회비 인상·인하에 관한 사항"},{"k":"ho","x":"3. 제40조 제１항의 회칙 개정에 관한 사항"},{"k":"hang","x":"③ 본회는 학생총회의 개의 7일 전까지 7일 이상의 인권침해사건 신고 기간을 두고, 본회 회원을 대상으로 한 인권침해 사건이 있었는지 조사하여야 한다."}],"num":30,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a31","label":"제31조","title":"안건","paras":[{"k":"hang","x":"① 학생총회의 안건은 다음 각호의 방법으로 상정할 수 있다."},{"k":"ho","x":"1. 학부운영위원회의 출석 과반수에 해당하는 결의"},{"k":"ho","x":"2. 학생대표자회의 출석 과반수에 해당하는 결의"},{"k":"ho","x":"3. 회원 50명 이상의 연서에 따른 임시회의 소집요구와 함께 발의"},{"k":"ho","x":"4. 제90조에 따라 발의된 학부 학생회장단 사퇴 허가 요청"},{"k":"ho","x":"5. 제91조에 따른 학부 학생회장단 탄핵 발의"},{"k":"ho","x":"6. 제175조에 따른 회칙 개정안 발의"},{"k":"hang","x":"② 학생총회는 다음 각호의 안건을 심의·의결한다."},{"k":"ho","x":"1. 학부운영위원회가 소집요구와 함께 상정한 안건"},{"k":"ho","x":"2. 회원 50명 이상의 연서에 따른 소집요구와 함께 발의된 안건"},{"k":"ho","x":"3. 제90조에 따라 발의된 학부 학생회장단 사퇴 허가 안건"},{"k":"ho","x":"4. 제91조에 따른 학부 학생회장단 탄핵 안건"},{"k":"ho","x":"5. 제36조 제2항에 따른 집행위원 해임 안건"},{"k":"ho","x":"6. 제175조에 따라 발의된 회칙 개정안건"},{"k":"ho","x":"7. 본회의 활동에 필요한 각종 세칙 제정·개정안건"},{"k":"ho","x":"8. 회비의 인상·인하에 관한 안건"},{"k":"ho","x":"9. 본회의 사업계획과 정책의 기본방향에 대한 논의 안건"},{"k":"ho","x":"10. 본회의 예산·결산의 심의 및 승인에 관한 안건"},{"k":"ho","x":"11. 본회의 회계 및 사업 전반에 대한 감사에 관한 안건"},{"k":"ho","x":"12. 학생활동 및 학생신분에 관한 학칙 개정 요구안에 관한 안건"},{"k":"ho","x":"13. 제36조 제1항에 따른 집행위원장 및 집행위원 인준에 관한 안건"},{"k":"ho","x":"14. 회원 전체 명의로 소송을 진행할 경우 해당 소송에 관한 안건"},{"k":"ho","x":"15. 자유전공학부의 자치공간과 기타물품 회수 및 분배에 관한 안건"},{"k":"ho","x":"16. 학생총투표 실시 및 안건 상정에 관한 안건"},{"k":"ho","x":"17. 의결기구 산하의 특별위원회 설립에 관한 안건"},{"k":"ho","x":"18. 제107조에 따른 자치단체 인준에 관한 안건"},{"k":"ho","x":"19. 제169조 제4항 및 제5항에 의한 징계에 관한 안건"},{"k":"hang","x":"③ 학생총회는 본회를 폐지하는 결의를 할 수 없다."}],"num":31,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a32","label":"제32조","title":"안건 위임","paras":[{"k":"hang","x":"① 학생총회는 회기 중 처리하지 못한 안건은 출석 인원의 3분의 2 이상의 찬성으로 학생대표자회의에 위임할 수 있다. 단, 학생총회가 개의되지 않아 처리하지 못한 안건은 자동으로 학생대표자회에 위임된다."},{"k":"hang","x":"② 제31조 제2항 제4호, 제35조에서 규정하고 있는 학부 학생회장단 탄핵 안건은 하위기구로 위임할 수 없으며, 학생총회에 의하지 않고서는 오직 학생총투표로서만 처리할 수 있다."}],"num":32,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a33","label":"제33조","title":"결정·집행 사항 변경에 관한 사항","paras":[{"k":"line","x":"학생총회는 산하 학부·반 운영위원회, 학부·반 학생회장단과 학부·반 집행위원회의 결정·집행 사항을 변경 또는 취소할 수 있다."}],"num":33,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a34","label":"제34조","title":"학부 학생회장단 사퇴 허가에 관한 사항","paras":[{"k":"line","x":"학생총회는 학부 학생회장 또는 학부 부학생회장이 제90조에 따라 사퇴의 허가를 요청할 때 허가 여부를 심의·의결한다."}],"num":34,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a35","label":"제35조","title":"학부 학생회장단 탄핵에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 학부 학생회장단에 대한 탄핵안이 상정될 경우 학부 학생회장단에 대한 탄핵을 결정할 수 있다."},{"k":"hang","x":"② 학생총회는 학생회장단 탄핵과 관련된 절차가 준수되었는지, 탄핵 이유가 사실에 기반하고 있는지 성실히 심사할 의무를 지닌다."},{"k":"hang","x":"③ 학생총회는 출석 3분의 2 이상에 해당하는 결의로 학부 학생회장단 탄핵 결정 대신 동일 안건을 학생총투표 안건으로 상정할 수 있다."},{"k":"hang","x":"④ 학부 학생회장단 탄핵안 발의에 관한 절차는 제91조를 따른다."}],"num":35,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a36","label":"제36조","title":"집행위원회에 관한 사항","paras":[{"k":"hang","x":"① 집행위원회는 다음 각호의 사항에 관하여 학부운영위원회의 사전 인준을 거친 후 학생총회에 보고하여 인준받아야 한다. 단, 제２호와 제３호의 사항에 관하여 학부운영위원회의 사전 인준이 있으면 해당 안건을 학생총회에서 심의하기 전까지 해당 결정은 효력을 지닌다."},{"k":"ho","x":"1. 사업계획과 정책의 기본방향"},{"k":"ho","x":"2. 집행위원장과 집행위원의 임명"},{"k":"ho","x":"3. 산하 국서의 신설·폐지와 변경"},{"k":"hang","x":"② 학생총회는 집행위원의 해임을 의결할 수 있다."}],"num":36,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a37","label":"제37조","title":"감사에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 본회 집행기구, 산하기구, 독립기구의 사업 전반에 대하여 감사를 시행할 수 있다."},{"k":"hang","x":"② 학생총회는 감사에 필요하다고 인정될 때 해당 기구의 대표자 혹은 사업담당자를 출석시켜 진술을 청취할 수 있다. 또한, 관련 자료의 제출을 요구할 수 있다."},{"k":"hang","x":"③ 학생총회는 특정 집행기구, 산하기구의 감사를 목적으로 하는 감사위원회를 학생총회 산하에 설치할 수 있다. 감사위원회는 학생총회의 결정에 따라 감사 활동을 진행한 후 그 결과를 우선적으로 학부운영위원회에 보고한 후, 학생총회에 최종 보고하여야 한다."}],"num":37,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a38","label":"제38조","title":"징계에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 회원, 집행위원, 학부운영위원회 위원, 학생대표자회 대의원, 독립기구 및 산하기구가 본 회칙·세칙·규칙을 위반할 때 징계할 수 있다."},{"k":"hang","x":"② 회원의 징계에 대한 자세한 사항은 ｢고려대학교 자유전공학부 징계 세칙｣을 따른다."}],"num":38,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a39","label":"제39조","title":"재정에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 학부운영위원회의 심의를 거친 학부·반 학생회비 예산안·결산을 심의하여 승인한다."},{"k":"hang","x":"② 학생총회는 제1항의 심의에서 불승인된 기구에는 제163조에 따라 해당 학기의 학부 학생회비를 지급하지 않거나 지급을 보류하도록 결정할 수 있다. 그 밖에 자세한 사항은 ｢총학생회 재정운용세칙｣을 따른다."},{"k":"hang","x":"③ 학생총회는 학부학생회비의 인상·인하를 결정할 수 있다."}],"num":39,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a40","label":"제40조","title":"회칙·세칙·규칙에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 회칙을 개정할 수 있다."},{"k":"hang","x":"② 학생총회는 세칙을 제정·개정·폐지할 수 있다."},{"k":"hang","x":"③ 학생총회는 규칙·자치규칙이 회칙·세칙에 부합하는지 여부에 대해 심사할 수 있으며, 출석 과반수에 해당하는 결의로 부합하지 않다고 의결할시, 회칙·세칙에 반하는 규칙·자치규칙은 의결 즉시 효력이 부인된다."}],"num":40,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a41","label":"제41조","title":"대외활동에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 본회 차원의 상설적 연대 단체 가입·탈퇴에 대한 동의권을 가진다."},{"k":"hang","x":"② 회원 전체의 명의로 소송을 진행할 필요가 있는 문제가 발생할 때 학생총회는 학부운영위원회에 소송권을 위임할 수 있다."}],"num":41,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a42","label":"제42조","title":"재소집","paras":[{"k":"line","x":"학생총회의 개의가 불가하거나 논의를 마치지 못하고 산회한 경우 의장의 재량에 따라 10일 이내에 재소집할 수 있다."}],"num":42,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제３절 학생총투표"},{"t":"art","id":"a43","label":"제43조","title":"지위","paras":[{"k":"line","x":"학생총투표를 통한 의결은 학생총회의 의결과 같은 효력이 있다."}],"num":43,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a44","label":"제44조","title":"투표권","paras":[{"k":"line","x":"정회원은 학생총투표의 투표권이 있다."}],"num":44,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a45","label":"제45조","title":"투표관리위원회","paras":[{"k":"hang","x":"① 투표관리위원회는 학부운영위원 및 제63조 제4항에 의해 의결권을 가질 수 있는 자 전원으로 구성한다. 단, 학부 학생회장단은 제60조에 따른 학부 학생회장단 탄핵안에 대한 학생총투표에 대해서는 투표관리위원이 될 수 없다."},{"k":"hang","x":"② 투표관리위원회는 학생총투표와 관련된 모든 업무를 총괄한다."},{"k":"hang","x":"③ 집행위원장 및 집행위원회는 투표관리위원회의 결정에 따라 학생총투표 시행준비를 성실히 보조한다."},{"k":"hang","x":"④ 그 밖에 투표관리위원회에 관한 사항은 투표관리위원회의 출석 과반수에 해당하는 결의로 ｢고려대학교 총학생회 선거시행세칙｣의 선거관리위원회에 관한 규정을 준용할 수 있다."}],"num":45,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a46","label":"제46조","title":"성립·의결요건","paras":[{"k":"hang","x":"① 학생총투표의 개시는 학생총회 또는 학생대표자회의 출석 과반수에 해당하는 결의로만 가능하다."},{"k":"hang","x":"② 학생총투표는 정회원 4분의 1 이상의 투표로 성립하고, 유효투표의 과반수 찬성으로 의결한다."},{"k":"hang","x":"③ 성립 여부를 판단하기 위한 투표율의 계산은 명부상 총 투표자 수를 기준으로 한다."}],"num":46,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a47","label":"제47조","title":"시행","paras":[{"k":"line","x":"학생총투표는 학생총회 혹은 학생대표자회의 시행 결정에 따라 투표관리위원장이 시행한다."}],"num":47,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a48","label":"제48조","title":"시행 공고","paras":[{"k":"hang","x":"① 학생총회 의장은 학생총투표의 시행을 시행 7일 전에 공고하여야 한다."},{"k":"hang","x":"② 공고문에는 다음 각호의 사항을 명시하여야 한다."},{"k":"ho","x":"1. 학생총투표 시행 일시"},{"k":"ho","x":"2. 학생총투표 투표소 설치 장소"},{"k":"ho","x":"3. 안건과 안건에 대한 설명"}],"num":48,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a49","label":"제49조","title":"투표 기간","paras":[{"k":"hang","x":"① 투표 기간은 3일의 범위에서 투표관리위원회가 정한다."},{"k":"hang","x":"② 투표 기간이 종료하였음에도 투표율이 25%를 넘지 않았으면 투표관리위원회의 결정에 따라 투표 기간을 2일의 범위에서 1회 연장할 수 있다."}],"num":49,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a50","label":"제50조","title":"투표 방법","paras":[{"k":"hang","x":"① 투표는 기표방법으로 함을 원칙으로 한다."},{"k":"hang","x":"② 회원들의 쉬운 투표 참여 혹은 부재중인 자의 투표 참여를 위하여 우편, 온라인, 모바일 그 밖에 특수한 투표방법을 병행할 수 있다. 특수한 투표방법에 대한 결정은 투표관리위원회의 출석 3분의 2 이상에 해당하는 결의로 한다."},{"k":"hang","x":"③ 특수한 투표방법의 시행 여부, 대상, 방식, 운영 등에 관하여서는 ｢자유전공학부 선거시행세칙｣의 특수한 투표방법에 대한 규정을 준용한다."}],"num":50,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a51","label":"제51조","title":"결과 공고","paras":[{"k":"line","x":"학생총투표가 종료되어 개표가 완료되면 개표종료 시부터 24시간 이내에 투표관리위원회가 투표율과 결과를 공고한다. 이때 최종 투표율은 총투표용지 수를 기준으로 계산한다."}],"num":51,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a52","label":"제52조","title":"무효처리","paras":[{"k":"hang","x":"① 한 투표소의 명부상 투표자 수와 투표함의 투표용지 수의 차이가 명부상 투표자 수 대비 5%를 넘으면 해당 투표함의 결과는 무효가 되며, 해당 투표함의 투표용지 수만큼 무효표로 처리한다."},{"k":"hang","x":"② 명부상 총 투표자 수와 총투표용지 수의 차이가 명부상 총 투표자 수 대비 5%를 넘으면 해당 학생총투표는 무효가 된다."}],"num":52,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a53","label":"제53조","title":"준용","paras":[{"k":"line","x":"그 밖에 학생총투표 관련 세부 사항은 투표관리위원회의 출석 3분의 2 이상에 해당하는 결의로 ｢고려대학교 총학생회 선거시행세칙｣의 투표·개표 관련 규정을 준용한다."}],"num":53,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제4절 학생대표자회"},{"t":"art","id":"a54","label":"제54조","title":"지위","paras":[{"k":"line","x":"학생대표자회는 학생총회 다음의 위계에 있는 의결기구이다."}],"num":54,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a55","label":"제55조","title":"구성","paras":[{"k":"hang","x":"① 학생대표자회는 각호의 대표자를 대의원으로 한다."},{"k":"ho","x":"1. 학부 학생회장 및 부학생회장"},{"k":"ho","x":"2. 각 반 학생회 반 운영위원 중 학생회장, 부학생회장, 신입생 대표, 고학번 대표 4인"},{"k":"ho","x":"3. 각 자치단체장"},{"k":"hang","x":"② 비상대책위원회 체제의 산하기구의 장은 궐위로 본다."},{"k":"hang","x":"③ 궐위 대의원은 재적 대의원에서 제외한다."},{"k":"hang","x":"④ 제1항 제3호의 대표자가 학생대표자회에 정당한 사유로 출석하지 못할 때는 개의 직후에 인준을 받아 부대표자가 대신 의결권을 가질 수 있다."}],"num":55,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a56","label":"제56조","title":"학생대표자회 대의원의 의무","paras":[{"k":"hang","x":"① 학생대표자회 대의원은 학생대표자회의 품위를 유지하여야 한다."},{"k":"hang","x":"② 학생대표자회 대의원은 회칙을 준수하여야 한다."},{"k":"hang","x":"③ 학생대표자회 대의원은 자신이 소속된 기구의 의사를 충분히 수렴하여 의결 과정 전반에서 소속된 기구를 대표하는 의사를 표명해야 한다."},{"k":"hang","x":"④ 학생대표자회 대의원은 본회를 대표하여 활동하는 자로서 양심에 따라 직무를 행하고 회의에 성실히 참여하여야 한다."}],"num":56,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a57","label":"제57조","title":"정기회","paras":[{"k":"hang","x":"① 학생대표자회 정기회는 매 학기 1회 개의한다."},{"k":"hang","x":"② 정기회는 각각 5월, 11월에 개의하는 것을 원칙으로 한다."},{"k":"hang","x":"③ 학부 학생회장은 대의원과 협의하여 해당 학기 학생대표자회의 정기회 개의일을 확정 및 공고하여야 한다."}],"num":57,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a57-2","label":"제57조의2","title":"개의·의결요건","paras":[{"k":"hang","x":"① 학생대표자회는 재적 대의원 과반수 출석으로 개의하고, 출석 대의원 과반수에 해당하는 결의로 의결한다."},{"k":"hang","x":"② 다음 각호의 사항은 출석 3분의 2 이상에 해당하는 결의로 의결한다."},{"k":"ho","x":"1. 제36조 제2항의 집행위원 해임에 관한 사항"},{"k":"ho","x":"2. 제39조 제３항의 학부 학생회비 인상·인하에 관한 사항"},{"k":"ho","x":"3. 제40조 제１항의 회칙 개정에 관한 사항"},{"k":"ho","x":"4. 제60조의 학부 학생회장단 탄핵안 학생총투표 발의에 관한 사항"}],"num":57,"sub":2,"bu":false,"bold_title":false},{"t":"art","id":"a58","label":"제58조","title":"안건","paras":[{"k":"hang","x":"① 학생대표자회의 안건은 다음 각호의 방법으로 상정할 수 있다."},{"k":"ho","x":"1. 학부운영위원회의 출석 과반수에 해당하는 결의"},{"k":"ho","x":"2. 회원 50명 이상의 연서에 따른 임시회의 소집요구와 함께 발의"},{"k":"ho","x":"3. 제90조에 따라 발의된 학부 학생회장단 사퇴 허가 요청"},{"k":"ho","x":"4. 제91조에 따른 학부 학생회장단 탄핵 발의"},{"k":"ho","x":"5. 제175조에 따른 회칙 개정안 발의"},{"k":"hang","x":"② 학생대표자회는 다음 각호의 안건을 심의·의결한다."},{"k":"ho","x":"1. 제31조 제2항 제4호, 제35조의 학부 학생회장 탄핵안건을 제외한 안건 중 학생총회에서 다룰 수 있는 안건 및 학생총회의 위임을 받은 안건"},{"k":"ho","x":"2. 학부 학생회장단 탄핵안 학생총투표 발의 안건"},{"k":"ho","x":"3. 임시 학생총회 소집 및 안건상정에 관한 안건"},{"k":"ho","x":"4. 학생총투표 실시 및 안건 상정에 관한 안건"}],"num":58,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a59","label":"제59조","title":"안건 위임","paras":[{"k":"line","x":"회기 중 처리하지 못한 안건은 출석 인원의 3분의 2 이상의 찬성으로 학부운영위원회의에 위임할 수 있다. 단, 제58조 제2항 및 제60조의 탄핵안 학생총투표 발의에 관한 안건, 제175조 회칙 개정안건, 세칙 제정·개정안건, 그 밖의 본회의 목적과 관련된 본질적으로 중대한 결정사항은 위임할 수 없다."}],"num":59,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a60","label":"제60조","title":"탄핵안 학생총투표 발의","paras":[{"k":"hang","x":"① 학생대표자회는 학부 학생회장단 탄핵안을 학생총투표에 붙일 수 있다."},{"k":"hang","x":"② 학부 학생회장단 탄핵안 학생총투표 발의에 관한 절차는 제91조를 따른다."}],"num":60,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a61","label":"제61조","title":"준용","paras":[{"k":"hang","x":"① 소집요건에 관한 사항은 제27조를 준용한다. 단, 제27조 제1항 제2호는 적용하지 아니한다."},{"k":"hang","x":"② 소집공고에 관한 사항은 제28조를 준용한다."},{"k":"hang","x":"③ 자료의 사전 배포에 관한 사항은 제29조를 준용한다."},{"k":"hang","x":"④ 산하기구의 결정·집행사항 변경에 관한 사항은 제33조를 준용한다."},{"k":"hang","x":"⑤ 학부 학생회장단 사퇴 허가에 관한 사항 사항은 제34조를 준용한다."},{"k":"hang","x":"⑥ 집행위원회에 관한 사항은 제36조를 준용한다."},{"k":"hang","x":"⑦ 감사에 관한 사항은 제37조를 준용한다."},{"k":"hang","x":"⑧ 재정에 관한 사항은 제39조를 준용한다."},{"k":"hang","x":"⑨ 회칙·세칙·규칙에 관한 사항은 제40조를 준용한다."},{"k":"hang","x":"⑩ 대외활동에 관한 사항은 제41조를 준용한다."},{"k":"hang","x":"⑪ 재소집에 관한 사항은 제42조를 준용한다."}],"num":61,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제5절 학부운영위원회"},{"t":"art","id":"a62","label":"제62조","title":"지위","paras":[{"k":"line","x":"학부운영위원회는 본회의 신속하고 민주적인 결정을 위하여 학생총회가 일정 권한을 위임한 상설적인 의결기구이다."}],"num":62,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a63","label":"제63조","title":"구성","paras":[{"k":"hang","x":"① 다음 각호 중 하나에 해당되는 자는 학부운영위원이 된다."},{"k":"ho","x":"1. 학부 학생회장과 부학생회장"},{"k":"ho","x":"2. 반 학생회장"},{"k":"hang","x":"② 비상대책위원회 체제인 산하기구의 장은 궐위로 본다."},{"k":"hang","x":"③ 궐위 대의원은 재적 대의원에서 제외한다."},{"k":"hang","x":"④ 제1항 제2호의 학부운영위원이 학부운영위원회에 정당한 사유로 출석하지 못할 때는 개의 직후에 인준을 받아 부회장이 대신 의결권을 가질 수 있다."}],"num":63,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a64","label":"제64조","title":"학부운영위원의 의무","paras":[{"k":"line","x":"학부운영위원의 의무에 관해서는 제56조를 준용한다."}],"num":64,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a65","label":"제65조","title":"정기회의","paras":[{"k":"hang","x":"① 학부운영위원회 정기회의는 매주 1회 개의함을 원칙으로 한다. 단, 학부운영위원회의 출석 과반수에 해당하는 결의로 정기회의의 일정을 조정할 수 있다."},{"k":"hang","x":"② 의장은 학부운영위원회 정기회의의 개의 요일과 시각을 학부운영위원들과 협의하여 결정한 후 이를 공고하여야 한다."},{"k":"hang","x":"③ 의장은 매월 말 다음 달의 학부운영위원회 정기회의 일정을 학부운영위원들과 협의하여 결정하여야 한다."}],"num":65,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a66","label":"제66조","title":"임시회의","paras":[{"k":"hang","x":"① 학부운영위원회 임시회의는 다음 각호 중 하나에 의해 의장이 소집한다."},{"k":"ho","x":"1. 의장의 소집요구"},{"k":"ho","x":"2. 학부운영위원회 재적 위원 3분의 1 이상의 연서에 따른 소집요구"},{"k":"ho","x":"3. 정회원 20명 이상의 연서에 따른 소집요구"},{"k":"hang","x":"② 연서에 따른 소집요구는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식을 준용하며 서식에는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 사항이 포함되어야 한다."},{"k":"hang","x":"③ 연서에 따른 소집요구가 있으면 학부운영위원회 의장은 지체 없이 학부운영위원회 개의일을 결정한다. 이때 개의일은 소집요구 서식에 기재된 개의 희망일로 함을 원칙으로 하되 변경할 때는 학부운영위원의 출석 3분의 2 이상에 해당하는 결의로 한다. 단, 이 경우에도 개의 희망일과 3일 이상 차이가 나서는 안 된다."}],"num":66,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a67","label":"제67조","title":"소집 공고","paras":[{"k":"hang","x":"① 의장은 학부운영위원회의 소집을 개의일 2일 전에 공고하여야 한다."},{"k":"hang","x":"② 공고문에는 다음 각호의 사항을 명시하여야 한다."},{"k":"ho","x":"1. 회의 시작 일시"},{"k":"ho","x":"2. 회의 장소"},{"k":"ho","x":"3. 안건과 안건에 대한 설명"}],"num":67,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a68","label":"제68조","title":"안건지의 사전 배포","paras":[{"k":"line","x":"학부운영위원회 의장은 학부운영위원회 정기회의 개의 1일 전까지 제출된 안건과 그에 관한 설명, 집행위원회 등의 보고·인준 사항 등이 포함된 안건지를 학부운영위원을 대상으로 배포하여야 한다. 배포는 유인물 형태로 제작하여 비치하는 방법과 전산화된 형태의 문서로 제작하여 온라인에 게시하는 방법으로 한다."}],"num":68,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a69","label":"제69조","title":"개의·의결요건","paras":[{"k":"line","x":"학부운영위원회는 재적 위원 과반수 출석으로 개의하고, 출석 위원 과반수 찬성으로 의결한다."}],"num":69,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a70","label":"제70조","title":"안건","paras":[{"k":"hang","x":"① 학부운영위원회의 안건은 다음 각호의 방법으로 상정할 수 있다."},{"k":"ho","x":"1. 학부운영위원이 발의한 안건"},{"k":"ho","x":"2. 회원 20명 이상의 연서에 따른 소집요구와 함께 발의한 안건"},{"k":"hang","x":"② 학부운영위원회는 다음 각호의 안건을 심의·의결한다."},{"k":"ho","x":"1. 제60조 탄핵안 학생총투표 발의에 관한 안건, 제175조 회칙 개정안건, 세칙 제정·개정안건 등 본회의 목적과 관련된 본질적으로 중대한 결정사항을 제외한 안건 중 학생대표자회에서 위임을 받은 안건"},{"k":"ho","x":"2. 임시학생총회 소집 및 안건 상정에 관한 건"},{"k":"ho","x":"3. 임시학생대표자회 소집 및 안건 상정에 관한 건"},{"k":"ho","x":"4. 학생회 제반 사업에 대한 논의 안건"},{"k":"ho","x":"5. 예산 및 결산에 대한 사전 심의·검토 안건"},{"k":"ho","x":"6. 각 반 학생회 사업 보고 및 공유에 관한 안건"},{"k":"ho","x":"7. 반 학생회장단 선거관리위원회 구성에 관한 안건"},{"k":"ho","x":"8. 특별위원회 설립에 관한 안건"},{"k":"ho","x":"9. 공간배정위원회 소집 및 안건 상정에 관한 건"},{"k":"ho","x":"10. 산하기구 감사에 관한 건"},{"k":"ho","x":"11. 학생대표자회 대표자 명단 확정 및 대표자 지위 심의에 관한 건"},{"k":"ho","x":"12. 기타 학생총회 및 학생대표자회의 의결을 요하지 않는 결정사항에 대한 안건"}],"num":70,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a71","label":"제71조","title":"","paras":[{"k":"line","x":"<삭제>"}],"num":71,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a72","label":"제72조","title":"의결기구에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 학생총회의 소집을 요구할 수 있으며 학생총회에 안건을 발의할 수 있다."},{"k":"hang","x":"② 학부운영위원회는 학생대표자회의 소집을 요구할 수 있으며 학생대표자회에 안건을 발의할 수 있다."},{"k":"hang","x":"③ 학부운영위원회는 학생총회 및 학생대표자회의 개의에 관한 세부 문제를 논의하고 결정한다."},{"k":"hang","x":"④ 학부운영위원회는 학생총회에 대하여 연서에 따른 소집요구가 있으면 학생총회의 개의일을 결정한다."},{"k":"hang","x":"⑤ 학부운영위원회는 학생대표자회 개의 전 산하기구의 대표자가 민주적 선거에 의해 당선되었는지, 실질적으로 기구를 대표하고 있는지 등 대표자 지위에 대한 심사를 진행하여야 하며, 이를 기준으로 대의원 명단을 확정 지어야 한다."}],"num":72,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a73","label":"제73조","title":"집행기구에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 제95조 제2항, 제96조 제2항에 따라 집행위원장과 집행위원회 각 국서의 국장과 국원을 사전 인준한다."},{"k":"hang","x":"② 학부운영위원회는 학생총회 및 학생대표자회 보고 사항을 사전 심의한다."},{"k":"hang","x":"③ 학부운영위원회는 학부 학생회장단과 집행위원회의 사업 계획과 진행 상황, 결과에 대한 보고를 받고 이를 심의하고 조정한다. 단, 학부 학생회장단과 집행위원회의 효율적인 집행을 보장하기 위하여 학부 학생회장단이 사전 집행이 불가피하다고 판단하여 집행한 사업에 대하여는 사후에 보고하고 심의 절차를 이행할 수 있다. 집행위원회는 불승인된 사업에 대해서는 의결 즉시 원상회복을 위해 노력해야 한다."},{"k":"hang","x":"④ 학부운영위원회는 학부 학생회장단과 집행위원회의 결정과 집행사항을 변경 또는 취소할 수 있다."},{"k":"hang","x":"⑤ 학부운영위원회는 학부 학생회장단에 대한 탄핵안이 발의되면 탄핵안이 제91조 제1항 내지 제3항에서 규정하고 있는 발의 요건을 충족하고 있는지 지체 없이 심의해야 하며 제91조 제4항에 따라 학생총회 또는 학생대표자회를 소집해야 한다."}],"num":73,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a74","label":"제74조","title":"감사에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 본회 집행기구, 산하기구의 사업 전반에 대하여 감사를 시행할 수 있다."},{"k":"hang","x":"② 학부운영위원회는 감사에 필요하다고 인정될 때 해당 기구의 대표자 혹은 사업담당자를 출석시켜 진술을 청취할 수 있다. 또한 관련 자료의 제출을 요구할 수 있다."}],"num":74,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a75","label":"제75조","title":"선거에 관한 사항","paras":[{"k":"line","x":"학부운영위원회는 반 학생회장단 동시선거 일정을 결정하고 반 학생회 동시 선거관리위원회를 구성할 수 있다. 그 밖에 자세한 사항은 ｢자유전공학부 학부·반 선거시행세칙｣을 따른다."}],"num":75,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a76","label":"제76조","title":"재정에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 제167조에 따라 학생회비를 사용하는 학부·반 집행위원회 등의 예산안과 결산을 사전 심의한 후 학생총회 및 학생대표자회에 상정한다."},{"k":"hang","x":"② 학부운영위원회는 제163조 제8항에 따라 집행기구 자산의 취득, 보관, 사용, 처분 행위를 취소할 수 있다."}],"num":76,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a77","label":"제77조","title":"회칙·세칙·규칙에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 제175조에 따라 회칙 개정안과 제182조에 따라 세칙 제정안·개정안·폐지안을 발의할 수 있다. 학부운영위원회는 회칙 개정안을 발의하면 제177조 제１항에 따라 학부운영위원회에서 회칙 개정안에 대해 사전 심의한다."},{"k":"hang","x":"② 세칙에 관련 규정이 있으면 학부운영위원회는 해당 세칙에 부수되는 규칙을 제정·개정·폐지할 수 있다. 이에 관하여서는 해당 세칙을 따른다."},{"k":"hang","x":"③ 학부운영위원회는 일반규칙을 제정·개정·폐지할 수 있다."}],"num":77,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a78","label":"제78조","title":"대외활동에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 본회의 대외적 활동에 대하여 동의 및 승인권을 갖는다."},{"k":"hang","x":"② 학부운영위원회는 직전 두 분기의 학부 학생회비 5%를 초과하는 재정적 지출을 수반하거나, 본회의 회원에게 중대한 영향을 미치는 학부 학생회장단 또는 집행위원회 차원의 대외활동에 대하여 동의권을 갖는다. 단, 학부 학생회장단과 집행위원회의 효율적인 대외활동을 보장하기 위하여 학부 학생회장단이 사전 집행이 불가피하다고 판단하여 집행한 사업에 대하여는 사후에 보고하고 승인 절차를 이행할 수 있다. 학부 학생회장단과 집행위원회는 부동의된 대외활동에 대해서는 의결 즉시 원상회복을 위해 노력해야 한다."}],"num":78,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제6절 비상대책위원회"},{"t":"art","id":"a79","label":"제79조","title":"비상대책위원회","paras":[{"k":"hang","x":"① 비상대책위원회는 다음 각호에 해당할 때 해당 사항의 공고 시로부터 48시간 후 구성한다. 단, 임기 종료일이 확정되지 않았을 때 잔여 임기의 계산을 위한 임기 종료일은 11월 30일로 한다."},{"k":"ho","x":"1. 학부 학생회장단 선거의 예정된 개표일이 경과하였을 때"},{"k":"ho","x":"2. 학부 학생회장단 두 명 모두가 사퇴하거나 탄핵되고, 해당 학부 학생회장단의 잔여 임기가 180일이 넘지 않을 때"},{"k":"hang","x":"② 제１항에 따라 비상대책위원회가 구성되면 다음 각호에 해당하는 자는 비상대책위원이 된다."},{"k":"ho","x":"1. 각 반 학생회장 및 부학생회장"},{"k":"ho","x":"2. 학생대표자회 대의원 중 호선된 자"}],"num":79,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a80","label":"제80조","title":"권한·업무","paras":[{"k":"hang","x":"① 비상대책위원회는 의결기구에 준하는 권한을 갖는다."},{"k":"hang","x":"② 비상대책위원회는 학부 학생회장단의 궐위기간 동안 학부운영위원회의 상시적 업무를 담당한다."},{"k":"hang","x":"③ 비상대책위원회는 학부 학생회장단의 궐위기간 동안 집행위원회의 상시적 업무를 담당하기 위하여 임시집행위원회를 구성할 수 있다."}],"num":80,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a81","label":"제81조","title":"비상대책위원장","paras":[{"k":"hang","x":"① 비상대책위원장은 비상대책위원회의 출석 과반수에 해당하는 결의로 선출하며, 선출이 무산될 경우 호선에 의한다. 비상대책위원장은 학생총회 또는 학생대표자회의 인준을 받아야 한다."},{"k":"hang","x":"② 비상대책위원장은 학부 학생회장에 준하는 권한을 갖는다."},{"k":"hang","x":"③ 비상대책위원장의 의무에 관해서는 제56조와 제88조를 준용한다."}],"num":81,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a81-2","label":"제81조의2","title":"임시집행위원회","paras":[{"k":"hang","x":"① 임시집행위원회는 집행위원회에 준하는 권한을 가지며, 학부 학생회장단의 궐위 기간 동안 집행위원회의 상시적 업무를 담당한다."},{"k":"hang","x":"② 임시집행위원은 각 반 학생회에서 두 명씩 추천하며, 그 외 임시집행위원은 공고를 내어 공개 모집함을 원칙으로 한다."},{"k":"hang","x":"③ 비상대책위원장은 임시집행위원장을 둘 수 있으며, 임시집행위원장의 임명에 관하여서는 학생대표자회의 인준을 받아야 한다."},{"k":"hang","x":"④ 각 국서의 국장과 국원은 비상대책위원장이 임명한다. 각 국서의 국장과 국원의 임명에 관하여서는 학생대표자회의 인준을 받아야 한다."}],"num":81,"sub":2,"bu":false,"bold_title":false},{"t":"art","id":"a82","label":"제82조","title":"제한","paras":[{"k":"hang","x":"① 비상대책위원장과 임시집행위원회는 학생회장단 및 집행위원회가 가지는 사전 집행·사후 학부운영위원회 승인 방식의 재정지출이 허용되지 않는다."},{"k":"hang","x":"② 비상대책위원장과 임시집행위원회는 학생회장단 및 집행위원회가 가지는 사전 집행·사후 학부운영위원회 승인 방식의 대외활동이 허용되지 않는다."},{"k":"hang","x":"③ 비상대책위원장과 임시집행위원회는 직전 두 분기의 학부 학생회비 30%를 초과하는 재정지출이 허용되지 않는다."}],"num":82,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a83","label":"제83조","title":"흠결의 보충","paras":[{"k":"line","x":"비상대책위원회 관련 회칙의 흠결로 비상대책위원회 및 비상대책위원장의 권한, 의무의 범위를 확정 짓기 어려울 시, 학부운영위원회의 출석 과반수에 해당하는 결의로 해당 회기에 한해 한시적으로 흠결을 보충할 수 있다. 단, 권한의 범위는 학부 학생회장과 집행위원회의 권한 내로 제한되며, 의무의 범위는 학부 학생회장단과 집행위원회의 의무 내로 제한된다."}],"num":83,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제３장 집행기구"},{"t":"h","lv":3,"text":"제１절 학부 학생회장단"},{"t":"art","id":"a84","label":"제84조","title":"지위","paras":[{"k":"hang","x":"① 학부 학생회장은 본회를 대표하며, 학생총회, 학생대표자회, 학부운영위원회의 의장이 된다."},{"k":"hang","x":"② 학부 학생회장은 총학생회 중앙운영위원 및 전체학생대표자회 대의원이 된다."},{"k":"hang","x":"③ 부학생회장은 학부 학생회장을 보좌하고 학부 학생회장이 권한을 위임하거나 사고인 때에 학부 학생회장의 직무를 대행한다."}],"num":84,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a85","label":"제85조","title":"의결기구 관련 권한","paras":[{"k":"line","x":"학부 학생회장은 학생총회, 학생대표자회, 학부운영위원회 등 의결기구를 운영한다."}],"num":85,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a86","label":"제86조","title":"집행기구 관련 권한","paras":[{"k":"hang","x":"① 학부 학생회장은 본회 사무의 집행을 총괄한다."},{"k":"hang","x":"② 학부 학생회장은 집행위원회의 구성권을 가진다."},{"k":"hang","x":"③ 학부 학생회장은 집행위원회 산하 국서의 국장과 국원에 대한 임면권을 가진다."},{"k":"hang","x":"④ 학부 학생회장은 집행위원회와 산하 국서를 지휘·감독한다."},{"k":"hang","x":"⑤ 학부 학생회장은 집행위원회의 결정·집행 사항을 변경 또는 취소할 수 있다."},{"k":"hang","x":"⑥ 학부 학생회장은 필요하다고 인정한 사안의 효율적 업무 집행을 위하여 직속 자문위원회를 설치할 수 있다. 직속 자문위원회와 그 위원에 관하여서는 제３항 내지 제5항을 준용한다."}],"num":86,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a87","label":"제87조","title":"대외활동 관련 권한","paras":[{"k":"hang","x":"① 학부 학생회장은 학생자치활동에 관계되는 학교 행정의 문제에 대해 회원의 의사를 대변하고 학교 당국에 의사를 개진하며, 관련 단체 및 회의에 참여할 수 있다."},{"k":"hang","x":"② 학부 학생회장은 본회와 본회 회원과 관련된 문제에 관하여 본회를 대표하여 대외적으로 입장을 표명하는 등의 대외활동을 할 수 있다. 단, 본회 차원의 연대 단체 가입과 대외적 협의, 본회의 재정적 지출을 수반는 행위나, 본회의 회원에게 중대한 영향을 미치는 학부 학생회장단 차원의 대외활동은 제78조에 따라 학부운영위원회의 동의를 받아야 한다."}],"num":87,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a88","label":"제88조","title":"의무","paras":[{"k":"hang","x":"① 학부 학생회장은 회원들의 의사를 반영하여 민주적 절차에 따라 직무를 수행해야 한다."},{"k":"hang","x":"② 학부 학생회장은 본회의 의결기구에 성실하게 본회의 활동 사항을 보고해야 한다."},{"k":"hang","x":"③ 학부 학생회장은 본회의 지속적·장기적 발전을 위하여 노력해야 한다."},{"k":"hang","x":"④ 학부 학생회장단은 본회와 본회 산하기구의 각종 선거에 대한 부당한 영향력의 행사 등 선거 결과에 직·간접적인 영향을 미치는 행위를 일체 하여서는 아니 된다."},{"k":"hang","x":"⑤ 학부 학생회장단은 후임 학부 학생회장단의 선출과 후임 학부 학생회장단으로의 인수인계가 원활하게 이루어질 수 있도록 노력해야 한다."},{"k":"hang","x":"⑥ 학부 학생회장은 본회의 대표로 학교 기구의 위원이 될 때 의결권 행사 등에 관하여 학부운영위원회와 협의하여야 한다."}],"num":88,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a89","label":"제89조","title":"임기·삼선 금지","paras":[{"k":"hang","x":"① 학부 학생회장단의 임기는 당선 공고일로부터 48시간 이후부터 후임 학부 학생회장단 임기 시작 전까지로 한다. 단, 후임 학부 학생회장단 선거가 무산되는 경우 후임 학부 학생회장단 선거 개표 예정일로부터 48시간이 도과하면 임기가 종료되는 것으로 본다."},{"k":"hang","x":"② 학부 학생회장은 후임 학부 학생회장단 선거에서 학부 학생회장 후보로 입후보할 수 있다. 단, 학생회장을 2회 역임한 경우, 차기 선거에서 학부 학생회장 및 부학생회장 후보로 입후보할 수 없다."}],"num":89,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a90","label":"제90조","title":"사퇴","paras":[{"k":"hang","x":"① 학부 학생회장 또는 학부 부학생회장이 사퇴하고자 할 때는 학생총회 또는 학생대표자회의 허가가 있어야 한다. 단, 사망 등으로 인하여 당사자가 허가를 받을 수 없으면 그러하지 아니하다."},{"k":"hang","x":"② 제1항의 사퇴요청의 접수일로부터 20일 이내에 학생총회 또는 학생대표자회의 결정이 없으면 사퇴를 승인한 것으로 본다."},{"k":"hang","x":"③ 학부 학생회장이 사퇴하거나 탄핵되면 학부 부학생회장이 그 직을 승계한다."}],"num":90,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a91","label":"제91조","title":"탄핵","paras":[{"k":"hang","x":"① 회원은 학부 학생회장단이 다음 각호 중 하나에 해당할 시 학부 학생회장단의 탄핵안을 발의할 수 있다. 회장과 부회장 중 한 명만 다음 각호 중 하나에 해당하는 경우, 회장과 부회장 중 한 명을 대상으로 한 탄핵안을 발의할 수 있다. 탄핵안의 경우 반드시 학생총회 또는 학생총투표의 방법 중 하나를 정해 발의해야 한다."},{"k":"ho","x":"1. 회칙의 중대한 위반을 저질렀을 경우"},{"k":"ho","x":"2. 상당한 기간 동안 회장단의 업무를 해태하고 있을 경우"},{"k":"ho","x":"3. 실정법 위반으로 벌금형 이상의 실형을 선고받은 경우"},{"k":"ho","x":"4. 회원으로부터 현저히 신임을 잃었을 경우"},{"k":"hang","x":"② 탄핵안의 상정은 다음 각호의 요건 중 하나를 충족시켜야 한다."},{"k":"ho","x":"1. 학부운영위원회의 재적 3분의 2 이상에 해당하는 연서"},{"k":"ho","x":"2. 학생대표자회의 재적 3분의 2 이상에 해당하는 연서"},{"k":"ho","x":"3. 본회 회원 10분의 1 이상에 해당하는 연서"},{"k":"hang","x":"③ 연서에 따른 발의는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식에 의하여야 한다."},{"k":"hang","x":"④ 학부운영위원회는 탄핵안이 발의되면 즉시 탄핵안이 제1항 내지 제3항의 발의 요건을 충족시켰는지 심의하여야 하며, 중대한 하자가 없으면 탄핵안 제출일로부터 7일 이내에 학생총회 소집 또는 학생총투표에 상정한다. 학생총회 및 학생총투표 방법에 관한 탄핵 안건이 모두 상정된 경우, 학부운영위원회의 출석 과반수에 해당하는 결의로 방법을 정한다. 단, 두 방법 모두 출석 과반수에 해당하는 결의가 성립되지 않으면, 탄핵안을 학생총투표에 상정하는 것으로 한다."}],"num":91,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a92","label":"제92조","title":"인수위원회","paras":[{"k":"hang","x":"① 학부 학생회장단 당선자는 학부 학생회장단 및 집행위원회의 업무 인수를 위해 당선 공고일로부터 48시간 이후부터 자유전공학부 학생회 인수위원회를 설치할 수 있다. 단, 보궐선거로 당선되었을 경우 설치하지 아니한다."},{"k":"hang","x":"② 인수위원회는 다음 각호의 직무를 수행한다."},{"k":"ho","x":"1. 집행위원회의 조직ᆞ 기능 및 예산 현황의 파악"},{"k":"ho","x":"2. 전임 학부 학생회장단과 집행위원회의 주요 사업 분석"},{"k":"ho","x":"3. 기타 학부 학생회장단과 집행위원회 업무의 인수에 필요한 사항"},{"k":"hang","x":"③ 인수위원장은 당선된 선거운동본부의 본부장으로 함을 원칙으로 한다."},{"k":"hang","x":"④ 인수위원회는 설치한 날로부터 7일 후 해산한다."}],"num":92,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제２절 집행위원회"},{"t":"art","id":"a93","label":"제93조","title":"지위","paras":[{"k":"line","x":"집행위원회는 본회의 최고집행기구이다."}],"num":93,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a94","label":"제94조","title":"구성","paras":[{"k":"line","x":"집행위원회는 각 국서의 국장과 국원으로 구성한다. 단, 원활한 운영을 위해 집행원장을 둘 수 있다."}],"num":94,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a95","label":"제95조","title":"집행위원장","paras":[{"k":"hang","x":"① 집행위원장은 학생회장단을 보좌하며, 본회 사무의 집행에 관하여 학부 학생회장단의 지시에 따라 각 국서를 관리·감독한다."},{"k":"hang","x":"② 집행위원장은 학부 학생회장이 임명하고, 학부운영위원회의 사전 인준(임명)으로 업무를 개시한다. 집행위원장의 임명에 관하여서는 학생총회 또는 학생대표자회의 사후 인준을 받아야 한다."}],"num":95,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a96","label":"제96조","title":"국서","paras":[{"k":"hang","x":"① 집행위원회는 원활한 업무 집행을 위하여 산하에 국서를 둘 수 있다."},{"k":"hang","x":"② 각 국서의 국장과 국원은 학부 학생회장이 임명하고, 학부운영위원회의 사전 인준(임명)으로 업무를 개시한다. 각 국서의 국장과 국원의 임명에 관하여서는 학생총회 또는 학생대표자회의 사후 인준을 받아야 한다."}],"num":96,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a97","label":"제97조","title":"업무","paras":[{"k":"hang","x":"① 집행위원회는 본회의 사업 집행 전반을 담당한다."},{"k":"hang","x":"② 집행위원회는 학생총회, 학생대표자회 및 학부운영위원회가 결정한 업무를 집행한다."},{"k":"hang","x":"③ 집행위원회는 학부 학생회장단이 결정한 업무를 집행한다."},{"k":"hang","x":"④ 집행위원회는 다음 각호의 사안에 대한 관리 권한을 갖는다. 관리 권한이라 함은 각 사안의 원활한 운영을 위하여 배타적인 권리행사 및 집행을 할 수 있는 권원을 의미한다."},{"k":"ho","x":"1. ｢권한등기부｣에 등기된 것"},{"k":"ho","x":"2. 학생회 자치 공간 분배 및 회수"},{"k":"ho","x":"3. 사물함 분배, 회수, 철거"},{"k":"hang","x":"⑤ 집행위원회는 학생총회, 학생총투표, 학생대표자회 및 학부운영위원회의 개의·시행을 준비하고, 이에 사용되는 각종 서식을 ｢고려대학교 총학생회 사무처리세칙｣을 준용하여 제작한다."},{"k":"hang","x":"⑥ 집행위원회는 학생총회, 학생대표자회 및 학부운영위원회에 본회의 운영 사항을 보고해야 한다."},{"k":"hang","x":"⑦ 집행위원회는 본회의 예산안·결산을 작성하여 학생총회 또는 학생대표자회와 학부운영위원회에 보고해야 한다."}],"num":97,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a98","label":"제98조","title":"집행회의","paras":[{"k":"hang","x":"① 집행위원장은 집행위원회의 업무에 속하는 사안을 심의하기 위하여 집행회의를 소집할 수 있다. 이 경우 집행회의의 의장은 집행위원장이 된다."},{"k":"hang","x":"② 집행회의의 구성, 업무와 권한, 운영 등에 관하여서는 규칙으로 정한다."},{"k":"hang","x":"③ 집행위원장이 궐위일 경우 집행회의의 의장은 학생회장이 된다."}],"num":98,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a99","label":"제99조","title":"계열회의","paras":[{"k":"line","x":"집행위원회는 원활한 업무 집행을 위하여 특정 국서의 국장과 각 반 학생회, 자치단체 및 독립기구 등의 동종 업무 담당 국장 혹은 이에 준하는 자가 참가하는 계열회의를 개최할 수 있다. 계열회의의 구성, 업무와 권한, 운영 등에 관하여서는 규칙으로 정한다."}],"num":99,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제4장 산하기구"},{"t":"h","lv":3,"text":"제１절 반 학생회"},{"t":"art","id":"a100","label":"제100조","title":"지위 및 구성","paras":[{"k":"line","x":"반 학생회는 고려대학교 자유전공학부 학생회원 중 A반부터 D반까지의 네 반을 기준으로 분류된 각 반의 회원들로 구성되며 반 학생회원들의 단결 및 권리와 이익 보장을 위해 자치활동을 하는 자유전공학부 학생회 산하기구이다."}],"num":100,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a101","label":"제101조","title":"회원","paras":[{"k":"hang","x":"① 자유전공학부 학생회원의 반 학생회별 분류는 다음 각호에 따른다."},{"k":"ho","x":"1. A반 소속 자유전공학부 학생회 회원은 A반 학생회원이 된다."},{"k":"ho","x":"2. B반 소속 자유전공학부 학생회 회원은 B반 학생회원이 된다."},{"k":"ho","x":"3. C반 소속 자유전공학부 학생회 회원은 C반 학생회원이 된다."},{"k":"ho","x":"4. D반 소속 자유전공학부 학생회 회원은 D반 학생회원이 된다."},{"k":"hang","x":"② 2학기 입학, 편입 등으로 반이 확정되지 않은 채로 회원이 된 경우, 해당 회원의 반은 학부운영위원회의 출석 과반수에 해당하는 결의로 결정한다."},{"k":"hang","x":"③ 반 학생회의 회원은 해당 반 학생회 회장단 선거의 선거권과 피선거권을 가진다."},{"k":"hang","x":"④ 반 학생회의 회원은 해당 반 학생회 사업을 향유할 권리를 지닌다."},{"k":"hang","x":"⑤ 반 학생회 회원의 권리 및 의무에 관한 사항은 각 반 학생회칙으로 정한다."}],"num":101,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a102","label":"제102조","title":"반 학생회장단","paras":[{"k":"hang","x":"① 반 학생회장단은 상위 규정과 어긋나지 않는 범위에서 반 학생회칙에 따라 회원의 보통ㆍ평등ㆍ직접ㆍ비밀선거로 선출한다."},{"k":"hang","x":"② 반 학생회장단의 임기는 당선 공고 후 시작되며 다음 반 학생회장단의 당선 공고 전까지로 한다."},{"k":"hang","x":"③ 반 학생회장단의 권한·의무 사항에 대해서는 각 반 학생회칙으로 정한다."},{"k":"hang","x":"④ 반 학생회장은 해당 반을 대표하며 학생대표자회 대의원 및 학부운영위원회 위원이 된다."},{"k":"hang","x":"⑤ 반 학생회장은 총학생회 전체학생대표자회의의 대의원이 된다."}],"num":102,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a103","label":"제103조","title":"운영","paras":[{"k":"hang","x":"① 반 학생회의 최고 의결기구는 반 학생총회이다."},{"k":"hang","x":"② 반 학생회는 정기적으로 반 학생총회 및 반 운영위원회를 개의해야 한다."},{"k":"hang","x":"③ 다음 각호 중 하나에 해당하는 자는 반 운영위원이 되며, 반 학생회장과 부학생회장을 제외한 반 운영위원의 선출·권한·의무 및 그 밖의 사항은 반 학생회칙으로 정한다."},{"k":"ho","x":"1. 반 학생회장과 부학생회장"},{"k":"ho","x":"2. 신입생 대표"},{"k":"ho","x":"3. 고학번 대표"},{"k":"ho","x":"4. 각 반 학생회칙으로 정한 이에 준하는 자"},{"k":"hang","x":"④ 반 학생회의 최고집행기구는 각 반 학생회의 집행위원회이며 반 학생회 집행위원회는 반 운영위원회에 사업을 성실히 보고하여야 한다."},{"k":"hang","x":"⑤ 반 학생회의 모든 기구의 권한과 업무는 각 반 학생회칙으로 정한다."}],"num":103,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a104","label":"제104조","title":"권리","paras":[{"k":"hang","x":"① 반 학생회는 학부 학생회로부터 재정 지원과 공간 지원을 받을 수 있다."},{"k":"hang","x":"② 반 학생회는 학부 학생회로부터 집행 인원을 지원받을 수 있다."},{"k":"hang","x":"③ 반 학생회는 법학관(신관), CJ법학관, 해송법학도서관 강의실을 대관할 수 있다."},{"k":"hang","x":"④ 반 학생회는 학생회 페이스북 페이지, 카카오톡 공지방, 행정실 게시판을 활용할 수 있다."}],"num":104,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a105","label":"제105조","title":"의무","paras":[{"k":"hang","x":"① 반 학생회는 매 학기 학생총회 또는 학생대표자회에서 예산안·결산에 대한 심의·승인 절차를 거쳐야 한다."},{"k":"hang","x":"② 반 학생회는 다른 반 학생회와 교류하고, 학부 학생회 사업에 협력해야 한다."}],"num":105,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a106","label":"제106조","title":"위계","paras":[{"k":"hang","x":"① 반 학생회의 회칙 및 결정사항이 본회의 회칙·세칙과 충돌할 시, 본회의 회칙·세칙과 합치될 수 있는 내용을 제외한 모든 내용은 무효로 한다. 단, 본회의 회칙·세칙의 개정 및 신설로 인해 기존의 반 학생회 회칙 및 결정사항과 충돌이 생겼을 시, 소급효는 인정하지 않는다."},{"k":"hang","x":"② 반 학생회의 결정이 본회 의결기구의 결정과 충돌할 시, 본회의 결정과 합치될 수 있는 내용을 제외한 모든 내용은 그 즉시 무효로 한다."}],"num":106,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 자치단체"},{"t":"art","id":"a107","label":"제107조","title":"지위","paras":[{"k":"hang","x":"① 자치단체는 특정한 분야에서 특정한 목적을 가지고 활동하는 단체 중 자유전공학부 학생회에 등록절차를 마치고 매년 자유전공학부 학생회의 인준을 받아 활동하는 단체이다."},{"k":"hang","x":"② 본회 자치단체로의 등록은 학생총회 혹은 학생대표자회의에서 각호와 같은 사유에 해당될 때에만 거절될 수 있다. 단 아래의 사유는 각 단체의 특수한 목적 및 사정을 고려하여 논의되어야 한다."},{"k":"ho","x":"1. 단체의 존속 가능성이 불분명한 경우"},{"k":"ho","x":"2. 단체의 활동과 목적이 본회가 추구하는 가치에 명백히 반하는 경우"},{"k":"ho","x":"3. 당해 모집 기간 이후에도 명부상 10명 이하의 회원만이 활동하는 것으로 판단되는 경우"},{"k":"ho","x":"4. 명부상 자유전공학부 회원이 구성원의 1/2 미만일 경우"},{"k":"ho","x":"5. 사회상규에 비추어 본회로의 등록이 용인되기 힘든 수준의 사유를 지닐 경우"}],"num":107,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a108","label":"제108조","title":"회원","paras":[{"k":"hang","x":"① 각 자치단체에 소속된 본회의 회원은 해당 자치단체의 회원이 된다."},{"k":"hang","x":"② 자치단체의 회원은 해당 자치단체장 선거의 선거권과 피선거권을 가진다."},{"k":"hang","x":"③ 자치단체의 회원은 해당 자치단체의 사업을 향유할 권리를 지닌다."},{"k":"hang","x":"④ 본회의 회원에 해당하지 않는 자치단체 회원은 자치단체에 관한 회칙의 적용에 한해서는 본회의 회원으로 본다."}],"num":108,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a109","label":"제109조","title":"자치단체장","paras":[{"k":"hang","x":"① 자치단체장은 상위 규정과 어긋나지 않는 범위에서 자치단체의 자치규칙에 따라 회원의 보통ㆍ평등ㆍ직접ㆍ비밀선거로 선출한다."},{"k":"hang","x":"② 자치단체장은 해당 자치단체를 대표하며 학생대표자회의 대의원이 된다."},{"k":"hang","x":"③ 자치단체 및 자치단체장의 권한·업무 등에 관하여서는 각 자치단체의 자치규칙으로 정한다."}],"num":109,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a110","label":"제110조","title":"권리","paras":[{"k":"hang","x":"① 자치단체는 학부 학생회로부터 집행 인원을 지원받을 수 있다."},{"k":"hang","x":"② 자치단체는 법학관(신관), CJ법학관, 해송법학도서관 강의실을 대관할 수 있다."},{"k":"hang","x":"③ 자치단체는 학생회 페이스북 페이지, 카카오톡 공지방, 행정실 게시판을 활용할 수 있다."}],"num":110,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a111","label":"제111조","title":"의무","paras":[{"k":"hang","x":"① 자치단체는 본회의 목표에 맞게 성실히 활동하며 창조적 대학 문화 창달을 위해 노력해야 한다."},{"k":"hang","x":"② 자치단체는 매년 1학기 학생총회 또는 학생대표자회에서 인준 절차를 거쳐야 한다. 등록 및 인준은 정해진 양식에 의하며, 인준의 요건은 제107조 제2항을 준용한다."},{"k":"hang","x":"③ 인준받지 못한 자치단체는 2학기 학생총회 또는 학생대표자회에서 재인준 절차를 거쳐야 하며, 재인준받지 못할 경우, 재인준에 관한 안건이 결의된 학생총회 또는 학생대표자회의 종료일을 기준으로 30일 이내에 자치공간 및 본회 자산을 반납하여야 한다."},{"k":"hang","x":"④ 자치단체는 다른 자치단체와 교류하고, 학생회 사업에 협력해야 한다."},{"k":"hang","x":"⑤ 자치단체는 본회의 회원들의 관심사에 따른 자발적인 참여를 보장해야 하며, 본회 회원의 결속 및 학생회의 발전에 기여해야 한다."}],"num":111,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a112","label":"제112조","title":"위계","paras":[{"k":"line","x":"자치단체의 결정 및 자치규약과 학부 학생회의 결정 및 회칙과의 위계에 관해서는 제106조를 준용한다."}],"num":112,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제3절 특별위원회"},{"t":"art","id":"a113","label":"제113조","title":"목적","paras":[{"k":"line","x":"감찰, 조사, 프로젝트 등 특수한 목적 달성을 위해 학생대표자회 혹은 학부운영위원회 산하에 한시적으로 특별위원회를 둘 수 있다."}],"num":113,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a114","label":"제114조","title":"구성","paras":[{"k":"hang","x":"① 특별위원회는 학생총회, 학생대표자회 혹은 학부운영위원회에서 임명한 위원장 1인과 위원으로 구성한다."},{"k":"hang","x":"② 특별위원회의 위원장과 위원은 공개모집을 원칙으로 하되 필요한 경우 학부운영위원회의 출석 과반수에 의한 결의로 집행위원만으로 구성할 수 있다."},{"k":"hang","x":"③ 특별위원회는 구체적인 활동 목적을 가지고 구성되어야 하며, 특별위원회 구성에 대한 안건에는 반드시 특별위원회의 구체적인 활동 목적과 활동 범위가 명시되어야 한다. 조사, 감찰의 경우 대상자를 특정할 수 있는 경우에는 안건에 함께 기재해야 한다."}],"num":114,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a115","label":"제115조","title":"인준","paras":[{"k":"line","x":"특별위원회의 위원장과 위원은 학부운영위원회의 사전 동의로 활동을 개시하며 소속된 의결기구에서 사후 인준을 받아야 한다. 단, 학부운영위원회 소속 특별위원회의 경우에는 사후 인준 절차를 생략한다."}],"num":115,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a116","label":"제116조","title":"활동","paras":[{"k":"hang","x":"① 특별위원회는 활동 목적에 직·간접적으로 필요하다고 판단될 경우, 학부운영위원회의 출석 3분의 2 이상에 의한 결의로 구체적 활동 범위를 벗어난 활동을 할 수 있다. 이 경우, 필요한 이유 및 재설정한 활동 범위를 소속된 의결기구에 보고하여야 하며, 소속된 의결기구는 언제든지 출석 과반수에 의한 결의로 학부운영위원회의 해당 결정을 취소할 수 있다."},{"k":"hang","x":"② 특별위원회의 활동 기간은 최단 7일, 최장 60일까지이다. 단, 1회에 한해 30일을 연장할 수 있 다."},{"k":"hang","x":"③ 특별위원회의 활동 목적이 새내기새로배움터 준비인 경우, 제2항을 적용하지 아니한다."},{"k":"hang","x":"④ 특별위원회는 활동 목적에 따라 회원 및 단체에 위원회 출석 및 자료 제출을 요청할 수 있다."}],"num":116,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a117","label":"제117조","title":"해산 및 폐지","paras":[{"k":"hang","x":"① 다음 각호에 해당하는 경우 특별위원회는 해산한다."},{"k":"ho","x":"1. 활동 목적이 달성된 경우"},{"k":"ho","x":"2. 활동 기간이 종료된 경우"},{"k":"hang","x":"② 특별위원회는 언제든지 소속된 의결기구의 출석 3분의 2 이상에 의한 결의로 폐지할 수 있다. 단, 특별위원회의 목적이 감찰 및 조사에 해당하는 경우, 감찰 및 조사의 대상이 되는 회원은 의결기구에서 의결권을 행사할 수 없다."}],"num":117,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제５장 독립기구"},{"t":"h","lv":3,"text":"제1절 통칙"},{"t":"art","id":"a118","label":"제118조","title":"지위","paras":[{"k":"hang","x":"① 독립기구는 특수한 영역과 기능을 담당하기 위하여 설치된 상설기구이다."},{"k":"hang","x":"② 독립기구는 자유전공학부 학생회의 물적·인적 지원을 받으며 학부 학생회장단으로부터 그 업무의 감독을 받는다. 다만, 자유전공학부 집행위원회로부터는 독립적인 위상을 보장받는다."},{"k":"hang","x":"③ 전항에도 불구하고 독립기구의 업무가 학부 학생회장단으로부터의 독립의 필요성이 인정되는 범위 내에서 그 독립성이 보장된다."}],"num":118,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a119","label":"제119조","title":"성립 요건","paras":[{"k":"line","x":"독립기구는 다음 각호 중 하나 이상의 요건을 갖추어 설치가 필요하다고 인정될 때에 설치된다."},{"k":"ho","x":"1. 본회 회원의 권익 보호를 위한 전문적 활동을 꾸준히 수행하여 독립기구로서의 정체성이 확보되어 있는 단체"},{"k":"ho","x":"2. 본회 차원의 포괄적, 대외적 사업이 필요한 분야에 관련된 단체"}],"num":119,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 선거관리위원회"},{"t":"art","id":"a120","label":"제120조","title":"목적","paras":[{"k":"line","x":"선거관리위원회는 민주적이고 공정한 절차에 입각해 선거를 효율적으로 진행하는 데 그 목적을 둔다."}],"num":120,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a121","label":"제121조","title":"구성","paras":[{"k":"hang","x":"① 선거관리위원회는 학부 학생회장단을 제외한 학부운영위원 및 학생회칙 제55조 제4항에 의해 의결권을 가질 수 있는 자 전원을 기본으로 구성하며, 나머지 인원은 공개 모집함을 원칙으로 한다. 단, 반 학생회장단 동시선거의 경우, 해당 선거를 진행하는 선거관리위원회는 학부운영위원 및 학생회칙 제55조 제4항에 의해 의결권을 가질 수 있는 자 전원을 기본으로 구성하며, 나머지 인원은 공개 모 집함을 원칙으로 한다."},{"k":"hang","x":"② 선거관리위원회는 학부운영위원회에서 인준받은 8인 이상 12인 이하의 선거관리위원으로 구성한다."}],"num":121,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a122","label":"제122조","title":"대표자 선출","paras":[{"k":"line","x":"선거관리위원회의 위원장은 학부 학생회장단을 제외한 학부운영위원 중 1인으로 한다. 단, 반 학생회장단 동시선거의 경우, 해당 선거를 진행하는 선거관리위원회의 위원장은 학부 학생회장으로 한다."}],"num":122,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a123","label":"제123조","title":"활동 내용","paras":[{"k":"hang","x":"① 선거관리위원회는 제6장 선거에서 규정하는 선거에 관한 절차를 성실히 이행한다."},{"k":"hang","x":"② 선거관리위원회는 제6장 선거에서 규정하는 절차에 관해 최고 해석권 및 결정권을 가지며, 본회의 어떠한 의결기구도 회칙에 따라 진행된 선거 절차상의 해석 및 결정을 번복·철회·변경할 수 없다."},{"k":"hang","x":"③ 선거관리위원은 선거기간 동안 징계할 수 없으며, 선거관리위원회의 출석 3분의 2 이상에 의한 결의로만 해임될 수 있다."}],"num":123,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a124","label":"제124조","title":"의무","paras":[{"k":"hang","x":"① 선거관리위원회의 결정은 표결로서 진행하며, 표결은 기명으로 진행한다."},{"k":"hang","x":"② 선거관리위원회는 결정 사항 및 선거의 진행 상황을 정기적으로 공고해야 한다."},{"k":"hang","x":"③ 선거관리위원은 중립성을 지켜야 하며, 선거에 부당한 영향을 미치는 활동을 할 수 없다."}],"num":124,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a125","label":"제125조","title":"집행위원회에 대한 사항","paras":[{"k":"hang","x":"① 선거관리위원회는 선거 사무의 처리에 관해 집행위원회의 협조를 얻을 수 있다."},{"k":"hang","x":"② 선거관리위원회는 선거의 원활한 진행을 위해 집행위원회에 사무의 처리를 요청할 수 있다."}],"num":125,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a126","label":"제126조","title":"학부 학생회장단에 대한 사항","paras":[{"k":"hang","x":"① 학부 학생회장단은 학부 학생회장단 선거관리위원회의 결정 및 집행에 일체 개입할 수 없다."},{"k":"hang","x":"② 학부 학생회장단 선거 진행에 학부 학생회장단의 부당한 영향력 행사가 있을시, 선거관리위원회는 선거 기간 동안 기간을 정해 한시적으로 학부 학생회장단의 해당 직무 및 활동을 정지·취소할 수 있다."}],"num":126,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a127","label":"제127조","title":"재정","paras":[{"k":"line","x":"본회는 선거관리위원회의 원활한 운영을 위한 재원을 마련해야 한다."}],"num":127,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제3절 투표관리위원회"},{"t":"art","id":"a128","label":"제128조","title":"목적","paras":[{"k":"line","x":"투표관리위원회는 민주적이고 공정한 절차에 입각해 학생총투표를 효율적으로 진행하는 데 그 목적을 둔다."}],"num":128,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a129","label":"제129조","title":"구성","paras":[{"k":"line","x":"투표관리위원회는 학부운영위원 및 제55조 제4항에 의해 의결권을 가질 수 있는 자 전원으로 구성한다. 단, 학부 학생회장단은 제60조에 따른 학부 학생회장단 탄핵안에 대한 학생총투표에 대해서는 투표관리위원이 될 수 없다."}],"num":129,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a130","label":"제130조","title":"대표자 선출","paras":[{"k":"line","x":"투표관리위원회의 위원장은 학부운영위원 중 1인으로 한다."}],"num":130,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a131","label":"제131조","title":"활동 내용","paras":[{"k":"hang","x":"① 투표관리위원회는 제2장 제3절 학생총투표에서 규정하는 학생총투표에 관한 절차를 성실히 이행한다."},{"k":"hang","x":"② 투표관리위원회는 제2장 제3절 학생총투표에서 규정하는 절차에 관해 최고 해석권 및 결정권을 가지며, 본회의 어떠한 의결기구도 회칙에 따라 진행된 투표 절차상의 해석 및 결정을 번복·철회·변경할 수 없다."}],"num":131,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a132","label":"제132조","title":"준용","paras":[{"k":"hang","x":"① 의무에 관해서는 제124조를 준용한다."},{"k":"hang","x":"② 집행위원회에 대한 사항에 대해서는 제125조를 준용한다."},{"k":"hang","x":"③ 학부 학생회장단에 대한 사항에 대해서는 제126조를 준용한다."},{"k":"hang","x":"④ 재정에 관해서는 제127조를 준용한다."}],"num":132,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제4절 학생자치장학금위원회"},{"t":"art","id":"a133","label":"제133조","title":"위계","paras":[{"k":"line","x":"학생자치장학금의 집행 및 운영에 관하여 회칙·세칙에 규정이 없으면 학생자치장학금 내규에 의하고 내규가 없으면 장학금위원회의 결정사항에 의한다."}],"num":133,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a134","label":"제134조","title":"구성","paras":[{"k":"hang","x":"① 학생자치장학금위원회는 장학금운영위원회와 장학금집행위원회로 구성한다."},{"k":"hang","x":"② 장학금운영위원회는 학부운영위원회 전원으로 구성한다."},{"k":"hang","x":"③ 장학금집행위원회는 공개모집하여야 한다."},{"k":"hang","x":"④ 학생자치장학금위원회 위원은 자유전공학부 학생회 회원 중 징계를 받지 아니한 자로 한다."}],"num":134,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a135","label":"제135조","title":"목적","paras":[{"k":"hang","x":"① 장학금운영위원회는 본 장학금에 관련된 제반 사항을 감시·감독하고 보고받는 데 그 목적을 둔다."},{"k":"hang","x":"② 장학금집행위원회는 본 장학금에 관한 사항을 집행하는 데 그 목적을 둔다."}],"num":135,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a136","label":"제136조","title":"대표자 선출","paras":[{"k":"hang","x":"① 장학금운영위원회의 위원장은 학부 학생회장으로 한다."},{"k":"hang","x":"② 장학금집행위원회의 대표는 장학금집행위원회에서 보통⋅평등⋅직접⋅비밀선거로 선출한다."}],"num":136,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a137","label":"제137조","title":"활동 내용","paras":[{"k":"hang","x":"① 장학금운영위원회는 다음 각호의 업무를 수행한다."},{"k":"ho","x":"1. 장학금 운영사항에 관련된 감독"},{"k":"ho","x":"2. 장학금 지급, 장학금집행위원 및 장학금집행위원회 활동에 대한 감사"},{"k":"ho","x":"3. 장학금 운영 전반에 관련된 정보공개청구"},{"k":"ho","x":"4. 장학금집행위원 임면"},{"k":"ho","x":"5. 학생자치장학금 내규 개정"},{"k":"hang","x":"② 장학금운영위원회는 장학금집행위원회 운영목적에 부합하는 필수적 활동이 이뤄지지 않는 경우, 이러한 활동에 대한 촉구, 지시 혹은 활동 그 자체를 수행할 수 있다. 단, 장학금집행위원회 고유 활동의 집행은 가급적 자제한다."},{"k":"hang","x":"③ 장학금집행위원회는 다음 각호의 업무를 수행한다."}],"num":137,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a138","label":"제138조","title":"준용","paras":[{"k":"hang","x":"① 장학금운영위원회의 의무에 관해서는 제124조를 준용한다. 단, 제124조 제3항은 준용하지 아니한다."},{"k":"hang","x":"② 재정에 관해서는 제127조를 준용한다"},{"k":"hang","x":"③ 장학금운영위원회 회의의 진행에 관한 절차는 출석 과반수에 의한 결의로 학부운영위원회의 절차를 준용할 수 있다."}],"num":138,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a139","label":"제139조","title":"중요활동에 관한 사항","paras":[{"k":"line","x":"장학금운영위원회는 회원에게 중대한 영향을 미치는 장학금집행위원회의 활동에 대하여 동의권을 갖는다. 단, 장학금집행위원회의 효율적인 활동을 보장하기 위하여 장학금집행위원회 대표가 사전 집행이 불가피하다고 판단하여 집행한 사업에 대하여는 사후에 보고하고 승인 절차를 이행할 수 있다. 장학금집행위원회는 부동의된 대외활동에 대해서는 의결 즉시 원상회복을 위해 노력해야 한다."}],"num":139,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제5절 학생홍보대사"},{"t":"art","id":"a140","label":"제140조","title":"목적","paras":[{"k":"line","x":"학생홍보대사는 대외적으로 자유전공학부를 홍보하고, 자유전공학부의 가치 제고 및 위상을 높이는 데 목적을 둔다."}],"num":140,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a141","label":"제141조","title":"구성","paras":[{"k":"hang","x":"① 학생홍보대사는 공개 모집하여야 한다."},{"k":"hang","x":"② 학생홍보대사는 자유전공학부 학생회 회원 중 징계를 받지 아니한 자로 한다."}],"num":141,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a142","label":"제142조","title":"대표자 선출","paras":[{"k":"line","x":"학생홍보대사의 대표는 학생홍보대사 회원 중 보통·평등·직접·비밀선거로 선출한다."}],"num":142,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a143","label":"제143조","title":"활동 내용","paras":[{"k":"line","x":"학생홍보대사의 활동은 다음 각호로 정한다."},{"k":"ho","x":"1. 자유전공학부 홍보 활동 진행"},{"k":"ho","x":"2. 모교 방문 자유전공학부 홍보 행사 진행"},{"k":"ho","x":"3. 학생 초청 자유전공학부 홍보 행사 진행"}],"num":143,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a144","label":"제144조","title":"권리","paras":[{"k":"hang","x":"① 학생홍보대사는 본회로부터 공간을 지원받을 수 있다."},{"k":"hang","x":"② 학생홍보대사는 법학관(신관), CJ법학관, 해송법학도서관 강의실을 대관할 수 있다."},{"k":"hang","x":"③ 학생홍보대사는 학생회 페이스북 페이지, 카카오톡 공지방, 행정실 게시판을 활용할 수 있다."}],"num":144,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a145","label":"제145조","title":"재정","paras":[{"k":"line","x":"본회는 학생홍보대사의 원활한 운영을 위한 재원을 마련해야 한다."}],"num":145,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제6절 소수자인권위원회"},{"t":"art","id":"a146","label":"제146조","title":"목적","paras":[{"k":"line","x":"소수자인권위원회는 본회 내 소수자의 인권을 증진하는 데 목적을 둔다."}],"num":146,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a147","label":"제147조","title":"구성","paras":[{"k":"hang","x":"① 소수자인권위원회는 공개 모집하여야 한다."},{"k":"hang","x":"② 소수자인권위원회는 자유전공학부 학생회 회원 중 징계를 받지 아니한 자로 한다."}],"num":147,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a148","label":"제148조","title":"대표자 선출","paras":[{"k":"line","x":"소수자인권위원회의 대표는 소수자인권위원회 회원 중 보통·평등·직접·비밀선거로 선출한다."}],"num":148,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a149","label":"제149조","title":"활동 내용","paras":[{"k":"line","x":"소수자인권위원회의 활동은 다음 각호로 정한다."},{"k":"ho","x":"1. 인권 담론의 공고화 및 확장"},{"k":"ho","x":"2. 인권침해의 발생 방지 노력"},{"k":"ho","x":"3. 인권침해 피해자에 대한 보호"},{"k":"ho","x":"4. 인권 관련 전문 역량의 확보"}],"num":149,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a150","label":"제150조","title":"권리","paras":[{"k":"hang","x":"① 소수자인권위원회는 본회로부터 공간을 지원받을 수 있다."},{"k":"hang","x":"② 소수자인권위원회는 법학관(신관), CJ 법학관, 해송법학도서관 강의실을 대관할 수 있다."},{"k":"hang","x":"③ 소수자인권위원회는 학생회 페이스북 페이지, 카카오톡 공지방, 행정실 게시판을 활용할 수 있다."}],"num":150,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a151","label":"제151조","title":"재정","paras":[{"k":"line","x":"본회는 소수자인권위원회의 원활한 운영을 위한 재원을 마련해야 한다."}],"num":151,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제6장 선거"},{"t":"h","lv":3,"text":"제1절 학부 학생회장단 선거"},{"t":"art","id":"a152","label":"제152조","title":"선거 방식","paras":[{"k":"hang","x":"① 학부 학생회장단은 회원의 보통·평등·직접·비밀 선거로 선출한다."},{"k":"hang","x":"② 학부 학생회장단 선거에는 학부 학생회장 후보 단독으로 출마하거나 학부 학생회장 후보와 학부 부학생회장 후보 각 한 명씩이 조를 이루어 입후보할 수 있다."},{"k":"hang","x":"③ 학부 학생회장단 선거 방식에 대한 세부적인 사항은 「자유전공학부 학부·반 선거 시행세칙」으로 정한다."}],"num":152,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a153","label":"제153조","title":"시기","paras":[{"k":"line","x":"학부 학생회장단 선거는 매년 11월에 시행함을 그 원칙으로 한다. 세부 일정은 학부운영위원회에서 정한다."}],"num":153,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a154","label":"제154조","title":"선거권·피선거권","paras":[{"k":"hang","x":"① 본회 정회원은 학부 학생회장단 선거의 선거권이 있다. 단, 휴학생 회원과 수료생 회원의 경우 정회원 등록 절차를 통해 당해 선거에 있어 선거권을 가질 수 있다."},{"k":"hang","x":"② 본회의 회원인 자는 학부 학생회장단 선거의 피선거권이 있다."},{"k":"hang","x":"③ 학부 학생회장단 선거에 출마하려는 후보는 3학기 이상 등록자이어야 한다."},{"k":"hang","x":"④ 징계로서 선거권과 피선거권을 박탈당한 자는 선거의 선거권과 피선거권이 없다."}],"num":154,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a155","label":"제155조","title":"선거관리위원회","paras":[{"k":"hang","x":"① 학부 학생회장단 선거를 공정하게 민주적으로 관리하기 위하여 선거관리위원회를 둔다."},{"k":"hang","x":"② 선거관리위원회는 회칙과 ｢자유전공학부 학부·반 선거시행세칙｣에 따라 학부 학생회장단 선거에 관련된 모든 사항을 결정한다."},{"k":"hang","x":"③ 선거 기간 동안 학부 학생회장단과 집행위원회가 사업 집행, 의견 표명 등을 하기 위해서는 선거 관리위원회의 사전 허가를 받아야 한다. 학생회장단과 집행위원회의 특정 행위가 선거에 영향을 미칠 수 있다고 판단되면 선거관리위원회는 해당 행위를 허가하지 않을 수 있다."},{"k":"hang","x":"④ 이 밖에 선거관리위원회의 운영에 관한 절차는 제5장 제2절 선거관리위원회 규정에 따른다."}],"num":155,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a156","label":"제156조","title":"보궐선거","paras":[{"k":"hang","x":"① 학생회장단이 탄핵 등의 이유로 궐위된 때 잔여 임기가 180일이 넘으면 궐위된 날로부터 10일 이내에 학부운영위원회는 보궐선거의 시행 일정을 결정하여야 한다. 단, 임기 종료일이 확정되지 않았을 때는 잔여 임기의 계산을 위한 임기 종료일은 11월 30일로 한다."},{"k":"hang","x":"② 잔여 임기가 180일이 넘지 않은 경우에도 학부운영위원회는 선거의 필요성, 선거 시기, 잔여 임기 등 본회의 제반 사정을 고려하여 보궐선거의 시행을 결정할 수 있다."},{"k":"hang","x":"③ 학부운영위원회가 보궐선거 시행 일정을 확정한 날로부터 20일 이내에 보궐선거를 시행하여야 한다."}],"num":156,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a157","label":"제157조","title":"선거시행세칙","paras":[{"k":"line","x":"그 밖에 선거에 관한 사항은 ｢자유전공학부 학부·반 선거 시행세칙｣으로 정한다."}],"num":157,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 반 학생회장단 동시선거"},{"t":"art","id":"a158","label":"제158조","title":"반 학생회장단 동시선거","paras":[{"k":"hang","x":"① 학부 학생회장단 선거관리위원회는 학부운영위원회의 출석 과반수에 의한 결의로 반 학생회장단 동시선거를 진행할 수 있다."},{"k":"hang","x":"② 제1항에서 규정하는 동시선거를 진행하지 않는 경우, 각 반 학생회장단 선거에 관한 제반 사항은 각 반 학생회칙이 정하는 바에 의한다."},{"k":"hang","x":"③ 반 학생회장단 동시선거가 결정되면, 본회의 회칙 및 학부·반 선거시행세칙이 규정하는 절차에 따라 반 학생회장단 선거를 진행한다."}],"num":158,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a159","label":"제159조","title":"준용","paras":[{"k":"hang","x":"① 선거 방식에 관해서는 제152조를 준용한다."},{"k":"hang","x":"② 선거 시기에 관해서는 제153조를 준용한다."},{"k":"hang","x":"③ 선거권에 관해서는 제154조를 준용한다."},{"k":"hang","x":"④ 선거관리위원회에 관해서는 제155조를 준용한다."},{"k":"hang","x":"⑤ 보궐선거에 관해서는 제156조를 준용한다."},{"k":"hang","x":"⑥ ｢선거시행세칙｣에 관해서는 제157조를 준용한다."}],"num":159,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제7장 재정"},{"t":"h","lv":3,"text":"제１절 통칙"},{"t":"art","id":"a160","label":"제160조","title":"원칙","paras":[{"k":"line","x":"본회의 각 기구는 재정을 효율적이고 투명하게 운용하여야 한다."}],"num":160,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a160-2","label":"제160조의2","title":"등기부","paras":[{"k":"hang","x":"① 본회는 다음 각호의 등기부를 두어 운용한다. 본회의 회원 또는 기구 간에 관리권한, 자산, 자치공간 등에 대한 분쟁이 있는 경우 등기부에 기재된 사항을 진실한 것으로 추정한다."},{"k":"ho","x":"1. 「관리권한등기부」"},{"k":"ho","x":"2. 「자산등기부」"},{"k":"ho","x":"3. 「자치공간등기부」"},{"k":"hang","x":"② 등기부의 관리는 집행위원회의 사무로 하되, 정정 또는 경정의 청구 기간이 경과하여 확정된 등기부 기재사항에 대하여는 제33조에 따라 변경 또는 취소할 수 없다."},{"k":"hang","x":"③ 등기부는 본회의 회원이 언제나 열람할 수 있도록 유·무형의 공간에 비치하여야 하며, 집행위원회는 기재사항에 변경이 있는 때에는 지체 없이 그 사실을 공고해야 한다."},{"k":"hang","x":"④ 본회의 회원은 등기부의 기재사항에 대하여 전항의 공고가 있은 때로부터 30일 내에 집행위원회에 기재사항에 대한 정정 또는 경정을 청구할 수 있다."},{"k":"hang","x":"⑤ 전항의 청구에 있어서 이해관계자 간의 분쟁이 있는 경우에는 임시 학생대표자회를 개의하여 심의 및 의결한다."}],"num":160,"sub":2,"bu":false,"bold_title":false},{"t":"art","id":"a161","label":"제161조","title":"재정운용세칙","paras":[{"k":"line","x":"그 밖에 재정 운용에 관한 사항은 ｢고려대학교 총학생회 재정운용세칙｣을 준용한다."}],"num":161,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제２절 자산·배분"},{"t":"art","id":"a162","label":"제162조","title":"자산","paras":[{"k":"hang","x":"① 본회는 유·무형의 동산, 부동산, 권리 등을 소유할 수 있으며, 이를 본회의 자산이라 한다."},{"k":"hang","x":"② 본회의 자산은 각 기구가 독립하여 취득, 보관, 사용, 처분함을 원칙으로 한다."},{"k":"hang","x":"③ 집행기구는 제작, 구매, 수증 등의 방법으로 자산을 취득한다. 다음 각호 중 어느 하나에 해당하는 것은 집행기구의 자산으로 본다."},{"k":"ho","x":"1. ｢자산등기부｣에 집행위원회의 자산으로 등기된 것"},{"k":"ho","x":"2. 학부 학생회장단·집행위원과 이에 준하는 자가 그 직으로써 취득한 것"},{"k":"ho","x":"3. 본회 집행기구의 사업 또는 사무 집행을 위하여 취득하거나, 사업 집행의 결과물로 취득한 것"},{"k":"ho","x":"4. 제1호 내지 제3호에 해당하는 자산으로부터 파생된 것"}],"num":162,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a163","label":"제163조","title":"자산의 관리","paras":[{"k":"hang","x":"① 본회의 각 기구는 자산을 항상 사용하거나 처분할 수 있도록 선량한 관리자의 주의로써 보관하여야 한다."},{"k":"hang","x":"② 집행기구의 자산은 본회 사업과 사무의 집행을 위하여 사용함을 원칙으로 한다."},{"k":"hang","x":"③ 집행기구의 자산은 대여를 목적으로 한 자산이거나 대여하여도 사업 또는 사무에 지장이 없다고 인정되는 자산일 때만 대여할 수 있다. 또한, 집행기구의 자산은 본회 기구와 회원에게 우선적으로 대여되어야 한다."},{"k":"hang","x":"④ 집행기구는 자산의 취득, 보관, 사용, 처분이 본회의 이익을 위하여 적정하고 효율적으로 이루어질 수 있도록 하여야 한다."},{"k":"hang","x":"⑤ 집행기구는 자산의 중대한 변화를 야기하는 집행에 대해 학부운영위원회의 인준을 받아야 한다. 이 경우, 사전에 집행에 대한 예고를 해야 하며, 집행 후 자산 변화를 공고해야 한다."},{"k":"hang","x":"⑥ 집행위원회는 집행기구 자산 중 고정자산의 목록을 작성하여 매 학기 정기학생총회 또는 정기학생대표자회에 보고한다."},{"k":"hang","x":"⑦ 본회의 각 기구는 사용할 필요가 없거나 사용할 수 없는 자산을 교환, 매각, 증여, 폐기 등의 방법으로 처분할 수 있다."},{"k":"hang","x":"⑧ 의결기구는 집행기구의 자산 취득, 보관, 사용, 처분이 본회의 이익을 위한 것이 아니거나, 적정성 또는 효율성이 없다고 판단되면 이를 허가하지 않거나, 취소할 수 있다."}],"num":163,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a164","label":"제164조","title":"수입","paras":[{"k":"line","x":"본회 재정의 수입은 학생회비, 학교 지원금, 사업별 후원금, 그 밖에 수익금으로 한다."}],"num":164,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a165","label":"제165조","title":"학생회비","paras":[{"k":"hang","x":"① 학생회비는 일시납부·1회 납부를 원칙으로 한다. 단, 일시납부 하지 못할 경제적·사회적 또는 그 밖의 중대한 사유가 있는 경우 분할납부를 할 수 있다."},{"k":"hang","x":"② 집행위원회는 학생회비의 수입 및 지출과 관련된 집행내역을 매달 날짜를 정하여 공고하여야 한다."},{"k":"hang","x":"③ 학부 학생회비의 수입 중 반 학생회비에 할당되는 금액은 반 학생회 소속 학생회비 납부자 1인당 40,000원으로 한다."},{"k":"hang","x":"④ 학생총회 또는 학생대표자회는 매년 2학기 정기회의에서 학부 학생회비의 조정에 관하여 논의하여, 필요할 때는 인상·인하를 결정할 수 있다."}],"num":165,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제３절 회계·심의"},{"t":"art","id":"a166","label":"제166조","title":"회계연도","paras":[{"k":"line","x":"본회의 재정은 다음 각호의 기간으로 나누어 집행하고 결산한다."},{"k":"ho","x":"1. 제1분기: 2학기 종강일 다음 날부터 1학기 개강일 전날까지"},{"k":"ho","x":"2. 제2분기: 1학기 개강일부터 1학기 종강일까지"},{"k":"ho","x":"3. 제3분기: 1학기 종강일 다음 날부터 2학기 개강일 전날까지"},{"k":"ho","x":"4. 제4분기: 2학기 개강일부터 2학기 종강일까지"}],"num":166,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a167","label":"제167조","title":"학부운영위원회 심의","paras":[{"k":"hang","x":"① 학생회비를 사용하는 집행위원회 및 독립기구 등은 다음 각호에 따라 예산안·결산을 작성하여 학생총회 또는 학생대표자회 개의 예정일 7일 전까지 학부운영위원회에 제출하여야 한다."},{"k":"ho","x":"1. 1학기 정기회의: 작년도 4분기, 금년도 1분기의 결산과 금년도 2분기·3분기의 예산안"},{"k":"ho","x":"2. 2학기 정기회의: 금년도 2분기·3분기의 결산과 금년도 4분기, 익년도 1분기의 예산안"},{"k":"hang","x":"② 학부운영위원회는 제１항에 따른 예산안·결산 제출기한을 정하여 공고하고 예산안·결산 보고의 의무가 있는 기구에 개별적으로 통보하여야 한다."},{"k":"hang","x":"③ 학부운영위원회는 제１항에 따라 제출된 예산안·결산을 심의한다."}],"num":167,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a168","label":"제168조","title":"승인","paras":[{"k":"hang","x":"① 학생회비를 사용하는 집행위원회 및 독립기구 등은 제167조 제1항에 따라 학부운영위원회의 심의를 거친 예산안·결산을 학생총회 또는 학생대표자회에 보고한다."},{"k":"hang","x":"② 학생대표자회 또는 학생총회는 제１항에 따라 보고된 예산안·결산을 승인한다."},{"k":"hang","x":"③ 학생대표자회 또는 학생총회에서 승인된 예산안·결산은 공개되어야 한다."},{"k":"hang","x":"④ 각 기구는 학생총회 또는 학생대표자회 출석 구성원의 과반수에 의한 동의가 있으면 예산안·결산을 현장에서 수정 발의하여 재상정할 수 있다."}],"num":168,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a169","label":"제169조","title":"재심의","paras":[{"k":"hang","x":"① 다음 각호에 해당하는 경우, 학생총회 또는 학생대표자회는 출석 과반수의 찬성으로 해당 기구에의 학생회비 지급을 유보하고 학부운영위원회에서 재심의를 받도록 해야 한다. 재심의에서의 승인은 학부운영위원회 출석 3분의 2 이상의 결의에 의한다."},{"k":"ho","x":"1. 예산안·결산이 승인되지 못한 경우"},{"k":"ho","x":"2. 예산안·결산에 중대한 하자가 있는 경우"},{"k":"ho","x":"3. 심의 과정 중 절차상 문제가 발견된 경우"},{"k":"ho","x":"4. 판단자료 미비로 예산안·결산에 대한 심의가 불가능하거나 예산안·결산을 신뢰할 수 없을 경우"},{"k":"hang","x":"② 제１항에 해당하는 기구는 학생총회 또는 학생대표자회 개의일로부터 10일 이내에 수정안을 작성하여 학부운영위원회에 제출해야 한다."},{"k":"hang","x":"③ 학부운영위원회는 수정안을 지체 없이 심의하여 학생총회 또는 학생대표자회 개의일로부터 15일 이내에 결과를 공고한다."},{"k":"hang","x":"④ 제１항에 해당함에도 수정안을 학부운영위원회에 제출하지 않은 기구 혹은 제기된 문제를 개선하지 않은 채 수정안을 작성하여 제출한 기구는 책임자에 따라 각호 중 하나의 징계를 한다. 책임자란 불승인 결정에 직·간접적인 책임이 있는 대표자 및 기구의 구성원을 의미한다."},{"k":"ho","x":"1. 책임자가 현직일 때: 예산 지급액의 50% 삭감과 사과문·경위서 게재"},{"k":"ho","x":"2. 책임자가 전직일 때: 책임자의 사과문·경위서 게재"},{"k":"hang","x":"⑤ 배임, 횡령 사안 등 문제의 정도가 심각한 경우 학부운영위원회는 제4항의 징계와 함께 다음 각호의 조치를 함께 결정할 수 있다. 제3호의 경우 책임자와 학생회비가 불법하게 사용될 당시 대표자가 연대하여 책임을 져야 한다."},{"k":"ho","x":"1. 기구가 가지고 있는 학생회비 잔금 사용 중지"},{"k":"ho","x":"2. 기구가 가지고 있는 학생회비 잔금 전액 환수"},{"k":"ho","x":"3. 기구가 불법하게 사용한 학생회비 전액 반환"}],"num":169,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제8장 자치공간"},{"t":"art","id":"a170","label":"제170조","title":"목적","paras":[{"k":"line","x":"본회의 자치공간은 본회의 자치활동의 기초가 되는 토대로서, 회원의 교류 및 결속을 공고히 하고 회원을 보호하며 안정을 보장해주는 역할을 통해 창조적이고 진보적인 대학문화를 건설하는 데 기여함을 목적으로 한다."}],"num":170,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a171","label":"제171조","title":"자치공간","paras":[{"k":"hang","x":"① 본회의 자치공간은 다음 각호로 정한다."},{"k":"ho","x":"1. ｢자치공간등기부｣에 등기된 공간"},{"k":"ho","x":"2. 학부 학생회실"},{"k":"ho","x":"3. 법학관(구관) 각 반 학생회실, 각 자치단체실, 학생회창고, 코웍스"},{"k":"ho","x":"4. 기타 본회의 노력으로 확보·명도 받은 공간"},{"k":"hang","x":"② 본회의 각 기구 및 회원은 대내외적으로 자치공간을 이용, 분배, 회수, 보수, 개조할 관리 권한을 갖는다. 관리 권한이라 함은 각 사안의 원활한 운영을 위하여 배타적인 권리행사 및 집행을 할 수 있는 권원을 의미한다."}],"num":171,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a172","label":"제172조","title":"준자치공간","paras":[{"k":"hang","x":"① 본회의 지배·관리하에 있지 않지만, 학교의 승인을 얻어 본회 회원의 자유로운 이용이 보장된 공간을 준자치공간이라고 한다."},{"k":"hang","x":"② 준자치공간은 다음 각호로 정한다."},{"k":"ho","x":"1. CJ법학관 남학생 휴게실"},{"k":"ho","x":"2. CJ법학관 여학생 휴게실"},{"k":"ho","x":"3. CJ법학관 및 해송법학도서관 라운지"},{"k":"ho","x":"4. CJ법학관 및 해송법학도서관 스터디룸"},{"k":"ho","x":"5. 법학관(구관), 법학관(신관), CJ법학관 강의실"},{"k":"ho","x":"6. 그 밖의 기타 학생 편의시설"}],"num":172,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a173","label":"제173조","title":"의무","paras":[{"k":"line","x":"본회는 자치공간에 대해 다음 각호의 의무가 있다."},{"k":"ho","x":"1. 자치공간에 대한 본회의 자치권이 침해받지 않도록 수호"},{"k":"ho","x":"2. 자치공간의 안전 및 청결 유지"},{"k":"ho","x":"3. 자치공간 이용과 관련한 갈등 해결"},{"k":"ho","x":"4. 회원의 자치공간 이용 기회보장"}],"num":173,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a174","label":"제174조","title":"자치공간운영세칙","paras":[{"k":"line","x":"그 밖의 자치공간에 관한 자세한 내용은 「자유전공학부 자치공간운영세칙」으로 정한다."}],"num":174,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제9장 회칙·세칙·규칙"},{"t":"h","lv":3,"text":"제１절 회칙 개정"},{"t":"art","id":"a175","label":"제175조","title":"개정안 발의","paras":[{"k":"hang","x":"① 회칙 개정안은 다음 각호 중 하나에 따라 발의된다."},{"k":"ho","x":"1. 학부운영위원회의 출석 과반수에 의한 발의"},{"k":"ho","x":"2. 학부운영위원회 재적 위원 과반수의 연서에 따른 발의"},{"k":"ho","x":"3. 회원 10분의 1의 연서에 따른 발의"},{"k":"ho","x":"4. 회칙개정특별위원회에 의한 발의"},{"k":"hang","x":"② 연서에 따른 소집요구는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식을 준용하며, ｢고려대학교 총학생회 사무처리세칙｣에서 정한 사항이 포함되어야 한다."}],"num":175,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a176","label":"제176조","title":"개정안 공고","paras":[{"k":"line","x":"회칙 개정안이 발의되면 학부 학생회장은 다음 각호의 사항을 7일 이상 공고하여야 한다."},{"k":"ho","x":"1. 회칙 개정안의 제안이유와 주요 내용"},{"k":"ho","x":"2. 신·구조문 대비표"},{"k":"ho","x":"3. 제175조에 따른 회칙 개정안 발의자 명단"}],"num":176,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a177","label":"제177조","title":"개정안 심의","paras":[{"k":"hang","x":"① 제175조 제１항 제１호의 경우 회칙 개정을 위한 학생총회 또는 학생대표자회 개의에 앞서 학부운영위원회에서 개정안을 심의하거나, 별도의 공청회를 개최하여 개정안을 심의한다."},{"k":"hang","x":"② 개정안 심의 과정에는 축조심사와 찬반 토론이 포함되어야 한다."}],"num":177,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a178","label":"제178조","title":"개정 의결","paras":[{"k":"hang","x":"① 회칙 개정안이 발의되었을 때 본회 의결기구의 의장은 지체 없이 학생총회 또는 학생대표자회를 소집하여 회칙 개정안을 심의·의결한다."},{"k":"hang","x":"② 회칙 개정의 의결은 제23조 제３항에 따라 기명투표로 표결한다."},{"k":"hang","x":"③ 회칙 개정의 의결 요건은 제30조 제２항 및 제57조의2 제2항에 따른다."}],"num":178,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a179","label":"제179조","title":"개정안 정리","paras":[{"k":"line","x":"회칙 개정의 의결이 있은 후 저촉되는 조항·자구·숫자 그 밖의 기타 정리가 필요한 경우 학부운영위원회는 회칙 개정의 공포 전까지 이를 검토하여 정리할 수 있다. 단, 개정 의결된 회칙의 내용이나 취지를 변경하는 것은 허용되지 아니한다."}],"num":179,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a180","label":"제180조","title":"공포","paras":[{"k":"hang","x":"① 회칙 개정이 의결되면 학부 학생회장은 개정안 정리를 거쳐 3일 이내에 공포한다."},{"k":"hang","x":"② 회칙의 공포문에는 다음 각호의 사항이 포함되어야 한다."},{"k":"ho","x":"1. 회칙 개정안의 제안이유와 주요 내용"},{"k":"ho","x":"2. 신·구조문 대비표"},{"k":"ho","x":"3. 제175조에 따른 회칙 개정안 발의자 명단"},{"k":"ho","x":"4. 회칙 개정 찬성자 명단"},{"k":"hang","x":"③ 본조는 세칙과 규칙의 제정·개정·폐지에도 준용한다. 단, 세칙 제정의 공포 시에는 세칙의 제정 순서에 따라 번호를 붙여서 공포하며, 규칙 제정의 공포 시에는 제정의 근거가 되는 세칙별로 규칙의 제정 순서에 따라 번호를 붙여서 공포한다."}],"num":180,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제２절 세칙·규칙"},{"t":"art","id":"a181","label":"제181조","title":"세칙·규칙","paras":[{"k":"hang","x":"① 본회는 회칙에 따라 세칙을 제정·개정하고, 세칙에 따라 규칙을 제정·개정한다. 단, 일반규칙은 세칙에 근거를 두지 않고 제정·개정할 수 있다."},{"k":"hang","x":"② 회칙에 위반되는 세칙과 세칙에 위반되는 규칙은 그 위반되는 부분에 한정하여 효력이 없다."},{"k":"hang","x":"③ 회칙에 위반되는 산하기구의 자치규칙은 성립하지 아니하고, 그 위반되는 부분에 한하여 효력이 없다."}],"num":181,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a182","label":"제182조","title":"세칙의 제정·개정·폐지","paras":[{"k":"hang","x":"① 세칙은 회칙에서 위임한 사항과 회칙을 시행하기 위한 사항을 정하기 위하여 제정한다."},{"k":"hang","x":"② 세칙은 학생총회 또는 학생대표자회에서 제정·개정·폐지를 의결한다."},{"k":"hang","x":"③ 세칙의 제정·개정·폐지는 제175조를 준용한다."},{"k":"hang","x":"④ 세칙 개정안의 정리에 관하여서는 제179조를 준용한다."},{"k":"hang","x":"⑤ 세칙 제정 및 개정의 공포에 관하여서는 제180조를 준용한다."}],"num":182,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a183","label":"제183조","title":"세칙에 부수된 규칙의 제정·개정·폐지","paras":[{"k":"hang","x":"① 세칙에 부수된 규칙은 해당 세칙에서 위임한 사항과 해당 세칙을 시행하기 위한 사항을 정하기 위하여 제정한다."},{"k":"hang","x":"② 세칙에 부수된 규칙은 해당 세칙의 근거 규정에 따라 제정·개정·폐지된다."},{"k":"hang","x":"③ 세칙에 부수된 규칙의 공포에 관하여서는 제180조를 준용한다."}],"num":183,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a184","label":"제184조","title":"일반규칙의 제정·개정·폐지","paras":[{"k":"hang","x":"① 일반규칙은 다음 각호의 사항을 규율하기 위해 제정한다."},{"k":"ho","x":"1. 의결기구에 관한 사항"},{"k":"ho","x":"2. 집행기구에 관한 사항"},{"k":"ho","x":"3. 산하기구에 관한 사항"},{"k":"ho","x":"4. 독립기구에 관한 사항"},{"k":"ho","x":"5. 본회의 정기사업·비정기사업에 관한 사항"},{"k":"ho","x":"6. 회원의 권리·의무에 관한 사항"},{"k":"ho","x":"7. 자치단체에 관한 사항"},{"k":"ho","x":"8. 학교 시설 사용 등에 대한 회원 전체의 합의에 관한 사항"},{"k":"ho","x":"9. 학교 당국과의 합의에 관한 사항"},{"k":"ho","x":"10. 본회와 학내 각 단체 간의 합의에 관한 사항"},{"k":"ho","x":"11. 본회와 외부단체와의 합의에 관한 사항"},{"k":"ho","x":"12. 회칙의 특정 조문에 관한 추가적인 사항"},{"k":"ho","x":"13. 그 밖에 규칙으로 명문화하는 것이 필요하다고 인정되는 사항"},{"k":"hang","x":"② 일반규칙은 학부운영위원회가 제정·개정·폐지를 의결한다."},{"k":"hang","x":"③ 일반규칙의 공포에 관하여서는 제180조를 준용한다."}],"num":184,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제３절 해석"},{"t":"art","id":"a185","label":"제185조","title":"회칙 해석의 원칙","paras":[{"k":"hang","x":"① 회칙을 해석·적용함에 있어서는 해당 조항의 문맥적 의미와 회칙 전체의 논리적 체계성에 비추 어 본회의 민주적 운영이 저해되거나 회원의 권리가 부당하게 침해되지 않도록 주의하여야 한다."},{"k":"hang","x":"② 본회의 중요 사항과 회원의 권리·의무에 중대한 변화를 야기하는 회칙의 해석은 회원들을 상대로 의견을 수렴하기 위한 공청회를 개최할 수 있다."},{"k":"hang","x":"③ 세칙·규칙에 관하여서도 본조를 적용한다."}],"num":185,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"부칙","bu":true,"id":"bu1"},{"t":"free","paras":[{"k":"line","x":"이 회칙은 2021. 11. 13.부터 시행한다."}]}],"note":"2021.11.13 회칙에 2023년 일부개정안 신구조문대비표(제79조 제1항 제1호)를 반영해 재구성한 본입니다. 원본 전문 파일은 없습니다."},{"id":"hoechik-20231112","date":"2023.11.12","kind":"일부개정","title":"고려대학교 자유전공학부 학생회칙","subtitle":null,"history":[["2009. 03.","제정"],["2011. 05. 11.","일부개정"],["2013. 10. 30.","일부개정"],["2014. 03. 26.","일부개정"],["2014. 09. 22.","일부개정"],["2015. 03. 24.","일부개정"],["2015. 09. 22.","일부개정"],["2016. 08. 29.","전부개정"],["2017. 03. 02.","일부개정"],["2017. 05. 27.","전부개정"],["2017. 08. 19.","전부개정"],["2018. 10. 12.","전부개정"],["2021. 11. 13.","전부개정"],["2023. 02. 11.","일부개정"],["2023. 11. 12.","일부개정"]],"pdf":"pdf/hoechik-20231112.pdf","pdfName":"고려대학교_자유전공학부_학생회칙(2023.11.12_일부개정).pdf","blocks":[{"t":"pre","title":"전문","paras":["정의를 추구하는 고려대학교의 역사적 사명과 함께 공동체를 선도하고 연대하는 자유전공학부는 창설 이래 이어져 온 민주적 전통과 자유·정의·진리를 좇는 본교의 교육 이념, 학문 및 사상에 대한 창조적 탐구 정신을 이어받아 자유전공학부의 주체적이고 자율적이며 민주적인 활동을 다짐하는 바이다. 이에 2009년 3월 제정되고 12차에 걸쳐 개정된 자유전공학부 학생회칙을 자유전공학부 학생대표자회의의 의결을 거쳐 개정한다."],"date":null},{"t":"h","lv":2,"text":"제1장 총칙"},{"t":"art","id":"a1","label":"제1조","title":"명칭","paras":[{"k":"line","x":"본회는 고려대학교 자유전공학부 학생회라 칭한다."}],"num":1,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a2","label":"제2조","title":"목적","paras":[{"k":"hang","x":"① 본회는 민주적이고 자율적인 학생자치활동을 통하여 회원 간의 결속을 강화하고 회원의 권익 신장을 도모하며 자유로운 진리의 탐구와 창조적이고 진보적인 대학문화의 건설을 추구하여 사회발전에 능동적으로 기여한다."},{"k":"hang","x":"② 본회는 시대의 불의에 맞서 사회적 연대를 구축하고 침해된 정의의 회복을 위해 대내외에서 주체적으로 행동한다."},{"k":"hang","x":"③ 본회는 본회의 자산 및 자치공간과 회원이 지닌 권리를 보호한다."},{"k":"hang","x":"④ 본회는 법률적 기초소양 및 다양한 영역에서의 복합적 전문성을 갖춘 공적 영역의 선도적 지도자를 양성한다는 교육목적을 달성하기 위해 노력하며, 제1전공이 다른 회원들 간의 교류를 장려한다."}],"num":2,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a3","label":"제3조","title":"위치","paras":[{"k":"line","x":"본회는 서울특별시 성북구 안암동 고려대학교 법학관(구관), 법학관(신관) 및 CJ법학관에 위치한다."}],"num":3,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a4","label":"제4조","title":"회원","paras":[{"k":"hang","x":"① 본회의 회원은 입학·재입학·편입학·소속변경 등으로 고려대학교 자유전공학부 소속이 된 자를 원칙으로 한다."},{"k":"hang","x":"② 졸업, 자퇴, 퇴학 등으로 고려대학교 서울캠퍼스 학부과정 소속이 아니게 된 자 및 총학생회 제명으로 인해 총학생회 회원 직을 박탈당한 자는 그 즉시 회원 자격을 잃으며 정학 등의 사유로 등교가 정지된 자는 그 기간 회원 자격이 정지된다."},{"k":"hang","x":"③ 제2항의 경우 회원의 자격이 부당하게 정지, 박탈된 자는 학부운영위원회의 출석 3분의 2 이상에 해당하는 결의로 회원 지위를 회복할 수 있다."},{"k":"hang","x":"④ 본회의 회원 중 재학 중인 자는 다음 각호의 기간 동안 본회의 정회원이 된다. 단, 재학 중 휴학 한 자는 그 즉시 정회원 자격을 상실하고 휴학생 회원이 된다."},{"k":"ho","x":"1. 1학기 재학생 : 1학기 개강일로부터 2학기 개강일 전일"},{"k":"ho","x":"2. 2학기 재학생 : 2학기 개강일로부터 이듬해 1학기 개강일 전일"},{"k":"hang","x":"⑤ 본회의 회원 중 휴학한 자는 휴학생 회원, 수료한 자는 수료생 회원이라고 하며, 선거권을 지닐 수 없다. 단, 휴학생 회원과 수료생 회원 중에서 다음 각호의 등록기간에 등록 절차를 이행한 자는 남은 기간 정회원이 된다. 자유전공학부 학부·반 학생회장단 선거의 특수성을 고려하여 선거 후보자 등록 마감일 다음 날부터 당선 공고일까지는 정회원 등록을 할 수 없다. 그 밖에 정회원 등록에 관한 사항은 규칙으로 정한다."},{"k":"ho","x":"1. 1학기 정회원 등록기간: 1학기 개강일부터 2학기 개강일 전날까지"},{"k":"ho","x":"2. 2학기 정회원 등록기간: 2학기 개강일부터 이듬해 1학기 개강일 전날까지"},{"k":"hang","x":"⑥ 본회의 회원 중에서 신입생 회원과 두 학번 이상 차이가 나는 회원은 고학번 회원이라고 한다."},{"k":"hang","x":"⑦ 본회의 회원 중에서 다음 각호에 해당하는 회원은 신입생 회원이라고 한다."},{"k":"ho","x":"1. 고려대학교에 입학한 지 2학기가 지나지 않은 회원"},{"k":"ho","x":"2. 편입학·소속변경 등으로 자유전공학부 재학생이 된 지 2학기가 지나지 않은 회원"},{"k":"hang","x":"⑧ 회원 여부에 시비가 있을 시 자유전공학부 학부운영위원회는 자유전공학부 행정실을 통해 확인한 재학생 명단, 휴학생 명단을 참고하여 회원 여부를 판단한다."}],"num":4,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a5","label":"제5조","title":"회원의 권리와 의무","paras":[{"k":"hang","x":"① 본회의 회원은 성별·연령·장애·병력·피부색·용모 등 신체조건, 인종·언어·출신국가·출신민족·출신지역 등 출생지, 혼인상태·출산형태 등 가족 형태, 종교·정치적견해·성적지향·성별정체성·출신학교·학력·전공·재산 등 사회적 신분에 의하여 차별을 받지 아니한다."},{"k":"hang","x":"② 본회의 회원은 본회의 모든 자치활동에 참여할 권리와 회칙에 근거한 선거권, 피선거권을 가진다."},{"k":"hang","x":"③ 본회의 회원은 회칙에 따라 본회의 활동과 운영 전반에 관하여 의견을 개진할 권리와 본회를 부인하거나 정당한 학생자치활동을 침해하는 것에 대해 저항할 권리를 가진다."},{"k":"hang","x":"④ 본회의 회원은 집회·결사의 자유 및 자유로운 종교·정치 활동에 대한 권리를 가진다."},{"k":"hang","x":"⑤ 본회의 회원은 본회의 모든 활동 및 재정 운영에 대해 보고를 받을 권리를 가진다."},{"k":"hang","x":"⑥ 본회의 회원은 본회가 지니는 급부를 적절한 시기에 제공받을 권리를 가진다."},{"k":"hang","x":"⑦ 본회의 회원은 자치공간 및 본회 자산을 향유할 권리를 가진다."},{"k":"hang","x":"⑧ 본회의 회원은 회칙을 준수할 의무를 지닌다."},{"k":"hang","x":"⑨ 본회의 회원은 본회가 결정한 사항을 준수할 의무를 지닌다."},{"k":"hang","x":"⑩ 본회의 회원은 회비를 납부할 의무를 지닌다."},{"k":"hang","x":"⑪ 본회의 회원은 본회의 자산을 보호할 의무를 지닌다."}],"num":5,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a6","label":"제6조","title":"본회와 각 기구의 의무","paras":[{"k":"hang","x":"① 본회와 본회의 각 기구는 고학번 회원의 본회와 본회의 각 기구 활동 참여를 보장해야 하며, 회원 간 원활한 교류를 위해 노력해야 한다."},{"k":"hang","x":"② 본회와 본회의 각 기구는 신입생 회원이 학번·연령으로 인해 부당한 대우를 받지 않도록 노력해야 한다."},{"k":"hang","x":"③ 본회와 본회의 각 기구는 전조에 열거된 회원의 권리가 대내외적으로 침해받지 않도록 항상 노력하여야 하며, 회원의 권리가 침해될 때 이를 적극적으로 수호하여야 한다."},{"k":"hang","x":"④ 본회와 본회의 각 기구는 본회와 각 기구의 자산 및 자치공간을 보호·관리하여야 한다."}],"num":6,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a7","label":"제7조","title":"구성","paras":[{"k":"line","x":"본회는 민주적이고 효율적인 운영을 통한 학생자치의 실현을 위하여 다음 각호의 의결기구, 집행기구, 산하기구, 독립기구를 둔다."},{"k":"ho","x":"1. 의결기구: 학생총회, 학생대표자회, 학부운영위원회, 비상대책위원회"},{"k":"ho","x":"2. 집행기구: 학부 학생회장단, 집행위원회"},{"k":"ho","x":"3. 산하기구: 반 학생회, 자치단체, 특별위원회"},{"k":"ho","x":"4. 독립기구: 선거관리위원회, 투표관리위원회, 학생자치장학금위원회, 학생홍보대사, 소수자인권위원회"}],"num":7,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a8","label":"제8조","title":"학교운영 참여","paras":[{"k":"hang","x":"① 본회의 활동과 관련하여 학교 당국과의 협의 또는 조정이 필요한 경우 본회의 각 기구는 학교운영에 적극적으로 참여하며 필요 시 학교 당국에 자료제출을 요청할 수 있다."},{"k":"hang","x":"② 본회는 다음 각호의 경우 학교의 운영에 적극 참여하여 의견을 개진하고 관련 진행 상황 및 결정 사항을 회원에게 공고하여야 한다."},{"k":"ho","x":"1. 본회의 활동과 관계된 회원의 징계 사항에 관해 회원을 변호할 필요가 있는 경우"},{"k":"ho","x":"2. 본회의 회원의 자치활동과 권익 보호가 필요한 경우"},{"k":"ho","x":"3. 자유전공학부 발전 방향 설정, 학제개편, 학칙개정 등의 임박하거나 이미 결정된 학교의 정책 및 결정사항이 본회 회원의 이익에 중대한 변화를 야기할 경우"},{"k":"ho","x":"4. 그 밖에 본회의 목적과 관련된 중요 사항"}],"num":8,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a9","label":"제9조","title":"대표자의 책임","paras":[{"k":"line","x":"학생회장단, 학부운영위원, 학생대표자회 대의원은 본회의 대표자로서 본회의 민주적이고 효율적인 운영과 각 기구의 협력을 통해 그 운영 목적을 달성할 수 있도록 주어진 역할을 책임 있게 수행하여야 한다."}],"num":9,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a10","label":"제10조","title":"겸직 금지","paras":[{"k":"hang","x":"① 본회의 회원은 다음 각호의 직을 동시에 2개 이상 가질 수 없다."},{"k":"ho","x":"1. 학부 학생회장과 부학생회장"},{"k":"ho","x":"2. 반 학생회장과 부학생회장"},{"k":"ho","x":"3. 고학번 대표 및 신입생 대표"},{"k":"ho","x":"4. 각 자치단체장"},{"k":"ho","x":"5. 그 밖에 학부운영위원 자격이 부여되는 직책"},{"k":"hang","x":"② 집행위원은 반 학생회장의 직을 겸직하기 위해서는 학생대표자회의 출석 과반수에 해당하는 결의로 인준을 받아야 한다."},{"k":"hang","x":"③ 제１항 각호의 직을 동시에 2개 이상 갖게 되었을 시 즉시 마지막에 갖게 된 직을 제외한 나머지 직에서는 해임된 것으로 본다. 단, 제1항 제1호의 직은 선후관계를 불문하고 그 직을 유지하는 것으로 본다."}],"num":10,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a11","label":"제11조","title":"사무 처리","paras":[{"k":"hang","x":"① 본회 각 기구의 사무 처리는 간소화·표준화·정보화를 통해 효율적으로 이루어져야 한다."},{"k":"hang","x":"② 정확과 신속을 기하고 책임의 소재를 명백히 밝히기 위하여 본회의 사무 처리와 대표자의 행위는 문서로써 함을 원칙으로 한다."},{"k":"hang","x":"③ 본회에서 장기간에 걸쳐 반복적으로 사용하는 문서로서 정형화할 수 있는 문서는 특별한 사유가 없으면 서식으로 정하여 사용한다."},{"k":"hang","x":"④ 회칙에서 공고하도록 한 사항은 회원들이 해당 공고를 쉽게 접할 수 있도록 구법학관 자유전공학부 학생회 게시판, 신법학관 자유전공학부 행정실 게시판 등 오프라인 게시판과, 자유전공학부 홈페이지 학생회 게시판 등 각종 온라인 게시판에 게시하여야 하며, 가시성이 확보되도록 공고의 모양을 정하여야 한다."},{"k":"hang","x":"⑤ 그 밖에 사무 처리에 관한 세부적인 사항은 학부운영위원회의 출석 과반수에 해당하는 결의로 ｢고려대학교 총학생회 사무처리세칙｣을 준용한다."}],"num":11,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a12","label":"제12조","title":"기록물 관리","paras":[{"k":"hang","x":"① 본회의 모든 활동은 기록되고, 기록물이 각 활동의 근거가 되는 것을 원칙으로 한다."},{"k":"hang","x":"② 본회는 지속적이고 체계적인 기록물 관리를 위해 적극 노력해야 하며, 기록물 관리기관이 효율적으로 기록물을 관리할 수 있도록 지원해야 한다."},{"k":"hang","x":"③ 기록물의 생산·수집 이후에는 임의로 수정할 수 없으며 훼손하거나 폐기할 수 없다. 단, 각호에 해당하는 경우 각호에서 정한 목적의 제한된 범위 내에서 게시물을 수정할 수 있다."},{"k":"ho","x":"1. 속기록의 내용이 실제 발언과 부합하지 않은 것을 7일 이내에 발견했을 시"},{"k":"ho","x":"2. 학생회 페이지, 그룹, 자유전공학부 홈페이지 게시판 등에 올린 게시물의 탈·오자 수정이 필요할 시"},{"k":"ho","x":"3. 학생회 페이지, 그룹, 자유전공학부 홈페이지 게시판 등에 올린 게시물의 내용에 중대한 하자를 발견하여 하자의 치유를 위한 수정 및 비공개 조치가 필요할 시"},{"k":"ho","x":"4. 같은 시각에 중복게시물을 올려 비공개 조치가 필요할 시"},{"k":"hang","x":"④ 본회가 생산·수집하는 모든 기록물은 회원들에게 공개되어야 하고 본회의 행정 사무와 의사 결정, 학술 연구 등의 활동을 위해 언제든지 참고할 수 있도록 투명하게 관리되어야 한다."},{"k":"hang","x":"⑤ 본회는 회원의 개인정보를 보호해야 할 의무가 있다. 본회가 수집한 개인정보는 당사자의 동의를 얻었거나 명확한 근거를 가진 정당한 목적이 있을 때만 열람·활용할 수 있다."},{"k":"hang","x":"⑥ 본회의 회원 또는 학술적 목적과 공익을 위해 본회의 기록물을 활용하려는 자는 본회의 모든 기록물에 대한 접근권이 있으며 정보공개청구로 기록물을 열람·활용할 수 있다."},{"k":"hang","x":"⑦ 본회의 각 기구는 본회의 회원 또는 학술적 목적과 공익을 위해 본회의 기록물을 활용하려는 자의 정보공개청구를 거부할 수 없다. 단, 다음 각호에 해당할 때는 학부운영위원회의 출석 과반수에 해당하는 결의로 일부만 공개하도록 할 수 있다."},{"k":"ho","x":"1. 본회의 회원이 아닌 자가 정보공개를 청구한 때"},{"k":"ho","x":"2. 정보의 공개로 인해 특정 회원의 개인정보 유출이 우려될 때"},{"k":"ho","x":"3. 정보의 공개가 본회 회원의 이익의 심각한 감소를 초래할 때"},{"k":"ho","x":"4. 기타 공익적 목적이 있을 때"},{"k":"hang","x":"⑧ 그 밖에 기록물 관리에 관한 세부적인 사항은 학부운영위원회의 출석 과반수에 해당하는 결의로 ｢고려대학교 총학생회 기록물관리세칙｣을 준용한다."}],"num":12,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a13","label":"제13조","title":"준용","paras":[{"k":"hang","x":"① 본회는 본회의 상위기구의 회칙, 세칙 및 규칙을 준용할 수 있다."},{"k":"hang","x":"② 제1항에 해당하는 결정은 준용에 관해 특별한 요건이 없는 경우, 학생총회의 출석 과반수, 학생대표자회의 출석 과반수 또는 학부운영위원회의 출석 과반수에 해당하는 결의로 한다."}],"num":13,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a14","label":"제14조","title":"세칙","paras":[{"k":"line","x":"본회는 회칙에 의거해 세칙을 제정 및 개정한다."}],"num":14,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제2장 의결기구"},{"t":"h","lv":3,"text":"제１절 통칙"},{"t":"art","id":"a15","label":"제15조","title":"기본이념","paras":[{"k":"line","x":"본회의 의결기구는 본회를 대표하는 의사를 결정하는 기구로서 민주적이고 공정하며 효율적인 절차에 따라 운영되어야 한다."}],"num":15,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a16","label":"제16조","title":"의결기구의 위계","paras":[{"k":"hang","x":"① 본회의 의결기구는 학생총회, 학생대표자회, 학부운영위원회 순으로 위계를 지닌다."},{"k":"hang","x":"② 다른 위계에 속한 의결기구 간의 의사결정 내용이 상이할 시 하위 의결기구의 의사결정 내용은 상위 의결기구의 의사결정 내용과 합치되는 범위 내에서 효력을 지닌다."},{"k":"hang","x":"③ 하위 의결기구에서 의결할 수 있도록 한 사항은 해당 의결기구보다 상위 의결기구에서도 의결할 수 있다."}],"num":16,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a17","label":"제17조","title":"회기","paras":[{"k":"line","x":"본회 의결기구의 회기는 다음 각호의 기간으로 나눈다."},{"k":"ho","x":"1. 제1회기: 2학기 종강일 다음 날부터 1학기 개강일 전날까지"},{"k":"ho","x":"2. 제2회기: 1학기 개강일부터 1학기 종강일까지"},{"k":"ho","x":"3. 제3회기: 1학기 종강일 다음 날부터 2학기 개강일 전날까지"},{"k":"ho","x":"4. 제4회기: 2학기 개강일부터 2학기 종강일까지"}],"num":17,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a18","label":"제18조","title":"의장","paras":[{"k":"hang","x":"① 본회 의결기구의 의장은 학부 학생회장으로 함을 원칙으로 한다. 단, 학부 학생회장 사고 시 학부 부학생회장이 그 직을 대신하며, 학부 학생회장과 학부 부학생회장이 모두 사고이거나, 학부 학생회장단 모두 또는 그중 한 명에 대한 탄핵 안건, 탄핵안 학생총투표 발의 안건이 상정된 경우 또는 기타 학부 학생회장단의 신상과 밀접한 관련이 있는 경우 학생회장단을 제외한 학부운영위원 중 한 명이 그 직을 대신한다."},{"k":"hang","x":"② 의장은 본회 의결기구를 대표하고 의사를 정리하며 질서를 유지하고 사무를 감독한다."},{"k":"hang","x":"③ 의장은 본회 절차에 따라 공정하고 효율적으로 회의를 진행하여야 한다."}],"num":18,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a19","label":"제19조","title":"사무·재정","paras":[{"k":"hang","x":"① 의결기구의 사무 처리는 집행위원회가 담당하며 학부운영위원회는 집행기구의 원활한 사무 처리를 감시·감독할 의무를 지닌다."},{"k":"hang","x":"② 본회는 의결기구의 원활한 운영을 위한 재원을 마련해야 한다."},{"k":"hang","x":"③ 집행위원회는 속기의 방법으로 회의록을 작성하고 다음 사항을 기재해야 한다."},{"k":"ho","x":"1. 회의 장소"},{"k":"ho","x":"2. 개회, 회의 중지와 산회의 일시"},{"k":"ho","x":"3. 개회 당시와 안건 의결 당시의 출석 대의원 명단"},{"k":"ho","x":"4. 부의 안건의 제목 및 내용"},{"k":"ho","x":"5. 발언자와 의사 표명의 내용"},{"k":"ho","x":"6. 표결 결과 (기명투표의 경우 각 대의원의 표결 사항을 기재)"},{"k":"ho","x":"7. 의장 또는 각 의결기구가 필요하다고 인정하는 사항"},{"k":"hang","x":"④ 의장은 개의일로부터 3일 이내에 제3항의 회의록을 공개하고 회의결과를 공고함을 원칙으로 한다. 단, 필요한 경우 그 기한을 7일까지 연장할 수 있다."}],"num":19,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a20","label":"제20조","title":"긴급한 사항","paras":[{"k":"hang","x":"① “긴급한 사항”이란 회의 소집 과정을 생략해서라도 긴급하게 의사를 결정해야 할 사항을 의미한다."},{"k":"hang","x":"② 긴급한 사항에 대한 해석은 각호의 목적 사항으로 제한한다."},{"k":"ho","x":"1. 본회의 활동과 관계된 회원의 징계 사항에 관해 변호가 필요할 경우"},{"k":"ho","x":"2. 본회 회원의 이익에 중대한 변화를 야기하는 자유전공학부 발전 방향 설정, 학제개편, 학칙개정 등의 학교 결정이 임박해 있거나 이미 결정된 경우"},{"k":"ho","x":"3. 그 밖에 본회의 목적과 관련된 중요 사항"},{"k":"hang","x":"③ 긴급한 사항이 있을 시 본회 의결기구 의장의 소집요구 없이도 학부운영위원회의 출석 과반수에 해당하는 결의로 임시학생총회 또는 임시학생대표자회를 소집할 수 있다."}],"num":20,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a21","label":"제21조","title":"안건의 발의","paras":[{"k":"hang","x":"① 안건 발의는 각 의결기구에서 정한 발의 요건에 따른다."},{"k":"hang","x":"② 안건 발의는 소집요구와 함께 이루어져야 한다. 단, 소집공고부터 산회 전까지 발의된 추가 안건에 대해서는 재적 구성원 과반수의 출석과 출석 구성원 과반수에 해당하는 결의로 한다."}],"num":21,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a22","label":"제22조","title":"안건의 의결","paras":[{"k":"hang","x":"① 각 의결기구의 재적 구성원 과반수의 출석과 출석 구성원 과반수에 해당하는 결의로 안건을 의결한다. 가부동수 및 찬성이 과반에 미치지 못할 경우 부결된 것으로 본다."},{"k":"hang","x":"② 안건의 의결 시 의결요건을 정하는 기준이 되는 출석 구성원 수는 각 안건의 의결 당시 집계된 구성원 명단을 기준으로 계산한다."},{"k":"hang","x":"③ 의결기구의 의결권은 구성원이 평등하게 가지며 직접 출석하여 행사하여야 한다."}],"num":22,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a23","label":"제23조","title":"안건의 표결","paras":[{"k":"hang","x":"① 표결은 기명으로 함을 원칙으로 한다."},{"k":"hang","x":"② 중요한 안건으로써 의장 또는 회원이 제의하고 의결기구 재적 구성원 3분의 2 이상에 해당하는 결의가 있으면 무기명으로 표결할 수 있다."},{"k":"hang","x":"③ 다음 각호의 사항에 관한 의결은 반드시 기명투표로 표결하여야 한다."},{"k":"ho","x":"1. 제40조 제１항의 회칙 개정에 관한 사항"},{"k":"ho","x":"2. 제40조 제２항의 세칙 제정·개정·폐지에 관한 사항"},{"k":"hang","x":"④ 다음 각호의 사항에 관한 의결은 반드시 무기명투표로 표결하여야 한다."},{"k":"ho","x":"1. 제35조 학부 학생회장단 탄핵에 관한 사항"},{"k":"ho","x":"2. 제36조 제2항 집행위원 해임에 관한 사항"},{"k":"ho","x":"3. 제39조 제1항 및 제２항의 학부 학생회비 지급에 관한 사항"},{"k":"hang","x":"⑤ 의장은 안건에 대한 이의의 유무를 물어서 이의가 없다고 인정한 때에는 가결되었음을 선포할 수 있다. 그러나 이의가 있는 안건일 경우 또는 무기명표결을 요하는 안건의 경우 반드시 표결하여야 한다."},{"k":"hang","x":"⑥ 의장 또는 회원의 제의와 출석 과반수의 찬성으로 전자투표에 의한 기록표결을 시행할 수 있다."}],"num":23,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a24","label":"제24조","title":"방청·발언권","paras":[{"k":"hang","x":"① 본회의 회원은 각 의결기구를 방청할 수 있다."},{"k":"hang","x":"② 본회의 회원은 각 의결기구에서 발언할 수 있는 권리를 가진다."},{"k":"hang","x":"③ 의장은 질서 유지 및 효율적인 의사 진행을 위해 방청인 수를 제한하거나 회원의 발언권을 제한할 수 있으며, 회의장 안의 질서를 현저히 방해하는 방청인의 경우 퇴장을 명할 수 있다."},{"k":"hang","x":"④ 의결기구의 구성원석과 방청인석은 구분이 되도록 배치한다."}],"num":24,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a25","label":"제25조","title":"회의진행세칙","paras":[{"k":"line","x":"그 밖에 의결기구의 회의 진행에 관한 사항은 각 의결기구의 출석 과반수에 해당하는 결의로 ｢고려대학교 총학생회 회의진행세칙｣을 준용한다."}],"num":25,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제２절 학생총회"},{"t":"art","id":"a26","label":"제26조","title":"지위 및 구성","paras":[{"k":"line","x":"학생총회는 본회의 최고의결기구로 본회의 회원 전원으로 구성한다."}],"num":26,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a27","label":"제27조","title":"소집요건","paras":[{"k":"hang","x":"① 학생총회 임시회는 다음 각호 중 하나에 의해 의장이 소집한다."},{"k":"ho","x":"1. 학부운영위원회의 소집요구"},{"k":"ho","x":"2. 학생대표자회의 소집요구"},{"k":"ho","x":"3. 회원 50명 이상의 연서에 따른 소집요구"},{"k":"ho","x":"4. 제90조에 따라 발의된 학부 학생회장단 사퇴 허가 요청"},{"k":"ho","x":"5. 제91조에 따른 학부 학생회장단 탄핵 발의"},{"k":"ho","x":"6. 제175조에 따른 회칙 개정안 발의"},{"k":"hang","x":"② 연서에 따른 소집요구는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식에 의하여야 하며, ｢고려대학교 총학생회 사무처리세칙｣에서 정한 사항이 포함되어야 한다."},{"k":"hang","x":"③ 연서에 따른 소집요구가 있으면 학부운영위원회는 지체 없이 학생총회 개의일을 결정한다. 이때 개의일은 소집요구 서식에 기재된 개의 희망일로 함을 원칙으로 하되 변경할 때는 학부운영위원의 출석 3분의 2 이상에 해당하는 결의로 한다. 단, 이 경우에도 개의 희망일과 2주 이상 차이가 나서는 안 된다."}],"num":27,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a28","label":"제28조","title":"소집 공고","paras":[{"k":"hang","x":"① 학생총회 의장은 학생총회의 소집을 개의일 7일 전에 공고하여야 한다."},{"k":"hang","x":"② 공고문에는 다음 각호의 사항을 명시하여야 한다."},{"k":"ho","x":"1. 회의 시작 일시"},{"k":"ho","x":"2. 회의 장소"},{"k":"ho","x":"3. 안건과 안건에 대한 설명"}],"num":28,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a29","label":"제29조","title":"자료의 사전 배포","paras":[{"k":"line","x":"학생총회 의장은 학생총회 회의 개의 5일 전까지 제출된 안건과 그에 관한 설명, 집행위원회 등의 보고·인준 사항, 각 기구의 학생회비 예산안·결산 등이 포함된 자료집을 회원들을 대상으로 배포하여야 한다. 배포는 책자 형태로 제작하여 비치하는 방법과 전산화된 형태의 문서로 제작하여 온라인에 게시하는 방법으로 한다."}],"num":29,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a30","label":"제30조","title":"개의·의결요건","paras":[{"k":"hang","x":"① 학생총회는 회원 7분의 1 이상의 출석으로 개의하고, 출석 과반수에 해당하는 결의로 의결한다."},{"k":"hang","x":"② 다음 각호의 사항은 재적 회원 7분의 1 이상의 출석 및 출석 회원 3분의 2 이상에 해당하는 결의로 의결한다."},{"k":"ho","x":"1. 제35조의 학부 학생회장단 탄핵안에 관한 사항"},{"k":"ho","x":"2. 제39조 제３항의 학부 학생회비 인상·인하에 관한 사항"},{"k":"ho","x":"3. 제40조 제１항의 회칙 개정에 관한 사항"},{"k":"hang","x":"③ 본회는 학생총회의 개의 7일 전까지 7일 이상의 인권침해사건 신고 기간을 두고, 본회 회원을 대상으로 한 인권침해 사건이 있었는지 조사하여야 한다."}],"num":30,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a31","label":"제31조","title":"안건","paras":[{"k":"hang","x":"① 학생총회의 안건은 다음 각호의 방법으로 상정할 수 있다."},{"k":"ho","x":"1. 학부운영위원회의 출석 과반수에 해당하는 결의"},{"k":"ho","x":"2. 학생대표자회의 출석 과반수에 해당하는 결의"},{"k":"ho","x":"3. 회원 50명 이상의 연서에 따른 임시회의 소집요구와 함께 발의"},{"k":"ho","x":"4. 제90조에 따라 발의된 학부 학생회장단 사퇴 허가 요청"},{"k":"ho","x":"5. 제91조에 따른 학부 학생회장단 탄핵 발의"},{"k":"ho","x":"6. 제175조에 따른 회칙 개정안 발의"},{"k":"hang","x":"② 학생총회는 다음 각호의 안건을 심의·의결한다."},{"k":"ho","x":"1. 학부운영위원회가 소집요구와 함께 상정한 안건"},{"k":"ho","x":"2. 회원 50명 이상의 연서에 따른 소집요구와 함께 발의된 안건"},{"k":"ho","x":"3. 제90조에 따라 발의된 학부 학생회장단 사퇴 허가 안건"},{"k":"ho","x":"4. 제91조에 따른 학부 학생회장단 탄핵 안건"},{"k":"ho","x":"5. 제36조 제2항에 따른 집행위원 해임 안건"},{"k":"ho","x":"6. 제175조에 따라 발의된 회칙 개정안건"},{"k":"ho","x":"7. 본회의 활동에 필요한 각종 세칙 제정·개정안건"},{"k":"ho","x":"8. 회비의 인상·인하에 관한 안건"},{"k":"ho","x":"9. 본회의 사업계획과 정책의 기본방향에 대한 논의 안건"},{"k":"ho","x":"10. 본회의 예산·결산의 심의 및 승인에 관한 안건"},{"k":"ho","x":"11. 본회의 회계 및 사업 전반에 대한 감사에 관한 안건"},{"k":"ho","x":"12. 학생활동 및 학생신분에 관한 학칙 개정 요구안에 관한 안건"},{"k":"ho","x":"13. 제36조 제1항에 따른 집행위원장 및 집행위원 인준에 관한 안건"},{"k":"ho","x":"14. 회원 전체 명의로 소송을 진행할 경우 해당 소송에 관한 안건"},{"k":"ho","x":"15. 자유전공학부의 자치공간과 기타물품 회수 및 분배에 관한 안건"},{"k":"ho","x":"16. 학생총투표 실시 및 안건 상정에 관한 안건"},{"k":"ho","x":"17. 의결기구 산하의 특별위원회 설립에 관한 안건"},{"k":"ho","x":"18. 제107조에 따른 자치단체 인준에 관한 안건"},{"k":"ho","x":"19. 제169조 제4항 및 제5항에 의한 징계에 관한 안건"},{"k":"hang","x":"③ 학생총회는 본회를 폐지하는 결의를 할 수 없다."}],"num":31,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a32","label":"제32조","title":"안건 위임","paras":[{"k":"hang","x":"① 학생총회는 회기 중 처리하지 못한 안건은 출석 인원의 3분의 2 이상의 찬성으로 학생대표자회의에 위임할 수 있다. 단, 학생총회가 개의되지 않아 처리하지 못한 안건은 자동으로 학생대표자회에 위임된다."},{"k":"hang","x":"② 제31조 제2항 제4호, 제35조에서 규정하고 있는 학부 학생회장단 탄핵 안건은 하위기구로 위임할 수 없으며, 학생총회에 의하지 않고서는 오직 학생총투표로서만 처리할 수 있다."}],"num":32,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a33","label":"제33조","title":"결정·집행 사항 변경에 관한 사항","paras":[{"k":"line","x":"학생총회는 산하 학부·반 운영위원회, 학부·반 학생회장단과 학부·반 집행위원회의 결정·집행 사항을 변경 또는 취소할 수 있다."}],"num":33,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a34","label":"제34조","title":"학부 학생회장단 사퇴 허가에 관한 사항","paras":[{"k":"line","x":"학생총회는 학부 학생회장 또는 학부 부학생회장이 제90조에 따라 사퇴의 허가를 요청할 때 허가 여부를 심의·의결한다."}],"num":34,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a35","label":"제35조","title":"학부 학생회장단 탄핵에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 학부 학생회장단에 대한 탄핵안이 상정될 경우 학부 학생회장단에 대한 탄핵을 결정할 수 있다."},{"k":"hang","x":"② 학생총회는 학생회장단 탄핵과 관련된 절차가 준수되었는지, 탄핵 이유가 사실에 기반하고 있는지 성실히 심사할 의무를 지닌다."},{"k":"hang","x":"③ 학생총회는 출석 3분의 2 이상에 해당하는 결의로 학부 학생회장단 탄핵 결정 대신 동일 안건을 학생총투표 안건으로 상정할 수 있다."},{"k":"hang","x":"④ 학부 학생회장단 탄핵안 발의에 관한 절차는 제91조를 따른다."}],"num":35,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a36","label":"제36조","title":"집행위원회에 관한 사항","paras":[{"k":"hang","x":"① 집행위원회는 다음 각호의 사항에 관하여 학부운영위원회의 사전 인준을 거친 후 학생총회에 보고하여 인준받아야 한다. 단, 제２호와 제３호의 사항에 관하여 학부운영위원회의 사전 인준이 있으면 해당 안건을 학생총회에서 심의하기 전까지 해당 결정은 효력을 지닌다."},{"k":"ho","x":"1. 사업계획과 정책의 기본방향"},{"k":"ho","x":"2. 집행위원장과 집행위원의 임명"},{"k":"ho","x":"3. 산하 국서의 신설·폐지와 변경"},{"k":"hang","x":"② 학생총회는 집행위원의 해임을 의결할 수 있다."}],"num":36,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a37","label":"제37조","title":"감사에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 본회 집행기구, 산하기구, 독립기구의 사업 전반에 대하여 감사를 시행할 수 있다."},{"k":"hang","x":"② 학생총회는 감사에 필요하다고 인정될 때 해당 기구의 대표자 혹은 사업담당자를 출석시켜 진술을 청취할 수 있다. 또한, 관련 자료의 제출을 요구할 수 있다."},{"k":"hang","x":"③ 학생총회는 특정 집행기구, 산하기구의 감사를 목적으로 하는 감사위원회를 학생총회 산하에 설치할 수 있다. 감사위원회는 학생총회의 결정에 따라 감사 활동을 진행한 후 그 결과를 우선적으로 학부운영위원회에 보고한 후, 학생총회에 최종 보고하여야 한다."}],"num":37,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a38","label":"제38조","title":"징계에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 회원, 집행위원, 학부운영위원회 위원, 학생대표자회 대의원, 독립기구 및 산하기구가 본 회칙·세칙·규칙을 위반할 때 징계할 수 있다."},{"k":"hang","x":"② 회원의 징계에 대한 자세한 사항은 ｢고려대학교 자유전공학부 징계 세칙｣을 따른다."}],"num":38,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a39","label":"제39조","title":"재정에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 학부운영위원회의 심의를 거친 학부·반 학생회비 예산안·결산을 심의하여 승인한다."},{"k":"hang","x":"② 학생총회는 제1항의 심의에서 불승인된 기구에는 제163조에 따라 해당 학기의 학부 학생회비를 지급하지 않거나 지급을 보류하도록 결정할 수 있다. 그 밖에 자세한 사항은 ｢총학생회 재정운용세칙｣을 따른다."},{"k":"hang","x":"③ 학생총회는 학부학생회비의 인상·인하를 결정할 수 있다."}],"num":39,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a40","label":"제40조","title":"회칙·세칙·규칙에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 회칙을 개정할 수 있다."},{"k":"hang","x":"② 학생총회는 세칙을 제정·개정·폐지할 수 있다."},{"k":"hang","x":"③ 학생총회는 규칙·자치규칙이 회칙·세칙에 부합하는지 여부에 대해 심사할 수 있으며, 출석 과반수에 해당하는 결의로 부합하지 않다고 의결할시, 회칙·세칙에 반하는 규칙·자치규칙은 의결 즉시 효력이 부인된다."}],"num":40,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a41","label":"제41조","title":"대외활동에 관한 사항","paras":[{"k":"hang","x":"① 학생총회는 본회 차원의 상설적 연대 단체 가입·탈퇴에 대한 동의권을 가진다."},{"k":"hang","x":"② 회원 전체의 명의로 소송을 진행할 필요가 있는 문제가 발생할 때 학생총회는 학부운영위원회에 소송권을 위임할 수 있다."}],"num":41,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a42","label":"제42조","title":"재소집","paras":[{"k":"line","x":"학생총회의 개의가 불가하거나 논의를 마치지 못하고 산회한 경우 의장의 재량에 따라 10일 이내에 재소집할 수 있다."}],"num":42,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제３절 학생총투표"},{"t":"art","id":"a43","label":"제43조","title":"지위","paras":[{"k":"line","x":"학생총투표를 통한 의결은 학생총회의 의결과 같은 효력이 있다."}],"num":43,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a44","label":"제44조","title":"투표권","paras":[{"k":"line","x":"정회원은 학생총투표의 투표권이 있다."}],"num":44,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a45","label":"제45조","title":"투표관리위원회","paras":[{"k":"hang","x":"① 투표관리위원회는 학부운영위원 및 제63조 제4항에 의해 의결권을 가질 수 있는 자 전원으로 구성한다. 단, 학부 학생회장단은 제60조에 따른 학부 학생회장단 탄핵안에 대한 학생총투표에 대해서는 투표관리위원이 될 수 없다."},{"k":"hang","x":"② 투표관리위원회는 학생총투표와 관련된 모든 업무를 총괄한다."},{"k":"hang","x":"③ 집행위원장 및 집행위원회는 투표관리위원회의 결정에 따라 학생총투표 시행준비를 성실히 보조한다."},{"k":"hang","x":"④ 그 밖에 투표관리위원회에 관한 사항은 투표관리위원회의 출석 과반수에 해당하는 결의로 ｢고려대학교 총학생회 선거시행세칙｣의 선거관리위원회에 관한 규정을 준용할 수 있다."}],"num":45,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a46","label":"제46조","title":"성립·의결요건","paras":[{"k":"hang","x":"① 학생총투표의 개시는 학생총회 또는 학생대표자회의 출석 과반수에 해당하는 결의로만 가능하다."},{"k":"hang","x":"② 학생총투표는 정회원 4분의 1 이상의 투표로 성립하고, 유효투표의 과반수 찬성으로 의결한다."},{"k":"hang","x":"③ 성립 여부를 판단하기 위한 투표율의 계산은 명부상 총 투표자 수를 기준으로 한다."}],"num":46,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a47","label":"제47조","title":"시행","paras":[{"k":"line","x":"학생총투표는 학생총회 혹은 학생대표자회의 시행 결정에 따라 투표관리위원장이 시행한다."}],"num":47,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a48","label":"제48조","title":"시행 공고","paras":[{"k":"hang","x":"① 학생총회 의장은 학생총투표의 시행을 시행 7일 전에 공고하여야 한다."},{"k":"hang","x":"② 공고문에는 다음 각호의 사항을 명시하여야 한다."},{"k":"ho","x":"1. 학생총투표 시행 일시"},{"k":"ho","x":"2. 학생총투표 투표소 설치 장소"},{"k":"ho","x":"3. 안건과 안건에 대한 설명"}],"num":48,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a49","label":"제49조","title":"투표 기간","paras":[{"k":"hang","x":"① 투표 기간은 3일의 범위에서 투표관리위원회가 정한다."},{"k":"hang","x":"② 투표 기간이 종료하였음에도 투표율이 25%를 넘지 않았으면 투표관리위원회의 결정에 따라 투표 기간을 2일의 범위에서 1회 연장할 수 있다."}],"num":49,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a50","label":"제50조","title":"투표 방법","paras":[{"k":"hang","x":"① 투표는 기표방법으로 함을 원칙으로 한다."},{"k":"hang","x":"② 회원들의 쉬운 투표 참여 혹은 부재중인 자의 투표 참여를 위하여 우편, 온라인, 모바일 그 밖에 특수한 투표방법을 병행할 수 있다. 특수한 투표방법에 대한 결정은 투표관리위원회의 출석 3분의 2 이상에 해당하는 결의로 한다."},{"k":"hang","x":"③ 특수한 투표방법의 시행 여부, 대상, 방식, 운영 등에 관하여서는 ｢자유전공학부 선거시행세칙｣의 특수한 투표방법에 대한 규정을 준용한다."}],"num":50,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a51","label":"제51조","title":"결과 공고","paras":[{"k":"line","x":"학생총투표가 종료되어 개표가 완료되면 개표종료 시부터 24시간 이내에 투표관리위원회가 투표율과 결과를 공고한다. 이때 최종 투표율은 총투표용지 수를 기준으로 계산한다."}],"num":51,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a52","label":"제52조","title":"무효처리","paras":[{"k":"hang","x":"① 한 투표소의 명부상 투표자 수와 투표함의 투표용지 수의 차이가 명부상 투표자 수 대비 5%를 넘으면 해당 투표함의 결과는 무효가 되며, 해당 투표함의 투표용지 수만큼 무효표로 처리한다."},{"k":"hang","x":"② 명부상 총 투표자 수와 총투표용지 수의 차이가 명부상 총 투표자 수 대비 5%를 넘으면 해당 학생총투표는 무효가 된다."}],"num":52,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a53","label":"제53조","title":"준용","paras":[{"k":"line","x":"그 밖에 학생총투표 관련 세부 사항은 투표관리위원회의 출석 3분의 2 이상에 해당하는 결의로 ｢고려대학교 총학생회 선거시행세칙｣의 투표·개표 관련 규정을 준용한다."}],"num":53,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제4절 학생대표자회"},{"t":"art","id":"a54","label":"제54조","title":"지위","paras":[{"k":"line","x":"학생대표자회는 학생총회 다음의 위계에 있는 의결기구이다."}],"num":54,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a55","label":"제55조","title":"구성","paras":[{"k":"hang","x":"① 학생대표자회는 각호의 대표자를 대의원으로 한다."},{"k":"ho","x":"1. 학부 학생회장 및 부학생회장"},{"k":"ho","x":"2. 각 반 학생회 반 운영위원 중 학생회장, 부학생회장, 신입생 대표, 고학번 대표 4인"},{"k":"ho","x":"3. 각 자치단체장"},{"k":"hang","x":"② 비상대책위원회 체제의 산하기구의 장은 궐위로 본다."},{"k":"hang","x":"③ 궐위 대의원은 재적 대의원에서 제외한다."},{"k":"hang","x":"④ 제1항 제3호의 대표자가 학생대표자회에 정당한 사유로 출석하지 못할 때는 개의 직후에 인준을 받아 부대표자가 대신 의결권을 가질 수 있다."}],"num":55,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a56","label":"제56조","title":"학생대표자회 대의원의 의무","paras":[{"k":"hang","x":"① 학생대표자회 대의원은 학생대표자회의 품위를 유지하여야 한다."},{"k":"hang","x":"② 학생대표자회 대의원은 회칙을 준수하여야 한다."},{"k":"hang","x":"③ 학생대표자회 대의원은 자신이 소속된 기구의 의사를 충분히 수렴하여 의결 과정 전반에서 소속된 기구를 대표하는 의사를 표명해야 한다."},{"k":"hang","x":"④ 학생대표자회 대의원은 본회를 대표하여 활동하는 자로서 양심에 따라 직무를 행하고 회의에 성실히 참여하여야 한다."}],"num":56,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a57","label":"제57조","title":"정기회","paras":[{"k":"hang","x":"① 학생대표자회 정기회는 매 학기 1회 개의한다."},{"k":"hang","x":"② 정기회는 각각 5월, 11월에 개의하는 것을 원칙으로 한다."},{"k":"hang","x":"③ 학부 학생회장은 대의원과 협의하여 해당 학기 학생대표자회의 정기회 개의일을 확정 및 공고하여야 한다."}],"num":57,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a57-2","label":"제57조의2","title":"개의·의결요건","paras":[{"k":"hang","x":"① 학생대표자회는 재적 대의원 과반수 출석으로 개의하고, 출석 대의원 과반수에 해당하는 결의로 의결한다."},{"k":"hang","x":"② 다음 각호의 사항은 출석 3분의 2 이상에 해당하는 결의로 의결한다."},{"k":"ho","x":"1. 제36조 제2항의 집행위원 해임에 관한 사항"},{"k":"ho","x":"2. 제39조 제３항의 학부 학생회비 인상·인하에 관한 사항"},{"k":"ho","x":"3. 제40조 제１항의 회칙 개정에 관한 사항"},{"k":"ho","x":"4. 제60조의 학부 학생회장단 탄핵안 학생총투표 발의에 관한 사항"}],"num":57,"sub":2,"bu":false,"bold_title":false},{"t":"art","id":"a58","label":"제58조","title":"안건","paras":[{"k":"hang","x":"① 학생대표자회의 안건은 다음 각호의 방법으로 상정할 수 있다."},{"k":"ho","x":"1. 학부운영위원회의 출석 과반수에 해당하는 결의"},{"k":"ho","x":"2. 회원 50명 이상의 연서에 따른 임시회의 소집요구와 함께 발의"},{"k":"ho","x":"3. 제90조에 따라 발의된 학부 학생회장단 사퇴 허가 요청"},{"k":"ho","x":"4. 제91조에 따른 학부 학생회장단 탄핵 발의"},{"k":"ho","x":"5. 제175조에 따른 회칙 개정안 발의"},{"k":"hang","x":"② 학생대표자회는 다음 각호의 안건을 심의·의결한다."},{"k":"ho","x":"1. 제31조 제2항 제4호, 제35조의 학부 학생회장 탄핵안건을 제외한 안건 중 학생총회에서 다룰 수 있는 안건 및 학생총회의 위임을 받은 안건"},{"k":"ho","x":"2. 학부 학생회장단 탄핵안 학생총투표 발의 안건"},{"k":"ho","x":"3. 임시 학생총회 소집 및 안건상정에 관한 안건"},{"k":"ho","x":"4. 학생총투표 실시 및 안건 상정에 관한 안건"}],"num":58,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a59","label":"제59조","title":"안건 위임","paras":[{"k":"line","x":"회기 중 처리하지 못한 안건은 출석 인원의 3분의 2 이상의 찬성으로 학부운영위원회의에 위임할 수 있다. 단, 제58조 제2항 및 제60조의 탄핵안 학생총투표 발의에 관한 안건, 제175조 회칙 개정안건, 세칙 제정·개정안건, 그 밖의 본회의 목적과 관련된 본질적으로 중대한 결정사항은 위임할 수 없다."}],"num":59,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a60","label":"제60조","title":"탄핵안 학생총투표 발의","paras":[{"k":"hang","x":"① 학생대표자회는 학부 학생회장단 탄핵안을 학생총투표에 붙일 수 있다."},{"k":"hang","x":"② 학부 학생회장단 탄핵안 학생총투표 발의에 관한 절차는 제91조를 따른다."}],"num":60,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a61","label":"제61조","title":"준용","paras":[{"k":"hang","x":"① 소집요건에 관한 사항은 제27조를 준용한다. 단, 제27조 제1항 제2호는 적용하지 아니한다."},{"k":"hang","x":"② 소집공고에 관한 사항은 제28조를 준용한다."},{"k":"hang","x":"③ 자료의 사전 배포에 관한 사항은 제29조를 준용한다."},{"k":"hang","x":"④ 산하기구의 결정·집행사항 변경에 관한 사항은 제33조를 준용한다."},{"k":"hang","x":"⑤ 학부 학생회장단 사퇴 허가에 관한 사항 사항은 제34조를 준용한다."},{"k":"hang","x":"⑥ 집행위원회에 관한 사항은 제36조를 준용한다."},{"k":"hang","x":"⑦ 감사에 관한 사항은 제37조를 준용한다."},{"k":"hang","x":"⑧ 재정에 관한 사항은 제39조를 준용한다."},{"k":"hang","x":"⑨ 회칙·세칙·규칙에 관한 사항은 제40조를 준용한다."},{"k":"hang","x":"⑩ 대외활동에 관한 사항은 제41조를 준용한다."},{"k":"hang","x":"⑪ 재소집에 관한 사항은 제42조를 준용한다."}],"num":61,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제5절 학부운영위원회"},{"t":"art","id":"a62","label":"제62조","title":"지위","paras":[{"k":"line","x":"학부운영위원회는 본회의 신속하고 민주적인 결정을 위하여 학생총회가 일정 권한을 위임한 상설적인 의결기구이다."}],"num":62,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a63","label":"제63조","title":"구성","paras":[{"k":"hang","x":"① 다음 각호 중 하나에 해당되는 자는 학부운영위원이 된다."},{"k":"ho","x":"1. 학부 학생회장과 부학생회장"},{"k":"ho","x":"2. 반 학생회장"},{"k":"hang","x":"② 비상대책위원회 체제인 산하기구의 장은 궐위로 본다."},{"k":"hang","x":"③ 궐위 대의원은 재적 대의원에서 제외한다."},{"k":"hang","x":"④ 제1항 제2호의 학부운영위원이 학부운영위원회에 정당한 사유로 출석하지 못할 때는 개의 직후에 인준을 받아 부회장이 대신 의결권을 가질 수 있다."}],"num":63,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a64","label":"제64조","title":"학부운영위원의 의무","paras":[{"k":"line","x":"학부운영위원의 의무에 관해서는 제56조를 준용한다."}],"num":64,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a65","label":"제65조","title":"정기회의","paras":[{"k":"hang","x":"① 학부운영위원회 정기회의는 매주 1회 개의함을 원칙으로 한다. 단, 학부운영위원회의 출석 과반수에 해당하는 결의로 정기회의의 일정을 조정할 수 있다."},{"k":"hang","x":"② 의장은 학부운영위원회 정기회의의 개의 요일과 시각을 학부운영위원들과 협의하여 결정한 후 이를 공고하여야 한다."},{"k":"hang","x":"③ 의장은 매월 말 다음 달의 학부운영위원회 정기회의 일정을 학부운영위원들과 협의하여 결정하여야 한다."}],"num":65,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a66","label":"제66조","title":"임시회의","paras":[{"k":"hang","x":"① 학부운영위원회 임시회의는 다음 각호 중 하나에 의해 의장이 소집한다."},{"k":"ho","x":"1. 의장의 소집요구"},{"k":"ho","x":"2. 학부운영위원회 재적 위원 3분의 1 이상의 연서에 따른 소집요구"},{"k":"ho","x":"3. 정회원 20명 이상의 연서에 따른 소집요구"},{"k":"hang","x":"② 연서에 따른 소집요구는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식을 준용하며 서식에는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 사항이 포함되어야 한다."},{"k":"hang","x":"③ 연서에 따른 소집요구가 있으면 학부운영위원회 의장은 지체 없이 학부운영위원회 개의일을 결정한다. 이때 개의일은 소집요구 서식에 기재된 개의 희망일로 함을 원칙으로 하되 변경할 때는 학부운영위원의 출석 3분의 2 이상에 해당하는 결의로 한다. 단, 이 경우에도 개의 희망일과 3일 이상 차이가 나서는 안 된다."}],"num":66,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a67","label":"제67조","title":"소집 공고","paras":[{"k":"hang","x":"① 의장은 학부운영위원회의 소집을 개의일 2일 전에 공고하여야 한다."},{"k":"hang","x":"② 공고문에는 다음 각호의 사항을 명시하여야 한다."},{"k":"ho","x":"1. 회의 시작 일시"},{"k":"ho","x":"2. 회의 장소"},{"k":"ho","x":"3. 안건과 안건에 대한 설명"}],"num":67,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a68","label":"제68조","title":"안건지의 사전 배포","paras":[{"k":"line","x":"학부운영위원회 의장은 학부운영위원회 정기회의 개의 1일 전까지 제출된 안건과 그에 관한 설명, 집행위원회 등의 보고·인준 사항 등이 포함된 안건지를 학부운영위원을 대상으로 배포하여야 한다. 배포는 유인물 형태로 제작하여 비치하는 방법과 전산화된 형태의 문서로 제작하여 온라인에 게시하는 방법으로 한다."}],"num":68,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a69","label":"제69조","title":"개의·의결요건","paras":[{"k":"line","x":"학부운영위원회는 재적 위원 과반수 출석으로 개의하고, 출석 위원 과반수 찬성으로 의결한다."}],"num":69,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a70","label":"제70조","title":"안건","paras":[{"k":"hang","x":"① 학부운영위원회의 안건은 다음 각호의 방법으로 상정할 수 있다."},{"k":"ho","x":"1. 학부운영위원이 발의한 안건"},{"k":"ho","x":"2. 회원 20명 이상의 연서에 따른 소집요구와 함께 발의한 안건"},{"k":"hang","x":"② 학부운영위원회는 다음 각호의 안건을 심의·의결한다."},{"k":"ho","x":"1. 제60조 탄핵안 학생총투표 발의에 관한 안건, 제175조 회칙 개정안건, 세칙 제정·개정안건 등 본회의 목적과 관련된 본질적으로 중대한 결정사항을 제외한 안건 중 학생대표자회에서 위임을 받은 안건"},{"k":"ho","x":"2. 임시학생총회 소집 및 안건 상정에 관한 건"},{"k":"ho","x":"3. 임시학생대표자회 소집 및 안건 상정에 관한 건"},{"k":"ho","x":"4. 학생회 제반 사업에 대한 논의 안건"},{"k":"ho","x":"5. 예산 및 결산에 대한 사전 심의·검토 안건"},{"k":"ho","x":"6. 각 반 학생회 사업 보고 및 공유에 관한 안건"},{"k":"ho","x":"7. 반 학생회장단 선거관리위원회 구성에 관한 안건"},{"k":"ho","x":"8. 특별위원회 설립에 관한 안건"},{"k":"ho","x":"9. 공간배정위원회 소집 및 안건 상정에 관한 건"},{"k":"ho","x":"10. 산하기구 감사에 관한 건"},{"k":"ho","x":"11. 학생대표자회 대표자 명단 확정 및 대표자 지위 심의에 관한 건"},{"k":"ho","x":"12. 기타 학생총회 및 학생대표자회의 의결을 요하지 않는 결정사항에 대한 안건"}],"num":70,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a71","label":"제71조","title":"","paras":[{"k":"line","x":"<삭제>"}],"num":71,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a72","label":"제72조","title":"의결기구에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 학생총회의 소집을 요구할 수 있으며 학생총회에 안건을 발의할 수 있다."},{"k":"hang","x":"② 학부운영위원회는 학생대표자회의 소집을 요구할 수 있으며 학생대표자회에 안건을 발의할 수 있다."},{"k":"hang","x":"③ 학부운영위원회는 학생총회 및 학생대표자회의 개의에 관한 세부 문제를 논의하고 결정한다."},{"k":"hang","x":"④ 학부운영위원회는 학생총회에 대하여 연서에 따른 소집요구가 있으면 학생총회의 개의일을 결정한다."},{"k":"hang","x":"⑤ 학부운영위원회는 학생대표자회 개의 전 산하기구의 대표자가 민주적 선거에 의해 당선되었는지, 실질적으로 기구를 대표하고 있는지 등 대표자 지위에 대한 심사를 진행하여야 하며, 이를 기준으로 대의원 명단을 확정 지어야 한다."}],"num":72,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a73","label":"제73조","title":"집행기구에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 제95조 제2항, 제96조 제2항에 따라 집행위원장과 집행위원회 각 국서의 국장과 국원을 사전 인준한다."},{"k":"hang","x":"② 학부운영위원회는 학생총회 및 학생대표자회 보고 사항을 사전 심의한다."},{"k":"hang","x":"③ 학부운영위원회는 학부 학생회장단과 집행위원회의 사업 계획과 진행 상황, 결과에 대한 보고를 받고 이를 심의하고 조정한다. 단, 학부 학생회장단과 집행위원회의 효율적인 집행을 보장하기 위하여 학부 학생회장단이 사전 집행이 불가피하다고 판단하여 집행한 사업에 대하여는 사후에 보고하고 심의 절차를 이행할 수 있다. 집행위원회는 불승인된 사업에 대해서는 의결 즉시 원상회복을 위해 노력해야 한다."},{"k":"hang","x":"④ 학부운영위원회는 학부 학생회장단과 집행위원회의 결정과 집행사항을 변경 또는 취소할 수 있다."},{"k":"hang","x":"⑤ 학부운영위원회는 학부 학생회장단에 대한 탄핵안이 발의되면 탄핵안이 제91조 제1항 내지 제3항에서 규정하고 있는 발의 요건을 충족하고 있는지 지체 없이 심의해야 하며 제91조 제4항에 따라 학생총회 또는 학생대표자회를 소집해야 한다."}],"num":73,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a74","label":"제74조","title":"감사에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 본회 집행기구, 산하기구의 사업 전반에 대하여 감사를 시행할 수 있다."},{"k":"hang","x":"② 학부운영위원회는 감사에 필요하다고 인정될 때 해당 기구의 대표자 혹은 사업담당자를 출석시켜 진술을 청취할 수 있다. 또한 관련 자료의 제출을 요구할 수 있다."}],"num":74,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a75","label":"제75조","title":"선거에 관한 사항","paras":[{"k":"line","x":"학부운영위원회는 반 학생회장단 동시선거 일정을 결정하고 반 학생회 동시 선거관리위원회를 구성할 수 있다. 그 밖에 자세한 사항은 ｢자유전공학부 학부·반 선거시행세칙｣을 따른다."}],"num":75,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a76","label":"제76조","title":"재정에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 제167조에 따라 학생회비를 사용하는 학부·반 집행위원회 등의 예산안과 결산을 사전 심의한 후 학생총회 및 학생대표자회에 상정한다."},{"k":"hang","x":"② 학부운영위원회는 제163조 제8항에 따라 집행기구 자산의 취득, 보관, 사용, 처분 행위를 취소할 수 있다."}],"num":76,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a77","label":"제77조","title":"회칙·세칙·규칙에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 제175조에 따라 회칙 개정안과 제182조에 따라 세칙 제정안·개정안·폐지안을 발의할 수 있다. 학부운영위원회는 회칙 개정안을 발의하면 제177조 제１항에 따라 학부운영위원회에서 회칙 개정안에 대해 사전 심의한다."},{"k":"hang","x":"② 세칙에 관련 규정이 있으면 학부운영위원회는 해당 세칙에 부수되는 규칙을 제정·개정·폐지할 수 있다. 이에 관하여서는 해당 세칙을 따른다."},{"k":"hang","x":"③ 학부운영위원회는 일반규칙을 제정·개정·폐지할 수 있다."}],"num":77,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a78","label":"제78조","title":"대외활동에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 본회의 대외적 활동에 대하여 동의 및 승인권을 갖는다."},{"k":"hang","x":"② 학부운영위원회는 직전 두 분기의 학부 학생회비 5%를 초과하는 재정적 지출을 수반하거나, 본회의 회원에게 중대한 영향을 미치는 학부 학생회장단 또는 집행위원회 차원의 대외활동에 대하여 동의권을 갖는다. 단, 학부 학생회장단과 집행위원회의 효율적인 대외활동을 보장하기 위하여 학부 학생회장단이 사전 집행이 불가피하다고 판단하여 집행한 사업에 대하여는 사후에 보고하고 승인 절차를 이행할 수 있다. 학부 학생회장단과 집행위원회는 부동의된 대외활동에 대해서는 의결 즉시 원상회복을 위해 노력해야 한다."}],"num":78,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제6절 비상대책위원회"},{"t":"art","id":"a79","label":"제79조","title":"비상대책위원회","paras":[{"k":"hang","x":"① 비상대책위원회는 다음 각호에 해당할 때 해당 사항의 공고 시로부터 48시간 후 구성한다. 단, 임기 종료일이 확정되지 않았을 때 잔여 임기의 계산을 위한 임기 종료일은 11월 30일로 한다."},{"k":"ho","x":"1. 학부 학생회장단 선거의 예정된 개표일이 경과하였을 때"},{"k":"ho","x":"2. 학부 학생회장단 두 명 모두가 사퇴하거나 탄핵되고, 해당 학부 학생회장단의 잔여 임기가 180일이 넘지 않을 때"},{"k":"hang","x":"② 제１항에 따라 비상대책위원회가 구성되면 다음 각호에 해당하는 자는 비상대책위원이 된다."},{"k":"ho","x":"1. 각 반 학생회장 및 부학생회장"},{"k":"ho","x":"2. 학생대표자회 대의원 중 호선된 자"}],"num":79,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a80","label":"제80조","title":"권한·업무","paras":[{"k":"hang","x":"① 비상대책위원회는 의결기구에 준하는 권한을 갖는다."},{"k":"hang","x":"② 비상대책위원회는 학부 학생회장단의 궐위기간 동안 학부운영위원회의 상시적 업무를 담당한다."},{"k":"hang","x":"③ 비상대책위원회는 학부 학생회장단의 궐위기간 동안 집행위원회의 상시적 업무를 담당하기 위하여 임시집행위원회를 구성할 수 있다."}],"num":80,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a81","label":"제81조","title":"비상대책위원장","paras":[{"k":"hang","x":"① 비상대책위원장은 비상대책위원회의 출석 과반수에 해당하는 결의로 선출하며, 선출이 무산될 경우 호선에 의한다. 비상대책위원장은 학생총회 또는 학생대표자회의 인준을 받아야 한다."},{"k":"hang","x":"② 비상대책위원장은 학부 학생회장에 준하는 권한을 갖는다."},{"k":"hang","x":"③ 비상대책위원장의 의무에 관해서는 제56조와 제88조를 준용한다."}],"num":81,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a81-2","label":"제81조의2","title":"임시집행위원회","paras":[{"k":"hang","x":"① 임시집행위원회는 집행위원회에 준하는 권한을 가지며, 학부 학생회장단의 궐위 기간 동안 집행위원회의 상시적 업무를 담당한다."},{"k":"hang","x":"② 임시집행위원은 각 반 학생회에서 두 명씩 추천하며, 그 외 임시집행위원은 공고를 내어 공개 모집함을 원칙으로 한다."},{"k":"hang","x":"③ 비상대책위원장은 임시집행위원장을 둘 수 있으며, 임시집행위원장의 임명에 관하여서는 학생대표자회의 인준을 받아야 한다."},{"k":"hang","x":"④ 각 국서의 국장과 국원은 비상대책위원장이 임명한다. 각 국서의 국장과 국원의 임명에 관하여서는 학생대표자회의 인준을 받아야 한다."}],"num":81,"sub":2,"bu":false,"bold_title":false},{"t":"art","id":"a82","label":"제82조","title":"제한","paras":[{"k":"hang","x":"① 비상대책위원장과 임시집행위원회는 학생회장단 및 집행위원회가 가지는 사전 집행·사후 학부운영위원회 승인 방식의 재정지출이 허용되지 않는다."},{"k":"hang","x":"② 비상대책위원장과 임시집행위원회는 학생회장단 및 집행위원회가 가지는 사전 집행·사후 학부운영위원회 승인 방식의 대외활동이 허용되지 않는다."},{"k":"hang","x":"③ 비상대책위원장과 임시집행위원회는 직전 두 분기의 학부 학생회비 30%를 초과하는 재정지출이 허용되지 않는다."}],"num":82,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a83","label":"제83조","title":"흠결의 보충","paras":[{"k":"line","x":"비상대책위원회 관련 회칙의 흠결로 비상대책위원회 및 비상대책위원장의 권한, 의무의 범위를 확정 짓기 어려울 시, 학부운영위원회의 출석 과반수에 해당하는 결의로 해당 회기에 한해 한시적으로 흠결을 보충할 수 있다. 단, 권한의 범위는 학부 학생회장과 집행위원회의 권한 내로 제한되며, 의무의 범위는 학부 학생회장단과 집행위원회의 의무 내로 제한된다."}],"num":83,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제３장 집행기구"},{"t":"h","lv":3,"text":"제１절 학부 학생회장단"},{"t":"art","id":"a84","label":"제84조","title":"지위","paras":[{"k":"hang","x":"① 학부 학생회장은 본회를 대표하며, 학생총회, 학생대표자회, 학부운영위원회의 의장이 된다."},{"k":"hang","x":"② 학부 학생회장은 총학생회 중앙운영위원 및 전체학생대표자회 대의원이 된다."},{"k":"hang","x":"③ 부학생회장은 학부 학생회장을 보좌하고 학부 학생회장이 권한을 위임하거나 사고인 때에 학부 학생회장의 직무를 대행한다."}],"num":84,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a85","label":"제85조","title":"의결기구 관련 권한","paras":[{"k":"line","x":"학부 학생회장은 학생총회, 학생대표자회, 학부운영위원회 등 의결기구를 운영한다."}],"num":85,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a86","label":"제86조","title":"집행기구 관련 권한","paras":[{"k":"hang","x":"① 학부 학생회장은 본회 사무의 집행을 총괄한다."},{"k":"hang","x":"② 학부 학생회장은 집행위원회의 구성권을 가진다."},{"k":"hang","x":"③ 학부 학생회장은 집행위원회 산하 국서의 국장과 국원에 대한 임면권을 가진다."},{"k":"hang","x":"④ 학부 학생회장은 집행위원회와 산하 국서를 지휘·감독한다."},{"k":"hang","x":"⑤ 학부 학생회장은 집행위원회의 결정·집행 사항을 변경 또는 취소할 수 있다."},{"k":"hang","x":"⑥ 학부 학생회장은 필요하다고 인정한 사안의 효율적 업무 집행을 위하여 직속 자문위원회를 설치할 수 있다. 직속 자문위원회와 그 위원에 관하여서는 제３항 내지 제5항을 준용한다."}],"num":86,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a87","label":"제87조","title":"대외활동 관련 권한","paras":[{"k":"hang","x":"① 학부 학생회장은 학생자치활동에 관계되는 학교 행정의 문제에 대해 회원의 의사를 대변하고 학교 당국에 의사를 개진하며, 관련 단체 및 회의에 참여할 수 있다."},{"k":"hang","x":"② 학부 학생회장은 본회와 본회 회원과 관련된 문제에 관하여 본회를 대표하여 대외적으로 입장을 표명하는 등의 대외활동을 할 수 있다. 단, 본회 차원의 연대 단체 가입과 대외적 협의, 본회의 재정적 지출을 수반는 행위나, 본회의 회원에게 중대한 영향을 미치는 학부 학생회장단 차원의 대외활동은 제78조에 따라 학부운영위원회의 동의를 받아야 한다."}],"num":87,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a88","label":"제88조","title":"의무","paras":[{"k":"hang","x":"① 학부 학생회장은 회원들의 의사를 반영하여 민주적 절차에 따라 직무를 수행해야 한다."},{"k":"hang","x":"② 학부 학생회장은 본회의 의결기구에 성실하게 본회의 활동 사항을 보고해야 한다."},{"k":"hang","x":"③ 학부 학생회장은 본회의 지속적·장기적 발전을 위하여 노력해야 한다."},{"k":"hang","x":"④ 학부 학생회장단은 본회와 본회 산하기구의 각종 선거에 대한 부당한 영향력의 행사 등 선거 결과에 직·간접적인 영향을 미치는 행위를 일체 하여서는 아니 된다."},{"k":"hang","x":"⑤ 학부 학생회장단은 후임 학부 학생회장단의 선출과 후임 학부 학생회장단으로의 인수인계가 원활하게 이루어질 수 있도록 노력해야 한다."},{"k":"hang","x":"⑥ 학부 학생회장은 본회의 대표로 학교 기구의 위원이 될 때 의결권 행사 등에 관하여 학부운영위원회와 협의하여야 한다."}],"num":88,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a89","label":"제89조","title":"임기·삼선 금지","paras":[{"k":"hang","x":"① 학부 학생회장단의 임기는 당선 확정 공고가 게시된 때부터 후임 학부 학생회장단 임기 시작 전까지로 한다. 단, 후임 학부 학생회장단 선거가 무산되는 경우 후임 학부 학생회장단 선거 개표 예정일로부터 48시간이 도과하면 임기가 종료되는 것으로 본다."},{"k":"hang","x":"② 학부 학생회장은 후임 학부 학생회장단 선거에서 학부 학생회장 후보로 입후보할 수 있다. 단, 학생회장을 2회 역임한 경우, 차기 선거에서 학부 학생회장 및 부학생회장 후보로 입후보할 수 없다."}],"num":89,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a90","label":"제90조","title":"사퇴","paras":[{"k":"hang","x":"① 학부 학생회장 또는 학부 부학생회장이 사퇴하고자 할 때는 학생총회 또는 학생대표자회의 허가가 있어야 한다. 단, 사망 등으로 인하여 당사자가 허가를 받을 수 없으면 그러하지 아니하다."},{"k":"hang","x":"② 제1항의 사퇴요청의 접수일로부터 20일 이내에 학생총회 또는 학생대표자회의 결정이 없으면 사퇴를 승인한 것으로 본다."},{"k":"hang","x":"③ 학부 학생회장이 사퇴하거나 탄핵되면 학부 부학생회장이 그 직을 승계한다."}],"num":90,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a91","label":"제91조","title":"탄핵","paras":[{"k":"hang","x":"① 회원은 학부 학생회장단이 다음 각호 중 하나에 해당할 시 학부 학생회장단의 탄핵안을 발의할 수 있다. 회장과 부회장 중 한 명만 다음 각호 중 하나에 해당하는 경우, 회장과 부회장 중 한 명을 대상으로 한 탄핵안을 발의할 수 있다. 탄핵안의 경우 반드시 학생총회 또는 학생총투표의 방법 중 하나를 정해 발의해야 한다."},{"k":"ho","x":"1. 회칙의 중대한 위반을 저질렀을 경우"},{"k":"ho","x":"2. 상당한 기간 동안 회장단의 업무를 해태하고 있을 경우"},{"k":"ho","x":"3. 실정법 위반으로 벌금형 이상의 실형을 선고받은 경우"},{"k":"ho","x":"4. 회원으로부터 현저히 신임을 잃었을 경우"},{"k":"hang","x":"② 탄핵안의 상정은 다음 각호의 요건 중 하나를 충족시켜야 한다."},{"k":"ho","x":"1. 학부운영위원회의 재적 3분의 2 이상에 해당하는 연서"},{"k":"ho","x":"2. 학생대표자회의 재적 3분의 2 이상에 해당하는 연서"},{"k":"ho","x":"3. 본회 회원 10분의 1 이상에 해당하는 연서"},{"k":"hang","x":"③ 연서에 따른 발의는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식에 의하여야 한다."},{"k":"hang","x":"④ 학부운영위원회는 탄핵안이 발의되면 즉시 탄핵안이 제1항 내지 제3항의 발의 요건을 충족시켰는지 심의하여야 하며, 중대한 하자가 없으면 탄핵안 제출일로부터 7일 이내에 학생총회 소집 또는 학생총투표에 상정한다. 학생총회 및 학생총투표 방법에 관한 탄핵 안건이 모두 상정된 경우, 학부운영위원회의 출석 과반수에 해당하는 결의로 방법을 정한다. 단, 두 방법 모두 출석 과반수에 해당하는 결의가 성립되지 않으면, 탄핵안을 학생총투표에 상정하는 것으로 한다."}],"num":91,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a92","label":"제92조","title":"인수위원회","paras":[{"k":"hang","x":"① 학부 학생회장단 당선자는 학부 학생회장단 및 집행위원회의 업무 인수를 위해 당선 공고일로부터 48시간 이후부터 자유전공학부 학생회 인수위원회를 설치할 수 있다. 단, 보궐선거로 당선되었을 경우 설치하지 아니한다."},{"k":"hang","x":"② 인수위원회는 다음 각호의 직무를 수행한다."},{"k":"ho","x":"1. 집행위원회의 조직ᆞ 기능 및 예산 현황의 파악"},{"k":"ho","x":"2. 전임 학부 학생회장단과 집행위원회의 주요 사업 분석"},{"k":"ho","x":"3. 기타 학부 학생회장단과 집행위원회 업무의 인수에 필요한 사항"},{"k":"hang","x":"③ 인수위원장은 당선된 선거운동본부의 본부장으로 함을 원칙으로 한다."},{"k":"hang","x":"④ 인수위원회는 설치한 날로부터 7일 후 해산한다."}],"num":92,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제２절 집행위원회"},{"t":"art","id":"a93","label":"제93조","title":"지위","paras":[{"k":"line","x":"집행위원회는 본회의 최고집행기구이다."}],"num":93,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a94","label":"제94조","title":"구성","paras":[{"k":"line","x":"집행위원회는 각 국서의 국장과 국원으로 구성한다. 단, 원활한 운영을 위해 집행원장을 둘 수 있다."}],"num":94,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a95","label":"제95조","title":"집행위원장","paras":[{"k":"hang","x":"① 집행위원장은 학생회장단을 보좌하며, 본회 사무의 집행에 관하여 학부 학생회장단의 지시에 따라 각 국서를 관리·감독한다."},{"k":"hang","x":"② 집행위원장은 학부 학생회장이 임명하고, 학부운영위원회의 사전 인준(임명)으로 업무를 개시한다. 집행위원장의 임명에 관하여서는 학생총회 또는 학생대표자회의 사후 인준을 받아야 한다."}],"num":95,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a96","label":"제96조","title":"국서","paras":[{"k":"hang","x":"① 집행위원회는 원활한 업무 집행을 위하여 산하에 국서를 둘 수 있다."},{"k":"hang","x":"② 각 국서의 국장과 국원은 학부 학생회장이 임명하고, 학부운영위원회의 사전 인준(임명)으로 업무를 개시한다. 각 국서의 국장과 국원의 임명에 관하여서는 학생총회 또는 학생대표자회의 사후 인준을 받아야 한다."}],"num":96,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a97","label":"제97조","title":"업무","paras":[{"k":"hang","x":"① 집행위원회는 본회의 사업 집행 전반을 담당한다."},{"k":"hang","x":"② 집행위원회는 학생총회, 학생대표자회 및 학부운영위원회가 결정한 업무를 집행한다."},{"k":"hang","x":"③ 집행위원회는 학부 학생회장단이 결정한 업무를 집행한다."},{"k":"hang","x":"④ 집행위원회는 다음 각호의 사안에 대한 관리 권한을 갖는다. 관리 권한이라 함은 각 사안의 원활한 운영을 위하여 배타적인 권리행사 및 집행을 할 수 있는 권원을 의미한다."},{"k":"ho","x":"1. ｢권한등기부｣에 등기된 것"},{"k":"ho","x":"2. 학생회 자치 공간 분배 및 회수"},{"k":"ho","x":"3. 사물함 분배, 회수, 철거"},{"k":"hang","x":"⑤ 집행위원회는 학생총회, 학생총투표, 학생대표자회 및 학부운영위원회의 개의·시행을 준비하고, 이에 사용되는 각종 서식을 ｢고려대학교 총학생회 사무처리세칙｣을 준용하여 제작한다."},{"k":"hang","x":"⑥ 집행위원회는 학생총회, 학생대표자회 및 학부운영위원회에 본회의 운영 사항을 보고해야 한다."},{"k":"hang","x":"⑦ 집행위원회는 본회의 예산안·결산을 작성하여 학생총회 또는 학생대표자회와 학부운영위원회에 보고해야 한다."}],"num":97,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a98","label":"제98조","title":"집행회의","paras":[{"k":"hang","x":"① 집행위원장은 집행위원회의 업무에 속하는 사안을 심의하기 위하여 집행회의를 소집할 수 있다. 이 경우 집행회의의 의장은 집행위원장이 된다."},{"k":"hang","x":"② 집행회의의 구성, 업무와 권한, 운영 등에 관하여서는 규칙으로 정한다."},{"k":"hang","x":"③ 집행위원장이 궐위일 경우 집행회의의 의장은 학생회장이 된다."}],"num":98,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a99","label":"제99조","title":"계열회의","paras":[{"k":"line","x":"집행위원회는 원활한 업무 집행을 위하여 특정 국서의 국장과 각 반 학생회, 자치단체 및 독립기구 등의 동종 업무 담당 국장 혹은 이에 준하는 자가 참가하는 계열회의를 개최할 수 있다. 계열회의의 구성, 업무와 권한, 운영 등에 관하여서는 규칙으로 정한다."}],"num":99,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제4장 산하기구"},{"t":"h","lv":3,"text":"제１절 반 학생회"},{"t":"art","id":"a100","label":"제100조","title":"지위 및 구성","paras":[{"k":"line","x":"반 학생회는 고려대학교 자유전공학부 학생회원 중 A반부터 D반까지의 네 반을 기준으로 분류된 각 반의 회원들로 구성되며 반 학생회원들의 단결 및 권리와 이익 보장을 위해 자치활동을 하는 자유전공학부 학생회 산하기구이다."}],"num":100,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a101","label":"제101조","title":"회원","paras":[{"k":"hang","x":"① 자유전공학부 학생회원의 반 학생회별 분류는 다음 각호에 따른다."},{"k":"ho","x":"1. A반 소속 자유전공학부 학생회 회원은 A반 학생회원이 된다."},{"k":"ho","x":"2. B반 소속 자유전공학부 학생회 회원은 B반 학생회원이 된다."},{"k":"ho","x":"3. C반 소속 자유전공학부 학생회 회원은 C반 학생회원이 된다."},{"k":"ho","x":"4. D반 소속 자유전공학부 학생회 회원은 D반 학생회원이 된다."},{"k":"hang","x":"② 2학기 입학, 편입 등으로 반이 확정되지 않은 채로 회원이 된 경우, 해당 회원의 반은 학부운영위원회의 출석 과반수에 해당하는 결의로 결정한다."},{"k":"hang","x":"③ 반 학생회의 회원은 해당 반 학생회 회장단 선거의 선거권과 피선거권을 가진다."},{"k":"hang","x":"④ 반 학생회의 회원은 해당 반 학생회 사업을 향유할 권리를 지닌다."},{"k":"hang","x":"⑤ 반 학생회 회원의 권리 및 의무에 관한 사항은 각 반 학생회칙으로 정한다."}],"num":101,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a102","label":"제102조","title":"반 학생회장단","paras":[{"k":"hang","x":"① 반 학생회장단은 상위 규정과 어긋나지 않는 범위에서 반 학생회칙에 따라 회원의 보통ㆍ평등ㆍ직접ㆍ비밀선거로 선출한다."},{"k":"hang","x":"② 반 학생회장단의 임기는 당선 확정 공고가 게시된 때부터 후임 반 학생회장단의 임기 시작 전까지로 한다. 단, 후임 반 학생회장단 선거가 무산되는 경우 후임 반 학생회장단 선거 개표 예정일로부터 48시간이 도과하면 임기가 종료되는 것으로 본다."},{"k":"hang","x":"③ 반 학생회장단의 권한·의무 사항에 대해서는 각 반 학생회칙으로 정한다."},{"k":"hang","x":"④ 반 학생회장은 해당 반을 대표하며 학생대표자회 대의원 및 학부운영위원회 위원이 된다."},{"k":"hang","x":"⑤ 반 학생회장은 총학생회 전체학생대표자회의의 대의원이 된다."}],"num":102,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a103","label":"제103조","title":"운영","paras":[{"k":"hang","x":"① 반 학생회의 최고 의결기구는 반 학생총회이다."},{"k":"hang","x":"② 반 학생회는 정기적으로 반 학생총회 및 반 운영위원회를 개의해야 한다."},{"k":"hang","x":"③ 다음 각호 중 하나에 해당하는 자는 반 운영위원이 되며, 반 학생회장과 부학생회장을 제외한 반 운영위원의 선출·권한·의무 및 그 밖의 사항은 반 학생회칙으로 정한다."},{"k":"ho","x":"1. 반 학생회장과 부학생회장"},{"k":"ho","x":"2. 신입생 대표"},{"k":"ho","x":"3. 고학번 대표"},{"k":"ho","x":"4. 각 반 학생회칙으로 정한 이에 준하는 자"},{"k":"hang","x":"④ 반 학생회의 최고집행기구는 각 반 학생회의 집행위원회이며 반 학생회 집행위원회는 반 운영위원회에 사업을 성실히 보고하여야 한다."},{"k":"hang","x":"⑤ 반 학생회의 모든 기구의 권한과 업무는 각 반 학생회칙으로 정한다."}],"num":103,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a104","label":"제104조","title":"권리","paras":[{"k":"hang","x":"① 반 학생회는 학부 학생회로부터 재정 지원과 공간 지원을 받을 수 있다."},{"k":"hang","x":"② 반 학생회는 학부 학생회로부터 집행 인원을 지원받을 수 있다."},{"k":"hang","x":"③ 반 학생회는 법학관(신관), CJ법학관, 해송법학도서관 강의실을 대관할 수 있다."},{"k":"hang","x":"④ 반 학생회는 학생회 페이스북 페이지, 카카오톡 공지방, 행정실 게시판을 활용할 수 있다."}],"num":104,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a105","label":"제105조","title":"의무","paras":[{"k":"hang","x":"① 반 학생회는 매 학기 학생총회 또는 학생대표자회에서 예산안·결산에 대한 심의·승인 절차를 거쳐야 한다."},{"k":"hang","x":"② 반 학생회는 다른 반 학생회와 교류하고, 학부 학생회 사업에 협력해야 한다."}],"num":105,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a106","label":"제106조","title":"위계","paras":[{"k":"hang","x":"① 반 학생회의 회칙 및 결정사항이 본회의 회칙·세칙과 충돌할 시, 본회의 회칙·세칙과 합치될 수 있는 내용을 제외한 모든 내용은 무효로 한다. 단, 본회의 회칙·세칙의 개정 및 신설로 인해 기존의 반 학생회 회칙 및 결정사항과 충돌이 생겼을 시, 소급효는 인정하지 않는다."},{"k":"hang","x":"② 반 학생회의 결정이 본회 의결기구의 결정과 충돌할 시, 본회의 결정과 합치될 수 있는 내용을 제외한 모든 내용은 그 즉시 무효로 한다."}],"num":106,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 자치단체"},{"t":"art","id":"a107","label":"제107조","title":"지위","paras":[{"k":"hang","x":"① 자치단체는 특정한 분야에서 특정한 목적을 가지고 활동하는 단체 중 자유전공학부 학생회에 등록절차를 마치고 매년 자유전공학부 학생회의 인준을 받아 활동하는 단체이다."},{"k":"hang","x":"② 본회 자치단체로의 등록은 학생총회 혹은 학생대표자회의에서 각호와 같은 사유에 해당될 때에만 거절될 수 있다. 단 아래의 사유는 각 단체의 특수한 목적 및 사정을 고려하여 논의되어야 한다."},{"k":"ho","x":"1. 단체의 존속 가능성이 불분명한 경우"},{"k":"ho","x":"2. 단체의 활동과 목적이 본회가 추구하는 가치에 명백히 반하는 경우"},{"k":"ho","x":"3. 당해 모집 기간 이후에도 명부상 10명 이하의 회원만이 활동하는 것으로 판단되는 경우"},{"k":"ho","x":"4. 명부상 자유전공학부 회원이 구성원의 1/2 미만일 경우"},{"k":"ho","x":"5. 사회상규에 비추어 본회로의 등록이 용인되기 힘든 수준의 사유를 지닐 경우"}],"num":107,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a108","label":"제108조","title":"회원","paras":[{"k":"hang","x":"① 각 자치단체에 소속된 본회의 회원은 해당 자치단체의 회원이 된다."},{"k":"hang","x":"② 자치단체의 회원은 해당 자치단체장 선거의 선거권과 피선거권을 가진다."},{"k":"hang","x":"③ 자치단체의 회원은 해당 자치단체의 사업을 향유할 권리를 지닌다."},{"k":"hang","x":"④ 본회의 회원에 해당하지 않는 자치단체 회원은 자치단체에 관한 회칙의 적용에 한해서는 본회의 회원으로 본다."}],"num":108,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a109","label":"제109조","title":"자치단체장","paras":[{"k":"hang","x":"① 자치단체장은 상위 규정과 어긋나지 않는 범위에서 자치단체의 자치규칙에 따라 회원의 보통ㆍ평등ㆍ직접ㆍ비밀선거로 선출한다."},{"k":"hang","x":"② 자치단체장은 해당 자치단체를 대표하며 학생대표자회의 대의원이 된다."},{"k":"hang","x":"③ 자치단체 및 자치단체장의 권한·업무 등에 관하여서는 각 자치단체의 자치규칙으로 정한다."}],"num":109,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a110","label":"제110조","title":"권리","paras":[{"k":"hang","x":"① 자치단체는 학부 학생회로부터 집행 인원을 지원받을 수 있다."},{"k":"hang","x":"② 자치단체는 법학관(신관), CJ법학관, 해송법학도서관 강의실을 대관할 수 있다."},{"k":"hang","x":"③ 자치단체는 학생회 페이스북 페이지, 카카오톡 공지방, 행정실 게시판을 활용할 수 있다."}],"num":110,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a111","label":"제111조","title":"의무","paras":[{"k":"hang","x":"① 자치단체는 본회의 목표에 맞게 성실히 활동하며 창조적 대학 문화 창달을 위해 노력해야 한다."},{"k":"hang","x":"② 자치단체는 매년 1학기 학생총회 또는 학생대표자회에서 인준 절차를 거쳐야 한다. 등록 및 인준은 정해진 양식에 의하며, 인준의 요건은 제107조 제2항을 준용한다."},{"k":"hang","x":"③ 인준받지 못한 자치단체는 2학기 학생총회 또는 학생대표자회에서 재인준 절차를 거쳐야 하며, 재인준받지 못할 경우, 재인준에 관한 안건이 결의된 학생총회 또는 학생대표자회의 종료일을 기준으로 30일 이내에 자치공간 및 본회 자산을 반납하여야 한다."},{"k":"hang","x":"④ 자치단체는 다른 자치단체와 교류하고, 학생회 사업에 협력해야 한다."},{"k":"hang","x":"⑤ 자치단체는 본회의 회원들의 관심사에 따른 자발적인 참여를 보장해야 하며, 본회 회원의 결속 및 학생회의 발전에 기여해야 한다."}],"num":111,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a112","label":"제112조","title":"위계","paras":[{"k":"line","x":"자치단체의 결정 및 자치규약과 학부 학생회의 결정 및 회칙과의 위계에 관해서는 제106조를 준용한다."}],"num":112,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제3절 특별위원회"},{"t":"art","id":"a113","label":"제113조","title":"목적","paras":[{"k":"line","x":"감찰, 조사, 프로젝트 등 특수한 목적 달성을 위해 학생대표자회 혹은 학부운영위원회 산하에 한시적으로 특별위원회를 둘 수 있다."}],"num":113,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a114","label":"제114조","title":"구성","paras":[{"k":"hang","x":"① 특별위원회는 학생총회, 학생대표자회 혹은 학부운영위원회에서 임명한 위원장 1인과 위원으로 구성한다."},{"k":"hang","x":"② 특별위원회의 위원장과 위원은 공개모집을 원칙으로 하되 필요한 경우 학부운영위원회의 출석 과반수에 의한 결의로 집행위원만으로 구성할 수 있다."},{"k":"hang","x":"③ 특별위원회는 구체적인 활동 목적을 가지고 구성되어야 하며, 특별위원회 구성에 대한 안건에는 반드시 특별위원회의 구체적인 활동 목적과 활동 범위가 명시되어야 한다. 조사, 감찰의 경우 대상자를 특정할 수 있는 경우에는 안건에 함께 기재해야 한다."}],"num":114,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a115","label":"제115조","title":"인준","paras":[{"k":"line","x":"특별위원회의 위원장과 위원은 학부운영위원회의 사전 동의로 활동을 개시하며 소속된 의결기구에서 사후 인준을 받아야 한다. 단, 학부운영위원회 소속 특별위원회의 경우에는 사후 인준 절차를 생략한다."}],"num":115,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a116","label":"제116조","title":"활동","paras":[{"k":"hang","x":"① 특별위원회는 활동 목적에 직·간접적으로 필요하다고 판단될 경우, 학부운영위원회의 출석 3분의 2 이상에 의한 결의로 구체적 활동 범위를 벗어난 활동을 할 수 있다. 이 경우, 필요한 이유 및 재설정한 활동 범위를 소속된 의결기구에 보고하여야 하며, 소속된 의결기구는 언제든지 출석 과반수에 의한 결의로 학부운영위원회의 해당 결정을 취소할 수 있다."},{"k":"hang","x":"② 특별위원회의 활동 기간은 최단 7일, 최장 60일까지이다. 단, 1회에 한해 30일을 연장할 수 있 다."},{"k":"hang","x":"③ 특별위원회의 활동 목적이 새내기새로배움터 준비인 경우, 제2항을 적용하지 아니한다."},{"k":"hang","x":"④ 특별위원회는 활동 목적에 따라 회원 및 단체에 위원회 출석 및 자료 제출을 요청할 수 있다."}],"num":116,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a117","label":"제117조","title":"해산 및 폐지","paras":[{"k":"hang","x":"① 다음 각호에 해당하는 경우 특별위원회는 해산한다."},{"k":"ho","x":"1. 활동 목적이 달성된 경우"},{"k":"ho","x":"2. 활동 기간이 종료된 경우"},{"k":"hang","x":"② 특별위원회는 언제든지 소속된 의결기구의 출석 3분의 2 이상에 의한 결의로 폐지할 수 있다. 단, 특별위원회의 목적이 감찰 및 조사에 해당하는 경우, 감찰 및 조사의 대상이 되는 회원은 의결기구에서 의결권을 행사할 수 없다."}],"num":117,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제５장 독립기구"},{"t":"h","lv":3,"text":"제1절 통칙"},{"t":"art","id":"a118","label":"제118조","title":"지위","paras":[{"k":"hang","x":"① 독립기구는 특수한 영역과 기능을 담당하기 위하여 설치된 상설기구이다."},{"k":"hang","x":"② 독립기구는 자유전공학부 학생회의 물적·인적 지원을 받으며 학부 학생회장단으로부터 그 업무의 감독을 받는다. 다만, 자유전공학부 집행위원회로부터는 독립적인 위상을 보장받는다."},{"k":"hang","x":"③ 전항에도 불구하고 독립기구의 업무가 학부 학생회장단으로부터의 독립의 필요성이 인정되는 범위 내에서 그 독립성이 보장된다."}],"num":118,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a119","label":"제119조","title":"성립 요건","paras":[{"k":"line","x":"독립기구는 다음 각호 중 하나 이상의 요건을 갖추어 설치가 필요하다고 인정될 때에 설치된다."},{"k":"ho","x":"1. 본회 회원의 권익 보호를 위한 전문적 활동을 꾸준히 수행하여 독립기구로서의 정체성이 확보되어 있는 단체"},{"k":"ho","x":"2. 본회 차원의 포괄적, 대외적 사업이 필요한 분야에 관련된 단체"}],"num":119,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 선거관리위원회"},{"t":"art","id":"a120","label":"제120조","title":"목적","paras":[{"k":"line","x":"선거관리위원회는 민주적이고 공정한 절차에 입각해 선거를 효율적으로 진행하는 데 그 목적을 둔다."}],"num":120,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a121","label":"제121조","title":"구성","paras":[{"k":"hang","x":"① 선거관리위원회는 학부 학생회장단을 제외한 학부운영위원 및 학생회칙 제55조 제4항에 의해 의결권을 가질 수 있는 자 전원을 기본으로 구성하며, 나머지 인원은 공개 모집함을 원칙으로 한다. 단, 반 학생회장단 동시선거의 경우, 해당 선거를 진행하는 선거관리위원회는 학부운영위원 및 학생회칙 제55조 제4항에 의해 의결권을 가질 수 있는 자 전원을 기본으로 구성하며, 나머지 인원은 공개 모 집함을 원칙으로 한다."},{"k":"hang","x":"② 선거관리위원회는 학부운영위원회에서 인준받은 8인 이상 12인 이하의 선거관리위원으로 구성한다."}],"num":121,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a122","label":"제122조","title":"대표자 선출","paras":[{"k":"line","x":"선거관리위원회의 위원장은 학부 학생회장단을 제외한 학부운영위원 중 1인으로 한다. 단, 반 학생회장단 동시선거의 경우, 해당 선거를 진행하는 선거관리위원회의 위원장은 학부 학생회장으로 한다."}],"num":122,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a123","label":"제123조","title":"활동 내용","paras":[{"k":"hang","x":"① 선거관리위원회는 제6장 선거에서 규정하는 선거에 관한 절차를 성실히 이행한다."},{"k":"hang","x":"② 선거관리위원회는 제6장 선거에서 규정하는 절차에 관해 최고 해석권 및 결정권을 가지며, 본회의 어떠한 의결기구도 회칙에 따라 진행된 선거 절차상의 해석 및 결정을 번복·철회·변경할 수 없다."},{"k":"hang","x":"③ 선거관리위원은 선거기간 동안 징계할 수 없으며, 선거관리위원회의 출석 3분의 2 이상에 의한 결의로만 해임될 수 있다."}],"num":123,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a124","label":"제124조","title":"의무","paras":[{"k":"hang","x":"① 선거관리위원회의 결정은 표결로서 진행하며, 표결은 기명으로 진행한다."},{"k":"hang","x":"② 선거관리위원회는 결정 사항 및 선거의 진행 상황을 정기적으로 공고해야 한다."},{"k":"hang","x":"③ 선거관리위원은 중립성을 지켜야 하며, 선거에 부당한 영향을 미치는 활동을 할 수 없다."}],"num":124,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a125","label":"제125조","title":"집행위원회에 대한 사항","paras":[{"k":"hang","x":"① 선거관리위원회는 선거 사무의 처리에 관해 집행위원회의 협조를 얻을 수 있다."},{"k":"hang","x":"② 선거관리위원회는 선거의 원활한 진행을 위해 집행위원회에 사무의 처리를 요청할 수 있다."}],"num":125,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a126","label":"제126조","title":"학부 학생회장단에 대한 사항","paras":[{"k":"hang","x":"① 학부 학생회장단은 학부 학생회장단 선거관리위원회의 결정 및 집행에 일체 개입할 수 없다."},{"k":"hang","x":"② 학부 학생회장단 선거 진행에 학부 학생회장단의 부당한 영향력 행사가 있을시, 선거관리위원회는 선거 기간 동안 기간을 정해 한시적으로 학부 학생회장단의 해당 직무 및 활동을 정지·취소할 수 있다."}],"num":126,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a127","label":"제127조","title":"재정","paras":[{"k":"line","x":"본회는 선거관리위원회의 원활한 운영을 위한 재원을 마련해야 한다."}],"num":127,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제3절 투표관리위원회"},{"t":"art","id":"a128","label":"제128조","title":"목적","paras":[{"k":"line","x":"투표관리위원회는 민주적이고 공정한 절차에 입각해 학생총투표를 효율적으로 진행하는 데 그 목적을 둔다."}],"num":128,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a129","label":"제129조","title":"구성","paras":[{"k":"line","x":"투표관리위원회는 학부운영위원 및 제55조 제4항에 의해 의결권을 가질 수 있는 자 전원으로 구성한다. 단, 학부 학생회장단은 제60조에 따른 학부 학생회장단 탄핵안에 대한 학생총투표에 대해서는 투표관리위원이 될 수 없다."}],"num":129,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a130","label":"제130조","title":"대표자 선출","paras":[{"k":"line","x":"투표관리위원회의 위원장은 학부운영위원 중 1인으로 한다."}],"num":130,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a131","label":"제131조","title":"활동 내용","paras":[{"k":"hang","x":"① 투표관리위원회는 제2장 제3절 학생총투표에서 규정하는 학생총투표에 관한 절차를 성실히 이행한다."},{"k":"hang","x":"② 투표관리위원회는 제2장 제3절 학생총투표에서 규정하는 절차에 관해 최고 해석권 및 결정권을 가지며, 본회의 어떠한 의결기구도 회칙에 따라 진행된 투표 절차상의 해석 및 결정을 번복·철회·변경할 수 없다."}],"num":131,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a132","label":"제132조","title":"준용","paras":[{"k":"hang","x":"① 의무에 관해서는 제124조를 준용한다."},{"k":"hang","x":"② 집행위원회에 대한 사항에 대해서는 제125조를 준용한다."},{"k":"hang","x":"③ 학부 학생회장단에 대한 사항에 대해서는 제126조를 준용한다."},{"k":"hang","x":"④ 재정에 관해서는 제127조를 준용한다."}],"num":132,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제4절 학생자치장학금위원회"},{"t":"art","id":"a133","label":"제133조","title":"위계","paras":[{"k":"line","x":"학생자치장학금의 집행 및 운영에 관하여 회칙·세칙에 규정이 없으면 학생자치장학금 내규에 의하고 내규가 없으면 장학금위원회의 결정사항에 의한다."}],"num":133,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a134","label":"제134조","title":"구성","paras":[{"k":"hang","x":"① 학생자치장학금위원회는 장학금운영위원회와 장학금집행위원회로 구성한다."},{"k":"hang","x":"② 장학금운영위원회는 학부운영위원회 전원으로 구성한다."},{"k":"hang","x":"③ 장학금집행위원회는 공개모집하여야 한다."},{"k":"hang","x":"④ 학생자치장학금위원회 위원은 자유전공학부 학생회 회원 중 징계를 받지 아니한 자로 한다."}],"num":134,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a135","label":"제135조","title":"목적","paras":[{"k":"hang","x":"① 장학금운영위원회는 본 장학금에 관련된 제반 사항을 감시·감독하고 보고받는 데 그 목적을 둔다."},{"k":"hang","x":"② 장학금집행위원회는 본 장학금에 관한 사항을 집행하는 데 그 목적을 둔다."}],"num":135,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a136","label":"제136조","title":"대표자 선출","paras":[{"k":"hang","x":"① 장학금운영위원회의 위원장은 학부 학생회장으로 한다."},{"k":"hang","x":"② 장학금집행위원회의 대표는 장학금집행위원회에서 보통⋅평등⋅직접⋅비밀선거로 선출한다."}],"num":136,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a137","label":"제137조","title":"활동 내용","paras":[{"k":"hang","x":"① 장학금운영위원회는 다음 각호의 업무를 수행한다."},{"k":"ho","x":"1. 장학금 운영사항에 관련된 감독"},{"k":"ho","x":"2. 장학금 지급, 장학금집행위원 및 장학금집행위원회 활동에 대한 감사"},{"k":"ho","x":"3. 장학금 운영 전반에 관련된 정보공개청구"},{"k":"ho","x":"4. 장학금집행위원 임면"},{"k":"ho","x":"5. 학생자치장학금 내규 개정"},{"k":"hang","x":"② 장학금운영위원회는 장학금집행위원회 운영목적에 부합하는 필수적 활동이 이뤄지지 않는 경우, 이러한 활동에 대한 촉구, 지시 혹은 활동 그 자체를 수행할 수 있다. 단, 장학금집행위원회 고유 활동의 집행은 가급적 자제한다."},{"k":"hang","x":"③ 장학금집행위원회는 다음 각호의 업무를 수행한다."}],"num":137,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a138","label":"제138조","title":"준용","paras":[{"k":"hang","x":"① 장학금운영위원회의 의무에 관해서는 제124조를 준용한다. 단, 제124조 제3항은 준용하지 아니한다."},{"k":"hang","x":"② 재정에 관해서는 제127조를 준용한다"},{"k":"hang","x":"③ 장학금운영위원회 회의의 진행에 관한 절차는 출석 과반수에 의한 결의로 학부운영위원회의 절차를 준용할 수 있다."}],"num":138,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a139","label":"제139조","title":"중요활동에 관한 사항","paras":[{"k":"line","x":"장학금운영위원회는 회원에게 중대한 영향을 미치는 장학금집행위원회의 활동에 대하여 동의권을 갖는다. 단, 장학금집행위원회의 효율적인 활동을 보장하기 위하여 장학금집행위원회 대표가 사전 집행이 불가피하다고 판단하여 집행한 사업에 대하여는 사후에 보고하고 승인 절차를 이행할 수 있다. 장학금집행위원회는 부동의된 대외활동에 대해서는 의결 즉시 원상회복을 위해 노력해야 한다."}],"num":139,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제5절 학생홍보대사"},{"t":"art","id":"a140","label":"제140조","title":"목적","paras":[{"k":"line","x":"학생홍보대사는 대외적으로 자유전공학부를 홍보하고, 자유전공학부의 가치 제고 및 위상을 높이는 데 목적을 둔다."}],"num":140,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a141","label":"제141조","title":"구성","paras":[{"k":"hang","x":"① 학생홍보대사는 공개 모집하여야 한다."},{"k":"hang","x":"② 학생홍보대사는 자유전공학부 학생회 회원 중 징계를 받지 아니한 자로 한다."}],"num":141,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a142","label":"제142조","title":"대표자 선출","paras":[{"k":"line","x":"학생홍보대사의 대표는 학생홍보대사 회원 중 보통·평등·직접·비밀선거로 선출한다."}],"num":142,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a143","label":"제143조","title":"활동 내용","paras":[{"k":"line","x":"학생홍보대사의 활동은 다음 각호로 정한다."},{"k":"ho","x":"1. 자유전공학부 홍보 활동 진행"},{"k":"ho","x":"2. 모교 방문 자유전공학부 홍보 행사 진행"},{"k":"ho","x":"3. 학생 초청 자유전공학부 홍보 행사 진행"}],"num":143,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a144","label":"제144조","title":"권리","paras":[{"k":"hang","x":"① 학생홍보대사는 본회로부터 공간을 지원받을 수 있다."},{"k":"hang","x":"② 학생홍보대사는 법학관(신관), CJ법학관, 해송법학도서관 강의실을 대관할 수 있다."},{"k":"hang","x":"③ 학생홍보대사는 학생회 페이스북 페이지, 카카오톡 공지방, 행정실 게시판을 활용할 수 있다."}],"num":144,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a145","label":"제145조","title":"재정","paras":[{"k":"line","x":"본회는 학생홍보대사의 원활한 운영을 위한 재원을 마련해야 한다."}],"num":145,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제6절 소수자인권위원회"},{"t":"art","id":"a146","label":"제146조","title":"목적","paras":[{"k":"line","x":"소수자인권위원회는 본회 내 소수자의 인권을 증진하는 데 목적을 둔다."}],"num":146,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a147","label":"제147조","title":"구성","paras":[{"k":"hang","x":"① 소수자인권위원회는 공개 모집하여야 한다."},{"k":"hang","x":"② 소수자인권위원회는 자유전공학부 학생회 회원 중 징계를 받지 아니한 자로 한다."}],"num":147,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a148","label":"제148조","title":"대표자 선출","paras":[{"k":"line","x":"소수자인권위원회의 대표는 소수자인권위원회 회원 중 보통·평등·직접·비밀선거로 선출한다."}],"num":148,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a149","label":"제149조","title":"활동 내용","paras":[{"k":"line","x":"소수자인권위원회의 활동은 다음 각호로 정한다."},{"k":"ho","x":"1. 인권 담론의 공고화 및 확장"},{"k":"ho","x":"2. 인권침해의 발생 방지 노력"},{"k":"ho","x":"3. 인권침해 피해자에 대한 보호"},{"k":"ho","x":"4. 인권 관련 전문 역량의 확보"}],"num":149,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a150","label":"제150조","title":"권리","paras":[{"k":"hang","x":"① 소수자인권위원회는 본회로부터 공간을 지원받을 수 있다."},{"k":"hang","x":"② 소수자인권위원회는 법학관(신관), CJ 법학관, 해송법학도서관 강의실을 대관할 수 있다."},{"k":"hang","x":"③ 소수자인권위원회는 학생회 페이스북 페이지, 카카오톡 공지방, 행정실 게시판을 활용할 수 있다."}],"num":150,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a151","label":"제151조","title":"재정","paras":[{"k":"line","x":"본회는 소수자인권위원회의 원활한 운영을 위한 재원을 마련해야 한다."}],"num":151,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제6장 선거"},{"t":"h","lv":3,"text":"제1절 학부 학생회장단 선거"},{"t":"art","id":"a152","label":"제152조","title":"선거 방식","paras":[{"k":"hang","x":"① 학부 학생회장단은 회원의 보통·평등·직접·비밀 선거로 선출한다."},{"k":"hang","x":"② 학부 학생회장단 선거에는 학부 학생회장 후보 단독으로 출마하거나 학부 학생회장 후보와 학부 부학생회장 후보 각 한 명씩이 조를 이루어 입후보할 수 있다."},{"k":"hang","x":"③ 학부 학생회장단 선거 방식에 대한 세부적인 사항은 「자유전공학부 학부·반 선거 시행세칙」으로 정한다."}],"num":152,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a153","label":"제153조","title":"시기","paras":[{"k":"line","x":"학부 학생회장단 선거는 매년 11월에 시행하며, 세부 일정은 학부운영위원회에서 정한다. 단, 재선거·보궐선거에 관하여는 선거시행세칙에 따른다."}],"num":153,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a154","label":"제154조","title":"선거권·피선거권","paras":[{"k":"hang","x":"① 본회 정회원은 학부 학생회장단 선거의 선거권이 있다. 단, 휴학생 회원과 수료생 회원의 경우 정회원 등록 절차를 통해 당해 선거에 있어 선거권을 가질 수 있다."},{"k":"hang","x":"② 본회의 회원인 자는 학부 학생회장단 선거의 피선거권이 있다."},{"k":"hang","x":"③ 학부 학생회장단 선거에 출마하려는 후보는 3학기 이상 등록자이어야 한다."},{"k":"hang","x":"④ 징계로서 선거권과 피선거권을 박탈당한 자는 선거의 선거권과 피선거권이 없다."}],"num":154,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a155","label":"제155조","title":"선거관리위원회","paras":[{"k":"hang","x":"① 학부 학생회장단 선거를 공정하게 민주적으로 관리하기 위하여 선거관리위원회를 둔다."},{"k":"hang","x":"② 선거관리위원회는 회칙과 ｢자유전공학부 학부·반 선거시행세칙｣에 따라 학부 학생회장단 선거에 관련된 모든 사항을 결정한다."},{"k":"hang","x":"③ 선거 기간 동안 학부 학생회장단과 집행위원회가 사업 집행, 의견 표명 등을 하기 위해서는 선거 관리위원회의 사전 허가를 받아야 한다. 학생회장단과 집행위원회의 특정 행위가 선거에 영향을 미칠 수 있다고 판단되면 선거관리위원회는 해당 행위를 허가하지 않을 수 있다."},{"k":"hang","x":"④ 이 밖에 선거관리위원회의 운영에 관한 절차는 제5장 제2절 선거관리위원회 규정에 따른다."}],"num":155,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a156","label":"제156조","title":"재선거·보궐선거","paras":[{"k":"hang","x":"① 다음 각호 중 하나의 경우에 해당할 경우 이듬해 3월 중 재선거를 실시한다. 이때 재선거 세부 일정은 비상대책위원회에서 정한다."},{"k":"ho","x":"1. 재투표에서도 총오차가 명부상 총 투표자 수 대비 3%를 넘을 때"},{"k":"ho","x":"2. “지지선본 없음”란에 기표한 사람의 수가 1위 득표 조보다 많을 때"},{"k":"ho","x":"3. “반대”와 “기권”란에 기표한 사람의 수의 합이 “찬성”란에 기표한 사람의 수보다 많을 때"},{"k":"ho","x":"4. 후보가 한 조일 경우 그 득표수가 선거권자 총수의 10% 이상이 아닐 때"},{"k":"ho","x":"5. 입후보자가 없거나 선거가 무산되는 등의 사유로 당선인이 없는 때"},{"k":"hang","x":"② 학생회장단이 탄핵 등의 이유로 궐위된 때 잔여 임기가 180일이 넘으면 궐위된 날로부터 10일 이내에 학부운영위원회는 보궐선거의 시행 일정을 결정하여야 한다. 단, 임기 종료일이 확정되지 않았을 때는 잔여 임기의 계산을 위한 임기 종료일은 11월 30일로 한다."},{"k":"hang","x":"③ 잔여 임기가 180일이 넘지 않은 경우에도 학부운영위원회는 선거의 필요성, 선거 시기, 잔여 임기 등 본회의 제반 사정을 고려하여 보궐선거의 시행을 결정할 수 있다."},{"k":"hang","x":"④ 학부운영위원회가 보궐선거 시행 일정을 확정한 날로부터 20일 이내에 보궐선거를 시행하여야 한다."}],"num":156,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a157","label":"제157조","title":"선거시행세칙","paras":[{"k":"line","x":"그 밖에 선거에 관한 사항은 ｢자유전공학부 학부·반 선거 시행세칙｣으로 정한다."}],"num":157,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 반 학생회장단 동시선거"},{"t":"art","id":"a158","label":"제158조","title":"반 학생회장단 동시선거","paras":[{"k":"hang","x":"① 학부 학생회장단 선거관리위원회는 학부운영위원회의 출석 과반수에 의한 결의로 반 학생회장단 동시선거를 진행할 수 있다."},{"k":"hang","x":"② 제1항에서 규정하는 동시선거를 진행하지 않는 경우, 각 반 학생회장단 선거에 관한 제반 사항은 각 반 학생회칙이 정하는 바에 의한다."},{"k":"hang","x":"③ 반 학생회장단 동시선거가 결정되면, 본회의 회칙 및 학부·반 선거시행세칙이 규정하는 절차에 따라 반 학생회장단 선거를 진행한다."}],"num":158,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a159","label":"제159조","title":"준용","paras":[{"k":"hang","x":"① 선거 방식에 관해서는 제152조를 준용한다."},{"k":"hang","x":"② 선거 시기에 관해서는 제153조를 준용한다."},{"k":"hang","x":"③ 선거권에 관해서는 제154조를 준용한다."},{"k":"hang","x":"④ 선거관리위원회에 관해서는 제155조를 준용한다."},{"k":"hang","x":"⑤ 재선거·보궐선거에 관해서는 제156조를 준용한다."},{"k":"hang","x":"⑥ ｢선거시행세칙｣에 관해서는 제157조를 준용한다."}],"num":159,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제7장 재정"},{"t":"h","lv":3,"text":"제１절 통칙"},{"t":"art","id":"a160","label":"제160조","title":"원칙","paras":[{"k":"line","x":"본회의 각 기구는 재정을 효율적이고 투명하게 운용하여야 한다."}],"num":160,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a160-2","label":"제160조의2","title":"등기부","paras":[{"k":"hang","x":"① 본회는 다음 각호의 등기부를 두어 운용한다. 본회의 회원 또는 기구 간에 관리권한, 자산, 자치공간 등에 대한 분쟁이 있는 경우 등기부에 기재된 사항을 진실한 것으로 추정한다."},{"k":"ho","x":"1. 「관리권한등기부」"},{"k":"ho","x":"2. 「자산등기부」"},{"k":"ho","x":"3. 「자치공간등기부」"},{"k":"hang","x":"② 등기부의 관리는 집행위원회의 사무로 하되, 정정 또는 경정의 청구 기간이 경과하여 확정된 등기부 기재사항에 대하여는 제33조에 따라 변경 또는 취소할 수 없다."},{"k":"hang","x":"③ 등기부는 본회의 회원이 언제나 열람할 수 있도록 유·무형의 공간에 비치하여야 하며, 집행위원회는 기재사항에 변경이 있는 때에는 지체 없이 그 사실을 공고해야 한다."},{"k":"hang","x":"④ 본회의 회원은 등기부의 기재사항에 대하여 전항의 공고가 있은 때로부터 30일 내에 집행위원회에 기재사항에 대한 정정 또는 경정을 청구할 수 있다."},{"k":"hang","x":"⑤ 전항의 청구에 있어서 이해관계자 간의 분쟁이 있는 경우에는 임시 학생대표자회를 개의하여 심의 및 의결한다."}],"num":160,"sub":2,"bu":false,"bold_title":false},{"t":"art","id":"a161","label":"제161조","title":"재정운용세칙","paras":[{"k":"line","x":"그 밖에 재정 운용에 관한 사항은 ｢고려대학교 총학생회 재정운용세칙｣을 준용한다."}],"num":161,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제２절 자산·배분"},{"t":"art","id":"a162","label":"제162조","title":"자산","paras":[{"k":"hang","x":"① 본회는 유·무형의 동산, 부동산, 권리 등을 소유할 수 있으며, 이를 본회의 자산이라 한다."},{"k":"hang","x":"② 본회의 자산은 각 기구가 독립하여 취득, 보관, 사용, 처분함을 원칙으로 한다."},{"k":"hang","x":"③ 집행기구는 제작, 구매, 수증 등의 방법으로 자산을 취득한다. 다음 각호 중 어느 하나에 해당하는 것은 집행기구의 자산으로 본다."},{"k":"ho","x":"1. ｢자산등기부｣에 집행위원회의 자산으로 등기된 것"},{"k":"ho","x":"2. 학부 학생회장단·집행위원과 이에 준하는 자가 그 직으로써 취득한 것"},{"k":"ho","x":"3. 본회 집행기구의 사업 또는 사무 집행을 위하여 취득하거나, 사업 집행의 결과물로 취득한 것"},{"k":"ho","x":"4. 제1호 내지 제3호에 해당하는 자산으로부터 파생된 것"}],"num":162,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a163","label":"제163조","title":"자산의 관리","paras":[{"k":"hang","x":"① 본회의 각 기구는 자산을 항상 사용하거나 처분할 수 있도록 선량한 관리자의 주의로써 보관하여야 한다."},{"k":"hang","x":"② 집행기구의 자산은 본회 사업과 사무의 집행을 위하여 사용함을 원칙으로 한다."},{"k":"hang","x":"③ 집행기구의 자산은 대여를 목적으로 한 자산이거나 대여하여도 사업 또는 사무에 지장이 없다고 인정되는 자산일 때만 대여할 수 있다. 또한, 집행기구의 자산은 본회 기구와 회원에게 우선적으로 대여되어야 한다."},{"k":"hang","x":"④ 집행기구는 자산의 취득, 보관, 사용, 처분이 본회의 이익을 위하여 적정하고 효율적으로 이루어질 수 있도록 하여야 한다."},{"k":"hang","x":"⑤ 집행기구는 자산의 중대한 변화를 야기하는 집행에 대해 학부운영위원회의 인준을 받아야 한다. 이 경우, 사전에 집행에 대한 예고를 해야 하며, 집행 후 자산 변화를 공고해야 한다."},{"k":"hang","x":"⑥ 집행위원회는 집행기구 자산 중 고정자산의 목록을 작성하여 매 학기 정기학생총회 또는 정기학생대표자회에 보고한다."},{"k":"hang","x":"⑦ 본회의 각 기구는 사용할 필요가 없거나 사용할 수 없는 자산을 교환, 매각, 증여, 폐기 등의 방법으로 처분할 수 있다."},{"k":"hang","x":"⑧ 의결기구는 집행기구의 자산 취득, 보관, 사용, 처분이 본회의 이익을 위한 것이 아니거나, 적정성 또는 효율성이 없다고 판단되면 이를 허가하지 않거나, 취소할 수 있다."}],"num":163,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a164","label":"제164조","title":"수입","paras":[{"k":"line","x":"본회 재정의 수입은 학생회비, 학교 지원금, 사업별 후원금, 그 밖에 수익금으로 한다."}],"num":164,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a165","label":"제165조","title":"학생회비","paras":[{"k":"hang","x":"① 학생회비는 일시납부·1회 납부를 원칙으로 한다. 단, 일시납부 하지 못할 경제적·사회적 또는 그 밖의 중대한 사유가 있는 경우 분할납부를 할 수 있다."},{"k":"hang","x":"② 집행위원회는 학생회비의 수입 및 지출과 관련된 집행내역을 매달 날짜를 정하여 공고하여야 한다."},{"k":"hang","x":"③ 학부 학생회비의 수입 중 반 학생회비에 할당되는 금액은 반 학생회 소속 학생회비 납부자 1인당 40,000원으로 한다."},{"k":"hang","x":"④ 학생총회 또는 학생대표자회는 매년 2학기 정기회의에서 학부 학생회비의 조정에 관하여 논의하여, 필요할 때는 인상·인하를 결정할 수 있다."}],"num":165,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제３절 회계·심의"},{"t":"art","id":"a166","label":"제166조","title":"회계연도","paras":[{"k":"line","x":"본회의 재정은 다음 각호의 기간으로 나누어 집행하고 결산한다."},{"k":"ho","x":"1. 제1분기: 2학기 종강일 다음 날부터 1학기 개강일 전날까지"},{"k":"ho","x":"2. 제2분기: 1학기 개강일부터 1학기 종강일까지"},{"k":"ho","x":"3. 제3분기: 1학기 종강일 다음 날부터 2학기 개강일 전날까지"},{"k":"ho","x":"4. 제4분기: 2학기 개강일부터 2학기 종강일까지"}],"num":166,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a167","label":"제167조","title":"학부운영위원회 심의","paras":[{"k":"hang","x":"① 학생회비를 사용하는 집행위원회 및 독립기구 등은 다음 각호에 따라 예산안·결산을 작성하여 학생총회 또는 학생대표자회 개의 예정일 7일 전까지 학부운영위원회에 제출하여야 한다."},{"k":"ho","x":"1. 1학기 정기회의: 작년도 4분기, 금년도 1분기의 결산과 금년도 2분기·3분기의 예산안"},{"k":"ho","x":"2. 2학기 정기회의: 금년도 2분기·3분기의 결산과 금년도 4분기, 익년도 1분기의 예산안"},{"k":"hang","x":"② 학부운영위원회는 제１항에 따른 예산안·결산 제출기한을 정하여 공고하고 예산안·결산 보고의 의무가 있는 기구에 개별적으로 통보하여야 한다."},{"k":"hang","x":"③ 학부운영위원회는 제１항에 따라 제출된 예산안·결산을 심의한다."}],"num":167,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a168","label":"제168조","title":"승인","paras":[{"k":"hang","x":"① 학생회비를 사용하는 집행위원회 및 독립기구 등은 제167조 제1항에 따라 학부운영위원회의 심의를 거친 예산안·결산을 학생총회 또는 학생대표자회에 보고한다."},{"k":"hang","x":"② 학생대표자회 또는 학생총회는 제１항에 따라 보고된 예산안·결산을 승인한다."},{"k":"hang","x":"③ 학생대표자회 또는 학생총회에서 승인된 예산안·결산은 공개되어야 한다."},{"k":"hang","x":"④ 각 기구는 학생총회 또는 학생대표자회 출석 구성원의 과반수에 의한 동의가 있으면 예산안·결산을 현장에서 수정 발의하여 재상정할 수 있다."}],"num":168,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a169","label":"제169조","title":"재심의","paras":[{"k":"hang","x":"① 다음 각호에 해당하는 경우, 학생총회 또는 학생대표자회는 출석 과반수의 찬성으로 해당 기구에의 학생회비 지급을 유보하고 학부운영위원회에서 재심의를 받도록 해야 한다. 재심의에서의 승인은 학부운영위원회 출석 3분의 2 이상의 결의에 의한다."},{"k":"ho","x":"1. 예산안·결산이 승인되지 못한 경우"},{"k":"ho","x":"2. 예산안·결산에 중대한 하자가 있는 경우"},{"k":"ho","x":"3. 심의 과정 중 절차상 문제가 발견된 경우"},{"k":"ho","x":"4. 판단자료 미비로 예산안·결산에 대한 심의가 불가능하거나 예산안·결산을 신뢰할 수 없을 경우"},{"k":"hang","x":"② 제１항에 해당하는 기구는 학생총회 또는 학생대표자회 개의일로부터 10일 이내에 수정안을 작성하여 학부운영위원회에 제출해야 한다."},{"k":"hang","x":"③ 학부운영위원회는 수정안을 지체 없이 심의하여 학생총회 또는 학생대표자회 개의일로부터 15일 이내에 결과를 공고한다."},{"k":"hang","x":"④ 제１항에 해당함에도 수정안을 학부운영위원회에 제출하지 않은 기구 혹은 제기된 문제를 개선하지 않은 채 수정안을 작성하여 제출한 기구는 책임자에 따라 각호 중 하나의 징계를 한다. 책임자란 불승인 결정에 직·간접적인 책임이 있는 대표자 및 기구의 구성원을 의미한다."},{"k":"ho","x":"1. 책임자가 현직일 때: 예산 지급액의 50% 삭감과 사과문·경위서 게재"},{"k":"ho","x":"2. 책임자가 전직일 때: 책임자의 사과문·경위서 게재"},{"k":"hang","x":"⑤ 배임, 횡령 사안 등 문제의 정도가 심각한 경우 학부운영위원회는 제4항의 징계와 함께 다음 각호의 조치를 함께 결정할 수 있다. 제3호의 경우 책임자와 학생회비가 불법하게 사용될 당시 대표자가 연대하여 책임을 져야 한다."},{"k":"ho","x":"1. 기구가 가지고 있는 학생회비 잔금 사용 중지"},{"k":"ho","x":"2. 기구가 가지고 있는 학생회비 잔금 전액 환수"},{"k":"ho","x":"3. 기구가 불법하게 사용한 학생회비 전액 반환"}],"num":169,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제8장 자치공간"},{"t":"art","id":"a170","label":"제170조","title":"목적","paras":[{"k":"line","x":"본회의 자치공간은 본회의 자치활동의 기초가 되는 토대로서, 회원의 교류 및 결속을 공고히 하고 회원을 보호하며 안정을 보장해주는 역할을 통해 창조적이고 진보적인 대학문화를 건설하는 데 기여함을 목적으로 한다."}],"num":170,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a171","label":"제171조","title":"자치공간","paras":[{"k":"hang","x":"① 본회의 자치공간은 다음 각호로 정한다."},{"k":"ho","x":"1. ｢자치공간등기부｣에 등기된 공간"},{"k":"ho","x":"2. 학부 학생회실"},{"k":"ho","x":"3. 법학관(구관) 각 반 학생회실, 각 자치단체실, 학생회창고, 코웍스"},{"k":"ho","x":"4. 기타 본회의 노력으로 확보·명도 받은 공간"},{"k":"hang","x":"② 본회의 각 기구 및 회원은 대내외적으로 자치공간을 이용, 분배, 회수, 보수, 개조할 관리 권한을 갖는다. 관리 권한이라 함은 각 사안의 원활한 운영을 위하여 배타적인 권리행사 및 집행을 할 수 있는 권원을 의미한다."}],"num":171,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a172","label":"제172조","title":"준자치공간","paras":[{"k":"hang","x":"① 본회의 지배·관리하에 있지 않지만, 학교의 승인을 얻어 본회 회원의 자유로운 이용이 보장된 공간을 준자치공간이라고 한다."},{"k":"hang","x":"② 준자치공간은 다음 각호로 정한다."},{"k":"ho","x":"1. CJ법학관 남학생 휴게실"},{"k":"ho","x":"2. CJ법학관 여학생 휴게실"},{"k":"ho","x":"3. CJ법학관 및 해송법학도서관 라운지"},{"k":"ho","x":"4. CJ법학관 및 해송법학도서관 스터디룸"},{"k":"ho","x":"5. 법학관(구관), 법학관(신관), CJ법학관 강의실"},{"k":"ho","x":"6. 그 밖의 기타 학생 편의시설"}],"num":172,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a173","label":"제173조","title":"의무","paras":[{"k":"line","x":"본회는 자치공간에 대해 다음 각호의 의무가 있다."},{"k":"ho","x":"1. 자치공간에 대한 본회의 자치권이 침해받지 않도록 수호"},{"k":"ho","x":"2. 자치공간의 안전 및 청결 유지"},{"k":"ho","x":"3. 자치공간 이용과 관련한 갈등 해결"},{"k":"ho","x":"4. 회원의 자치공간 이용 기회보장"}],"num":173,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a174","label":"제174조","title":"자치공간운영세칙","paras":[{"k":"line","x":"그 밖의 자치공간에 관한 자세한 내용은 「자유전공학부 자치공간운영세칙」으로 정한다."}],"num":174,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제9장 회칙·세칙·규칙"},{"t":"h","lv":3,"text":"제１절 회칙 개정"},{"t":"art","id":"a175","label":"제175조","title":"개정안 발의","paras":[{"k":"hang","x":"① 회칙 개정안은 다음 각호 중 하나에 따라 발의된다."},{"k":"ho","x":"1. 학부운영위원회의 출석 과반수에 의한 발의"},{"k":"ho","x":"2. 학부운영위원회 재적 위원 과반수의 연서에 따른 발의"},{"k":"ho","x":"3. 회원 10분의 1의 연서에 따른 발의"},{"k":"ho","x":"4. 회칙개정특별위원회에 의한 발의"},{"k":"hang","x":"② 연서에 따른 소집요구는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식을 준용하며, ｢고려대학교 총학생회 사무처리세칙｣에서 정한 사항이 포함되어야 한다."}],"num":175,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a176","label":"제176조","title":"개정안 공고","paras":[{"k":"line","x":"회칙 개정안이 발의되면 학부 학생회장은 다음 각호의 사항을 7일 이상 공고하여야 한다."},{"k":"ho","x":"1. 회칙 개정안의 제안이유와 주요 내용"},{"k":"ho","x":"2. 신·구조문 대비표"},{"k":"ho","x":"3. 제175조에 따른 회칙 개정안 발의자 명단"}],"num":176,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a177","label":"제177조","title":"개정안 심의","paras":[{"k":"hang","x":"① 제175조 제１항 제１호의 경우 회칙 개정을 위한 학생총회 또는 학생대표자회 개의에 앞서 학부운영위원회에서 개정안을 심의하거나, 별도의 공청회를 개최하여 개정안을 심의한다."},{"k":"hang","x":"② 개정안 심의 과정에는 축조심사와 찬반 토론이 포함되어야 한다."}],"num":177,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a178","label":"제178조","title":"개정 의결","paras":[{"k":"hang","x":"① 회칙 개정안이 발의되었을 때 본회 의결기구의 의장은 지체 없이 학생총회 또는 학생대표자회를 소집하여 회칙 개정안을 심의·의결한다."},{"k":"hang","x":"② 회칙 개정의 의결은 제23조 제３항에 따라 기명투표로 표결한다."},{"k":"hang","x":"③ 회칙 개정의 의결 요건은 제30조 제２항 및 제57조의2 제2항에 따른다."}],"num":178,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a179","label":"제179조","title":"개정안 정리","paras":[{"k":"line","x":"회칙 개정의 의결이 있은 후 저촉되는 조항·자구·숫자 그 밖의 기타 정리가 필요한 경우 학부운영위원회는 회칙 개정의 공포 전까지 이를 검토하여 정리할 수 있다. 단, 개정 의결된 회칙의 내용이나 취지를 변경하는 것은 허용되지 아니한다."}],"num":179,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a180","label":"제180조","title":"공포","paras":[{"k":"hang","x":"① 회칙 개정이 의결되면 학부 학생회장은 개정안 정리를 거쳐 3일 이내에 공포한다."},{"k":"hang","x":"② 회칙의 공포문에는 다음 각호의 사항이 포함되어야 한다."},{"k":"ho","x":"1. 회칙 개정안의 제안이유와 주요 내용"},{"k":"ho","x":"2. 신·구조문 대비표"},{"k":"ho","x":"3. 제175조에 따른 회칙 개정안 발의자 명단"},{"k":"ho","x":"4. 회칙 개정 찬성자 명단"},{"k":"hang","x":"③ 본조는 세칙과 규칙의 제정·개정·폐지에도 준용한다. 단, 세칙 제정의 공포 시에는 세칙의 제정 순서에 따라 번호를 붙여서 공포하며, 규칙 제정의 공포 시에는 제정의 근거가 되는 세칙별로 규칙의 제정 순서에 따라 번호를 붙여서 공포한다."}],"num":180,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제２절 세칙·규칙"},{"t":"art","id":"a181","label":"제181조","title":"세칙·규칙","paras":[{"k":"hang","x":"① 본회는 회칙에 따라 세칙을 제정·개정하고, 세칙에 따라 규칙을 제정·개정한다. 단, 일반규칙은 세칙에 근거를 두지 않고 제정·개정할 수 있다."},{"k":"hang","x":"② 회칙에 위반되는 세칙과 세칙에 위반되는 규칙은 그 위반되는 부분에 한정하여 효력이 없다."},{"k":"hang","x":"③ 회칙에 위반되는 산하기구의 자치규칙은 성립하지 아니하고, 그 위반되는 부분에 한하여 효력이 없다."}],"num":181,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a182","label":"제182조","title":"세칙의 제정·개정·폐지","paras":[{"k":"hang","x":"① 세칙은 회칙에서 위임한 사항과 회칙을 시행하기 위한 사항을 정하기 위하여 제정한다."},{"k":"hang","x":"② 세칙은 학생총회 또는 학생대표자회에서 제정·개정·폐지를 의결한다."},{"k":"hang","x":"③ 세칙의 제정·개정·폐지는 제175조를 준용한다."},{"k":"hang","x":"④ 세칙 개정안의 정리에 관하여서는 제179조를 준용한다."},{"k":"hang","x":"⑤ 세칙 제정 및 개정의 공포에 관하여서는 제180조를 준용한다."}],"num":182,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a183","label":"제183조","title":"세칙에 부수된 규칙의 제정·개정·폐지","paras":[{"k":"hang","x":"① 세칙에 부수된 규칙은 해당 세칙에서 위임한 사항과 해당 세칙을 시행하기 위한 사항을 정하기 위하여 제정한다."},{"k":"hang","x":"② 세칙에 부수된 규칙은 해당 세칙의 근거 규정에 따라 제정·개정·폐지된다."},{"k":"hang","x":"③ 세칙에 부수된 규칙의 공포에 관하여서는 제180조를 준용한다."}],"num":183,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a184","label":"제184조","title":"일반규칙의 제정·개정·폐지","paras":[{"k":"hang","x":"① 일반규칙은 다음 각호의 사항을 규율하기 위해 제정한다."},{"k":"ho","x":"1. 의결기구에 관한 사항"},{"k":"ho","x":"2. 집행기구에 관한 사항"},{"k":"ho","x":"3. 산하기구에 관한 사항"},{"k":"ho","x":"4. 독립기구에 관한 사항"},{"k":"ho","x":"5. 본회의 정기사업·비정기사업에 관한 사항"},{"k":"ho","x":"6. 회원의 권리·의무에 관한 사항"},{"k":"ho","x":"7. 자치단체에 관한 사항"},{"k":"ho","x":"8. 학교 시설 사용 등에 대한 회원 전체의 합의에 관한 사항"},{"k":"ho","x":"9. 학교 당국과의 합의에 관한 사항"},{"k":"ho","x":"10. 본회와 학내 각 단체 간의 합의에 관한 사항"},{"k":"ho","x":"11. 본회와 외부단체와의 합의에 관한 사항"},{"k":"ho","x":"12. 회칙의 특정 조문에 관한 추가적인 사항"},{"k":"ho","x":"13. 그 밖에 규칙으로 명문화하는 것이 필요하다고 인정되는 사항"},{"k":"hang","x":"② 일반규칙은 학부운영위원회가 제정·개정·폐지를 의결한다."},{"k":"hang","x":"③ 일반규칙의 공포에 관하여서는 제180조를 준용한다."}],"num":184,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제３절 해석"},{"t":"art","id":"a185","label":"제185조","title":"회칙 해석의 원칙","paras":[{"k":"hang","x":"① 회칙을 해석·적용함에 있어서는 해당 조항의 문맥적 의미와 회칙 전체의 논리적 체계성에 비추 어 본회의 민주적 운영이 저해되거나 회원의 권리가 부당하게 침해되지 않도록 주의하여야 한다."},{"k":"hang","x":"② 본회의 중요 사항과 회원의 권리·의무에 중대한 변화를 야기하는 회칙의 해석은 회원들을 상대로 의견을 수렴하기 위한 공청회를 개최할 수 있다."},{"k":"hang","x":"③ 세칙·규칙에 관하여서도 본조를 적용한다."}],"num":185,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"부칙","bu":true,"id":"bu1"},{"t":"free","paras":[{"k":"line","x":"이 회칙은 2021. 11. 13.부터 시행한다."}]}],"note":null},{"id":"hoechik-20260402","date":"2026.04.02","kind":"전부개정","title":"고려대학교 자유전공학부 학생회칙","subtitle":null,"history":[["2009. 03.","제정"],["2011. 05. 11.","일부개정"],["2013. 10. 30.","일부개정"],["2014. 03. 26.","일부개정"],["2014. 09. 22.","일부개정"],["2015. 03. 24.","일부개정"],["2015. 09. 22.","일부개정"],["2016. 08. 29.","전부개정"],["2017. 03. 02.","일부개정"],["2017. 05. 27.","전부개정"],["2017. 08. 19.","전부개정"],["2018. 10. 12.","전부개정"],["2021. 11. 13.","전부개정"],["2023. 02. 11.","일부개정"],["2023. 11. 12.","일부개정"],["2024. 10. 26.","전부개정"],["2026. 04. 02.","전부개정"]],"pdf":"pdf/hoechik-20260402.pdf","pdfName":"고려대학교_자유전공학부_학생회칙(2026.04.02_전부개정).pdf","blocks":[{"t":"pre","title":"전문","paras":["정의를 추구하는 고려대학교의 역사적 사명과 함께 공동체를 선도하고 연대하는 자유전공학부는 창설 이래 이어져 온 민주적 전통과 자유ㆍ정의ㆍ진리를 좇는 본교의 교육 이념, 학문 및 사상에 관한 창조적 탐구 정신을 이어받아 자유전공학부의 주체적이고 자율적이며 민주적인 활동을 다짐하는 바이다. 이에 2009년 3월 제정되고 15차에 걸쳐 개정된 자유전공학부 학생회칙을 자유전공학부 학생대표자회의 의결을 거쳐 개정한다."],"date":"2026년 04월 02일"},{"t":"h","lv":2,"text":"제1장 총칙"},{"t":"art","id":"a1","label":"제1조","title":"명칭","paras":[{"k":"line","x":"본회는 고려대학교 자유전공학부 학생회라 한다."}],"num":1,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a2","label":"제2조","title":"목적","paras":[{"k":"hang","x":"① 본회는 민주적이고 자율적인 학생자치활동을 통하여 회원 간의 결속을 강화하고 회원의 권익 신장을 도모함을 목적으로 한다."},{"k":"hang","x":"② 본회는 자유로운 진리의 탐구와 창조적이고 진보적인 대학 문화의 건설을 추구하여 사회발전에 능동적으로 이바지함을 목적으로 한다."},{"k":"hang","x":"③ 본회는 시대의 불의에 맞서 사회적 연대를 구축하고 침해된 정의의 회복을 위하여 대내외에서 주체적으로 행동함을 목적으로 한다."},{"k":"hang","x":"④ 본회는 본회의 자산 및 자치공간과 회원이 지닌 권리를 보호함을 목적으로 한다."},{"k":"hang","x":"⑤ 본회는 법률적 기초 소양 및 다양한 영역에서의 복합적 전문성을 갖춘 공적 영역의 선도적 지도자를 양성한다는 교육목적을 달성하기 위하여 노력하며, 제1전공이 다른 회원들 간의 교류를 장려함을 목적으로 한다."}],"num":2,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a3","label":"제3조","title":"소재지","paras":[{"k":"line","x":"본회는 고려대학교 서울캠퍼스 법학관 구관, 법학관 신관 및 CJ법학관에 위치한다."}],"num":3,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a4","label":"제4조","title":"회원","paras":[{"k":"hang","x":"① 고려대학교 자유전공학부 소속인 자는 본회의 회원이 된다."},{"k":"hang","x":"② 졸업ㆍ자퇴ㆍ퇴학 등으로 고려대학교 서울캠퍼스 학부 과정 소속이 아니게 된 사람과 총학생회 제명으로 인해 총학생회 회원직을 박탈당한 사람은 그 즉시 회원 자격을 잃으며, 정학 등의 사유로 등교가 정지된 자는 그 기간 회원 자격이 정지된다."},{"k":"hang","x":"③ 제2항에도 불구하고 회원의 자격이 부당하게 정지 또는 박탈된 자는 학부운영위원회 출석 위원 3분의 2 이상의 찬성으로 회원 지위를 회복할 수 있다."},{"k":"hang","x":"④ 본회의 회원 중 고려대학교 서울캠퍼스 학부 과정 재학생은 다음 각호의 기간 본회의 정회원이 된다. 단, 학기 중 휴학한 자는 그 즉시 준회원이 된다."},{"k":"ho","x":"1. 1학기 재학생: 1학기 개강일로부터 2학기 개강일 전날까지"},{"k":"ho","x":"2. 2학기 재학생: 2학기 개강일로부터 이듬해 1학기 개강일 전날까지"},{"k":"hang","x":"⑤ 본회의 회원 중 고려대학교 서울캠퍼스 학부 과정 휴학생은 준회원이 된다."},{"k":"hang","x":"⑥ 본회의 회원 중 고려대학교 서울캠퍼스 학부 과정 수료생은 수료회원이 된다."},{"k":"hang","x":"⑦ 준회원ㆍ수료회원 중에서 다음 각호의 등록 기간에 등록 절차를 이행한 자는 남은 기간 정회원이 된다. 단, 자유전공학부 학부ㆍ반 학생회장단 선거의 특수성을 고려하여 선거 후보자 등록 마감일 다음 날부터 당선 공고일까지는 정회원으로 등록할 수 없다. 그 밖의 정회원 등록에 관한 사항은 규칙으로 정한다."},{"k":"ho","x":"1. 1학기 정회원 등록 기간: 1학기 개강일부터 2학기 개강일 전날까지"},{"k":"ho","x":"2. 2학기 정회원 등록 기간: 2학기 개강일부터 이듬해 1학기 개강일 전날까지"},{"k":"hang","x":"⑧ 본회의 회원 중 다음 각호에 해당하는 회원은 신입생 회원이라고 한다."},{"k":"ho","x":"1. 고려대학교에 입학한 지 2학기가 지나지 않은 회원"},{"k":"ho","x":"2. 편입학ㆍ소속 변경 등으로 자유전공학부 재학생이 된 지 2학기가 지나지 않은 회원"},{"k":"hang","x":"⑨ 본회의 회원 중 제8항 제1호에 해당하는 회원과 두 학번 이상 차이가 나는 회원은 고학번 회원이라고 한다."},{"k":"hang","x":"⑩ 본회의 회원 중 순수정원외 및 외국인 학생은 국제 회원이라고 한다."}],"num":4,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a5","label":"제5조","title":"회원의 권리","paras":[{"k":"hang","x":"① 본회의 회원은 성별ㆍ성적 지향ㆍ성 정체성ㆍ인종ㆍ사상ㆍ종교ㆍ장애 등에 의하여 차별받지 않을 권리를 가진다."},{"k":"hang","x":"② 본회의 회원은 본회의 모든 자치활동에 참여할 권리를 가진다."},{"k":"hang","x":"③ 본회의 회원은 양심ㆍ사상ㆍ종교의 자유를 가지며, 이에 따라 자유롭게 활동할 권리를 가진다."},{"k":"hang","x":"④ 본회의 회원은 집회ㆍ결사의 자유를 가진다."},{"k":"hang","x":"⑤ 본회의 회원은 회칙에 따라 본회의 활동과 운영 전반에 관하여 보고받고 의견을 개진할 권리를 가진다."},{"k":"hang","x":"⑥ 본회의 회원은 본회를 부인하거나 정당한 학생 자치활동을 침해하는 것에 저항할 권리를 가진다."},{"k":"hang","x":"⑦ 본회의 회원은 본회가 지니는 급부를 적절한 시기에 제공받을 권리를 가진다."},{"k":"hang","x":"⑧ 본회의 회원은 자치공간 및 본회 자산을 누릴 권리를 가진다."},{"k":"hang","x":"⑨ 본회의 회원은 회칙에 근거한 선거권을 가진다."},{"k":"hang","x":"⑩ 본회의 정회원은 회칙에 근거한 피선거권을 가진다."},{"k":"hang","x":"⑪ 본회의 회원이 지닌 자유와 권리는 회칙에 열거되지 아니한 이유로 경시되지 아니한다. 다만, 회원의 모든 자유와 권리는 그 본질적인 내용을 침해하지 아니하는 범위 내에서 안전보장ㆍ질서유지 또는 공공복리를 위하여 필요한 경우에만 제한할 수 있다."}],"num":5,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a6","label":"제6조","title":"회원의 의무","paras":[{"k":"hang","x":"① 본회의 회원은 성별ㆍ성적 지향ㆍ성 정체성ㆍ인종ㆍ사상ㆍ종교ㆍ장애 등을 이유로 차별하지 않을 의무를 지닌다."},{"k":"hang","x":"② 본회의 회원은 회칙을 준수할 의무를 지닌다."},{"k":"hang","x":"③ 본회의 회원은 본회가 결정한 사항을 준수할 의무를 지닌다."},{"k":"hang","x":"④ 본회의 회원은 회비를 납부할 의무를 지닌다."},{"k":"hang","x":"⑤ 본회의 회원은 본회의 자산을 보호할 의무를 지닌다."}],"num":6,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a7","label":"제7조","title":"기구","paras":[{"k":"hang","x":"① 본회는 민주적이고 효율적인 운영을 통한 학생자치의 실현을 위하여 다음 각호의 의결기구, 집행기구, 산하기구, 독립기구 및 특별기구를 둔다."},{"k":"ho","x":"1. 의결기구: 학생총회, 학생대표자회, 학부운영위원회, 비상대책위원회"},{"k":"ho","x":"2. 집행기구: 학부 학생회장단, 집행위원회, 임시집행위원회"},{"k":"ho","x":"3. 산하기구: 반 학생회, 자치단체"},{"k":"ho","x":"4. 독립기구: 선거관리위원회, 투표관리위원회"},{"k":"ho","x":"5. 특별기구"},{"k":"hang","x":"② 본회의 각 기구는 제5조에 따른 회원의 권리가 내ㆍ외부적으로 침해받지 않도록 항상 노력하여야 하며, 회원의 권리가 침해될 때는 이를 적극적으로 수호하여야 한다."},{"k":"hang","x":"③ 본회의 각 기구는 본회 각 기구의 자산 및 자치공간 등을 확보하고 보호ㆍ관리하여야 한다."},{"k":"hang","x":"④ 본회의 각 기구는 서로 교류하고, 본회 사업에 협력하여야 한다."},{"k":"hang","x":"⑤ 본회의 각 기구는 회원의 개인정보를 보호하여야 한다."}],"num":7,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a8","label":"제8조","title":"학교 운영 참여","paras":[{"k":"hang","x":"① 본회는 본회의 활동에 관하여 학교 당국과의 협의 또는 조정이 필요한 경우 학교 운영에 적극적으로 참여하여 의견을 개진하고, 학교 당국에 자료 제출을 요청할 수 있다."},{"k":"hang","x":"② 본회는 다음 각호의 경우에 관하여 관련 진행 상황 및 결정 사항을 회원에게 공고하여야 한다."},{"k":"ho","x":"1. 본회의 활동에 관련된 회원의 징계 사항에 관해 회원을 변호할 필요가 있는 경우"},{"k":"ho","x":"2. 본회의 회원의 자치활동과 권익 보호가 필요한 경우"},{"k":"ho","x":"3. 자유전공학부 발전 방향 설정, 학제 개편, 학칙 개정 등의 임박하거나 이미 결정된 학교의 정책 및 결정 사항이 본회 회원의 이익에 중대한 변화를 일으키는 경우"},{"k":"ho","x":"4. 그 밖의 본회의 목적에 관련된 중요 사항"}],"num":8,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a9","label":"제9조","title":"대표자의 책임","paras":[{"k":"line","x":"학부 학생회장단, 학부운영위원 및 학생대표자회 대의원은 본회의 대표자로서 본회의 민주적이고 효율적인 운영과 각 기구의 협력을 통하여 그 운영 목적을 달성할 수 있도록 주어진 역할을 책임 있게 수행하여야 한다."}],"num":9,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a10","label":"제10조","title":"겸직 금지","paras":[{"k":"hang","x":"① 본회의 회원은 다음 각호의 직을 동시에 2개 이상 가질 수 없다."},{"k":"ho","x":"1. 학부 학생회장과 학부 부학생회장"},{"k":"ho","x":"2. 각 반 학생회장과 반 부학생회장"},{"k":"ho","x":"3. 각 반 고학번 대표와 반 신입생 대표"},{"k":"ho","x":"4. 각 자치단체장"},{"k":"ho","x":"5. 그 밖의 학생대표자회 대의원 자격이 부여될 수 있는 직책"},{"k":"hang","x":"② 반 학생회장은 집행위원의 직을 겸직하기 위해서는 학생대표자회의 의결로 허가를 받아야 한다."}],"num":10,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a11","label":"제11조","title":"당연퇴직","paras":[{"k":"hang","x":"① 다음 각호에 해당하는 자가 학칙에서 정한 사유 등에 따라 본회의 회원 자격을 잃게 되는 경우 그 시점부터 당연퇴직한다. 단, 정학 등의 사유로 회원 자격이 정지된 사람은 그러하지 아니한다."},{"k":"ho","x":"1.본회의 대표자"},{"k":"ho","x":"2.집행위원"},{"k":"ho","x":"3.특별기구 회원"},{"k":"ho","x":"4.제1호부터 제3호까지의 직에 준하는 자"},{"k":"ho","x":"5.그 밖의 본회의 회원 자격을 요건으로 하여 회칙ㆍ세칙 및 규칙에 따라 직위를 수행하는 자"},{"k":"hang","x":"② 제1항에 해당하는 사람이 제4조 제3항에 따른 절차 등을 통하여 회원 지위를 회복할 때는 그 회원 자격을 잃게 된 시점으로 소급하여 본회에서 수행한 직위의 경력을 인정한다. 단, 해당 경력의 소급 인정만으로는 그 기간에 있었던 사실상 또는 법률상 행위의 추인을 주장할 수 없다."},{"k":"hang","x":"③ 제10조를 위반한 자는 마지막으로 갖게 된 직을 제외한 나머지 직에서 당연퇴직한다. 단, 제10조 제1항 제1호의 직은 선후관계를 불문하고 그 직을 제외한 나머지 직에서 당연퇴직한다."}],"num":11,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a12","label":"제12조","title":"사무 처리","paras":[{"k":"hang","x":"① 본회는 간소화ㆍ표준화ㆍ정보화를 통하여 효율적으로 사무를 처리하여야 한다."},{"k":"hang","x":"② 정확과 신속을 기하고 책임의 소재를 분명히 하기 위하여 본회의 사무 처리와 대표자의 행위는 문서로 함을 원칙으로 한다."},{"k":"hang","x":"③ 본회에서 장기간에 걸쳐 반복적으로 사용하는 문서로서 정형화할 수 있는 문서는 특별한 사유가 없으면 서식으로 정하여 사용한다."},{"k":"hang","x":"④ 본회의 회칙ㆍ세칙 및 규칙에서 공고하도록 한 사항은 회원들이 해당 공고를 쉽게 접할 수 있도록 1개 이상의 오프라인 게시판 또는 온라인 플랫폼에 게시하여야 하며, 가시성이 확보되도록 공고의 모양을 정하여야 한다."},{"k":"hang","x":"⑤ 그 밖의 사무 처리에 관한 세부적인 사항은 학부운영위원회의 의결로 ｢고려대학교 총학생회 사무처리세칙｣을 준용한다."}],"num":12,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a13","label":"제13조","title":"기록물 관리","paras":[{"k":"hang","x":"① 본회의 모든 활동은 기록되고, 기록물이 각 활동의 근거가 되는 것을 원칙으로 한다."},{"k":"hang","x":"② 본회는 지속적이고 체계적인 기록물 관리를 위하여 적극 노력하여야 하며, 기록물 관리기관이 효율적으로 기록물을 관리할 수 있도록 지원하여야 한다."},{"k":"hang","x":"③ 기록물의 생산ㆍ수집 이후에는 임의로 수정, 훼손하거나 폐기할 수 없다. 단, 다음 각호에 해당하면 각호에서 정한 목적에 어긋나지 않는 범위 내에서 게시물을 수정할 수 있다."},{"k":"ho","x":"1. 회의록의 내용이 실제 발언과 부합하지 않은 것을 개의일로부터 7일 이내에 발견한 경우"},{"k":"ho","x":"2. 온라인 플랫폼에 올린 게시물의 탈ㆍ오자 수정이 필요한 경우"},{"k":"ho","x":"3. 온라인 플랫폼에 올린 게시물의 내용에 중대한 하자를 발견하여 하자의 치유를 위한 수정 및 비공개 조치가 필요한 경우"},{"k":"ho","x":"4. 온라인 플랫폼에 중복게시물을 올려 비공개 조치가 필요한 경우"},{"k":"hang","x":"④ 본회가 생산ㆍ수집하는 모든 기록물은 회원들에게 공개되어야 하고 본회의 행정 사무, 의사결정 및 학술 연구 등의 활동을 위하여 언제든지 참고할 수 있도록 투명하게 관리되어야 한다."},{"k":"hang","x":"⑤ 본회가 수집한 개인정보는 당사자의 동의를 얻었거나 명확한 근거를 가진 정당한 목적이 있을 때만 열람ㆍ활용할 수 있다."},{"k":"hang","x":"⑥ 본회의 회원 또는 학술적 목적 및 공익을 위하여 본회의 기록물을 활용하려는 자는 본회의 모든 기록물에 대한 접근권이 있으며 정보공개청구로 기록물을 열람ㆍ활용할 수 있다."},{"k":"hang","x":"⑦ 본회의 각 기구는 제6항에 따른 정보공개청구를 거부할 수 없다. 단, 다음 각호에 해당하면 학부운영위원회의 의결로 청구한 사항의 일부만 공개하도록 할 수 있다."},{"k":"ho","x":"1. 본회의 회원이 아닌 자가 정보 공개를 청구할 때"},{"k":"ho","x":"2. 특정 회원의 개인정보 유출이 우려될 때"},{"k":"ho","x":"3. 본회 회원의 이익에 심각한 감소를 초래할 때"},{"k":"ho","x":"4. 기타 공익적 목적이 있을 때"},{"k":"hang","x":"⑧ 그 밖의 기록물 관리에 관한 세부적인 사항은 학부운영위원회의 의결로 ｢고려대학교 총학생회 사무처리세칙｣을 준용한다."}],"num":13,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a14","label":"제14조","title":"준용","paras":[{"k":"hang","x":"① 본회는 각 의결기구의 의결로 본회 상위기구의 회칙, 세칙 및 규칙을 준용할 수 있다."},{"k":"hang","x":"② 제1항에도 불구하고 특별한 규정이 있는 경우 본회는 각 의결기구의 의결 없이도 본회 상위기구의 회칙, 세칙 및 규칙을 준용한다."}],"num":14,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제2장 의결기구"},{"t":"h","lv":3,"text":"제１절 통칙"},{"t":"art","id":"a15","label":"제15조","title":"기본이념","paras":[{"k":"line","x":"본회의 의결기구는 본회를 대표하는 의사를 결정하는 기구로서 민주적이고 공정하며 효율적인 절차에 따라 운영되어야 한다."}],"num":15,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a16","label":"제16조","title":"위계","paras":[{"k":"hang","x":"① 본회의 의결기구는 학생총회, 학생대표자회, 학부운영위원회 순으로 위계가 있다."},{"k":"hang","x":"② 하위 의결기구의 의사결정 내용은 상위 의결기구의 의사결정 내용과 합치되는 범위 내에서 효력을 지닌다."},{"k":"hang","x":"③ 하위 의결기구에서 의결할 수 있는 사항은 해당 의결기구보다 상위 의결기구에서도 의결할 수 있다."},{"k":"hang","x":"④ 하위 의결기구에서 가중된 요건으로 의결하여야 하는 사항을 상위 의결기구에서 의결하고자 할 때 특별한 규정이 없으면 일반의결요건으로 의결한다."}],"num":16,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a17","label":"제17조","title":"회기","paras":[{"k":"hang","x":"① 본회 의결기구의 회기는 다음 각호의 기간으로 나눈다."},{"k":"ho","x":"1. 제1회기: 2학기 종강일 다음 날부터 1학기 개강일 전날까지"},{"k":"ho","x":"2. 제2회기: 1학기 개강일부터 1학기 종강일까지"},{"k":"ho","x":"3. 제3회기: 1학기 종강일 다음 날부터 2학기 개강일 전날까지"},{"k":"ho","x":"4. 제4회기: 2학기 개강일부터 2학기 종강일까지"},{"k":"hang","x":"② 본회 의결기구의 회기는 원활한 운영을 위하여 필요한 경우 다음 각호의 기간으로 표현할 수 있다."},{"k":"ho","x":"1. 상반기: 금년도 제2회기 및 금년도 제3회기"},{"k":"ho","x":"2. 하반기: 금년도 제4회기 및 익년도 제1회기"}],"num":17,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a18","label":"제18조","title":"의장","paras":[{"k":"hang","x":"① 본회 의결기구의 의장은 학부 학생회장으로 함을 원칙으로 한다."},{"k":"hang","x":"② 의장은 본회 의결기구를 대표하고 의사를 정리하며, 질서를 유지하고 사무를 감독한다."},{"k":"hang","x":"③ 의장은 회칙에 따라 공정하고 효율적으로 회의를 진행하여야 한다."}],"num":18,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a19","label":"제19조","title":"학부 부학생회장의 의장 직무대리","paras":[{"k":"line","x":"학부 부학생회장은 학부 학생회장이 권한을 위임하거나 사고일 때에 학부 학생회장의 직무를 대행한다."}],"num":19,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a20","label":"제20조","title":"임시의장","paras":[{"k":"hang","x":"① 다음 각호 중 하나에 해당하는 사유로 학부 학생회장단이 의장에서 물러나면 각 의결기구는 학부운영위원 중 1인을 임시의장으로 선출한다."},{"k":"ho","x":"1.학부 학생회장단 전원이 사고일 때"},{"k":"ho","x":"2.학부 학생회장단에 대한 탄핵안이 상정되거나 발의되었을 때"},{"k":"ho","x":"3.제21조에 따라 의장이 물러날 때"},{"k":"hang","x":"② 학생총회 또는 학생대표자회에 대한 소집요구가 있을 때 제1항 제1호 및 제2호에 해당하면 다음 각호 중 하나에 따라 인준받은 학부운영위원이 해당 의결기구의 회의를 소집한다."},{"k":"ho","x":"1. 학생총회: 학생대표자회에서 인준"},{"k":"ho","x":"2. 학생대표자회: 학부운영위원회에서 인준"},{"k":"hang","x":"③ 제2항에도 불구하고 제31조 제1항 제3호에 따른 학생총회의 소집요구가 있을 때 제1항 제1호에 해당하면 학부운영위원회에서 인준받은 학부운영위원이 학생총회를 소집한다."},{"k":"hang","x":"④ 학생총회 또는 학생대표자회는 개의 직후 의결로 제2항 및 제3항에 따라 회의를 소집한 임시의장을 재인준한다."},{"k":"hang","x":"⑤ 학부운영위원회에 대한 소집요구가 있을 때 또는 특별한 규정으로 인하여 학부운영위원회를 소집하여야 할 때 제1항 제1호 및 제2호에 해당하면 학부운영위원회 재적 위원 3분의 2 이상의 출석과 출석 위원 3분의 2 이상의 찬성으로 회의를 개의하며, 학부운영위원 중 호선되는 1인을 임시의장으로 한다."}],"num":20,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a21","label":"제21조","title":"의장 직무의 제한","paras":[{"k":"hang","x":"① 의장은 학생총회와 학생대표자회를 주재하는 동안 토론에 참여할 수 없으며, 토론에 참여하고자 한다면 해당 안건의 심의가 끝날 때까지 의장에서 물러나야 한다. 단, 제안 설명, 질의와 정보요구는 그러하지 아니한다."},{"k":"hang","x":"② 학부 학생회장단이 의장일 때 의장은 학생총회와 학생대표자회에서 다음 각호에 해당하는 안건의 심의ㆍ의결에 관하여서는 해당 안건의 심의가 끝날 때까지 의장에서 물러나야 한다."},{"k":"ho","x":"1. 의장 개인과 자기 관련성이 있는 안건"},{"k":"ho","x":"2. 집행위원장과 집행위원의 해임 안건"},{"k":"ho","x":"3. 학부 학생회장단과 집행위원회의 결정 사항 변경에 관한 안건"}],"num":21,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a22","label":"제22조","title":"사무ㆍ재정","paras":[{"k":"hang","x":"① 의결기구의 사무 처리는 집행위원회가 담당하며, 학부운영위원은 이에 최대한 협조할 의무 및 감시ㆍ감독할 의무를 지닌다."},{"k":"hang","x":"② 집행위원회는 속기의 방법으로 회의록을 작성하고 다음 각호의 사항을 기재하여야 한다."},{"k":"ho","x":"1. 회의 장소"},{"k":"ho","x":"2. 개의ㆍ정회 및 산회의 일시"},{"k":"ho","x":"3. 개의 당시와 안건 의결 당시의 출석 구성원 명단"},{"k":"ho","x":"4. 부의 안건의 제목 및 내용"},{"k":"ho","x":"5. 발언자와 의사 표명의 내용"},{"k":"ho","x":"6. 표결 결과 (기명투표의 경우 각 구성원의 표결 사항을 기재)"},{"k":"ho","x":"7. 의장 또는 각 의결기구가 필요하다고 인정하는 사항"},{"k":"hang","x":"③ 의장은 개의일로부터 3일 이내에 제2항의 회의록을 공개하고 회의 결과를 공고함을 원칙으로 한다. 단, 필요한 경우 그 기한을 7일까지 연장할 수 있다."},{"k":"hang","x":"④ 본회는 의결기구의 원활한 운영을 위한 재원을 마련하여야 한다."}],"num":22,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a23","label":"제23조","title":"긴급한 사항","paras":[{"k":"hang","x":"① “긴급한 사항”이란 회의 소집 과정을 생략해서라도 긴급하게 회의를 소집하여야 할 사항이거나, 그렇게 하는 것이 더 효율적이라고 판단되는 사항을 말한다."},{"k":"hang","x":"② 각 의결기구의 의장은 긴급한 사항이 있을 때 이 회칙이 정하는 바에 따라 소집요구 없이도 학생총회와 학생대표자회를 소집할 수 있다."},{"k":"hang","x":"③ 제2항에 따라 회의가 소집되는 경우 해당 의결기구는 개의 직후 긴급한 사항의 성립 여부에 관하여 심의한다. 긴급한 사항은 다음 중 하나로 성립되며, 긴급한 사항이 성립되지 않았을 때 해당 회의는 즉시 산회한다."},{"k":"ho","x":"1.학생총회: 출석 회원 과반수의 찬성"},{"k":"ho","x":"2.학생대표자회: 출석 대의원 3분의 2 이상의 찬성"},{"k":"hang","x":"④ 긴급한 사항을 다음 각호의 목적만으로 주장하는 것은 허용되지 아니한다."},{"k":"ho","x":"1. 소집 요건을 완화하고자 하는 목적"},{"k":"ho","x":"2. 공고 기간ㆍ절차를 단축하고자 하는 목적"},{"k":"hang","x":"⑤ 제2항에도 불구하고 가중된 요건으로 의결하여야 하는 안건을 심의하는 회의는 긴급한 사항으로 소집할 수 없다."}],"num":23,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a24","label":"제24조","title":"안건의 발의","paras":[{"k":"hang","x":"① 안건 발의는 각 의결기구에서 정한 발의 요건에 따른다."},{"k":"hang","x":"② 정기회의를 제외한 회의에서 소집공고부터 산회 전까지의 안건 발의는 허용되지 아니한다."},{"k":"hang","x":"③ 정기회의의 소집공고부터 산회 전까지 발의된 추가 안건에 관하여서는 각 의결기구의 의결로 안건의 상정 여부를 결정한다."}],"num":24,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a25","label":"제25조","title":"연서의 심의","paras":[{"k":"hang","x":"① 의결기구의 소집요구 및 안건 발의를 위한 연서는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식을 준용한다."},{"k":"hang","x":"② 학생총회 또는 학생대표자회에 대한 소집요구 및 안건 발의가 연서에 따라 이루어졌을 때 특별한 규정이 없는 한 학부운영위원회는 지체 없이 회의를 소집하여 연서에서 형식상의 결함을 심의한다."},{"k":"hang","x":"③ 학부운영위원회의 소집요구 및 안건 발의가 연서에 따라 이루어졌을 때 학부운영위원회는 개의 직후 연서에서 형식상의 결함을 심의한다."},{"k":"hang","x":"④ 각 의결기구는 연서의 서식 및 기재 정보가 ｢고려대학교 총학생회 사무처리세칙｣에 따른 규정과 맞지 않으면 연서가 무효하다고 볼 수 있다. 이때 해당 의결기구는 그 무효 판단의 근거를 회원에게 자세히 설명하기 위하여 노력하여야 한다."},{"k":"hang","x":"⑤ 의결기구의 구성원과 방청인은 연서에 기재된 개인정보에 대하여 비밀을 유지할 의무를 지닌다."}],"num":25,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a26","label":"제26조","title":"안건의 의결","paras":[{"k":"hang","x":"① 각 의결기구는 특별한 규정이 없는 한 재적 구성원 과반수의 출석과 출석 구성원 과반수의 찬성으로 안건을 의결한다."},{"k":"hang","x":"② 다음 각호 중 어느 하나에 해당하면 모두 부결된 것으로 된다."},{"k":"ho","x":"1. 가부동수일 때"},{"k":"ho","x":"2. 과반의 의견이 없을 때"},{"k":"ho","x":"3. 기권이 과반수일 때"},{"k":"hang","x":"③ 의결 요건의 기준이 되는 출석 구성원 수는 각 안건의 의결 당시를 기준으로 계산한다."},{"k":"hang","x":"④ 의결기구의 의결권은 모든 구성원이 평등하게 가지며, 직접 출석하여 행사하여야 한다."}],"num":26,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a27","label":"제27조","title":"방청ㆍ발언권","paras":[{"k":"hang","x":"① 본회의 회원은 각 의결기구를 방청할 수 있다."},{"k":"hang","x":"② 본회의 회원은 각 의결기구에서 발언할 수 있는 권리를 가진다."},{"k":"hang","x":"③ 의장은 질서유지 및 효율적인 의사 진행을 위하여 방청인 수를 제한하거나 회원의 발언권을 제한할 수 있으며, 회의장 안의 질서를 현저히 방해하는 방청인의 퇴장을 명할 수 있다."},{"k":"hang","x":"④ 의결기구의 구성원과 방청인의 자리는 구분되도록 배치한다."}],"num":27,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a28","label":"제28조","title":"회의진행세칙","paras":[{"k":"line","x":"그 밖의 의결기구의 회의 진행에 관한 사항은 ｢고려대학교 총학생회 회의진행세칙｣을 준용한다."}],"num":28,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제２절 학생총회"},{"t":"art","id":"a29","label":"제29조","title":"지위","paras":[{"k":"line","x":"학생총회는 본회의 최고의결기구이다."}],"num":29,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a30","label":"제30조","title":"구성","paras":[{"k":"line","x":"학생총회는 본회의 회원 전원으로 구성된다."}],"num":30,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a31","label":"제31조","title":"소집","paras":[{"k":"hang","x":"① 학생총회는 다음 각호 중 하나에 따라 의장이 소집한다."},{"k":"ho","x":"1. 학생대표자회의 소집요구"},{"k":"ho","x":"2. 학생대표자회의 재적 대의원 과반수의 연서에 따른 소집요구"},{"k":"ho","x":"3. 본회의 회원 50명 이상의 연서에 따른 소집요구"},{"k":"ho","x":"4. 제67조 제2항에 따른 학부 학생회장단 탄핵안 부의"},{"k":"hang","x":"② 학부운영위원회는 연서에 따른 소집요구가 있으면 제25조 제2항에 따라 연서를 심의하고, 결함이 없는 경우 지체 없이 학생총회 개의일을 결정한다. 이때 개의일은 소집요구 서식에 기재된 개의 희망일로 함을 원칙으로 하며, 변경하더라도 개의 희망일과 7일 이상의 차이가 있게 정할 수 없다."},{"k":"hang","x":"③ 학생총회 의장은 제1항에도 불구하고 제23조 제2항에 따라 긴급한 사항으로 학부운영위원회의 의결을 거쳐 학생총회를 소집할 수 있다."}],"num":31,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a32","label":"제32조","title":"소집공고","paras":[{"k":"hang","x":"① 학생총회 의장은 학생총회의 소집을 개의일 5일 전까지 공고하여야 한다. 단, 제31조 제3항에 따른 소집은 그러하지 아니한다."},{"k":"hang","x":"② 공고문에는 다음 각호의 사항을 명시하여야 한다."},{"k":"ho","x":"1. 회의 시작 일시"},{"k":"ho","x":"2. 회의 장소"},{"k":"ho","x":"3. 안건 및 안건에 대한 설명"}],"num":32,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a33","label":"제33조","title":"자료의 사전 배포","paras":[{"k":"hang","x":"① 학생총회 의장은 학생총회 개의 5일 전까지 제출된 안건과 그에 관한 설명 등이 포함된 자료집을 회원들에게 배포하여야 한다."},{"k":"hang","x":"② 자료집의 배포는 책자 형태로 제작하여 비치하는 방법 또는 전산화된 형태의 문서로 제작하여 온라인에 게시하는 방법으로 한다."}],"num":33,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a34","label":"제34조","title":"개의ㆍ의결요건","paras":[{"k":"hang","x":"① 학생총회는 본회의 회원 80명 이상의 출석으로 개의하고 출석 회원 과반수의 찬성으로 의결한다."},{"k":"hang","x":"② 학부 학생회장단에 대한 탄핵안은 출석 회원 3분의 2 이상의 찬성으로 의결한다."}],"num":34,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a35","label":"제35조","title":"표결방법","paras":[{"k":"hang","x":"① 표결은 기명으로 함을 원칙으로 한다."},{"k":"hang","x":"② 중요한 안건으로서 의장 또는 회원이 제의하여 학생총회가 의결하면 표결을 무기명으로 할 수 있다."},{"k":"hang","x":"③ 학부 학생회장단에 대한 탄핵안은 반드시 무기명투표로 표결하여야 한다."}],"num":35,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a36","label":"제36조","title":"안건","paras":[{"k":"hang","x":"① 학생총회는 다음 각호의 안건을 심의ㆍ의결한다."},{"k":"ho","x":"1. 학생대표자회가 소집요구와 함께 상정한 안건"},{"k":"ho","x":"2. 학생대표자회의 재적 대의원 과반수의 연서에 따른 소집요구와 함께 발의한 안건"},{"k":"ho","x":"3. 회원 50명 이상의 연서에 따른 소집요구와 함께 발의한 안건"},{"k":"ho","x":"4. 제67조 제2항에 따라 부의된 학부 학생회장단 탄핵안"},{"k":"hang","x":"② 학생총회는 본회를 폐지하는 의결을 할 수 없다."}],"num":36,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a37","label":"제37조","title":"안건 위임","paras":[{"k":"hang","x":"① 안건을 처리하지 못한 채로 회의의 산회가 결정되면 처리하지 못한 안건은 출석 회원 3분의 2 이상의 찬성으로 학생대표자회의에 위임할 수 있다."},{"k":"hang","x":"② 학부 학생회장단 탄핵안은 위임할 수 없으며, 학생총회에 의하지 않고서는 출석 회원 3분의 2 이상의 찬성으로 학생총투표에서 처리할 수 있다."},{"k":"hang","x":"③ 개의하지 못한 학생총회에 발의된 안건은 위임하지 아니하고 폐기한다."}],"num":37,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제３절 학생총투표"},{"t":"art","id":"a38","label":"제38조","title":"지위","paras":[{"k":"hang","x":"① 학생총투표는 본회의 중대한 사항을 회원의 의사를 물어 결정하기 위한 투표이다."},{"k":"hang","x":"② 학생총투표를 통한 의결은 학생총회의 의결과 같은 효력을 가진다."}],"num":38,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a39","label":"제39조","title":"투표권","paras":[{"k":"hang","x":"① 본회의 정회원은 학생총투표의 투표권을 가지며, 투표권자 총수에 포함된다."},{"k":"hang","x":"② 제1항에도 불구하고 본회의 국제 회원은 투표권을 행사한 경우에만 투표권자 총수에 포함된다."},{"k":"hang","x":"③ 본회의 준회원ㆍ수료회원은 투표권을 가지며, 투표권을 행사한 경우에만 투표권자 총수에 포함된다."}],"num":39,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a40","label":"제40조","title":"시행","paras":[{"k":"line","x":"학생총투표는 다음 각호 중 하나에 따라 학생총회 의장이 시행한다."},{"k":"ho","x":"1. 학생총회의 시행 결정"},{"k":"ho","x":"2. 학생대표자회의 시행 결정"},{"k":"ho","x":"3. 제67조 제2항에 따른 학부 학생회장단 탄핵안 부의"}],"num":40,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a41","label":"제41조","title":"시행 공고","paras":[{"k":"hang","x":"① 학생총회 의장은 학생총투표의 시행을 투표일 5일 전까지 공고하여야 한다."},{"k":"hang","x":"② 공고문에는 다음 각호의 사항을 명시하여야 한다."},{"k":"ho","x":"1. 학생총투표 시행 일시"},{"k":"ho","x":"2. 학생총투표 투표소 설치 장소"},{"k":"ho","x":"3. 안건 및 안건에 대한 설명"}],"num":41,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a42","label":"제42조","title":"성립ㆍ의결요건","paras":[{"k":"hang","x":"① 학생총투표는 제39조에 따라 결정된 투표권자 총수 4분의 1 이상의 투표로 성립하고, 유효투표의 과반수 찬성으로 의결한다."},{"k":"hang","x":"② 성립 여부를 판단하기 위한 투표율의 계산은 명부상 총 투표자 수를 기준으로 한다. 단, 부정한 목적으로 명부를 부실하게 기재하였을 때는 그러하지 아니하다."}],"num":42,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a43","label":"제43조","title":"투표관리위원회","paras":[{"k":"hang","x":"① 투표관리위원회는 학생총투표와 관련된 모든 업무를 총괄한다."},{"k":"hang","x":"② 그 밖의 투표관리위원회에 관한 자세한 사항은 제156조부터 제160조까지에 따른다."}],"num":43,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a44","label":"제44조","title":"투표 기간","paras":[{"k":"hang","x":"① 투표 기간은 3일의 범위에서 투표관리위원회가 정한다."},{"k":"hang","x":"② 투표관리위원회는 투표 기간이 종료하였음에도 투표율이 제42조에 따른 성립 요건을 넘지 않았으면 투표 기간을 2일의 범위에서 1회 연장할 수 있다."}],"num":44,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a45","label":"제45조","title":"투표 방법","paras":[{"k":"hang","x":"① 투표는 기표 방법으로 함을 원칙으로 한다."},{"k":"hang","x":"② 투표관리위원회는 회원들의 쉬운 투표 참여 혹은 부재중인 자의 투표 참여를 위하여 우편, 온라인, 모바일 그 밖의 특수한 투표 방법을 사용할 수 있다."},{"k":"hang","x":"③ 투표관리위원회는 특수한 투표 방법의 시행 여부, 대상, 방식 및 운영 등에 관한 사항을 규칙으로 정한다."}],"num":45,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a46","label":"제46조","title":"결과 공고","paras":[{"k":"hang","x":"① 투표관리위원회는 학생총투표가 종료되어 개표가 완료되면 지체 없이 투표율과 개표 결과를 공고한다."},{"k":"hang","x":"② 제1항에 따라 공고하는 최종 투표율은 총 투표용지 수를 기준으로 계산한다."}],"num":46,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a47","label":"제47조","title":"무효 처리","paras":[{"k":"hang","x":"① 한 투표소의 명부상 투표자 수와 투표함의 투표용지 수의 차이가 명부상 투표자 수 대비 3%를 넘으면 해당 투표함의 투표는 무효로 하며, 투표관리위원회는 해당 투표함의 투표용지를 모두 무효표로 처리한다. 단, 명부상 투표자 수가 100 이하일 때, 오차는 3까지 허용한다."},{"k":"hang","x":"② 명부상 총 투표자 수와 총 투표용지 수의 차이가 명부상 총 투표자 수 대비 3%를 넘으면 해당 학생총투표는 무효가 된다."}],"num":47,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a48","label":"제48조","title":"준용","paras":[{"k":"line","x":"그 밖의 학생총투표 관련 세부 사항은 ｢고려대학교 자유전공학부 학부ㆍ반 선거시행세칙｣의 투표ㆍ개표 관련 규정을 준용한다."}],"num":48,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제4절 학생대표자회"},{"t":"h","lv":4,"text":"제1관 통칙"},{"t":"art","id":"a49","label":"제49조","title":"지위","paras":[{"k":"line","x":"학생대표자회는 본회와 본회 산하기구의 대표자를 대의원으로 하는 학생총회 다음의 의결기구이다."}],"num":49,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a50","label":"제50조","title":"정기회의","paras":[{"k":"hang","x":"① 학생대표자회 정기회의는 매 학기 1회 개의한다."},{"k":"hang","x":"② 학생대표자회 정기회의는 각각 5월, 11월에 개의하는 것을 원칙으로 한다."},{"k":"hang","x":"③ 학생대표자회 의장은 대의원과 협의하여 해당 학기 학생대표자회 정기회의 개의일을 확정 및 공고하여야 한다."}],"num":50,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a51","label":"제51조","title":"임시회의","paras":[{"k":"hang","x":"① 학생대표자회 임시회의는 다음 각호 중 하나에 따라 의장이 소집한다."},{"k":"ho","x":"1. 학부운영위원회의 소집요구"},{"k":"ho","x":"2. 학부운영위원회 재적 위원 과반수의 연서에 따른 소집요구"},{"k":"ho","x":"3. 학생대표자회 재적 대의원 3분의 1 이상의 연서에 따른 소집요구"},{"k":"ho","x":"4. 본회의 회원 30명 이상의 연서에 따른 소집요구"},{"k":"ho","x":"5. 제37조 제1항에 따른 학생총회의 안건 위임"},{"k":"ho","x":"6. 제108조 제1항에 따라 발의된 학생회장단 사퇴 허가 요청"},{"k":"ho","x":"7. 제109조에 따라 발의된 학부 학생회장단 탄핵안의 학생총회ㆍ학생총투표 부의"},{"k":"ho","x":"8. 제194조에 따른 회칙 개정안 발의"},{"k":"ho","x":"9. 제202조 제3항에 따른 세칙 제정안ㆍ개정안ㆍ폐지안 발의"},{"k":"hang","x":"② 학부운영위원회는 연서에 따른 소집요구가 있으면 제25조 제2항에 따라 연서를 심의하고, 결함이 없는 경우 지체 없이 학생대표자회 개의일을 결정한다. 이때 개의일은 소집요구 서식에 기재된 개의 희망일로 함을 원칙으로 하며, 변경하더라도 개의 희망일과 5일 이상의 차이가 있게 정할 수 없다."},{"k":"hang","x":"③ 학생대표자회 의장은 제1항에도 불구하고 제23조 제2항에 따라 긴급한 사항으로 학생대표자회를 소집할 수 있다."}],"num":51,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":4,"text":"제2관 대의원"},{"t":"art","id":"a52","label":"제52조","title":"대의원","paras":[{"k":"hang","x":"① 다음 각호에 해당하는 사람은 학생대표자회 대의원이 된다."},{"k":"ho","x":"1. 학부 학생회장과 학부 부학생회장"},{"k":"ho","x":"2. 각 반 학생회의 학생회장, 부학생회장, 신입생 대표 1인 및 고학번 대표 1인"},{"k":"ho","x":"3. 각 자치단체장"},{"k":"hang","x":"② 선거 미시행 등의 이유로 대의원이 공석일 때는 사고로 하고 재적에서 제외한다. 이때 해당 기구는 발언권을 가지는 대표를 파견할 수 있다."},{"k":"hang","x":"③ 제1항 제3호에 해당하는 사람이 학생대표자회에 정당한 사유로 출석하지 못할 때는 개의 직후 인준을 받아 해당 기구의 부 대표자가 대신 의결권을 가질 수 있다."},{"k":"hang","x":"④ 특별기구장은 제59조와 제60조에 따른 소집공고 및 사전 배포된 자료집을 근거로 학생대표자회에 제출된 안건에 해당 특별기구와의 관련성이 있다고 판단하면 학생대표자회 개의 1일 전까지 학생대표자회 의장에게 대의원직을 신청할 수 있다. 해당 특별기구장의 대의원직 부여는 학생대표자회 개의 직후 출석 대의원 3분의 2 이상의 찬성으로 의결한다."},{"k":"hang","x":"⑤ 제4항에 따라 부여된 대의원직은 해당 학생대표자회가 산회하면 소멸한다."}],"num":52,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a53","label":"제53조","title":"의무","paras":[{"k":"hang","x":"① 대의원은 대의원으로서의 품위를 유지하여야 한다."},{"k":"hang","x":"② 대의원은 회칙을 준수하여야 한다."},{"k":"hang","x":"③ 대의원은 양심에 따라 직무를 행하고 회의에 성실히 참여하여야 한다."},{"k":"hang","x":"④ 대의원은 자신이 소속된 기구의 의사를 충분히 수렴하여 의사 과정 전반에서 기구를 대표하는 의사를 표명하여야 한다."}],"num":53,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a54","label":"제54조","title":"결석","paras":[{"k":"hang","x":"① 대의원이 사고로 인하여 학생대표자회에 출석하지 못하게 되거나 못한 경우 결석계를 의장에게 제출하여야 한다."},{"k":"hang","x":"② 결석계의 제출은 학생대표자회 개의일로부터 3일 후까지 하는 것을 원칙으로 한다."},{"k":"hang","x":"③ 결석계의 작성은 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식을 준용한다."},{"k":"hang","x":"④ 학부운영위원회는 결석의 사유를 참작하여 제출된 결석계를 심의하고 의결로 해당 결석을 인정한다."},{"k":"hang","x":"⑤ 학부운영위원회는 결석계를 제출하지 않았거나 결석이 인정되지 않은 대의원의 경우, 대자보 등을 통하여 결석 사실을 공개할 수 있다."}],"num":54,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":4,"text":"제3관 특별위원회"},{"t":"art","id":"a55","label":"제55조","title":"특별위원회","paras":[{"k":"hang","x":"① 학생대표자회는 특수한 목적을 달성하기 위하여 의결로 학생대표자회 대의원 중 일부를 구성원으로 하는 특별위원회를 둘 수 있다."},{"k":"hang","x":"② 학생대표자회는 제1항에 따른 특별위원회를 구성할 때 다음 각호의 사항을 정하여야 한다. 단, 제3호의 경우 학생대표자회의 의결로 연장할 수 있다."},{"k":"ho","x":"1.소관 사항"},{"k":"ho","x":"2.구성원"},{"k":"ho","x":"3.활동기간"},{"k":"hang","x":"③ 특별위원회의 위원장은 위원 중 학생대표자회에서 임명한 자로 한다."},{"k":"hang","x":"④ 학생대표자회는 다음 각호에 해당하면 출석 대의원 3분의 2 이상의 찬성으로 특별위원회의 활동을 종료시킬 수 있다."},{"k":"ho","x":"1.특별위원회의 활동 목적이 달성된 경우"},{"k":"ho","x":"2.특별위원회의 활동 필요성이 없어진 경우"},{"k":"ho","x":"3.특별위원회의 활동이 상당한 기간 진행되지 않은 경우"},{"k":"ho","x":"4.그 밖의 특별위원회 활동을 종료시킬 만한 사유가 있는 경우"},{"k":"hang","x":"⑤ 특별위원회는 다음 각호에 해당하면 해산한다."},{"k":"ho","x":"1.활동기간이 종료된 경우"},{"k":"ho","x":"2.제4항에 따라 활동이 종료된 경우"},{"k":"hang","x":"⑥ 특별위원회는 활동 목적의 달성에 관하여 필요한 경우 대의원이 아닌 본회의 회원 중에서 자문위원을 둘 수 있다. 단, 제56조와 제57조는 그러하지 아니한다."}],"num":55,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a56","label":"제56조","title":"감사위원회","paras":[{"k":"hang","x":"① 학생대표자회는 본회 집행기구ㆍ산하기구ㆍ독립기구 및 특별기구의 사업 전반을 감사하기 위하여 감사위원회를 둘 수 있다."},{"k":"hang","x":"② 감사위원회는 학생대표자회의 의결에 따라 감사 활동을 진행한 후 그 결과를 우선적으로 학부운영위원회에, 최종적으로 학생대표자회 정기회의에 보고하여야 한다."}],"num":56,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a57","label":"제57조","title":"징계위원회","paras":[{"k":"hang","x":"① 학생대표자회는 다음 각호에 해당하는 대상이 회칙ㆍ세칙ㆍ규칙을 위반할 때 징계에 관한 사항을 심사하기 위하여 징계위원회를 둘 수 있다."},{"k":"ho","x":"1. 집행위원"},{"k":"ho","x":"2. 학생대표자회 대의원"},{"k":"ho","x":"3. 산하기구"},{"k":"ho","x":"4. 독립기구"},{"k":"ho","x":"5. 특별기구"},{"k":"ho","x":"6. 제1호 및 제2호에 해당하지 않는 본회의 회원"},{"k":"hang","x":"② 징계위원회는 제1항 제1호, 제2호 및 제6호에 해당하는 대상의 징계에 관하여서는 학생대표자회의 의결과 동등한 효력을 갖는 의결을 할 수 있다."},{"k":"hang","x":"③ 징계위원회는 징계에 관하여 심사한 후 그 결과를 학생대표자회에 보고하여야 한다. 단, 제1항 제1호, 제2호 및 제6호에 해당하는 대상의 징계에 관한 사항은 징계위원회의 의결로 보고하지 않을 수 있다."},{"k":"hang","x":"④ 그 밖의 징계위원회에 관한 사항은 ｢고려대학교 자유전공학부 징계세칙｣으로 정한다."}],"num":57,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a58","label":"제58조","title":"활동","paras":[{"k":"hang","x":"① 특별위원회는 활동 목적에 직ㆍ간접적으로 필요하다고 판단되면 학생대표자회의 출석 3분의 2 이상의 찬성으로 제55조 제2항 제1호의 소관 사항을 벗어난 활동을 할 수 있다."},{"k":"hang","x":"② 특별위원회는 본회의 회원 및 각 기구에 출석 또는 자료 제출을 요청할 수 있다."},{"k":"hang","x":"③ 특별위원회는 집행위원회에 협조를 요청할 수 있다."}],"num":58,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":4,"text":"제4관 회의"},{"t":"art","id":"a59","label":"제59조","title":"소집공고","paras":[{"k":"hang","x":"① 학생대표자회 의장은 학생대표자회의 소집을 개의일 3일 전까지 공고하여야 한다. 단, 제51조 제3항에 따른 소집은 그러하지 아니한다."},{"k":"hang","x":"② 공고문에는 다음 각호의 사항을 명시하여야 한다."},{"k":"ho","x":"1. 회의 시작 일시"},{"k":"ho","x":"2. 회의 장소"},{"k":"ho","x":"3. 안건 및 안건에 대한 설명"}],"num":59,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a60","label":"제60조","title":"자료의 사전 배포","paras":[{"k":"hang","x":"① 학생대표자회 의장은 학생대표자회 정기회의 개의 3일 전까지 다음 각호의 사항이 포함된 자료집을 회원들에게 배포하여야 한다."},{"k":"ho","x":"1.정기회의에 제출된 안건 및 그에 관한 설명"},{"k":"ho","x":"2.집행위원회 등의 보고 및 인준 사항"},{"k":"ho","x":"3.각 기구의 학생회비 예산안 및 결산"},{"k":"ho","x":"4.그 밖의 정기회의에서 다루는 사항으로 사전 공고가 필요한 사항"},{"k":"hang","x":"② 자료집의 배포는 책자 형태로 제작하여 비치하는 방법 또는 전산화된 형태의 문서로 제작하여 온라인에 게시하는 방법으로 한다."}],"num":60,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a61","label":"제61조","title":"개의ㆍ의결요건","paras":[{"k":"hang","x":"① 학생대표자회는 특별한 규정이 없는 한 재적 대의원 과반수 출석으로 개의하고 출석 대의원 과반수의 찬성으로 의결한다."},{"k":"hang","x":"② 다음 각호의 사항은 재적 대의원 3분의 2 이상의 출석과 출석 대의원 3분의 2 이상의 찬성으로 의결한다."},{"k":"ho","x":"1. 제67조 제2항의 학부 학생회장단 탄핵안의 학생총회ㆍ학생총투표 부의에 관한 사항"},{"k":"ho","x":"2. 제74조 제1항의 회칙 개정에 관한 사항"},{"k":"hang","x":"③ 다음 각호의 사항은 재적 대의원 과반수 출석과 출석 대의원 3분의 2 이상의 찬성으로 의결한다."},{"k":"ho","x":"1. 제68조 제2항의 집행위원 해임에 관한 사항"},{"k":"ho","x":"2. 제72조 제1항의 징계에 관한 사항"},{"k":"ho","x":"3. 제73조 제3항의 학부 학생회비 인상ㆍ인하에 관한 사항"},{"k":"ho","x":"4. 제74조 제2항의 세칙의 제정ㆍ개정ㆍ폐지에 관한 사항"}],"num":61,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a62","label":"제62조","title":"표결방법","paras":[{"k":"hang","x":"① 표결은 기명으로 함을 원칙으로 한다."},{"k":"hang","x":"② 의장 또는 대의원이 제의하여 학생대표자회가 의결하면 표결을 전자투표에 의한 기록표결을 시행할 수 있다."},{"k":"hang","x":"③ 중요한 안건으로서 의장 또는 대의원이 제의하여 학생대표자회가 의결하면 표결을 무기명으로 할 수 있다."},{"k":"hang","x":"④ 다음 각호의 사항을 의결할 때는 반드시 기명투표로 표결하여야 한다."},{"k":"ho","x":"1.제74조 제1항의 회칙 개정에 관한 사항"},{"k":"ho","x":"2.제74조 제2항의 세칙 제정ㆍ개정ㆍ폐지에 관한 사항"},{"k":"hang","x":"⑤ 다음 각호의 사항을 의결할 때는 반드시 무기명투표로 표결하여야 한다."},{"k":"ho","x":"1.제67조 제2항의 학부 학생회장단 탄핵안에 관한 사항"},{"k":"ho","x":"2.제68조 제2항의 집행위원 해임에 관한 사항"},{"k":"ho","x":"3.제72조 제1항의 징계에 관한 사항"},{"k":"ho","x":"4.제73조 제2항의 학부 학생회비 지급에 관한 사항"},{"k":"hang","x":"⑥ 의장은 안건에 대한 이의가 있는지 물어서 이의가 없다고 인정하면 가결되었음을 선포할 수 있다. 단, 이의가 있을 때 또는 무기명으로 표결할 때는 반드시 표결하여야 한다."}],"num":62,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a63","label":"제63조","title":"안건","paras":[{"k":"line","x":"학생대표자회는 다음 각호의 안건을 심의ㆍ의결한다."},{"k":"ho","x":"1. 학부운영위원회가 상정한 안건"},{"k":"ho","x":"2. 학부운영위원회 재적 위원 과반수의 연서에 따른 소집요구와 함께 발의한 안건"},{"k":"ho","x":"3. 학생대표자회 재적 대의원 3분의 1 이상의 연서에 따른 소집요구와 함께 발의한 안건"},{"k":"ho","x":"4. 본회의 회원 30명 이상의 연서에 따라 발의된 안건"},{"k":"ho","x":"5. 제37조 제1항에 따라 학생총회에서 위임된 안건"},{"k":"ho","x":"6. 제108조 제1항에 따라 발의된 학부 학생회장단 사퇴 허가 안건"},{"k":"ho","x":"7. 제109조에 따라 발의된 학부 학생회장단 탄핵안의 학생총회ㆍ학생총투표 부의에 관한 안건"},{"k":"ho","x":"8. 제194조에 따라 발의된 회칙 개정안"},{"k":"ho","x":"9. 제202조 제3항에 따라 발의된 세칙 제정안ㆍ개정안ㆍ폐지안"}],"num":63,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a64","label":"제64조","title":"안건 위임","paras":[{"k":"hang","x":"① 안건을 처리하지 못한 채로 회의의 산회가 결정되면 처리하지 못한 안건은 출석 대의원 3분의 2 이상의 찬성으로 학부운영위원회에 위임할 수 있다."},{"k":"hang","x":"② 다음 각호의 안건은 위임할 수 없다."},{"k":"ho","x":"1. 제67조 제2항의 학부 학생회장단 탄핵안에 관한 사항"},{"k":"ho","x":"2. 제68조 제2항의 집행위원 해임에 관한 사항"},{"k":"ho","x":"3. 제72조 제1항의 징계에 관한 사항"},{"k":"ho","x":"4. 제73조 제3항의 학부 학생회비의 인상ㆍ인하에 관한 사항"},{"k":"ho","x":"5. 제74조 제1항의 회칙 개정에 관한 사항"},{"k":"ho","x":"6. 제74조 제2항의 세칙 제정ㆍ개정ㆍ폐지에 관한 사항"},{"k":"ho","x":"7. 그 밖의 본회의 목적에 관련된 본질적으로 중대한 결정 사항"},{"k":"hang","x":"③ 개의하지 못한 학생대표자회에 발의된 안건은 위임하지 아니하고 폐기한다."}],"num":64,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":4,"text":"제5관 권한"},{"t":"art","id":"a65","label":"제65조","title":"학생총회ㆍ학생총투표에 관한 사항","paras":[{"k":"hang","x":"① 학생대표자회는 제31조 제1항에 따라 학생총회의 소집을 요구할 수 있으며, 제36조 제1항에 따라 학생총회에 안건을 상정할 수 있다."},{"k":"hang","x":"② 학생대표자회는 제40조에 따라 학생총투표 시행을 결정할 수 있다."}],"num":65,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a66","label":"제66조","title":"결정ㆍ집행 사항 변경에 관한 사항","paras":[{"k":"hang","x":"① 학생대표자회는 학부운영위원회, 학부 학생회장단과 집행위원회의 결정ㆍ집행 사항을 변경 또는 취소할 수 있다."},{"k":"hang","x":"② 학생대표자회는 반 운영위원회, 반 학생회장단과 반 집행위원회의 결정ㆍ집행 사항을 변경 또는 취소할 수 있다."}],"num":66,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a67","label":"제67조","title":"학부 학생회장단 사퇴ㆍ탄핵에 관한 사항","paras":[{"k":"hang","x":"① 학생대표자회는 학부 학생회장 또는 학부 부학생회장이 제108조 제1항에 따라 사퇴의 허가를 요청하면 허가 여부를 심의ㆍ의결한다."},{"k":"hang","x":"② 학생대표자회는 제109조에 따라 학부 학생회장단에 대한 탄핵안이 상정되면 탄핵안의 학생총회ㆍ학생총투표 부의를 의결할 수 있다."}],"num":67,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a68","label":"제68조","title":"집행위원회에 관한 사항","paras":[{"k":"hang","x":"① 학생대표자회는 집행위원회의 다음 각호의 사항에 관하여 보고받고 이를 인준한다. 단, 학부운영위원회의 사전 인준이 있으면 학생대표자회 정기회의 개의 전까지 해당 결정은 효력을 지닌다."},{"k":"ho","x":"1. 사업 계획과 정책의 기본 방향"},{"k":"ho","x":"2. 집행위원장과 집행위원의 임명"},{"k":"ho","x":"3. 산하 국서의 신설ㆍ폐지와 변경"},{"k":"hang","x":"② 학생대표자회는 집행위원장과 집행위원 또는 이에 준하는 자를 해임할 수 있다."}],"num":68,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a69","label":"제69조","title":"자치단체에 관한 사항","paras":[{"k":"hang","x":"① 학생대표자회는 자치단체를 등록 및 인준할 수 있다."},{"k":"hang","x":"② 학생대표자회는 자치단체의 탈퇴를 승인할 수 있다."}],"num":69,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a70","label":"제70조","title":"특별기구에 관한 사항","paras":[{"k":"hang","x":"① 학생대표자회는 학생자치의 특수한 영역과 기능을 담당하는 특별기구를 인준할 수 있다."},{"k":"hang","x":"② 학생대표자회는 특별기구의 해산을 승인할 수 있다."}],"num":70,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a71","label":"제71조","title":"감사에 관한 사항","paras":[{"k":"hang","x":"① 학생대표자회는 본회 집행기구, 산하기구, 독립기구 및 특별기구의 사업 전반에 대하여 감사를 시행할 수 있다."},{"k":"hang","x":"② 학생대표자회는 감사에 필요하다고 인정될 때 해당 기구의 대표자 또는 사업담당자를 출석시켜 진술을 청취하거나 관련 자료의 제출을 요구할 수 있다."},{"k":"hang","x":"③ 학생대표자회는 제1항의 감사를 위하여 제56조의 감사위원회를 설치할 수 있다."},{"k":"hang","x":"④ 제1항에도 불구하고 학생대표자회는 독립기구의 사업이 진행되고 있는 동안에는 해당 독립기구에 대하여 감사를 시행할 수 없다."}],"num":71,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a72","label":"제72조","title":"징계에 관한 사항","paras":[{"k":"hang","x":"① 학생대표자회는 회원, 집행위원장과 집행위원, 학생대표자회 대의원, 산하기구, 독립기구 및 특별기구가 본 회칙ㆍ세칙ㆍ규칙을 위반할 때 징계할 수 있다."},{"k":"hang","x":"② 학생대표자회는 제1항의 징계를 위하여 제57조의 징계위원회를 설치할 수 있다."},{"k":"hang","x":"③ 제1항에도 불구하고 학생대표자회는 독립기구의 사업이 진행되고 있는 동안에는 해당 독립기구에 대하여 징계할 수 없다."},{"k":"hang","x":"④ 그 밖에 징계에 대한 자세한 사항은 ｢고려대학교 자유전공학부 징계세칙｣을 따른다."}],"num":72,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a73","label":"제73조","title":"재정에 관한 사항","paras":[{"k":"hang","x":"① 학생대표자회는 학부운영위원회의 심의를 거친 집행위원회, 반 학생회, 특별기구 및 그 밖의 학부 학생회비를 사용하는 기구의 예산안ㆍ결산을 심의하여 승인한다."},{"k":"hang","x":"② 학생대표자회는 제1항의 심의에서 승인되지 않은 기구에는 제190조에 따라 해당 학기의 학부 학생회비를 지급하지 않거나 지급액을 삭감 또는 지급을 보류하도록 결정할 수 있다."},{"k":"hang","x":"③ 학생대표자회는 학부 학생회비의 인상ㆍ인하를 결정할 수 있다."}],"num":73,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a74","label":"제74조","title":"회칙ㆍ세칙ㆍ규칙에 관한 사항","paras":[{"k":"hang","x":"① 학생대표자회는 회칙을 개정할 수 있다."},{"k":"hang","x":"② 학생대표자회는 세칙을 제정ㆍ개정ㆍ폐지할 수 있다."},{"k":"hang","x":"③ 학생대표자회는 규칙ㆍ자치규칙이 회칙ㆍ세칙에 부합하는지 심사할 수 있으며, 부합하지 않다고 의결하면 해당 규칙ㆍ자치규칙은 즉시 효력을 잃는다."}],"num":74,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a75","label":"제75조","title":"대외활동에 관한 사항","paras":[{"k":"hang","x":"① 학생대표자회는 본회 차원의 상설적 연대 단체 가입ㆍ탈퇴에 대한 동의권을 가진다."},{"k":"hang","x":"② 학생대표자회는 회원 전체의 명의로 소송을 진행할 필요가 있는 문제가 발생할 때 학부운영위원회에 소송권을 위임할 수 있다."}],"num":75,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제5절 학부운영위원회"},{"t":"h","lv":4,"text":"제1관 통칙"},{"t":"art","id":"a76","label":"제76조","title":"지위","paras":[{"k":"line","x":"학부운영위원회는 본회의 신속하고 민주적인 결정을 위하여 학생대표자회가 일정 권한을 위임한 상설적인 의결기구이다."}],"num":76,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a77","label":"제77조","title":"정기회의","paras":[{"k":"hang","x":"① 학부운영위원회 정기회의는 매주 1회 개의함을 원칙으로 한다. 단, 학부운영위원회는 의결로 정기회의의 일정을 조정할 수 있다."},{"k":"hang","x":"② 학부 학생회장은 임기 시작 직후 학부운영위원회 정기회의 개의 요일과 시각을 학부운영위원들과 협의하여 결정한 후 이를 공고하여야 한다."},{"k":"hang","x":"③ 학부운영위원회 의장은 매월 말 익월의 학부운영위원회 정기회의 일정을 학부운영위원들과 협의하여 결정하여야 한다."}],"num":77,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a78","label":"제78조","title":"임시회의","paras":[{"k":"hang","x":"① 학부운영위원회 임시회의는 다음 각호 중 하나에 따라 의장이 소집한다."},{"k":"ho","x":"1. 의장의 소집요구"},{"k":"ho","x":"2. 학부운영위원회 재적 위원 3분의 1 이상의 연서에 따른 소집요구"},{"k":"ho","x":"3. 본회의 회원 20명 이상의 연서에 따른 소집요구"},{"k":"hang","x":"② 학부운영위원회는 연서에 따른 소집요구가 있으면 제25조 제2항에 따라 연서를 심의하고, 결함이 없는 경우 지체 없이 학부운영위원회 개의일을 결정한다. 이때 개의일은 소집요구 서식에 기재된 개의 희망일로 함을 원칙으로 하며, 변경하더라도 개의 희망일과 3일 이상의 차이가 있게 정할 수 없다."}],"num":78,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":4,"text":"제2관 위원"},{"t":"art","id":"a79","label":"제79조","title":"학부운영위원","paras":[{"k":"hang","x":"① 다음 각호 중 하나에 해당하는 자는 학부운영위원이 된다."},{"k":"ho","x":"1. 학부 학생회장과 학부 부학생회장"},{"k":"ho","x":"2. 각 반 학생회장"},{"k":"hang","x":"② 선거 미시행 등의 이유로 위원이 공석일 때는 사고로 하고 재적에서 제외한다. 이때 반 학생회는 발언권을 가지는 대표를 파견할 수 있다."},{"k":"hang","x":"③ 제1항 제2호의 학부운영위원이 학부운영위원회에 정당한 사유로 출석하지 못할 때는 개의 직후 인준을 받아 해당 기구의 부학생회장이 대신 의결권을 가질 수 있다."}],"num":79,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a80","label":"제80조","title":"학부운영위원의 의무","paras":[{"k":"line","x":"학부운영위원의 의무에 관하여서는 제53조를 준용한다."}],"num":80,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":4,"text":"제3관 특별위원회"},{"t":"art","id":"a81","label":"제81조","title":"특별위원회","paras":[{"k":"hang","x":"① 학부운영위원회는 특수한 목적을 달성하기 위하여 의결로 특별위원회를 둘 수 있다."},{"k":"hang","x":"② 학부운영위원회는 제1항에 따른 특별위원회를 구성할 때 구체적인 소관 사항을 정하여야 한다."},{"k":"hang","x":"③ 본회의 회원은 특별위원회의 위원이 될 수 있다."},{"k":"hang","x":"④ 특별위원회는 본회의 회원을 대상으로 위원을 공개적으로 모집할 수 있다. 단, 특별위원회의 위원장이 선출되지 않았으면 학부운영위원회 의장이 대신 모집할 수 있다."},{"k":"hang","x":"⑤ 특별위원회의 위원장은 특별위원회 내부에서 선출한다."},{"k":"hang","x":"⑥ 특별위원회는 학부운영위원회의 인준으로 업무를 개시하며, 그 구성원의 변동이 있을 때는 지체 없이 학부운영위원회에 보고하여야 한다."},{"k":"hang","x":"⑦ 특별위원회는 학부운영위원회에 활동 내용을 수시로 보고하여야 한다."},{"k":"hang","x":"⑧ 특별위원회의 활동기간은 제5항에 따라 처음으로 인준된 후 첫 번째 2학기 종강일까지로 한다. 단, 특별위원회는 수행하던 업무가 종료되지 아니하였다고 판단할 때는 활동 종료일 후 30일 이내에 학부운영위원회에 재인준을 요청할 수 있다."},{"k":"hang","x":"⑨ 학부운영위원회는 다음 각호에 해당하면 출석 위원 3분의 2 이상의 찬성으로 특별위원회의 활동을 종료시킬 수 있다."},{"k":"ho","x":"1. 특별위원회의 활동 목적이 달성된 경우"},{"k":"ho","x":"2. 특별위원회의 활동 필요성이 없어진 경우"},{"k":"ho","x":"3. 특별위원회의 활동이 상당한 기간 진행되지 않은 경우"},{"k":"ho","x":"4. 그 밖의 특별위원회 활동을 종료시킬 만한 사유가 있는 경우"},{"k":"hang","x":"⑩ 특별위원회는 다음 각호에 해당하면 해산한다."},{"k":"ho","x":"1. 활동기간이 종료된 경우"},{"k":"ho","x":"2. 제9항에 따라 활동이 종료된 경우"}],"num":81,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a82","label":"제82조","title":"인권침해사건대책위원회","paras":[{"k":"hang","x":"① 학부운영위원회는 본회의 회원에 대한 인권침해사건이 발생할 때는 해당 사건을 조사하기 위하여 인권침해사건대책위원회를 둘 수 있다."},{"k":"hang","x":"② 인권침해사건대책위원회의 구성ㆍ업무ㆍ권한 및 운영에 관하여 필요한 사항은 의결로 ｢고려대학교 총학생회 인권침해사건대응세칙｣을 준용한다."}],"num":82,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a83","label":"제83조","title":"활동","paras":[{"k":"hang","x":"① 특별위원회는 활동 목적에 직ㆍ간접적으로 필요하다고 판단되면 학부운영위원회의 출석 3분의 2 이상의 찬성으로 제81조 제2항에서 정한 소관 사항을 벗어난 활동을 할 수 있다."},{"k":"hang","x":"② 특별위원회는 본회의 회원 및 각 기구에 출석 또는 자료 제출을 요청할 수 있다."},{"k":"hang","x":"③ 특별위원회는 집행위원회에 협조를 요청할 수 있다."}],"num":83,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":4,"text":"제4관 회의"},{"t":"art","id":"a84","label":"제84조","title":"소집 공고","paras":[{"k":"hang","x":"① 학부운영위원회 의장은 학부운영위원회 정기회의의 소집을 개의일 1일 전까지 공고하여야 한다."},{"k":"hang","x":"② 공고문에는 다음 각호의 사항을 명시하여야 한다."},{"k":"ho","x":"1. 회의 시작 일시"},{"k":"ho","x":"2. 회의 장소"},{"k":"ho","x":"3. 안건과 안건에 대한 설명"}],"num":84,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a85","label":"제85조","title":"안건지의 사전 배포","paras":[{"k":"hang","x":"① 학부운영위원회 의장은 학부운영위원회 정기회의 개의 1일 전까지 제출된 안건과 그에 관한 설명, 집행위원회 등의 보고ㆍ인준 사항 등이 포함된 안건지를 회원들에게 배포하여야 한다."},{"k":"hang","x":"② 안건지의 배포는 유인물 형태로 제작하여 비치하는 방법 또는 전산화된 형태의 문서로 제작하여 온라인에 게시하는 방법으로 한다."}],"num":85,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a86","label":"제86조","title":"개의ㆍ의결요건","paras":[{"k":"line","x":"학부운영위원회는 특별한 규정이 없는 한 재적 위원 과반수의 출석으로 개의하고 출석 위원 과반수의 찬성으로 의결한다."}],"num":86,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a87","label":"제87조","title":"표결방법","paras":[{"k":"hang","x":"① 표결은 기명으로 함을 원칙으로 한다."},{"k":"hang","x":"② 중요한 안건으로서 의장 또는 위원이 제의하여 학부운영위원회가 의결하면 표결을 무기명으로 할 수 있다."},{"k":"hang","x":"③ 제96조 제4항의 규칙 제정ㆍ개정ㆍ폐지에 관한 사항은 반드시 기명투표로 표결하여야 한다."},{"k":"hang","x":"④ 학부운영위원회 의장은 안건에 대한 이의가 있는지 물어서 이의가 없다고 인정하면 가결되었음을 선포할 수 있다. 단, 이의가 있을 때 또는 무기명으로 표결할 때는 반드시 표결하여야 한다."}],"num":87,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a88","label":"제88조","title":"안건","paras":[{"k":"hang","x":"① 학부운영위원회는 다음 각호의 안건을 심의ㆍ의결한다."},{"k":"ho","x":"1. 학부운영위원이 발의한 안건"},{"k":"ho","x":"2. 집행위원회가 발의한 안건"},{"k":"ho","x":"3. 본회의 회원 20명 이상의 연서에 따른 소집요구와 함께 발의한 안건"},{"k":"ho","x":"4. 제64조 제1항에 따라 학생대표자회에서 위임된 안건"},{"k":"hang","x":"② 세칙에서 해당 세칙에 부수되는 규칙의 제정ㆍ개정ㆍ폐지에 관한 권한을 학부운영위원회에 위임할 때는 제1항에도 불구하고 해당 규칙의 제정안ㆍ개정안ㆍ폐지안 발의에 관하여서는 해당 세칙의 규정에 따른다."}],"num":88,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":4,"text":"제5관 권한"},{"t":"art","id":"a89","label":"제89조","title":"의결기구에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 제51조 제1항에 따라 학생대표자회의 소집을 요구할 수 있으며 제63조에 따라 학생대표자회에 안건을 발의할 수 있다."},{"k":"hang","x":"② 학부운영위원회는 학생총회 또는 학생대표자회 개의에 관한 세부 문제를 논의하고 결정한다."},{"k":"hang","x":"③ 학부운영위원회는 학생총회 또는 학생대표자회에 대하여 연서에 따른 소집요구가 있으면 제31조 제2항 및 제51조 제2항에 따라 학생총회 또는 학생대표자회의 개의일을 결정한다."},{"k":"hang","x":"④ 학부운영위원회는 학생대표자회 개의 전 학생대표자회 대의원이 민주적 선거에 따라 당선되었는지 실질적으로 기구를 대표하고 있는지 등 대표자 지위에 대한 심사를 진행하여야 하며, 이를 기준으로 대의원 명단을 확정한다."}],"num":89,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a90","label":"제90조","title":"학부 학생회장단의 탄핵에 관한 사항","paras":[{"k":"line","x":"학부운영위원회는 학부 학생회장단에 대한 탄핵안이 발의되면 제109조 제4항에 따라 학생대표자회를 소집한다."}],"num":90,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a91","label":"제91조","title":"집행기구에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 제119조 제3항, 제120조 제3항에 따라 집행위원장과 집행위원회 국서별 국장과 국원을 사전 인준한다."},{"k":"hang","x":"② 학부운영위원회는 제68조 제1항에 따라 학생총회 또는 학생대표자회 보고 사항을 사전 심의ㆍ의결한다."},{"k":"hang","x":"③ 학부운영위원회는 학부 학생회장단과 집행위원회의 사업 계획과 진행 상황, 결과에 대한 보고를 받고 이를 심의하고 조정한다."},{"k":"hang","x":"④ 학부운영위원회는 학부 학생회장단과 집행위원회의 효율적인 집행을 보장하기 위하여 학부 학생회장단이 사전 집행이 불가피하다고 판단하여 집행한 사업의 승인권을 가진다."},{"k":"hang","x":"⑤ 학부운영위원회는 학부 학생회장단과 집행위원회의 결정과 집행 사항을 변경 또는 취소할 수 있다."}],"num":91,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a92","label":"제92조","title":"자치단체에 관한 사항","paras":[{"k":"line","x":"학부운영위원회는 자치단체 등록 신청을 심의하여 학생대표자회에 해당 단체의 자치단체 등록에 관한 안건을 상정한다."}],"num":92,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a93","label":"제93조","title":"특별기구에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 특별기구 인준 신청을 심의하여 학생대표자회에 해당 단체의 특별기구 인준에 관한 안건을 상정한다."},{"k":"hang","x":"② 학부운영위원회는 특별기구 재인준 신청을 심의하여 학생대표자회에 특별기구 재인준에 관한 안건을 상정한다."},{"k":"hang","x":"③ 학부운영위원회는 필요한 경우 특별기구의 장 또는 특정 업무 담당자의 출석을 요구할 수 있다."}],"num":93,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a94","label":"제94조","title":"선거에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 학부 학생회장단 선거 일정을 결정한다."},{"k":"hang","x":"② 학부운영위원회는 동시선거 일정을 결정한다."},{"k":"hang","x":"③ 학부운영위원회는 제152조 제1항에 따라 선거관리위원회가 구성되면 지체 없이 각 선거관리위원의 자격 등을 심사한다."},{"k":"hang","x":"④ 그 밖의 자세한 사항은 ｢고려대학교 자유전공학부 학부ㆍ반 선거시행세칙｣을 따른다."}],"num":94,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a95","label":"제95조","title":"재정에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 제184조에 따라 집행기구 자산의 취득, 사용, 보관 및 처분 행위를 변경 또는 취소할 수 있다."},{"k":"hang","x":"② 학부운영위원회는 제188조에 따라 집행위원회, 반 학생회, 특별기구 및 그 밖의 학부 학생회비를 사용하는 기구의 예산안 및 결산을 사전 심의한 후 학생대표자회에 상정한다."}],"num":95,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a96","label":"제96조","title":"회칙ㆍ세칙ㆍ규칙에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 제194조에 따라 회칙 개정안을 발의할 수 있다."},{"k":"hang","x":"② 학부운영위원회는 제202조 제3항에 따라 세칙 제정안ㆍ개정안 및 폐지안을 발의할 수 있다."},{"k":"hang","x":"③ 학부운영위원회는 세칙에 따라 그 세칙에 부수되는 규칙을 제정ㆍ개정 및 폐지할 수 있다."},{"k":"hang","x":"④ 학부운영위원회는 일반규칙ㆍ임시규칙을 제정ㆍ개정 및 폐지할 수 있다."}],"num":96,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a97","label":"제97조","title":"대외활동에 관한 사항","paras":[{"k":"hang","x":"① 학부운영위원회는 본회 차원의 대외적 활동에 대한 동의권을 갖는다."},{"k":"hang","x":"② 학부운영위원회는 직전 학기로부터 당해 학기로 이월된 학부 학생회비의 5%를 초과하는 재정적 지출을 수반하거나, 본회의 회원에게 중대한 영향을 미치는 학부 학생회장단 또는 집행위원회 차원의 대외활동에 대하여 동의권을 갖는다."},{"k":"hang","x":"③ 제1항과 제2항의 사항에 관하여 학부운영위원회는 학부 학생회장단과 집행위원회의 효율적인 대외활동을 보장하기 위하여 학부 학생회장이 사전 집행이 불가피하다고 판단하여 집행한 대외활동의 승인권을 가진다."}],"num":97,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a98","label":"제98조","title":"학교 운영 참여에 관한 사항","paras":[{"k":"line","x":"학부운영위원회는 본회를 대표하여 학교 기구의 학생 대표가 되는 자를 회의에 배석하도록 하여 그 기구에서의 논의 사항을 보고받고, 의결권의 행사에 관하여 회원의 의사가 반영되도록 할 수 있는 방안을 논의한다."}],"num":98,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제6절 비상대책위원회"},{"t":"art","id":"a99","label":"제99조","title":"지위","paras":[{"k":"line","x":"비상대책위원회는 학부운영위원회를 대신하여 임시로 구성되는 의결기구이다."}],"num":99,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a100","label":"제100조","title":"구성","paras":[{"k":"line","x":"비상대책위원회는 다음 각호 중 어느 하나에 해당하면 구성된다. 단, 제1호에 해당할 때 학부 학생회장단 임기가 끝나지 않았다면 그 임기가 끝난 시점부터 구성된다."},{"k":"ho","x":"1. 학부 학생회장단 선거가 무산될 때"},{"k":"ho","x":"2. 학부 학생회장단 전원이 사퇴하고, 해당 학부 학생회장단의 잔여 임기가 180일이 넘지 않을 때"},{"k":"ho","x":"3. 학부 학생회장단 전원이 탄핵되고, 해당 학부 학생회장단의 잔여 임기가 180일이 넘지 않을 때"},{"k":"ho","x":"4. 학부 학생회장단 전원이 당연퇴직하고, 해당 학부 학생회장단의 잔여 임기가 180일이 넘지 않을 때"}],"num":100,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a101","label":"제101조","title":"비상대책위원","paras":[{"k":"hang","x":"① 각 반 학생회장과 부학생회장은 비상대책위원이 된다."},{"k":"hang","x":"② 학생대표자회는 제1항을 제외한 학생대표자회 대의원 중 비상대책위원을 호선할 수 있다."},{"k":"hang","x":"③ 제2항에 따라 비상대책위원이 된 자가 더 이상 학생대표자회 대의원이 아니게 된 경우 그다음으로 해당 대의원직을 가지게 된 자에게는 제2항에 따른 호선의 효력이 인정되지 아니한다."}],"num":101,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a102","label":"제102조","title":"위원장","paras":[{"k":"hang","x":"① 비상대책위원장은 학부 학생회장단의 궐위 동안 학부 학생회장에 준하는 권한을 가지며, 학부 학생회장단의 상시적 업무를 담당한다."},{"k":"hang","x":"② 비상대책위원장은 위원들이 제101조 제1항에 따라 위원이 된 자 중에서 선출한다."},{"k":"hang","x":"③ 비상대책위원장은 비상대책위원회의 선출로 업무를 개시하며 선출 직후 지체 없이 학생대표자회의 인준을 받아야 한다."},{"k":"hang","x":"④ 비상대책위원장의 임기는 비상대책위원회에서 선출된 시점부터 다음 학부 학생회장단 선거에 따른 학부 학생회장단 당선인의 임기 개시 예정일까지로 한다. 단, 제174조 제2항에 따른 재선거가 무산될 때는 학생대표자회의 의결로 그 해 2학기 종강일까지 임기를 연장할 수 있다."},{"k":"hang","x":"⑤ 비상대책위원장이 다음 각호 중 어느 하나에 해당하면 그 시점부터 임기를 마친 것으로 본다."},{"k":"ho","x":"1.당연퇴직한 경우"},{"k":"ho","x":"2.제101조 제1항 또는 학생대표자회 대의원의 임기가 만료된 경우"},{"k":"hang","x":"⑥ 비상대책위원장은 비상대책위원회의 허가를 받아 사퇴할 수 있다. 이때 비상대책위원회는 지체 없이 다음 비상대책위원장을 선출한다."},{"k":"hang","x":"⑦ 비상대책위원장은 중임할 수 없다."},{"k":"hang","x":"⑧ 비상대책위원장의 의무에 관하여서는 제107조를 준용한다."}],"num":102,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a103","label":"제103조","title":"권한ㆍ업무","paras":[{"k":"hang","x":"① 비상대책위원회는 학부운영위원회에 준하는 권한을 가지며, 특별한 사유가 없으면 회칙ㆍ세칙ㆍ규칙의 “학부운영위원회”와 “학부운영위원”을 “비상대책위원회”와 “비상대책위원”으로 본다."},{"k":"hang","x":"② 비상대책위원회는 학부 학생회장단의 궐위 기간 학부운영위원회의 상시적 업무를 담당한다."},{"k":"hang","x":"③ 비상대책위원회는 학부 학생회장단의 궐위 기간 집행위원회의 상시적 업무를 담당하기 위하여 임시 집행위원회를 구성할 수 있다."}],"num":103,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a104","label":"제104조","title":"제한","paras":[{"k":"hang","x":"① 비상대책위원장은 학부 학생회장이 가지는 사전 집행ㆍ사후 학부운영위원회 승인 방식의 사업 집행 및 대외활동을 할 수 없다."},{"k":"hang","x":"② 임시집행위원회는 집행위원회가 가지는 사전 집행ㆍ사후 학부운영위원회 승인 방식의 사업 집행 및 대외활동을 할 수 없다."},{"k":"hang","x":"③ 비상대책위원장과 임시집행위원회는 직전 학기로부터 당해 학기로 이월된 학부 학생회비의 30%를 초과하는 재정지출을 할 수 없다."},{"k":"hang","x":"④ 제3항의 경우 제186조 제2항 및 제186조 제3항에 따른 재정지출은 포함하지 아니한다."}],"num":104,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제3장 집행기구"},{"t":"h","lv":3,"text":"제1절 학부 학생회장단"},{"t":"h","lv":4,"text":"제1관 지위"},{"t":"art","id":"a105","label":"제105조","title":"학부 학생회장단","paras":[{"k":"hang","x":"① 학부 학생회장은 본회를 대표하며, 본회 의결기구의 의장이 된다."},{"k":"hang","x":"② 학부 부학생회장은 학부 학생회장을 보좌하고, 학부 학생회장이 권한을 위임하거나 사고일 때에 학부 학생회장의 직무를 대행한다."}],"num":105,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a106","label":"제106조","title":"임기ㆍ삼선 금지","paras":[{"k":"hang","x":"① 학부 학생회장단의 임기는 특별한 규정이 없는 한 당선된 해의 2학기 종강일 다음 날부터 이듬해 2학기 종강일까지로 한다."},{"k":"hang","x":"② 학부 학생회장단이 제174조 제2항에 따른 재선거 및 제175조의 보궐선거를 통하여 당선되었으면 해당 학부 학생회장단의 임기는 당선 확정이 공고된 시점부터 그 해 2학기 종강일까지로 한다."},{"k":"hang","x":"③ 학부 학생회장단이 제174조 제3항에 따른 재선거를 통하여 당선되었으면 해당 학부 학생회장단의 임기는 당선 확정이 공고된 시점부터 이듬해 2학기 종강일까지로 한다."},{"k":"hang","x":"④ 학부 학생회장 또는 학부 부학생회장은 후임 학부 학생회장단 선거에서 학부 학생회장 또는 학부 부학생회장 후보로 입후보할 수 있다. 단 이미 학부 학생회장단을 중임하였을 때는 그러하지 아니한다."}],"num":106,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a107","label":"제107조","title":"의무","paras":[{"k":"hang","x":"① 학부 학생회장단은 회원들의 의사를 반영하여 민주적 절차에 따라 업무를 수행하여야 한다."},{"k":"hang","x":"② 학부 학생회장은 본회의 대표로서 본회의 의결기구에 본회의 활동 사항을 보고하여야 한다."},{"k":"hang","x":"③ 학부 학생회장단은 본회의 지속적ㆍ장기적 발전을 위하여 노력하여야 한다."},{"k":"hang","x":"④ 학부 학생회장단은 본회와 본회 산하기구 및 특별기구에서 치러지는 각종 선거에서 부당한 영향력의 행사 등 선거 결과에 직ㆍ간접적인 영향을 미치는 행위를 하여서는 아니 된다."},{"k":"hang","x":"⑤ 학부 학생회장단은 후임 학부 학생회장단의 선출과 후임 학부 학생회장단으로의 인수인계가 원활하게 이루어질 수 있도록 노력하여야 한다."},{"k":"hang","x":"⑥ 학부 학생회장은 본회의 대표로 학교 기구의 위원이 될 때는 제98조에 따라 의결권 행사 등에 관하여 학부운영위원회와 협의하여야 한다."}],"num":107,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a108","label":"제108조","title":"사퇴","paras":[{"k":"hang","x":"① 학부 학생회장 또는 학부 부학생회장이 사퇴하고자 할 때는 학생대표자회의 허가가 있어야 한다. 단, 사망 등으로 인하여 당사자가 허가를 받을 수 없을 때는 그러하지 아니한다."},{"k":"hang","x":"② 학부 학생회장이 사퇴하면 학부 부학생회장이 그 직을 승계한다."}],"num":108,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a109","label":"제109조","title":"탄핵","paras":[{"k":"hang","x":"① 학부 학생회장단이 업무 수행에 있어서 회칙을 중대하게 위반하였을 때 다음 각호 중 하나에 따라 학부 학생회장단의 탄핵안을 발의할 수 있다."},{"k":"ho","x":"1. 학부운영위원회의 재적 위원 3분의 2 이상에 해당하는 연서"},{"k":"ho","x":"2. 학생대표자회의 재적 위원 과반수에 해당하는 연서"},{"k":"ho","x":"3. 본회의 회원 50명 이상에 해당하는 연서"},{"k":"hang","x":"② 학부 학생회장단에 대한 탄핵안은 학부 학생회장과 학부 부학생회장 전원을 대상으로 발의할 수도 있고, 한 명만을 대상으로 발의할 수도 있다."},{"k":"hang","x":"③ 탄핵안이 발의되면 학부운영위원회 의장은 지체 없이 학부운영위원회를 소집하여 제1항의 연서에서 형식상의 결함을 심의한다. 단, 학부운영위원회 의장이 회의 소집을 거부하였을 때는 학부운영위원회 재적 위원 3분의 1의 연서에 따라 학부운영위원이 직접 회의를 소집할 수 있으며, 개의 직후 임시의장을 선출한다."},{"k":"hang","x":"④ 제3항에 따라 심의한 연서에 중대한 하자가 없는 경우 학부운영위원회는 탄핵안 발의 10일 이내에 학생대표자회를 소집한다."},{"k":"hang","x":"⑤ 학생대표자회는 제61조 제2항에 따라 탄핵안의 학생총회ㆍ학생총투표 부의를 의결한다."},{"k":"hang","x":"⑥ 제5항에 따라 부의가 의결되는 경우 학생대표자회는 학생총회 소집과 학생총투표 시행 중 탄핵안을 처리할 방식을 의결한다."},{"k":"hang","x":"⑦ 학부 학생회장단에 대한 탄핵안은 학생총회이면 제34조 제2항, 학생총투표이면 제42조 제1항에 따라 의결한다."},{"k":"hang","x":"⑧ 제7항에 따라 탄핵이 의결되면 탄핵의 대상이 된 학부 학생회장단의 일부 또는 전원은 그 의결된 시점부터 해당 직을 잃는다."},{"k":"hang","x":"⑨ 학부 학생회장만이 탄핵되면 학부 부학생회장이 그 직을 승계한다."}],"num":109,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a110","label":"제110조","title":"당연퇴직","paras":[{"k":"line","x":"학부 학생회장이 당연퇴직하면 학부 부학생회장이 그 직을 승계한다."}],"num":110,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a111","label":"제111조","title":"직무정지","paras":[{"k":"hang","x":"① 제109조 제5항에 따라 학생대표자회에서 탄핵안의 부의가 의결된 시점으로부터 그 대상은 모든 직무가 정지되며, 제108조에 따른 사퇴를 할 수 없다."},{"k":"hang","x":"② 제1항의 직무 정지는 학생총회ㆍ학생총투표에서 탄핵안이 부결된 시점부터 해제된다."},{"k":"hang","x":"③ 학부 학생회장단 중 일부 또는 전원이 다음 학부 학생회장단 선거에 후보로 등록하여 후보 등록 공고가 된 시점으로부터 그 대상은 모든 직무가 정지된다."},{"k":"hang","x":"④ 제3항의 직무 정지는 해당 학부 학생회장단 선거가 종료된 시점부터 해제된다."},{"k":"hang","x":"⑤ 학부 학생회장만이 직무가 정지될 때는 학부 부학생회장이 그 직을 대행한다."}],"num":111,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a112","label":"제112조","title":"학부 학생회장단 권한대행","paras":[{"k":"hang","x":"① 학부 학생회장단 권한대행은 다음 각호 중 하나에 해당할 때 그 사항의 공고 직후 구성된다."},{"k":"ho","x":"1. 학부 학생회장단 전원이 제111조의 직무정지 상태일 때"},{"k":"ho","x":"2. 학부 학생회장단 전원이 사퇴하고, 해당 학부 학생회장단의 잔여 임기가 180일을 초과할 때"},{"k":"ho","x":"3. 학부 학생회장단 전원이 탄핵되고, 해당 학부 학생회장단의 잔여 임기가 180일을 초과할 때"},{"k":"ho","x":"4. 학부 학생회장단 전원이 당연퇴직하고, 해당 학부 학생회장단의 잔여 임기가 180일 초과할 때"},{"k":"hang","x":"② 학부 학생회장단 권한대행은 학부운영위원들이 그 위원 중에서 선출한다."},{"k":"hang","x":"③ 학부 학생회장단 권한대행은 학부 학생회장단에 준하는 권한과 의무를 지닌다. 단, 제114조 제3항 및 제5항에 따른 권한의 행사에 관하여서는 학부운영위원회의 동의를 받아야 한다."},{"k":"hang","x":"④ 제1항 제1호에 따른 학부 학생회장단 권한대행의 임기는 학부 학생회장단의 직무 정지가 해제되는 시점까지로 한다. 다만, 학부 학생회장단의 임기가 직무 정지 중에 종료될 때는 권한대행의 임기도 그 시점으로부터 종료된 것으로 본다."},{"k":"hang","x":"⑤ 제1항 제2호부터 제4호까지에 따른 학부 학생회장단 권한대행의 임기는 후임 학부 학생회장단 보궐선거가 종료되는 시점까지로 한다."}],"num":112,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":4,"text":"제2관 권한"},{"t":"art","id":"a113","label":"제113조","title":"의결기구에 관한 사항","paras":[{"k":"line","x":"학부 학생회장은 의장으로서 학생총회, 학생대표자회, 학부운영위원회를 운영한다."}],"num":113,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a114","label":"제114조","title":"집행기구에 관한 사항","paras":[{"k":"hang","x":"① 학부 학생회장은 본회의 사무 집행을 총괄한다."},{"k":"hang","x":"② 학부 학생회장은 집행위원회의 구성권을 가진다."},{"k":"hang","x":"③ 학부 학생회장은 집행위원장과 집행위원회 산하 국서의 국장과 국원에 대한 임면권을 가진다."},{"k":"hang","x":"④ 학부 학생회장은 집행위원회와 산하 국서를 지휘ㆍ감독한다."},{"k":"hang","x":"⑤ 학부 학생회장은 집행위원회의 결정ㆍ집행 사항을 변경 또는 취소할 수 있다."},{"k":"hang","x":"⑥ 학부 학생회장은 필요하다고 인정한 사안의 효율적 업무 집행을 위하여 제2항부터 제5항까지를 준용하여 직속 위원회를 설치할 수 있다."},{"k":"hang","x":"⑦ 학부 학생회장은 학부 학생회장단과 집행위원회의 효율적인 집행을 보장하기 위하여 불가피하다고 판단할 때는 학부운영위원회의 동의 없이 사전 집행할 수 있다. 단, 학부 학생회장은 집행 직후 지체 없이 그 사실을 학부운영위원회에 보고하여 승인받아야 하며, 승인을 받지 못한 경우 원상회복을 위하여 노력하여야 한다."}],"num":114,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a115","label":"제115조","title":"대외활동에 관한 사항","paras":[{"k":"hang","x":"① 학부 학생회장은 학생자치활동에 관한 학교 행정의 문제에 대하여 회원의 의사를 대변하고 학교 당국에 의사를 개진하며 관련 단체 및 회의에 참여할 수 있다."},{"k":"hang","x":"② 학부 학생회장은 본회와 본회의 회원에 관한 문제에 관하여 본회를 대표하여 대외적으로 입장을 표명하는 등의 활동을 할 수 있다. 이때 학부 학생회장은 제75조와 제97조에 따라 활동하여야 한다."},{"k":"hang","x":"③ 학부 학생회장은 학부 학생회장단과 집행위원회의 효율적인 대외활동을 보장하기 위하여 불가피하다고 판단할 때는 학부운영위원회의 동의 없이 사전 집행할 수 있다. 단, 학부 학생회장은 활동 직후 지체 없이 그 사실을 학부운영위원회에 보고하여 승인받아야 하며, 승인을 받지 못한 경우 원상회복을 위하여 노력하여야 한다."}],"num":115,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":4,"text":"제3관 학부 학생회장단 인수위원회"},{"t":"art","id":"a116","label":"제116조","title":"인수위원회","paras":[{"k":"hang","x":"① 학부 학생회장단 당선인은 학부 학생회장단과 집행위원회의 업무 인수를 위하여 당선 확정이 공고된 시점부터 자유전공학부 학생회 인수위원회를 설치할 수 있다. 단, 제174조 제2항에 따른 재선거의 당선인과 보궐선거의 당선인은 그러하지 아니한다."},{"k":"hang","x":"② 인수위원회는 다음 각호의 직무를 수행한다."},{"k":"ho","x":"1. 집행위원회의 조직ㆍ기능 및 예산 현황의 파악"},{"k":"ho","x":"2. 전임 학부 학생회장단과 집행위원회의 주요 사업 분석"},{"k":"ho","x":"3. 후임 집행위원회 정책의 기본 방향 수립을 위한 준비"},{"k":"ho","x":"4. 기타 학부 학생회장단과 집행위원회 업무의 인수에 필요한 사항"},{"k":"hang","x":"③ 인수위원장은 당선된 선거운동본부의 본부장으로 함을 원칙으로 하되, 필요할 때는 당선인이 별도로 정할 수 있다."},{"k":"hang","x":"④ 인수위원회는 제106조에 따라 당선인의 학부 학생회장단 임기가 시작한 시점에 해산한다."}],"num":116,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제２절 집행위원회"},{"t":"art","id":"a117","label":"제117조","title":"지위","paras":[{"k":"line","x":"집행위원회는 본회의 최고집행기구이다."}],"num":117,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a118","label":"제118조","title":"국서","paras":[{"k":"line","x":"집행위원회는 원활한 업무 집행을 위하여 산하에 국서를 둘 수 있다."}],"num":118,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a119","label":"제119조","title":"집행위원","paras":[{"k":"hang","x":"① 집행위원회 산하 각 국서의 국장ㆍ국원은 집행위원이 된다."},{"k":"hang","x":"② 집행위원은 집행위원회의 업무를 수행한다."},{"k":"hang","x":"③ 각 국서의 국장과 국원은 학부 학생회장이 임명하고, 학부운영위원회의 인준으로 업무를 개시한다. 해당 임명에 관하여서는 학생대표자회의 사후 인준을 받아야 한다."},{"k":"hang","x":"④ 모든 집행위원에 대하여 제3항의 사후 인준이 부결되면 학부 학생회장은 학부운영위원회에서 추천한 인원에게 집행위원의 직무를 대행하도록 하여야 한다."},{"k":"hang","x":"⑤ 제4항에 따라 직무를 대행하는 자는 특별한 사유가 없는 한 학부 학생회장이 새로 임명한 집행위원이 학생대표자회의 인준을 받는 시점까지 그 업무를 수행한다."}],"num":119,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a120","label":"제120조","title":"집행위원장","paras":[{"k":"hang","x":"① 학부 학생회장은 원활한 운영을 위하여 집행위원장을 둘 수 있다."},{"k":"hang","x":"② 집행위원장은 학부 학생회장단을 보좌하며, 본회 사무의 집행에 관하여 학부 학생회장단의 지시에 따라 각 국서를 관리ㆍ감독한다."},{"k":"hang","x":"③ 집행위원장은 학부 학생회장이 임명하고, 학부운영위원회의 인준으로 업무를 개시한다. 해당 임명에 관하여서는 학생대표자회의 사후 인준을 받아야 한다."}],"num":120,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a121","label":"제121조","title":"임기","paras":[{"k":"hang","x":"① 집행위원회의 임기는 제106조에 따른 학부 학생회장단의 임기가 종료되는 시점까지로 한다."},{"k":"hang","x":"② 제1항에도 불구하고 제112조 제1항 제2호부터 제4호까지에 따라 학부 학생회장단 권한대행 체제가 구성된 경우, 집행위원회의 임기는 해당 권한대행의 임기가 종료되는 시점까지로 한다."}],"num":121,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a122","label":"제122조","title":"업무","paras":[{"k":"hang","x":"① 집행위원회는 본회의 사업 집행 전반을 담당한다."},{"k":"hang","x":"② 집행위원회는 학생총회, 학생대표자회, 학부운영위원회가 결정한 업무를 집행한다."},{"k":"hang","x":"③ 집행위원회는 학부 학생회장단이 결정한 업무를 집행한다."},{"k":"hang","x":"④ 집행위원회는 학생총회, 학생총투표, 학생대표자회, 학부운영위원회의 개의ㆍ시행을 준비하고, 이에 사용되는 각종 서식을 ｢고려대학교 총학생회 사무처리세칙｣에 따라 제작한다."},{"k":"hang","x":"⑤ 집행위원회는 자치공간을 분배 및 회수할 수 있는 권한을 가진다."},{"k":"hang","x":"⑥ 집행위원회는 본회의 사물함을 분배, 회수 및 철거할 수 있는 권한을 가진다."},{"k":"hang","x":"⑦ 집행위원회는 학생총회, 학생대표자회, 학부운영위원회에 본회의 운영 사항을 보고하여야 한다."},{"k":"hang","x":"⑧ 집행위원회는 본회의 예산안ㆍ결산을 작성하여 학생대표자회와 학부운영위원회에 보고하여야 한다."}],"num":122,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a123","label":"제123조","title":"집행회의","paras":[{"k":"line","x":"집행위원회는 집행위원회의 업무에 속하는 사안을 심의하기 위하여 집행회의를 소집할 수 있다."}],"num":123,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a124","label":"제124조","title":"계열회의","paras":[{"k":"line","x":"집행위원회는 원활한 업무 집행을 위하여 특정 국서의 국장과 각 반 학생회, 자치단체 및 특별기구 등의 동종 업무 담당 국장 혹은 이에 준하는 자가 참가하는 계열회의를 개최할 수 있다."}],"num":124,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제3절 임시집행위원회"},{"t":"art","id":"a125","label":"제125조","title":"지위","paras":[{"k":"line","x":"임시집행위원회는 집행위원회에 준하는 권한을 가지며, 학부 학생회장단의 궐위 기간 집행위원회의 상시적 업무를 담당한다."}],"num":125,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a126","label":"제126조","title":"국서","paras":[{"k":"line","x":"비상대책위원회는 임시집행위원회의 원활한 업무 진행을 위하여 국서를 둘 수 있다."}],"num":126,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a127","label":"제127조","title":"임시집행위원","paras":[{"k":"hang","x":"① 비상대책위원회는 임시집행위원회를 구성하기 위하여 각 반 학생회에 임시집행위원을 두 명씩 추천하도록 하며, 그 외 임시집행위원은 공고를 내어 공개모집 및 선발할 수 있다."},{"k":"hang","x":"② 임시집행위원의 업무 개시와 인준 절차는 제119조를 준용한다."}],"num":127,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a128","label":"제128조","title":"임시집행위원장","paras":[{"k":"hang","x":"① 비상대책위원장은 원활한 운영을 위하여 임시집행위원장을 둘 수 있다."},{"k":"hang","x":"② 임시집행위원장의 업무 개시와 인준 절차는 제120조를 준용한다."}],"num":128,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a129","label":"제129조","title":"임기","paras":[{"k":"line","x":"임시집행위원회의 임기는 특별한 사유가 없는 한 임시집행위원회를 구성한 비상대책위원회가 해산하는 시점까지로 한다. 단, 제174조 제3항에 따른 재선거가 무산될 때는 2학기 종강일까지로 하며, 비상대책위원회는 제127조에 따라 새로 임시집행위원회를 구성하여야 한다."}],"num":129,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a130","label":"제130조","title":"업무","paras":[{"k":"line","x":"임시집행위원회의 업무에 관하여서는 제122조부터 제124조까지를 준용한다."}],"num":130,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제4장 산하기구"},{"t":"h","lv":3,"text":"제1절 반 학생회"},{"t":"art","id":"a131","label":"제131조","title":"지위","paras":[{"k":"line","x":"반 학생회는 본회의 A반, B반, C반, D반으로 분류되는 네 개의 반을 기준으로 하여 그에 속한 본회의 회원 전원이 회원의 지위를 가지고 반 학생회원의 단결 및 권리와 이익 보장을 위하여 자치활동을 하는 조직이다."}],"num":131,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a132","label":"제132조","title":"회원","paras":[{"k":"hang","x":"① 각 반 학생회에 소속된 본회의 회원은 해당 반 학생회의 회원이 된다. 이때 본회 회원의 반 학생회별 분류는 학부운영위원회에서 규칙으로 정한다."},{"k":"hang","x":"② 반 학생회의 회원은 해당 반 학생회장단 선거의 선거권과 피선거권을 가진다."},{"k":"hang","x":"③ 반 학생회의 회원은 해당 반 학생회 사업을 향유할 권리를 지닌다."},{"k":"hang","x":"④ 그 밖의 반 학생회 회원의 유형, 권리, 의무 등에 관한 사항은 해당 반 학생회의 자치규칙으로 정한다."}],"num":132,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a133","label":"제133조","title":"의결기관","paras":[{"k":"hang","x":"① 반 학생총회는 반 학생회의 최고의결기관이며 소속 회원 전체로 구성된다."},{"k":"hang","x":"② 반 학생회는 반 학생총회의 상설적인 의결기관으로 반 운영위원회를 둘 수 있다."},{"k":"hang","x":"③ 반 학생회는 반 학생총회와 반 운영위원회의 중간 위계를 가지는 의결기관을 둘 수 있다."},{"k":"hang","x":"④ 각 의결기관의 구성, 업무와 권한, 운영 등에 관하여서는 해당 반 학생회의 자치규칙으로 정한다."}],"num":133,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a134","label":"제134조","title":"학생회장단","paras":[{"k":"hang","x":"① 반 학생회장단은 각 반 학생회의 자치규칙에 따라 회원의 보통ㆍ평등ㆍ직접ㆍ비밀선거로 선출한다."},{"k":"hang","x":"② 반 학생회장은 해당 반을 대표하며 학생대표자회 대의원 및 학부운영위원이 된다."},{"k":"hang","x":"③ 반 학생회는 부학생회장을 둘 수 있으며, 이때 부학생회장은 학생대표자회 대의원이 된다."},{"k":"hang","x":"④ 반 학생회장단의 선출, 임기, 업무와 권한, 의무 등에 관하여서는 해당 반 학생회의 자치규칙으로 정한다."}],"num":134,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a135","label":"제135조","title":"집행기관","paras":[{"k":"hang","x":"① 반 학생회는 반 학생회의 최고집행기관으로서 해당 반 학생회의 사업 집행 전반을 담당하는 반 집행위원회를 둘 수 있다."},{"k":"hang","x":"② 반 집행위원회의 구성, 업무와 권한, 운영 등에 관하여서는 해당 반 학생회의 자치규칙으로 정한다."}],"num":135,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a136","label":"제136조","title":"재정","paras":[{"k":"hang","x":"① 반 학생회는 학부 학생회비에서 제186조 제2항에 따라 재정의 배분을 받는다."},{"k":"hang","x":"② 반 학생회는 재정 배분에 관한 결정이 이루어지는 각종 절차에 참가할 권리가 있다."},{"k":"hang","x":"③ 반 학생회는 제188조 제1항에 따라 예산안ㆍ결산을 작성하여 학생대표자회 정기회의 개의 7일 전까지 학부운영위원회에 제출하여야 한다."},{"k":"hang","x":"④ 반 학생회는 학부운영위원회에 출석하여 제3항에 따라 제출한 예산안ㆍ결산을 보고하여야 한다."}],"num":136,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a137","label":"제137조","title":"자치규칙","paras":[{"k":"hang","x":"① 반 학생회는 자치규칙을 제정하여 자치에 필요한 전반적인 사항을 규정한다."},{"k":"hang","x":"② 반 학생회는 자치규칙을 개정하였을 때는 지체 없이 학부운영위원회에 보고하여야 한다."},{"k":"hang","x":"③ 반 학생회의 자치규칙이 없거나 부실하여 특정 사안에 관한 규정이 없을 때는 해당 반 학생회 의결기관의 의결로 본회의 회칙ㆍ세칙ㆍ규칙 또는 ｢고려대학교 총학생회 산하기구 회칙준칙｣의 전부 또는 일부를 적용하도록 할 수 있다. 단, 반 학생회가 새로 만들어져서 의결기관이 없는 경우 의결기관이 구성될 때까지는 별도의 의결 없이 가능하다."}],"num":137,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 자치단체"},{"t":"art","id":"a138","label":"제138조","title":"지위","paras":[{"k":"line","x":"자치단체는 본회의 단체 중 본회의 등록 절차를 거쳐 특정한 분야에서 특정한 목적을 가지고 활동하는 단체이다."}],"num":138,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a139","label":"제139조","title":"목적","paras":[{"k":"hang","x":"① 자치단체는 본회의 목적에 맞게 성실히 활동하며 창조적 대학 문화 창달을 위하여 노력하는 것을 목적으로 한다."},{"k":"hang","x":"② 자치단체는 본회의 회원들의 관심사에 따른 자발적인 참여를 보장함으로써 본회 회원의 결속 및 학생회의 발전에 이바지함을 목적으로 한다."}],"num":139,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a140","label":"제140조","title":"회원","paras":[{"k":"hang","x":"① 각 자치단체에 소속된 본회의 회원은 해당 자치단체의 회원이 된다."},{"k":"hang","x":"② 자치단체는 자치단체의 원활한 운영을 위하여 필요할 때는 본회의 회원이 아닌 자가 자치단체에 가입하는 것을 허용할 수 있다."},{"k":"hang","x":"③ 자치단체의 회원은 해당 자치단체장 선거의 선거권과 피선거권을 가진다."},{"k":"hang","x":"④ 자치단체의 회원은 해당 자치단체의 사업을 향유할 권리를 지닌다."}],"num":140,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a141","label":"제141조","title":"자치단체장","paras":[{"k":"hang","x":"① 자치단체장은 각 자치단체의 자치규칙에 따라 회원의 보통ㆍ평등ㆍ직접ㆍ비밀선거로 선출함을 원칙으로 한다."},{"k":"hang","x":"② 자치단체장은 해당 자치단체를 대표하며 학생대표자회 대의원이 된다."},{"k":"hang","x":"③ 자치단체는 부 자치단체장을 둘 수 있으며, 이때 부 자치단체장은 제52조 제3항에 따라 학생대표자회에서 의결권을 가질 수 있다."},{"k":"hang","x":"④ 자치단체장의 선출, 임기, 업무와 권한, 의무 등에 관하여서는 해당 자치단체의 자치규칙으로 정한다."}],"num":141,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a142","label":"제142조","title":"등록","paras":[{"k":"hang","x":"① 자치단체로 등록하고자 하는 단체는 학부운영위원회에 다음 각호의 서류를 제출한다. 이때 서류의 서식은 학부운영위원회에서 정하는 바에 따른다."},{"k":"ho","x":"1. 회원 명부"},{"k":"ho","x":"2. 단체 소개서"},{"k":"ho","x":"3. 180일 이상의 지속적인 단체 활동을 증명하는 자료"},{"k":"ho","x":"4. 사업계획서"},{"k":"ho","x":"5. 학생회칙 준수서약서"},{"k":"hang","x":"② 학부운영위원회는 제1항에 따라 제출받은 서류에 형식상의 결함이 없는지 심의하며, 문제가 없다면 의결로 학생대표자회에 해당 단체의 자치단체 등록에 관한 안건을 상정한다."},{"k":"hang","x":"③ 학생대표자회는 제2항에 따라 상정된 단체의 자치단체 등록을 심의하여 의결한다."},{"k":"hang","x":"④ 학생대표자회는 다음 각호 중 어느 하나에 해당하는 경우에만 자치단체의 등록을 거절할 수 있다. 이때 단체의 특수한 목적 및 사정을 고려하여야 한다."},{"k":"ho","x":"1. 단체의 존속 가능성이 불분명한 경우"},{"k":"ho","x":"2. 단체의 활동과 목적이 본회가 추구하는 가치에 명백히 반하는 경우"},{"k":"ho","x":"3. 10명 미만의 회원만이 활동하는 것으로 판단되는 경우"},{"k":"ho","x":"4. 본회의 회원이 구성원의 2분의 1 미만인 경우"},{"k":"ho","x":"5. 사회상규에 비추어 본회로의 등록이 용인되기 힘든 수준의 사유를 지니는 경우"}],"num":142,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a143","label":"제143조","title":"인준","paras":[{"k":"hang","x":"① 자치단체는 매년 1학기 학생대표자회 정기회의에서 인준을 받아야 한다."},{"k":"hang","x":"② 자치단체는 1학기 학생대표자회 정기회의 개의 7일 전까지 학생대표자회 의장에게 다음 각호의 서류를 제출하여야 한다. 이때 서류의 서식은 학부운영위원회에서 정하는 바에 따른다."},{"k":"ho","x":"1.회원 명부"},{"k":"ho","x":"2.전년도 활동보고서"},{"k":"ho","x":"3.금년도 활동계획서"},{"k":"hang","x":"③ 학생대표자회는 제142조 제4항 각호의 요건을 고려하여 자치단체의 인준을 심의하고 의결한다."}],"num":143,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a144","label":"제144조","title":"재인준","paras":[{"k":"hang","x":"① 제143조에 따른 인준이 부결된 자치단체는 그 해 2학기 학생대표자회 정기회의에서 재인준 절차를 거쳐야 한다."},{"k":"hang","x":"② 제1항에 해당하는 자치단체는 학생대표자회 정기회의 개의 7일 전까지 학생대표자회 의장에게 다음 각호의 서류를 제출하여야 한다. 이때 서류의 서식은 학부운영위원회에서 정하는 바에 따른다."},{"k":"ho","x":"1.회원 명부"},{"k":"ho","x":"2.전년도 활동보고서"},{"k":"ho","x":"3.금년도 활동계획서"},{"k":"ho","x":"4.인준 부결 사유 소명서"},{"k":"hang","x":"③ 학생대표자회는 제142조 제4항 각호의 요건을 고려하여 자치단체의 재인준을 심의하고 의결한다."},{"k":"hang","x":"④ 재인준이 부결된 자치단체는 제146조에 따라 자치공간 및 본회로부터 받았던 모든 자산을 반환하여야 한다."}],"num":144,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a145","label":"제145조","title":"탈퇴","paras":[{"k":"hang","x":"① 자치단체는 본회에서 탈퇴할 수 있다."},{"k":"hang","x":"② 탈퇴하고자 하는 자치단체는 자치단체장과 해당 자치단체의 구성원 3분의 2 이상의 서명을 포함한 탈퇴 요청서를 학부운영위원회에 제출하여야 한다."},{"k":"hang","x":"③ 학부운영위원회는 제2항에 따라 제출된 자치단체의 탈퇴 요청서에 형식상의 결함을 심의한다. 이때 서명의 기준이 되는 자치단체의 구성원 총수는 학부운영위원회에서 의결로 결정한다."},{"k":"hang","x":"④ 탈퇴를 신청한 자치단체의 장은 제3항의 학부운영위원회 회의에 출석하여야 한다."},{"k":"hang","x":"⑤ 학부운영위원회는 제3항의 심의 결과에 문제가 없다면 의결로 학생대표자회에 해당 자치단체의 탈퇴에 관한 안건을 상정한다."},{"k":"hang","x":"⑥ 학생대표자회는 제5항에 따라 상정된 자치단체의 탈퇴를 심의하여 의결한다."},{"k":"hang","x":"⑦ 학생대표자회 의장은 자치단체의 탈퇴가 승인되었으면 이를 지체 없이 공고하고, 공고한 시점으로부터 48시간 동안 이의제기를 받는다."},{"k":"hang","x":"⑧ 제7항의 이의제기가 있을 때는 학생대표자회 의장은 지체 없이 회의를 소집하여 이를 심의하고 인용 여부를 결정한다."},{"k":"hang","x":"⑨ 탈퇴 승인 공고로부터 48시간 이내에 이의가 없거나, 제8항에 따른 이의의 인용이 부결되었을 때 탈퇴를 승인받은 자치단체의 인준 또는 재인준은 취소된다."}],"num":145,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a146","label":"제146조","title":"반환","paras":[{"k":"line","x":"재인준이 부결되거나 탈퇴로 인하여 인준 또는 재인준이 취소된 자치단체는 해당 결정 또는 취소된 날로부터 30일 이내에 자치공간 및 본회로부터 받았던 모든 자산을 본회에 반환하여야 한다."}],"num":146,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a147","label":"제147조","title":"자치규칙","paras":[{"k":"hang","x":"① 자치단체는 자치규칙을 제정하여 자치에 필요한 전반적인 사항을 규정한다."},{"k":"hang","x":"② 자치단체는 자치규칙을 개정하였을 때는 지체 없이 학부운영위원회에 보고하여야 한다."}],"num":147,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제5장 독립기구"},{"t":"h","lv":3,"text":"제1절 통칙"},{"t":"art","id":"a148","label":"제148조","title":"지위","paras":[{"k":"line","x":"독립기구는 본회에서 특별한 공정성과 중립성을 요구하는 업무를 독자적으로 수행하기 위하여 설치된 기구이다."}],"num":148,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a149","label":"제149조","title":"독립성","paras":[{"k":"line","x":"독립기구는 그 권한에 속하는 업무를 수행하는 데 있어서 학생총회 및 학생총투표를 제외한 모든 의결기구, 학부 학생회장단, 집행위원회로부터 독립적인 위상을 보장받는다."}],"num":149,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a150","label":"제150조","title":"의무","paras":[{"k":"hang","x":"① 독립기구는 운영과 업무 수행에 관하여 중립적으로 결정하고 자율적으로 집행하여야 한다."},{"k":"hang","x":"② 독립기구는 운영과 업무 수행에 관하여 공공성과 투명성을 확보하도록 노력하여야 한다."}],"num":150,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 선거관리위원회"},{"t":"art","id":"a151","label":"제151조","title":"목적","paras":[{"k":"line","x":"선거관리위원회는 민주적이고 공정한 절차에 따라 선거를 효율적으로 진행하는 것을 목적으로 한다."}],"num":151,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a152","label":"제152조","title":"구성","paras":[{"k":"hang","x":"① 다음 각호에 해당하는 사람은 선거관리위원이 된다. 단, 학부 학생회장단은 필요한 경우 일부만을 선거관리위원으로 파견할 수 있다."},{"k":"ho","x":"1.학부 학생회장단 전원"},{"k":"ho","x":"2.각 반 학생회에서 파견한 2명"},{"k":"hang","x":"② 학부 학생회장단과 각 반 학생회는 후보 등록 마감일 10일 전까지 위원을 파견하여야 한다."},{"k":"hang","x":"③ 각 반 학생회에서 위원으로 파견되는 사람은 소속 의결기관의 의결을 거쳐야 한다."},{"k":"hang","x":"④ 선거관리위원은 학부운영위원회에서 심사를 거쳐 업무를 개시하여야 한다."},{"k":"hang","x":"⑤ 선거관리위원장은 선거관리위원회 내부에서 선출한다."}],"num":152,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a153","label":"제153조","title":"업무ㆍ권한","paras":[{"k":"hang","x":"① 선거관리위원회는 회칙ㆍ세칙ㆍ규칙에 따라 민주적이고 공정한 선거 절차를 진행한다."},{"k":"hang","x":"② 선거관리위원회는 선거에 관한 모든 업무의 최고 결정권과 집행권을 가지며, 학생총회와 학생총투표를 제외한 어떠한 의결기구도 회칙에 따른 선거 관련 결정 및 집행을 변경 또는 취소할 수 없다. 단, 학생대표자회는 선거관리위원회의 선거 관련 결정 및 집행에 의견을 제출할 수 있고 선거관리위원회는 이를 존중하여야 한다."},{"k":"hang","x":"③ 학부 학생회장단, 집행위원회 및 학부운영위원회는 선거기간에 사업 집행 및 의견 표명 등을 하기 위해서는 선거관리위원회의 허가를 받아야 하며, 선거관리위원회는 선거에 영향을 미칠 수 있다고 인정되는 행위를 허가하지 않을 수 있다."},{"k":"hang","x":"④ 선거관리위원회는 선거의 원활한 진행을 위하여 집행위원회에 사무 처리의 협조를 얻을 수 있다."}],"num":153,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a154","label":"제154조","title":"재정","paras":[{"k":"line","x":"본회는 선거관리위원회의 원활한 운영을 위한 재원을 마련하여야 한다."}],"num":154,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a155","label":"제155조","title":"선거시행세칙","paras":[{"k":"line","x":"그 밖의 선거관리위원회에 관한 자세한 사항은 ｢고려대학교 자유전공학부 학부ㆍ반 선거시행세칙｣으로 정한다."}],"num":155,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제3절 투표관리위원회"},{"t":"art","id":"a156","label":"제156조","title":"목적","paras":[{"k":"line","x":"투표관리위원회는 민주적이고 공정한 절차에 따라 학생총투표를 효율적으로 진행하는 것을 목적으로 한다."}],"num":156,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a157","label":"제157조","title":"구성","paras":[{"k":"line","x":"투표관리위원회는 학생총투표 시행이 결정되면 학생총회 의장을 위원장으로 하여 학부운영위원, 제79조 제3항에 따라 의결권을 가질 수 있는 사람 및 이에 준하는 사람을 위원으로 구성한다. 단, 학부 학생회장단은 학부 학생회장단 탄핵안에 대한 학생총투표에서는 투표관리위원이 될 수 없다."}],"num":157,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a158","label":"제158조","title":"업무ㆍ권한","paras":[{"k":"hang","x":"① 투표관리위원회는 회칙ㆍ세칙ㆍ규칙에 따라 민주적이고 공정한 학생총투표 절차를 진행한다."},{"k":"hang","x":"② 투표관리위원회는 학생총투표에 관한 모든 업무의 최고 결정권과 집행권을 가지며, 학생총회를 제외한 어떠한 의결기구도 회칙에 따른 학생총투표 관련 결정 및 집행을 변경 또는 취소할 수 없다. 단, 학생대표자회는 투표관리위원회의 학생총투표 관련 결정 및 집행에 의견을 제출할 수 있고 투표관리위원회는 이를 존중하여야 한다."},{"k":"hang","x":"③ 학부 학생회장단 및 집행위원회는 학생총투표 기간에 사업 집행 및 의견 표명 등을 하기 위해서는 투표관리위원회의 허가를 받아야 하며, 투표관리위원회는 학생총투표에 영향을 미칠 수 있다고 인정되는 행위를 허가하지 않을 수 있다."},{"k":"hang","x":"④ 투표관리위원회는 학생총투표의 원활한 진행을 위하여 집행위원회에 시행 준비를 보조받을 수 있다."}],"num":158,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a159","label":"제159조","title":"재정","paras":[{"k":"line","x":"본회는 투표관리위원회의 원활한 운영을 위한 재원을 마련하여야 한다."}],"num":159,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a160","label":"제160조","title":"준용","paras":[{"k":"line","x":"그 밖의 투표관리위원회에 관한 자세한 사항은 ｢고려대학교 자유전공학부 학부ㆍ반 선거시행세칙｣의 선거관리위원회에 관한 규정을 준용한다."}],"num":160,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제6장 특별기구"},{"t":"h","lv":3,"text":"제1절 통칙"},{"t":"art","id":"a161","label":"제161조","title":"지위","paras":[{"k":"hang","x":"① 특별기구는 본회의 특수한 영역과 기능을 담당하기 위하여 설치된 상설기구이다."},{"k":"hang","x":"② 특별기구는 학부 학생회장단으로부터 그 업무의 감독을 받는다. 다만, 집행위원회로부터는 독립적인 위상을 보장받는다."}],"num":161,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a162","label":"제162조","title":"성립 요건","paras":[{"k":"line","x":"특별기구는 다음 각호 중 어느 하나 이상의 요건을 갖추어 설치가 필요하다고 인정될 때 설치된다."},{"k":"ho","x":"1. 본회 회원의 권익 보호를 위한 전문적 활동을 꾸준히 수행하여 특별기구로서의 정체성이 확보되어 있는 단체"},{"k":"ho","x":"2. 본회 차원의 포괄적ㆍ대외적 사업이 필요한 분야에 관련된 단체"}],"num":162,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a163","label":"제163조","title":"회원","paras":[{"k":"hang","x":"① 본회의 회원은 특별기구의 회원이 될 수 있다."},{"k":"hang","x":"② 특별기구 회원의 유형ㆍ권리 및 의무 등에 관하여서는 해당 특별기구의 자치규칙으로 정한다."}],"num":163,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a164","label":"제164조","title":"기구장","paras":[{"k":"hang","x":"① 특별기구장은 해당 특별기구의 자치규칙에 따라 회원의 보통ㆍ평등ㆍ직접ㆍ비밀선거로 선출함을 원칙으로 한다."},{"k":"hang","x":"② 특별기구장은 해당 특별기구를 대표한다."},{"k":"hang","x":"③ 특별기구장은 제52조 제4항에 따라 한시적으로 학생대표자회의 대의원이 될 수 있다."}],"num":164,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a165","label":"제165조","title":"재정","paras":[{"k":"hang","x":"① 특별기구는 학부 학생회비에서 제186조 제3항에 따라 재정의 배분을 받는다."},{"k":"hang","x":"② 특별기구는 재정 배분에 관한 결정이 이루어지는 각종 절차에 참가할 권리가 있다."},{"k":"hang","x":"③ 특별기구는 제188조 제1항에 따라 예산안ㆍ결산을 작성하여 학생대표자회 정기회의 개의 7일 전까지 학부운영위원회에 제출하여야 한다."},{"k":"hang","x":"④ 특별기구는 학부운영위원회에 출석하여 제3항에 따라 제출한 예산안ㆍ결산을 보고하여야 한다."}],"num":165,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a166","label":"제166조","title":"자치규칙","paras":[{"k":"hang","x":"① 특별기구는 자치규칙을 제정하여 자치에 필요한 전반적인 사항을 규정한다."},{"k":"hang","x":"② 특별기구는 자치규칙을 개정하였을 때는 지체 없이 학부운영위원회에 보고하여야 한다."}],"num":166,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a167","label":"제167조","title":"협의","paras":[{"k":"hang","x":"① 특별기구는 학부운영위원회에 출석하여 사업을 제안하거나 협의할 수 있다."},{"k":"hang","x":"② 특별기구는 사업의 기획과 집행에 관하여 필요한 경우 집행위원회와 협의할 수 있다."}],"num":167,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 인준"},{"t":"art","id":"a168","label":"제168조","title":"인준","paras":[{"k":"hang","x":"① 특별기구로 인준되고자 하는 단체는 학부운영위원회에 다음 각호의 서류를 제출한다. 이때 서류의 서식은 학부운영위원회에서 정하는 바에 따른다."},{"k":"ho","x":"1. 회원명부"},{"k":"ho","x":"2. 소개서"},{"k":"ho","x":"3. 사업계획서"},{"k":"ho","x":"4. 학생회칙 준수서약서"},{"k":"ho","x":"5. 예산안"},{"k":"ho","x":"6. 본회의 회원 30명 이상의 추천이 있는 추천서"},{"k":"hang","x":"② 학부운영위원회는 제1항에 따라 제출받은 서류를 검토하여 형식상의 결함과 해당 단체가 제162조 각호의 요건 중 어느 하나 이상을 충족하는지를 심의하며, 문제가 없다면 의결로 학생대표자회에 해당 단체의 특별기구 인준에 관한 안건을 상정한다."},{"k":"hang","x":"③ 학부운영위원회는 제2항에 따라 안건을 상정할 때는 심의서를 작성하여 안건과 함께 학생대표자회에 제출한다."},{"k":"hang","x":"④ 학생대표자회는 제2항에 따라 상정된 단체의 특별기구 인준을 심의하여 의결한다."}],"num":168,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a169","label":"제169조","title":"재인준","paras":[{"k":"hang","x":"① 특별기구는 매년 1학기 학생대표자회 정기회의 개의 7일 전까지 학부운영위원회에 다음 각호의 서류를 제출하여야 한다. 이때 서류의 서식은 학부운영위원회에서 정하는 바에 따른다."},{"k":"ho","x":"1.회원 명부"},{"k":"ho","x":"2.전년도 활동보고서"},{"k":"ho","x":"3.금년도 활동계획서"},{"k":"hang","x":"② 학부운영위원회는 제1항에 따라 제출된 서류를 검토하여 형식상의 결함과 해당 특별기구가 제162조 각호의 요건 중 어느 하나 이상을 충족하는지를 심의하며, 문제가 없다면 의결로 학생대표자회에 각 특별기구의 재인준에 관한 안건을 상정한다."},{"k":"hang","x":"③ 학부운영위원회는 제2항의 재인준에 관한 안건 상정이 부결될 때는 해당 특별기구의 부결 사유를 포함한 심의서를 작성하여 학생대표자회에 별도의 안건으로 상정하여야 한다."},{"k":"hang","x":"④ 제2항의 재인준에 관한 안건 상정이 부결된 특별기구는 학생대표자회에 그 심의 부결에 대한 소명서를 작성하여 제출하여야 한다."},{"k":"hang","x":"⑤ 학생대표자회는 제2항과 제3항에 따라 상정된 특별기구의 재인준을 심의하고 의결한다."},{"k":"hang","x":"⑥ 학생대표자회 의장은 제5항의 심의에서 재인준이 부결되면 즉시 제72조에 따라 해당 특별기구의 징계 안건을 상정한다."}],"num":169,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a169-2","label":"제169조의2","title":"해산","paras":[{"k":"hang","x":"① 특별기구는 해산할 수 있다."},{"k":"hang","x":"② 해산하고자 하는 특별기구는 학부운영위원회에 직전 재인준 당시 제출한 회원명부를 기준으로 재적 회원 3분의 2 이상의 서명을 포함한 해산 요청서를 제출하여야 한다."},{"k":"hang","x":"③ 제168조에 따라 최초 인준된 날로부터 2년(4학기)이 경과하지 아니한 특별기구는 해산을 신청할 수 없다. 단, 기구의 존속이 불가능한 중대한 사유가 있는 경우 학부운영위원회의 의결로 예외를 둘 수 있다."},{"k":"hang","x":"④ 학부운영위원회는 제2항에 따라 제출된 해산 요청서 형식상 결함을 심의하며, 특별기구장은 해당 심의에 출석하여야 한다."},{"k":"hang","x":"⑤ 학부운영위원회는 해산 요청서에 결함이 없으면 학생대표자회에 해당 특별기구의 해산 안건을 상정한다."},{"k":"hang","x":"⑥ 학생대표자회는 해산 여부를 의결하며 해산을 승인받은 특별기구의 인준 또는 재인준은 그 승인 시점부터 48시간 이후에 취소된다."},{"k":"hang","x":"⑦ 학생대표자회는 다음 각호의 경우 해산을 거절할 수 있다."},{"k":"ho","x":"1.특별기구가 여전히 본회의 특수한 기능을 수행할 수 있으며, 해산 시 회원의 권리가 침해될 것이 예상되는 때"},{"k":"ho","x":"2.해산 요청서의 서식 및 정보가 부실하여 무효라고 판단되는 때"},{"k":"ho","x":"3.회칙에 명시된 해산 이외의 절차가 선행될 수 있을 때"}],"num":169,"sub":2,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제7장 선거"},{"t":"h","lv":3,"text":"제1절 학부 학생회장단 선거"},{"t":"art","id":"a170","label":"제170조","title":"선거","paras":[{"k":"hang","x":"① 학부 학생회장단은 회원의 보통ㆍ평등ㆍ직접ㆍ비밀선거로 선출한다."},{"k":"hang","x":"② 학부 학생회장단 선거에는 학부 학생회장 후보 단독으로 입후보하거나 학부 학생회장 후보와 학부 부학생회장 후보 각 한 명이 조를 이루어 입후보할 수 있다."},{"k":"hang","x":"③ 유효투표 중 최다 득표한 조 또는 후보에 대한 “찬성”표의 수가 “반대” 및 “기권”표의 합보다 많은 조가 학부 학생회장단으로 당선된다."}],"num":170,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a171","label":"제171조","title":"시기","paras":[{"k":"hang","x":"① 학부 학생회장단 선거는 매년 11월에 시행함을 원칙으로 한다."},{"k":"hang","x":"② 학부 학생회장단 선거에 관한 자세한 일정은 학부운영위원회에서 정한다."}],"num":171,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a172","label":"제172조","title":"선거권ㆍ피선거권","paras":[{"k":"hang","x":"① 본회의 정회원은 학부 학생회장단 선거의 선거권을 가지며, 선거권자 총수에 포함된다."},{"k":"hang","x":"② 제1항에도 불구하고 본회의 국제 회원은 학부 학생회장단 선거의 선거권을 행사한 경우에만 선거권자 총수에 포함된다."},{"k":"hang","x":"③ 본회의 준회원ㆍ수료회원은 학부 학생회장단 선거의 선거권을 가지며, 선거권을 행사한 경우에만 선거권자 총수에 포함된다."},{"k":"hang","x":"④ 본회의 정회원으로서, 3학기 이상 등록한 자는 학부 학생회장단 선거의 피선거권이 있다."}],"num":172,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a173","label":"제173조","title":"선거관리위원회","paras":[{"k":"hang","x":"① 학부 학생회장단 선거를 공정하고 민주적으로 관리하기 위하여 선거관리위원회를 둔다."},{"k":"hang","x":"② 그 밖의 선거관리위원회에 관한 자세한 사항은 제151조부터 제155조까지를 따른다."}],"num":173,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a174","label":"제174조","title":"재선거","paras":[{"k":"hang","x":"① 다음 각호 중 어느 하나에 해당하면 재선거를 시행한다. 다만, 조를 이루어 당선된 학부 학생회장단 당선 조에서 한 명만 제3호 또는 제4호에 해당할 때는 그러하지 아니한다."},{"k":"ho","x":"1. 학부 학생회장단 선거의 후보자가 없는 경우"},{"k":"ho","x":"2. 학부 학생회장단 선거의 당선인이 없는 경우"},{"k":"ho","x":"3. 학부 학생회장단 당선인이 임기 개시 전에 사망한 경우"},{"k":"ho","x":"4. 학부 학생회장단 당선인이 임기 개시 전에 선거권ㆍ피선거권 박탈 이상의 징계를 받은 경우"},{"k":"ho","x":"5. 학부 학생회장단 당선인이 소속된 선거운동본부가 임기 개시 전에 ｢고려대학교 자유전공학부 학부ㆍ반 선거시행세칙｣에서 정한 징계 사유가 새로 발견되어 후보 자격이 박탈된 경우"},{"k":"ho","x":"6. 그 밖의 ｢고려대학교 자유전공학부 학부ㆍ반 선거시행세칙｣에서 정한 사유가 발생한 경우"},{"k":"hang","x":"② 재선거는 제1항의 사유가 발생한 이듬해 3월에 실시함을 원칙으로 한다."},{"k":"hang","x":"③ 제2항에 따른 재선거가 무산되어 실시하는 재선거는 같은 해 11월에 시행함을 원칙으로 한다."},{"k":"hang","x":"④ 제3항에 따른 재선거가 무산된 이후 시행하는 재선거의 시기에 관하여서는 제2항 및 제3항을 준용한다."},{"k":"hang","x":"⑤ 제2항 및 제3항에 따라 시행하는 재선거에는 차수를 표시하여 이전 재선거와 구분한다."},{"k":"hang","x":"⑥ 재선거에 관한 자세한 일정은 학부운영위원회 또는 비상대책위원회에서 정한다."}],"num":174,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a175","label":"제175조","title":"보궐선거","paras":[{"k":"hang","x":"① 학부 학생회장단이 사퇴ㆍ탄핵 및 당연퇴직 등으로 궐위되었으며, 잔여 임기가 180일을 초과하면 보궐선거를 시행한다."},{"k":"hang","x":"② 학부운영위원회는 제1항의 사유가 발생한 날부터 10일 이내에 보궐선거의 시행 일정을 결정하여야 한다."},{"k":"hang","x":"③ 학부운영위원회는 보궐선거의 시행 일정이 확정한 날로부터 20일 이내에 보궐선거를 시행하여야 한다."},{"k":"hang","x":"④ 학부운영위원회는 잔여 임기가 180일이 넘지 않은 경우에도 선거의 필요성, 선거 시기, 잔여 임기 등 본회의 제반 사정을 고려하여 보궐선거의 시행을 결정할 수 있다."}],"num":175,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a176","label":"제176조","title":"선거시행세칙","paras":[{"k":"line","x":"그 밖의 선거에 관한 사항은 ｢고려대학교 자유전공학부 학부ㆍ반 선거시행세칙｣으로 정한다."}],"num":176,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 동시선거"},{"t":"art","id":"a177","label":"제177조","title":"동시선거","paras":[{"k":"line","x":"본 회칙에서 “동시선거”라 함은 본회 및 본회 각 반 학생회의 학생회장단 선거 중 2 이상의 선거를 동일한 일정에 따라 시행하는 것을 말한다."}],"num":177,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a178","label":"제178조","title":"동시선거의 진행","paras":[{"k":"hang","x":"① 학부운영위원회는 의결로 동시선거를 진행할 수 있다."},{"k":"hang","x":"② 동시선거에 관한 자세한 일정은 학부운영위원회에서 정한다."},{"k":"hang","x":"③ 동시선거에 있어서 선거의 진행은 본 회칙 및 ｢고려대학교 자유전공학부 학부ㆍ반 선거시행세칙｣에 따른다."},{"k":"hang","x":"④ 제2항에도 불구하고 동시선거에 있어서 다음 각호의 경우는 각 반 학생회의 자치규칙에 따른다. 이때 제3호의 경우 학부운영위원회의 의결로 결정한다."},{"k":"ho","x":"1.각 반 학생회장단 선거의 피선거권"},{"k":"ho","x":"2.각 반 학생회장단 당선인의 임기"},{"k":"ho","x":"3.그 밖의 각 반 학생회의 자치규칙에 따르는 것이 적절하다고 인정된 경우"},{"k":"hang","x":"⑤ 동시선거를 진행하지 않는 경우 각 반 학생회장단 선거의 진행은 각 반 학생회의 자치규칙에 따른다."}],"num":178,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제8장 재정"},{"t":"h","lv":3,"text":"제1절 통칙"},{"t":"art","id":"a179","label":"제179조","title":"원칙","paras":[{"k":"line","x":"본회의 각 기구는 재정을 효율적이고 투명하게 운용하여야 한다."}],"num":179,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a180","label":"제180조","title":"재정운용세칙","paras":[{"k":"line","x":"그 밖의 재정 운용에 관한 사항은 각 의결기구의 의결로 ｢고려대학교 총학생회 재정운용세칙｣을 준용한다."}],"num":180,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 자산"},{"t":"art","id":"a181","label":"제181조","title":"자산","paras":[{"k":"hang","x":"① 본회는 유ㆍ무형의 동산, 부동산 및 권리 등을 소유할 수 있으며, 이를 본회의 자산이라 한다."},{"k":"hang","x":"② 본회의 자산은 각 기구가 독립하여 취득ㆍ사용ㆍ보관 및 처분함을 원칙으로 한다."},{"k":"hang","x":"③ 본회의 산하기구 및 특별기구는 회칙의 취지에 어긋나지 아니하는 범위에서 그 자산에 관하여 필요한 사항을 각 기구의 의결기관의 의결 또는 자치규칙으로 정할 수 있다."}],"num":181,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a182","label":"제182조","title":"집행기구 자산","paras":[{"k":"line","x":"다음 각호 중 어느 하나에 해당하는 것은 집행기구의 자산으로 본다."},{"k":"ho","x":"1. 취득 과정에서 본회의 자산이 투입되어 취득한 것"},{"k":"ho","x":"2. 학부 학생회장단, 집행위원 또는 이에 준하는 자가 그 직으로 취득한 것"},{"k":"ho","x":"3. 본회 집행기구의 사업 또는 사무 집행을 위하여 취득하였거나 사업 집행의 결과물로 취득한 것"},{"k":"ho","x":"4. 제1호부터 제3호까지에 해당하는 자산으로부터 파생된 것"}],"num":182,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a183","label":"제183조","title":"자산의 관리","paras":[{"k":"hang","x":"① 집행기구는 자산의 취득ㆍ사용ㆍ보관 및 처분이 본회의 이익을 위하여 적정하고 효율적으로 이루어지도록 노력하여야 한다."},{"k":"hang","x":"② 집행기구는 제작, 구매, 수증 등의 방법으로 자산을 취득한다."},{"k":"hang","x":"③ 집행기구의 자산은 본회 사업과 사무의 집행을 위하여 사용함을 원칙으로 한다."},{"k":"hang","x":"④ 집행기구의 자산은 대여를 목적으로 한 자산이거나 대여하여도 본회 사업 또는 사무에 지장이 없는 자산이어야만 대여할 수 있으며, 본회의 각 기구와 회원에게 우선으로 대여하여야 한다."},{"k":"hang","x":"⑤ 집행기구는 자산을 언제든지 사용하거나 처분할 수 있도록 선량한 관리자의 주의로 보관하여야 한다."},{"k":"hang","x":"⑥ 집행기구는 사용할 필요가 없거나 사용할 수 없는 자산을 교환, 매각, 증여, 폐기 등의 방법으로 처분할 수 있다."},{"k":"hang","x":"⑦ 집행기구는 자산의 중대한 변화를 불러오는 집행에 관하여 학부운영위원회의 인준을 받아야 한다."},{"k":"hang","x":"⑧ 집행기구는 제7항에 따라 인준받은 집행을 회원들에게 예고하여야 하며, 해당 집행 이후 자산 변화를 공고하여야 한다."}],"num":183,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a184","label":"제184조","title":"취소ㆍ변경","paras":[{"k":"line","x":"학부운영위원회는 집행기구의 자산 취득, 사용, 보관 및 처분이 본회의 이익을 위한 것이 아니거나, 적정성 또는 효율성이 없다고 판단되면 이를 변경하거나 취소할 수 있다."}],"num":184,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a185","label":"제185조","title":"수입","paras":[{"k":"line","x":"본회 재정의 수입은 학부 학생회비, 지원금, 사업별 후원금, 그 밖의 수익금으로 한다."}],"num":185,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a186","label":"제186조","title":"학생회비","paras":[{"k":"hang","x":"① 학부 학생회비는 일시납부 및 1회 납부를 원칙으로 한다. 단, 일시에 납부하지 못할 경제적ㆍ사회적 또는 그 밖의 중대한 사유가 있는 경우 분할하여 납부할 수 있다."},{"k":"hang","x":"② 학부 학생회비의 수입 중 반 학생회에 배분되는 금액은 반 학생회 소속 학생회비 납부자 1인당 50,000원으로 한다."},{"k":"hang","x":"③ 학부 학생회비의 수입 중 특별기구에 배분되는 금액은 학부운영위원회에서 각 특별기구와 협의하여 결정한다."},{"k":"hang","x":"④ 학부 학생회비의 수입 중 집행기구에 배분되는 금액은 제2항 및 제3항에 따라 배분되는 금액을 제외한 금액으로 한다."},{"k":"hang","x":"⑤ 다음 각호에 해당하는 기구의 재정은 제4항에 따른 집행기구 재정에서 사용하며, 재정 운용의 책임은 집행위원회에 있다."},{"k":"ho","x":"1.의결기구"},{"k":"ho","x":"2.자치단체"},{"k":"ho","x":"3.독립기구"},{"k":"hang","x":"⑥ 학생대표자회는 학부 학생회비의 인상ㆍ인하가 필요하다고 판단하면 매년 2학기 정기회의에서 학부 학생회비의 조정을 논의할 수 있다."}],"num":186,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제3절 회계ㆍ심의"},{"t":"art","id":"a187","label":"제187조","title":"회계연도","paras":[{"k":"line","x":"본회의 재정은 다음 각호의 기간으로 나누어 집행하고 결산한다."},{"k":"ho","x":"1. 제1분기: 2학기 종강일 다음 날부터 1학기 개강일 전날까지"},{"k":"ho","x":"2. 제2분기: 1학기 개강일부터 1학기 종강일까지"},{"k":"ho","x":"3. 제3분기: 1학기 종강일 다음 날부터 2학기 개강일 전날까지"},{"k":"ho","x":"4. 제4분기: 2학기 개강일부터 2학기 종강일까지"}],"num":187,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a188","label":"제188조","title":"사전 심의","paras":[{"k":"hang","x":"① 집행위원회, 반 학생회, 특별기구 및 그 밖의 학부 학생회비를 사용하는 기구는 다음 각호에 따라 예산안ㆍ결산을 작성하여 학생대표자회 정기회의 개의 7일 전까지 학부운영위원회에 제출하여야 한다."},{"k":"ho","x":"1. 1학기 정기회의: 작년도 4분기, 금년도 1분기의 결산과 금년도 2분기ㆍ3분기의 예산안"},{"k":"ho","x":"2. 2학기 정기회의: 금년도 2분기ㆍ3분기의 결산과 금년도 4분기, 익년도 1분기의 예산안"},{"k":"hang","x":"② 학부운영위원회는 제1항에 따른 예산안ㆍ결산 제출 기한을 정하여 공고한다."},{"k":"hang","x":"③ 학부운영위원회는 제1항에 따라 제출된 예산안ㆍ결산을 사전 심의한다."}],"num":188,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a189","label":"제189조","title":"승인","paras":[{"k":"hang","x":"① 집행위원회, 반 학생회, 특별기구 및 그 밖의 학부 학생회비를 사용하는 기구는 제188조 제3항의 사전 심의를 거친 예산안ㆍ결산을 학생대표자회에 보고하여야 한다."},{"k":"hang","x":"② 학생대표자회는 제1항에 따라 보고된 예산안ㆍ결산을 승인한다."},{"k":"hang","x":"③ 학생대표자회에서 승인된 예산안ㆍ결산은 공개되어야 한다."}],"num":189,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a190","label":"제190조","title":"징계","paras":[{"k":"hang","x":"① 학생대표자회는 제189조 제2항의 회의에서 다음 각호 중 어느 하나에 해당하는 기구가 있으면 제2항에 따라 징계한다."},{"k":"ho","x":"1. 학생대표자회 또는 학부운영위원회에 예산안ㆍ결산을 제출하지 아니한 기구"},{"k":"ho","x":"2. 학생대표자회에서 예산안ㆍ결산 승인이 부결된 기구"},{"k":"hang","x":"② 제1항에 따른 징계는 다음 각호 중 하나로 한다. 단, 제4호의 경우 다른 징계와 함께 하도록 결정할 수 있다."},{"k":"ho","x":"1. 해당 학기의 학부 학생회비 미지급"},{"k":"ho","x":"2. 해당 학기의 학부 학생회비 지급액 삭감"},{"k":"ho","x":"3. 해당 학기의 학부 학생회비 지급 보류"},{"k":"ho","x":"4. 사과문ㆍ경위서 게재 요구"},{"k":"hang","x":"③ 배임, 횡령 등 중대한 문제의 경우 학생대표자회는 제2항의 징계와 함께 다음 각호의 조치를 함께 결정할 수 있다. 이때 제3호의 경우 제1항 당시 대표자와 학부 학생회비가 불법하게 사용될 당시 대표자가 함께 책임을 져야 한다."},{"k":"ho","x":"1. 기구가 가지고 있는 학부 학생회비 잔금 사용 중지"},{"k":"ho","x":"2. 기구가 가지고 있는 학부 학생회비 잔금 전액 환수"},{"k":"ho","x":"3. 기구가 불법하게 사용한 학부 학생회비 전액 반환"},{"k":"ho","x":"4. 그 밖의 ｢고려대학교 자유전공학부 징계세칙｣에 따른 징계"}],"num":190,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제9장 자치공간"},{"t":"art","id":"a191","label":"제191조","title":"목적","paras":[{"k":"line","x":"본회의 자치공간은 본회의 자치활동의 기초가 되는 토대로서, 회원의 교류 및 결속을 공고히 하고 회원을 보호하며 안정을 보장하는 역할을 통해 창조적이고 진보적인 대학 문화를 건설하는데 이바지함을 목적으로 한다."}],"num":191,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a192","label":"제192조","title":"자치공간","paras":[{"k":"hang","x":"① 본회의 자치공간은 다음 각호로 정한다."},{"k":"ho","x":"1. 학부 학생회실"},{"k":"ho","x":"2. 반 학생회실"},{"k":"ho","x":"3. 자치단체실"},{"k":"ho","x":"4. 특별기구실"},{"k":"ho","x":"5. 코웍스"},{"k":"ho","x":"6. 범울터"},{"k":"ho","x":"7. 기타 본회의 노력으로 확보 또는 양도받은 공간"},{"k":"hang","x":"② 본회의 각 기구는 각 기구에 주어진 자치공간을 자유롭게 이용, 보수 및 개조할 수 있다."}],"num":192,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a193","label":"제193조","title":"자치공간운영세칙","paras":[{"k":"line","x":"그 밖의 자치공간에 관한 자세한 내용은 ｢고려대학교 자유전공학부 자치공간운영세칙｣으로 정한다."}],"num":193,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제10장 회칙ㆍ세칙ㆍ규칙"},{"t":"h","lv":3,"text":"제1절 회칙 개정"},{"t":"art","id":"a194","label":"제194조","title":"개정안 발의","paras":[{"k":"hang","x":"① 회칙 개정안은 다음 각호 중 하나에 따라 발의된다."},{"k":"ho","x":"1. 학부운영위원회 의결에 의한 발의"},{"k":"ho","x":"2. 학부운영위원회 재적 위원 과반수의 연서에 따른 발의"},{"k":"ho","x":"3. 학생대표자회 재적 위원 3분의 1 이상의 연서에 따른 발의"},{"k":"ho","x":"4. 본회의 회원 50명 이상의 연서에 따른 발의"},{"k":"ho","x":"5. 본회의 의결기구가 회칙 개정 발의에 관한 권한을 위임한 특별위원회의 발의"},{"k":"hang","x":"② 연서에 따른 발의는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식에 의한다."}],"num":194,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a195","label":"제195조","title":"개정안 공고","paras":[{"k":"line","x":"학생대표자회 의장은 회칙 개정안이 발의되면 다음 각호의 사항을 5일 이상 공고하여야 한다. 단, 회칙 개정안이 전부개정안이면 제2호를 개정안 전문으로 대신할 수 있다."},{"k":"ho","x":"1. 회칙 개정안의 제안 이유와 주요 내용"},{"k":"ho","x":"2. 신ㆍ구조문 대비표"},{"k":"ho","x":"3. 제194조에 따른 회칙 개정안 발의자 명단"}],"num":195,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a196","label":"제196조","title":"의견 수렴","paras":[{"k":"line","x":"회칙 개정안을 발의한 자의 대표는 회칙 개정을 위한 학생대표자회 개의에 앞서 학부운영위원회에 의견을 요청하거나, 별도의 공청회 등을 통하여 의견을 수렴할 수 있다."}],"num":196,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a197","label":"제197조","title":"개정안 심의","paras":[{"k":"hang","x":"① 학생대표자회는 제194조에 따라 발의된 회칙 개정안을 심의한다."},{"k":"hang","x":"② 개정안 심의 과정에는 축조심사와 찬반 토론이 포함되어야 한다. 단, 일부개정안은 의결로 축조심사를 생략할 수 있다."}],"num":197,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a198","label":"제198조","title":"개정 의결","paras":[{"k":"hang","x":"① 학생대표자회는 제61조 제2항 제2호에 따라 재적 대의원 3분의 2 이상의 출석과 출석 대의원 3분의 2 이상의 찬성으로 회칙 개정을 의결한다."},{"k":"hang","x":"② 회칙 개정의 의결은 제62조 제4항에 따라 기명투표로 표결한다."}],"num":198,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a199","label":"제199조","title":"개정안 정리","paras":[{"k":"line","x":"회칙 개정의 의결 후 저촉되는 조항ㆍ자구ㆍ숫자 및 그 밖의 기타 정리가 필요하면 학부운영위원회는 회칙 개정의 공포 전까지 이를 검토하여 정리할 수 있다. 단, 정리 과정에서 의결된 사항의 내용이나 취지를 변경하는 것은 허용되지 아니한다."}],"num":199,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a200","label":"제200조","title":"공포","paras":[{"k":"hang","x":"① 학부 학생회장은 회칙 개정이 의결되면 개정안 정리를 거쳐 지체 없이 공포한다."},{"k":"hang","x":"② 회칙의 공포문에는 다음 각호의 사항이 포함되어야 한다. 단, 회칙 개정안이 전부개정안이면 신ㆍ구조문 대비표를 생략할 수 있다."},{"k":"ho","x":"1. 회칙 개정안의 제안 이유와 주요 내용"},{"k":"ho","x":"2. 신ㆍ구조문 대비표 및 해당 개정안 전문"},{"k":"ho","x":"3. 제194조에 따른 회칙 개정안 발의자 명단"},{"k":"ho","x":"4. 회칙 개정 찬성자 명단"},{"k":"hang","x":"③ 회칙을 온라인으로 배포할 때는 조문의 수정이 불가능한 파일로 배포한다."},{"k":"hang","x":"④ 학부운영위원회는 학부 학생회장이 개정 의결된 회칙의 공포를 정당한 사유 없이 상당한 기간 지체하였다고 인정할 때는 해당 개정안을 의결로 공포할 수 있다."}],"num":200,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 세칙"},{"t":"art","id":"a201","label":"제201조","title":"세칙","paras":[{"k":"line","x":"세칙은 회칙에서 위임한 사항과 회칙을 시행하기 위한 사항을 규정한다."}],"num":201,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a202","label":"제202조","title":"세칙의 제정ㆍ개정ㆍ폐지","paras":[{"k":"hang","x":"① 세칙의 제정ㆍ개정ㆍ폐지는 제61조 제3항에 따라 학생대표자회 재적 대의원 과반수의 출석과 출석 대의원 3분의 2 이상의 찬성으로 의결한다."},{"k":"hang","x":"② 세칙 제정의 공포 시에는 세칙의 제정 순서에 따라 번호를 붙여서 공포한다."},{"k":"hang","x":"③ 그 밖의 세칙의 제정ㆍ개정ㆍ폐지에 관하여서는 제194조부터 제200조까지를 준용한다."}],"num":202,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제3절 규칙"},{"t":"art","id":"a203","label":"제203조","title":"규칙","paras":[{"k":"hang","x":"① 규칙은 회칙 및 세칙에서 위임한 사항 및 그 밖에 본회의 운영에 필요한 사항을 규정한다."},{"k":"hang","x":"② 규칙은 다음 각호에 따라 나눈다."},{"k":"ho","x":"1.세칙에 부수된 규칙: 세칙의 시행 및 운영 등에 필요한 사항"},{"k":"ho","x":"2.일반규칙: 규칙을 통하여 일반적으로 규정이 필요한 사항"},{"k":"ho","x":"3.임시규칙: 규칙을 통하여 한시적으로 규정이 필요한 사항"},{"k":"hang","x":"③ 규칙의 제정ㆍ개정ㆍ폐지의 의결은 제87조 제3항에 따라 기명투표로 표결한다."},{"k":"hang","x":"④ 규칙 제정의 공포 시에는 규칙의 제정 순서에 따라 번호를 붙여서 공포한다. 단, 세칙에 부수된 규칙은 그 제정의 근거가 된 세칙별로 번호를 붙인다."}],"num":203,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a204","label":"제204조","title":"규칙의 제정ㆍ개정ㆍ폐지","paras":[{"k":"hang","x":"① 학부운영위원회는 제96조 제3항 및 각 세칙으로 정한 바에 따라 세칙에 부수된 규칙을 제정ㆍ개정ㆍ폐지할 수 있다."},{"k":"hang","x":"② 학부운영위원회는 제96조 제4항에 따라 일반규칙 및 임시규칙을 제정ㆍ개정ㆍ폐지할 수 있다."}],"num":204,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제4절 해석"},{"t":"art","id":"a205","label":"제205조","title":"회칙 해석의 원칙","paras":[{"k":"hang","x":"① 회칙을 해석ㆍ적용함에 있어서는 해당 조항의 문맥적 의미와 회칙 전체의 논리적 체계성에 비추어 본회의 민주적 운영이 저해되거나 회원의 권리가 부당하게 침해되지 않도록 주의하여야 한다."},{"k":"hang","x":"② 본회의 중요 사항과 회원의 권리ㆍ의무에 중대한 변화를 불러오는 회칙의 해석은 본회의 회원을 상대로 의견을 수렴하기 위한 공청회를 개최할 수 있다."},{"k":"hang","x":"③ 세칙ㆍ규칙에 관하여서도 본조를 적용한다."},{"k":"hang","x":"④ 다음 각호에 해당하는 세칙ㆍ규칙 및 자치규칙은 그 위반되는 부분에 한정하여 효력이 없다."},{"k":"ho","x":"1.회칙에 위반되는 세칙"},{"k":"ho","x":"2.회칙 및 세칙에 위반되는 규칙"},{"k":"ho","x":"3.회칙에 위반되는 산하기구 및 특별기구의 자치규칙"}],"num":205,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a205-2","label":"제205조의2","title":"회칙해석위원회","paras":[{"k":"hang","x":"① 학부운영위원회 의장은 회칙의 해석에 문제가 발생한 때에는 지체 없이 회칙해석위원회를 소집한다."},{"k":"hang","x":"② 회칙해석위원회의 구성은 학부운영위원으로 하며, 그 운영 및 회의 진행에 관하여서는 제78조 및 「고려대학교 총학생회 회의진행세칙」에서 정한 바에 따른다."},{"k":"hang","x":"③ 회칙해석위원회의 소집은 소집일 3일 전까지 공고되어야 하며, 이때 해석에 이견이 발생한 회칙 조항과 그 조항의 해석에 관한 각 측의 주장이 공개되어야 한다. 다만, 긴급한 사항은 회칙해석위원회 재적 위원 3분의 2 이상의 동의로 공고를 생략할 수 있다."},{"k":"hang","x":"④ 회칙해석위원회 의장은 위원의 요청 등에 의하여 필요하다고 인정되는 때에는 전문가를 위원회에 출석시켜 발언하게 하거나 전문가 명의의 자료 제출을 요청할 수 있다."},{"k":"hang","x":"⑤ 이 회의 중요 사항과 회원의 권리 및 의무에 관한 회칙의 해석은 회원들을 상대로 의견을 수렴하기 위한 공청회를 개최할 수 있다."},{"k":"hang","x":"⑥ 회칙해석위원회가 조항의 해석을 의결한 때에는 회의의 논의 과정과 해석 내용을 규정집에 첨부하여 항상 회칙과 함께 열람할 수 있도록 하여야 한다."},{"k":"hang","x":"⑦ 세칙ㆍ규칙 및 자치규칙의 해석에 관하여서도 제1항부터 제6항까지를 적용한다. 다만, 회칙해석위원회는 산하기구 및 특별기구의 요청이 있는 때에만 그 자치규칙에 관하여 유권해석을 할 수 있다."}],"num":205,"sub":2,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"부칙","bu":true,"id":"bu1"},{"t":"art","id":"b1-1","label":"제1조","title":"시행 일자","paras":[{"k":"line","x":"이 회칙은 공포 후 48시간 후부터 시행한다."}],"num":1,"sub":null,"bu":true,"bold_title":false},{"t":"art","id":"b1-2","label":"제2조","title":"학생회비 배분금에 관한 사항","paras":[{"k":"line","x":"제186조 제2항에도 불구하고 2026학년도 반 학생회에 배분되는 금액은 40,000원으로 한다."}],"num":2,"sub":null,"bu":true,"bold_title":false}],"note":null}],"current":"hoechik-20260402","title":"고려대학교 자유전공학부 학생회칙"},{"id":"seongeo","cat":"세칙","short":"선거시행세칙","versions":[{"id":"seongeo-20170819","date":"2017.08.19","kind":"전부개정","title":"자유전공학부 학부·반 학생회장단 선거 시행세칙","subtitle":"[고려대학교 자유전공학부 학생회 세칙 제1호]","history":[["2017. 5. 27.","제정"],["2017. 8. 19.","전부개정"]],"pdf":"pdf/seongeo-20170819.pdf","pdfName":"자유전공학부_학부·반_학생회장단_선거_시행세칙(2017.08.19_전부개정).pdf","blocks":[{"t":"h","lv":2,"text":"제1장 총칙"},{"t":"art","id":"a1","label":"제1조","title":"목적","paras":[{"k":"line","x":"자유전공학부 학부·반 학생회장단 선거 시행세칙은 자유전공학부 학부·반 학생회장단 선거에 관한 세부적인 사항을 규정하여 선거가 민주적인 절차에 의하여 공정하게 치러질 수 있도록 함을 목적으로 한다."}],"num":1,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a2","label":"제2조","title":"기본원칙","paras":[{"k":"line","x":"학부·반 학생회장단 선거는 보통ㆍ평등ㆍ직접ㆍ비밀선거를 원칙으로 한다."}],"num":2,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a3","label":"제3조","title":"적용범위","paras":[{"k":"line","x":"이 세칙은 자유전공학부 학부ㆍ반 학생회장단 선거에 적용한다. 단, 반 학생회장단 선거의 경우 동시선거일 때만 본 세칙을 적용한다."}],"num":3,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제2장 선거권과 피선거권"},{"t":"art","id":"a4","label":"제4조","title":"선거권","paras":[{"k":"hang","x":"① 본회 정회원은 학부 학생회장단 선거의 선거권이 있다."},{"k":"hang","x":"② 반 학생회장단 선거의 선거권은 각 호를 따른다."},{"k":"ho","x":"1. A반 소속 자유전공학부 학생회 정회원은 A반 학생회장단 선거의 선거권이 있다."},{"k":"ho","x":"2. B반 소속 자유전공학부 학생회 정회원은 B반 학생회장단 선거의 선거권이 있다."},{"k":"ho","x":"3. C반 소속 자유전공학부 학생회 정회원은 C반 학생회장단 선거의 선거권이 있다."},{"k":"ho","x":"4. D반 소속 자유전공학부 학생회 정회원은 D반 학생회장단 선거의 선거권이 있다."},{"k":"hang","x":"③ 투표인 명부는 자유전공학부 행정실을 통해 확인한 재학생 명단, 휴학생 명단, 타 학부 학생 중에서 본회의 회원으로 등록한 명단을 참고하여 선거관리위원회에서 확정한다."}],"num":4,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a5","label":"제5조","title":"피선거권","paras":[{"k":"hang","x":"① 본회의 회원인 자는 학부 학생회장단 선거의 피선거권이 있다."},{"k":"hang","x":"② 학부 학생회장단 선거에 학부 학생회장 후보 단독으로 출마한 경우 그 후보는 3학기 이상 등록자이어야 한다. 단, 학부 학생회장 후보와 학부 부학생회장 후보 각 한명씩이 조를 이루어 입후보한 경우 둘 중 한 명만 3학기 이상 등록자인 경우에도 피선거권이 있다."},{"k":"hang","x":"③ 다음 각 호의 조건을 모두 만족한 자는 반 학생회장단의 피선거권이 있다."},{"k":"ho","x":"1. 선거일 현재 2학기 이상 등록한 자"},{"k":"ho","x":"2. 「자유전공학부 학생회칙」과 이 세칙에 반하는 활동 목적을 갖지 아니한 자"},{"k":"hang","x":"④ 학부운영위원의 자격을 갖고 있거나 학부 학생회 집행위원으로 활동하고 있는 자가 학생회장단 선거에 출마하려는 경우 해당 직책을 사퇴해야 한다."},{"k":"hang","x":"⑤ 징계로서 선거권과 피선거권을 박탈당한 자는 선거의 선거권과 피선거권이 없다."}],"num":5,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제3장 기관"},{"t":"h","lv":3,"text":"제1절 선거관리위원회"},{"t":"art","id":"a7","label":"제7조","title":"목적","paras":[{"k":"line","x":"선거관리위원회는 학생회장단 선거가 민주적인 절차에 의하여 공정하게 치러질 수 있도록 하기 위하여 설립된 기구이다."}],"num":7,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a8","label":"제8조","title":"의무","paras":[{"k":"hang","x":"① 선거관리위원회는 「자유전공학부 학생회칙」과 세칙을 성실히 준수함으로써 선거의 관리에 공정을 기하여야한다."},{"k":"hang","x":"② 선거관리위원회는 본회 회원의 주권의식을 높이기 위해 올바른 투표방법을 적극적으로 알리고, 불특정 다수에 대한 투표 독려를 해야 한다."}],"num":8,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a9","label":"제9조","title":"업무","paras":[{"k":"line","x":"선거관리위원회는 다음 각 호의 사무를 행한다."},{"k":"ho","x":"1. 학생회장단 선거 업무의 기획 및 집행"},{"k":"ho","x":"2. 학생회장단 선거에 대한 홍보"},{"k":"ho","x":"3. 학생회장단 선거의 민주성ㆍ공정성을 높이기 위한 활동"},{"k":"ho","x":"4. 「자유전공학부 학생회칙」과 이 세칙에 따른 각 선거운동본부 감시"},{"k":"ho","x":"5. 「자유전공학부 학생회칙」과 이 세칙을 위반한 선거운동본부에 대한 징계 조치"},{"k":"ho","x":"6. 그 외에 학생회장단 선거 운영에 필요하다고 인정되는 사안"}],"num":9,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a10","label":"제10조","title":"구성","paras":[{"k":"hang","x":"① 선거관리위원회는 최소한 투표 개시일 21일 전에 학부운영위원회의 승인을 받아 구성 되어야 한다."},{"k":"hang","x":"② 선거관리위원회는 학부 학생회장단을 제외한 학부운영위원 및 학생회칙 제 64조 제5항에 의해 의결권을 가질 수 있는 자 전원을 기본으로 구성하며, 나머지 인원은 공개모집함을 원칙으로 한다. 단, 반 학생회장단 동시선거의 경우 해당 선거를 진행하는 선거관리위원회는 학부운영위원 및 학생회칙 제 64조 제5항에 의해 의결권을 가질 수 있는 자 전원을 기본으로 구성하며, 나머지 인원은 공개모집함을 원칙으로 한다."},{"k":"hang","x":"③ 선거관리위원회는 학부운영위원회 회의에서 인준 받은 8인 이상 12인 이하의 선거관리 위원으로 구성된다. 단, 모집인원이 12인 이상일 경우 선착순으로 함을 원칙으로 한다."},{"k":"hang","x":"④ 선거관리위원의 충원이 필요할 시 선거관리위원을 추가로 공개모집 할 수 있으며 변동사항을 학부운 영위원회에서 인준 받아야 한다."},{"k":"hang","x":"⑤ 선거시행세칙 제13조제2항에 의해 선거관리위원의 결손이 생겼을 경우, 선거관리위원회는 선거관리 위원을 충원하지 못한다."},{"k":"hang","x":"⑥ 선거시행세칙 제14조에 의해 선거관리위원회가 해체되었을 경우, 해당 선거는 무효가 되며, 학부운영 위원회는 지체 없이 재선거를 위한 선거관리위원회를 구성해야 한다. 단, 해체된 선거관리위원회의 선거관리위원은 지원할 수 없다."}],"num":10,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a11","label":"제11조","title":"선거관리위원장","paras":[{"k":"hang","x":"① 선거관리위원장은 선거관리위원회에서 민주적으로 선출한다. 선출된 선거관리위원장은 지체 없이 학부운영위원회에서 인준 받아야 한다."},{"k":"hang","x":"② 선거관리위원장은 선거관리위원회를 대표하고, 그 사무를 총괄한다."},{"k":"hang","x":"③ 선거관리위원장은 선거관리위원회 회의의 의장이 된다."},{"k":"hang","x":"④ 선거관리위원장이 사고 시에는 선관위 내부적 호선을 통해 다른 선관위원 중 한 명이 그 직무를 대신한다. 단, 이를 학부운영위원회에 통보해야 한다."}],"num":11,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a12","label":"제12조","title":"선거관리위원회 회의","paras":[{"k":"hang","x":"① 선거관리위원회는 선거관리위원회 회의를 통해 선거관리와 관련된 모든 문제를 처리한다."},{"k":"hang","x":"② 선거관리위원회 회의는 각 호 중 하나에 의해 위원장이 소집한다."},{"k":"ho","x":"1. 위원장의 소집요구"},{"k":"ho","x":"2. 선거관리위원회 재적 위원 3분의 1 이상의 연서에 따른 소집요구"},{"k":"ho","x":"3. 선거운동본부 본부장의 이의제기에 따른 소집요구"},{"k":"hang","x":"③ 선거관리위원회 회의는 재적 선거관리위원 과반수의 출석으로 개의하고, 출석 선거관리위원 과반수의 찬성으로 의결한다. 이 때 표결은 기명으로 함을 원칙으로 한다. 단, 중요한 안건으로서 위원장 또는 위원이 제기하여 선거관리위원회가 의결하거나 재적 위원 3분의 1 이상의 요구가 있을 때에는 표결을 무기명으로 할 수 있다. 또한 제13조제2항에 의한 선거관리위원 파면에 관한 안건은 재적 선거관리위원 과반수의 출석, 출석 선거관리위원 3분의 2 이상의 찬성으로 의결한다."},{"k":"hang","x":"④ 의장은 안건에 대한 이의의 유무를 물어서 이의가 없다고 인정한 때에는 가결되었음을 선포할 수 있 다. 이의가 있을 때 또는 표결을 무기명으로 할 때에는 반드시 표결하여야 한다."},{"k":"hang","x":"⑤ 선거관리위원회는 원활한 선거관리를 위하여 다음 각 호에 해당하는 자의 회의 출석을 요구할 수 있다."},{"k":"ho","x":"1. 후보자"},{"k":"ho","x":"2. 각 선거운동본부의 선거운동본부장"},{"k":"ho","x":"3. 선거운동본부에 대한 징계 사유와 관련된 자"}],"num":12,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a13","label":"제13조","title":"선거관리위원의 직권남용","paras":[{"k":"hang","x":"① 선거관리위원장을 포함한 선거관리위원이 본회 선거시행세칙을 지키지 않았을 경우 본 회 회원은 이에 대해 선거관리위원회에 이의제기를 할 수 있다. 이의제기가 있는 즉시 선거관리위원회 회의의 의장은 선거관리위원회 회의를 소집하여야 하고, 선거관리위원회 회의의 의결에 따라 해당 선거관리위원은 파면될 수 있다."},{"k":"hang","x":"② 선거관리위원에 대한 파면은 재적 선거관리위원 과반수의 출석, 출석 선거관리위원 3분의 2 이상의 찬성으로 의결한다. 이 때 이의제기의 대상이 된 선거관리위원은 재적 위원과 출석 위원의 수에서 제외한다."}],"num":13,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a14","label":"제14조","title":"선거관리위원회의 직권남용","paras":[{"k":"line","x":"선거관리원회가 직권을 남용해 본회 선거시행세칙을 지키지 않았을 경우 본회 회원은 해당 선거관리위원회의 징계를 학부운영위원회에 요구할 수 있다. 선거관리위원회에 대한 징계가 접수되었을 때 학부운영위원회는 집행위원 3인, 학부운영위원을 제외한 학생대표자회 대의원 중 3인의 모집을 요청하여 징계위원회를 결성한다. 징계위원회는 선거관리위원회에 대한 징계를 심의·의결한다. 징계의 방법은 「자유전공학부 학생회칙」 제39조를 따른다."}],"num":14,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a15","label":"제15조","title":"재정 및 운영","paras":[{"k":"hang","x":"① 선거관리위원회의 선거관리비용은 학생회비에서 사후 전액 지원받는 것을 원칙으로 한다."},{"k":"hang","x":"② 선거관리위원장은 선거관리위원회 구성과 동시에 선거관리비용에 대한 예산안을 작성하여 이를 학부운영위원회에서 인준 받는다."},{"k":"hang","x":"③ 선거관리위원장은 선거가 끝난 후 선거관리비용에 대한 결산을 작성하여 이를 학부운영위원회 회의에서 심의 받는다."},{"k":"hang","x":"④ 학부운영위원회 회의는 심의 후 선거관리비용에 대한 금액을 지원한다."}],"num":15,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 선거운동본부"},{"t":"art","id":"a16","label":"제16조","title":"정의","paras":[{"k":"line","x":"선거운동본부는 학생회장단 선거에 등록한 후보의 선거운동을 통해 해당 후보의 당선을 도모하고, 각 현안에 대한 의견표명ㆍ정책개발 등을 통해 회원의 선거와 관련된 의사형성에 도움을 주는 회원의 자발적 조직을 말한다."}],"num":16,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a17","label":"제17조","title":"의무","paras":[{"k":"hang","x":"① 선거운동본부는 학생회장단 선거가 민주적이고 공정하게 치러지도록 노력하여야 한다."},{"k":"hang","x":"② 선거운동본부는 학생회장단 선거가 발전적인 정책 선거로 치러지도록 노력하여야 한다."},{"k":"hang","x":"③ 선거운동본부는 학생회장단 선거가 원활하게 진행될 수 있도록 선관위에 최대한 협조하여야 한다."}],"num":17,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a18","label":"제18조","title":"구성","paras":[{"k":"hang","x":"① 선거운동본부는 학생회장단 선거 후보, 선거운동본부장, 선거운동본부원으로 구성된다."},{"k":"hang","x":"② 선거운동본부장 및 선거운동본부원은 본회의 회원이어야 한다."}],"num":18,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a19","label":"제19조","title":"모집공고","paras":[{"k":"hang","x":"① 선거운동본부는 선거 공고가 있은 후부터 본부원 모집을 위한 공고를 할 수 있다. 단, 공고문에는 다음 각 호의 사항을 제외하고는 명시할 수 없다."},{"k":"ho","x":"1. 선거운동본부명"},{"k":"ho","x":"2. 후보의 이름, 소속 학부ㆍ과ㆍ반, 학번"},{"k":"ho","x":"3. 선거운동본부장의 이름, 소속 학부ㆍ과ㆍ반, 학번"},{"k":"ho","x":"4. 담당자 한 명의 연락처"},{"k":"ho","x":"5. 500자 내외의 선거운동본부 소개"},{"k":"hang","x":"② 선거운동본부원을 모집하고자 하는 선거운동본부는 제1항의 공고문을 선거관리위원회에 제출하여 허가를 받아야 한다. 선거관리위원회는 선거운동본부원 모집 공고문이 접수되면 지체 없이 선거관리위원회 회의를 열어 공고문을 심의한다."},{"k":"hang","x":"③ 공고문에 결함이 있을 때 선거관리위원회는 공고문의 게시를 허가하지 않을 수 있으며, 해당 선거운동본부는 결함이 있는 부분을 시정하여 공고문을 다시 심의 받을 수 있다."}],"num":19,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a20","label":"제20조","title":"선거운동본부장","paras":[{"k":"hang","x":"① 선거운동본부장은 해당 선거운동본부를 대표하고, 선거 과정 전반에서 후보자를 보좌하며, 후보자를 대신하여 선거관리위원회를 상대로 선거 운영 전반에 대한 의사를 표명한다."},{"k":"hang","x":"② 선거운동본부장은 해당 선거운동본부의 학생회장단 후보가 임명한다."},{"k":"hang","x":"③ 학생회장단 후보는 선거운동본부장을 교체할 수 있다. 단, 이를 선거관리위원회에 보고하며 선거관리위원회는 선거운동본부장의 교체 신청이 접수되면 지체 없이 이를 심사하여 승인한다."}],"num":20,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a21","label":"제21조","title":"선거운동본부원","paras":[{"k":"hang","x":"① 각 선거운동본부는 선거운동본부원을 선거관리위원회에 등록하여야 한다."},{"k":"hang","x":"② 선거운동본부원 등록은 후보 등록 신청과 함께 등록하며, 그 이후부터는 변동 사항이 있을 경우 이를 선거관리위원회에 보고한다."},{"k":"hang","x":"③ 선거관리위원회에 선거운동본부원으로 등록되지 않은 자는 해당 선거운동본부원의 본부원으로 활동 할 수 없다."},{"k":"hang","x":"④ 한 선거운동본부의 본부원으로 등록된 상태에서는 다른 선거운동본부의 본부원으로 등록할 수 없다."}],"num":21,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제4장 선거"},{"t":"h","lv":3,"text":"제1절 선거일정"},{"t":"art","id":"a22","label":"제22조","title":"선거 일정의 결정","paras":[{"k":"hang","x":"① 본회 학생회장단 선거는 11월 중에 시행함을 원칙으로 하며, 반 학생회장단 선거는 6월 중에 시행함을 원칙으로 한다."},{"k":"hang","x":"② 학생회장단 선거일정은 선거 공고, 등록 기간, 선거운동기간, 투표일, 개표일, 당선공고로 구성된다."},{"k":"hang","x":"③ 선거관리위원회는 등록 기간을 5일 이내, 선거운동기간을 5일 이내, 투표일을 3일로 하여 선거일정을 정한다. 등록 기간과 투표일은 토요일과 공휴일이 기간에 산입하지 않는 것을 원칙으로 한다."},{"k":"hang","x":"④ 그 외 구체적인 선거일정은 선거관리위원회에서 정한다."}],"num":22,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a23","label":"제23조","title":"선거 공고","paras":[{"k":"line","x":"선거관리위원회는 구성 후 최소한 투표 개시일 14일 전까지 다음 각 호를 명시한 선거 공고를 하여야 한다. 단 재투표의 경우, 투표 개시일 7일 전까지 공고한다."},{"k":"ho","x":"1. 선거관리위원회 활동개시의 뜻"},{"k":"ho","x":"2. 선거 일정"},{"k":"ho","x":"3. 후보 등록에 필요한 서류 목록"},{"k":"ho","x":"4. 선거관리위원장 및 선거관리위원 명단"},{"k":"ho","x":"5. 선거관리위원들의 공정한 선거 진행을 위한 서약 내용 및 서명"}],"num":23,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 후보등록"},{"t":"art","id":"a24","label":"제24조","title":"후보등록","paras":[{"k":"hang","x":"① 학부 학생회장단 선거에 등록하려는 자는 다음 각 호의 서류를 첨부하여 선거관리위원회에 제출하여야 한다."},{"k":"ho","x":"1. 「자유전공학부 학부·반선거시행세칙」 제5조2항의 요건을 충족하는 재학증명서"},{"k":"ho","x":"2. 선거운동본부장의 재학증명서 또는 휴학증명서"},{"k":"ho","x":"3. 선거운동본부명"},{"k":"ho","x":"4. 출마 소견문"},{"k":"ho","x":"5. 50인 이상의 회원 추천서명-50인 이상의 회원 추천서명에 있어서 당해 연도 입학한 학번 10명 이상, 이전 연도 입학한 학번 10명 이상, 그 이전에 입학한 학번 10명 이상의 추천서명을 받는 것을 원칙으로 한다."},{"k":"ho","x":"6. 선거본부 소속 운동원 명부"},{"k":"hang","x":"② 반 학생회장단 선거에 등록하려는 자는 다음 각 호의 서류를 첨부하여 선거관리위원회에 제출하여야 한다."},{"k":"ho","x":"1. 선거일 현재에 2학기 이상 재학했음을 증명할 수 있는 재학증명서"},{"k":"ho","x":"2. 선거운동본부장의 재학증명서 또는 휴학증명서"},{"k":"ho","x":"3. 선거운동본부명"},{"k":"ho","x":"4. 출마 소견문"},{"k":"ho","x":"5. 15인 이상의 회원 추천서명-15인 이상의 회원 추천서명에 있어서 당해 연도 입학한 학번 5명 이상, 그 이전에 입학한 학번 5명 이상의 추천서명을 받는 것을 원칙으로 한다."},{"k":"ho","x":"6. 선거본부 소속 운동원 명부"},{"k":"hang","x":"③ 후보등록 서류양식 및 제출방식은 선거관리위원회에서 정하며, 선거관리위원회가 정한 서류양식 및 제출 방식이 아닌 서류는 모두 무효이다."},{"k":"hang","x":"④ 선거관리위원회는 모든 학생회장단 선거 등록자에게 동일한 서류양식 및 제출방식으로 서류를 제출 받아야 한다."},{"k":"hang","x":"⑤ 추천서명은 추천인의 자필서명을 원칙으로 한다. 단, 선거관리위원회는 추천인의 서명을 추천인 본인 확인이 가능한 전자서명 또는 이에 준하는 수단으로 대체하여 받을 수 있다."}],"num":24,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a25","label":"제25조","title":"후보 등록 심사","paras":[{"k":"hang","x":"① 선거관리위원회는 후보 등록 마감 후 24시간 이내에 선거관리위원회 회의를 열어 후보등록을 위 한 서류들을 검토한다."},{"k":"hang","x":"② 제1항의 회의에는 각 선거운동본부의 후보, 선거운동본부장이 모두 참석하여야 한다."},{"k":"hang","x":"③ 선거관리위원회는 서류 검토 후 특별한 결격사유가 없을 경우 이를 즉시 수리해야 한다. 단, 하자가 있을 시, 즉시 등록 불가 의사와 그 사유를 공고한다."},{"k":"hang","x":"④ 등록이 마무리된 후에는 제출한 서류의 내용을 퇴고하거나 수정할 수 없다."}],"num":25,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a26","label":"제26조","title":"복수추천의 허용","paras":[{"k":"line","x":"선거권자는 동일한 선거에서 서로 다른 후보를 동시에 추천할 수 있다. 단, 동일후보에 대한 중복 추천 서명은 인정하지 않는다."}],"num":26,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a27","label":"제27조","title":"후보자의 사퇴","paras":[{"k":"line","x":"후보자가 사퇴하고자 하는 때에는 본인이 직접 선거관리위원회에 사유서를 제출하여야 한다. 단, 선거운동 기간 후에는 사퇴할 수 없다."}],"num":27,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a28","label":"제28조","title":"후보자의 겸직 금지","paras":[{"k":"line","x":"후보자의 겸직 금지에 관한 사항은 자유전공학부 회칙 제 10조를 따른다."}],"num":28,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a29","label":"제29조","title":"후보자 등록 등의 공고","paras":[{"k":"hang","x":"① 선거관리위원회는 후보 등록 다음 날까지 다음 각 호의 사항을 명시한 입후보자 공고를 해야 한다."},{"k":"ho","x":"1. 후보의 이름, 소속 학과ㆍ반, 학번"},{"k":"ho","x":"2. 선거운동본부명 및 선거운동본부장의 이름, 소속 학과ㆍ반, 학번"},{"k":"hang","x":"② 선거관리위원회는 후보자가 사퇴ㆍ사망하거나 후보 자격이 박탈되면 지체 없이 이를 공고한다."}],"num":29,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a30","label":"제30조","title":"후보자가 없는 경우","paras":[{"k":"line","x":"후보로 아무도 등록하지 않거나, 등록한 모든 후보의 사퇴 등으로 후보가 없어 해당 선거가 무산된 경우, 「자유전공학부 회칙」 또는 「반 학생회칙」에 따라 비상대책위원회를 구성한다."}],"num":30,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제3절 선거운동"},{"t":"art","id":"a31","label":"제31조","title":"선거운동","paras":[{"k":"hang","x":"① 선거운동이라 함은 특정후보의 당선을 위한 제반의 행위이다."},{"k":"hang","x":"② 선거운동은 다음 각 호의 방법으로 한다."},{"k":"ho","x":"1. 개인유세ㆍ합동유세"},{"k":"ho","x":"2. 선전물의 게시ㆍ배포"},{"k":"ho","x":"3. 간담회ㆍ공청회"},{"k":"ho","x":"4. 인터넷 선거운동 공간의 구성 및 운영"},{"k":"ho","x":"5. 선거운동본부복의 착용"},{"k":"ho","x":"6. 그밖에 당선을 위한 각종 행위"},{"k":"hang","x":"③ 다음 각 호의 행위는 선거운동으로 보지 않는다."},{"k":"ho","x":"1. 선거에 관한 일반적인 의견개진 및 의사표시"},{"k":"ho","x":"2. 후보등록을 위한 준비 행위"},{"k":"hang","x":"④ 선거운동은 본회 선거시행세칙에 규정된 이외의 방법으로는 할 수 없다."}],"num":31,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a32","label":"제32조","title":"선거운동기간","paras":[{"k":"hang","x":"① 선거운동기간은 후보 등록이 마무리 된 이후부터 투표일 전날 24시 사이에서 선거관리위원회가 결정한다. 단, 부착된 전지규격의 선전물은 투표 종료일까지 게시 가능하다."},{"k":"hang","x":"② 사전선거운동은 허용하지 않는다. 단, 추천 서명을 받는 행위는 사전선거운동으로 보지 않는다."}],"num":32,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a33","label":"제33조","title":"선거운동을 할 수 없는 자","paras":[{"k":"line","x":"다음 각 호에 해당하는 자는 선거운동을 할 수 없다."},{"k":"ho","x":"1. 선거관리위원장 및 선거관리위원"},{"k":"ho","x":"2. 본회의 회원이 아닌 자"},{"k":"ho","x":"3. 본회 회원 중 적법한 절차를 거쳐 선거운동본부원으로 등록하지 않은 자"}],"num":33,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a34","label":"제34조","title":"선거관리위원회 제작 선전벽보","paras":[{"k":"hang","x":"① 선거관리위원회는 후보 등록이 완료된 다음날까지 다음 각 호의 사항을 명시한 선거관리위원회 제 작 선전벽보를 게시하여야 한다."},{"k":"ho","x":"1. 후보의 사진, 이름, 소속 학과ㆍ반, 학번"},{"k":"ho","x":"2. 선거운동본부명"},{"k":"ho","x":"3. 핵심 공약"},{"k":"hang","x":"② 선거관리위원회 제작 선전벽보의 수량과 게시 위치는 선거관리위원회와 각 선거운동본부의 합의로 결정한다."}],"num":34,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a35","label":"제35조","title":"선거운동 일정의 보고의무","paras":[{"k":"hang","x":"① 각 선거운동본부는 선거운동 일정을 선거관리위원회에 보고해야 한다."},{"k":"hang","x":"② 선거관리위원회가 보고받은 사항 중 일정이 겹치는 부분에 한해서 선거관리위원회가 공정하게 조정한다."},{"k":"hang","x":"③ 보고되지 않은 선거운동이 진행되는 경우, 선거관리위원회는 선거운동이 더 이상 진행되지 않도록 막을 수 있으며, 그 위반 사실을 지체없이 공고해야한다."}],"num":35,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a36","label":"제36조","title":"선전물의 사전허가","paras":[{"k":"hang","x":"① 각 선거운동본부는 선거관련 선전물을 선거관리위원의 허가를 거친 후 게시ㆍ배포한다."},{"k":"hang","x":"② 선거 관련 선전물에 타 후보에 대한 비방 등 선거의 공정성을 해칠 수 있는 내용이 있으면 선거관리 위원회가 게시ㆍ배포 금지 처분을 할 수 있다."},{"k":"hang","x":"③ 선거관리위원회에 신고하지 않은 선전물을 게시ㆍ배포하면 선거관리위원회는 해당 선거운동본부에 해당 게시물ㆍ유인물의 수거를 명할 수 있다."}],"num":36,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a37","label":"제37조","title":"선전물","paras":[{"k":"hang","x":"① A0규격을 초과하는 선전물은 게시할 수 없다."},{"k":"hang","x":"② 선거운동기간 중에 게시된 선전물은 투표 종료일까지 게시가 가능하다. 단, 투표소로부터 10m 이내에 게시된 선전물은 제거하여야 한다."},{"k":"hang","x":"③ 각 선거운동본부는 선거운동기간 동안 유인물과 20쪽 내의 소책자를 배포할 수 있으며, 유인물과 소책자의 규격 및 개수 등의 사항은 선거운동기간에 들어가기 전에 선거운동본부장과 선거관리위원회의 합의로 결정한다."},{"k":"hang","x":"④ 선거운동본부원이 타 선거운동본부의 선전물을 임의로 제거할 수 없다."},{"k":"hang","x":"⑤ 선거관리위원회는 선거운동본부의 선전물의 게시ㆍ배포를 최대한 보장하여야 한다."}],"num":37,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a38","label":"제38조","title":"개인유세","paras":[{"k":"hang","x":"① 개인유세는 각 선거운동본부의 후보 또는 선거운동본부원들이 선거운동의 일환으로 벌이는 강의실 유세, 선거 물품 배포 등의 모든 종류의 선전활동을 말한다."},{"k":"hang","x":"② 개인유세는 8시부터 20시까지 가능하다."},{"k":"hang","x":"③ 선거관리위원회는 선거의 민주성ㆍ대중성 향상을 위하여 각 선거운동본부의 개인유세를 최대한 보장 하여야 한다."},{"k":"hang","x":"④ 개인유세는 각 선거운동본부가 수시로 개최할 수 있다. 단, 지나친 소음 등으로 학우들의 불편을 초래할 위험이 있거나, 초래한 때는 선거관리위원회가 이를 제한할 수 있다."},{"k":"hang","x":"⑤ 개인유세와 관련된 세부적인 사항들은 선거운동기간에 들어가기 전에 각 선거운동본부의 선거운동본부장과 선거관리위원회의 합의로 결정한다."}],"num":38,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a39","label":"제39조","title":"합동유세","paras":[{"k":"hang","x":"① 두 개 이상의 선거운동본부가 등록한 경우, 선거관리위원회는 합동유세를 개최해야 하며, 합동유세의 진행은 선거관리위원장이 담당한다."},{"k":"hang","x":"② 합동유세에서의 유세 순서는 합동유세 전에 추첨하여 정한다."},{"k":"hang","x":"③ 후보자는 유세시간을 준수하여야 한다. 각 선거운동본부 당 유세시간은 선거관리위원회에서 결정하 며, 제한시간을 초과하면 선거관리위원회는 마이크 등 유세시설을 철거하여 유세를 중단시킨다. 단, 유세자를 교체하기 위해 소요되는 시간은 유세시간에 포함되지 않는다."},{"k":"hang","x":"④ 후보자는 합동유세가 끝날 때까지 합동유세장에서 퇴장할 수 없다. 단, 부득이할 때는 선거관리위원 장의 동의에 따라 10분 이내로 자리를 비울 수 있다."},{"k":"hang","x":"⑤ 후보자는 타 후보자의 유세 시간 중에 유세를 방해하거나 자기 선거운동본부의 선전물을 배포하는 행위를 할 수 없다."},{"k":"hang","x":"⑥ 선거관리위원회는 합동유세장에서 연설을 방해하거나 장내질서를 어지럽히는 자가 있을 때 퇴장을 명할 수 있다."}],"num":39,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a40","label":"제40조","title":"인터넷에서의 선거운동","paras":[{"k":"hang","x":"① 각 선거운동본부는 인터넷에 홈페이지, 카페, 커뮤니티 등의 인터넷 선거운동 공간을 구성할 수 있다."},{"k":"hang","x":"② 각 선거운동본부의 후보자, 선거운동본부장, 선거운동본부원은 선거관리위원회가 허용한 공간 이외의 인터넷 공간에서 논쟁ㆍ답변 등의 의사표현 행위를 할 수 없다."},{"k":"hang","x":"③ 그밖에 인터넷에서의 선거운동과 관련해서는 선거관리위원회와 선거운동본부의 합의에 따라 결정한다."}],"num":40,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a41","label":"제41조","title":"후보간담회","paras":[{"k":"line","x":"각 선거운동본부는 선거운동기간 중 간담회를 주최할 수 있다."}],"num":41,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a42","label":"제42조","title":"공청회","paras":[{"k":"hang","x":"① 선거운동본부는 선거관리위원회에 공청회를 요청할 수 있으며, 선거관리위원회는 정당한 사유 없이 선거운동본부의 요청을 거부할 수 없다."},{"k":"hang","x":"② 선거운동본부가 두 개 이상일 경우, 선거관리위원회에서 합동공청회를 진행할 수 있다."},{"k":"hang","x":"③ 공청회는 선거관리위원회 주제 하에 개최된다."},{"k":"hang","x":"④ 공청회의 사회는 선거관리위원 중 한 명이 맡는다."},{"k":"hang","x":"⑤ 공청회의 구체적인 운영방법은 선거관리위원회에서 추후 결정한다."}],"num":42,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a43","label":"제43조","title":"선거운동 비용","paras":[{"k":"hang","x":"① 선거운동비용은 후보 등록 시부터 당선인 결정 때까지 소요되는 모든 금전, 물품, 채무 등 모든 재산상 가치를 말한다."},{"k":"hang","x":"② 각 선거운동본부의 선거운동 비용은 선거운동 비용의 최대 80%까지 학생회비에서 사후 지원받을 수 있다."},{"k":"hang","x":"③ 각 선거운동본부의 선거운동본부장을 투표를 통해 당선 및 낙선이 확정된 이후, 선거운동 비용에 대한 결산을 작성하여 이를 운영위원회 회의에서 심의 받는다. 이 때 결격사유가 발견될 경우 학부운영위원회는 학생회비 지원을 하지 않을 수 있다."}],"num":43,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제4절 이의제기"},{"t":"art","id":"a44","label":"제44조","title":"이의제기의 방식","paras":[{"k":"hang","x":"① 본회 회원은 공정한 선거를 위하여 불법행위를 선거관리위원회에 고발할 의무를 지닌다."},{"k":"hang","x":"② 선거에 관한 이의제기는 한 선거운동본부 내에서는 각 선거운동본부의 본부장만 할 수 있다."},{"k":"hang","x":"③ 각 선거운동본부는 선거운동본부장 명의의 서면으로 이의제기를 하여야 한다."},{"k":"hang","x":"④ 투표와 관련해서는 해당 투표소에 파견된 투표참관인이 선거운동본부장을 대신하여 구두로 이의제기를 할 수 있다. 단, 이 때 해당 선거운동본부는 24시간 이내에 해당 이의제기 내용을 서면으로 다시 제출하여야 한다."},{"k":"hang","x":"⑤ 개표와 관련해서는 선거운동본부장이 구두로 이의제기를 할 수 있다. 단, 이 때 해당 선거운동본부는 24시간 이내에 해당 이의제기 내용을 서면으로 다시 제출하여야 한다."},{"k":"hang","x":"⑥ 선거운동본부가 제2항부터 제5항까지를 위반하면 선거관리위원회가 해당 선거운동본부에 시정명령을 내린다."}],"num":44,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a45","label":"제45조","title":"이의제기의 처리","paras":[{"k":"hang","x":"① 이의제기가 있으면 선거관리위원장은 지체 없이 회의를 소집하여 이를 심의하여 처리한다."},{"k":"hang","x":"② 이의제기의 처리는 선거관리위원회 재적 위원 과반수 출석과 출석 위원 과반수 찬성으로 의결한다."}],"num":45,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제5절 징계"},{"t":"art","id":"a46","label":"제46조","title":"징계","paras":[{"k":"line","x":"징계라 함은 이 세칙에 반하는 행위를 하거나, 선거관리위원회가 징계 사유라고 정한 행위를 할 때 해당 선거운동본부에 제재를 가하는 것을 말한다."}],"num":46,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a47","label":"제47조","title":"징계의사유","paras":[{"k":"line","x":"다음 각 호에 해당하는 경우에 선관위는 해당 선본에게 징계를 내릴 수 있다."},{"k":"ho","x":"1. 선거운동본부의 행위가 공정한 선거 진행을 해치는 것이 분명할 때"},{"k":"ho","x":"2. 선거운동본부의 행위가 공정한 선거 진행을 의도적으로 해치거나, 중대한 영향을 주는 것이 분명할 때"}],"num":47,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a48","label":"제48조","title":"징계의 종류","paras":[{"k":"line","x":"선관위는 징계의 종류를 제47조의 사유에 비례해 정할 수 있다. 징계의 종류는 다음 각 호에 명시된 바를 따른다."},{"k":"ho","x":"1. 위반사유의 공고"},{"k":"ho","x":"2. 징계결정 익일간 일체의 선거운동 금지"}],"num":48,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a49","label":"제49조","title":"자격의 박탈","paras":[{"k":"line","x":"다음 각 호에 해당하는 경우에 선관위는 해당 선본의 후보자격을 박탈한다."},{"k":"ho","x":"1. 제47조 1호의 징계사유에 관하여 3회 징계를 받은 경우"},{"k":"ho","x":"2. 제47조 2호의 징계사유에 관하여 2회 징계를 받은 경우"},{"k":"ho","x":"3. 제47조 1호의 징계사유에 관하여 2회의 징계와 제47조 2호의 징계사유에 관하여 1회 징계를 받은 경우"}],"num":49,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제6절 투표"},{"t":"art","id":"a50","label":"제50조","title":"투표방법","paras":[{"k":"line","x":"학생회장단 선거의 투표는 기표방법으로 함을 원칙으로 한다."}],"num":50,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a51","label":"제51조","title":"투표인명부의 열람","paras":[{"k":"line","x":"투표가 진행되고 있을 때에는 투표소에 있는 선거관리위원을 제외한 어느 누구도 투표인명부를 열람할 수 없다."}],"num":51,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a52","label":"제52조","title":"투표관리","paras":[{"k":"line","x":"선거관리위원들은 특정 지역에 설치되는 투표구의 투표 업무를 관리ㆍ감독한다."}],"num":52,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a53","label":"제53조","title":"투표소","paras":[{"k":"hang","x":"① 투표소는 선거관리위원회가 편성하여 의결한다."},{"k":"hang","x":"② 투표소 1개 당 투표함 1개를 비치한다."},{"k":"hang","x":"③ 선거관리위원회는 투표소의 명칭과 소재지를 공고해야 한다."},{"k":"hang","x":"④ 투표소에는 기표소ㆍ투표함ㆍ참관인의 좌석 그 밖의 투표관리에 필요한 시설을 설비하여야 한다."},{"k":"hang","x":"⑤ 기표소는 그 안을 다른 사람이 엿볼 수 없도록 설비하여야 하며 어떠한 표지도 하여서는 아니 된다."},{"k":"hang","x":"⑥ 각 선거운동본부의 본부장 및 해당 투표소에 파견된 투표참관인은 투표소의 설비에 대하여 그 시정을 요구할 수 있다."}],"num":53,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a54","label":"제54조","title":"투표일ㆍ투표시간","paras":[{"k":"hang","x":"① 투표는 3일간 진행한다."},{"k":"hang","x":"② 투표는 10시 00분부터 시작하여 19시 00분에 종료한다. 단, 마감할 때 투표하기 위해 대기하고 있는 투표인에게는 투표를 할 수 있도록 한다."},{"k":"hang","x":"③ 선거관리위원은 투표가 시작되기 10분 전까지 해당 투표소의 투표함 및 기표소 내외의 이상 유무 검사를 완료해야 한다."}],"num":54,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a55","label":"제55조","title":"투표용지ㆍ투표함","paras":[{"k":"hang","x":"① 투표용지와 투표함은 선거관리위원회에서 제공한다."},{"k":"hang","x":"② 투표용지에는 학생회장단 후보자 성명, 소속 학과ㆍ반, 학번, 선거운동본부명을 표시하여야 한다."},{"k":"hang","x":"③ 후보 등록 시 제출한 추천서의 추천인 수가 많은 순서로 후보자의 게재 순서를 정한다."},{"k":"hang","x":"④ 해당 선거에 출마한 후보가 두 조 이상일 경우 투표용지에는 후보자란과 동일한 크기의 “지지선본 없음”란을 두어야 한다."},{"k":"hang","x":"⑤ 해당 선거에 출마한 후보가 한 조일 경우 투표용지에는 “찬성”, “반대”, “기권” 란을 두어야 한다."},{"k":"hang","x":"⑥ 투표용지에는 선거관리위원회의 확인란, 투표소별 투표관리요원의 확인란이 있어야 한다."},{"k":"hang","x":"⑦ 선거관리위원의 서명이 없는 투표용지는 어떠한 경우에도 무효가 된다."},{"k":"hang","x":"⑧ 기표한 것이 전사되어 어느 후보자에게 투표한 것인지 알 수 없게 될 때를 방지하기 위하여 선거인이 전사되지 않는 방향으로 접을 수 있도록 투표용지 중간에 점선을 표시하여야 한다."},{"k":"hang","x":"⑨ 두 후보자란의 구분선상에 기표되어 어느 후보자에게 기표한 것인지를 확정할 수 없을 때를 방지하기 위하여 각 후보자란 사이의 간격을 기표용구의 지름보다 크게 해야 한다."},{"k":"hang","x":"⑩ 투표함은 자물쇠로 봉인할 수 있도록 제작되어야 한다."},{"k":"hang","x":"⑪ 투표함의 열쇠는 선거관리위원장이 보관한다."}],"num":55,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a56","label":"제56조","title":"투표용지 수령","paras":[{"k":"hang","x":"① 투표인은 본인이 투표소에 가서 선거관리위원에게 본인의 학생증, 신분증, 여권 등과 함께 본인의 학적을 선거관리위원회에서 정한 방법으로 확인한 후 투표용지 1장을 받는다."},{"k":"hang","x":"② 선거관리위원은 투표용지를 교부함과 동시에 투표인명부에 투표인을 표시해야 한다."},{"k":"hang","x":"③ 선거관리위원과 투표참관인은 투표용지를 교부할 때마다 이상 유무를 확인하고, 각자의 서명을 해야 한다."}],"num":56,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a57","label":"제57조","title":"기표절차","paras":[{"k":"hang","x":"① 투표인은 투표용지를 받은 후 기표소로 들어가 준비된 기표도구로 자신의 의사를 밝히는 기표를 한 뒤 반드시 그 자리에서 보이지 않게 투표용지를 접어 선거관리위원과 투표참관인이 지켜보는 가운데 투표함에 집어넣어야 한다."},{"k":"hang","x":"② 기표행위의 실수 시, 투표용지를 재교부하지 않는다."},{"k":"hang","x":"③ 동일기표소에 2인 이상이 들어갈 수 없다. 단, 시각 또는 신체의 장애로 인하여 자신이 기표할 수 없는 선거인은 본인이 지명한 2인을 동반하여 투표를 보조하게 할 수 있다."}],"num":57,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a58","label":"제58조","title":"투표소에서의 선거관리위원 업무","paras":[{"k":"hang","x":"① 선거관리위원은 투표소에 관련된 모든 업무를 관리ㆍ감독한다."},{"k":"hang","x":"② 투표소를 관리하는 선거관리위원은 해당 투표소를 떠날 수 없다. 단, 불가피한 경우에는 다른 선거관리위원으로 대체한다. 그리고 이 사실을 선거관리위원장에게 보고한다."}],"num":58,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a59","label":"제59조","title":"투표참관인","paras":[{"k":"hang","x":"① 투표참관인은 각 선거운동본부가 투표 진행을 감독하기 위해 각 투표소에 배치 한 자를 말한다."},{"k":"hang","x":"② 각 선거운동본부는 투표참관인을 투표일 전까지 선거관리위원회에 등록하여야 한다."},{"k":"hang","x":"③ 각 선거운동본부의 투표참관인은 투표소에 1인씩 배치하며, 교체 가능하다."},{"k":"hang","x":"④ 투표참관인은 정당한 이유 없이 참관을 거부하거나, 사임할 수 없다."},{"k":"hang","x":"⑤ 투표참관인은 투표소 질서 유지에 협조해야 한다."},{"k":"hang","x":"⑥ 투표참관인은 투표에 영향을 주는 행위를 해서는 안 된다."},{"k":"hang","x":"⑦ 투표참관인은 투표 진행상황에 대한 이의제기를 선거관리위원회에 할 수 있다."},{"k":"hang","x":"⑧ 투표참관인은 투표함 및 기표소 내외의 이상 유무를 선거관리위원과 함께 검사해야 하며, 문제가 있 을 시 이의제기를 할 수 있다. 여기에 불참할 경우 검사를 포기한 것으로 간주하고, 당일 투표소 설치에 관한 어떠한 이의제기도 할 수 없다."},{"k":"hang","x":"⑨ 투표참관인이 지각했을 경우 지각한 시간만큼의 참관을 포기한 것으로 간주하고 투표를 진행한다. 지각한 투표참관인은 자신의 도착 이전에 이루어진 투표에 대해 이의를 제기할 수 없다."}],"num":59,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a60","label":"제60조","title":"투표의 중단","paras":[{"k":"hang","x":"① 다음 각 호의 경우 중 하나에 해당할 경우 해당 투표소의 투표를 중단시킨다."},{"k":"ho","x":"1. 투표소에 선거관리위원이 없을 때"},{"k":"ho","x":"2. 투표참관인이 잠시 자리를 비울 때"},{"k":"ho","x":"3. 투표소 내에서 투표참관인의 이의제기로 인해 합의가 필요할 때"},{"k":"ho","x":"4. 투표소의 질서가 혼잡하여 공정한 투표를 진행할 수 없다고 판단될 때"},{"k":"hang","x":"② 제1항에 명시한 상황이 종료되었을 경우 바로 투표를 재개한다."}],"num":60,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a61","label":"제61조","title":"투표소 주의사항","paras":[{"k":"hang","x":"① 투표소 부근에서 선거관리위원, 투표참관인, 투표인을 제외한 사람이 선거에 영향을 미치기 위한 목적으로 접근한다고 판단될 때 선거관리위원은 이들의 접근을 제한할 수 있다."},{"k":"hang","x":"② 투표소로부터 10m 이내에서 투표참관인을 포함한 모든 자는 선거에 영향을 미치는 표식을 지녀서는 안 된다."},{"k":"hang","x":"③ 투표소로부터 10m 이내에서 소란한 언동을 하는 자가 있을 시에는 선거관리위원이 제재한다."},{"k":"hang","x":"④ 투표소로부터 10m 이내에는 선거관리위원회 제작 선전벽보 외의 어떠한 선전물도 있어서는 안 된 다."}],"num":61,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a62","label":"제62조","title":"투표의 비밀보장","paras":[{"k":"hang","x":"① 투표의 비밀은 어떠한 경우에도 보장되어야 한다."},{"k":"hang","x":"② 선거인은 투표한 후보자의 성명이나 선거운동본부명을 누구에게도 또한 어떠한 때도 진술할 의무가 없으며, 누구든지 투표 마감 시각까지 이를 질문하거나 그 진술을 요구할 수 없다."},{"k":"hang","x":"③ 선거인은 자신이 기표한 투표지를 공개할 수 없으며, 공개된 투표지는 무효로 한다."}],"num":62,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a63","label":"제63조","title":"투표 시작 전 투표함 이송","paras":[{"k":"hang","x":"① 각 투표함은 매 투표일 9시 30분에 선거관리위원과 각 선거운동본부장 또는 해당 선본의 정후보 또는 부후보의 입회 하에 선거관리위원회실에서 투표함의 투입구와 그 자물쇠를 봉쇄하여야 한다."},{"k":"hang","x":"② 자물쇠를 봉쇄한 투표함 및 투표용지, 선거인 명부, 참관시간기록표 등 투표에 필요한 제반 물품은 투표관리요원 및 선거운동본부에서 파견한 한 명이 각 투표소로 이송한다."}],"num":63,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a64","label":"제64조","title":"투표 종료 시 투표함 이송","paras":[{"k":"hang","x":"① 매 투표일 투표가 종료된 후 선거관리위원은 투표참관인의 참관 하에 투표함의 투입구와 그 자물쇠를 봉쇄 후 날인하여야 한다."},{"k":"hang","x":"② 선거관리위원은 투표함의 이송 전에 해당 투표소의 투표참관인에게 투표함에 이상이 없음을 서면으로 확인받는다."},{"k":"hang","x":"③ 자물쇠를 이용해 봉해진 투표함 및 남은 투표용지, 선거인 명부, 참관시간기록표 등 투표에 필요한 제반 물품은 선거관리위원 혹은 선거운동본부의 투표참관인이 선거관리위원회실로 이송한다."}],"num":64,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a65","label":"제65조","title":"투표함 확인","paras":[{"k":"line","x":"선거관리위원장은 투표함, 남은 투표용지, 선거인 명부 등을 인수하여 지체 없이 이상 여부를 확인한다."}],"num":65,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a66","label":"제66조","title":"투표함 보관","paras":[{"k":"line","x":"각 투표소의 투표함은 매 투표일 투표가 종료된 후 선거관리위원회가 지정한 선거관리위원회실에 보관한다."}],"num":66,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제7절 투표성립"},{"t":"art","id":"a67","label":"제67조","title":"투표 성립 요건","paras":[{"k":"line","x":"학생회장단 선거는 3일간의 투표 기간이 지나고 명부상 투표율이 20% 이상일 경우 성립한다."}],"num":67,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제8절 개표"},{"t":"art","id":"a68","label":"제68조","title":"개표 공고","paras":[{"k":"line","x":"선거관리위원회는 투표개시일 전까지 개표 장소와 개표 시간을 공고해야 한다."}],"num":68,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a69","label":"제69조","title":"개표관리","paras":[{"k":"hang","x":"① 개표는 선거관리위원회가 담당한다."},{"k":"hang","x":"② 개표는 선거관리위원장과 선거관리위원의 과반수이상의 출석과 승인 하에 진행할 수 있다."},{"k":"hang","x":"③ 선거관리위원회는 개표 전까지 투표함을 개표소로 옮기고, 개표에 필요한 모든 준비를 마쳐야 한다."},{"k":"hang","x":"④ 각 선거운동본부의 학생회장단 후보 및 선거운동본부장은 개표가 종료될 때까지 개표 장소에 있어야 한다."},{"k":"hang","x":"⑤ 각 선거운동본부는 개표참관인 2인을 선정하여 개표현장을 참관하도록 한다."},{"k":"hang","x":"⑥ 개표참관인은 개표 진행상황에 대한 이의제기를 선거관리위원회에 할 수 있다."}],"num":69,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a70","label":"제70조","title":"개표소","paras":[{"k":"hang","x":"① 개표소는 선거관리위원들이 개표를 하는 장소를 말하며, 개표장 내에서 방청객과 일정한 거리를 유지하는 위치에 설치하여야 한다."},{"k":"hang","x":"② 개표소에는 선거관리위원과 각 선거운동본부가 파견한 개표참관인만이 출입할 수 있다."}],"num":70,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a71","label":"제71조","title":"개표 시작 시 투표함 이송","paras":[{"k":"line","x":"각 투표함은 투입구와 그 자물쇠가 봉쇄된 채로 선거관리위원이 개표소로 이송한다."}],"num":71,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a72","label":"제72조","title":"개표개시","paras":[{"k":"hang","x":"① 개표는 투표함이 모두 도착한 후 개표준비가 완료되었다고 판단되는 즉시 시행 한다."},{"k":"hang","x":"② 개표참관인은 투표함이 도착한 때에 그 봉인 등을 확인하고 관리상황을 참관한다."},{"k":"hang","x":"③ 투표함 하나의 개표가 끝나기 전에 다른 투표함을 열어서는 안 된다."},{"k":"hang","x":"④ 선거관리위원장은 개표소의 질서가 지나치게 혼잡하여 공정한 개표가 진행될 수 없다고 판단될 때에는 질서 회복이 될 때까지 개표를 중단할 수 있다."}],"num":72,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a73","label":"제73조","title":"개표절차","paras":[{"k":"line","x":"개"},{"k":"line","x":"표절차는 다음 각 호의 순서에 의한다."},{"k":"ho","x":"1. 총 투표자 수 공고"},{"k":"ho","x":"2. 투표함 개봉"},{"k":"ho","x":"3. 개표"},{"k":"ho","x":"4. 개표참관인의 재확인 및 득표의 검산"},{"k":"ho","x":"5. 득표를 후보 별로 분하여 투표함에 재투입"},{"k":"ho","x":"6. 현황판에 기재"},{"k":"ho","x":"7. 제2호부터 제6호까지의 과정을 투표소별로 반복"},{"k":"ho","x":"8. 투표를 시행할 때 그 투표의 결과 확인 및 공고"},{"k":"ho","x":"9. 최종 결과 발표"}],"num":73,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a74","label":"제74조","title":"투표용지의 무효처리","paras":[{"k":"hang","x":"① 다음 각 호의 어느 하나에 해당하는 투표용지는 무효로 한다."},{"k":"ho","x":"1. 어느 란에도 기표를 하지 아니한 것"},{"k":"ho","x":"2. 두 개 이상의 란에 기표한 것"},{"k":"ho","x":"3. 어느 란에 기표를 한 것인지 식별할 수 없는 것"},{"k":"ho","x":"4. 정해진 기표용구를 사용해 기표하지 않은 것"},{"k":"ho","x":"5. 투표용지에 투표관리요원의 서명ㆍ날인이 없는 것"},{"k":"hang","x":"② 다음 각 호의 어느 하나에 해당하는 투표는 무효로 하지 아니한다."},{"k":"ho","x":"1. 기표한 것의 일부분 표시되거나 기표한 것 내부가 메워진 것으로 정해진 기표용구를 사용하여 기표를 한 것이 명확한 것"},{"k":"ho","x":"2. 후보자란 외에 추가 기표되었으나 추가 기표된 것이 어느 후보자에게도 기표한 것으로 볼 수 없는 것"},{"k":"ho","x":"3. 두 후보자란의 구분선상에 기표된 것으로서 어느 후보자에게 기표한 것인지가 명확한 것"},{"k":"ho","x":"4. 기표한 것이 전사된 것으로서 어느 후보자에게 기표한 것인지가 명확한 것"},{"k":"ho","x":"5. 훼손되었으나 정규의 투표용지임이 명백하고 어느 후보자에게 기표한 것인지가 명확한 것"},{"k":"hang","x":"③ 정규의 투표용지를 사용하지 아니한 것은 투표용지로 보지 아니하고, 따라서 무효표로도 보지 아니한다."}],"num":74,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a75","label":"제75조","title":"투표함의 무효처리","paras":[{"k":"hang","x":"① 한 투표소의 명부상 투표자수와 투표함의 투표용지수의 차이(이하 “오차”라 한다)가 명부상 투표자수 대비 3%를 넘을 때 해당 투표함의 결과는 무효가 되며, 해당 투표용지 수만큼 무효표로 산입한다. 단, 명부상 투표자 수가 100 이하일 때는 오차는 3까지 허용한다."},{"k":"hang","x":"② 모든 투표소의 명부상 투표자수 총합과 모든 투표함의 투표용지 수 총합의 차이(이하 “총오차”라 한다)가 명부상 총 투표자수 대비 3%를 넘을 때 투표는 무효가 된다."}],"num":75,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a76","label":"제76조","title":"투표의 효력에 관한 이의에 대한 결정","paras":[{"k":"hang","x":"① 투표의 효력에 관하여 이의가 있는 때에는 선거관리위원회의 재적 위원 과반수의 출석과 출석 위원 과반수의 의결로 결정한다."},{"k":"hang","x":"② 투표의 효력을 결정함에 있어서는 선거인의 의사가 존중되어야 한다."}],"num":76,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a77","label":"제77조","title":"개표참관인","paras":[{"k":"hang","x":"① 각 선거운동본부는 개표 시작 시각 전까지 개표참관인 2명을 선정하여 선거관리위원회에 통보하여야 한다."},{"k":"hang","x":"② 개표참관인은 개표 상황을 참관하고, 득표를 검산하는 등의 역할을 수행한다."},{"k":"hang","x":"③ 개표참관인의 교체는 선거관리위원장의 허가가 있어야 할 수 있다."}],"num":77,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a78","label":"제78조","title":"개표장에서의 질서 유지","paras":[{"k":"line","x":"선거관리위원장은 개표장의 질서가 심히 문란하여 공정한 개표가 시행될 수 없다고 인정되는 때에는 개표소의 질서를 유지하기 위하여 해당인의 퇴장을 명할 수 있다."}],"num":78,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a79","label":"제79조","title":"투표용지ㆍ선거인명부 등의 보관","paras":[{"k":"line","x":"선거관리위원회는 투표용지ㆍ선거인명부 등을 당선 공고 후 48시간 동안 보관하여야 한다."}],"num":79,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제9절 당선"},{"t":"art","id":"a80","label":"제80조","title":"당선의 기준","paras":[{"k":"hang","x":"① 해당 선거에 출마한 후보가 두 조 이상일 경우 개표 결과 최다 득표한 후보를 당선 후보로 한다."},{"k":"hang","x":"② 해당 선거에 출마한 후보가 한 조일 경우 “찬성”표의 수가 “반대”와 “기권”표의 수의 합보다 많을 경우 그 후보를 당선으로 본다."},{"k":"hang","x":"③ 다음 각 호일 때는 당선을 확정할 수 없으며, 재투표ㆍ결선투표ㆍ재선거를 시행한다."},{"k":"ho","x":"1. 총오차가 명부상 총 투표자수 대비 3%를 넘을 때"},{"k":"ho","x":"2. 최고 득표 후보가 두 후보 이상일 때"},{"k":"ho","x":"3. 1위 득표 후보와의 득표 차이가 총오차보다 적은 후보가 있을 때"},{"k":"ho","x":"4. “지지선본 없음”란에 기표한 사람의 수가 1위 득표 조에 기표한 사람의 수를 넘을 때"},{"k":"ho","x":"5. “반대”와 “기권”란에 기표한 사람의 수의 합이 “찬성”란에 기표한 사람의 수 보다 많을 때"}],"num":80,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a81","label":"제81조","title":"당선공고","paras":[{"k":"hang","x":"① 개표 결과가 최종 확인되면 선거관리위원장은 이를 지체 없이 공고하고, 공고한 때로부터 48시간 동안 이의신청을 받는다."},{"k":"hang","x":"② 결과에 관한 이의신청이 있는 때에는 선거관리위원장은 지체 없이 회의를 소집하여 이를 심사한다. 이의신청의 인용ㆍ기각에 관하여서는 재적 위원 과반수의 출석과 출석 위원 과반수의 의결로 결정한다."},{"k":"hang","x":"③ 개표 결과의 최종 공고로부터 48시간 이내에 이의신청이 없으면 선거관리위원회는 당선자의 당선확정을 공고한다. 공고에는 다음 각 호가 포함되어야 한다."},{"k":"ho","x":"1. 학생회장단 당선자의 이름, 소속 학과ㆍ반, 학번"},{"k":"ho","x":"2. 학생회장단 당선자의 선거운동본부명"},{"k":"ho","x":"3. 최종 투표율"},{"k":"ho","x":"4. 투표 결과(각 선거운동본부의 투표소별 득표수, 총 득표수, 득표율을 포함한다)"}],"num":81,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제10절 확정 및 기타"},{"t":"art","id":"a82","label":"제82조","title":"재투표ㆍ결선투표","paras":[{"k":"hang","x":"① 총오차율이 명부상 총 투표자수 대비 3%를 넘을 때는 후보 자격이 있는 모든 후보를 후보로 하여 재투표를 시행한다."},{"k":"hang","x":"② 최고 득표조가 두 조 이상인 때는 각 최고 득표를 기록한 모든 후보를 후보로 하여 결선투표를 시행한다."},{"k":"hang","x":"③ 1위 득표 조와의 득표 차이가 총오차보다 적은 조가 있을 때는 1위 득표 조와 해당 조들을 후보로 하여 결선투표를 시행한다."},{"k":"hang","x":"④ 재투표ㆍ결선투표는 개표 종료 후 7일 안에 3일 동안에 걸쳐 선거운동 없이 시행하며, 투표율에 상관없이 득표수가 많은 후보를 당선으로 한다."}],"num":82,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a83","label":"제83조","title":"재선거","paras":[{"k":"line","x":"다음 각 호 중 하나의 경우에 해당할 경우 재선거를 실시한다."},{"k":"ho","x":"1. 재투표에서도 총오차가 명부상 총 투표자수 대비 3%를 넘을 때"},{"k":"ho","x":"2. 재투표에서도 “지지선본 없음”란에 기표한 사람의 수가 1위 득표 조보다 많을 때"},{"k":"ho","x":"3. 재투표에서 후보가 한 조일 경우 그 득표수가 선거권자 총수의 10% 이상이 아닐 때"}],"num":83,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a84","label":"제84조","title":"투표기간 연기 및 연장","paras":[{"k":"hang","x":"① 해당 선거에 출마한 후보가 한 조일 때 투표율 미달, 천재지변이나 이에 준하는 사태로 투표를 진행할 수 없을 경우 선거관리위원회는 선거관리위원회 회의를 통해 투표를 연기 혹은 연장할 수 있다. 단, 투표연장의 경우 최대 2일까지 연장할 수 있다."},{"k":"hang","x":"② 해당 선거에 출마한 후보가 두 조 이상일 때 천재지변이나 이에 준하는 사태로 투표를 진행할 수 없을 경우 선거관리위원회는 선거관리위원회 회의를 통해 투표를 연기할 수 있다."}],"num":84,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a85","label":"제85조","title":"선거 무효","paras":[{"k":"line","x":"다음 각 호 중 하나의 경우에 해당할 경우 해당 선거는 무효처리가 되고, 비상대책 위원회를 구성한다."},{"k":"ho","x":"1. 해당 선거에서 투표율이 미달될 경우"},{"k":"ho","x":"2. 선거시행세칙 제14조에 의해 선거관리위원회가 해체되었을 경우"}],"num":85,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제5장 선거 기록물 관리"},{"t":"art","id":"a86","label":"제86조","title":"선거 기록물 관리","paras":[{"k":"line","x":"선거에서 생산된 기록물 중 보존의 가치가 있는 것은 선거 일정이 모두 종료된 후 선거관리위원장이 기록물 관리기관으로 이관하고, 기록물 관리기관은 최대한 협조한다."}],"num":86,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"부칙<2017.08.??>","bu":true,"id":"bu1"},{"t":"art","id":"b1-1","label":"제1조","title":"시행일","paras":[{"k":"line","x":"이 세칙은 공포 후 즉시 시행한다. 단 다음 각 호의 사항은 각호의 구분에 의한 날부터 시행한다."},{"k":"ho","x":"1. 제22조1항는 2020학년도 3월 1일부터 시행한다."},{"k":"ho","x":"2. 제5조3항의1호는 2018년 11월 선거부터 적용한다."},{"k":"ho","x":"3. 제10조1항은 2018학년도 1학기부터 적용한다."}],"num":1,"sub":null,"bu":true,"bold_title":false},{"t":"art","id":"b1-2","label":"제2조","title":"선거 시기 조정을 위한 준비행위","paras":[{"k":"line","x":"제22조에도 불구하고 2016학년도 6월 반 학생회장단 선거 다음 순서로 시행하는 반 학생회장단에 대한 세 차례의 선거는 2017년 9월, 2018년 11월, 2020년 6월에 시행한다."}],"num":2,"sub":null,"bu":true,"bold_title":false}],"note":null},{"id":"seongeo-20211113","date":"2021.11.13","kind":"전부개정","title":"자유전공학부 학부·반 선거시행세칙","subtitle":"[고려대학교 자유전공학부 학생회 세칙 제1호]","history":[["2017. 5. 27.","제정"],["2017. 8. 19.","전부개정"],["2021. 11. 13.","전부개정"]],"pdf":"pdf/seongeo-20211113.pdf","pdfName":"자유전공학부_학부·반_선거시행세칙(2021.11.13_전부개정).pdf","blocks":[{"t":"h","lv":2,"text":"제1장 총칙"},{"t":"art","id":"a1","label":"제1조","title":"목적","paras":[{"k":"line","x":"자유전공학부 학부·반 선거시행세칙은 자유전공학부 학부·반 학생회장단 선거에 관한 세부적인 사항을 규정하여 선거가 민주적인 절차에 의하여 공정하게 치러질 수 있도록 함을 목적으로 한다."}],"num":1,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a2","label":"제2조","title":"기본원칙","paras":[{"k":"line","x":"학부·반 학생회장단 선거는 보통ㆍ평등ㆍ직접ㆍ비밀선거를 원칙으로 한다."}],"num":2,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a3","label":"제3조","title":"적용범위","paras":[{"k":"line","x":"이 세칙은 자유전공학부 학부ㆍ반 학생회장단 선거에 적용한다. 단, 반 학생회장단 선거의 경우 동시선거일 때만 본 세칙을 적용한다."}],"num":3,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제2장 선거권과 피선거권"},{"t":"art","id":"a4","label":"제4조","title":"선거권","paras":[{"k":"hang","x":"① 본회 정회원은 학부 학생회장단 선거의 선거권이 있다."},{"k":"hang","x":"② 반 학생회장단 선거의 선거권은 각호를 따른다."},{"k":"ho","x":"1. A반 소속 자유전공학부 학생회 정회원은 A반 학생회장단 선거의 선거권이 있다."},{"k":"ho","x":"2. B반 소속 자유전공학부 학생회 정회원은 B반 학생회장단 선거의 선거권이 있다."},{"k":"ho","x":"3. C반 소속 자유전공학부 학생회 정회원은 C반 학생회장단 선거의 선거권이 있다."},{"k":"ho","x":"4. D반 소속 자유전공학부 학생회 정회원은 D반 학생회장단 선거의 선거권이 있다."},{"k":"hang","x":"③ 선거인 명부는 자유전공학부 행정실을 통해 확인한 재학생 명단, 휴학생 명단을 참고하여 선거관리위원회에서 확정한다."}],"num":4,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a5","label":"제5조","title":"피선거권","paras":[{"k":"hang","x":"① 본회의 정회원인 자는 학부 학생회장단 선거의 피선거권이 있다."},{"k":"hang","x":"② 학부 학생회장단 선거에 출마하려는 후보는 3학기 이상 등록자이어야 한다."},{"k":"hang","x":"③ 다음 각호의 조건을 모두 만족한 자는 반 학생회장단의 피선거권이 있다."},{"k":"ho","x":"1. 선거일 현재 2학기 이상 등록한 자"},{"k":"ho","x":"2. 「자유전공학부 학생회칙」과 이 세칙에 반하는 활동 목적을 갖지 아니한 자"},{"k":"hang","x":"④ 다음 각호에 해당하는 자가 학생회장단 선거에 출마하려는 경우 후보 등록 마감 전까지 해당 직책을 사퇴해야 한다. 단, 현직에 있는 자가 재임을 위해 해당 선거에 출마하려는 경우에는 해당하지 않는다."},{"k":"ho","x":"1. 학부운영위원의 자격을 갖고 있거나 「자유전공학부 학생회칙」 제63조 제4항에 의해 의결권을 가질 수 있는 자"},{"k":"ho","x":"2. 학부 학생회 집행위원으로 활동하고 있는 자"},{"k":"ho","x":"3. 각 반 고학번 대표 및 신입생 대표"},{"k":"ho","x":"4. 각 자치단체장 또는 이에 준하는 자"},{"k":"ho","x":"5. 각 독립기구장 또는 이에 준하는 자"},{"k":"hang","x":"⑤ 징계로서 선거권과 피선거권을 박탈당한 자는 선거의 선거권과 피선거권이 없다."}],"num":5,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제3장 기관"},{"t":"h","lv":3,"text":"제1절 선거관리위원회"},{"t":"art","id":"a6","label":"제6조","title":"목적","paras":[{"k":"line","x":"선거관리위원회는 학생회장단 선거가 민주적인 절차에 의하여 공정하게 치러질 수 있도록 하기 위하여 설립된 기구이다."}],"num":6,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a7","label":"제7조","title":"의무","paras":[{"k":"hang","x":"① 선거관리위원회는 「자유전공학부 학생회칙」 과 세칙을 성실히 준수함으로써 선거 관리에 공정을 기하여야 한다."},{"k":"hang","x":"② 선거관리위원회는 본회 회원의 주권의식을 높이기 위해 올바른 투표방법을 적극적으로 알리고, 불특정 다수에 대한 투표 독려를 해야 한다."}],"num":7,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a8","label":"제8조","title":"업무","paras":[{"k":"line","x":"선거관리위원회는 다음 각호의 사무를 행한다."},{"k":"ho","x":"1. 학생회장단 선거 업무의 기획 및 집행"},{"k":"ho","x":"2. 학생회장단 선거에 대한 홍보"},{"k":"ho","x":"3. 학생회장단 선거의 민주성ㆍ공정성을 높이기 위한 활동"},{"k":"ho","x":"4. 「자유전공학부 학생회칙」과 본 세칙에 따른 각 선거운동본부 감시"},{"k":"ho","x":"5. 「자유전공학부 학생회칙」과 본 세칙을 위반한 선거운동본부에 대한 징계 조치"},{"k":"ho","x":"6. 그 외에 학생회장단 선거 운영에 필요하다고 인정되는 사안"}],"num":8,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a9","label":"제9조","title":"구성","paras":[{"k":"hang","x":"① 선거관리위원회는 최소한 투표 개시일 21일 전에 학부운영위원회의 승인을 받아 구성 되어야 한다."},{"k":"hang","x":"② 선거관리위원회는 학부 학생회장단을 제외한 학부운영위원 및 학생회칙 제63조 제4항에 의해 의결권을 가질 수 있는 자 전원을 기본으로 구성하며, 나머지 인원은 공개모집함을 원칙으로 한다. 단, 반 학생회장단 동시선거의 경우 해당 선거를 진행하는 선거관리위원회는 학부운영위원 및 학생회칙 제63조 제4항에 의해 의결권을 가질 수 있는 자 전원을 기본으로 구성하며, 나머지 인원은 공개모집함을 원칙으로 한다."},{"k":"hang","x":"③ 선거관리위원회는 학부운영위원회 회의에서 인준받은 8인 이상 12인 이하의 선거관리위원으로 구성된다. 단, 모집인원이 12인 이상일 경우 선착순으로 함을 원칙으로 한다."},{"k":"hang","x":"④ 선거관리위원의 충원이 필요할 시 선거관리위원을 추가로 공개모집 할 수 있으며 변동사항을 학부운 영위원회에서 인준 받아야 한다."},{"k":"hang","x":"⑤ 후보 등록기간이 시작된 뒤 선거시행세칙 제12조에 의해 선거관리위원의 결손이 생겼을 경우, 선거관리위원회는 선거관리 위원을 충원하지 못한다."},{"k":"hang","x":"⑥ 선거시행세칙 제13조에 의해 선거관리위원회가 해체되었을 경우, 해당 선거는 무효가 되며, 학부운영 위원회는 지체 없이 재선거를 위한 선거관리위원회를 구성해야 한다. 단, 해체된 선거관리위원회의 선거관리위원은 구성원이 될 수 없다."}],"num":9,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a10","label":"제10조","title":"선거관리위원장","paras":[{"k":"hang","x":"① 선거관리위원장은 선거관리위원회에서 민주적으로 선출한다. 선출된 선거관리위원장은 지체 없이 학부운영위원회에서 인준 받아야 한다."},{"k":"hang","x":"② 선거관리위원장은 선거관리위원회를 대표하고, 그 사무를 총괄한다."},{"k":"hang","x":"③ 선거관리위원장은 선거관리위원회 회의의 의장이 된다."},{"k":"hang","x":"④ 선거관리위원장이 사고 시에는 선거관리위원회의 내부적 호선을 통해 다른 선거관리위원 중 한 명이 그 직무를 대신한다. 단, 이를 학부운영위원회에 통보해야 한다."}],"num":10,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a11","label":"제11조","title":"선거관리위원회 회의","paras":[{"k":"hang","x":"① 선거관리위원회는 선거관리와 관련된 모든 문제를 선거관리위원회 회의를 통해 처리한다."},{"k":"hang","x":"② 선거관리위원회 회의는 각호 중 하나에 의해 위원장이 소집한다."},{"k":"ho","x":"1. 선거관리위원장의 소집요구"},{"k":"ho","x":"2. 선거관리위원회 재적 위원 3분의 1 이상의 연서에 따른 소집요구"},{"k":"ho","x":"3. 선거운동본부의 후보자 또는 선거운동본부장의 이의제기에 따른 소집요구"},{"k":"hang","x":"③ 선거관리위원회 회의는 재적 선거관리위원 과반수의 출석으로 개의하고, 출석 선거관리위원 과반수의 찬성으로 의결한다. 이 때 표결은 기명으로 함을 원칙으로 한다. 단, 중요한 안건으로서 위원장 또는 위원이 제기하여 선거관리위원회가 의결하거나 재적 위원 3분의 1 이상의 요구가 있을 때에는 표결을 무기명으로 할 수 있다. 또한 선거관리위원 파면에 관한 안건은 제12조에 따라 의결한다."},{"k":"hang","x":"④ 의장은 안건에 대한 이의의 유무를 물어서 이의가 없다고 인정한 때에는 가결되었음을 선포할 수 있 다. 이의가 있을 때 또는 표결을 무기명으로 할 때에는 반드시 표결하여야 한다."},{"k":"hang","x":"⑤ 선거관리위원회는 원활한 선거관리를 위하여 다음 각호에 해당하는 자의 회의 출석을 요구할 수 있다."},{"k":"ho","x":"1. 후보"},{"k":"ho","x":"2. 각 선거운동본부의 선거운동본부장"},{"k":"ho","x":"3. 선거운동본부에 대한 징계 사유와 관련된 자"}],"num":11,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a12","label":"제12조","title":"선거관리위원의 직권남용","paras":[{"k":"hang","x":"① 선거관리위원장을 포함한 선거관리위원이 본회 선거시행세칙을 지키지 않았을 경우 본회 회원은 이에 대해 선거관리위원회에 이의제기를 할 수 있다. 이의제기가 있는 즉시 선거관리위원장은 선거관리위원회 회의를 소집하여야 하고, 선거관리위원회 회의의 의결에 따라 해당 선거관리위원은 파면될 수 있다."},{"k":"hang","x":"② 선거관리위원의 파면은 재적 선거관리위원 과반수의 출석과 출석 선거관리위원 3분의 2 이상의 찬성으로 의결한다. 이때 이의제기의 대상이 된 선거관리위원은 재적 위원과 출석 위원의 수에서 제외한다."}],"num":12,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a13","label":"제13조","title":"선거관리위원회의 직권남용","paras":[{"k":"line","x":"선거관리위원회가 직권을 남용해 본회 선거시행세칙을 지키지 않았을 경우 본회 회원은 해당 선거관리위원회의 징계를 집행위원회에 청구할 수 있다. 징계의 청구 방법, 징계 절차 등에 대해서는 「고려대학교 자유전공학부 징계 세칙」을 따른다."}],"num":13,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a14","label":"제14조","title":"재정 및 운영","paras":[{"k":"hang","x":"① 선거관리위원회의 선거관리비용은 학생회비에서 사후 전액 지원받는 것을 원칙으로 한다."},{"k":"hang","x":"② 선거관리위원장은 선거관리위원회 구성과 동시에 선거관리비용에 대한 예산안을 작성하여 이를 학부 운영위원회에서 인준받는다."},{"k":"hang","x":"③ 선거관리위원장은 선거가 끝난 후 선거관리비용에 대한 결산을 작성하여 이를 학부운영위원회에서 심의받는다."},{"k":"hang","x":"④ 학부운영위원회는 심의 후 선거관리비용에 대한 금액 지원을 결정한다."}],"num":14,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 선거운동본부"},{"t":"art","id":"a15","label":"제15조","title":"정의","paras":[{"k":"line","x":"선거운동본부는 학생회장단 선거에 등록한 후보의 선거운동을 통해 해당 후보의 당선을 도모하고, 각 현안에 대한 의견표명ㆍ정책개발 등을 통해 선거와 관련된 의사형성에 도움을 주는 회원의 자발적 조직을 말한다."}],"num":15,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a16","label":"제16조","title":"의무","paras":[{"k":"hang","x":"① 선거운동본부는 학생회장단 선거가 민주적이고 공정하게 치러지도록 노력하여야 한다."},{"k":"hang","x":"② 선거운동본부는 학생회장단 선거가 발전적인 정책 선거로 치러지도록 노력하여야 한다."},{"k":"hang","x":"③ 선거운동본부는 학생회장단 선거가 원활하게 진행될 수 있도록 선거관리위원회에 최대한 협조하여야 한다."}],"num":16,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a17","label":"제17조","title":"구성","paras":[{"k":"hang","x":"① 선거운동본부는 학생회장단 선거 후보, 선거운동본부장, 선거운동본부원으로 구성된다."},{"k":"hang","x":"② 선거운동본부장 및 선거운동본부원은 본회의 회원이어야 한다."}],"num":17,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a18","label":"제18조","title":"모집공고","paras":[{"k":"hang","x":"① 선거운동본부는 선거 공고가 있은 후부터 본부원 모집을 위한 공고를 할 수 있다. 단, 공고문에는 다음 각호의 사항을 제외하고는 명시할 수 없다."},{"k":"ho","x":"1. 선거운동본부명"},{"k":"ho","x":"2. 후보의 이름, 소속 학부ㆍ과ㆍ반, 학번"},{"k":"ho","x":"3. 선거운동본부장의 이름, 소속 학부ㆍ과ㆍ반, 학번"},{"k":"ho","x":"4. 후보 및 선거운동본부장의 연락처"},{"k":"ho","x":"5. 500자 내외의 선거운동본부 소개"},{"k":"hang","x":"② 선거운동본부원을 모집하고자 하는 선거운동본부는 제1항의 공고문을 선거관리위원회에 제출하여 허가를 받아야 한다. 선거관리위원회는 선거운동본부원 모집 공고문이 접수되면 지체 없이 선거관리위원회 회의를 열어 공고문을 심의한다."},{"k":"hang","x":"③ 공고문에 결함이 있을 때 선거관리위원회는 공고문의 게시를 허가하지 않을 수 있으며, 해당 선거운동본부는 결함이 있는 부분을 시정하여 공고문을 다시 심의받을 수 있다."}],"num":18,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a19","label":"제19조","title":"선거운동본부장","paras":[{"k":"hang","x":"① 선거운동본부장은 해당 선거운동본부를 대표하고, 선거 과정 전반에서 후보를 보좌하며, 후보를 대신하여 선거관리위원회를 상대로 선거 운영 전반에 대한 의사를 표명할 수 있다."},{"k":"hang","x":"② 선거운동본부장은 해당 선거운동본부의 학생회장단 후보가 임명한다."},{"k":"hang","x":"③ 학생회장단 후보는 선거운동본부장을 교체할 수 있다. 단, 이를 선거관리위원회에 보고하며 선거관리위원회는 선거운동본부장의 교체 신청이 접수되면 지체 없이 이를 심사하여 승인한다."}],"num":19,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a20","label":"제20조","title":"선거운동본부원","paras":[{"k":"hang","x":"① 각 선거운동본부는 선거운동본부원을 선거관리위원회에 등록하여야 한다."},{"k":"hang","x":"② 선거운동본부원 등록은 후보 등록 신청과 함께 등록하며, 그 이후부터는 변동 사항이 있을 경우 이를 선거관리위원회에 보고한다."},{"k":"hang","x":"③ 선거관리위원회에 선거운동본부원으로 등록되지 않은 자는 해당 선거운동본부의 본부원으로 활동할 수 없다."},{"k":"hang","x":"④ 한 선거운동본부의 본부원으로 등록된 상태에서는 다른 선거운동본부의 본부원으로 등록할 수 없다."}],"num":20,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제4장 선거"},{"t":"h","lv":3,"text":"제1절 선거일정"},{"t":"art","id":"a21","label":"제21조","title":"선거일정의 결정","paras":[{"k":"hang","x":"① 본회 학부·반 학생회장단 선거는 11월 중에 시행함을 원칙으로 한다."},{"k":"hang","x":"② 학생회장단 선거일정은 선거 공고, 등록 기간, 선거운동기간, 투표일, 개표일, 당선공고로 구성된다."},{"k":"hang","x":"③ 선거관리위원회는 등록 기간을 5일 이내, 선거운동기간을 5일 이내, 투표일을 3일로 하여 선거일정을 정한다. 등록 기간과 투표일을 정함에 있어서 토요일과 공휴일은 기간에 산입하지 않는 것을 원칙으로 한다."},{"k":"hang","x":"④ 그 외 구체적인 선거일정은 선거관리위원회에서 정한다."}],"num":21,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a22","label":"제22조","title":"선거 공고","paras":[{"k":"line","x":"선거관리위원회는 구성 후 최소한 투표 개시일 14일 전까지 다음 각호를 명시한 선거 공고를 하여야 한다. 단 재투표의 경우, 투표 개시일 7일 전까지 공고한다."},{"k":"ho","x":"1. 선거관리위원회 활동개시의 뜻"},{"k":"ho","x":"2. 선거 일정"},{"k":"ho","x":"3. 후보 등록에 필요한 서류 목록"},{"k":"ho","x":"4. 선거관리위원장 및 선거관리위원 명단"},{"k":"ho","x":"5. 선거관리위원들의 공정한 선거 진행을 위한 서약 내용 및 서명"}],"num":22,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 후보등록"},{"t":"art","id":"a23","label":"제23조","title":"후보등록","paras":[{"k":"hang","x":"① 학부 학생회장단 선거에 등록하려는 자는 다음 각호의 서류를 첨부하여 선거관리위원회에 제출하여야 한다."},{"k":"ho","x":"1. 본 세칙 제5조 제2항의 요건을 충족하는 재학증명서 또는 휴학증명서"},{"k":"ho","x":"2. 선거운동본부장의 재학증명서 또는 휴학증명서"},{"k":"ho","x":"3. 선거운동본부명"},{"k":"ho","x":"4. 출마 소견문"},{"k":"ho","x":"5. 정회원 50인 이상의 추천서명-정회원 50인 이상의 추천서명에 있어서 당해 연도 입학한 학번 10명 이상, 이전 연도 입학한 학번 10명 이상, 그 이전에 입학한 학번 10명 이상의 추천서명을 받는 것을 원칙으로 한다."},{"k":"ho","x":"6. 선거운동본부원 명부"},{"k":"hang","x":"② 반 학생회장단 선거에 등록하려는 자는 다음 각호의 서류를 첨부하여 선거관리위원회에 제출하여야 한다."},{"k":"ho","x":"1. 본 세칙 제5조 제3항 제1호의 요건을 충족하는 재학증명서 또는 휴학증명서"},{"k":"ho","x":"2. 선거운동본부장의 재학증명서 또는 휴학증명서"},{"k":"ho","x":"3. 선거운동본부명"},{"k":"ho","x":"4. 출마 소견문"},{"k":"ho","x":"5. 정회원 15인 이상의 추천서명-정회원 15인 이상의 추천서명에 있어서 당해 연도 입학한 학번 5명 이상, 그 이전에 입학한 학번 5명 이상의 추천서명을 받는 것을 원칙으로 한다."},{"k":"ho","x":"6. 선거운동본부원 명부"},{"k":"hang","x":"③ 후보등록 서류양식 및 제출방식은 선거관리위원회에서 정하며, 선거관리위원회가 정한 서류양식 및 제출방식이 아닌 서류는 모두 무효이다."},{"k":"hang","x":"④ 선거관리위원회는 모든 학생회장단 선거 등록자에게 동일한 서류양식 및 제출방식으로 서류를 제출 받아야 한다."},{"k":"hang","x":"⑤ 추천서명은 추천인의 자필서명을 원칙으로 한다. 단, 선거관리위원회는 추천인의 서명을 추천인 본인 확인이 가능한 전자서명 또는 이에 준하는 수단으로 대체하여 받을 수 있다."}],"num":23,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a24","label":"제24조","title":"후보 등록 심사","paras":[{"k":"hang","x":"① 선거관리위원회는 후보 등록 마감 후 24시간 이내에 선거관리위원회 회의를 열어 후보등록을 위 한 서류들을 검토한다."},{"k":"hang","x":"② 제1항의 회의에는 각 선거운동본부의 후보, 선거운동본부장이 모두 참석하여야 한다."},{"k":"hang","x":"③ 선거관리위원회는 서류 검토 후 특별한 결격사유가 없을 경우 이를 즉시 수리해야 한다. 단, 하자가 있을 시, 즉시 등록 불가 의사와 그 사유를 공고한다."},{"k":"hang","x":"④ 등록이 마무리된 후에는 제출한 서류의 내용을 퇴고하거나 수정할 수 없다."}],"num":24,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a25","label":"제25조","title":"사전 규칙확정회의","paras":[{"k":"hang","x":"① 사전 규칙확정회의는 후보 등록 심사가 완료된 직후 선거운동에 관한 기본적인 사항을 합의하기 위해 각 선거운동본부와 선거관리위원회 간에 이루어지는 회의를 말한다."},{"k":"hang","x":"② 사전 규칙확정회의는 다음 각호의 사항들을 합의 사항으로 한다."},{"k":"ho","x":"1. 개인유세·합동유세의 개최 여부 및 세부적인 운영 방법"},{"k":"ho","x":"2. 후보간담회·공청회의 개최 여부 및 세부적인 운영 방법"},{"k":"ho","x":"3. 인터넷 선거운동 공간의 구성 및 세부적인 운영 방법"},{"k":"ho","x":"4. 선거운동본부 선전물(유인물·소책자 등)의 규격, 수량 및 게시·배포 방법"},{"k":"ho","x":"5. 선거운동본부복의 착용 여부"},{"k":"ho","x":"6. 선거관리위원회 제작 선전벽보의 규격, 수량 및 게시 위치"},{"k":"ho","x":"7. 그 밖의 선거운동에 관련된 기본적인 사항"},{"k":"hang","x":"③ 선거관리위원회는 사전 규칙확정회의 시 징계에 해당하는 행위, 투표참관인 및 개표참관인 등록일정 등 본 세칙에 기반한 원활한 선거 진행을 위해 필요한 사항들을 각 선거운동본부에 고지하여야 한다."}],"num":25,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a26","label":"제26조","title":"복수추천의 허용","paras":[{"k":"line","x":"선거권자는 동일한 선거에서 서로 다른 후보를 동시에 추천할 수 있다. 단, 동일후보에 대한 중복 추천 서명은 인정하지 않는다."}],"num":26,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a27","label":"제27조","title":"후보의 사퇴","paras":[{"k":"line","x":"후보가 사퇴하고자 하는 때에는 본인이 직접 선거관리위원회에 사유서를 제출하여야 한다. 단, 선거운동 기간 후에는 사퇴할 수 없다."}],"num":27,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a28","label":"제28조","title":"후보 등록 등의 공고","paras":[{"k":"hang","x":"① 선거관리위원회는 후보 등록 다음 날까지 다음 각호의 사항을 명시한 입후보자 공고를 해야 한다."},{"k":"ho","x":"1. 후보의 이름, 소속 학과ㆍ반, 학번"},{"k":"ho","x":"2. 선거운동본부명 및 선거운동본부장의 이름, 소속 학과ㆍ반, 학번"},{"k":"hang","x":"② 선거관리위원회는 후보가 사퇴ㆍ사망하거나 후보 자격이 박탈되면 지체 없이 이를 공고한다."}],"num":28,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a29","label":"제29조","title":"후보가 없는 경우","paras":[{"k":"line","x":"후보로 아무도 등록하지 않거나, 등록한 모든 후보의 사퇴 등으로 후보가 없어 해당 선거가 무산된 경우, 「자유전공학부 학생회칙」 또는 각 「반 학생회칙」에 따라 비상대책위원회를 구성한다."}],"num":29,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제3절 선거운동"},{"t":"art","id":"a30","label":"제30조","title":"선거운동","paras":[{"k":"hang","x":"① 선거운동이라 함은 특정 후보의 당선을 위한 제반 행위이다."},{"k":"hang","x":"② 선거운동은 다음 각호의 방법으로 한다."},{"k":"ho","x":"1. 개인유세ㆍ합동유세"},{"k":"ho","x":"2. 선전물의 게시ㆍ배포"},{"k":"ho","x":"3. 간담회ㆍ공청회"},{"k":"ho","x":"4. 인터넷 선거운동 공간의 구성 및 운영"},{"k":"ho","x":"5. 선거운동본부복의 착용"},{"k":"ho","x":"6. 그 밖의 당선을 위한 각종 행위"},{"k":"hang","x":"③ 다음 각호의 행위는 선거운동으로 보지 않는다."},{"k":"ho","x":"1. 선거에 관한 일반적인 의견개진 및 의사표시"},{"k":"ho","x":"2. 후보등록을 위한 준비 행위"},{"k":"ho","x":"3. 회원의 특정 후보자 단순 지지 표명 행위"},{"k":"hang","x":"④ 선거운동은 본회 선거시행세칙에 규정된 것 이외의 방법으로는 할 수 없다."}],"num":30,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a31","label":"제31조","title":"선거운동기간","paras":[{"k":"hang","x":"① 선거운동기간은 후보 등록이 마무리 된 이후부터 투표일 전날 24시 사이에서 선거관리위원회가 결정한다. 단, 부착된 A0규격의 선전물은 본 세칙 제36조 제2항에 해당하지 않는 한 투표 종료일까지 게시 가능하다."},{"k":"hang","x":"② 사전선거운동은 허용하지 않는다. 단, 추천 서명을 받는 행위는 사전선거운동으로 보지 않는다."}],"num":31,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a32","label":"제32조","title":"선거운동을 할 수 없는 자","paras":[{"k":"line","x":"다음 각호에 해당하는 자는 선거운동을 할 수 없다."},{"k":"ho","x":"1. 선거관리위원장 및 선거관리위원"},{"k":"ho","x":"2. 본회의 회원이 아닌 자"},{"k":"ho","x":"3. 본회 회원 중 적법한 절차를 거쳐 선거운동본부원으로 등록하지 않은 자"}],"num":32,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a33","label":"제33조","title":"선거관리위원회 제작 선전벽보","paras":[{"k":"hang","x":"① 선거관리위원회는 후보 등록이 완료된 다음날까지 다음 각호의 사항을 명시한 선거관리위원회 제 작 선전벽보를 게시하여야 한다."},{"k":"ho","x":"1. 후보의 사진, 이름, 소속 학과ㆍ반, 학번"},{"k":"ho","x":"2. 선거운동본부명"},{"k":"ho","x":"3. 핵심 공약"},{"k":"hang","x":"② 선거관리위원회 제작 선전벽보의 규격, 수량과 게시 위치는 선거관리위원회와 각 선거운동본부의 합의로 결정한다."}],"num":33,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a34","label":"제34조","title":"선거운동 일정의 보고의무","paras":[{"k":"hang","x":"① 각 선거운동본부는 선거운동 일정을 선거관리위원회에 보고해야 한다."},{"k":"hang","x":"② 선거관리위원회가 보고받은 사항 중 각 선거운동본부의 일정이 겹치는 부분에 대해서는 선거관리위원회가 공정하게 조정한다."},{"k":"hang","x":"③ 보고되지 않은 선거운동이 진행되는 경우, 선거관리위원회는 선거운동이 더 이상 진행되지 않도록 막을 수 있으며, 그 위반 사실을 지체 없이 공고해야 한다."}],"num":34,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a35","label":"제35조","title":"선전물의 사전허가","paras":[{"k":"hang","x":"① 각 선거운동본부는 선거관련 선전물을 선거관리위원회의 허가를 거친 후 게시ㆍ배포한다."},{"k":"hang","x":"② 선거 관련 선전물에 타 후보에 대한 비방 등 선거의 공정성을 해칠 수 있는 내용이 있으면 선거관리 위원회가 게시ㆍ배포 금지 처분을 할 수 있다."},{"k":"hang","x":"③ 선거관리위원회에 신고하지 않은 선전물을 게시ㆍ배포하면 선거관리위원회는 해당 선거운동본부에 해당 게시물ㆍ유인물의 수거를 명할 수 있다."}],"num":35,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a36","label":"제36조","title":"선전물","paras":[{"k":"hang","x":"① A0규격을 초과하는 선전물은 게시할 수 없다."},{"k":"hang","x":"② 선거운동기간 중에 게시된 선전물은 투표 종료일까지 게시가 가능하다. 단, 투표소로부터 10m 이내 에 게시된 선거운동본부의 선전물은 제거하여야 한다."},{"k":"hang","x":"③ 각 선거운동본부는 선거운동기간 동안 유인물과 표지를 포함한 20쪽 내의 소책자를 배포할 수 있으며, 유인물과 소책자의 규격 및 개수 등의 사항은 선거운동기간 전에 각 선거운동본부와 선거관리위원회의 합의로 결정한다."},{"k":"hang","x":"④ 선거운동본부원이 타 선거운동본부의 선전물을 임의로 제거할 수 없다."},{"k":"hang","x":"⑤ 선거관리위원회는 선거운동본부의 선전물의 게시ㆍ배포를 최대한 보장하여야 한다."}],"num":36,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a37","label":"제37조","title":"개인유세","paras":[{"k":"hang","x":"① 개인유세는 각 선거운동본부의 후보 또는 선거운동본부원들이 선거운동의 일환으로 벌이는 강의실 유세, 선거 물품 배포 등의 모든 종류의 선전활동을 말한다."},{"k":"hang","x":"② 개인유세는 8시부터 20시까지 가능하다."},{"k":"hang","x":"③ 선거관리위원회는 선거의 민주성ㆍ대중성 향상을 위하여 각 선거운동본부의 개인유세를 최대한 보장 하여야 한다."},{"k":"hang","x":"④ 개인유세는 각 선거운동본부가 수시로 개최할 수 있다. 단, 지나친 소음 등으로 학우들의 불편을 초래할 위험이 있거나, 초래한 때는 선거관리위원회가 이를 제한할 수 있다."},{"k":"hang","x":"⑤ 개인유세와 관련된 세부적인 사항들은 선거운동기간 전에 각 선거운동본부와 선거관리위원회의 합의로 결정한다."}],"num":37,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a38","label":"제38조","title":"합동유세","paras":[{"k":"hang","x":"① 두 개 이상의 선거운동본부가 등록한 경우, 선거관리위원회는 합동유세를 개최할 수 있으며, 합동유세의 진행은 선거관리위원장이 담당한다."},{"k":"hang","x":"② 합동유세에서의 유세 순서는 합동유세 전에 추첨하여 정한다."},{"k":"hang","x":"③ 후보자는 유세시간을 준수하여야 한다. 각 선거운동본부 당 유세시간은 선거관리위원회에서 결정하 며, 제한시간을 초과하면 선거관리위원회는 마이크 등 유세시설을 철거하여 유세를 중단시킨다. 단, 유세 자를 교체하기 위해 소요되는 시간은 유세시간에 포함되지 않는다."},{"k":"hang","x":"④ 후보자는 합동유세가 끝날 때까지 합동유세장에서 퇴장할 수 없다. 단, 부득이할 때는 선거관리위원 장의 동의에 따라 10분 이내로 자리를 비울 수 있다."},{"k":"hang","x":"⑤ 후보자는 타 후보자의 유세 시간 중에 유세를 방해하거나 소속 선거운동본부의 선전물을 배포하는 행위를 할 수 없다."},{"k":"hang","x":"⑥ 선거관리위원회는 합동유세장에서 연설을 방해하거나 장내 질서를 어지럽히는 자가 있을 때 퇴장을 명할 수 있다."},{"k":"hang","x":"⑦ 합동유세와 관련된 세부적인 사항들은 선거운동기간 전에 각 선거운동본부와 선거관리위원회의 합의로 결정한다."}],"num":38,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a39","label":"제39조","title":"인터넷에서의 선거운동","paras":[{"k":"hang","x":"① 각 선거운동본부는 인터넷에 홈페이지, 카페, 커뮤니티 등의 인터넷 선거운동 공간을 구성할 수 있다."},{"k":"hang","x":"② 각 선거운동본부의 후보, 선거운동본부장, 선거운동본부원은 선거관리위원회가 허용한 공간 이외의 인터넷 공간에서 논쟁ㆍ답변 등의 의사표현 행위를 할 수 없다."},{"k":"hang","x":"③ 그 밖의 인터넷에서의 선거운동과 관련해서는 선거관리위원회와 선거운동본부의 합의로 결정한다."}],"num":39,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a40","label":"제40조","title":"후보간담회","paras":[{"k":"hang","x":"① 각 선거운동본부는 선거운동기간 중 간담회를 주최할 수 있다."},{"k":"hang","x":"② 후보간담회의 구체적인 운영방법은 선거관리위원회와 선거운동본부의 합의로 결정한다."}],"num":40,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a41","label":"제41조","title":"공청회","paras":[{"k":"hang","x":"① 선거운동본부는 선거관리위원회에 공청회를 요청할 수 있으며, 선거관리위원회는 정당한 사유 없이 선거운동본부의 요청을 거부할 수 없다."},{"k":"hang","x":"② 선거운동본부가 두 개 이상일 경우, 선거관리위원회에서 합동공청회를 진행할 수 있다."},{"k":"hang","x":"③ 공청회는 선거관리위원회 주재 하에 개최된다."},{"k":"hang","x":"④ 공청회의 사회는 선거관리위원 중 한 명이 맡는다."},{"k":"hang","x":"⑤ 공청회의 구체적인 운영방법은 선거관리위원회와 선거운동본부의 합의에 따라 결정한다."}],"num":41,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a42","label":"제42조","title":"선거운동 비용","paras":[{"k":"hang","x":"① 선거운동 비용은 후보가 선거에 입후보한 때부터 당해 선거의 당선인이 결정될 때까지 선거 사무를 처리하기 위해 소모한 금전, 물건, 기타 재산상 가치를 말한다."},{"k":"hang","x":"② 각 선거운동본부의 선거운동 비용은 선거운동 비용의 최대 80%까지 학생회비에서 사후 지원받을 수 있다."},{"k":"hang","x":"③ 각 선거운동본부의 선거운동본부장은 투표를 통해 당선 및 낙선이 확정된 이후, 선거운동 비용에 대한 결산을 작성하여 이를 학부운영위원회에서 심의받는다. 이 때 결격사유가 발견될 경우 학부운영위원회는 학생회비 지원을 하지 않을 수 있다."}],"num":42,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제4절 이의제기"},{"t":"art","id":"a43","label":"제43조","title":"이의제기의 방식","paras":[{"k":"hang","x":"① 본회 회원은 공정한 선거를 위하여 본회의 학생회칙 및 선거시행세칙에 반하는 행위를 선거관리위원회에 고발할 의무를 지닌다."},{"k":"hang","x":"② 선거에 관한 이의제기는 한 선거운동본부 내에서는 각 선거운동본부의 후보와 선거운동본부장만 할 수 있다."},{"k":"hang","x":"③ 각 선거운동본부는 후보 또는 선거운동본부장 명의의 서면으로 이의제기를 하여야 한다."},{"k":"hang","x":"④ 투표와 관련해서는 해당 투표소에 파견된 투표참관인이 후보 또는 선거운동본부장을 대신하여 구두로 이의제기를 할 수 있다. 단, 이때 해당 선거운동본부는 24시간 이내에 해당 이의제기 내용을 서면으로 다시 제출하여야 한다."},{"k":"hang","x":"⑤ 개표와 관련해서는 후보 또는 선거운동본부장이 구두로 이의제기를 할 수 있다. 단, 이 때 해당 선거운동본부는 24시간 이내에 해당 이의제기 내용을 서면으로 다시 제출하여야 한다."},{"k":"hang","x":"⑥ 선거운동본부가 제2항 내지 제5항을 위반하면 선거관리위원회가 해당 선거운동본부에 시정명령을 내릴 수 있다."}],"num":43,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a44","label":"제44조","title":"이의제기의 처리","paras":[{"k":"hang","x":"① 이의제기가 있으면 선거관리위원장은 지체 없이 회의를 소집하여 이를 심의하여 처리한다."},{"k":"hang","x":"② 이의제기의 처리는 선거관리위원회 재적 위원 과반수 출석과 출석 위원 과반수 찬성으로 의결한다."}],"num":44,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제5절 징계"},{"t":"art","id":"a45","label":"제45조","title":"징계","paras":[{"k":"line","x":"징계라 함은 본 세칙에 반하는 행위를 하거나, 선거관리위원회가 징계 사유라고 정한 행위를 할 때 해당 선거운동본부에 제재를 가하는 것을 말한다."}],"num":45,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a46","label":"제46조","title":"징계의 종류","paras":[{"k":"hang","x":"① 징계는 시정명령, 주의, 경고로 나뉜다."},{"k":"hang","x":"② 동일한 내용으로 시정명령이 2회 누적되면 주의 1회를 받은 것으로 한다. 시정명령 2회가 주의 1회로 전환되면, 해당 시정명령 2회는 소멸한다."},{"k":"hang","x":"③ 주의가 2회 누적되면 경고 1회를 받은 것으로 한다. 주의 2회가 경고 1회로 전환되면, 해당 주의 2회는 소멸한다."},{"k":"hang","x":"④ 경고가 3회 누적되면 해당 선거운동본부의 후보 자격을 박탈한다."}],"num":46,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a47","label":"제47조","title":"시정명령","paras":[{"k":"line","x":"다음 각호의 사항에 해당할 때 선거관리위원회는 해당 선거운동본부에 시정명령을 내릴 수 있다."},{"k":"ho","x":"1. 선거운동본부원 모집을 위한 공고문에 결함이 있을 때"},{"k":"ho","x":"2. 선거운동본부원의 등록 절차상의 문제가 있을 때"},{"k":"ho","x":"3. 게시물ㆍ선전물의 사전 허가를 위한 회의 결과 본 세칙에서 규정하고 있는 규격과 맞지 않을 때"},{"k":"ho","x":"4. 투·개표 참관인이 정당한 이유 없이 참관을 거부하거나 태만하는 경우"},{"k":"ho","x":"5. 그 외 선거 진행에 큰 지장을 주지는 않으나, 본 세칙을 위반한 것이 분명하여 선거관리위원회에서 판단하기에 시정명령에 해당할 때"}],"num":47,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a48","label":"제48조","title":"주의","paras":[{"k":"line","x":"다음 각호의 사항에 해당할 때 선거관리위원회는 해당 선거운동본부에 주의를 내릴 수 있다. 주의를 내릴 경우 해당 사실을 온라인 및 오프라인 게시를 통해 공고한다."},{"k":"ho","x":"1. 시정명령을 받은 후에도 해당 선거운동본부가 징계 사유에 해당하는 행위를 2시간 이내에 시정하지 않을 때"},{"k":"ho","x":"2. 동일한 내용으로 시정명령을 두 번 받았을 때"},{"k":"ho","x":"3. 선거관리위원회로부터 허가받지 않은 선거운동본부원의 모집 공고문을 게시할 때"},{"k":"ho","x":"4. 후보 등록 신청 시 제출한 서류ㆍ파일에 결함이 있을 때"},{"k":"ho","x":"5. 선거운동을 할 수 없는 자로 규정된 자가 선거운동을 할 때"},{"k":"ho","x":"6. 본 세칙 및 사전 규칙확정회의에서 정해진 개인유세ㆍ합동유세ㆍ후보간담회ㆍ공청회 등의 합의사항을 준수하지 않을 때"},{"k":"ho","x":"7. 게시물ㆍ유인물의 사전 허가를 위한 회의 결과 타 후보에 대한 비방 등 선거의 공정성을 해칠 수 있는 내용이 있을 때"},{"k":"ho","x":"8. 선거운동본부에 소속된 인원 중 허용되지 않은 자가 온라인 선거운동을 할 때"},{"k":"ho","x":"9. 투·개표 참관인을 허가 없이 교체했을 경우"},{"k":"ho","x":"10. 그 외 선거운동본부의 행위가 공정한 선거 진행을 해치는 것이 분명하여 선거관리위원회에서 판단하기에 주의에 해당할 때"}],"num":48,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a49","label":"제49조","title":"경고","paras":[{"k":"hang","x":"① 다음 각호의 사항에 해당할 때 선거관리위원회는 해당 선거운동본부에 경고를 내릴 수 있다. 경고를 내릴 경우 해당 사실을 온라인 및 오프라인 게시를 통해 공고한다."},{"k":"ho","x":"1. 주의를 받은 후에도 해당 선거운동본부가 징계 사유에 해당하는 행위를 2시간 이내에 시정하지 않을 때"},{"k":"ho","x":"2. 한 선거운동본부에 주의가 2회 누적될 때"},{"k":"ho","x":"3. 사전선거운동을 할 때"},{"k":"ho","x":"4. 사전 허가를 받지 않은 게시물ㆍ유인물을 게시ㆍ배포할 때"},{"k":"ho","x":"5. 특정 후보자의 당락이나 선거인의 자유로운 투표의사에 영향을 미치게 할 목적으로 선거인, 다른후보자, 다른 선거운동본부의 본부장ㆍ및 본부원, 참관인에게 금전ㆍ물품ㆍ향응 그 밖에 재산상의 이익을 제공하거나 그 제공의 의사를 표시하거나 그 제공을 약속할 때"},{"k":"ho","x":"6. 선거에 관하여 다른 후보자, 다른 선거운동본부의 본부장ㆍ본부원을 폭행ㆍ협박하거나 선거운동용 물품을 탈취할 때"},{"k":"ho","x":"7. 선거에 관하여 집회ㆍ연설을 방해하거나 그 밖에 부정한 방법으로 선거의 자유를 방해할 때"},{"k":"ho","x":"8. 정당한 사유 없이 게시물의 작성ㆍ게시 또는 설치를 방해하거나 이를 훼손ㆍ철거할 때"},{"k":"ho","x":"9. 특정 후보자에게 유리하도록 후보자, 선거운동본부에 관하여 허위의 사실을 공표할 때"},{"k":"ho","x":"10. 특정 후보자에게 불리하도록 다른 후보자, 다른 선거운동본부에 관하여 허위의 사실을 공표할 때"},{"k":"ho","x":"11. 당선되게 하거나 되지 못하게 할 목적으로 다른 후보자, 다른 선거운동본부에 관하여 공연히 사실을 적시하여 다른 후보자, 다른 선거운동본부를 비방하는 행위를 할 때"},{"k":"ho","x":"12. 그 외 선거운동본부의 행위가 공정한 선거 진행을 의도적으로 해치거나, 중대한 영향을 주는 것이 분명하여 선거관리위원회에서 판단하기에 경고에 해당할 때"},{"k":"hang","x":"② 경고를 받은 선거운동본부는 선거관리위원회의 경고 공고 게시 12시간 이내에 이에 대한 공개 사과문을 선거관리위원회가 지정한 온.오프라인 게시판, 해당 선거운동본부 인터넷 선거운동 공간에 게시할 수 있다."}],"num":49,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a50","label":"제50조","title":"징계의 의결ㆍ취소","paras":[{"k":"hang","x":"① 징계는 선거관리위원회 재적 과반수 출석과 출석 과반수 찬성으로 의결한다."},{"k":"hang","x":"② 경고를 받거나, 주의 2회를 받아 경고로 전환될 때에 해당 선거운동본부는 선거관리위원회에 경고 혹은 경고로 전환되는 징계에 대한 재심의를 요구할 수 있다. 재심의 요구가 있으면 선거관리위원장은 지체없이 회의를 소집하여 이를 심의한다."},{"k":"hang","x":"③ 징계 재심의는 징계의 유지 또는 하향 조절을 결정하며, 선거관리위원회 재적 과반수 출석과 출석 과반수 찬성으로 의결한다."},{"k":"hang","x":"④ 징계 취소는 선거관리위원회 재적 과반수 출석과 출석 과반수 찬성으로 의결한다."}],"num":50,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제6절 투표"},{"t":"art","id":"a51","label":"제51조","title":"투표방법","paras":[{"k":"line","x":"학생회장단 선거의 투표는 기표방법으로 함을 원칙으로 한다. 단, 선거관리위원회의 결정으로 선거권자의 편의와 특수한 사정을 고려하여 전자투표 등의 방법을 사용할 수 있다."}],"num":51,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a52","label":"제52조","title":"선거인명부의 열람","paras":[{"k":"line","x":"투표가 진행되고 있을 때에는 투표소에 있는 선거관리위원을 제외한 어느 누구도 선거인명부를 열람할 수 없다."}],"num":52,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a53","label":"제53조","title":"투표관리","paras":[{"k":"line","x":"선거관리위원들은 특정 지역에 설치되는 투표구의 투표 업무를 관리ㆍ감독한다."}],"num":53,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a54","label":"제54조","title":"투표소","paras":[{"k":"hang","x":"① 투표소는 선거관리위원회가 편성하여 의결한다."},{"k":"hang","x":"② 투표소 1개 당 투표함 1개를 비치한다."},{"k":"hang","x":"③ 선거관리위원회는 투표소의 명칭과 소재지를 공고해야 한다."},{"k":"hang","x":"④ 투표소에는 기표소ㆍ투표함ㆍ투표참관인의 좌석 그 밖의 투표관리에 필요한 시설을 설비하여야 한다."},{"k":"hang","x":"⑤ 기표소는 그 안을 다른 사람이 엿볼 수 없도록 설비하여야 하며 선거의 공정성을 해치는 어떠한 표지도 하여서는 아니 된다."},{"k":"hang","x":"⑥ 각 선거운동본부의 본부장 및 해당 투표소에 파견된 투표참관인은 투표소의 설비에 대하여 그 시정을 요구할 수 있다."}],"num":54,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a55","label":"제55조","title":"투표일ㆍ투표시간","paras":[{"k":"hang","x":"① 투표는 3일간 진행한다."},{"k":"hang","x":"② 투표는 10시 00분부터 시작하여 19시 00분에 종료한다. 단, 마감할 때 투표하기 위해 대기하고 있는 투표인에게는 투표를 할 수 있도록 한다."},{"k":"hang","x":"③ 선거관리위원은 투표가 시작되기 10분 전까지 해당 투표소의 투표함 및 기표소 내외의 이상 유무 검사를 완료해야 한다."}],"num":55,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a56","label":"제56조","title":"투표용지ㆍ투표함","paras":[{"k":"hang","x":"① 투표용지와 투표함은 선거관리위원회에서 제공한다."},{"k":"hang","x":"② 투표용지에는 학생회장단 후보 성명, 소속 학과ㆍ반, 학번, 선거운동본부명을 표시하여야 한다."},{"k":"hang","x":"③ 후보 등록 시 제출한 추천서의 추천인 수가 많은 순서로 후보자의 게재 순서를 정한다."},{"k":"hang","x":"④ 해당 선거에 출마한 후보가 두 조 이상일 경우 투표용지에는 후보자란과 동일한 크기의 “지지선본 없음”란을 두어야 한다."},{"k":"hang","x":"⑤ 해당 선거에 출마한 후보가 한 조일 경우 투표용지에는 “찬성”, “반대”, “기권” 란을 두어야 한다."},{"k":"hang","x":"⑥ 투표용지에는 선거관리위원의 확인란, 투표소별 투표참관인의 확인란이 있어야 한다."},{"k":"hang","x":"⑦ 선거관리위원의 서명이 없는 투표용지는 어떠한 경우에도 무효가 된다."},{"k":"hang","x":"⑧ 기표한 것이 전사되어 어느 후보자에게 투표한 것인지 알 수 없게 될 때를 방지하기 위하여 선거인이 전사되지 않는 방향으로 접을 수 있도록 투표용지 중간에 점선을 표시하여야 한다."},{"k":"hang","x":"⑨ 두 후보자란의 구분선상에 기표되어 어느 후보자에게 기표한 것인지를 확정할 수 없을 때를 방지하기 위하여 각 후보자란 사이의 간격을 기표용구의 지름보다 크게 해야 한다."},{"k":"hang","x":"⑩ 투표함은 자물쇠로 봉인할 수 있도록 제작되어야 한다."},{"k":"hang","x":"⑪ 투표함의 열쇠는 선거관리위원장이 보관한다."}],"num":56,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a57","label":"제57조","title":"투표용지 수령","paras":[{"k":"hang","x":"① 투표인은 본인이 투표소에 가서 선거관리위원에게 본인의 학생증, 신분증, 여권 등과 함께 본인의 학적을 선거관리위원회에서 정한 방법으로 확인한 후 투표용지 1장을 받는다."},{"k":"hang","x":"② 선거관리위원은 투표용지를 교부함과 동시에 선거인명부에 투표인을 표시해야 한다."},{"k":"hang","x":"③ 선거관리위원과 투표참관인은 투표용지를 교부할 때마다 이상 유무를 확인하고, 각자의 서명을 해야 한다."}],"num":57,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a58","label":"제58조","title":"기표절차","paras":[{"k":"hang","x":"① 투표인은 투표용지를 받은 후 기표소로 들어가 준비된 기표도구로 본인의 의사를 밝히는 기표를 한 뒤 반드시 그 자리에서 안의 내용이 보이지 않게 투표용지를 접어 선거관리위원과 투표참관인이 지켜보는 가운데 투표함에 집어넣어야 한다."},{"k":"hang","x":"② 기표행위의 실수 시, 투표용지를 재교부하지 않는다."},{"k":"hang","x":"③ 동일기표소에 2인 이상이 들어갈 수 없다. 단, 시각 또는 신체의 장애로 인하여 본인이 기표할 수 없는 투표인은 본인이 지명한 2인을 동반하여 투표를 보조하게 할 수 있다."}],"num":58,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a59","label":"제59조","title":"투표소에서의 선거관리위원 업무","paras":[{"k":"hang","x":"① 선거관리위원은 투표소에 관련된 모든 업무를 관리ㆍ감독한다."},{"k":"hang","x":"② 투표소를 관리하는 선거관리위원은 해당 투표소를 떠날 수 없다. 단, 불가피한 경우에는 다른 선거관리위원으로 대체하고 이 사실을 선거관리위원장에게 보고한다."}],"num":59,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a60","label":"제60조","title":"투표참관인","paras":[{"k":"hang","x":"① 투표참관인은 각 선거운동본부가 투표 진행을 감독하기 위해 각 투표소에 배치한 자를 말한다."},{"k":"hang","x":"② 각 선거운동본부는 투표참관인을 투표일 전까지 선거관리위원회에 등록하여야 한다."},{"k":"hang","x":"③ 각 선거운동본부의 투표참관인은 투표소에 1인씩 배치하며, 교체 가능하다."},{"k":"hang","x":"④ 투표참관인은 정당한 이유 없이 참관을 거부하거나, 사임할 수 없다."},{"k":"hang","x":"⑤ 투표참관인은 투표소 질서 유지에 협조해야 한다."},{"k":"hang","x":"⑥ 투표참관인은 투표의 공정성에 영향을 주는 행위를 해서는 안 된다."},{"k":"hang","x":"⑦ 투표참관인은 선거관리위원회에 투표 진행 상황에 대한 이의제기를 할 수 있다."},{"k":"hang","x":"⑧ 투표참관인은 투표함 및 기표소 내외의 이상 유무를 선거관리위원과 함께 검사해야 하며, 문제가 있 을 시 이의제기를 할 수 있다. 여기에 불참할 경우 검사를 포기한 것으로 간주하고, 당일 투표소 설치에 관한 어떠한 이의제기도 할 수 없다."},{"k":"hang","x":"⑨ 투표참관인이 지각했을 경우 지각한 시간만큼의 참관을 포기한 것으로 간주하고 투표를 진행한다. 지각한 투표참관인은 자신의 도착 이전에 이루어진 투표에 대해 이의를 제기할 수 없다."}],"num":60,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a61","label":"제61조","title":"투표의 중단","paras":[{"k":"hang","x":"① 다음 각호의 경우 중 하나에 해당할 경우 해당 투표소의 투표를 중단시킨다."},{"k":"ho","x":"1. 투표소에 선거관리위원이 없을 때"},{"k":"ho","x":"2. 투표소 내에서 투표참관인의 이의제기로 인해 합의가 필요할 때"},{"k":"ho","x":"3. 투표소의 질서가 혼잡하여 공정한 투표를 진행할 수 없다고 판단될 때"},{"k":"hang","x":"② 제1항에 명시한 상황이 종료되었을 경우 바로 투표를 재개한다."}],"num":61,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a62","label":"제62조","title":"투표소 주의사항","paras":[{"k":"hang","x":"① 투표소 부근에서 선거관리위원, 투표참관인, 투표인을 제외한 사람이 선거에 영향을 미칠 목적으로 접근한다고 판단될 때 선거관리위원은 이들의 접근을 제한할 수 있다."},{"k":"hang","x":"② 투표소로부터 10m 이내에서 투표참관인을 포함한 모든 자는 선거에 영향을 미치는 표식을 지녀서는 안 된다."},{"k":"hang","x":"③ 투표소로부터 10m 이내에서 소란한 언동을 하는 자가 있을 시에는 선거관리위원이 제재한다."},{"k":"hang","x":"④ 투표소로부터 10m 이내에는 선거관리위원회 제작 선전벽보 외의 어떠한 선전물도 있어서는 안 된 다."}],"num":62,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a63","label":"제63조","title":"투표의 비밀보장","paras":[{"k":"hang","x":"① 투표의 비밀은 어떠한 경우에도 보장되어야 한다."},{"k":"hang","x":"② 투표인은 투표한 후보자의 성명이나 선거운동본부명을 누구에게도 또한 어떠한 때도 진술할 의무가 없으며, 누구든지 투표 마감 시각까지 진술을 강요할 수 없다."},{"k":"hang","x":"③ 투표인은 자신이 기표한 투표지를 공개할 수 없으며, 공개된 투표지는 무효로 한다."}],"num":63,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a64","label":"제64조","title":"투표 시작 전 투표함 이송","paras":[{"k":"hang","x":"① 각 투표함은 매 투표일 9시 30분에 선거관리위원과 각 선거운동본부장 또는 해당 선본의 정후보 또는 부후보의 입회 하에 선거관리위원회실에서 투표함의 투입구와 그 자물쇠를 봉쇄하여야 한다."},{"k":"hang","x":"② 자물쇠를 봉쇄한 투표함 및 투표용지, 선거인 명부, 참관시간기록표 등 투표에 필요한 제반 물품은 투표관리요원 및 선거운동본부에서 파견한 한 명이 각 투표소로 이송한다."}],"num":64,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a65","label":"제65조","title":"투표 종료 시 투표함 이송","paras":[{"k":"hang","x":"① 매 투표일 투표가 종료된 후 선거관리위원은 투표참관인의 참관 하에 투표함의 투입구와 그 자물쇠 를 봉쇄 후 날인하여야 한다."},{"k":"hang","x":"② 선거관리위원은 투표함의 이송 전에 해당 투표소의 투표참관인에게 투표함에 이상이 없음을 서면으로 확인받는다."},{"k":"hang","x":"③ 자물쇠를 이용해 봉해진 투표함 및 남은 투표용지, 선거인 명부, 참관시간기록표 등 투표에 필요한 제반 물품은 선거관리위원과 선거운동본부의 투표참관인이 선거관리위원회실로 이송한다."}],"num":65,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a66","label":"제66조","title":"투표함 확인","paras":[{"k":"line","x":"선거관리위원장은 투표함, 남은 투표용지, 선거인 명부 등을 인수하여 지체 없이 이상 여부를 확인한다."}],"num":66,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a67","label":"제67조","title":"투표함 보관","paras":[{"k":"line","x":"각 투표소의 투표함은 매 투표일 투표가 종료된 후 선거관리위원회가 지정한 선거관리위원회실에 보관 한다."}],"num":67,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제7절 투표성립"},{"t":"art","id":"a68","label":"제68조","title":"투표 성립 요건","paras":[{"k":"line","x":"학생회장단 선거는 3일간의 투표 기간이 지나고 명부상 투표율이 25% 이상일 경우 성립한다."}],"num":68,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제8절 개표"},{"t":"art","id":"a69","label":"제69조","title":"개표 공고","paras":[{"k":"line","x":"선거관리위원회는 투표개시일 전까지 개표 장소와 개표 시간을 공고해야 한다."}],"num":69,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a70","label":"제70조","title":"개표관리","paras":[{"k":"hang","x":"① 개표는 선거관리위원회가 담당한다."},{"k":"hang","x":"② 개표는 선거관리위원장과 선거관리위원의 과반수 이상의 출석과 승인 하에 진행할 수 있다."},{"k":"hang","x":"③ 선거관리위원회는 개표 전까지 투표함을 개표소로 옮기고, 개표에 필요한 모든 준비를 마쳐야 한다."},{"k":"hang","x":"④ 각 선거운동본부의 학생회장단 후보 및 선거운동본부장은 개표가 종료될 때까지 개표 장소에 있어야 한다."},{"k":"hang","x":"⑤ 각 선거운동본부는 개표참관인 2인을 선정하여 개표현장을 참관하도록 한다."},{"k":"hang","x":"⑥ 개표참관인은 선거관리위원회에 개표 진행상황에 대한 이의제기를 할 수 있다."}],"num":70,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a71","label":"제71조","title":"개표소","paras":[{"k":"hang","x":"① 개표소는 선거관리위원들이 개표를 하는 장소를 말하며, 개표장 내에서 방청객과 일정한 거리를 유지하는 위치에 설치하여야 한다."},{"k":"hang","x":"② 개표소에는 선거관리위원과 각 선거운동본부가 파견한 개표참관인만이 출입할 수 있다."}],"num":71,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a72","label":"제72조","title":"개표참관인","paras":[{"k":"hang","x":"① 각 선거운동본부는 개표개시일 전까지 개표참관인 2명을 선정하여 선거관리위원회에 통보하여야 한다."},{"k":"hang","x":"② 개표참관인은 개표 상황을 참관하고, 득표를 검산하는 등의 역할을 수행한다."},{"k":"hang","x":"③ 개표참관인의 교체는 선거관리위원장의 허가가 있어야 할 수 있다."}],"num":72,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a73","label":"제73조","title":"개표 시작 전 투표함 이송","paras":[{"k":"line","x":"각 투표함은 투입구와 그 자물쇠가 봉쇄된 채로 선거관리위원이 개표소로 이송한다."}],"num":73,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a74","label":"제74조","title":"개표개시","paras":[{"k":"hang","x":"① 개표는 투표함이 모두 도착한 후 개표준비가 완료되었다고 판단되는 즉시 시행한다."},{"k":"hang","x":"② 개표참관인은 투표함이 도착한 때에 그 봉인 등을 확인하고 관리상황을 참관한다."},{"k":"hang","x":"③ 투표함 하나의 개표가 끝나기 전에 다른 투표함을 열어서는 안 된다."},{"k":"hang","x":"④ 선거관리위원장은 개표소의 질서가 지나치게 혼잡하여 공정한 개표가 진행될 수 없다고 판단될 때에는 질서가 회복될 때까지 개표를 중단하고, 해당인의 퇴장을 명할 수 있다."}],"num":74,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a75","label":"제75조","title":"개표절차","paras":[{"k":"line","x":"개표절차는 다음 각호의 순서에 의한다."},{"k":"ho","x":"1. 총 투표자 수 공고"},{"k":"ho","x":"2. 투표함 개봉"},{"k":"ho","x":"3. 개표"},{"k":"ho","x":"4. 개표참관인의 재확인 및 득표의 검산"},{"k":"ho","x":"5. 득표를 후보 별로 분하여 투표함에 재투입"},{"k":"ho","x":"6. 현황판에 기재"},{"k":"ho","x":"7. 제2호부터 제6호까지의 과정을 투표소별로 반복"},{"k":"ho","x":"8. 현황판에 기재된 상황과 선거인 명부상 투표자 수를 비교하여 오차율 계산"},{"k":"ho","x":"9. 최종 결과 발표"}],"num":75,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a76","label":"제76조","title":"투표용지의 무효처리","paras":[{"k":"hang","x":"① 다음 각호의 어느 하나에 해당하는 투표용지는 무효로 한다."},{"k":"ho","x":"1. 어느 란에도 기표를 하지 아니한 것"},{"k":"ho","x":"2. 두 개 이상의 란에 기표한 것"},{"k":"ho","x":"3. 어느 란에 기표를 한 것인지 식별할 수 없는 것"},{"k":"ho","x":"4. 정해진 기표용구를 사용해 기표하지 않은 것"},{"k":"ho","x":"5. 투표용지에 선거관리위원의 서명ㆍ날인이 없는 것"},{"k":"hang","x":"② 다음 각호의 어느 하나에 해당하는 투표는 무효로 하지 아니한다."},{"k":"ho","x":"1. 기표한 것의 일부분 표시되거나 기표한 것 내부가 메워진 것으로 정해진 기표용구를 사용하여 기표를 한 것이 명확한 것"},{"k":"ho","x":"2. 후보자란 외에 추가 기표되었으나 추가 기표된 것이 어느 후보자에게도 기표한 것으로 볼 수 없 는 것"},{"k":"ho","x":"3. 두 후보자란의 구분선상에 기표된 것으로서 어느 후보자에게 기표한 것인지가 명확한 것"},{"k":"ho","x":"4. 기표한 것이 전사된 것으로서 어느 후보자에게 기표한 것인지가 명확한 것"},{"k":"ho","x":"5. 훼손되었으나 정규의 투표용지임이 명백하고 어느 후보자에게 기표한 것인지가 명확한 것"},{"k":"hang","x":"③ 정해진 투표용지를 사용하지 아니한 것은 투표용지로 보지 아니하고, 따라서 무효표로도 보지 아니 한다."}],"num":76,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a77","label":"제77조","title":"투표함의 무효처리","paras":[{"k":"hang","x":"① 한 투표소의 명부상 투표자 수와 투표함의 투표용지 수의 차이(이하 “오차”라 한다)가 명부상 투표자 수 대비 3%를 넘을 때 해당 투표함의 결과는 무효가 되며, 해당 투표용지 수만큼 무효표로 산입한다. 단, 명부상 투표자 수가 100 이하일 때는 오차는 3까지 허용한다."},{"k":"hang","x":"② 모든 투표소의 명부상 투표자 수 총합과 모든 투표함의 투표용지 수 총합의 차이(이하 “총오차”라 한다)가 명부상 총 투표자 수 대비 3%를 넘을 때 투표는 무효가 된다."}],"num":77,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a78","label":"제78조","title":"투표의 효력에 관한 이의에 대한 결정","paras":[{"k":"hang","x":"① 투표의 효력에 관하여 이의가 있는 때에는 선거관리위원회의 재적 위원 과반수의 출석과 출석 위원 과반수의 의결로 인용·기각을 결정한다."},{"k":"hang","x":"② 투표의 효력을 결정함에 있어서는 선거인의 의사가 존중되어야 한다."}],"num":78,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a79","label":"제79조","title":"투표용지ㆍ선거인명부 등의 보관","paras":[{"k":"line","x":"선거관리위원회는 투표용지ㆍ선거인명부 등을 당선 공고 후 48시간 동안 보관하여야 한다."}],"num":79,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제9절 당선"},{"t":"art","id":"a80","label":"제80조","title":"당선의 기준","paras":[{"k":"hang","x":"① 해당 선거에 출마한 후보가 두 조 이상일 경우 개표 결과 최다 득표한 후보를 당선 후보로 한다."},{"k":"hang","x":"② 해당 선거에 출마한 후보가 한 조일 경우 “찬성”표의 수가 “반대”와 “기권”표의 수의 합보다 많을 경우 그 후보를 당선으로 본다."},{"k":"hang","x":"③ 개표 결과가 본 세칙 제82조·제83조에 해당할 때는 당선을 확정할 수 없다."}],"num":80,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a81","label":"제81조","title":"당선공고","paras":[{"k":"hang","x":"① 개표 결과가 최종 확인되면 선거관리위원장은 이를 지체 없이 공고하고, 공고한 때로부터 48시간 동안 이의신청을 받는다."},{"k":"hang","x":"② 결과에 관한 이의신청이 있는 때에는 선거관리위원장은 지체 없이 회의를 소집하여 이를 심사한다. 이의신청의 인용ㆍ기각에 관하여서는 재적 위원 과반수의 출석과 출석 위원 과반수의 의결로 결정한다."},{"k":"hang","x":"③ 개표 결과의 최종 공고로부터 48시간 이내에 이의신청이 없으면 선거관리위원회는 당선자의 당선확정을 공고한다. 공고에는 다음 각호가 포함되어야 한다."},{"k":"ho","x":"1. 학생회장단 당선자의 이름, 소속 학과ㆍ반, 학번"},{"k":"ho","x":"2. 학생회장단 당선자의 선거운동본부명"},{"k":"ho","x":"3. 최종 투표율"},{"k":"ho","x":"4. 투표 결과(각 선거운동본부의 투표소별 득표수, 총 득표수, 득표율을 포함한다)"}],"num":81,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제10절 확정 및 기타"},{"t":"art","id":"a82","label":"제82조","title":"재투표ㆍ결선투표","paras":[{"k":"hang","x":"① 총오차율이 명부상 총 투표자 수 대비 3%를 넘을 때는 후보 자격이 있는 모든 후보를 후보로 하여 재투표를 시행한다."},{"k":"hang","x":"② 최고 득표조가 두 조 이상인 때는 최고 득표를 기록한 모든 조를 후보로 하여 결선투표를 시행한다."},{"k":"hang","x":"③ 1위 득표 조와의 득표 차이가 총오차보다 적은 조가 있을 때는 1위 득표 조와 해당 조들을 후보로 하여 결선투표를 시행한다."},{"k":"hang","x":"④ 재투표ㆍ결선투표는 개표 종료 후 7일 안에 3일 동안에 걸쳐 선거운동 없이 시행하며, 투표율에 상관없이 득표수가 많은 후보를 당선으로 한다."}],"num":82,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a83","label":"제83조","title":"재선거","paras":[{"k":"line","x":"다음 각호 중 하나의 경우에 해당할 경우 재선거를 실시한다."},{"k":"ho","x":"1. 재투표에서도 총오차가 명부상 총 투표자 수 대비 3%를 넘을 때"},{"k":"ho","x":"2. “지지선본 없음”란에 기표한 사람의 수가 1위 득표 조보다 많을 때"},{"k":"ho","x":"3. “반대”와 “기권”란에 기표한 사람의 수의 합이 “찬성”란에 기표한 사람의 수보다 많을 때"},{"k":"ho","x":"4. 후보가 한 조일 경우 그 득표수가 선거권자 총수의 10% 이상이 아닐 때"}],"num":83,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a84","label":"제84조","title":"투표기간 연기 및 연장","paras":[{"k":"hang","x":"① 해당 선거에 출마한 후보가 한 조일 때 투표율 미달, 천재지변이나 이에 준하는 사태로 투표를 진행 할 수 없을 경우 선거관리위원회는 선거관리위원회 회의를 통해 투표를 연기 혹은 연장할 수 있다. 단, 투표연장의 경우 최대 2일까지 연장할 수 있다."},{"k":"hang","x":"② 해당 선거에 출마한 후보가 두 조 이상일 때 천재지변이나 이에 준하는 사태로 투표를 진행할 수 없을 경우 선거관리위원회는 선거관리위원회 회의를 통해 투표를 연기할 수 있다."}],"num":84,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a85","label":"제85조","title":"선거 무효","paras":[{"k":"line","x":"다음 각호 중 하나의 경우에 해당할 경우 해당 선거는 무효처리가 되고, 비상대책위원회를 구성한다."},{"k":"ho","x":"1. 해당 선거에서 투표율이 미달될 경우"},{"k":"ho","x":"2. 선거시행세칙 제13조에 의해 선거관리위원회가 해체되었을 경우"}],"num":85,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제5장 선거 기록물 관리"},{"t":"art","id":"a86","label":"제86조","title":"선거 기록물 관리","paras":[{"k":"line","x":"선거에서 생산된 기록물 중 보존의 가치가 있는 것은 선거 일정이 모두 종료된 후 선거관리위원장이 기록물 관리기관으로 이관하고, 기록물 관리기관은 최대한 협조한다."}],"num":86,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"부칙","bu":true,"id":"bu1"},{"t":"free","paras":[{"k":"line","x":"이 세칙은 공포 후 2021년 11월 29일부터 시행한다."}]}],"note":null},{"id":"seongeo-20230211","date":"2023.02.11","kind":"일부개정","title":"자유전공학부 학부·반 선거시행세칙","subtitle":"[고려대학교 자유전공학부 학생회 세칙 제1호]","history":[["2017. 5. 27.","제정"],["2017. 8. 19.","전부개정"],["2021. 11. 13.","전부개정"],["2023. 02. 11.","일부개정"]],"pdf":"pdf/seongeo-20230211.pdf","pdfName":"자유전공학부_학부·반_선거시행세칙(2023.02.11_일부개정).pdf","blocks":[{"t":"h","lv":2,"text":"제1장 총칙"},{"t":"art","id":"a1","label":"제1조","title":"목적","paras":[{"k":"line","x":"자유전공학부 학부·반 선거시행세칙은 자유전공학부 학부·반 학생회장단 선거에 관한 세부적인 사항을 규정하여 선거가 민주적인 절차에 의하여 공정하게 치러질 수 있도록 함을 목적으로 한다."}],"num":1,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a2","label":"제2조","title":"기본원칙","paras":[{"k":"line","x":"학부·반 학생회장단 선거는 보통ㆍ평등ㆍ직접ㆍ비밀선거를 원칙으로 한다."}],"num":2,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a3","label":"제3조","title":"적용범위","paras":[{"k":"line","x":"이 세칙은 자유전공학부 학부ㆍ반 학생회장단 선거에 적용한다. 단, 반 학생회장단 선거의 경우 동시선거일 때만 본 세칙을 적용한다."}],"num":3,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제2장 선거권과 피선거권"},{"t":"art","id":"a4","label":"제4조","title":"선거권","paras":[{"k":"hang","x":"① 본회 정회원은 학부 학생회장단 선거의 선거권이 있다."},{"k":"hang","x":"② 반 학생회장단 선거의 선거권은 각호를 따른다."},{"k":"ho","x":"1. A반 소속 자유전공학부 학생회 정회원은 A반 학생회장단 선거의 선거권이 있다."},{"k":"ho","x":"2. B반 소속 자유전공학부 학생회 정회원은 B반 학생회장단 선거의 선거권이 있다."},{"k":"ho","x":"3. C반 소속 자유전공학부 학생회 정회원은 C반 학생회장단 선거의 선거권이 있다."},{"k":"ho","x":"4. D반 소속 자유전공학부 학생회 정회원은 D반 학생회장단 선거의 선거권이 있다."},{"k":"hang","x":"③ 선거인 명부는 자유전공학부 행정실을 통해 확인한 재학생 명단, 휴학생 명단을 참고하여 선거관리위원회에서 확정한다."}],"num":4,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a5","label":"제5조","title":"피선거권","paras":[{"k":"hang","x":"① 본회의 정회원인 자는 학부 학생회장단 선거의 피선거권이 있다."},{"k":"hang","x":"② 학부 학생회장단 선거에 출마하려는 후보는 3학기 이상 등록자이어야 한다."},{"k":"hang","x":"③ 다음 각호의 조건을 모두 만족한 자는 반 학생회장단의 피선거권이 있다."},{"k":"ho","x":"1. 선거일 현재 2학기 이상 등록한 자"},{"k":"ho","x":"2. 「자유전공학부 학생회칙」과 이 세칙에 반하는 활동 목적을 갖지 아니한 자"},{"k":"hang","x":"④ 다음 각호에 해당하는 자가 학생회장단 선거에 출마하려는 경우 후보 등록 마감 전까지 해당 직책을 사퇴해야 한다. 단, 현직에 있는 자가 재임을 위해 해당 선거에 출마하려는 경우에는 해당하지 않는다."},{"k":"ho","x":"1. 학부운영위원의 자격을 갖고 있거나 「자유전공학부 학생회칙」 제63조 제4항에 의해 의결권을 가질 수 있는 자"},{"k":"ho","x":"2. 학부 학생회 집행위원으로 활동하고 있는 자"},{"k":"ho","x":"3. 각 반 고학번 대표 및 신입생 대표"},{"k":"ho","x":"4. 각 자치단체장 또는 이에 준하는 자"},{"k":"ho","x":"5. 각 독립기구장 또는 이에 준하는 자"},{"k":"hang","x":"⑤ 징계로서 선거권과 피선거권을 박탈당한 자는 선거의 선거권과 피선거권이 없다."}],"num":5,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제3장 기관"},{"t":"h","lv":3,"text":"제1절 선거관리위원회"},{"t":"art","id":"a6","label":"제6조","title":"목적","paras":[{"k":"line","x":"선거관리위원회는 학생회장단 선거가 민주적인 절차에 의하여 공정하게 치러질 수 있도록 하기 위하여 설립된 기구이다."}],"num":6,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a7","label":"제7조","title":"의무","paras":[{"k":"hang","x":"① 선거관리위원회는 「자유전공학부 학생회칙」 과 세칙을 성실히 준수함으로써 선거 관리에 공정을 기하여야 한다."},{"k":"hang","x":"② 선거관리위원회는 본회 회원의 주권의식을 높이기 위해 올바른 투표방법을 적극적으로 알리고, 불특정 다수에 대한 투표 독려를 해야 한다."}],"num":7,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a8","label":"제8조","title":"업무","paras":[{"k":"line","x":"선거관리위원회는 다음 각호의 사무를 행한다."},{"k":"ho","x":"1. 학생회장단 선거 업무의 기획 및 집행"},{"k":"ho","x":"2. 학생회장단 선거에 대한 홍보"},{"k":"ho","x":"3. 학생회장단 선거의 민주성ㆍ공정성을 높이기 위한 활동"},{"k":"ho","x":"4. 「자유전공학부 학생회칙」과 본 세칙에 따른 각 선거운동본부 감시"},{"k":"ho","x":"5. 「자유전공학부 학생회칙」과 본 세칙을 위반한 선거운동본부에 대한 징계 조치"},{"k":"ho","x":"6. 그 외에 학생회장단 선거 운영에 필요하다고 인정되는 사안"}],"num":8,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a9","label":"제9조","title":"구성","paras":[{"k":"hang","x":"① 선거관리위원회는 최소한 투표 개시일 21일 전에 학부운영위원회의 승인을 받아 구성 되어야 한다."},{"k":"hang","x":"② 선거관리위원회는 학부 학생회장단(재선거·보궐선거에 있어서 비상대책위원장은 포함하지 아니한다)을 제외한 학부운영위원 및 학생회칙 제63조 제4항에 의해 의결권을 가질 수 있는 자 전원을 기본으로 구성하며, 나머지 인원은 공개모집함을 원칙으로 한다. 단, 반 학생회장단 동시선거의 경우 해당 선거를 진행하는 선거관리위원회는 학부운영위원 및 학생회칙 제63조 제4항에 의해 의결권을 가질 수 있는 자 전원을 기본으로 구성하며, 나머지 인원은 공개모집함을 원칙으로 한다."},{"k":"hang","x":"③ 선거관리위원회는 학부운영위원회 회의에서 인준받은 8인 이상 12인 이하의 선거관리위원으로 구성된다. 단, 모집인원이 12인 이상일 경우 선착순으로 함을 원칙으로 한다."},{"k":"hang","x":"④ 선거관리위원의 충원이 필요할 시 선거관리위원을 추가로 공개모집 할 수 있으며 변동사항을 학부운 영위원회에서 인준 받아야 한다."},{"k":"hang","x":"⑤ 후보 등록기간이 시작된 뒤 선거시행세칙 제12조에 의해 선거관리위원의 결손이 생겼을 경우, 선거관리위원회는 선거관리 위원을 충원하지 못한다."},{"k":"hang","x":"⑥ 선거시행세칙 제13조에 의해 선거관리위원회가 해체되었을 경우, 해당 선거는 무효가 되며, 학부운영 위원회는 지체 없이 재선거를 위한 선거관리위원회를 구성해야 한다. 단, 해체된 선거관리위원회의 선거관리위원은 구성원이 될 수 없다."}],"num":9,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a10","label":"제10조","title":"선거관리위원장","paras":[{"k":"hang","x":"① 선거관리위원장은 선거관리위원회에서 민주적으로 선출한다. 선출된 선거관리위원장은 지체 없이 학부운영위원회에서 인준 받아야 한다."},{"k":"hang","x":"② 선거관리위원장은 선거관리위원회를 대표하고, 그 사무를 총괄한다."},{"k":"hang","x":"③ 선거관리위원장은 선거관리위원회 회의의 의장이 된다."},{"k":"hang","x":"④ 선거관리위원장이 사고 시에는 선거관리위원회의 내부적 호선을 통해 다른 선거관리위원 중 한 명이 그 직무를 대신한다. 단, 이를 학부운영위원회에 통보해야 한다."}],"num":10,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a11","label":"제11조","title":"선거관리위원회 회의","paras":[{"k":"hang","x":"① 선거관리위원회는 선거관리와 관련된 모든 문제를 선거관리위원회 회의를 통해 처리한다."},{"k":"hang","x":"② 선거관리위원회 회의는 각호 중 하나에 의해 위원장이 소집한다."},{"k":"ho","x":"1. 선거관리위원장의 소집요구"},{"k":"ho","x":"2. 선거관리위원회 재적 위원 3분의 1 이상의 연서에 따른 소집요구"},{"k":"ho","x":"3. 선거운동본부의 후보자 또는 선거운동본부장의 이의제기에 따른 소집요구"},{"k":"hang","x":"③ 선거관리위원회 회의는 재적 선거관리위원 과반수의 출석으로 개의하고, 출석 선거관리위원 과반수의 찬성으로 의결한다. 이 때 표결은 기명으로 함을 원칙으로 한다. 단, 중요한 안건으로서 위원장 또는 위원이 제기하여 선거관리위원회가 의결하거나 재적 위원 3분의 1 이상의 요구가 있을 때에는 표결을 무기명으로 할 수 있다. 또한 선거관리위원 파면에 관한 안건은 제12조에 따라 의결한다."},{"k":"hang","x":"④ 의장은 안건에 대한 이의의 유무를 물어서 이의가 없다고 인정한 때에는 가결되었음을 선포할 수 있 다. 이의가 있을 때 또는 표결을 무기명으로 할 때에는 반드시 표결하여야 한다."},{"k":"hang","x":"⑤ 선거관리위원회는 원활한 선거관리를 위하여 다음 각호에 해당하는 자의 회의 출석을 요구할 수 있다."},{"k":"ho","x":"1. 후보"},{"k":"ho","x":"2. 각 선거운동본부의 선거운동본부장"},{"k":"ho","x":"3. 선거운동본부에 대한 징계 사유와 관련된 자"}],"num":11,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a12","label":"제12조","title":"선거관리위원의 직권남용","paras":[{"k":"hang","x":"① 선거관리위원장을 포함한 선거관리위원이 본회 선거시행세칙을 지키지 않았을 경우 본회 회원은 이에 대해 선거관리위원회에 이의제기를 할 수 있다. 이의제기가 있는 즉시 선거관리위원장은 선거관리위원회 회의를 소집하여야 하고, 선거관리위원회 회의의 의결에 따라 해당 선거관리위원은 파면될 수 있다."},{"k":"hang","x":"② 선거관리위원의 파면은 재적 선거관리위원 과반수의 출석과 출석 선거관리위원 3분의 2 이상의 찬성으로 의결한다. 이때 이의제기의 대상이 된 선거관리위원은 재적 위원과 출석 위원의 수에서 제외한다."}],"num":12,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a13","label":"제13조","title":"선거관리위원회의 직권남용","paras":[{"k":"line","x":"선거관리위원회가 직권을 남용해 본회 선거시행세칙을 지키지 않았을 경우 본회 회원은 해당 선거관리위원회의 징계를 집행위원회에 청구할 수 있다. 징계의 청구 방법, 징계 절차 등에 대해서는 「고려대학교 자유전공학부 징계 세칙」을 따른다."}],"num":13,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a14","label":"제14조","title":"재정 및 운영","paras":[{"k":"hang","x":"① 선거관리위원회의 선거관리비용은 학생회비에서 사후 전액 지원받는 것을 원칙으로 한다."},{"k":"hang","x":"② 선거관리위원장은 선거관리위원회 구성과 동시에 선거관리비용에 대한 예산안을 작성하여 이를 학부 운영위원회에서 인준받는다."},{"k":"hang","x":"③ 선거관리위원장은 선거가 끝난 후 선거관리비용에 대한 결산을 작성하여 이를 학부운영위원회에서 심의받는다."},{"k":"hang","x":"④ 학부운영위원회는 심의 후 선거관리비용에 대한 금액 지원을 결정한다."}],"num":14,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 선거운동본부"},{"t":"art","id":"a15","label":"제15조","title":"정의","paras":[{"k":"line","x":"선거운동본부는 학생회장단 선거에 등록한 후보의 선거운동을 통해 해당 후보의 당선을 도모하고, 각 현안에 대한 의견표명ㆍ정책개발 등을 통해 선거와 관련된 의사형성에 도움을 주는 회원의 자발적 조직을 말한다."}],"num":15,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a16","label":"제16조","title":"의무","paras":[{"k":"hang","x":"① 선거운동본부는 학생회장단 선거가 민주적이고 공정하게 치러지도록 노력하여야 한다."},{"k":"hang","x":"② 선거운동본부는 학생회장단 선거가 발전적인 정책 선거로 치러지도록 노력하여야 한다."},{"k":"hang","x":"③ 선거운동본부는 학생회장단 선거가 원활하게 진행될 수 있도록 선거관리위원회에 최대한 협조하여야 한다."}],"num":16,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a17","label":"제17조","title":"구성","paras":[{"k":"hang","x":"① 선거운동본부는 학생회장단 선거 후보, 선거운동본부장, 선거운동본부원으로 구성된다."},{"k":"hang","x":"② 선거운동본부장 및 선거운동본부원은 본회의 회원이어야 한다."}],"num":17,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a18","label":"제18조","title":"모집공고","paras":[{"k":"hang","x":"① 선거운동본부는 선거 공고가 있은 후부터 본부원 모집을 위한 공고를 할 수 있다. 단, 공고문에는 다음 각호의 사항을 제외하고는 명시할 수 없다."},{"k":"ho","x":"1. 선거운동본부명"},{"k":"ho","x":"2. 후보의 이름, 소속 학부ㆍ과ㆍ반, 학번"},{"k":"ho","x":"3. 선거운동본부장의 이름, 소속 학부ㆍ과ㆍ반, 학번"},{"k":"ho","x":"4. 후보 및 선거운동본부장의 연락처"},{"k":"ho","x":"5. 500자 내외의 선거운동본부 소개"},{"k":"hang","x":"② 선거운동본부원을 모집하고자 하는 선거운동본부는 제1항의 공고문을 선거관리위원회에 제출하여 허가를 받아야 한다. 선거관리위원회는 선거운동본부원 모집 공고문이 접수되면 지체 없이 선거관리위원회 회의를 열어 공고문을 심의한다."},{"k":"hang","x":"③ 공고문에 결함이 있을 때 선거관리위원회는 공고문의 게시를 허가하지 않을 수 있으며, 해당 선거운동본부는 결함이 있는 부분을 시정하여 공고문을 다시 심의받을 수 있다."}],"num":18,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a19","label":"제19조","title":"선거운동본부장","paras":[{"k":"hang","x":"① 선거운동본부장은 해당 선거운동본부를 대표하고, 선거 과정 전반에서 후보를 보좌하며, 후보를 대신하여 선거관리위원회를 상대로 선거 운영 전반에 대한 의사를 표명할 수 있다."},{"k":"hang","x":"② 선거운동본부장은 해당 선거운동본부의 학생회장단 후보가 임명한다."},{"k":"hang","x":"③ 학생회장단 후보는 선거운동본부장을 교체할 수 있다. 단, 이를 선거관리위원회에 보고하며 선거관리위원회는 선거운동본부장의 교체 신청이 접수되면 지체 없이 이를 심사하여 승인한다."}],"num":19,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a20","label":"제20조","title":"선거운동본부원","paras":[{"k":"hang","x":"① 각 선거운동본부는 선거운동본부원을 선거관리위원회에 등록하여야 한다."},{"k":"hang","x":"② 선거운동본부원 등록은 후보 등록 신청과 함께 등록하며, 그 이후부터는 변동 사항이 있을 경우 이를 선거관리위원회에 보고한다."},{"k":"hang","x":"③ 선거관리위원회에 선거운동본부원으로 등록되지 않은 자는 해당 선거운동본부의 본부원으로 활동할 수 없다."},{"k":"hang","x":"④ 한 선거운동본부의 본부원으로 등록된 상태에서는 다른 선거운동본부의 본부원으로 등록할 수 없다."}],"num":20,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제4장 선거"},{"t":"h","lv":3,"text":"제1절 선거일정"},{"t":"art","id":"a21","label":"제21조","title":"선거일정의 결정","paras":[{"k":"hang","x":"① 본회 학부·반 학생회장단 선거는 11월 중에 시행함을 원칙으로 한다."},{"k":"hang","x":"② 학생회장단 선거일정은 선거 공고, 등록 기간, 선거운동기간, 투표일, 개표일, 당선공고로 구성된다."},{"k":"hang","x":"③ 선거관리위원회는 등록 기간을 5일 이내, 선거운동기간을 5일 이내, 투표일을 3일로 하여 선거일정을 정한다. 등록 기간과 투표일을 정함에 있어서 토요일과 공휴일은 기간에 산입하지 않는 것을 원칙으로 한다."},{"k":"hang","x":"④ 그 외 구체적인 선거일정은 선거관리위원회에서 정한다."}],"num":21,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a22","label":"제22조","title":"선거 공고","paras":[{"k":"line","x":"선거관리위원회는 구성 후 최소한 투표 개시일 14일 전까지 다음 각호를 명시한 선거 공고를 하여야 한다. 단 재투표의 경우, 투표 개시일 7일 전까지 공고한다."},{"k":"ho","x":"1. 선거관리위원회 활동개시의 뜻"},{"k":"ho","x":"2. 선거 일정"},{"k":"ho","x":"3. 후보 등록에 필요한 서류 목록"},{"k":"ho","x":"4. 선거관리위원장 및 선거관리위원 명단"},{"k":"ho","x":"5. 선거관리위원들의 공정한 선거 진행을 위한 서약 내용 및 서명"}],"num":22,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 후보등록"},{"t":"art","id":"a23","label":"제23조","title":"후보등록","paras":[{"k":"hang","x":"① 학부 학생회장단 선거에 등록하려는 자는 다음 각호의 서류를 첨부하여 선거관리위원회에 제출하여야 한다."},{"k":"ho","x":"1. 본 세칙 제5조 제2항의 요건을 충족하는 재학증명서 또는 휴학증명서"},{"k":"ho","x":"2. 선거운동본부장의 재학증명서 또는 휴학증명서"},{"k":"ho","x":"3. 선거운동본부명"},{"k":"ho","x":"4. 출마 소견문"},{"k":"ho","x":"5. 정회원 50인 이상의 추천서명-정회원 50인 이상의 추천서명에 있어서 당해 연도 입학한 학번 10명 이상, 이전 연도 입학한 학번 10명 이상, 그 이전에 입학한 학번 10명 이상의 추천서명을 받는 것을 원칙으로 한다."},{"k":"ho","x":"6. 선거운동본부원 명부"},{"k":"hang","x":"② 반 학생회장단 선거에 등록하려는 자는 다음 각호의 서류를 첨부하여 선거관리위원회에 제출하여야 한다."},{"k":"ho","x":"1. 본 세칙 제5조 제3항 제1호의 요건을 충족하는 재학증명서 또는 휴학증명서"},{"k":"ho","x":"2. 선거운동본부장의 재학증명서 또는 휴학증명서"},{"k":"ho","x":"3. 선거운동본부명"},{"k":"ho","x":"4. 출마 소견문"},{"k":"ho","x":"5. 정회원 15인 이상의 추천서명-정회원 15인 이상의 추천서명에 있어서 당해 연도 입학한 학번 5명 이상, 그 이전에 입학한 학번 5명 이상의 추천서명을 받는 것을 원칙으로 한다."},{"k":"ho","x":"6. 선거운동본부원 명부"},{"k":"hang","x":"③ 후보등록 서류양식 및 제출방식은 선거관리위원회에서 정하며, 선거관리위원회가 정한 서류양식 및 제출방식이 아닌 서류는 모두 무효이다."},{"k":"hang","x":"④ 선거관리위원회는 모든 학생회장단 선거 등록자에게 동일한 서류양식 및 제출방식으로 서류를 제출 받아야 한다."},{"k":"hang","x":"⑤ 추천서명은 추천인의 자필서명을 원칙으로 한다. 단, 선거관리위원회는 추천인의 서명을 추천인 본인 확인이 가능한 전자서명 또는 이에 준하는 수단으로 대체하여 받을 수 있다."}],"num":23,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a24","label":"제24조","title":"후보 등록 심사","paras":[{"k":"hang","x":"① 선거관리위원회는 후보 등록 마감 후 24시간 이내에 선거관리위원회 회의를 열어 후보등록을 위 한 서류들을 검토한다."},{"k":"hang","x":"② 제1항의 회의에는 각 선거운동본부의 후보, 선거운동본부장이 모두 참석하여야 한다."},{"k":"hang","x":"③ 선거관리위원회는 서류 검토 후 특별한 결격사유가 없을 경우 이를 즉시 수리해야 한다. 단, 하자가 있을 시, 즉시 등록 불가 의사와 그 사유를 공고한다."},{"k":"hang","x":"④ 등록이 마무리된 후에는 제출한 서류의 내용을 퇴고하거나 수정할 수 없다."}],"num":24,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a25","label":"제25조","title":"사전 규칙확정회의","paras":[{"k":"hang","x":"① 사전 규칙확정회의는 후보 등록 심사가 완료된 직후 선거운동에 관한 기본적인 사항을 합의하기 위해 각 선거운동본부와 선거관리위원회 간에 이루어지는 회의를 말한다."},{"k":"hang","x":"② 사전 규칙확정회의는 다음 각호의 사항들을 합의 사항으로 한다."},{"k":"ho","x":"1. 개인유세·합동유세의 개최 여부 및 세부적인 운영 방법"},{"k":"ho","x":"2. 후보간담회·공청회의 개최 여부 및 세부적인 운영 방법"},{"k":"ho","x":"3. 인터넷 선거운동 공간의 구성 및 세부적인 운영 방법"},{"k":"ho","x":"4. 선거운동본부 선전물(유인물·소책자 등)의 규격, 수량 및 게시·배포 방법"},{"k":"ho","x":"5. 선거운동본부복의 착용 여부"},{"k":"ho","x":"6. 선거관리위원회 제작 선전벽보의 규격, 수량 및 게시 위치"},{"k":"ho","x":"7. 그 밖의 선거운동에 관련된 기본적인 사항"},{"k":"hang","x":"③ 선거관리위원회는 사전 규칙확정회의 시 징계에 해당하는 행위, 투표참관인 및 개표참관인 등록일정 등 본 세칙에 기반한 원활한 선거 진행을 위해 필요한 사항들을 각 선거운동본부에 고지하여야 한다."}],"num":25,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a26","label":"제26조","title":"복수추천의 허용","paras":[{"k":"line","x":"선거권자는 동일한 선거에서 서로 다른 후보를 동시에 추천할 수 있다. 단, 동일후보에 대한 중복 추천 서명은 인정하지 않는다."}],"num":26,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a27","label":"제27조","title":"후보의 사퇴","paras":[{"k":"line","x":"후보가 사퇴하고자 하는 때에는 본인이 직접 선거관리위원회에 사유서를 제출하여야 한다. 단, 선거운동 기간 후에는 사퇴할 수 없다."}],"num":27,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a28","label":"제28조","title":"후보 등록 등의 공고","paras":[{"k":"hang","x":"① 선거관리위원회는 후보 등록 다음 날까지 다음 각호의 사항을 명시한 입후보자 공고를 해야 한다."},{"k":"ho","x":"1. 후보의 이름, 소속 학과ㆍ반, 학번"},{"k":"ho","x":"2. 선거운동본부명 및 선거운동본부장의 이름, 소속 학과ㆍ반, 학번"},{"k":"hang","x":"② 선거관리위원회는 후보가 사퇴ㆍ사망하거나 후보 자격이 박탈되면 지체 없이 이를 공고한다."}],"num":28,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a29","label":"제29조","title":"후보가 없는 경우","paras":[{"k":"line","x":"후보로 아무도 등록하지 않거나, 등록한 모든 후보의 사퇴 등으로 후보가 없어 해당 선거가 무산된 경우, 「자유전공학부 학생회칙」 또는 각 「반 학생회칙」에 따라 비상대책위원회를 구성한다."}],"num":29,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제3절 선거운동"},{"t":"art","id":"a30","label":"제30조","title":"선거운동","paras":[{"k":"hang","x":"① 선거운동이라 함은 특정 후보의 당선을 위한 제반 행위이다."},{"k":"hang","x":"② 선거운동은 다음 각호의 방법으로 한다."},{"k":"ho","x":"1. 개인유세ㆍ합동유세"},{"k":"ho","x":"2. 선전물의 게시ㆍ배포"},{"k":"ho","x":"3. 간담회ㆍ공청회"},{"k":"ho","x":"4. 인터넷 선거운동 공간의 구성 및 운영"},{"k":"ho","x":"5. 선거운동본부복의 착용"},{"k":"ho","x":"6. 그 밖의 당선을 위한 각종 행위"},{"k":"hang","x":"③ 다음 각호의 행위는 선거운동으로 보지 않는다."},{"k":"ho","x":"1. 선거에 관한 일반적인 의견개진 및 의사표시"},{"k":"ho","x":"2. 후보등록을 위한 준비 행위"},{"k":"ho","x":"3. 회원의 특정 후보자 단순 지지 표명 행위"},{"k":"hang","x":"④ 선거운동은 본회 선거시행세칙에 규정된 것 이외의 방법으로는 할 수 없다."}],"num":30,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a31","label":"제31조","title":"선거운동기간","paras":[{"k":"hang","x":"① 선거운동기간은 후보 등록이 마무리 된 이후부터 투표일 전날 24시 사이에서 선거관리위원회가 결정한다. 단, 부착된 A0규격의 선전물은 본 세칙 제36조 제2항에 해당하지 않는 한 투표 종료일까지 게시 가능하다."},{"k":"hang","x":"② 사전선거운동은 허용하지 않는다. 단, 추천 서명을 받는 행위는 사전선거운동으로 보지 않는다."}],"num":31,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a32","label":"제32조","title":"선거운동을 할 수 없는 자","paras":[{"k":"line","x":"다음 각호에 해당하는 자는 선거운동을 할 수 없다."},{"k":"ho","x":"1. 선거관리위원장 및 선거관리위원"},{"k":"ho","x":"2. 본회의 회원이 아닌 자"},{"k":"ho","x":"3. 본회 회원 중 적법한 절차를 거쳐 선거운동본부원으로 등록하지 않은 자"}],"num":32,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a33","label":"제33조","title":"선거관리위원회 제작 선전벽보","paras":[{"k":"hang","x":"① 선거관리위원회는 후보 등록이 완료된 다음날까지 다음 각호의 사항을 명시한 선거관리위원회 제 작 선전벽보를 게시하여야 한다."},{"k":"ho","x":"1. 후보의 사진, 이름, 소속 학과ㆍ반, 학번"},{"k":"ho","x":"2. 선거운동본부명"},{"k":"ho","x":"3. 핵심 공약"},{"k":"hang","x":"② 선거관리위원회 제작 선전벽보의 규격, 수량과 게시 위치는 선거관리위원회와 각 선거운동본부의 합의로 결정한다."}],"num":33,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a34","label":"제34조","title":"선거운동 일정의 보고의무","paras":[{"k":"hang","x":"① 각 선거운동본부는 선거운동 일정을 선거관리위원회에 보고해야 한다."},{"k":"hang","x":"② 선거관리위원회가 보고받은 사항 중 각 선거운동본부의 일정이 겹치는 부분에 대해서는 선거관리위원회가 공정하게 조정한다."},{"k":"hang","x":"③ 보고되지 않은 선거운동이 진행되는 경우, 선거관리위원회는 선거운동이 더 이상 진행되지 않도록 막을 수 있으며, 그 위반 사실을 지체 없이 공고해야 한다."}],"num":34,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a35","label":"제35조","title":"선전물의 사전허가","paras":[{"k":"hang","x":"① 각 선거운동본부는 선거관련 선전물을 선거관리위원회의 허가를 거친 후 게시ㆍ배포한다."},{"k":"hang","x":"② 선거 관련 선전물에 타 후보에 대한 비방 등 선거의 공정성을 해칠 수 있는 내용이 있으면 선거관리 위원회가 게시ㆍ배포 금지 처분을 할 수 있다."},{"k":"hang","x":"③ 선거관리위원회에 신고하지 않은 선전물을 게시ㆍ배포하면 선거관리위원회는 해당 선거운동본부에 해당 게시물ㆍ유인물의 수거를 명할 수 있다."}],"num":35,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a36","label":"제36조","title":"선전물","paras":[{"k":"hang","x":"① A0규격을 초과하는 선전물은 게시할 수 없다."},{"k":"hang","x":"② 선거운동기간 중에 게시된 선전물은 투표 종료일까지 게시가 가능하다. 단, 투표소로부터 10m 이내 에 게시된 선거운동본부의 선전물은 제거하여야 한다."},{"k":"hang","x":"③ 각 선거운동본부는 선거운동기간 동안 유인물과 표지를 포함한 20쪽 내의 소책자를 배포할 수 있으며, 유인물과 소책자의 규격 및 개수 등의 사항은 선거운동기간 전에 각 선거운동본부와 선거관리위원회의 합의로 결정한다."},{"k":"hang","x":"④ 선거운동본부원이 타 선거운동본부의 선전물을 임의로 제거할 수 없다."},{"k":"hang","x":"⑤ 선거관리위원회는 선거운동본부의 선전물의 게시ㆍ배포를 최대한 보장하여야 한다."}],"num":36,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a37","label":"제37조","title":"개인유세","paras":[{"k":"hang","x":"① 개인유세는 각 선거운동본부의 후보 또는 선거운동본부원들이 선거운동의 일환으로 벌이는 강의실 유세, 선거 물품 배포 등의 모든 종류의 선전활동을 말한다."},{"k":"hang","x":"② 개인유세는 8시부터 20시까지 가능하다."},{"k":"hang","x":"③ 선거관리위원회는 선거의 민주성ㆍ대중성 향상을 위하여 각 선거운동본부의 개인유세를 최대한 보장 하여야 한다."},{"k":"hang","x":"④ 개인유세는 각 선거운동본부가 수시로 개최할 수 있다. 단, 지나친 소음 등으로 학우들의 불편을 초래할 위험이 있거나, 초래한 때는 선거관리위원회가 이를 제한할 수 있다."},{"k":"hang","x":"⑤ 개인유세와 관련된 세부적인 사항들은 선거운동기간 전에 각 선거운동본부와 선거관리위원회의 합의로 결정한다."}],"num":37,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a38","label":"제38조","title":"합동유세","paras":[{"k":"hang","x":"① 두 개 이상의 선거운동본부가 등록한 경우, 선거관리위원회는 합동유세를 개최할 수 있으며, 합동유세의 진행은 선거관리위원장이 담당한다."},{"k":"hang","x":"② 합동유세에서의 유세 순서는 합동유세 전에 추첨하여 정한다."},{"k":"hang","x":"③ 후보자는 유세시간을 준수하여야 한다. 각 선거운동본부 당 유세시간은 선거관리위원회에서 결정하 며, 제한시간을 초과하면 선거관리위원회는 마이크 등 유세시설을 철거하여 유세를 중단시킨다. 단, 유세 자를 교체하기 위해 소요되는 시간은 유세시간에 포함되지 않는다."},{"k":"hang","x":"④ 후보자는 합동유세가 끝날 때까지 합동유세장에서 퇴장할 수 없다. 단, 부득이할 때는 선거관리위원 장의 동의에 따라 10분 이내로 자리를 비울 수 있다."},{"k":"hang","x":"⑤ 후보자는 타 후보자의 유세 시간 중에 유세를 방해하거나 소속 선거운동본부의 선전물을 배포하는 행위를 할 수 없다."},{"k":"hang","x":"⑥ 선거관리위원회는 합동유세장에서 연설을 방해하거나 장내 질서를 어지럽히는 자가 있을 때 퇴장을 명할 수 있다."},{"k":"hang","x":"⑦ 합동유세와 관련된 세부적인 사항들은 선거운동기간 전에 각 선거운동본부와 선거관리위원회의 합의로 결정한다."}],"num":38,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a39","label":"제39조","title":"인터넷에서의 선거운동","paras":[{"k":"hang","x":"① 각 선거운동본부는 인터넷에 홈페이지, 카페, 커뮤니티 등의 인터넷 선거운동 공간을 구성할 수 있다."},{"k":"hang","x":"② 각 선거운동본부의 후보, 선거운동본부장, 선거운동본부원은 선거관리위원회가 허용한 공간 이외의 인터넷 공간에서 논쟁ㆍ답변 등의 의사표현 행위를 할 수 없다."},{"k":"hang","x":"③ 그 밖의 인터넷에서의 선거운동과 관련해서는 선거관리위원회와 선거운동본부의 합의로 결정한다."}],"num":39,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a40","label":"제40조","title":"후보간담회","paras":[{"k":"hang","x":"① 각 선거운동본부는 선거운동기간 중 간담회를 주최할 수 있다."},{"k":"hang","x":"② 후보간담회의 구체적인 운영방법은 선거관리위원회와 선거운동본부의 합의로 결정한다."}],"num":40,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a41","label":"제41조","title":"공청회","paras":[{"k":"hang","x":"① 선거운동본부는 선거관리위원회에 공청회를 요청할 수 있으며, 선거관리위원회는 정당한 사유 없이 선거운동본부의 요청을 거부할 수 없다."},{"k":"hang","x":"② 선거운동본부가 두 개 이상일 경우, 선거관리위원회에서 합동공청회를 진행할 수 있다."},{"k":"hang","x":"③ 공청회는 선거관리위원회 주재 하에 개최된다."},{"k":"hang","x":"④ 공청회의 사회는 선거관리위원 중 한 명이 맡는다."},{"k":"hang","x":"⑤ 공청회의 구체적인 운영방법은 선거관리위원회와 선거운동본부의 합의에 따라 결정한다."}],"num":41,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a42","label":"제42조","title":"선거운동 비용","paras":[{"k":"hang","x":"① 선거운동 비용은 후보가 선거에 입후보한 때부터 당해 선거의 당선인이 결정될 때까지 선거 사무를 처리하기 위해 소모한 금전, 물건, 기타 재산상 가치를 말한다."},{"k":"hang","x":"② 각 선거운동본부의 선거운동 비용은 선거운동 비용의 최대 80%까지 학생회비에서 사후 지원받을 수 있다."},{"k":"hang","x":"③ 각 선거운동본부의 선거운동본부장은 투표를 통해 당선 및 낙선이 확정된 이후, 선거운동 비용에 대한 결산을 작성하여 이를 학부운영위원회에서 심의받는다. 이 때 결격사유가 발견될 경우 학부운영위원회는 학생회비 지원을 하지 않을 수 있다."}],"num":42,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제4절 이의제기"},{"t":"art","id":"a43","label":"제43조","title":"이의제기의 방식","paras":[{"k":"hang","x":"① 본회 회원은 공정한 선거를 위하여 본회의 학생회칙 및 선거시행세칙에 반하는 행위를 선거관리위원회에 고발할 의무를 지닌다."},{"k":"hang","x":"② 선거에 관한 이의제기는 한 선거운동본부 내에서는 각 선거운동본부의 후보와 선거운동본부장만 할 수 있다."},{"k":"hang","x":"③ 각 선거운동본부는 후보 또는 선거운동본부장 명의의 서면으로 이의제기를 하여야 한다."},{"k":"hang","x":"④ 투표와 관련해서는 해당 투표소에 파견된 투표참관인이 후보 또는 선거운동본부장을 대신하여 구두로 이의제기를 할 수 있다. 단, 이때 해당 선거운동본부는 24시간 이내에 해당 이의제기 내용을 서면으로 다시 제출하여야 한다."},{"k":"hang","x":"⑤ 개표와 관련해서는 후보 또는 선거운동본부장이 구두로 이의제기를 할 수 있다. 단, 이 때 해당 선거운동본부는 24시간 이내에 해당 이의제기 내용을 서면으로 다시 제출하여야 한다."},{"k":"hang","x":"⑥ 선거운동본부가 제2항 내지 제5항을 위반하면 선거관리위원회가 해당 선거운동본부에 시정명령을 내릴 수 있다."}],"num":43,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a44","label":"제44조","title":"이의제기의 처리","paras":[{"k":"hang","x":"① 이의제기가 있으면 선거관리위원장은 지체 없이 회의를 소집하여 이를 심의하여 처리한다."},{"k":"hang","x":"② 이의제기의 처리는 선거관리위원회 재적 위원 과반수 출석과 출석 위원 과반수 찬성으로 의결한다."}],"num":44,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제5절 징계"},{"t":"art","id":"a45","label":"제45조","title":"징계","paras":[{"k":"line","x":"징계라 함은 본 세칙에 반하는 행위를 하거나, 선거관리위원회가 징계 사유라고 정한 행위를 할 때 해당 선거운동본부에 제재를 가하는 것을 말한다."}],"num":45,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a46","label":"제46조","title":"징계의 종류","paras":[{"k":"hang","x":"① 징계는 시정명령, 주의, 경고로 나뉜다."},{"k":"hang","x":"② 동일한 내용으로 시정명령이 2회 누적되면 주의 1회를 받은 것으로 한다. 시정명령 2회가 주의 1회로 전환되면, 해당 시정명령 2회는 소멸한다."},{"k":"hang","x":"③ 주의가 2회 누적되면 경고 1회를 받은 것으로 한다. 주의 2회가 경고 1회로 전환되면, 해당 주의 2회는 소멸한다."},{"k":"hang","x":"④ 경고가 3회 누적되면 해당 선거운동본부의 후보 자격을 박탈한다."}],"num":46,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a47","label":"제47조","title":"시정명령","paras":[{"k":"line","x":"다음 각호의 사항에 해당할 때 선거관리위원회는 해당 선거운동본부에 시정명령을 내릴 수 있다."},{"k":"ho","x":"1. 선거운동본부원 모집을 위한 공고문에 결함이 있을 때"},{"k":"ho","x":"2. 선거운동본부원의 등록 절차상의 문제가 있을 때"},{"k":"ho","x":"3. 게시물ㆍ선전물의 사전 허가를 위한 회의 결과 본 세칙에서 규정하고 있는 규격과 맞지 않을 때"},{"k":"ho","x":"4. 투·개표 참관인이 정당한 이유 없이 참관을 거부하거나 태만하는 경우"},{"k":"ho","x":"5. 그 외 선거 진행에 큰 지장을 주지는 않으나, 본 세칙을 위반한 것이 분명하여 선거관리위원회에서 판단하기에 시정명령에 해당할 때"}],"num":47,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a48","label":"제48조","title":"주의","paras":[{"k":"line","x":"다음 각호의 사항에 해당할 때 선거관리위원회는 해당 선거운동본부에 주의를 내릴 수 있다. 주의를 내릴 경우 해당 사실을 온라인 및 오프라인 게시를 통해 공고한다."},{"k":"ho","x":"1. 시정명령을 받은 후에도 해당 선거운동본부가 징계 사유에 해당하는 행위를 2시간 이내에 시정하지 않을 때"},{"k":"ho","x":"2. 동일한 내용으로 시정명령을 두 번 받았을 때"},{"k":"ho","x":"3. 선거관리위원회로부터 허가받지 않은 선거운동본부원의 모집 공고문을 게시할 때"},{"k":"ho","x":"4. 후보 등록 신청 시 제출한 서류ㆍ파일에 결함이 있을 때"},{"k":"ho","x":"5. 선거운동을 할 수 없는 자로 규정된 자가 선거운동을 할 때"},{"k":"ho","x":"6. 본 세칙 및 사전 규칙확정회의에서 정해진 개인유세ㆍ합동유세ㆍ후보간담회ㆍ공청회 등의 합의사항을 준수하지 않을 때"},{"k":"ho","x":"7. 게시물ㆍ유인물의 사전 허가를 위한 회의 결과 타 후보에 대한 비방 등 선거의 공정성을 해칠 수 있는 내용이 있을 때"},{"k":"ho","x":"8. 선거운동본부에 소속된 인원 중 허용되지 않은 자가 온라인 선거운동을 할 때"},{"k":"ho","x":"9. 투·개표 참관인을 허가 없이 교체했을 경우"},{"k":"ho","x":"10. 그 외 선거운동본부의 행위가 공정한 선거 진행을 해치는 것이 분명하여 선거관리위원회에서 판단하기에 주의에 해당할 때"}],"num":48,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a49","label":"제49조","title":"경고","paras":[{"k":"hang","x":"① 다음 각호의 사항에 해당할 때 선거관리위원회는 해당 선거운동본부에 경고를 내릴 수 있다. 경고를 내릴 경우 해당 사실을 온라인 및 오프라인 게시를 통해 공고한다."},{"k":"ho","x":"1. 주의를 받은 후에도 해당 선거운동본부가 징계 사유에 해당하는 행위를 2시간 이내에 시정하지 않을 때"},{"k":"ho","x":"2. 한 선거운동본부에 주의가 2회 누적될 때"},{"k":"ho","x":"3. 사전선거운동을 할 때"},{"k":"ho","x":"4. 사전 허가를 받지 않은 게시물ㆍ유인물을 게시ㆍ배포할 때"},{"k":"ho","x":"5. 특정 후보자의 당락이나 선거인의 자유로운 투표의사에 영향을 미치게 할 목적으로 선거인, 다른후보자, 다른 선거운동본부의 본부장ㆍ및 본부원, 참관인에게 금전ㆍ물품ㆍ향응 그 밖에 재산상의 이익을 제공하거나 그 제공의 의사를 표시하거나 그 제공을 약속할 때"},{"k":"ho","x":"6. 선거에 관하여 다른 후보자, 다른 선거운동본부의 본부장ㆍ본부원을 폭행ㆍ협박하거나 선거운동용 물품을 탈취할 때"},{"k":"ho","x":"7. 선거에 관하여 집회ㆍ연설을 방해하거나 그 밖에 부정한 방법으로 선거의 자유를 방해할 때"},{"k":"ho","x":"8. 정당한 사유 없이 게시물의 작성ㆍ게시 또는 설치를 방해하거나 이를 훼손ㆍ철거할 때"},{"k":"ho","x":"9. 특정 후보자에게 유리하도록 후보자, 선거운동본부에 관하여 허위의 사실을 공표할 때"},{"k":"ho","x":"10. 특정 후보자에게 불리하도록 다른 후보자, 다른 선거운동본부에 관하여 허위의 사실을 공표할 때"},{"k":"ho","x":"11. 당선되게 하거나 되지 못하게 할 목적으로 다른 후보자, 다른 선거운동본부에 관하여 공연히 사실을 적시하여 다른 후보자, 다른 선거운동본부를 비방하는 행위를 할 때"},{"k":"ho","x":"12. 그 외 선거운동본부의 행위가 공정한 선거 진행을 의도적으로 해치거나, 중대한 영향을 주는 것이 분명하여 선거관리위원회에서 판단하기에 경고에 해당할 때"},{"k":"hang","x":"② 경고를 받은 선거운동본부는 선거관리위원회의 경고 공고 게시 12시간 이내에 이에 대한 공개 사과문을 선거관리위원회가 지정한 온.오프라인 게시판, 해당 선거운동본부 인터넷 선거운동 공간에 게시할 수 있다."}],"num":49,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a50","label":"제50조","title":"징계의 의결ㆍ취소","paras":[{"k":"hang","x":"① 징계는 선거관리위원회 재적 과반수 출석과 출석 과반수 찬성으로 의결한다."},{"k":"hang","x":"② 경고를 받거나, 주의 2회를 받아 경고로 전환될 때에 해당 선거운동본부는 선거관리위원회에 경고 혹은 경고로 전환되는 징계에 대한 재심의를 요구할 수 있다. 재심의 요구가 있으면 선거관리위원장은 지체없이 회의를 소집하여 이를 심의한다."},{"k":"hang","x":"③ 징계 재심의는 징계의 유지 또는 하향 조절을 결정하며, 선거관리위원회 재적 과반수 출석과 출석 과반수 찬성으로 의결한다."},{"k":"hang","x":"④ 징계 취소는 선거관리위원회 재적 과반수 출석과 출석 과반수 찬성으로 의결한다."}],"num":50,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제6절 투표"},{"t":"art","id":"a51","label":"제51조","title":"투표방법","paras":[{"k":"line","x":"학생회장단 선거의 투표는 기표방법으로 함을 원칙으로 한다. 단, 선거관리위원회의 결정으로 선거권자의 편의와 특수한 사정을 고려하여 전자투표 등의 방법을 사용할 수 있다."}],"num":51,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a52","label":"제52조","title":"선거인명부의 열람","paras":[{"k":"line","x":"투표가 진행되고 있을 때에는 투표소에 있는 선거관리위원을 제외한 어느 누구도 선거인명부를 열람할 수 없다."}],"num":52,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a53","label":"제53조","title":"투표관리","paras":[{"k":"line","x":"선거관리위원들은 특정 지역에 설치되는 투표구의 투표 업무를 관리ㆍ감독한다."}],"num":53,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a54","label":"제54조","title":"투표소","paras":[{"k":"hang","x":"① 투표소는 선거관리위원회가 편성하여 의결한다."},{"k":"hang","x":"② 투표소 1개 당 투표함 1개를 비치한다."},{"k":"hang","x":"③ 선거관리위원회는 투표소의 명칭과 소재지를 공고해야 한다."},{"k":"hang","x":"④ 투표소에는 기표소ㆍ투표함ㆍ투표참관인의 좌석 그 밖의 투표관리에 필요한 시설을 설비하여야 한다."},{"k":"hang","x":"⑤ 기표소는 그 안을 다른 사람이 엿볼 수 없도록 설비하여야 하며 선거의 공정성을 해치는 어떠한 표지도 하여서는 아니 된다."},{"k":"hang","x":"⑥ 각 선거운동본부의 본부장 및 해당 투표소에 파견된 투표참관인은 투표소의 설비에 대하여 그 시정을 요구할 수 있다."}],"num":54,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a55","label":"제55조","title":"투표일ㆍ투표시간","paras":[{"k":"hang","x":"① 투표는 3일간 진행한다."},{"k":"hang","x":"② 투표는 10시 00분부터 시작하여 19시 00분에 종료한다. 단, 마감할 때 투표하기 위해 대기하고 있는 투표인에게는 투표를 할 수 있도록 한다."},{"k":"hang","x":"③ 선거관리위원은 투표가 시작되기 10분 전까지 해당 투표소의 투표함 및 기표소 내외의 이상 유무 검사를 완료해야 한다."}],"num":55,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a56","label":"제56조","title":"투표용지ㆍ투표함","paras":[{"k":"hang","x":"① 투표용지와 투표함은 선거관리위원회에서 제공한다."},{"k":"hang","x":"② 투표용지에는 학생회장단 후보 성명, 소속 학과ㆍ반, 학번, 선거운동본부명을 표시하여야 한다."},{"k":"hang","x":"③ 후보 등록 시 제출한 추천서의 추천인 수가 많은 순서로 후보자의 게재 순서를 정한다."},{"k":"hang","x":"④ 해당 선거에 출마한 후보가 두 조 이상일 경우 투표용지에는 후보자란과 동일한 크기의 “지지선본 없음”란을 두어야 한다."},{"k":"hang","x":"⑤ 해당 선거에 출마한 후보가 한 조일 경우 투표용지에는 “찬성”, “반대”, “기권” 란을 두어야 한다."},{"k":"hang","x":"⑥ 투표용지에는 선거관리위원의 확인란, 투표소별 투표참관인의 확인란이 있어야 한다."},{"k":"hang","x":"⑦ 선거관리위원의 서명이 없는 투표용지는 어떠한 경우에도 무효가 된다."},{"k":"hang","x":"⑧ 기표한 것이 전사되어 어느 후보자에게 투표한 것인지 알 수 없게 될 때를 방지하기 위하여 선거인이 전사되지 않는 방향으로 접을 수 있도록 투표용지 중간에 점선을 표시하여야 한다."},{"k":"hang","x":"⑨ 두 후보자란의 구분선상에 기표되어 어느 후보자에게 기표한 것인지를 확정할 수 없을 때를 방지하기 위하여 각 후보자란 사이의 간격을 기표용구의 지름보다 크게 해야 한다."},{"k":"hang","x":"⑩ 투표함은 자물쇠로 봉인할 수 있도록 제작되어야 한다."},{"k":"hang","x":"⑪ 투표함의 열쇠는 선거관리위원장이 보관한다."}],"num":56,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a57","label":"제57조","title":"투표용지 수령","paras":[{"k":"hang","x":"① 투표인은 본인이 투표소에 가서 선거관리위원에게 본인의 학생증, 신분증, 여권 등과 함께 본인의 학적을 선거관리위원회에서 정한 방법으로 확인한 후 투표용지 1장을 받는다."},{"k":"hang","x":"② 선거관리위원은 투표용지를 교부함과 동시에 선거인명부에 투표인을 표시해야 한다."},{"k":"hang","x":"③ 선거관리위원과 투표참관인은 투표용지를 교부할 때마다 이상 유무를 확인하고, 각자의 서명을 해야 한다."}],"num":57,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a58","label":"제58조","title":"기표절차","paras":[{"k":"hang","x":"① 투표인은 투표용지를 받은 후 기표소로 들어가 준비된 기표도구로 본인의 의사를 밝히는 기표를 한 뒤 반드시 그 자리에서 안의 내용이 보이지 않게 투표용지를 접어 선거관리위원과 투표참관인이 지켜보는 가운데 투표함에 집어넣어야 한다."},{"k":"hang","x":"② 기표행위의 실수 시, 투표용지를 재교부하지 않는다."},{"k":"hang","x":"③ 동일기표소에 2인 이상이 들어갈 수 없다. 단, 시각 또는 신체의 장애로 인하여 본인이 기표할 수 없는 투표인은 본인이 지명한 2인을 동반하여 투표를 보조하게 할 수 있다."}],"num":58,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a59","label":"제59조","title":"투표소에서의 선거관리위원 업무","paras":[{"k":"hang","x":"① 선거관리위원은 투표소에 관련된 모든 업무를 관리ㆍ감독한다."},{"k":"hang","x":"② 투표소를 관리하는 선거관리위원은 해당 투표소를 떠날 수 없다. 단, 불가피한 경우에는 다른 선거관리위원으로 대체하고 이 사실을 선거관리위원장에게 보고한다."}],"num":59,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a60","label":"제60조","title":"투표참관인","paras":[{"k":"hang","x":"① 투표참관인은 각 선거운동본부가 투표 진행을 감독하기 위해 각 투표소에 배치한 자를 말한다."},{"k":"hang","x":"② 각 선거운동본부는 투표참관인을 투표일 전까지 선거관리위원회에 등록하여야 한다."},{"k":"hang","x":"③ 각 선거운동본부의 투표참관인은 투표소에 1인씩 배치하며, 교체 가능하다."},{"k":"hang","x":"④ 투표참관인은 정당한 이유 없이 참관을 거부하거나, 사임할 수 없다."},{"k":"hang","x":"⑤ 투표참관인은 투표소 질서 유지에 협조해야 한다."},{"k":"hang","x":"⑥ 투표참관인은 투표의 공정성에 영향을 주는 행위를 해서는 안 된다."},{"k":"hang","x":"⑦ 투표참관인은 선거관리위원회에 투표 진행 상황에 대한 이의제기를 할 수 있다."},{"k":"hang","x":"⑧ 투표참관인은 투표함 및 기표소 내외의 이상 유무를 선거관리위원과 함께 검사해야 하며, 문제가 있 을 시 이의제기를 할 수 있다. 여기에 불참할 경우 검사를 포기한 것으로 간주하고, 당일 투표소 설치에 관한 어떠한 이의제기도 할 수 없다."},{"k":"hang","x":"⑨ 투표참관인이 지각했을 경우 지각한 시간만큼의 참관을 포기한 것으로 간주하고 투표를 진행한다. 지각한 투표참관인은 자신의 도착 이전에 이루어진 투표에 대해 이의를 제기할 수 없다."}],"num":60,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a61","label":"제61조","title":"투표의 중단","paras":[{"k":"hang","x":"① 다음 각호의 경우 중 하나에 해당할 경우 해당 투표소의 투표를 중단시킨다."},{"k":"ho","x":"1. 투표소에 선거관리위원이 없을 때"},{"k":"ho","x":"2. 투표소 내에서 투표참관인의 이의제기로 인해 합의가 필요할 때"},{"k":"ho","x":"3. 투표소의 질서가 혼잡하여 공정한 투표를 진행할 수 없다고 판단될 때"},{"k":"hang","x":"② 제1항에 명시한 상황이 종료되었을 경우 바로 투표를 재개한다."}],"num":61,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a62","label":"제62조","title":"투표소 주의사항","paras":[{"k":"hang","x":"① 투표소 부근에서 선거관리위원, 투표참관인, 투표인을 제외한 사람이 선거에 영향을 미칠 목적으로 접근한다고 판단될 때 선거관리위원은 이들의 접근을 제한할 수 있다."},{"k":"hang","x":"② 투표소로부터 10m 이내에서 투표참관인을 포함한 모든 자는 선거에 영향을 미치는 표식을 지녀서는 안 된다."},{"k":"hang","x":"③ 투표소로부터 10m 이내에서 소란한 언동을 하는 자가 있을 시에는 선거관리위원이 제재한다."},{"k":"hang","x":"④ 투표소로부터 10m 이내에는 선거관리위원회 제작 선전벽보 외의 어떠한 선전물도 있어서는 안 된 다."}],"num":62,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a63","label":"제63조","title":"투표의 비밀보장","paras":[{"k":"hang","x":"① 투표의 비밀은 어떠한 경우에도 보장되어야 한다."},{"k":"hang","x":"② 투표인은 투표한 후보자의 성명이나 선거운동본부명을 누구에게도 또한 어떠한 때도 진술할 의무가 없으며, 누구든지 투표 마감 시각까지 진술을 강요할 수 없다."},{"k":"hang","x":"③ 투표인은 자신이 기표한 투표지를 공개할 수 없으며, 공개된 투표지는 무효로 한다."}],"num":63,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a64","label":"제64조","title":"투표 시작 전 투표함 이송","paras":[{"k":"hang","x":"① 각 투표함은 매 투표일 9시 30분에 선거관리위원과 각 선거운동본부장 또는 해당 선본의 정후보 또는 부후보의 입회 하에 선거관리위원회실에서 투표함의 투입구와 그 자물쇠를 봉쇄하여야 한다."},{"k":"hang","x":"② 자물쇠를 봉쇄한 투표함 및 투표용지, 선거인 명부, 참관시간기록표 등 투표에 필요한 제반 물품은 투표관리요원 및 선거운동본부에서 파견한 한 명이 각 투표소로 이송한다."}],"num":64,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a65","label":"제65조","title":"투표 종료 시 투표함 이송","paras":[{"k":"hang","x":"① 매 투표일 투표가 종료된 후 선거관리위원은 투표참관인의 참관 하에 투표함의 투입구와 그 자물쇠 를 봉쇄 후 날인하여야 한다."},{"k":"hang","x":"② 선거관리위원은 투표함의 이송 전에 해당 투표소의 투표참관인에게 투표함에 이상이 없음을 서면으로 확인받는다."},{"k":"hang","x":"③ 자물쇠를 이용해 봉해진 투표함 및 남은 투표용지, 선거인 명부, 참관시간기록표 등 투표에 필요한 제반 물품은 선거관리위원과 선거운동본부의 투표참관인이 선거관리위원회실로 이송한다."}],"num":65,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a66","label":"제66조","title":"투표함 확인","paras":[{"k":"line","x":"선거관리위원장은 투표함, 남은 투표용지, 선거인 명부 등을 인수하여 지체 없이 이상 여부를 확인한다."}],"num":66,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a67","label":"제67조","title":"투표함 보관","paras":[{"k":"line","x":"각 투표소의 투표함은 매 투표일 투표가 종료된 후 선거관리위원회가 지정한 선거관리위원회실에 보관 한다."}],"num":67,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제7절 투표성립"},{"t":"art","id":"a68","label":"제68조","title":"투표 성립 요건","paras":[{"k":"line","x":"학생회장단 선거는 3일간의 투표 기간이 지나고 명부상 투표율이 25% 이상일 경우 성립한다."}],"num":68,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제8절 개표"},{"t":"art","id":"a69","label":"제69조","title":"개표 공고","paras":[{"k":"line","x":"선거관리위원회는 투표개시일 전까지 개표 장소와 개표 시간을 공고해야 한다."}],"num":69,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a70","label":"제70조","title":"개표관리","paras":[{"k":"hang","x":"① 개표는 선거관리위원회가 담당한다."},{"k":"hang","x":"② 개표는 선거관리위원장과 선거관리위원의 과반수 이상의 출석과 승인 하에 진행할 수 있다."},{"k":"hang","x":"③ 선거관리위원회는 개표 전까지 투표함을 개표소로 옮기고, 개표에 필요한 모든 준비를 마쳐야 한다."},{"k":"hang","x":"④ 각 선거운동본부의 학생회장단 후보 및 선거운동본부장은 개표가 종료될 때까지 개표 장소에 있어야 한다."},{"k":"hang","x":"⑤ 각 선거운동본부는 개표참관인 2인을 선정하여 개표현장을 참관하도록 한다."},{"k":"hang","x":"⑥ 개표참관인은 선거관리위원회에 개표 진행상황에 대한 이의제기를 할 수 있다."}],"num":70,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a71","label":"제71조","title":"개표소","paras":[{"k":"hang","x":"① 개표소는 선거관리위원들이 개표를 하는 장소를 말하며, 개표장 내에서 방청객과 일정한 거리를 유지하는 위치에 설치하여야 한다."},{"k":"hang","x":"② 개표소에는 선거관리위원과 각 선거운동본부가 파견한 개표참관인만이 출입할 수 있다."}],"num":71,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a72","label":"제72조","title":"개표참관인","paras":[{"k":"hang","x":"① 각 선거운동본부는 개표개시일 전까지 개표참관인 2명을 선정하여 선거관리위원회에 통보하여야 한다."},{"k":"hang","x":"② 개표참관인은 개표 상황을 참관하고, 득표를 검산하는 등의 역할을 수행한다."},{"k":"hang","x":"③ 개표참관인의 교체는 선거관리위원장의 허가가 있어야 할 수 있다."}],"num":72,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a73","label":"제73조","title":"개표 시작 전 투표함 이송","paras":[{"k":"line","x":"각 투표함은 투입구와 그 자물쇠가 봉쇄된 채로 선거관리위원이 개표소로 이송한다."}],"num":73,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a74","label":"제74조","title":"개표개시","paras":[{"k":"hang","x":"① 개표는 투표함이 모두 도착한 후 개표준비가 완료되었다고 판단되는 즉시 시행한다."},{"k":"hang","x":"② 개표참관인은 투표함이 도착한 때에 그 봉인 등을 확인하고 관리상황을 참관한다."},{"k":"hang","x":"③ 투표함 하나의 개표가 끝나기 전에 다른 투표함을 열어서는 안 된다."},{"k":"hang","x":"④ 선거관리위원장은 개표소의 질서가 지나치게 혼잡하여 공정한 개표가 진행될 수 없다고 판단될 때에는 질서가 회복될 때까지 개표를 중단하고, 해당인의 퇴장을 명할 수 있다."}],"num":74,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a75","label":"제75조","title":"개표절차","paras":[{"k":"line","x":"개표절차는 다음 각호의 순서에 의한다."},{"k":"ho","x":"1. 총 투표자 수 공고"},{"k":"ho","x":"2. 투표함 개봉"},{"k":"ho","x":"3. 개표"},{"k":"ho","x":"4. 개표참관인의 재확인 및 득표의 검산"},{"k":"ho","x":"5. 득표를 후보 별로 분하여 투표함에 재투입"},{"k":"ho","x":"6. 현황판에 기재"},{"k":"ho","x":"7. 제2호부터 제6호까지의 과정을 투표소별로 반복"},{"k":"ho","x":"8. 현황판에 기재된 상황과 선거인 명부상 투표자 수를 비교하여 오차율 계산"},{"k":"ho","x":"9. 최종 결과 발표"}],"num":75,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a76","label":"제76조","title":"투표용지의 무효처리","paras":[{"k":"hang","x":"① 다음 각호의 어느 하나에 해당하는 투표용지는 무효로 한다."},{"k":"ho","x":"1. 어느 란에도 기표를 하지 아니한 것"},{"k":"ho","x":"2. 두 개 이상의 란에 기표한 것"},{"k":"ho","x":"3. 어느 란에 기표를 한 것인지 식별할 수 없는 것"},{"k":"ho","x":"4. 정해진 기표용구를 사용해 기표하지 않은 것"},{"k":"ho","x":"5. 투표용지에 선거관리위원의 서명ㆍ날인이 없는 것"},{"k":"hang","x":"② 다음 각호의 어느 하나에 해당하는 투표는 무효로 하지 아니한다."},{"k":"ho","x":"1. 기표한 것의 일부분 표시되거나 기표한 것 내부가 메워진 것으로 정해진 기표용구를 사용하여 기표를 한 것이 명확한 것"},{"k":"ho","x":"2. 후보자란 외에 추가 기표되었으나 추가 기표된 것이 어느 후보자에게도 기표한 것으로 볼 수 없 는 것"},{"k":"ho","x":"3. 두 후보자란의 구분선상에 기표된 것으로서 어느 후보자에게 기표한 것인지가 명확한 것"},{"k":"ho","x":"4. 기표한 것이 전사된 것으로서 어느 후보자에게 기표한 것인지가 명확한 것"},{"k":"ho","x":"5. 훼손되었으나 정규의 투표용지임이 명백하고 어느 후보자에게 기표한 것인지가 명확한 것"},{"k":"hang","x":"③ 정해진 투표용지를 사용하지 아니한 것은 투표용지로 보지 아니하고, 따라서 무효표로도 보지 아니 한다."}],"num":76,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a77","label":"제77조","title":"투표함의 무효처리","paras":[{"k":"hang","x":"① 한 투표소의 명부상 투표자 수와 투표함의 투표용지 수의 차이(이하 “오차”라 한다)가 명부상 투표자 수 대비 3%를 넘을 때 해당 투표함의 결과는 무효가 되며, 해당 투표용지 수만큼 무효표로 산입한다. 단, 명부상 투표자 수가 100 이하일 때는 오차는 3까지 허용한다."},{"k":"hang","x":"② 모든 투표소의 명부상 투표자 수 총합과 모든 투표함의 투표용지 수 총합의 차이(이하 “총오차”라 한다)가 명부상 총 투표자 수 대비 3%를 넘을 때 투표는 무효가 된다."}],"num":77,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a78","label":"제78조","title":"투표의 효력에 관한 이의에 대한 결정","paras":[{"k":"hang","x":"① 투표의 효력에 관하여 이의가 있는 때에는 선거관리위원회의 재적 위원 과반수의 출석과 출석 위원 과반수의 의결로 인용·기각을 결정한다."},{"k":"hang","x":"② 투표의 효력을 결정함에 있어서는 선거인의 의사가 존중되어야 한다."}],"num":78,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a79","label":"제79조","title":"투표용지ㆍ선거인명부 등의 보관","paras":[{"k":"line","x":"선거관리위원회는 투표용지ㆍ선거인명부 등을 당선 공고 후 48시간 동안 보관하여야 한다."}],"num":79,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제9절 당선"},{"t":"art","id":"a80","label":"제80조","title":"당선의 기준","paras":[{"k":"hang","x":"① 해당 선거에 출마한 후보가 두 조 이상일 경우 개표 결과 최다 득표한 후보를 당선 후보로 한다."},{"k":"hang","x":"② 해당 선거에 출마한 후보가 한 조일 경우 “찬성”표의 수가 “반대”와 “기권”표의 수의 합보다 많을 경우 그 후보를 당선으로 본다."},{"k":"hang","x":"③ 개표 결과가 본 세칙 제82조·제83조에 해당할 때는 당선을 확정할 수 없다."}],"num":80,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a81","label":"제81조","title":"당선공고","paras":[{"k":"hang","x":"① 개표 결과가 최종 확인되면 선거관리위원장은 이를 지체 없이 공고하고, 공고한 때로부터 48시간 동안 이의신청을 받는다."},{"k":"hang","x":"② 결과에 관한 이의신청이 있는 때에는 선거관리위원장은 지체 없이 회의를 소집하여 이를 심사한다. 이의신청의 인용ㆍ기각에 관하여서는 재적 위원 과반수의 출석과 출석 위원 과반수의 의결로 결정한다."},{"k":"hang","x":"③ 개표 결과의 최종 공고로부터 48시간 이내에 이의신청이 없으면 선거관리위원회는 당선자의 당선확정을 공고한다. 공고에는 다음 각호가 포함되어야 한다."},{"k":"ho","x":"1. 학생회장단 당선자의 이름, 소속 학과ㆍ반, 학번"},{"k":"ho","x":"2. 학생회장단 당선자의 선거운동본부명"},{"k":"ho","x":"3. 최종 투표율"},{"k":"ho","x":"4. 투표 결과(각 선거운동본부의 투표소별 득표수, 총 득표수, 득표율을 포함한다)"}],"num":81,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제10절 확정 및 기타"},{"t":"art","id":"a82","label":"제82조","title":"재투표ㆍ결선투표","paras":[{"k":"hang","x":"① 총오차율이 명부상 총 투표자 수 대비 3%를 넘을 때는 후보 자격이 있는 모든 후보를 후보로 하여 재투표를 시행한다."},{"k":"hang","x":"② 최고 득표조가 두 조 이상인 때는 최고 득표를 기록한 모든 조를 후보로 하여 결선투표를 시행한다."},{"k":"hang","x":"③ 1위 득표 조와의 득표 차이가 총오차보다 적은 조가 있을 때는 1위 득표 조와 해당 조들을 후보로 하여 결선투표를 시행한다."},{"k":"hang","x":"④ 재투표ㆍ결선투표는 개표 종료 후 7일 안에 3일 동안에 걸쳐 선거운동 없이 시행하며, 투표율에 상관없이 득표수가 많은 후보를 당선으로 한다."}],"num":82,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a83","label":"제83조","title":"재선거·보궐선거","paras":[{"k":"line","x":"재선거나 보궐선거를 시행하는 경우에는 선거에 관한 제반 규정을 준용한다."}],"num":83,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a84","label":"제84조","title":"투표기간 연기 및 연장","paras":[{"k":"hang","x":"① 해당 선거에 출마한 후보가 한 조일 때 투표율 미달, 천재지변이나 이에 준하는 사태로 투표를 진행 할 수 없을 경우 선거관리위원회는 선거관리위원회 회의를 통해 투표를 연기 혹은 연장할 수 있다. 단, 투표연장의 경우 최대 2일까지 연장할 수 있다."},{"k":"hang","x":"② 해당 선거에 출마한 후보가 두 조 이상일 때 천재지변이나 이에 준하는 사태로 투표를 진행할 수 없을 경우 선거관리위원회는 선거관리위원회 회의를 통해 투표를 연기할 수 있다."}],"num":84,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a85","label":"제85조","title":"선거 무효","paras":[{"k":"line","x":"다음 각호 중 하나의 경우에 해당할 경우 해당 선거는 무효처리가 되고, 비상대책위원회를 구성한다."},{"k":"ho","x":"1. 해당 선거에서 투표율이 미달될 경우"},{"k":"ho","x":"2. 선거시행세칙 제13조에 의해 선거관리위원회가 해체되었을 경우"}],"num":85,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제5장 선거 기록물 관리"},{"t":"art","id":"a86","label":"제86조","title":"선거 기록물 관리","paras":[{"k":"line","x":"선거에서 생산된 기록물 중 보존의 가치가 있는 것은 선거 일정이 모두 종료된 후 선거관리위원장이 기록물 관리기관으로 이관하고, 기록물 관리기관은 최대한 협조한다."}],"num":86,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"부칙","bu":true,"id":"bu1"},{"t":"free","paras":[{"k":"line","x":"이 세칙은 공포 후 2021년 11월 29일부터 시행한다."}]}],"note":null},{"id":"seongeo-20250512","date":"2025.05.12","kind":"전부개정","title":"선거시행세칙","subtitle":"[고려대학교 자유전공학부 학생회 세칙 제1호]","history":[["2017. 05. 27.","제정"],["2017. 08. 19.","전부개정"],["2021. 11. 13.","전부개정"],["2023. 02. 11.","일부개정"],["2025. 05. 12.","전부개정"]],"pdf":"pdf/seongeo-20250512.pdf","pdfName":"선거시행세칙(2025.05.12_전부개정).pdf","blocks":[{"t":"h","lv":2,"text":"제1장 총칙"},{"t":"art","id":"a1","label":"제1조","title":"목적","paras":[{"k":"line","x":"본 세칙은 고려대학교 자유전공학부 학부ㆍ반 학생회장단 선거에 관한 세부적인 사항을 규정하여 선거가 민주적인 절차에 따라 공정하게 치러질 수 있도록 함을 목적으로 한다."}],"num":1,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a2","label":"제2조","title":"적용범위","paras":[{"k":"hang","x":"① 본 세칙은 학부 학생회장단 선거에 적용한다."},{"k":"hang","x":"② 본 세칙은 ｢고려대학교 자유전공학부 학생회칙｣ 제177조의 동시선거로 진행하는 각 반 학생회장단 선거에 적용한다."},{"k":"hang","x":"③ 동시선거를 진행하지 않는 경우 각 반 학생회장단 선거의 진행은 각 반 학생회의 자치규칙에 따른다."},{"k":"hang","x":"④ 제3항에도 불구하고 선거에 관하여 반 학생회의 자치규칙에서 규정하고 있지 않거나 부실하다고 인정되는 사항은 해당 반 학생회의 선거관리위원회와 선거 후보자의 합의를 통하여 본 세칙의 일부를 적용하도록 할 수 있다."}],"num":2,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a3","label":"제3조","title":"기본이념","paras":[{"k":"hang","x":"① 선거는 보통ㆍ평등ㆍ직접ㆍ비밀선거를 원칙으로 한다."},{"k":"hang","x":"② 선거는 전대 학생회를 발전적으로 평가하고 계승하는 과정이어야 한다."},{"k":"hang","x":"③ 선거는 모든 회원의 적극적인 참여를 통하여 학생회의 민주성을 확립하는 과정이어야 한다."}],"num":3,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a4","label":"제4조","title":"선거사무협조","paras":[{"k":"line","x":"본회의 각 기구는 선거 사무에 관하여 선거관리위원회의 협조 요구를 받은 때에는 우선하여 이에 따라야 한다."}],"num":4,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a5","label":"제5조","title":"선거관리위원의 의무","paras":[{"k":"hang","x":"① 선거관리위원은 책임 있는 자세로 선거가 민주적인 절차에 따라 공정하게 치러질 수 있도록 하여야 한다."},{"k":"hang","x":"② 선거관리위원은 선거에 대한 부당한 영향력의 행사 등 선거 결과에 영향을 미치는 행위를 하여서는 아니 된다."}],"num":5,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a6","label":"제6조","title":"대표자의 의무","paras":[{"k":"hang","x":"① 학부 학생회장단, 학부운영위원 및 학생대표자회 대의원 또는 이에 준하는 자는 선거에 대한 부당한 영향력의 행사 등 선거 결과에 영향을 미치는 행위를 하여서는 아니 된다."},{"k":"hang","x":"② 학부 학생회장단, 학부운영위원 및 학생대표자회 대의원 또는 이에 준하는 자는 선거가 민주적이고 공정하게 치러질 수 있도록 최대한의 협조를 하여야 한다."}],"num":6,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a7","label":"제7조","title":"선거운동본부ㆍ후보자의 의무","paras":[{"k":"hang","x":"① 선거운동본부ㆍ후보자는 선거가 민주적이고 공정하게 치러지도록 노력하여야 한다."},{"k":"hang","x":"② 선거운동본부ㆍ후보자는 ｢고려대학교 자유전공학부 학생회칙｣ 중 선거 관련 규정, 본 세칙 및 본 세칙에 부수된 규칙을 준수하여야 한다."},{"k":"hang","x":"③ 선거운동본부ㆍ후보자는 선거관리위원회 및 선거운동본부장회의의 결정ㆍ합의사항을 준수하여야 한다."},{"k":"hang","x":"④ 선거운동본부ㆍ후보자는 선거가 발전적인 정책 선거로 치러지도록 노력하여야 한다."},{"k":"hang","x":"⑤ 선거운동본부ㆍ후보자는 선거가 원활하게 진행될 수 있도록 선거관리위원회에 최대한 협조하여야 한다."}],"num":7,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a8","label":"제8조","title":"세칙의 해석","paras":[{"k":"line","x":"본 세칙의 해석은 ｢고려대학교 자유전공학부 학생회칙｣ 제205조의 원칙과 절차를 준용한다."}],"num":8,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제2장 선거권과 피선거권"},{"t":"art","id":"a9","label":"제9조","title":"선거권","paras":[{"k":"hang","x":"① 본회의 정회원은 학부 학생회장단 선거의 선거권을 가지며, 선거권자 총수에 포함된다."},{"k":"hang","x":"② 제1항에도 불구하고 본회의 국제 회원은 학부 학생회장단 선거의 선거권을 행사한 경우에만 선거권자 총수에 포함된다."},{"k":"hang","x":"③ 본회의 준회원ㆍ수료회원은 학부 학생회장단 선거의 선거권을 가지며, 선거권을 행사한 경우에만 선거권자 총수에 포함된다."},{"k":"hang","x":"④ 각 반 학생회의 회원은 소속된 반 학생회장단 선거의 선거권을 가진다. 이때 제1항부터 제3항까지를 준용한다."}],"num":9,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a10","label":"제10조","title":"피선거권","paras":[{"k":"hang","x":"① 본회의 정회원으로 후보 등록 마감일 기준 3학기 이상 등록한 자는 학부 학생회장단 선거의 피선거권을 가진다."},{"k":"hang","x":"② 각 반 학생회의 회원은 소속된 반 학생회장단 선거의 피선거권을 가진다. 이때 피선거권의 자세한 사항은 각 반 학생회의 자치규칙으로 정한다."}],"num":10,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제3장 선거관리위원회"},{"t":"art","id":"a11","label":"제11조","title":"지위","paras":[{"k":"line","x":"선거관리위원회는 선거가 민주적인 절차에 따라 공정하게 치러질 수 있도록 선거에 관한 모든 업무의 결정과 집행을 담당하는 독립기구이다."}],"num":11,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a12","label":"제12조","title":"직무","paras":[{"k":"hang","x":"① 선거관리위원회는 다음 각호의 사무를 행한다."},{"k":"ho","x":"1. 선거 업무의 기획 및 집행"},{"k":"ho","x":"2. 선거의 홍보"},{"k":"ho","x":"3. 선거의 민주성ㆍ공정성을 높이기 위한 활동"},{"k":"ho","x":"4. 선거가 정책 중심의 선거가 되도록 하기 위한 활동"},{"k":"ho","x":"5. 선거의 원활한 진행을 위한 각 선거운동본부와의 협의"},{"k":"ho","x":"6. ｢고려대학교 자유전공학부 학생회칙｣ㆍ본 세칙 및 규칙에 따른 각 선거운동본부 감시"},{"k":"ho","x":"7. ｢고려대학교 자유전공학부 학생회칙｣ㆍ본 세칙 및 규칙을 위반한 선거운동본부에 대한 벌칙 심의 및 의결"},{"k":"ho","x":"8. 선거관리위원회 재정의 편성ㆍ운영 및 결산 공개"},{"k":"ho","x":"9. 그 밖의 선거 운영에 필요하다고 인정되는 사무"},{"k":"hang","x":"② 선거관리위원회는 ｢고려대학교 자유전공학부 학생회칙｣, 세칙 및 규칙을 성실히 준수함으로써 선거를 공정하게 관리하여야 한다."}],"num":12,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a13","label":"제13조","title":"위원","paras":[{"k":"hang","x":"① 다음 각호에 해당하는 사람은 선거관리위원이 된다. 단, 학부 학생회장단은 필요한 경우 일부만을 선거관리위원으로 파견할 수 있다."},{"k":"ho","x":"1. 학부 학생회장단 전원"},{"k":"ho","x":"2. 각 반 학생회에서 파견한 2명"},{"k":"hang","x":"② 학부 학생회장단과 각 반 학생회는 투표 시작일 22일 전까지 위원을 파견하여야 한다."},{"k":"hang","x":"③ 제2항에도 불구하고 각 반 학생회는 선거관리위원회의 파견 요청이 있으면 지체 없이 위원을 파견하여야 한다."},{"k":"hang","x":"④ 각 반 학생회에서 위원으로 파견되는 사람은 소속 의결기관의 의결을 거쳐야 한다."},{"k":"hang","x":"⑤ 학부운영위원회는 선거관리위원이 파견되면 지체 없이 이를 심사하여야 한다. 선거관리위원은 학부운영위원회의 심사를 거쳐 업무를 개시한다."},{"k":"hang","x":"⑥ 모든 선거관리위원은 선거관리위원회가 구성된 후 지체 없이 제5조와 제12조에 명시된 의무 이행 및 직무에 대하여 서약하여야 한다."},{"k":"hang","x":"⑦ 선거관리위원회는 위원의 해임ㆍ사직 및 추가 임명으로 인하여 그 구성에 변경이 있을 때는 이를 지체 없이 공고하여야 한다."}],"num":13,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a14","label":"제14조","title":"위원장","paras":[{"k":"hang","x":"① 위원장은 투표 시작일 21일 전까지 선거관리위원회 내부에서 민주적으로 선출한다. 위원장의 선출과 동시에 선거관리위원회가 구성된 것으로 본다."},{"k":"hang","x":"② 위원장은 선거관리위원회를 대표하고 그 사무를 관리ㆍ감독한다."},{"k":"hang","x":"③ 위원장은 선거관리위원회 회의의 의장이 된다."},{"k":"hang","x":"④ 위원장이 사고가 있을 때는 위원 중에서 호선된 한 명이 위원장의 직무를 대행한다."}],"num":14,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a15","label":"제15조","title":"위원의 해임 사유","paras":[{"k":"hang","x":"① 선거관리위원은 다음 각호 중 하나에 해당할 때가 아니면 해임되지 아니한다."},{"k":"ho","x":"1. 선거에 대한 부당한 영향력의 행사 또는 선거 결과에 영향을 미치는 행위를 하였을 때"},{"k":"ho","x":"2. 직무 수행 과정에서 ｢고려대학교 자유전공학부 학생회칙｣, 세칙 및 규칙을 위반하거나 선거의 공정성을 심각하게 훼손하였을 때"},{"k":"ho","x":"3. 선거에 입후보하거나 선거운동본부에 가입하였을 때"},{"k":"ho","x":"4. 본회의 회원이 아니게 되었을 때"},{"k":"hang","x":"② 선거관리위원에 대한 해임 요구는 다음 각호에 따라 가능하다."},{"k":"ho","x":"1. 선거관리위원의 요구"},{"k":"ho","x":"2. 각 선거운동본부 본부장의 요구"},{"k":"ho","x":"3. 본회의 회원 50명 이상의 연서에 따른 요구"},{"k":"hang","x":"③ 선거관리위원에 대한 해임 요구서는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식에 따라야 하며, 해임 요구에 대한 이유를 명시하여 선거관리위원장에게 서면으로 제출하여야 한다."},{"k":"hang","x":"④ 위원장은 위원에 대한 해임 요구서가 접수되면 지체 없이 회의를 소집하여 이를 심의한다."},{"k":"hang","x":"⑤ 선거관리위원회는 위원에 대한 해임을 재적 위원 과반수의 출석과 출석 위원 3분의 2 이상의 찬성으로 의결한다. 이때 해임 요구의 대상이 된 위원은 의결권을 행사할 수 없으며 재적 총수에서 제외된다."}],"num":15,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a16","label":"제16조","title":"위원의 사직","paras":[{"k":"hang","x":"① 선거관리위원은 불가피한 사유가 아니면 사직할 수 없다."},{"k":"hang","x":"② 위원이 사직하고자 할 때에는 ｢고려대학교 총학생회 사무처리세칙｣에서 정한 서식에 따라 그 사직에 대한 이유를 명시한 사직 요청서를 선거관리위원장에게 서면으로 제출하여야 한다."},{"k":"hang","x":"③ 위원장은 사직 요청이 접수되면 지체 없이 회의를 소집하여 이를 심의 및 의결한다."}],"num":16,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a17","label":"제17조","title":"위원의 추가 임명","paras":[{"k":"hang","x":"① 선거관리위원회는 해임 또는 사직으로 위원이 결원되었을 때는 그 위원이 소속된 기구에 새로운 위원의 파견을 요청할 수 있다. 단, 학부 학생회장단은 그러하지 아니한다."},{"k":"hang","x":"② 제1항에도 불구하고 선거관리위원회는 후보 등록 마감 시각 이후에는 위원을 추가 임명할 수 없다."},{"k":"hang","x":"③ 선거관리위원회는 제1항에 따른 위원의 추가 임명을 재적 위원 3분의 2 이상의 출석과 출석 위원 3분의 2 이상의 찬성으로 의결한다."}],"num":17,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a18","label":"제18조","title":"위원의 피선거권 등 제한","paras":[{"k":"hang","x":"① 선거관리위원은 본회와 본회의 산하기구ㆍ특별기구에서 치러지는 각종 선거에서 피선거권을 가지지 아니하며, 선거운동본부에 가입할 수 없다."},{"k":"hang","x":"② 해임되거나 사직한 선거관리위원은 해임 또는 사직이 의결된 날을 기준으로 진행되고 있는 선거가 있는 경우 해당 선거가 종료될 때까지 본회와 본회의 산하기구ㆍ특별기구에서 치러지는 각종 선거에서 피선거권을 가지지 아니하며, 선거운동본부에 가입할 수 없다."}],"num":18,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a19","label":"제19조","title":"개의ㆍ의결요건","paras":[{"k":"line","x":"선거관리위원회는 특별한 규정이 없는 한 재적 위원 과반수의 출석으로 개의하고 출석 위원 과반수 찬성으로 의결한다."}],"num":19,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a20","label":"제20조","title":"소집","paras":[{"k":"hang","x":"① 선거관리위원회는 다음 각호 중 하나에 따라 위원장이 소집한다."},{"k":"ho","x":"1. 위원장의 소집요구"},{"k":"ho","x":"2. 재적 위원 3분의 1 이상의 연서에 따른 소집요구"},{"k":"ho","x":"3. 후보자 또는 선거운동본부장의 이의신청에 따른 소집요구"},{"k":"hang","x":"② 제1항 제2호의 소집요구에도 불구하고 위원장이 회의의 소집을 거부한 때에는 회의 소집을 요구한 위원 중 한 명이 대표로 회의를 소집할 수 있다."}],"num":20,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a21","label":"제21조","title":"소집공고","paras":[{"k":"hang","x":"① 선거관리위원장은 회의의 소집을 개의 시각 전까지 공고하여야 한다."},{"k":"hang","x":"② 제1항에도 불구하고 제20조 제2항에 따른 회의 소집의 경우에는 회의 소집을 요구한 위원 중 한 명이 대표로 회의 소집을 공고하여야 한다."},{"k":"hang","x":"③ 공고문에는 다음 각호의 사항을 명시하여야 한다."},{"k":"ho","x":"1. 회의 시작 일시"},{"k":"ho","x":"2. 회의 장소"},{"k":"ho","x":"3. 안건과 안건에 대한 설명"}],"num":21,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a22","label":"제22조","title":"표결방법","paras":[{"k":"hang","x":"① 표결은 기명으로 함을 원칙으로 한다."},{"k":"hang","x":"② 중요한 안건으로서 위원장 또는 위원이 제의하여 선거관리위원회가 의결하면 표결을 무기명으로 할 수 있다."},{"k":"hang","x":"③ 제15조의 위원의 해임에 관한 사항은 반드시 무기명으로 표결하여야 한다."},{"k":"hang","x":"④ 위원장은 안건에 대한 이의가 있는지 물어서 이의가 없다고 인정하면 가결되었음을 선포할 수 있다. 단, 이의가 있을 때 또는 무기명으로 표결할 때는 반드시 표결하여야 한다."}],"num":22,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a23","label":"제23조","title":"안건","paras":[{"k":"line","x":"선거관리위원회는 다음 각호의 안건을 심의ㆍ의결한다."},{"k":"ho","x":"1. 선거관리위원이 발의한 안건"},{"k":"ho","x":"2. 후보자 또는 선거운동본부장의 이의신청을 통하여 발의된 안건"}],"num":23,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a24","label":"제24조","title":"출석요구","paras":[{"k":"line","x":"선거관리위원회는 원활한 선거관리를 위하여 다음 각호에 해당하는 사람의 회의 출석을 요구할 수 있다."},{"k":"ho","x":"1. 후보자"},{"k":"ho","x":"2. 각 선거운동본부의 본부장"},{"k":"ho","x":"3. 선거운동본부에 대한 벌칙 사유와 관련된 자"}],"num":24,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a25","label":"제25조","title":"선거운동본부장회의","paras":[{"k":"line","x":"선거관리위원장은 각 선거운동본부와의 협의를 위하여 위원장과 각 선거운동본부의 본부장이 참석하는 회의를 소집할 수 있다."}],"num":25,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a26","label":"제26조","title":"재정","paras":[{"k":"hang","x":"① 선거관리위원회는 구성 이후 지체 없이 선거관리위원회의 예산안을 작성하여 이를 학부운영위원회에 보고하여야 한다."},{"k":"hang","x":"② 선거관리위원회는 선거 종료 후 지체 없이 선거관리위원회의 결산을 작성하여 이를 학부운영위원회에 보고하여야 한다."},{"k":"hang","x":"③ 학부운영위원회는 제1항과 제2항에 따라 보고된 선거관리위원회의 예산안ㆍ결산을 심의한다."}],"num":26,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제4장 선거운동본부"},{"t":"art","id":"a27","label":"제27조","title":"지위","paras":[{"k":"line","x":"선거운동본부는 선거에 등록한 후보의 선거운동을 통하여 해당 후보의 당선을 도모하고, 각 현안에 대한 의견 표명ㆍ정책개발 등을 통하여 회원의 선거와 관련된 의사 형성에 도움을 주는 회원의 자발적 조직이다."}],"num":27,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a28","label":"제28조","title":"구성","paras":[{"k":"hang","x":"① 선거운동본부는 다음 각호로 구성된다."},{"k":"ho","x":"1. 후보자"},{"k":"ho","x":"2. 선거운동본부장"},{"k":"ho","x":"3. 선거운동본부원"},{"k":"hang","x":"② 학부 학생회장단 선거운동본부의 구성원은 본회의 회원이어야 한다."},{"k":"hang","x":"③ 반 학생회장단 선거운동본부의 구성원은 해당 반 학생회의 회원이어야 한다."},{"k":"hang","x":"④ 각 선거운동본부는 선거운동본부장을 반드시 두어야 한다. 단, 선거운동본부원은 그러하지 아니한다."}],"num":28,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a29","label":"제29조","title":"선거운동본부원의 모집","paras":[{"k":"hang","x":"① 선거운동본부는 제34조의 선거 공고 이후부터 본부원 모집을 위한 공고를 할 수 있다. 단, 공고문에는 다음 각호의 사항을 제외하고는 명시할 수 없다."},{"k":"ho","x":"1. 선거운동본부명"},{"k":"ho","x":"2. 후보자의 이름, 소속 학부ㆍ학과, 반, 학번"},{"k":"ho","x":"3. 선거운동본부장의 이름, 소속 학부ㆍ학과, 반, 학번"},{"k":"ho","x":"4. 후보자ㆍ선거운동본부장의 연락처"},{"k":"ho","x":"5. 500자 이내의 선거운동본부 소개"},{"k":"hang","x":"② 선거운동본부원을 모집하고자 하는 선거운동본부는 제1항의 공고문을 선거관리위원회에 제출하여 허가를 받아야 한다."},{"k":"hang","x":"③ 선거관리위원회는 제2항에 따라 선거운동본부원 모집 공고문이 접수되면 지체 없이 회의를 열어 공고문을 심의한다."},{"k":"hang","x":"④ 선거관리위원회는 공고문에 결함이 있을 때 공고문의 게시를 허가하지 않을 수 있으며, 해당 선거운동본부에 시정명령 1회를 준다."},{"k":"hang","x":"⑤ 선거관리위원회는 특정 선거운동본부가 선거관리위원회의 허가를 받지 않고 모집공고를 했을 때 해당 선거운동본부에 주의 1회를 줄 수 있다."}],"num":29,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a30","label":"제30조","title":"선거운동본부원의 등록","paras":[{"k":"hang","x":"① 각 선거운동본부는 제35조에 따른 후보 등록 신청과 함께 모집한 선거운동본부원을 선거관리위원회에 등록하여야 한다."},{"k":"hang","x":"② 각 선거운동본부는 제1항에 따른 등록 이후 선거운동본부원의 변동 사항이 있을 때는 이를 선거관리위원회에 보고하여야 한다. 보고한 선거운동본부원의 변동은 보고한 다음 날부터 유효하다."},{"k":"hang","x":"③ 선거관리위원회에 선거운동본부원으로 등록되지 아니한 자는 해당 선거운동본부의 구성원으로 활동할 수 없다."},{"k":"hang","x":"④ 선거관리위원회는 제3항을 위반한 선거운동본부에 시정명령 1회를 준다."}],"num":30,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a31","label":"제31조","title":"선거운동본부원으로 등록할 수 없는 자","paras":[{"k":"hang","x":"① 선거운동본부는 다음 각호에 해당하는 사람을 선거운동본부원으로 등록할 수 없다."},{"k":"ho","x":"1. 이미 다른 선거운동본부의 구성원으로 등록된 자"},{"k":"ho","x":"2. 제45조의 선거운동을 할 수 없는 자"},{"k":"hang","x":"② 제1항에도 불구하고 본회의 회원은 학부 학생회장단 선거운동본부와 소속된 반 학생회의 학생회장단 선거운동본부에 동시에 등록할 수 있다. 단, 후보자는 그러하지 아니한다."},{"k":"hang","x":"③ 선거관리위원회는 제1항을 위반한 선거운동본부에 시정명령 1회를 준다."},{"k":"hang","x":"④ 선거관리위원회는 특정 선거운동본부원이 여러 선거운동본부에 중복으로 등록된 것을 확인하면 어떤 선거운동본부의 잘못인지 판단하여 책임 있는 선거운동본부에 시정명령 1회를 준다. 다만, 모든 선거운동본부가 책임이 없으면 그러하지 아니하며 중복으로 등록한 자의 등록을 모두 무효로 한다."},{"k":"hang","x":"⑤ 선거운동본부원으로 등록할 의사가 없음에도 불구하고 강제로 등록된 자의 등록은 무효로 한다. 이때 선거관리위원회는 해당 선거운동본부에 주의 1회를 줄 수 있다. 다만, 해당 선거운동본부원의 변심에 의한 것은 그러하지 아니한다."}],"num":31,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a32","label":"제32조","title":"선거운동본부장","paras":[{"k":"hang","x":"① 선거운동본부장은 해당 선거운동본부를 대표하고 선거 과정 전반에서 후보자를 보좌하며, 후보자를 대신하여 선거관리위원회에 선거 운영 전반에 관한 의사를 표명한다."},{"k":"hang","x":"② 선거운동본부장은 해당 선거운동본부의 후보자가 임명한다."},{"k":"hang","x":"③ 후보자는 선거운동본부장을 교체할 수 있다."},{"k":"hang","x":"④ 제3항에 따라 후보자가 선거운동본부장을 교체하기 위해서는 다음 각호의 서류를 선거관리위원회에 제출하여야 한다."},{"k":"ho","x":"1. 신임 선거운동본부장의 이름, 소속 학부ㆍ학과, 반, 학번"},{"k":"ho","x":"2. 신임 선거운동본부장의 재학 또는 휴학(수료)증명서 1부"},{"k":"hang","x":"⑤ 제4항의 신청이 접수되면 선거관리위원회는 이를 심사하여 승인한다."},{"k":"hang","x":"⑥ 선거관리위원회는 심사 결과 선거운동본부장의 교체 신청에 결함이 있으면 해당 선거운동본부에 시정명령 1회를 준다."}],"num":32,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제5장 선거 일정 결정 및 선거 공고"},{"t":"art","id":"a33","label":"제33조","title":"선거 일정","paras":[{"k":"hang","x":"① 학부 학생회장단 선거는 매년 11월에 시행함을 원칙으로 한다."},{"k":"hang","x":"② 반 학생회장단 선거는 동시선거일 때에만 본조를 적용한다."},{"k":"hang","x":"③ 본조에도 불구하고 학부 학생회장단 선거와 각 반 학생회장단 선거를 동일한 일정에 따라 시행하는 동시선거에 있어서 본 세칙보다 상위 규정에 따라 선거 일정이 결정되는 경우, 해당 선거 일정에 따른다."},{"k":"hang","x":"④ 선거 기간은 다음 각호로 구성된다."},{"k":"ho","x":"1. 선거 공고"},{"k":"ho","x":"2. 추천 및 후보 등록 기간"},{"k":"ho","x":"3. 입후보자 공고"},{"k":"ho","x":"4. 선거운동 기간"},{"k":"ho","x":"5. 투표일"},{"k":"ho","x":"6. 개표일"},{"k":"ho","x":"7. 당선 공고"},{"k":"hang","x":"⑤ 학부운영위원회는 다음 각호에 따라 선거 일정을 정한다. 단, 투표일은 투표율이 성립 요건을 만족시키지 못한 경우 제58조 제2항에 따라 2일의 범위에서 연장할 수 있다."},{"k":"ho","x":"1. 선거 공고: 투표 시작일 14일 전"},{"k":"ho","x":"2. 추천 및 후보 등록 기간: 선거 공고 다음 날부터 투표 시작일 9일 전"},{"k":"ho","x":"3. 입후보자 공고: 후보 등록 마감일 다음 날까지"},{"k":"ho","x":"4. 선거운동 기간: 입후보자 공고 다음 날부터 투표 시작일 전날까지"},{"k":"ho","x":"5. 투표일: 3일간"},{"k":"hang","x":"⑥ 추천 및 후보 등록 기간과 투표일의 경우 토요일 및 공휴일은 일정을 진행하더라도 기간에 산입하지 아니함을 원칙으로 한다."},{"k":"hang","x":"⑦ 그 밖의 구체적인 선거 일정은 선거관리위원회에서 정한다."}],"num":33,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a34","label":"제34조","title":"선거 공고","paras":[{"k":"line","x":"선거관리위원회는 투표 시작일 14일 전에 다음 각호를 명시하여 학부ㆍ반 학생회장단 선거를 공고하여야 한다."},{"k":"ho","x":"1. 제33조에 따라 확정된 선거 일정"},{"k":"ho","x":"2. 제35조의 후보 등록 신청 마감 시각"},{"k":"ho","x":"3. 제36조 제1항의 후보 등록 심사 시각"},{"k":"ho","x":"4. 제35조 제1항 및 제2항의 후보 등록에 필요한 서류 종류 및 제출 방식"},{"k":"ho","x":"5. 선거관리위원장 및 선거관리위원 명단"},{"k":"ho","x":"6. 제13조 제6항의 선거관리위원 서약 내용 및 서명"}],"num":34,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제6장 후보자"},{"t":"art","id":"a35","label":"제35조","title":"후보 등록 신청","paras":[{"k":"hang","x":"① 학부 학생회장단 선거에 후보로 등록하려는 자는 후보 등록 마감 시각 전까지 다음 각호를 선거관리위원회에 제출하여야 한다."},{"k":"ho","x":"1. 학부 학생회장 후보와 학부 부학생회장 후보의 재학증명서 또는 정회원 등록 증명서ㆍ휴학(수료)증명서 각 1부"},{"k":"ho","x":"2. 선거운동본부장의 재학 또는 휴학(수료)증명서 1부"},{"k":"ho","x":"3. 후보 등록 신청서"},{"k":"ho","x":"4. 본회의 회원 50명 이상의 추천 서명(이때 서명에는 당해 연도 입학한 학번 10명 이상, 직전 연도 입학한 학번 10명 이상, 그 이전에 입학한 학번 10명 이상을 포함하는 것을 원칙으로 한다.)"},{"k":"ho","x":"5. 선거운동본부명"},{"k":"ho","x":"6. 선거운동본부원 명부"},{"k":"ho","x":"7. 출마 소견문 및 핵심 공약"},{"k":"ho","x":"8. 입후보자 공고용 사진"},{"k":"hang","x":"② 반 학생회장단 선거에 후보로 등록하려는 자는 후보 등록 마감 시각 전까지 다음 각호를 선거관리위원회에 제출하여야 한다."},{"k":"ho","x":"1. 반 학생회장 후보와 반 부학생회장 후보의 재학 또는 휴학(수료)증명서 각 1부"},{"k":"ho","x":"2. 선거운동본부장의 재학 또는 휴학(수료)증명서 1부"},{"k":"ho","x":"3. 후보 등록 신청서"},{"k":"ho","x":"4. 소속된 반 학생회의 회원 15명 이상의 추천 서명(이때 서명에는 당해 연도 입학한 학번 5명 이상, 직전 연도 입학한 학번 5명 이상, 그 이전에 입학한 학번 5명 이상을 포함하는 것을 원칙으로 한다.)"},{"k":"ho","x":"5. 선거운동본부명"},{"k":"ho","x":"6. 선거운동본부원 명부"},{"k":"ho","x":"7. 출마 소견문 및 핵심 공약"},{"k":"ho","x":"8. 입후보자 공고용 사진"},{"k":"hang","x":"③ 선거관리위원회는 제1항과 제2항의 서류 양식 및 제출 방식을 정하여 제34조 제4호에 따라 선거 공고에 명시하여야 하며, 선거관리위원회가 정한 서류 양식 및 제출 방식을 따르지 않은 서류는 무효이다."},{"k":"hang","x":"④ 추천 서명은 자필서명을 원칙으로 한다. 단, 선거관리위원회는 추천인의 서명을 추천인 본인 확인이 가능한 전자적 방법 또는 이에 준하는 수단으로 대체하여 받을 수 있다."},{"k":"hang","x":"⑤ 본회의 회원은 동일한 선거에서 서로 다른 후보를 동시에 추천할 수 있다. 단, 동일한 후보에 대한 중복 추천 서명은 인정하지 않는다."}],"num":35,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a36","label":"제36조","title":"후보 등록 심사","paras":[{"k":"hang","x":"① 선거관리위원회는 후보 등록 마감 시각 이후 24시간 이내에 회의를 소집하여 제35조에 따라 제출된 서류를 검토하고 제10조의 조건에 부합하는지를 심사한다."},{"k":"hang","x":"② 제1항의 회의에는 각 선거운동본부의 후보와 선거운동본부장이 모두 참석하여야 한다. 선거관리위원회는 후보 또는 선거운동본부장이 불참한 선거운동본부의 후보 등록을 허락하지 않을 수 있다."},{"k":"hang","x":"③ 선거관리위원회는 제1항에 따른 후보 등록 심사 후 문제가 없는 것으로 결정되면 해당 선거운동본부 후보의 등록을 허가한다."},{"k":"hang","x":"④ 선거관리위원회는 후보 등록 심사 결과 제35조에 따라 제출된 서류에 결함이 있을 때는 해당 선거운동본부에 주의 1회를 줄 수 있다."}],"num":36,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a37","label":"제37조","title":"규칙확정회의","paras":[{"k":"hang","x":"① 선거관리위원회는 제36조 제1항의 회의에 이어서 각 선거운동본부의 본부장이 참여하는 규칙확정회의를 개최한다."},{"k":"hang","x":"② 규칙확정회의에서는 다음 각호의 사항을 논의하고 선거관리위원회와 각 선거운동본부의 본부장이 합의하여 규칙에 규정할 사항을 정한다."},{"k":"ho","x":"1. 개인유세ㆍ합동유세의 개최 여부 및 세부적인 운영 방법"},{"k":"ho","x":"2. 후보간담회ㆍ공청회의 개최 여부 및 세부적인 운영 방법"},{"k":"ho","x":"3. 인터넷 선거운동 공간의 구성 및 세부적인 운영 방법"},{"k":"ho","x":"4. 선거운동본부 선전물의 규격, 수량 및 게시ㆍ배포 방법"},{"k":"ho","x":"5. 선거운동본부 선전물의 사전 허가 방법"},{"k":"ho","x":"6. 선거운동본부복의 착용 여부"},{"k":"ho","x":"7. 선거비용 보전금 상한액"},{"k":"ho","x":"8. 입후보자 공고의 규격, 수량 및 게시 위치"},{"k":"ho","x":"9. 그 밖의 선거에 관하여 규정이 필요하다고 인정되는 사항"},{"k":"hang","x":"③ 선거관리위원회는 제2항에서 결정된 사항을 제109조 제1항에 따라 본 세칙에 부수되는 규칙으로 제정한다. 단, 이에 따라 제정되는 규칙은 해당 선거가 종료될 때까지만 효력이 있다."},{"k":"hang","x":"④ 선거관리위원회는 제3항에 따라 규칙이 제정되면 지체 없이 이를 공포하여야 한다."},{"k":"hang","x":"⑤ 선거관리위원회는 규칙확정회의에서 벌칙에 해당하는 행위, 투표참관인 및 개표참관인 등록 일정 등 본 세칙에 기반한 원활한 선거 진행을 위하여 필요한 사항을 각 선거운동본부에 고지하여야 한다."},{"k":"hang","x":"⑥ 선거관리위원회는 각 선거운동본부의 본부장이 규칙확정회의에 참여하지 않으면 해당 선거운동본부에 주의 1회를 줄 수 있다."}],"num":37,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a38","label":"제38조","title":"입후보자 공고","paras":[{"k":"line","x":"선거관리위원회는 후보 등록 마감일 다음 날까지 다음 각호의 사항을 명시하여 입후보자를 공고하여야 한다."},{"k":"ho","x":"1. 후보자의 이름, 소속 학부ㆍ학과, 반, 학번"},{"k":"ho","x":"2. 선거운동본부명과 선거운동본부장의 이름, 소속 학부ㆍ학과, 반, 학번"},{"k":"ho","x":"3. 핵심 공약"},{"k":"ho","x":"4. 입후보자 공고용 사진"}],"num":38,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a39","label":"제39조","title":"후보자의 겸직 금지","paras":[{"k":"hang","x":"① 후보가 되려는 사람이 다음 각호의 어느 하나에 해당하면 후보 등록 마감 시각 전까지 그 직을 그만두어야 한다. 단, 현재 그 직에 있는 자가 재임을 위하여 해당 선거에 출마하려는 경우에는 그러하지 아니한다."},{"k":"ho","x":"1. 학부 학생회장과 학부 부학생회장"},{"k":"ho","x":"2. 학부 집행위원"},{"k":"ho","x":"3. 반 학생회장과 반 부학생회장"},{"k":"ho","x":"4. 각 반 고학번 대표와 신입생 대표"},{"k":"ho","x":"5. 각 자치단체장"},{"k":"ho","x":"6. 각 특별기구장"},{"k":"ho","x":"7. 제1호부터 제6호까지의 직에 준하는 자"},{"k":"hang","x":"② 제1항의 규정에 따라 사퇴하고자 하는 사람의 사퇴는 그 소속 기구에서 게시한 사퇴 공고를 통하여 확인함을 원칙으로 한다."}],"num":39,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a40","label":"제40조","title":"후보의 사퇴","paras":[{"k":"hang","x":"① 후보자가 사퇴하고자 하는 때에는 정후보ㆍ부후보 전원이 직접 선거관리위원회에 문서로 신고한다. 단, 선거운동 기간 이후에는 사퇴할 수 없다."},{"k":"hang","x":"② 제1항에도 불구하고 정후보ㆍ부후보 중 한 명 이상이 사망한 경우에는 당연 사퇴로 본다."},{"k":"hang","x":"③ 후보자의 사퇴가 접수되면 선거관리위원장은 지체 없이 이를 공고하여야 한다."}],"num":40,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a41","label":"제41조","title":"후보 자격 박탈 공고","paras":[{"k":"line","x":"선거관리위원회는 후보자의 후보 자격이 박탈되면 지체 없이 이를 공고한다."}],"num":41,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제7장 선거운동과 선거운동자금"},{"t":"art","id":"a42","label":"제42조","title":"선거운동","paras":[{"k":"hang","x":"① 선거운동은 특정 후보의 당선을 위한 제반 행위이다."},{"k":"hang","x":"② 다음 각호의 행위는 선거운동으로 보지 아니한다."},{"k":"ho","x":"1. 선거에 관한 일반적인 의견 개진 및 의사표시"},{"k":"ho","x":"2. 후보 등록과 선거운동을 위한 준비행위"},{"k":"ho","x":"3. 후보자 추천에 관한 단순한 지지ㆍ반대의 의견 개진 및 의사표시"},{"k":"ho","x":"4. 본회의 각 기구 및 학내 단체의 통상적인 활동"},{"k":"hang","x":"③ 특정 후보를 위한 선거운동은 해당 후보가 속한 선거운동본부의 구성원만 할 수 있다."},{"k":"hang","x":"④ 선거관리위원회는 제3항을 위반한 선거운동본부에 시정명령 1회를 준다."}],"num":42,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a43","label":"제43조","title":"투표 참여 권유 활동","paras":[{"k":"line","x":"본회의 회원은 투표 참여를 권유하는 행위를 할 수 있다. 단, 다음 각호의 어느 하나에 해당하면 그러하지 아니하다."},{"k":"ho","x":"1. 본회의 자치공간에 방문하여서 하는 경우"},{"k":"ho","x":"2. 투표소로부터 20미터 안에서 하는 경우"},{"k":"ho","x":"3. 특정 선거운동본부 또는 후보자를 지지ㆍ반대하는 내용을 포함하여서 하는 경우"},{"k":"ho","x":"4. 그 밖의 특정 선거운동본부 또는 후보자임을 유추할 수 있는 내용을 포함한 선전물을 사용하여서 하는 경우"}],"num":43,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a44","label":"제44조","title":"선거운동 기간","paras":[{"k":"hang","x":"① 선거운동은 입후보자 공고 다음 날부터 투표 시작일 전날까지에 한하여 할 수 있다. 단, 다음 각호의 어느 하나에 해당하면 그러하지 아니하다."},{"k":"ho","x":"1. 제29조 제1항의 선거운동본부원 모집 행위"},{"k":"ho","x":"2. 후보자의 선거운동본부원 모집을 위한 유세 행위"},{"k":"ho","x":"3. 후보자에 대한 추천 서명 행위"},{"k":"ho","x":"4. 설문조사"},{"k":"hang","x":"② 그 밖의 선거운동 기간에 관한 자세한 사항은 선거관리위원회에서 정한다."},{"k":"hang","x":"③ 선거관리위원회는 제1항을 위반한 선거운동본부에 경고 1회를 줄 수 있다."}],"num":44,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a45","label":"제45조","title":"선거운동을 할 수 없는 자","paras":[{"k":"hang","x":"① 다음 각호에 해당하는 자는 선거운동을 할 수 없다."},{"k":"ho","x":"1. 본회의 회원이 아닌 자"},{"k":"ho","x":"2. 선거관리위원장과 선거관리위원"},{"k":"ho","x":"3. 선거 공고일로부터 6개월 이내에 학부 학생회장 또는 학부 부학생회장의 직에 있었거나, 현재 그 직에 있는 자"},{"k":"ho","x":"4. 선거 공고일로부터 6개월 이내에 반 학생회장 또는 반 부학생회장의 직에 있었거나, 현재 그 직에 있는 자"},{"k":"ho","x":"5. 반 신입생 대표"},{"k":"ho","x":"6. 반 고학번 대표"},{"k":"ho","x":"7. 자치단체장"},{"k":"ho","x":"8. 특별기구장"},{"k":"ho","x":"9. 후보 등록 마감 시각 기준 학부 집행위원장과 학부 집행위원의 직에 있는 자"},{"k":"hang","x":"② 제18조 제2항에 따라 선거관리위원장과 선거관리위원은 사직하더라도 선거운동을 할 수 없다."},{"k":"hang","x":"③ 학부 집행위원장과 학부 집행위원은 후보 등록 마감 시각 전에 사퇴하면 선거운동을 할 수 있다. 이때 사퇴는 공고를 통하여 확인함을 원칙으로 한다."},{"k":"hang","x":"④ 후보자의 선거운동 행위에는 본조를 적용하지 아니한다."},{"k":"hang","x":"⑤ 선거관리위원회는 제1항 각호의 선거운동을 할 수 없는 자가 선거운동을 한 선거운동본부에 주의 1회를 줄 수 있으며, 해당 선거운동을 할 수 없는 자에게 사과문을 요구하고 그 사과문을 공고한다."}],"num":45,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a46","label":"제46조","title":"선거운동 방법","paras":[{"k":"line","x":"선거운동은 다음 각호의 방법으로 한다."},{"k":"ho","x":"1. 선전물의 게시 또는 배포"},{"k":"ho","x":"2. 개인유세"},{"k":"ho","x":"3. 합동유세"},{"k":"ho","x":"4. 공청회 참가"},{"k":"ho","x":"5. 온라인 선거운동 공간의 구성 및 운영"},{"k":"ho","x":"6. 선거운동본부복의 착용"},{"k":"ho","x":"7. 그 밖의 당선을 위한 각종 행위"}],"num":46,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a47","label":"제47조","title":"게시물ㆍ유인물의 사전 허가","paras":[{"k":"hang","x":"① 선거운동본부는 게시 및 배포하고자 하는 선거 관련 게시물ㆍ유인물의 개수와 그 내용에 관하여 선거관리위원회의 사전 허가를 받아야 한다."},{"k":"hang","x":"② 선거관리위원회는 게시물ㆍ유인물의 사전 허가 방법을 규칙확정회의에서 정한다. 이때 사전 허가의 방법은 모든 선거운동본부에 공정하여야 한다."},{"k":"hang","x":"③ 선거관리위원회는 제48조 및 제49조에 따른 규격에서 5% 범위의 오차를 넘어선 게시물ㆍ유인물의 게시 및 배포를 허가하지 않을 수 있다."},{"k":"hang","x":"④ 선거관리위원회는 제3항의 경우 해당 선거운동본부에 시정명령 1회를 준다."},{"k":"hang","x":"⑤ 선거관리위원회는 선거 관련 게시물ㆍ유인물에 타 후보에 대한 비방 등 선거의 공정성을 해칠 수 있는 내용이 있으면 게시 및 배포를 허가하지 않을 수 있다. 이때 선거관리위원회는 해당 선거운동본부에 주의 1회를 줄 수 있다."},{"k":"hang","x":"⑥ 선거관리위원회는 선거운동본부가 사전 허가를 받지 않은 게시물ㆍ유인물을 게시ㆍ배포한 때에는 수거를 명할 수 있다. 이때 선거관리위원회는 해당 선거운동본부에 경고 1회를 줄 수 있다."}],"num":47,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a48","label":"제48조","title":"게시물","paras":[{"k":"hang","x":"① 선거운동본부가 선거운동 기간 게시판ㆍ장소에 부착하거나 온라인 플랫폼에 올린 선전물을 게시물이라 한다."},{"k":"hang","x":"② 게시물은 다음 각호로 분류한다."},{"k":"ho","x":"1. 대자보: 각 선거운동본부가 해당 선거운동본부의 견해를 널리 주장하기 위하여 이를 큰 종이에 작성하여 부착하는 선전물"},{"k":"ho","x":"2. 포스터: 각 선거운동본부가 홍보 등을 목적으로 제작하여 부착하는 선전물"},{"k":"ho","x":"3. 온라인 플랫폼에 게시한 제작물: 각 선거운동본부가 홍보 등을 목적으로 제작하여 온라인 플랫폼에 게시한 글ㆍ그림ㆍ사진ㆍ영상 등의 선전물"},{"k":"hang","x":"③ 선거운동본부는 종류의 제한 없이 A2 크기 이하의 대자보, 그리고 A2 크기 이하의 포스터를 부착할 수 있다. 이때 동시에 부착할 수 있는 대자보 및 포스터의 개수는 모든 게시판을 합하여 10매 이내로 한다."},{"k":"hang","x":"④ 선거운동본부는 선거관리위원회가 허가한 게시판, 장소 및 온라인 플랫폼에만 선전물을 게시할 수 있다."},{"k":"hang","x":"⑤ 선거관리위원회는 모든 선거운동본부의 선전물 게시를 최대한 보장하여야 한다."},{"k":"hang","x":"⑥ 그 밖의 게시물과 관련된 자세한 사항들은 선거관리위원회와 각 선거운동본부의 합의로 결정한다."},{"k":"hang","x":"⑦ 선거관리위원회는 제3항 또는 제4항을 위반한 선거운동본부에 주의 1회를 줄 수 있다."}],"num":48,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a49","label":"제49조","title":"유인물","paras":[{"k":"hang","x":"① 선거운동본부가 선거운동 기간 발행하여 배포하는 선전물을 유인물이라 한다."},{"k":"hang","x":"② 각 선거운동본부는 횟수에 상관없이 유인물을 발행할 수 있다."},{"k":"hang","x":"③ 유인물의 배포 시 크기는 A3 크기 이하로 한다. 단, 접지하는 유인물의 경우 펼쳤을 때 A1 크기 이하로 한다."},{"k":"hang","x":"④ 유인물은 총 200부 이내로 발행하여야 한다."},{"k":"hang","x":"⑤ 각 선거운동본부는 B5 크기에 표지를 포함하여 20쪽 이내 소책자를 배포할 수 있으며, 제3항 및 제4항의 적용을 받지 아니한다."},{"k":"hang","x":"⑥ 선거관리위원회는 모든 선거운동본부의 유인물 발행을 최대한 보장하여야 한다."},{"k":"hang","x":"⑦ 그 밖의 유인물과 관련된 자세한 사항들은 선거관리위원회와 각 선거운동본부의 합의로 결정한다."},{"k":"hang","x":"⑧ 선거관리위원회는 제3항의 유인물 크기 또는 제4항의 유인물 부수 규정을 위반한 선거운동본부에 주의 1회를 줄 수 있다."}],"num":49,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a50","label":"제50조","title":"개인유세","paras":[{"k":"hang","x":"① 개인유세는 각 선거운동본부의 구성원이 선거운동의 하나로 벌이는 강의실 유세, 선전물 배포 등의 모든 종류의 선전 활동이다."},{"k":"hang","x":"② 개인유세는 8시부터 20시까지에 한하여 각 선거운동본부가 수시로 개최할 수 있다."},{"k":"hang","x":"③ 선거관리위원회는 선거의 민주성ㆍ대중성 향상을 위하여 각 선거운동본부의 개인유세를 최대한 보장하여야 한다. 단, 지나친 소음 등으로 회원의 불편을 초래할 위험이 있거나 초래한 때에는 이를 제한할 수 있다."},{"k":"hang","x":"④ 특정 선거운동본부가 이동 인구가 많은 시간 및 장소를 독점하여 사용할 수 없으며, 선거관리위원회는 필요하다고 인정되는 때에 규칙을 통하여 독점 행위를 제한할 수 있다."},{"k":"hang","x":"⑤ 그 밖의 개인유세와 관련된 자세한 사항들은 선거관리위원회와 각 선거운동본부의 합의로 결정한다."},{"k":"hang","x":"⑥ 선거관리위원회는 제2항을 위반한 선거운동본부에 주의 1회를 줄 수 있다."},{"k":"hang","x":"⑦ 선거관리위원회는 제3항 또는 제4항의 제한을 위반한 선거운동본부에 주의 1회를 줄 수 있다."}],"num":50,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a51","label":"제51조","title":"합동유세","paras":[{"k":"hang","x":"① 선거관리위원회는 하나의 선거에서 후보로 등록한 조가 두 개 이상이면 합동유세를 개최할 수 있다."},{"k":"hang","x":"② 합동유세는 선거운동 기간 중 2회 이하로 시행한다."},{"k":"hang","x":"③ 합동유세의 진행은 선거관리위원장이 한다."},{"k":"hang","x":"④ 유세 순서는 합동유세 1시간 전에 추첨하여 정한다."},{"k":"hang","x":"⑤ 후보자는 유세 시작 10분 전까지 합동유세 현장에 도착하여야 한다."},{"k":"hang","x":"⑥ 각 선거운동본부는 유세 시간을 준수하여야 한다. 각 선거운동본부당 유세 시간은 선거관리위원회가 결정하며, 제한 시간을 초과하면 선거관리위원회는 마이크 등 유세시설을 철거하여 유세를 중단시킨다. 단, 유세자를 교체하기 위해 걸리는 시간은 유세 시간에 포함되지 않는다."},{"k":"hang","x":"⑦ 후보자는 합동유세가 끝날 때까지 합동유세장에서 퇴장할 수 없다. 단, 부득이할 때에는 선거관리위원장의 동의를 받아 자리를 비울 수 있다."},{"k":"hang","x":"⑧ 후보자는 다른 선거운동본부 후보자의 유세 시간 중에 유세를 방해하거나 자기 선본의 유인물을 배포하는 행위를 할 수 없다."},{"k":"hang","x":"⑨ 그 밖의 합동유세와 관련된 자세한 사항들은 선거관리위원회와 각 선거운동본부의 합의로 결정한다."},{"k":"hang","x":"⑩ 선거관리위원회는 제5항부터 제8항까지 중 어느 하나를 위반한 선거운동본부에 주의 1회를 줄 수 있다."}],"num":51,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a52","label":"제52조","title":"공청회","paras":[{"k":"hang","x":"① 선거운동본부는 선거관리위원회에 공청회를 요청할 수 있으며, 선거관리위원회는 정당한 사유 없이 선거운동본부의 요청을 거부할 수 없다."},{"k":"hang","x":"② 선거관리위원회는 하나의 선거에서 후보로 등록한 조가 두 개 이상이면 합동 공청회를 진행할 수 있다."},{"k":"hang","x":"③ 공청회의 진행은 선거관리위원장이 한다."},{"k":"hang","x":"④ 후보자는 공청회 시작 10분 전까지 공청회 현장에 도착하여야 한다."},{"k":"hang","x":"⑤ 선거관리위원회는 공청회의 공정한 진행을 위하여 질의 중 일부를 선별하여 공개할 수 있다."},{"k":"hang","x":"⑥ 그 밖의 공청회와 관련된 자세한 사항들은 선거관리위원회와 각 선거운동본부의 합의로 결정한다."},{"k":"hang","x":"⑦ 선거관리위원회는 제4항을 위반한 선거운동본부에 주의 1회를 줄 수 있다."}],"num":52,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a53","label":"제53조","title":"온라인 선거운동","paras":[{"k":"hang","x":"① 선거운동본부는 홈페이지ㆍ카페 및 커뮤니티 등의 인터넷 선거운동 공간을 구성할 수 있다."},{"k":"hang","x":"② 선거운동본부는 선거관리위원회가 허용한 인터넷 공간에서만 선거 관련 논쟁 및 답변 등의 의사 표현을 할 수 있다."},{"k":"hang","x":"③ 선거관리위원회는 각 선거운동본부를 대표하여 인터넷 공간에서 선거 관련 의사 표현을 할 수 있는 아이디의 수를 제한하고, 해당 아이디를 보고하도록 할 수 있다."},{"k":"hang","x":"④ 그 밖의 온라인 선거운동과 관련된 자세한 사항은 선거관리위원회와 각 선거운동본부의 합의로 결정한다."},{"k":"hang","x":"⑤ 선거관리위원회는 제2항을 위반한 선거운동본부에 경고 1회를 줄 수 있다."},{"k":"hang","x":"⑥ 선거관리위원회는 제3항에 따라 보고 받은 아이디 이외의 아이디를 사용하여 선거 관련 의사 표현을 한 선거운동본부에 주의 1회를 줄 수 있다."}],"num":53,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a54","label":"제54조","title":"선거운동본부복","paras":[{"k":"hang","x":"① 선거운동본부는 후보의 신상 정보, 선거운동본부의 이름, 상징물, 구호 등이 적힌 의상 1종을 선거운동본부복으로 하여 선거운동본부의 구성원에게 착용하게 할 수 있다."},{"k":"hang","x":"② 선거운동본부는 선거운동본부복으로 사용하고자 하는 의상 1종의 디자인을 선거관리위원회에 보고하고 허가를 받아야 한다."},{"k":"hang","x":"③ 선거관리위원회는 제2항에 따라 보고 받은 선거운동본부복에 타 후보에 대한 비방 등 선거의 공정성을 해칠 수 있는 내용이 있으면 착용 금지를 명할 수 있다. 이때 선거관리위원회는 해당 선거운동본부에 주의 1회를 줄 수 있다."},{"k":"hang","x":"④ 선거관리위원회는 선거운동본부가 사전 허가를 받지 않은 선거운동본부복을 착용한 선거운동본부에 경고 1회를 줄 수 있다."}],"num":54,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a55","label":"제55조","title":"선거운동자금","paras":[{"k":"hang","x":"① 선거에서 선거운동을 위하여 선거운동 기간 소요되는 재산상의 가치가 있는 것으로서 선거운동본부가 부담하는 비용을 선거운동자금이라 한다."},{"k":"hang","x":"② 각 선거운동본부는 선거운동자금의 일부를 학생회비에서 보전받을 수 있다."},{"k":"hang","x":"③ 선거운동자금을 보전받고자 하는 각 선거운동본부의 본부장은 선거 결과가 확정된 날로부터 7일 이내에 선거운동자금의 결산을 작성하여 학부운영위원회에 제출한다."},{"k":"hang","x":"④ 학부운영위원회는 제3항에 따라 제출된 결산을 심의하고 특별한 결함이 없으면 해당 선거운동본부의 선거운동자금을 보전한다."},{"k":"hang","x":"⑤ 선거운동자금 보전액은 각 선거운동본부의 형평성이 침해되지 않도록 규칙확정회의에서 정한다."},{"k":"hang","x":"⑥ 그 밖의 선거운동자금에 관한 자세한 사항은 규칙으로 정한다."}],"num":55,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제8장 투표"},{"t":"h","lv":3,"text":"제1절 통칙"},{"t":"art","id":"a56","label":"제56조","title":"투표의 비밀보장","paras":[{"k":"hang","x":"① 선거에서 투표의 비밀은 보장되어야 한다."},{"k":"hang","x":"② 선거인은 투표한 후보자의 이름이나 선거운동본부명을 누구에게도 그리고 어떠한 때에도 진술할 의무가 없으며, 누구든지 투표 마감 시각까지 이를 질문하거나 그 진술을 요구할 수 없다."}],"num":56,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a57","label":"제57조","title":"투표 방법","paras":[{"k":"hang","x":"① 투표는 전자투표 방법으로 함을 원칙으로 한다."},{"k":"hang","x":"② 선거관리위원회는 필요하다고 인정될 때는 기표소 설치, 우편 그 밖의 다양한 투표 방법을 병행할 수 있다."},{"k":"hang","x":"③ 선거관리위원회는 제2항에 따라 결정된 투표 방법의 시행 여부, 대상, 방식, 운영 등에 관하여 본 세칙에 특별한 규정이 없으면 규칙으로 정한다. 단, 이에 따라 제정되는 규칙은 해당 선거가 종료될 때까지만 효력이 있다."},{"k":"hang","x":"④ 선거관리위원회는 기표 방법에 따른 오프라인 투표에만 제61조부터 제77조까지에 명시된 세칙을 따른다. 추가로 정하여야 하는 사항은 규칙확정회의에서 정한다."},{"k":"hang","x":"⑤ 투표관리위원회가 ｢고려대학교 자유전공학부 학생회칙｣ 제48조에 따라 본 세칙을 준용할 때 ｢고려대학교 자유전공학부 학생회칙｣ 제45조 제3항에 따른 규칙은 해당 학생총투표가 종료될 때까지만 효력이 있으며, 해당 규칙은 제109조 제2항에 따른 학생총투표시행규칙으로 본다."}],"num":57,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a58","label":"제58조","title":"투표일ㆍ투표 시간","paras":[{"k":"hang","x":"① 투표는 3일간 진행한다."},{"k":"hang","x":"② 선거관리위원회는 투표 기간이 종료하였음에도 투표율이 제78조의 투표 성립 요건을 넘지 않았으면 의결로 투표 기간을 2일의 범위에서 1회 연장할 수 있다."},{"k":"hang","x":"③ 선거관리위원회는 천재지변이나 이에 준하는 사태로 투표를 진행할 수 없으면 의결로 투표 기간을 연기하거나 2일의 범위에서 1회 연장할 수 있다."},{"k":"hang","x":"④ 투표 시간은 9시 30분부터 18시 30분까지로 한다. 단, 선거관리위원회가 필요하다고 인정할 때는 특정 투표구나 전자투표의 투표 시간을 당일 내로 한정하여 연장할 수 있다."}],"num":58,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a59","label":"제59조","title":"투표용지","paras":[{"k":"hang","x":"① 투표용지에는 후보자의 이름, 소속 학부ㆍ학과, 반, 학번 및 선거운동본부명을 표시하여야 한다."},{"k":"hang","x":"② 투표용지에서의 후보자 게재 순서는 제35조 제1항 제4호 또는 제35조 제2항 제4호에 따라 제출한 추천서의 추천인 수가 많은 순서로 한다."},{"k":"hang","x":"③ 하나의 선거에 등록한 후보가 두 조 이상이면 투표용지에는 후보자 칸과 동일한 크기의 “지지 선본 없음” 칸을 두어야 한다."},{"k":"hang","x":"④ 하나의 선거에 등록한 후보가 한 조이면 투표용지에는 “찬성”, “반대”, “기권” 칸을 두어야 한다."}],"num":59,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a60","label":"제60조","title":"투표ㆍ개표 공고","paras":[{"k":"hang","x":"① 선거관리위원회는 투표 시작일 1일 전까지 투표 및 개표에 관한 사항을 공고하여야 한다."},{"k":"hang","x":"② 공고문에는 다음 각호의 사항을 명시하여야 한다. 단, 제3호는 기표 방법에 따른 투표를 병행하는 경우에만 그러하다."},{"k":"ho","x":"1. 투표 방법"},{"k":"ho","x":"2. 온라인 투표 플랫폼"},{"k":"ho","x":"3. 투표소 명칭 및 소재지"},{"k":"ho","x":"4. 투표일ㆍ투표 시간"},{"k":"ho","x":"5. 개표 장소"},{"k":"ho","x":"6. 개표 시작 일시"}],"num":60,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 기표 방법에 따른 투표에 관한 특례"},{"t":"art","id":"a61","label":"제61조","title":"투표소","paras":[{"k":"hang","x":"① 선거관리위원회는 의결로 투표소를 편성한다."},{"k":"hang","x":"② 투표소에는 다음 각호의 시설을 설비하여야 한다."},{"k":"ho","x":"1. 기표소"},{"k":"ho","x":"2. 투표함"},{"k":"ho","x":"3. 선거관리위원 및 투표참관인의 좌석"},{"k":"ho","x":"4. 그 밖의 투표 관리에 필요하다고 인정되는 시설"},{"k":"hang","x":"③ 투표소와 투표소로부터 10m 이내에는 선거관리위원회가 부착한 것을 제외한 어떠한 게시물도 부착할 수 없다."},{"k":"hang","x":"④ 선거관리위원회는 외부로부터 내부를 볼 수 없도록 기표소를 설비하여야 하며, 기표소 안과 밖에 어떠한 표지도 하여서는 아니 된다."},{"k":"hang","x":"⑤ 다음 각호에 해당하는 사람은 투표소의 설비에 대하여 시정을 요구할 수 있다."},{"k":"ho","x":"1. 각 선거운동본부의 본부장"},{"k":"ho","x":"2. 해당 투표소에 파견된 투표참관인"}],"num":61,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a62","label":"제62조","title":"투표 관리","paras":[{"k":"hang","x":"① 선거관리위원회는 투표소의 투표 업무를 관리ㆍ감독한다."},{"k":"hang","x":"② 투표 시간 동안 모든 투표소에는 1인 이상의 선거관리위원이 배치되어 있어야 한다."}],"num":62,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a63","label":"제63조","title":"투표용지의 구성","paras":[{"k":"hang","x":"① 기표 방법에 따른 투표를 진행하는 경우, 투표용지에는 선거관리위원회, 투표소별 선거관리위원 및 각 선거운동본부에서 파견한 투표참관인의 확인 칸이 있어야 한다."},{"k":"hang","x":"② 기표 방법에 따른 투표를 진행하는 경우, 기표한 것이 전사되어 어느 칸에 기표한 것인지 알 수 없게 되는 것을 방지하기 위하여 선거인이 전사되지 않는 방향으로 접을 수 있도록 투표용지 중간에 점선을 표시하여야 한다."},{"k":"hang","x":"③ 기표 방법에 따른 투표를 진행하는 경우, 기표한 것이 두 칸의 구분선상에 어느 칸에 기표한 것인지를 확정할 수 없는 것을 방지하기 위하여 각 칸 사이의 간격은 기표용구의 지름보다 크게 하여야 한다."},{"k":"hang","x":"④ 동시선거에 있어서 기표 방법에 따른 투표를 진행하는 경우, 선거관리위원회는 선거별 투표용지가 구분되도록 색도 또는 지질 등을 다르게 하는 등의 방법으로 선거의 투표용지를 제작할 수 있다."}],"num":63,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a64","label":"제64조","title":"투표함의 제작","paras":[{"k":"hang","x":"① 선거관리위원회는 자물쇠로 봉인할 수 있도록 투표함을 제작하여야 한다."},{"k":"hang","x":"② 동시선거에 있어서 선거관리위원회는 선거별 투표함이 구분되도록 제작하여야 한다."}],"num":64,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a65","label":"제65조","title":"투표 시작 전 투표함 등 이송","paras":[{"k":"hang","x":"① 선거관리위원회는 매 투표일 8시 30분에 선거관리위원회실에서 선거관리위원과 각 선거운동본부 본부장의 입회하에 모든 투표함의 투입구와 그 자물쇠를 봉쇄하여야 한다."},{"k":"hang","x":"② 선거관리위원회는 매 투표일 9시까지 투표용지의 선거관리위원회 확인 칸에 서명 또는 날인하여 각 투표소로 송부한다."},{"k":"hang","x":"③ 선거관리위원 및 각 선거운동본부에서 파견한 한 명은 다음 각호의 물품을 각 투표소로 이송한다."},{"k":"ho","x":"1. 제1항에 따라 봉쇄된 투표함"},{"k":"ho","x":"2. 제2항에 따라 선거관리위원회의 서명 또는 날인된 투표용지"},{"k":"ho","x":"3. 선거인 명부"},{"k":"ho","x":"4. 참관 시간 기록표"},{"k":"ho","x":"5. 그 밖의 투표에 필요한 제반 물품"},{"k":"hang","x":"④ 투표함을 봉인한 자물쇠의 열쇠는 선거관리위원장이 보관한다."},{"k":"hang","x":"⑤ 선거관리위원은 담당하는 투표소에 투표용지가 추가로 필요할 경우 선거관리위원회에서 투표용지를 추가로 받을 수 있다."}],"num":65,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a66","label":"제66조","title":"투표 절차","paras":[{"k":"line","x":"투표용지 수령 및 기표 절차는 다음 각호의 순서에 따른다."},{"k":"ho","x":"1. 선거관리위원의 본인 확인"},{"k":"ho","x":"2. 선거인 명부 확인"},{"k":"ho","x":"3. 투표자의 서명"},{"k":"ho","x":"4. 선거관리위원 및 선거운동본부별 투표참관인의 투표용지 확인"},{"k":"ho","x":"5. 투표용지 배부"},{"k":"ho","x":"6. 기표 및 투표"}],"num":66,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a67","label":"제67조","title":"본인 확인","paras":[{"k":"hang","x":"① 선거인은 투표소에 가서 투표참관인의 참관하에 신분증을 제시하고 본인임을 확인받은 후 선거인 명부에 서명하고 투표용지를 받아야 한다. 선거인 명부를 전자적으로 운영하는 경우 선거관리위원회는 주민등록번호의 입력 또는 그 밖의 서명을 대신할 본인 확인 방법을 시행할 수 있다."},{"k":"hang","x":"② 제1항의 신분증은 학생증을 원칙으로 한다. 단, 선거관리위원회는 관공서 또는 공공기관이 발행한 증명서로서 사진이 붙어있어 본인임을 확인할 수 있는 신분증 중 일부를 신분증으로 대신 사용하도록 할 수 있다."},{"k":"hang","x":"③ 선거관리위원은 신분증을 제시하지 아니한 선거인에게 투표용지를 교부하여서는 아니 된다."}],"num":67,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a68","label":"제68조","title":"투표용지 배부","paras":[{"k":"hang","x":"① 선거관리위원과 투표참관인은 선거인의 본인 확인을 마치면 투표용지를 확인하여 확인 칸에 서명 또는 날인한 후 투표용지를 교부하되, 필요하다고 인정되는 때에는 50장 이내의 범위 내에서 투표용지의 확인 칸에 미리 서명 또는 날인한 후 이를 교부할 수 있다."},{"k":"hang","x":"② 제1항에도 불구하고 특정 선거운동본부가 투표참관인을 파견하지 않은 투표소는 해당 선거운동본부의 투표참관인 확인 칸을 빈칸으로 하여 교부한다."},{"k":"hang","x":"③ 동시선거에 있어서 각 투표소의 선거관리위원은 선거인이 선거권을 가진 선거에 해당하는 투표용지를 모두 교부한다."},{"k":"hang","x":"④ 투표용지를 교부받은 후 그 선거인의 책임으로 훼손되면 다시 이를 교부하지 아니한다."}],"num":68,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a69","label":"제69조","title":"기표ㆍ투표","paras":[{"k":"hang","x":"① 선거인은 투표용지를 받은 후 기표소에 들어가 준비된 기표 도구로 투표용지의 본인 의사와 일치하는 칸에 기표한 후, 그 자리에서 기표 내용이 다른 사람에게 보이지 않게 접어 선거관리위원과 투표참관인이 지켜보는 가운데 투표함에 집어넣어야 한다."},{"k":"hang","x":"② 동일한 기표소 안에 두 명 이상이 동시에 들어갈 수 없다. 단, 시각 또는 신체의 장애로 인하여 본인이 기표할 수 없는 선거인은 본인이 지명한 두 명 이하의 사람을 동반하여 투표를 보조하게 할 수 있다."},{"k":"hang","x":"③ 선거인은 자신이 기표한 투표용지를 공개할 수 없으며, 공개된 투표용지는 무효로 한다."}],"num":69,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a70","label":"제70조","title":"투표참관인","paras":[{"k":"hang","x":"① 투표참관인은 각 선거운동본부가 투표 진행을 감독하기 위하여 각 투표소에 배치한 자를 말한다."},{"k":"hang","x":"② 선거관리위원은 투표참관인이 투표용지의 교부 상황과 투표 상황을 참관하게 하여야 한다."},{"k":"hang","x":"③ 각 선거운동본부는 투표참관인을 투표 시작일 전까지 선거관리위원회에 등록하여야 한다."},{"k":"hang","x":"④ 각 선거운동본부는 투표소별로 참관인 한 명을 배치할 수 있으며, 교체할 수 있다."},{"k":"hang","x":"⑤ 투표참관인은 투표소에 비치된 참관 시간 기록표의 소속 선거운동본부 항목에 이름, 참관을 시작한 시각 및 참관을 종료한 시각을 기재하여야 한다."}],"num":70,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a71","label":"제71조","title":"투표참관인의 이의신청","paras":[{"k":"hang","x":"① 투표참관인은 제97조 제2항에 따라 소속 선거운동본부의 본부장을 대신하여 투표 상황에 관한 이의신청을 할 수 있다."},{"k":"hang","x":"② 선거관리위원은 담당하는 투표소에서 제1항에 따른 이의신청이 있으면, 선거관리위원회가 이를 처리할 때까지 해당 투표소의 투표 진행을 중지한다."},{"k":"hang","x":"③ 투표참관인을 파견한 선거운동본부는 해당 투표참관인의 이의신청을 철회할 수 없다."},{"k":"hang","x":"④ 투표참관인은 이의신청 여부를 판단할 수 없는 때에 소속 선거운동본부의 본부장을 해당 투표소에 입회시켜 판단하도록 할 수 있다."},{"k":"hang","x":"⑤ 투표참관인은 투표소 안에서 사고가 발생한 때에는 투표 상황을 촬영할 수 있다."}],"num":71,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a72","label":"제72조","title":"투표참관인의 부정행위","paras":[{"k":"hang","x":"① 투표참관인은 투표소에서 다음 각호의 행위를 할 수 없다."},{"k":"ho","x":"1. 투표 방해 행위 및 소란 행위"},{"k":"ho","x":"2. 특정 후보ㆍ선거운동본부의 선전 물품 소지 및 선전 발언 등 선거운동 행위"},{"k":"ho","x":"3. 투표에 간섭하거나 투표를 권유하는 행위"},{"k":"ho","x":"4. 그 밖의 선거관리위원회가 부정행위로 인정한 행위"},{"k":"hang","x":"② 제54조 제2항에 따라 선거관리위원회의 허가를 받은 선거운동본부복의 착용은 제1항 제2호에 해당하지 아니한다."},{"k":"hang","x":"③ 선거관리위원은 투표참관인이 투표소에서 ｢고려대학교 자유전공학부 학생회칙｣ 및 본 세칙에 반하는 부정행위를 할 때 해당 투표참관인의 퇴장을 명할 수 있으며, 이때 선거관리위원회는 해당 투표참관인이 속한 선거운동본부에 주의 1회를 줄 수 있다."}],"num":72,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a73","label":"제73조","title":"투표소에서의 질서 유지","paras":[{"k":"line","x":"선거관리위원은 투표소의 질서가 심히 문란하여 공정한 투표가 시행될 수 없다고 인정되는 때에는 투표소의 질서를 유지하기 위하여 투표를 중단하거나 관련된 자의 퇴장을 명할 수 있다."}],"num":73,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a74","label":"제74조","title":"후보자의 투표 권유 행위","paras":[{"k":"line","x":"후보자는 선거관리위원회가 허용하는 범위 내에서 투표소에서 투표를 권유하는 발언을 할 수 있다. 단, 후보자가 투표참관인이면 그러하지 아니한다."}],"num":74,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a75","label":"제75조","title":"투표 종료 시 투표함 등 이송","paras":[{"k":"hang","x":"① 매 투표일 투표가 종료된 후 선거관리위원은 투표참관인의 참관하에 투표함의 투입구와 그 자물쇠를 봉쇄 후 날인하여야 한다."},{"k":"hang","x":"② 선거관리위원은 투표함의 이송 전에 해당 투표소의 투표참관인에게 투표함에 이상이 없음을 서면으로 확인받는다."},{"k":"hang","x":"③ 선거관리위원 및 각 선거운동본부의 투표참관인은 다음 각호의 물품을 선거관리위원회실로 이송한다."},{"k":"ho","x":"1. 제1항에 따라 봉쇄된 투표함"},{"k":"ho","x":"2. 남은 투표용지"},{"k":"ho","x":"3. 선거인 명부"},{"k":"ho","x":"4. 참관 시간 기록표"},{"k":"ho","x":"5. 그 밖의 투표에 필요한 제반 물품"}],"num":75,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a76","label":"제76조","title":"투표함 등 확인","paras":[{"k":"line","x":"선거관리위원장은 제75조 제3항에 따라 이송된 투표함, 남은 투표용지, 선거인 명부 및 참관 시간 기록표 등을 인수하여 지체 없이 이상이 있는지 확인한다."}],"num":76,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a77","label":"제77조","title":"투표함 보관","paras":[{"k":"line","x":"각 투표소의 투표함은 매 투표일 투표가 종료된 후 선거관리위원회실에 보관한다. 단, 선거관리위원회실이 투표함의 보관에 적당하지 않다고 인정되면 선거관리위원회와 각 선거운동본부 본부장의 합의로 투표함 보관 장소를 변경할 수 있다."}],"num":77,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제9장 투표 성립"},{"t":"art","id":"a78","label":"제78조","title":"투표 성립 요건","paras":[{"k":"line","x":"선거는 제9조에 따라 결정된 선거권자 총수 4분의 1 이상의 투표로 성립한다."}],"num":78,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제10장 개표"},{"t":"art","id":"a79","label":"제79조","title":"개표관리","paras":[{"k":"hang","x":"① 개표는 선거관리위원만이 할 수 있다."},{"k":"hang","x":"② 개표는 개표소에 선거관리위원회 재적 위원 과반수가 참석한 상태에서만 진행할 수 있다."}],"num":79,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a80","label":"제80조","title":"개표장","paras":[{"k":"line","x":"선거관리위원회는 학교 내의 공개된 장소를 개표장으로 정한다."}],"num":80,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a81","label":"제81조","title":"개표소","paras":[{"k":"hang","x":"① 개표소는 선거관리위원이 개표하는 장소를 말한다."},{"k":"hang","x":"② 개표소는 개표장 내에서 방청객과 일정한 거리를 유지하는 위치에 설치하여야 한다."},{"k":"hang","x":"③ 개표소에는 선거관리위원과 각 선거운동본부가 파견한 개표참관인만이 출입할 수 있다."}],"num":81,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a82","label":"제82조","title":"개표 시작 시 투표함 이송","paras":[{"k":"line","x":"기표 방법에 따른 투표를 병행한 경우, 선거관리위원은 투표함을 투입구와 그 자물쇠가 봉쇄된 채로 개표소로 이송한다."}],"num":82,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a83","label":"제83조","title":"개표 절차","paras":[{"k":"hang","x":"① 개표는 투표소별로 구분하여 투표수를 계산한다."},{"k":"hang","x":"② 개표 절차는 다음 각호의 순서에 따른다. 단, 기표 방법에 따른 투표를 병행하지 아니하였으면 제2호부터 제6호까지의 절차를 생략할 수 있다."},{"k":"ho","x":"1. 총 투표자 수 공고"},{"k":"ho","x":"2. 투표소별 투표함 개봉 및 개표"},{"k":"ho","x":"3. 개표참관인의 재확인 및 득표의 검산"},{"k":"ho","x":"4. 후보별 득표를 묶음별로 분류하여 투표함에 재투입"},{"k":"ho","x":"5. 후보별 득표 공고 및 현황판에 결과 기재"},{"k":"ho","x":"6. 제2호부터 제5호의 과정을 투표소별로 반복"},{"k":"ho","x":"7. 전자투표의 결과 확인"},{"k":"ho","x":"8. 후보별 득표 공고 및 현황판에 결과 기재"},{"k":"ho","x":"9. 현황판에 기재된 상황과 선거인 명부상 투표자 수를 비교하여 오차율 계산"},{"k":"ho","x":"10. 최종 결과 발표"}],"num":83,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a84","label":"제84조","title":"투표용지의 무효 처리","paras":[{"k":"hang","x":"① 다음 각호의 어느 하나에 해당하는 투표는 무효로 한다."},{"k":"ho","x":"1. 어느 칸에도 기표하지 아니한 것"},{"k":"ho","x":"2. 두 개 이상의 칸에 기표한 것"},{"k":"ho","x":"3. 어느 칸에 기표한 것인지 식별할 수 없는 것"},{"k":"ho","x":"4. 정해진 기표용구가 아닌 용구를 사용하여 기표한 것"},{"k":"ho","x":"5. 투표용지에 선거관리위원의 서명ㆍ날인이 없는 것"},{"k":"hang","x":"② 제1항에도 불구하고 다음 각호의 어느 하나에 해당하는 투표는 무효로 하지 아니한다."},{"k":"ho","x":"1. 기표한 것이 일부분 표시되거나 기표한 것의 안이 메워진 것으로서 정해진 기표용구를 사용하여 기표한 것이 명확한 것"},{"k":"ho","x":"2. 한 후보자 칸에만 두 번 이상 기표한 것"},{"k":"ho","x":"3. 후보자 칸 외에 추가 기표하였으나 그 기표가 어느 후보자에게도 기표한 것으로 볼 수 없는 것"},{"k":"ho","x":"4. 두 후보자 칸의 구분선상에 기표한 것으로서 어느 후보자에게 기표한 것인지가 명확한 것"},{"k":"ho","x":"5. 기표한 것이 전사된 것으로서 어느 후보자에게 기표한 것인지가 명확한 것"},{"k":"ho","x":"6. 훼손되었으나 정규의 투표용지임이 명백하고 어느 후보자에게 기표한 것인지가 명확한 것"},{"k":"ho","x":"7. 해당 선거에 출마한 후보가 두 조 이상일 때 투표 기간 중 후보 자격이 박탈된 후보자에게 기표한 것"},{"k":"hang","x":"③ 기표 방법에 따른 투표에 있어서, 정해진 투표용지를 사용하지 아니한 것은 투표용지로 보지 아니하고 따라서 무효표로도 보지 아니한다."}],"num":84,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a85","label":"제85조","title":"투표함의 무효 처리","paras":[{"k":"hang","x":"① 한 투표소의 명부상 투표자 수와 투표함의 투표용지 수의 차이(이하 “오차”라 한다)가 명부상 투표자 수 대비 3%를 넘을 때 해당 투표함의 결과는 무효가 되며, 해당 투표함의 투표용지 수만큼 무효표로 산입한다. 단, 명부상 투표자 수가 100 이하일 때 오차는 3까지 허용한다."},{"k":"hang","x":"② 모든 투표소의 명부상 투표자 수 총합과 모든 투표함의 투표용지 수 총합의 차이(이하 “총오차”라 한다)가 명부상 총 투표자 수 대비 3%를 넘을 때 투표는 무효가 된다."}],"num":85,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a86","label":"제86조","title":"투표 효력에 관한 이의의 결정","paras":[{"k":"hang","x":"① 선거관리위원회는 투표의 효력에 관하여 이의가 있는 때에는 재적 위원 과반수의 출석과 출석 위원 과반수의 찬성으로 투표의 효력을 결정한다."},{"k":"hang","x":"② 투표의 효력을 결정함에 있어서는 선거인의 의사가 존중되어야 한다."}],"num":86,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a87","label":"제87조","title":"후보자ㆍ선거운동본부장의 개표장 출석 의무","paras":[{"k":"line","x":"각 선거운동본부의 후보자와 선거운동본부장은 개표 시작 시각까지 개표장에 도착하여야 하며, 개표가 종료되는 때까지 개표 현장에 있어야 한다."}],"num":87,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a88","label":"제88조","title":"개표참관인","paras":[{"k":"hang","x":"① 개표참관인은 각 선거운동본부가 개표 진행을 감독하기 위하여 개표소에 배치한 자를 말한다."},{"k":"hang","x":"② 개표참관인은 개표 상황을 참관하고, 득표를 검산하는 등의 역할을 수행한다."},{"k":"hang","x":"③ 각 선거운동본부는 개표 시작일 전까지 개표참관인 두 명을 선정하여 선거관리위원회에 통보하여야 한다."},{"k":"hang","x":"④ 개표참관인은 개표 시작 시각 전까지 개표장에 도착하여야 한다."},{"k":"hang","x":"⑤ 개표참관인의 교체는 선거관리위원장의 허가가 있어야 할 수 있다."}],"num":88,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a89","label":"제89조","title":"개표장에서의 질서 유지","paras":[{"k":"line","x":"선거관리위원은 개표소의 질서가 심히 문란하여 공정한 개표가 시행될 수 없다고 인정되는 때에는 개표소의 질서를 유지하기 위하여 개표를 중단하거나 관련된 자의 퇴장을 명할 수 있다."}],"num":89,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a90","label":"제90조","title":"투표용지ㆍ선거인 명부 등의 보관","paras":[{"k":"line","x":"선거관리위원회는 투표함ㆍ투표용지ㆍ선거인 명부 등 선거에 관한 모든 자료를 제92조의 개표 결과 공고 후 48시간 동안 보관하여야 한다."}],"num":90,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제11장 당선"},{"t":"art","id":"a91","label":"제91조","title":"당선의 기준","paras":[{"k":"hang","x":"① 하나의 선거에 등록한 후보가 두 조 이상이면 개표 결과 유효투표 중 최다 득표 조를 당선으로 본다. 단, 투표 기간 중 후보 자격이 박탈된 조가 최다 득표하였으면 당선 조는 없는 것으로 본다."},{"k":"hang","x":"② 하나의 선거에 등록한 후보가 한 조이면 유효투표 중 “찬성” 표의 수가 “반대”와 “기권” 표의 수의 합보다 많은 경우 그 조를 당선으로 본다."},{"k":"hang","x":"③ 다음 각호 중 어느 하나에 해당하면 당선 조를 확정할 수 없으며, 제94조 또는 제95조에 따라 재투표 또는 결선투표를 시행한다."},{"k":"ho","x":"1. 총오차가 명부상 총 투표자 수 대비 3%를 넘은 경우"},{"k":"ho","x":"2. “찬성” 표의 수와 “반대” 및 “기권” 표의 수의 합 간의 차이가 총오차보다 적은 경우"},{"k":"ho","x":"3. 최고 득표 조가 두 조 이상인 경우"},{"k":"ho","x":"4. 1위 득표 조와의 득표 차이가 총오차보다 적은 조가 있는 경우"},{"k":"hang","x":"④ 제3항에도 불구하고 제3항 제3호 및 제4호에 해당하는 조 중에서 한 조를 제외한 나머지 조가 투표 기간 중 후보 자격이 박탈된 때에는 후보 자격이 박탈되지 않은 후보가 당선된 것으로 본다."},{"k":"hang","x":"⑤ 다음 각호 중 어느 하나에 해당하면 당선 조는 없는 것으로 보며, 제96조에 따라 재선거를 시행한다."},{"k":"ho","x":"1. “지지 선본 없음” 칸에 기표한 사람의 수가 1위 득표 조 기표한 사람의 수보다 많은 경우"},{"k":"ho","x":"2. “찬성” 표의 수가 “반대”와 “기권” 표의 수의 합을 넘지 않는 경우"}],"num":91,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a92","label":"제92조","title":"개표 결과 공고","paras":[{"k":"hang","x":"① 선거관리위원장은 개표가 완료되면 지체 없이 그 결과를 공고하고, 공고한 때로부터 48시간 동안 이의신청을 받는다."},{"k":"hang","x":"② 개표 결과 공고에는 다음 각호가 명시되어야 한다."},{"k":"ho","x":"1. 총 투표자 수와 최종 투표율"},{"k":"ho","x":"2. 각 선거운동본부의 투표소별 득표수, 총득표수 및 득표율을 포함한 투표 결과"},{"k":"ho","x":"3. 제91조에 따른 선거 결과"},{"k":"hang","x":"③ 제1항에 따른 이의신청에 관한 자세한 사항은 제97조부터 제99조까지를 따른다."}],"num":92,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a93","label":"제93조","title":"당선 공고","paras":[{"k":"hang","x":"① 당선 조가 있는 경우, 선거관리위원회는 제92조의 개표 결과 공고로부터 48시간 이내에 이의신청이 없으면 당선 조의 당선 확정을 공고한다."},{"k":"hang","x":"② 당선 조가 있는 경우로서 선거관리위원회는 개표 결과 공고로부터 48시간 이내에 이의신청이 있으면 다음 각호에 따른다."},{"k":"ho","x":"1. 이의신청이 개표 결과 공고로부터 48시간 이내에 기각된 경우, 공고로부터 48시간이 지난 시점에 당선 조의 당선 확정을 공고한다."},{"k":"ho","x":"2. 이의신청이 개표 결과 공고로부터 48시간 이후에 기각된 경우, 그 즉시 당선 조의 당선 확정을 공고한다."},{"k":"ho","x":"3. 이의신청이 인용된 경우, 지체 없이 그에 따른 후속 선거 절차를 결정하고 이를 공고한다."},{"k":"hang","x":"③ 이의신청이 둘 이상 제기된 경우, 마지막으로 이의신청이 기각된 시점을 기준으로 제2항을 적용한다."},{"k":"hang","x":"④ 당선 확정 공고에는 다음 각호가 명시되어야 한다."},{"k":"ho","x":"1. 학생회장ㆍ부학생회장 당선인의 이름, 소속 학부ㆍ학과, 반, 학번"},{"k":"ho","x":"2. 학생회장ㆍ부학생회장 당선인의 선거운동본부명"},{"k":"ho","x":"3. 총 투표자 수와 최종 투표율"},{"k":"ho","x":"4. 각 선거운동본부의 투표소별 득표수, 총득표수 및 득표율을 포함한 투표 결과"}],"num":93,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제12장 재투표ㆍ결선투표 및 재선거"},{"t":"art","id":"a94","label":"제94조","title":"재투표","paras":[{"k":"hang","x":"① 다음 각호 중 어느 하나에 해당하면 재투표를 시행한다."},{"k":"ho","x":"1. 총오차가 명부상 총 투표자 수 대비 3%를 넘은 경우"},{"k":"ho","x":"2. “찬성” 표의 수와 “반대” 및 “기권” 표의 수의 합 간의 차이가 총오차보다 적은 경우"},{"k":"ho","x":"3. 투표 기간 중 후보 자격이 박탈된 후보자의 선거운동본부에 관한 이의신청이 인용되어 투표에 문제가 생긴 경우"},{"k":"hang","x":"② 재투표는 제1항의 상황이 발생하고 7일 이내에 이틀에 걸쳐 선거운동 없이 시행한다."},{"k":"hang","x":"③ 제2항에 따라 재투표를 시행할 때, 하나의 선거에 등록한 후보가 두 조 이상이면 투표율에 상관없이 득표수가 많은 후보를 당선 조로 한다."},{"k":"hang","x":"④ 제2항에 따라 재투표를 시행할 때, 하나의 선거에 등록한 후보가 한 조이면 투표율에 상관없이 “찬성” 표의 수가 “반대”와 “기권” 표의 수의 합보다 많은 경우 당선으로 한다."}],"num":94,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a95","label":"제95조","title":"결선투표","paras":[{"k":"hang","x":"① 다음 각호 중 어느 하나에 해당하면, 이에 해당하는 조들로 하여 결선투표를 시행한다."},{"k":"ho","x":"1. 최고 득표 조가 두 조 이상인 경우"},{"k":"ho","x":"2. 1위 득표 조와의 득표 차이가 총오차보다 적은 조가 있는 경우"},{"k":"hang","x":"② 결선투표는 제1항의 상황이 발생하고 7일 이내에 이틀에 걸쳐 선거운동 없이 시행한다."},{"k":"hang","x":"③ 제2항에 따라 결선투표를 시행할 때, 하나의 선거에 등록한 후보가 두 조 이상이면 투표율에 상관없이 득표수가 많은 후보를 당선 조로 한다."},{"k":"hang","x":"④ 제2항에 따라 결선투표를 시행할 때, 하나의 선거에 등록한 후보가 한 조이면 투표율에 상관없이 “찬성” 표의 수가 “반대”와 “기권” 표의 수의 합보다 많은 경우 당선으로 한다."}],"num":95,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a96","label":"제96조","title":"재선거","paras":[{"k":"hang","x":"① 다음 각호 중 어느 하나에 해당하면 재선거를 시행한다."},{"k":"ho","x":"1. ｢고려대학교 자유전공학부 학생회칙｣ 제174조 제1항의 사유가 발생한 경우"},{"k":"ho","x":"2. 투표율이 제78조의 투표 성립 요건을 넘지 않은 경우"},{"k":"ho","x":"3. 재투표에서도 총오차가 명부상 총 투표자 수 대비 3%를 넘은 경우"},{"k":"ho","x":"4. 재투표에서도 “찬성” 표의 수와 “반대”와 “기권” 표의 수의 합 간의 차이가 총오차보다 적은 경우"},{"k":"ho","x":"5. “지지 선본 없음” 칸에 기표한 사람의 수가 1위 득표 조에 기표한 사람의 수보다 많은 경우"},{"k":"ho","x":"6. “찬성” 표의 수가 “반대”와 “기권” 표의 수의 합을 넘지 않는 경우"},{"k":"hang","x":"② 재선거에 관한 자세한 일정은 학부운영위원회 또는 비상대책위원회에서 정한다."}],"num":96,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제13장 이의신청"},{"t":"art","id":"a97","label":"제97조","title":"이의신청의 방식","paras":[{"k":"hang","x":"① 선거에 관한 이의신청은 다음 각호에 따라 진행할 수 있다."},{"k":"ho","x":"1. 각 선거운동본부의 후보자 또는 본부장의 명의로 작성된 서면을 통한 이의신청"},{"k":"ho","x":"2. 본회의 회원 20명의 연서를 통한 이의신청"},{"k":"hang","x":"② 투표에 관하여서는 해당 투표소에 파견된 투표참관인이 후보자 또는 선거운동본부장을 대신하여 구두로 이의신청을 할 수 있다. 이때 해당 선거운동본부는 24시간 이내에 해당 이의신청 내용을 제1항 제1호에 따라 다시 제출하여야 한다."},{"k":"hang","x":"③ 개표에 관하여서는 후보자 또는 선거운동본부장이 구두로 이의신청을 할 수 있다. 이때 해당 선거운동본부는 24시간 이내에 해당 이의신청 내용을 제1항 제1호에 따라 다시 제출하여야 한다."},{"k":"hang","x":"④ 선거관리위원회는 제1항부터 제3항까지 중 어느 하나를 위반한 선거운동본부에 시정명령 1회를 준다."}],"num":97,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a98","label":"제98조","title":"이의신청의 처리","paras":[{"k":"hang","x":"① 선거관리위원장은 제97조에 따른 이의신청이 있으면 지체 없이 회의를 소집하여 이를 처리한다."},{"k":"hang","x":"② 선거관리위원회는 재적 위원 과반수의 출석과 출석 위원 과반수의 찬성으로 이의신청을 인용(認容)한다."}],"num":98,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a99","label":"제99조","title":"일사부재리","paras":[{"k":"hang","x":"① 이의신청에 관하여 선거관리위원회의 의결로 기각 또는 인용이 확정된 경우, 그와 동일한 사실 및 동일한 증거에 따라 다시 이의신청을 진행할 수 없다."},{"k":"hang","x":"② 다음 각호 중 어느 하나에 해당하면 제1항의 적용을 받지 아니한다."},{"k":"ho","x":"1. 이의신청에 관하여 제97조 제4항에 따라 시정명령을 받은 경우"},{"k":"ho","x":"2. 선거관리위원회의 이의신청 심의 과정에서 중대한 절차상 하자가 있었음이 확인된 경우"}],"num":99,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제14장 벌칙"},{"t":"art","id":"a100","label":"제100조","title":"정의","paras":[{"k":"line","x":"본 세칙에서 “벌칙”이란 선거운동본부가 본 세칙에 명시된 벌칙 사유에 해당하는 행위를 하였거나, 선거관리위원회가 벌칙 사유로 결정한 행위를 한 경우, 선거관리위원회의 심의를 거쳐 해당 선거운동본부에 제재를 가하는 것을 말한다."}],"num":100,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a101","label":"제101조","title":"벌칙의 종류","paras":[{"k":"line","x":"벌칙의 종류는 다음 각호와 같다."},{"k":"ho","x":"1. 시정명령"},{"k":"ho","x":"2. 주의"},{"k":"ho","x":"3. 경고"}],"num":101,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a102","label":"제102조","title":"벌칙의 적용과 후보 자격 박탈","paras":[{"k":"hang","x":"① 동일한 내용으로 시정명령이 2회 누적되면 제106조에 따른 벌칙의 의결이 없어도 주의 1회를 받은 것으로 한다. 이때 해당 시정명령 2회는 소멸한다."},{"k":"hang","x":"② 주의가 2회 누적되면 제106조에 따른 벌칙의 의결이 없어도 경고 1회를 받은 것으로 한다. 이때 해당 주의 2회는 소멸한다."},{"k":"hang","x":"③ 경고가 3회 이상 누적되면 해당 선거운동본부의 학생회장ㆍ부학생회장 후보자의 후보 자격을 박탈한다."}],"num":102,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a103","label":"제103조","title":"시정명령","paras":[{"k":"hang","x":"① 선거운동본부가 다음 각호 중 어느 하나에 해당하는 행위를 하면 선거관리위원회는 해당 선거운동본부에 시정명령을 구두로 통보한다."},{"k":"ho","x":"1. 제29조 제1항의 선거운동본부원 모집을 위한 공고문에 결함이 있는 경우"},{"k":"ho","x":"2. 제30조 제3항의 선거운동본부원으로 등록되지 아니한 자가 그 구성원으로 활동한 경우"},{"k":"ho","x":"3. 제31조 제1항의 선거운동본부원으로 등록할 수 없는 자가 등록한 경우"},{"k":"ho","x":"4. 제31조 제4항의 여러 선거운동본부에 중복으로 등록된 자가 있는 경우"},{"k":"ho","x":"5. 제32조 제4항의 선거운동본부장의 교체 신청에 결함이 있는 경우"},{"k":"ho","x":"6. 제42조 제3항의 선거운동본부원의 구성원이 아닌 자가 그 소속 후보자를 위한 선거운동을 한 경우"},{"k":"ho","x":"7. 제47조 제3항의 게시물ㆍ유인물의 사전 허가를 위한 회의 결과 규격이 맞지 않은 경우"},{"k":"ho","x":"8. 제97조의 이의신청 관련 규정을 위반한 경우"},{"k":"ho","x":"9. 그 밖의 선거 진행에 큰 지장을 주지는 않으나, 본 세칙 및 규칙을 위반한 것이 분명한 경우"},{"k":"hang","x":"② 선거운동본부는 시정명령의 대상이 된 내용을 시정하여 다시 제출하거나 심의를 받을 수 있다."}],"num":103,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a104","label":"제104조","title":"주의","paras":[{"k":"line","x":"선거운동본부가 다음 각호 중 어느 하나에 해당하는 행위를 하면 선거관리위원회는 해당 선거운동본부에 주의를 줄 수 있다. 이때 선거관리위원회는 이를 구두로 통보하고, 그 사실을 공고한다."},{"k":"ho","x":"1. 선거운동본부가 시정명령을 받은 후 2시간 이내에 대상이 된 내용을 시정하지 않은 경우(단, 제103조 제1항 제1호, 제5호, 제7호 및 제8호는 그러하지 아니한다)"},{"k":"ho","x":"2. 제102조 제1항에 따라 동일한 내용으로 시정명령을 두 번 받은 경우"},{"k":"ho","x":"3. 제29조 제5항의 선거관리위원회의 허가를 받지 않은 선거운동본부원의 모집 공고문을 게시한 경우"},{"k":"ho","x":"4. 제31조 제5항의 선거운동본부원으로 등록할 의사가 없는 자를 강제로 등록한 경우"},{"k":"ho","x":"5. 제36조 제4항의 후보 등록 신청 시 제출한 서류ㆍ파일에 결함이 있는 경우"},{"k":"ho","x":"6. 제37조 제6항의 선거운동본부장이 규칙확정회의에 참여하지 않은 경우"},{"k":"ho","x":"7. 제45조 제1항의 선거운동을 할 수 없는 자로 규정된 자가 선거운동을 하는 경우"},{"k":"ho","x":"8. 제47조 제5항의 게시물ㆍ유인물의 사전 허가를 위한 회의 결과 타 후보에 대한 비방 등 선거의 공정성을 해칠 수 있는 내용이 있는 경우"},{"k":"ho","x":"9. 제48조 제3항의 대자보와 포스터의 크기와 개수 규정을 위반한 경우"},{"k":"ho","x":"10. 제48조 제4항의 게시물의 게시 장소 규정을 위반한 경우"},{"k":"ho","x":"11. 제49조 제3항의 유인물 크기 규정을 위반한 경우"},{"k":"ho","x":"12. 제49조 제4항의 유인물 부수 규정을 위반한 경우"},{"k":"ho","x":"13. 제50조 제2항의 개인유세 가능 시간을 위반한 경우"},{"k":"ho","x":"14. 제50조 제3항 또는 제4항의 개인유세 제한 사항을 위반한 경우"},{"k":"ho","x":"15. 제51조 제5항부터 제8항까지 중 어느 하나의 합동유세 규제 사항을 위반한 경우"},{"k":"ho","x":"16. 제52조 제4항의 공청회 시작 10분 전까지 후보자가 현장에 도착하지 않은 경우"},{"k":"ho","x":"17. 제53조 제6항의 보고 받은 아이디 이외의 아이디를 사용하여 선거 관련 의사 표현을 한 경우"},{"k":"ho","x":"18. 제54조 제3항의 선거운동본부복의 사전 허가를 위한 심의 결과 타 후보에 대한 비방 등 선거의 공정성을 해칠 수 있는 내용이 있는 경우"},{"k":"ho","x":"19. 제72조 제3항에 따른 투표참관인의 부정행위가 있는 경우"},{"k":"ho","x":"20. 그 밖의 선거운동본부 행위가 공정한 선거 진행을 해치는 것이 분명한 경우"}],"num":104,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a105","label":"제105조","title":"경고","paras":[{"k":"hang","x":"① 선거운동본부가 다음 각호 중 어느 하나에 해당하는 행위를 하면 선거관리위원회는 해당 선거운동본부에 경고를 줄 수 있다. 이때 선거관리위원회는 이를 구두로 통보하고, 그 사실을 공고한다."},{"k":"ho","x":"1. 선거운동본부가 주의를 받은 후 2시간 이내에 대상이 된 내용을 시정하지 않은 경우"},{"k":"ho","x":"2. 선거운동본부가 경고를 받은 후 12시간 이내에 공개 사과문을 게시하지 않은 경우"},{"k":"ho","x":"3. 제102조 제2항에 따라 주의가 2회 누적된 경우"},{"k":"ho","x":"4. 제44조 제1항의 선거운동 기간이 아닌 때에 선거운동을 하는 경우"},{"k":"ho","x":"5. 제47조 제6항의 사전 허가를 받지 않은 게시물ㆍ유인물을 게시ㆍ배포한 경우"},{"k":"ho","x":"6. 제53조 제5항의 허용된 인터넷 공간이 아닌 곳에서 선거 관련 의사 표현을 한 경우"},{"k":"ho","x":"7. 제54조 제4항의 사전 허가를 받지 않은 선거운동본부복을 착용한 경우"},{"k":"ho","x":"8. 특정 후보자의 당락 또는 선거인의 자유로운 투표 의사에 영향을 미칠 목적으로 선거인, 다른 선거운동본부의 구성원 또는 참관인에게 금전ㆍ물품ㆍ향응 그 밖의 재산상 이익을 제공하거나, 그 제공의 의사를 표시하거나, 그 제공을 약속한 경우"},{"k":"ho","x":"9. 선거에 관하여 다른 선거운동본부의 구성원을 폭행ㆍ협박하거나 선거운동 물품을 탈취한 경우"},{"k":"ho","x":"10. 선거에 관하여 집회ㆍ연설을 방해하거나 그 밖의 부정한 방법으로 선거의 자유를 방해한 경우"},{"k":"ho","x":"11. 정당한 사유 없이 게시물ㆍ현수막 그 밖의 선전시설의 작성ㆍ게시ㆍ부착 또는 설치를 방해하거나 이를 훼손ㆍ철거한 경우"},{"k":"ho","x":"12. 당선되거나 되게 할 목적으로 특정 후보자에게 유리하도록 후보자, 선거운동본부 등에 관하여 허위의 사실을 공표한 경우"},{"k":"ho","x":"13. 당선되지 못하게 할 목적으로 특정 후보자에게 불리하도록 다른 후보자 또는 선거운동본부 등에 관하여 허위의 사실을 공표한 경우"},{"k":"ho","x":"14. 당선되거나 되게 하거나 되지 못하게 할 목적으로 공연히 사실을 적시하여 다른 후보자 또는 선거운동본부를 비방한 경우"},{"k":"ho","x":"15. 그 밖의 선거운동본부 행위가 공정한 선거 진행을 의도적으로 해치거나, 중대한 영향을 주는 것이 분명한 경우"},{"k":"hang","x":"② 경고를 받은 선거운동본부는 선거관리위원회의 경고 공고로부터 12시간 이내에 이에 대한 공개 사과문을 선거관리위원회가 지정한 오프라인 게시판, 온라인 플랫폼 및 해당 선거운동본부의 인터넷 선거운동 공간에 게시한다."}],"num":105,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a106","label":"제106조","title":"벌칙의 의결","paras":[{"k":"hang","x":"① 벌칙은 선거관리위원회 재적 위원 과반수의 출석과 출석 위원 과반수의 찬성으로 의결한다."},{"k":"hang","x":"② 하나의 행위가 여러 개의 벌칙 사유에 해당하면 가장 무거운 벌칙 1회를 준다."},{"k":"hang","x":"③ 본조에도 불구하고 시정명령은 별도의 의결 없이 해당 선거운동본부에 통보할 수 있으며, 다른 벌칙과 함께 줄 수 있다."}],"num":106,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a107","label":"제107조","title":"벌칙의 재심의","paras":[{"k":"hang","x":"① 경고를 받거나, 주의가 2회 누적되어 경고로 전환된 선거운동본부의 후보자 또는 본부장은 선거관리위원회에 해당 경고 또는 경고로 전환되게 한 벌칙에 대하여 재심의를 요구할 수 있다."},{"k":"hang","x":"② 선거관리위원장은 제1항에 따른 재심의 요구가 있으면 지체 없이 회의를 소집하여 이를 심의한다."},{"k":"hang","x":"③ 벌칙의 재심의는 다음 각호 중 어느 하나로 결정하며, 선거관리위원회 재적 위원 과반수의 출석과 출석 위원 과반수의 찬성으로 의결한다."},{"k":"ho","x":"1. 벌칙 유지"},{"k":"ho","x":"2. 벌칙 하향 조정"},{"k":"ho","x":"3. 벌칙 취소"},{"k":"hang","x":"④ 벌칙의 재심의는 하나의 벌칙에 대하여 한 번만 요구할 수 있다."},{"k":"hang","x":"⑤ 벌칙의 재심의는 제97조부터 제99조까지의 적용을 받지 아니한다."}],"num":107,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제15장 선거 기록물 관리"},{"t":"art","id":"a108","label":"제108조","title":"선거 기록물 관리","paras":[{"k":"line","x":"선거에서 생산된 기록물 중 보존의 가치가 있는 것은 선거 일정이 모두 종료된 후 선거관리위원장이 기록물 관리기관으로 이관한다."}],"num":108,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제16장 선거시행규칙"},{"t":"art","id":"a109","label":"제109조","title":"선거시행규칙","paras":[{"k":"hang","x":"① 선거 시행에 관하여 세부적인 사항을 본 세칙에 부수되는 규칙으로 정할 수 있으며, 이를 “선거시행규칙”이라 한다."},{"k":"hang","x":"② 투표관리위원회는 ｢고려대학교 자유전공학부 학생회칙｣ 제48조에 따라 본 세칙을 준용하는 경우 학생총투표 시행에 관하여 세부적인 사항을 규칙으로 정할 수 있으며, 이를 “학생총투표시행규칙”이라 한다. 단, 이에 따라 제정되는 규칙은 해당 학생총투표가 종료될 때까지만 효력이 있다."}],"num":109,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a110","label":"제110조","title":"제정ㆍ개정ㆍ폐지","paras":[{"k":"hang","x":"① 선거시행규칙의 제정안ㆍ개정안ㆍ폐지안은 다음 각호 중 하나에 따라 발의한다."},{"k":"ho","x":"1. 선거관리위원의 발의"},{"k":"ho","x":"2. 제37조의 규칙확정회의에 따른 합의"},{"k":"hang","x":"② 선거관리위원회는 제1항에 따라 발의된 선거시행규칙의 제정ㆍ개정ㆍ폐지를 재적 위원 과반수의 출석과 출석 위원 과반수의 찬성으로 의결한다."},{"k":"hang","x":"③ 제109조 제2항에 따른 학생총투표시행규칙의 제정안ㆍ개정안ㆍ폐지안은 투표관리위원이 발의하고, 투표관리위원회는 해당 규칙의 제정ㆍ개정ㆍ폐지를 재적 위원 과반수의 출석과 출석 위원 과반수의 찬성으로 의결한다."}],"num":110,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"부칙","bu":true,"id":"bu1"},{"t":"art","id":"b1-1","label":"제1조","title":"시행일자","paras":[{"k":"line","x":"본 세칙은 공포 후 48시간 후부터 시행한다."}],"num":1,"sub":null,"bu":true,"bold_title":false}],"note":null}],"current":"seongeo-20250512","title":"선거시행세칙"},{"id":"jachigonggan","cat":"세칙","short":"자치공간운영세칙","versions":[{"id":"jachigonggan-20181012","date":"2018.10.12","kind":"제정","title":"자유전공학부「자치공간운영세칙」","subtitle":null,"history":[["2018. 10. 12.","제정"]],"pdf":"pdf/jachigonggan-20181012.pdf","pdfName":"자유전공학부_자치공간운영세칙(2018.10.12_제정).pdf","blocks":[{"t":"art","id":"a1","label":"제1조","title":"학부 학생회실","paras":[{"k":"hang","x":"① 학부 학생회실은 학생회 사무를 처리하고 학부운영위원회의, 집행위원회의 등을 진행하는 업무 공간이다."},{"k":"hang","x":"② 본회의 기구는 업무와 관련하여 학부 학생회실을 대관하여 이용할 수 있다."},{"k":"hang","x":"③ 학부 학생회장단은 학부 학생회실의 안전 및 청결을 유지할 책임이 있다."},{"k":"hang","x":"④ 학부 학생회실 운영에 관한 자세한 사항은 규칙으로 정한다."}],"num":1,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a2","label":"제2조","title":"반 학생회실","paras":[{"k":"hang","x":"① 반 학생회실은 다음 각호의 목적으로 이용되는 반 학생회의 복합공간이다."},{"k":"ho","x":"1. 반 학생회원 간의 친목 및 교류를 위한 문화 공간"},{"k":"ho","x":"2. 회원들의 휴식 공간"},{"k":"ho","x":"3. 반 학생회 사무처리 및 반 운영위원회의 등을 진행하는 업무 공간"},{"k":"hang","x":"② 반 학생회장단은 반 학생회실의 안전 및 청결을 유지할 책임이 있다."},{"k":"hang","x":"③ 반 학생회실 운영에 관한 자세한 사항은 규칙으로 정한다."}],"num":2,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a3","label":"제3조","title":"자치단체실","paras":[{"k":"hang","x":"① 자치단체실은 자치단체 회원 간의 교류, 자치단체 목적 활동 등 자치단체 활동의 목적상의 필요에 의해 자치단체가 이용하는 공간이다."},{"k":"hang","x":"② 자치단체는 자치단체 회원의 해당 공간이용을 자유롭게 보장하여야 한다."},{"k":"hang","x":"③ 자치단체는 공간을 목적에 맞게 이용하여야 할 의무가 있다."},{"k":"hang","x":"④ 자치단체장은 자치단체실의 안전 및 청결을 유지할 책임이 있다."},{"k":"hang","x":"⑤ 인준받지 못한 자치단체는 자유전공학부 학생회칙 제111조 제3항에 따라 자치공간 반납절차를 이행하여야 한다."}],"num":3,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a4","label":"제4조","title":"밴드연습실","paras":[{"k":"hang","x":"① 밴드연습실은 합주 및 개인 연습 등을 필요로 하는 밴드의 활동 공간이다."},{"k":"hang","x":"② 밴드연습실은 밴드의 동의 없이 재분배 및 회수 결정을 할 수 없다."},{"k":"hang","x":"③ 밴드연습실은 ｢자치공간등기부｣에 별도의 기재를 한다. 단, 자치공간의 밴드연습실 해당 유무에 대해 이견이 있으면 공간배정위원회의 결정에 따른다."}],"num":4,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a5","label":"제5조","title":"학생회 창고","paras":[{"k":"hang","x":"① 학생회 창고는 집행위원회, 반 학생회, 독립기구 등이 자치활동을 위해 자치적으로 관리하고 있는 학생회 자산을 보관 · 유지할 목적으로 이용하는 공간이다."},{"k":"hang","x":"② 학생회 각 기구는 자산을 보관 · 유지할 목적으로 학생회 창고를 이용할 수 있다."}],"num":5,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a6","label":"제6조","title":"사물함보관실","paras":[{"k":"hang","x":"① 본회 회원의 사물함을 보관하고 있는 공간이다."},{"k":"hang","x":"② 학생회 각 기구는 자산을 보관 · 유지할 목적으로 사물함보관실을 이용할 수 있다."}],"num":6,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a7","label":"제7조","title":"안전관리서약서","paras":[{"k":"hang","x":"① 자치단체실을 이용 중인 각 자치단체는 매 학기 안전관리서약서를 집행위원회에 제출하여야 한다."},{"k":"hang","x":"② 안전관리서약서에는 다음 각호에 해당하는 사항이 반드시 포함되어야 한다."},{"k":"ho","x":"1. 화재 안전"},{"k":"ho","x":"2. 위생 안전"}],"num":7,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a8","label":"제8조","title":"안전점검","paras":[{"k":"hang","x":"① 본회 집행위원회에서는 다음 각호에 해당하는 안전점검을 실시하여야 한다."},{"k":"ho","x":"1. 정기 안전점검 : 학기별 1회"},{"k":"ho","x":"2. 비정기 안전점검 : 학부운영위원회의 결정에 따라 상시 실시"},{"k":"hang","x":"② 안전점검의 시행은 총학생회의 절차를 따른다."},{"k":"hang","x":"③ 각 자치공간을 사용하고 있는 단체는 안전점검에 적극 협조하여야 한다."}],"num":8,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a9","label":"제9조","title":"공간자치규약","paras":[{"k":"line","x":"자치공간의 운영에 관한 세부사항은 각 공간별 자치규약을 따른다."}],"num":9,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 공간배정"},{"t":"art","id":"a10","label":"제10조","title":"공간배정","paras":[{"k":"hang","x":"① 자치공간을 새로 확보하여 자치단체로의 배정이 필요하거나 자치단체 간의 공평한 공간 사용을 장려하기 위해 공간의 재분배가 필요한 경우 학부운영위원회는 다음 각호의 방법으로 공간분배를 진행하게 결정할 수 있다."},{"k":"ho","x":"1. 공간배정위원회 개최"},{"k":"ho","x":"2. 자치단체연합회 위임"},{"k":"hang","x":"② 제1항 제1호의 경우 본회 회칙상의 공간배정위원회의 절차에 따라 공간을 배정해야 하며, 제1항 제2호의 경우 자치문제협의회에서 정한 절차를 따른다."}],"num":10,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a11","label":"제11조","title":"공간배정위원회","paras":[{"k":"hang","x":"① 공간배정위원회는 학생대표자회 대의원 전체로 구성한다."},{"k":"hang","x":"② 공간배정위원회의 위원장은 학부 학생회장으로 한다."},{"k":"hang","x":"③ 공간배정위원회는 다음 각호의 사항을 고려하여 합리적 · 공평하게 공간을 배정하여야 한다."},{"k":"ho","x":"1. 자치단체가 하나 이상의 자치공간을 이용하고 있는지"},{"k":"ho","x":"2. 자치단체의 기존 자치공간의 사용에 안전상의 문제가 없는지"},{"k":"ho","x":"3. 자치단체 목적 활동에 자치공간의 유무가 중대한 영향을 미치는지"},{"k":"ho","x":"4. 자치단체 목적 활동 및 자치단체 규모에 자치단체실 크기가 중대한 영향을 미치는지"},{"k":"ho","x":"5. 자치단체가 기존 자치공간을 목적 활동에 맞게 사용하고 있는지"},{"k":"ho","x":"6. 자치단체가 기존 자치공간을 활발하게 이용하고 있는지"},{"k":"hang","x":"④ 공간배정위원회에서 공간 배분은 논의를 통한 배분을 원칙으로 하되, 의견이 첨예하게 갈릴 경우는 표결의 방법으로 공간을 배분한다."},{"k":"hang","x":"⑤ 공간배정위원회는 출석 과반수로 의결한다. 과반수가 성립하지 못할 경우 가장 득표수가 많았던 두 개 안을 두고 재의결을 실시한다."},{"k":"hang","x":"⑥ 그 밖에 회의 진행에 관한 절차는 자유전공학부 학생회칙 제2장 제4절 학생대표자회의 절차를 준용한다."}],"num":11,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"부칙","bu":true,"id":"bu1"},{"t":"free","paras":[{"k":"line","x":"이 세칙은 공포 후 2018년 10월 20일부터 시행한다. (2018. 10. 12. 개정)"}]}],"note":null},{"id":"jachigonggan-20211113","date":"2021.11.13","kind":"전부개정","title":"자유전공학부 「자치공간운영세칙」","subtitle":"[고려대학교 자유전공학부 학생회 세칙 제2호]","history":[["2018. 10. 12.","제정"],["2021. 11. 13.","전부개정"]],"pdf":"pdf/jachigonggan-20211113.pdf","pdfName":"자유전공학부_자치공간운영세칙(2021.11.13_전부개정).pdf","blocks":[{"t":"h","lv":3,"text":"제1절 자치공간"},{"t":"art","id":"a1","label":"제1조","title":"목적","paras":[{"k":"line","x":"본 세칙은 자유전공학부 학생회 각 기구의 자치공간을 대·내외적으로 명확히 하고, 각 자치공간을 민주적이고 원활하게 수호하고 운영하는데 필요한 각 사항을 규정하는 것을 목적으로 한다."}],"num":1,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a2","label":"제2조","title":"학부 학생회실","paras":[{"k":"hang","x":"① 학부 학생회실은 학생회 사무를 처리하고 학부운영위원회의, 집행위원회의 등을 진행하는 업무 공간이다."},{"k":"hang","x":"② 본회의 기구는 업무와 관련하여 학부 학생회실을 대관하여 이용할 수 있다."},{"k":"hang","x":"③ 학부 학생회장단은 학부 학생회실의 안전 및 청결을 유지할 책임이 있다."},{"k":"hang","x":"④ 학부 학생회실 운영에 관한 자세한 사항은 집행위원회가 규칙으로 정한다."}],"num":2,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a3","label":"제3조","title":"반 학생회실","paras":[{"k":"hang","x":"① 반 학생회실은 다음 각호의 목적으로 이용되는 반 학생회의 복합공간이다."},{"k":"ho","x":"1. 반 학생회원 간의 친목 및 교류를 위한 문화 공간"},{"k":"ho","x":"2. 반 학생회원들의 휴식 공간"},{"k":"ho","x":"3. 반 학생회 사무처리 및 반 운영위원회의 등을 진행하는 업무 공간"},{"k":"hang","x":"② 각 반 학생회원은 업무상 목적 외의 사유로 타반 학생회실에 출입하여서는 안 된다."},{"k":"hang","x":"③ 반 학생회장단은 반 학생회실의 안전 및 청결을 유지할 책임이 있다."},{"k":"hang","x":"④ 반 학생회실 운영에 관한 자세한 사항은 각 반 학생회에서 규칙으로 정한다."}],"num":3,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a4","label":"제4조","title":"자치단체실","paras":[{"k":"hang","x":"① 자치단체실은 자치단체 회원 간의 교류, 자치단체 목적 활동 등 자치단체 활동의 목적상의 필요에 의해 자치단체가 이용하는 공간이다."},{"k":"hang","x":"② 자치단체는 자치단체 회원의 자유로운 해당 공간이용을 보장하여야 한다."},{"k":"hang","x":"③ 자치단체는 공간을 목적에 맞게 이용하여야 할 의무가 있다."},{"k":"hang","x":"④ 자치단체장은 자치단체실의 안전 및 청결을 유지할 책임이 있다."},{"k":"hang","x":"⑤ 인준받지 못한 자치단체는 자유전공학부 학생회칙 제111조 제3항에 따라 자치공간 반납절차를 이행하여야 한다."}],"num":4,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a5","label":"제5조","title":"독립기구실","paras":[{"k":"hang","x":"① 독립기구실은 자유전공학부 학생홍보대사, 학생자치장학금위원회, 소수자인권위원회 등의 각 독립기구 회원 간의 교류, 독립기구별 목적 활동 등을 위한 공간이다."},{"k":"hang","x":"② 각 독립기구는 독립기구실을 목적에 맞게 이용하여야 할 의무가 있다."},{"k":"hang","x":"③ 각 독립기구장은 독립기구실의 안전 및 청결을 유지할 책임이 있다."},{"k":"hang","x":"④ 독립기구실의 세부적인 운영 방법에 관해서는 각 독립기구와 학부 학생회장단과의 협의를 통해 결정하여야 한다."}],"num":5,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a6","label":"제6조","title":"밴드연습실","paras":[{"k":"hang","x":"① 밴드연습실은 합주 및 개인 연습 등을 필요로 하는 밴드의 활동 공간이다."},{"k":"hang","x":"② 밴드연습실은 밴드의 동의 없이 재분배 및 회수 결정을 할 수 없다."},{"k":"hang","x":"③ 밴드연습실은 ｢자치공간등기부｣에 별도의 기재를 한다. 단, 자치공간의 밴드연습실 해당 유무에 대해 이견이 있으면 공간배정위원회의 결정에 따른다."}],"num":6,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a7","label":"제7조","title":"학생회 창고","paras":[{"k":"hang","x":"① 학생회 창고는 집행위원회, 반 학생회, 독립기구 등이 자치활동을 위해 자치적으로 관리하고 있는 학생회 자산을 보관 · 유지할 목적으로 이용하는 공간이다."},{"k":"hang","x":"② 학생회 각 기구는 자산을 보관 · 유지할 목적으로 학생회 창고를 이용할 수 있다."}],"num":7,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a8","label":"제8조","title":"코웍스","paras":[{"k":"hang","x":"① 코웍스는 학번·전공·소속 등을 불문하고 본회 회원들 간의 자유로운 교류와 휴식을 위한 공간이다."},{"k":"hang","x":"② 학부 학생회장단과 집행위원회는 코웍스의 안전 및 청결을 유지할 책임이 있다."},{"k":"hang","x":"③ 코웍스 운영에 관한 자세한 사항은 집행위원회가 규칙으로 정한다."}],"num":8,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a9","label":"제9조","title":"안전관리서약서","paras":[{"k":"hang","x":"① 집행위원회는 매 학기 시작 전 안전관리서약서 양식을 각 자치공간을 사용하고 있는 단체의 장에게 배포하여 작성하도록 한다."},{"k":"hang","x":"② 자치공간을 사용하고 있는 각 단체는 매 학기 안전관리서약서를 작성하여 집행위원회에 제출하여야 한다."}],"num":9,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a10","label":"제10조","title":"안전점검","paras":[{"k":"hang","x":"① 본회 집행위원회에서는 다음 각호에 해당하는 안전점검을 실시하여야 한다."},{"k":"ho","x":"1. 정기 안전점검 : 학기별 1회"},{"k":"ho","x":"2. 비정기 안전점검 : 학부운영위원회의 결정에 따라 상시 실시"},{"k":"hang","x":"② 안전점검의 시행은 본 세칙에 부수된 안전점검절차규칙을 따른다."},{"k":"hang","x":"③ 각 자치공간을 사용하고 있는 단체는 안전점검에 적극 협조하여야 한다."}],"num":10,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a11","label":"제11조","title":"공간자치규약","paras":[{"k":"line","x":"자치공간의 운영에 관한 세부사항은 각 공간별 자치규약을 따른다."}],"num":11,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 공간배정"},{"t":"art","id":"a12","label":"제12조","title":"공간배정","paras":[{"k":"line","x":"자치공간을 새로 확보하여 자치단체로의 배정이 필요하거나 자치단체 간의 공평한 공간 사용을 장려하기 위해 공간의 재분배가 필요한 경우 학부운영위원회는 공간배정위원회를 개최하여 공간분배를 결정할 수 있다."}],"num":12,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a13","label":"제13조","title":"공간배정위원회","paras":[{"k":"hang","x":"① 공간배정위원회는 학생대표자회 대의원 전체로 구성한다."},{"k":"hang","x":"② 공간배정위원회의 위원장은 학부 학생회장으로 함을 원칙으로 한다."},{"k":"hang","x":"③ 공간배정위원회는 다음 각호의 사항을 고려하여 합리적 · 공평하게 공간을 배정하여야 한다."},{"k":"ho","x":"1. 자치단체가 하나 이상의 자치공간을 이용하고 있는지"},{"k":"ho","x":"2. 자치단체의 기존 자치공간의 사용에 안전상의 문제가 없는지"},{"k":"ho","x":"3. 자치단체 목적 활동에 자치공간의 유무가 중대한 영향을 미치는지"},{"k":"ho","x":"4. 자치단체 목적 활동 및 자치단체 규모에 자치단체실 크기가 중대한 영향을 미치는지"},{"k":"ho","x":"5. 자치단체가 기존 자치공간을 목적 활동에 맞게 사용하고 있는지"},{"k":"ho","x":"6. 자치단체가 기존 자치공간을 활발하게 이용하고 있는지"},{"k":"hang","x":"④ 공간배정위원회에서 공간 배분은 논의를 통한 배분을 원칙으로 하되, 의견이 첨예하게 갈릴 경우에는 표결의 방법으로 공간을 배분한다."},{"k":"hang","x":"⑤ 공간배정위원회가 표결의 방법을 실시하였을 때는 출석 과반수가 투표한 안을 채택한다. 과반수가 성립하지 못할 경우 가장 득표수가 많았던 두 개 안을 두고 재의결을 실시한다."},{"k":"hang","x":"⑥ 그 밖에 회의 진행에 관한 절차는 자유전공학부 학생회칙 제2장 제4절 학생대표자회의 절차를 준용한다."}],"num":13,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"부칙","bu":true,"id":"bu1"},{"t":"free","paras":[{"k":"line","x":"이 세칙은 공포 후 2021년 11월 13일부터 시행한다."}]},{"t":"art","id":"x1","label":"별 첨","title":"","paras":[{"k":"ho","x":"1. 자유전공학부 안전관리서약서 양식"}],"num":null}],"note":null}],"current":"jachigonggan-20211113","title":"자유전공학부 「자치공간운영세칙」"},{"id":"jinggye","cat":"세칙","short":"징계세칙","versions":[{"id":"jinggye-20211113","date":"2021.11.13","kind":"제정","title":"고려대학교 자유전공학부 징계세칙","subtitle":"[고려대학교 자유전공학부 학생회 세칙 제3호]","history":[["2021. 11. 13.","제정"]],"pdf":"pdf/jinggye-20211113.pdf","pdfName":"고려대학교_자유전공학부_징계세칙(2021.11.13_제정).pdf","blocks":[{"t":"h","lv":1,"text":"제1편 총칙"},{"t":"h","lv":2,"text":"제1장 적용범위와 원칙"},{"t":"art","id":"a1","label":"제1조","title":"목적","paras":[{"k":"line","x":"고려대학교 자유전공학부 징계 세칙은 고려대학교 자유전공학부 회원·기구의 권리를 침해하거나 본회 회원·기구로서의 의무를 다하지 않는 개인이나 기구를 징계함으로써 본회의 건전성과 지속가능성을 유지하는 것을 목적으로 한다."}],"num":1,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a2","label":"제2조","title":"적용범위","paras":[{"k":"hang","x":"① 징계 대상행위의 성립과 이에 대한 징계 처분은 행위 시의 본 세칙에 의한다."},{"k":"hang","x":"② 징계의 대상행위 후 본 세칙의 변경에 의하여 그 행위가 징계의 대상행위를 구성하지 아니하거나 징계가 구 세칙보다 경한 때에는 변경된 세칙에 의한다."},{"k":"hang","x":"③ 징계의 확정 후 본 세칙의 변경에 의하여 그 행위가 징계의 대상행위를 구성하지 아니하는 때에는 징계의 집행을 면제한다."},{"k":"hang","x":"④ 본회의 회원을 대상으로 한 위법행위로 형법 등 현행법에 의해 형벌을 부과받은 경우 제명 6개월 이상에 처할 수 있다."},{"k":"hang","x":"⑤ 중대한 인권침해 사건 또는 총학생회 차원의 징계 절차가 개시된 사안의 경우, 징계위원회 재적 과반수에 해당하는 결의로 총학생회에 징계를 위임할 수 있다."}],"num":2,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a3","label":"제3조","title":"징계 심의의 원칙","paras":[{"k":"hang","x":"① 본회의 모든 회원 및 기구의 대표자는 징계의 심의 과정에서 인권을 침해받지 아니하며, 자신에게 불리한 진술을 강요당하지 아니한다."},{"k":"hang","x":"② 본회의 모든 회원 및 기구는 징계가 확정될 때까지 무죄로 추정된다."},{"k":"hang","x":"③ 징계 심의 과정에 있어 징계혐의자에게 충분한 소명의 기회를 주어야 한다."}],"num":3,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a4","label":"제4조","title":"징계혐의자","paras":[{"k":"hang","x":"① ‘징계혐의자’는 징계 청구의 대상이 된 본회의 회원 및 기구를 말한다."},{"k":"hang","x":"② 징계혐의자가 기구인 경우에는, 해당 기구의 대표자가 징계 절차 전반의 일방 당사자가 되어 제14조, 제20조 제1항 및 제3항, 제21조, 제25조, 제26조 제3항 및 제4항, 제29조에 규정된 내용을 수행한다."},{"k":"hang","x":"③ 전항에도 불구하고 징계 의결의 효력은 해당 기구에 미친다."}],"num":4,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제2장 징계"},{"t":"h","lv":3,"text":"제1절 징계의 종류 및 경중"},{"t":"art","id":"a5","label":"제5조","title":"징계의 종류","paras":[{"k":"hang","x":"① 징계의 종류는 다음 각호로 한다."},{"k":"ho","x":"1. 주의"},{"k":"ho","x":"2. 경고와 사과문 게시"},{"k":"ho","x":"3. 몰수·추징"},{"k":"ho","x":"4. 보직해임"},{"k":"ho","x":"5. 선거권·피선거권 박탈"},{"k":"ho","x":"6. 자격정지"},{"k":"ho","x":"7. 기간 있는 제명"},{"k":"ho","x":"8. 영구제명"},{"k":"hang","x":"② 제1항 제1호와 제2호 처분에 대해서는 징계 대상 행위에 대한 정보공개와 시정 명령을 병과한다."},{"k":"hang","x":"③ 제1항 제3호 내지 제8호 처분에 대해서는 징계 대상 행위에 대한 정보공개를 병과한다."},{"k":"hang","x":"④ 정보공개에 있어 소속 반·기구를 제외한 개인 신상 정보는 비공개를 원칙으로 한다."},{"k":"hang","x":"⑤ 제1항의 제2호 내지 제8호에 해당하는 징계를 받은 자는 독립기구 및 집행기구 소속 회원이 되지 못한다."}],"num":5,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a6","label":"제6조","title":"주의","paras":[{"k":"hang","x":"① 주의는 본회의 회원·기구로서의 의무에 어긋나는 경미한 행위에 대한 처분으로서 징계 처분 중 가장 경미한 형태를 말한다."},{"k":"hang","x":"② 주의 처분에 해당하는 행위는 본 세칙의 각칙에서 세부적으로 규정한다."}],"num":6,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a7","label":"제7조","title":"경고 및 사과문 게시","paras":[{"k":"hang","x":"① 경고 및 사과문 게시는 주의 처분에 해당하는 동일한 행위를 2회 이상 행하거나 주의 처분의 정도를 넘어서는 상당한 행위를 한 경우에 대한 처분을 말한다."},{"k":"hang","x":"② 경고 및 사과문 게시 처분에 해당하는 주의 처분을 넘어서는 상당한 행위는 본 세칙의 각칙에서 세부적으로 규정한다."},{"k":"hang","x":"③ 사과문의 경우 법학관(구관) 자유전공학부 학생회 게시판, 법학관(신관) 자유전공학부 행정실 게시판 등 오프라인 게시판과 자유전공학부 홈페이지 학생회 게시판 등 각종 온라인 게시판에 게시하여야 한다."}],"num":7,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a8","label":"제8조","title":"몰수·추징","paras":[{"k":"hang","x":"① 몰수·추징은 본회의 자산을 사적으로 운용하여 이익을 취득하거나 본회에 피해가 발생했을 경우 해당 행위에 제공된 자산 자체, 행위의 결과로 얻은 자산 또는 그 가액을 본회의 자산으로 환수하는 처분을 말한다. 이때, 환수의 방법은 집행위원회의 결정에 따른다."},{"k":"hang","x":"② 몰수·추징의 대상 행위에 대해서는 본 세칙의 각칙에서 세부적으로 규정한다."}],"num":8,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a9","label":"제9조","title":"보직해임","paras":[{"k":"hang","x":"① 보직해임은 본회 집행위원회 및 독립기구의 구성원이 해당 직위에 따르는 의무를 적절하게 이행하지 아니하거나 해당 직위 수행으로 본회에 상당한 피해를 야기한 경우 해당 직위에서 해임하는 처분을 말한다. 단, 선출직은 보직해임 대상에 속하지 아니한다."},{"k":"hang","x":"② 보직해임의 대상 행위에 대해서는 본 세칙의 각칙에서 세부적으로 규정한다."}],"num":9,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a10","label":"제10조","title":"선거권·피선거권 박탈","paras":[{"k":"hang","x":"① 선거권·피선거권 박탈은 본회 각종 선거의 공정성·신뢰성을 현저히 침해하는 행위를 한 자에 대하여 일정 기간 동안 선거권 또는 피선거권을 박탈하는 처분을 말한다."},{"k":"hang","x":"② 선거권·피선거권 박탈의 범위와 기간에 대해서는 본 세칙의 각칙에서 세부적으로 규정한다."}],"num":10,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a11","label":"제11조","title":"자격정지","paras":[{"k":"hang","x":"① 자격정지는 본회의 회칙 및 세칙에 대한 중대한 위반 행위를 하였거나 본회 회원의 권리를 현격히 침해하는 행위를 한 자 또는 기구에 대해 기간을 정하여 본회 회원 또는 소속 기구로서의 자격을 정지시키는 처분을 말한다."},{"k":"hang","x":"② 자격정지 처분의 대상 행위 및 기간에 대해서는 본 세칙의 각칙에서 세부적으로 규정한다."},{"k":"hang","x":"③ 자격정지 처분의 대상이 된 자는 부과된 자격정지의 기간이 경과하면 자동으로 본회의 정회원 또는 기구로서의 자격을 회복한다."}],"num":11,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a12","label":"제12조","title":"제명","paras":[{"k":"hang","x":"① 제명은 본회의 회칙 및 세칙에 대한 중대한 위반 행위를 하였거나 본회 회원의 권리를 현격히 침해하는 행위를 한 자 또는 기구에 대해 한시적 혹은 영구적으로 회원 또는 소속 기구로서의 자격을 박탈시키는 것을 말한다."},{"k":"hang","x":"② 제명 처분의 대상 행위에 대해서는 본 세칙의 각칙에서 세부적으로 규정한다."},{"k":"hang","x":"③ 제명은 기간 있는 제명과 영구제명으로 나뉘며, 기간 있는 제명의 세부적인 기간에 대해서는 본 세칙의 각칙에서 세부적으로 규정한다."},{"k":"hang","x":"④ 제명의 경우 기간이 경과하더라도 별도의 회원 또는 기구 자격 등록 없이는 본회의 회원 또는 기구로서의 자격을 회복하지 못한다."}],"num":12,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제2절 징계의 청구"},{"t":"art","id":"a13","label":"제13조","title":"징계의 청구","paras":[{"k":"hang","x":"① 모든 회원은 본회 회원 또는 기구를 대상으로 징계를 청구할 수 있다."},{"k":"hang","x":"② 징계의 청구는 집행위원회에 서면으로 제출함을 원칙으로 하며, 서면에는 청구자의 이름·소속, 징계혐의자의 이름·소속, 징계 청구의 사유 등을 명시하여야 한다."},{"k":"hang","x":"③ 집행위원회는 징계의 청구가 있는 날로부터 1일 이내에 학생대표자회에 징계 청구의 사실을 알리고 징계위원회 구성을 요청해야 한다."},{"k":"hang","x":"④ 제2항의 서면 청구에 있어 청구자의 신상에 대한 위협이 발생할 가능성이 있는 경우 청구자는 이름·소속 등을 서면에는 기재하지 않고 추후 징계위원회 구성 시 징계위원장에게만 밝힐 수 있다."},{"k":"hang","x":"⑤ 징계위원장은 제4항의 사항에 대해 누구에게도 절대 발설하여서는 안된다."}],"num":13,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a14","label":"제14조","title":"징계혐의자에 대한 부본 송달","paras":[{"k":"line","x":"집행위원회는 징계청구서의 부본을 청구일로부터 3일 이내에 징계혐의자에게 송달하여야 한다."}],"num":14,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a15","label":"제15조","title":"특정 직위의 징계혐의자에 대한 직무집행정지 결정","paras":[{"k":"line","x":"집행위원, 독립기구 소속원 등 특정 직위에 있는 징계혐의자의 경우 징계위원회의 결정으로 해당 직위의 직무집행이 정지될 수 있다."}],"num":15,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a16","label":"제16조","title":"징계 청구의 취하","paras":[{"k":"line","x":"당해 청구사안이 징계 사유에 해당되지 아니한다고 인정할 만한 새로운 사실이 발견되는 등의 사유가 있는 경우 징계청구자는 징계혐의자에 대한 징계 청구를 제25조에 따른 징계 의결 전까지 취하할 수 있다. 단, 이 경우에도 징계위원회가 청구사안으로 인해 회원에 대한 중대한 침해가 예상되거나 본회의 건전성과 지속가능성을 유지를 위해 징계가 필요하다고 판단한 사항에 대해서는 절차를 계속할 수 있다."}],"num":16,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a17","label":"제17조","title":"징계 청구의 시효","paras":[{"k":"line","x":"징계 대상 행위가 있는 날부터 1년이 경과하면 이에 대해 징계를 청구하지 못한다. 다만, 징계 청구자에게 불가항력적인 장애 사유가 있었던 경우에는 그 장애 사유가 제거된 날로부터 3개월 내에 징계를 청구할 수 있다."}],"num":17,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제3절 징계위원회"},{"t":"art","id":"a18","label":"제18조","title":"목적","paras":[{"k":"line","x":"징계위원회는 징계 청구에 대하여 본회 회칙과 징계 세칙에 기반하여 구체적인 징계 대상 여부, 징계의 종류 및 징계의 양정 등을 심의하고 확정하는 것을 목적으로 한다."}],"num":18,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a19","label":"제19조","title":"구성","paras":[{"k":"hang","x":"① 징계위원회는 징계 청구 시 학생대표자회 대의원 중 7인을 선정하여 구성하고 예비위원 2인을 둔다. 단, 징계를 청구한 자는 징계위원회 구성에 참여하지 못한다."},{"k":"hang","x":"② 징계위원장은 학부 학생회장으로 함을 원칙으로 한다. 단, 학부 학생회장이 징계위원장이 될 수 없는 경우에는 징계위원 중 호선으로 결정한다."},{"k":"hang","x":"③ 징계위원장은 징계위원 명단을 첨부하여 징계위원회 구성을 공고한다."},{"k":"hang","x":"④ 징계위원은 사건의 징계 심의 절차 계속중에 임기 종료로 인해 학생대표자회 대의원 자격을 상실하더라도 당해 사건에 있어서는 징계위원의 자격을 상실하지 아니한다. 단, 졸업, 수료, 제적, 자퇴, 군휴학 등의 사유로 본회의 정회원 자격을 상실한 경우 그러하지 아니한다."}],"num":19,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a20","label":"제20조","title":"징계위원의 제척·기피","paras":[{"k":"hang","x":"① 징계위원회는 징계위원이 다음 각호 가운데 어느 하나에 해당하는 제척의 이유가 있는 때에는 직권으로 또는 징계혐의자의 신청에 따라 해당 징계위원에 대한 제척 여부를 결정한다."},{"k":"ho","x":"1. 징계위원이 당해 징계에 있어 당사자가 되거나, 징계의 당사자와 공동권리자ㆍ공동의무자의 관계에 있는 때"},{"k":"ho","x":"2. 징계위원이 당사자와 친족의 관계에 있거나 밀접한 사적 관계에 있을 때"},{"k":"ho","x":"3. 징계위원이 사건에 관하여 증언을 하였을 때"},{"k":"hang","x":"② 전항 제1호와 제2호에 있어 ‘당사자’라 함은 징계청구자 또는 징계혐의자를 지칭한다."},{"k":"hang","x":"③ 징계혐의자는 징계위원에게 공정한 징계 결정을 기대하기 어려운 사정이 있는 때에는 기피신청을 할 수 있으며, 징계위원회는 재적위원 과반수의 출석과 출석위원 과반수의 찬성으로 해당 징계위원에 대한 기피 신청 인용 여부를 결정한다. 단, 징계혐의자가 징계위원을 기피할 이유가 있다는 것을 알면서도 징계위원회 회의에서 진술을 한 경우에는 기피신청을 하지 못한다."}],"num":20,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a21","label":"제21조","title":"제척과 기피신청의 방식","paras":[{"k":"hang","x":"① 징계위원에 대한 제척 또는 기피는 징계위원회에 이유를 밝혀 신청하여야 한다."},{"k":"hang","x":"② 제척 또는 기피하는 이유와 소명방법은 신청한 날부터 3일 이내에 서면으로 제출하여야 한다."}],"num":21,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a22","label":"제22조","title":"제척 또는 기피신청의 각하 등","paras":[{"k":"hang","x":"① 제척 또는 기피신청이 제20조의 규정에 어긋나거나 징계 심의 및 확정의 지연을 목적으로 하는 것이 분명한 경우에는 신청을 받은 징계위원회의 결정으로 이를 각하한다."},{"k":"hang","x":"② 제척 또는 기피를 당한 징계위원은 제1항의 경우를 제외하고는 바로 제척 또는 기피신청에 대한 의견서를 제출하여야 한다."}],"num":22,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a23","label":"제23조","title":"징계 심의 절차의 정지","paras":[{"k":"line","x":"징계위원회는 제척 또는 기피신청이 있는 경우에는 결정 및 인용 여부가 확정될 때까지 징계 심의 절차를 정지하여야 한다. 다만, 제척 또는 기피신청이 각하된 경우에는 그러하지 아니하다."}],"num":23,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a24","label":"제24조","title":"징계위원 선정에 대한 회피","paras":[{"k":"line","x":"학생대표자회 대의원은 제19조의 사유가 있는 경우에는 징계위원으로의 선정을 회피할 수 있다."}],"num":24,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a25","label":"제25조","title":"징계의 심의","paras":[{"k":"hang","x":"① 징계위원회는 위원장을 포함한 재적 위원 과반수의 출석으로 심의를 개시한다."},{"k":"hang","x":"② 징계 심의 절차는 다음과 같이 진행한다."},{"k":"ho","x":"1. 징계 심의 기일 결정"},{"k":"ho","x":"2. 징계위원장의 징계혐의자에 대한 출석 명령"},{"k":"ho","x":"3. 심의 개시 선언"},{"k":"ho","x":"4. 징계혐의자에 대한 징계 청구의 사실관계 확인 및 그 밖에 필요한 사항 심문"},{"k":"ho","x":"5. 징계혐의자의 소명·반론 및 증거 제출"},{"k":"ho","x":"6. 징계 부과 여부, 징계의 종류 및 징계의 정도 심의"},{"k":"ho","x":"7. 징계 의결"},{"k":"hang","x":"③ 징계위원회는 징계혐의자가 징계위원장의 출석 명령을 받고 징계 심의 기일에 출석하지 아니한 때에는 서면으로 심의할 수 있다."}],"num":25,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a26","label":"제26조","title":"징계의 의결","paras":[{"k":"hang","x":"① 징계위원회는 징계의 심의를 마치면 출석위원 과반수의 찬성으로 징계혐의자에 대한 징계 부과 여부에 대해 의결한다."},{"k":"hang","x":"② 징계위원회가 제1항에 따라 징계 부과로 의결한 후 징계의 기간 등에 대한 의견이 나뉘어 출석위원 과반수에 이르지 못한 경우에는 출석위원 과반수에 이르기까지 징계혐의자에게 가장 불리한 의견의 수에 차례로 유리한 의견의 수를 더하여 그 중 가장 유리한 의견에 따른다."},{"k":"hang","x":"③ 징계위원회가 징계의 이유가 없다고 의결하였을 때에는 사건을 완결하여야 한다. 이러한 경우 그 내용을 징계혐의자와 징계청구자에게 알려야 하며, 관련 내용을 공고하여야 한다."},{"k":"hang","x":"④ 징계위원회는 징계 사유가 있으나 징계 처분을 하지 아니하는 것이 타당하다고 인정되는 경우에는 불문으로 하는 결정을 할 수 있다. 이 경우에도 불문의 사유 등을 포함한 불문 결정의 내용을 징계혐의자와 징계청구자에게 알려야 하며, 관련 내용을 공고하여야 한다."}],"num":26,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a27","label":"제27조","title":"서기의 참여와 심의기록의 작성","paras":[{"k":"hang","x":"① 본회 집행위원회는 집행위원 2인을 서기로 파견하여야 하며, 서기는 사건심의에 참여하여 심의기록을 작성하고 위원장과 함께 심의기록에 서명날인하여야 한다."},{"k":"hang","x":"② 집행위원회는 집행위원을 파견함에 있어 제19조의 사항을 충분히 고려하여야 한다."}],"num":27,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a28","label":"제28조","title":"징계결정서의 작성","paras":[{"k":"hang","x":"① 징계위원회가 징계를 의결하였을 때에는 결정서를 작성하여 위원장과 심의에 관여한 위원이 함께 결정서에 서명날인하여야 한다."},{"k":"hang","x":"② 징계의 결정요지서는 집행위원회, 징계혐의자 및 징계청구자에게 각각 송달하여야 한다."}],"num":28,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a29","label":"제29조","title":"이의제기","paras":[{"k":"line","x":"피징계자 또는 피징계기구는 징계 결정에 대해 서면으로 이의를 1회 제기할 수 있으며, 이 경우 징계위원회는 징계 결정에 대해 이의제기가 있은 날로부터 5일 이내에 수용 여부를 결정해야 한다."}],"num":29,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":3,"text":"제4절 징계의 집행"},{"t":"art","id":"a30","label":"제30조","title":"집행의 담당","paras":[{"k":"hang","x":"① 징계의 집행은 집행위원회가 담당한다."},{"k":"hang","x":"② 피징계자 또는 피징계기구의 이름·소속·반 등은 명부로 작성하여 보관하며, 징계결정서를 첨부한다."},{"k":"hang","x":"③ 피징계자 또는 피징계기구가 기록된 명부는 선거관리위원회, 투표관리위원회 또는 징계를 받은 자를 회원으로 둘 수 없는 각 기구의 확인 요청을 통해서만 집행위원회가 열람하여 징계 여부만을 회신할 수 있다."},{"k":"hang","x":"④ 전항에도 불구하고 피징계자는 본인의 징계 사항에 한해 징계 명부 등에 대한 열람이 가능하다."}],"num":30,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a31","label":"제31조","title":"집행의 내용","paras":[{"k":"hang","x":"① 본 세칙 제4조 제1항 제1호 내지 제4호 처분의 경우 징계의 대상, 징계 조항, 징계의 종류 등을 공고문 형식으로 작성하여 자유전공학부 게시판 등에 게시한다."},{"k":"hang","x":"② 동 조항 제5호 내지 제8호 처분에 대해서는 징계의 대상, 징계 조항, 징계의 종류, 징계의 기간 등을 공고문 형식으로 작성하여 자유전공학부 게시판 등에 게시한다."},{"k":"hang","x":"③ 공고문 작성 및 게시에 있어 소속 반·기구를 제외한 개인 신상 정보는 비공개를 원칙으로 한다."}],"num":31,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a32","label":"제32조","title":"징계 집행에 대한 보완 조치","paras":[{"k":"hang","x":"① 징계위원회는 집행위원회가 의결된 징계 사항을 온전히 이행하지 아니할 시, 직접 징계의 집행을 수행할 수 있다."},{"k":"hang","x":"② 이 경우에도 전조 제3항의 원칙에 기반하여야 한다."}],"num":32,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":1,"text":"제2편 각칙"},{"t":"h","lv":2,"text":"제1장 회원 및 기구의 권리 및 의무 위반에 대한 징계"},{"t":"art","id":"a33","label":"제33조","title":"공고문·홍보문 훼손","paras":[{"k":"hang","x":"① 본회 각 기구의 공고문 또는 홍보문을 고의 또는 중과실로 훼손한 경우 경고 및 사과문 게시에 처한다. 단, 공고문 또는 홍보문은 게시판 또는 해당 기구의 자치공간에 부착되어 있는 것에 한정한다."},{"k":"hang","x":"② 본회 각 기구의 공고문 또는 홍보문을 경과실로 훼손한 경우에는 주의에 처한다."},{"k":"hang","x":"③ 제1항에 해당하는 행위를 2회 이상 행한 경우 1개월 이상의 자격정지에 처한다."}],"num":33,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a34","label":"제34조","title":"자치공간 훼손","paras":[{"k":"hang","x":"① 본회의 자치공간을 고의 또는 중과실로 훼손한 경우 경고 및 사과문 게시에 처한다."},{"k":"hang","x":"② 본회의 자치공간을 경과실로 훼손한 경우 또는 훼손할 우려가 있는 행동을 한 경우 주의에 처한다."},{"k":"hang","x":"③ 제1항에 해당하는 행위를 2회 이상 행한 경우 1개월 이상의 자격정지에 처한다."}],"num":34,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a35","label":"제35조","title":"자치공간 무단침입","paras":[{"k":"hang","x":"① 본회 산하기구 및 독립기구가 점유하고 있는 자치공간에 해당 기구의 회원이 아닌 자가 정당한 사유 없이 무단으로 침입한 경우 주의에 처한다."},{"k":"hang","x":"② 본회 산하기구 및 독립기구가 점유하고 있는 자치공간에 해당 기구의 회원이 정당한 사유 없이 해당 기구의 회원이 아닌 자를 무단으로 침입시킨 경우 주의에 처한다."},{"k":"hang","x":"③ 본회 산하기구 및 독립기구가 점유하고 있는 자치공간에 해당 기구의 회원이 정당한 사유 없이 본회의 회원이 아닌 자를 무단으로 침입시킨 경우 경고 및 사과문 게시에 처한다."},{"k":"hang","x":"④ 이전 세 항에 해당하여 징계를 받고도 재차 해당 행위를 한 자는 1개월 이상의 자격정지에 처한다."}],"num":35,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a36","label":"제36조","title":"방화·실화","paras":[{"k":"hang","x":"① 실내흡연, 실내 화기 사용 등 화재를 야기할 수 있는 행위를 한 경우 자격정지 2개월 이상에 처한다."},{"k":"hang","x":"② 제1항에 해당하는 행위로 인해 화재가 발생한 경우 그 행위를 한 자는 제명 1년 이상에 처한다."}],"num":36,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a37","label":"제37조","title":"학부 차원의 결정사항과 공지사항 위반","paras":[{"k":"line","x":"정당한 사유 없이 학부 차원의 결정사항과 공지사항을 위반하는 경우 주의에 처한다."}],"num":37,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a38","label":"제38조","title":"혐오선전·선동","paras":[{"k":"line","x":"본회의 회원이 본회의 회원을 대상으로 신체조건, 인종, 출신지역·학교, 전공, 가족형태, 종교적 견해·정치적 견해, 성적지향·성정체성 등 사회적 신분에 대한 혐오를 선전·선동한 경우 경고 이상 제명 1년 이하에 처한다."}],"num":38,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제2장 선거에 관한 징계"},{"t":"art","id":"a39","label":"제39조","title":"회원에 대한 징계","paras":[{"k":"hang","x":"① 당해 선거에 있어 선거운동본부에 속하지 않은 회원이 다음 각호의 사항을 행한 경우 경고 및 사과문 게시에 처한다."},{"k":"ho","x":"1. 투·개표소에서 소란을 피우는 경우"},{"k":"ho","x":"2. 투표소로부터 10m 이내에서 선거에 영향을 미치게 하는 어떠한 표식을 지닌 경우"},{"k":"ho","x":"3. 선거관리위원회의 허가없이 투표소에서 투표인명부를 열람하려 하거나 열람하는 경우"},{"k":"ho","x":"4. 선거운동본부에 속하지 아니하고 특정 후보에 대한 지지의사 표명 이외의 선거운동에 해당하는 행위를 한 경우"},{"k":"ho","x":"5. 집회·연설·유세 등을 방해하거나, 선전물의 제작·배포와 게시를 임의로 방해하는 등 각종 부정한 방법으로 선거운동을 방해하는 경우"},{"k":"ho","x":"6. 선거관리위원회의 공고를 훼손하는 경우"},{"k":"ho","x":"7. 특정 후보나 선거관리위원을 상대로 무고하는 경우"},{"k":"ho","x":"8. 특정 후보의 신분·경력 또는 인격·사상에 관해 허위 사실을 진술 또는 유포한 경우"},{"k":"ho","x":"9. 특정 후보에 대해 선거와 관련 없는 사실을 들추어내어 인신공격하는 경우"},{"k":"ho","x":"10. 유세·벽보·유인물 등 어떤 방법으로든 특정 후보의 당선 또는 낙선을 목적으로 공익과 관계없이 공연한 사실을 드러내어 상대 후보자를 비방하는 경우"},{"k":"ho","x":"11. 정당한 이유 없이 투·개표에 간섭하거나 투표를 지시하거나 기타 투·개표에 영향을 주는 행위를 하는 경우"},{"k":"ho","x":"12. 기타 공정한 선거 질서를 해치는 것이 분명한 행위를 한 경우"},{"k":"hang","x":"② 당해 선거에 있어 선거운동본부에 속하지 않은 회원이 다음 각호의 사항을 행한 경우 1년 이하의 선거권·피선거권 박탈에 처한다."},{"k":"ho","x":"1. 제1항 각호에 해당하는 행위를 재차 반복하는 경우"},{"k":"ho","x":"2. 본회의 다른 회원을 대상으로 투표내용을 알리기를 강요하거나 투표를 강권·저지하여 투표의 기본 원칙을 상당히 침해하는 경우"}],"num":39,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a40","label":"제40조","title":"선거관리위원의 직권남용","paras":[{"k":"line","x":"선거관리위원이 직권남용에 해당한다고 판단되어 선거관리위원회에 의해 파면을 의결받은 경우 해당 선거관리위원은 당해 선거에 있어 선거권·피선거권 박탈에 처하며, 경고 및 사과문 게시를 병과한다. 이 경우 징계 심의 절차를 별도로 진행하지 아니한다."}],"num":40,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a41","label":"제41조","title":"선거관리위원회의 직권남용","paras":[{"k":"line","x":"선거관리위원회가 직권을 남용하여 본회의 회칙 및 선거시행세칙을 지키지 않은 경우 사안에 따라 다음 각호의 징계 중 하나에 처한다."},{"k":"ho","x":"1. 경고 및 사과문 게시"},{"k":"ho","x":"2. 당해 선거에 있어 선거권·피선거권 박탈"},{"k":"ho","x":"3. 자격정지"}],"num":41,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a42","label":"제42조","title":"학부 학생회장단의 선거 개입","paras":[{"k":"line","x":"현임 학부 학생회장단이 본회와 본회 산하기구의 각종 선거에 대해 부당한 영향력 행사 등 선거 결과에 직·간접적인 영향을 미치는 행위를 한 경우 당해 선거와 차기 선거에 있어 선거권·피선거권 박탈에 처하고, 경고 및 사과문 게시를 병과한다. 단, 피선거권 박탈의 경우 소급하여 적용하지 아니한다."}],"num":42,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a43","label":"졔43조","title":"선거운동본부에 대한 관할","paras":[{"k":"line","x":"선거에 관한 선거운동본부의 본회 회칙 및 선거시행세칙에의 위반에 관한 제반 사항은 징계위원회가 아닌 선거관리위원회의 관할로 하며, 그 징계 또한 본회 선거시행세칙에 따른다."}],"num":43,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"제3장 대표자의 의무 위반에 대한 징계"},{"t":"art","id":"a44","label":"제44조","title":"자료제출 서식 및 마감기한 위반","paras":[{"k":"line","x":"본회 각 기구의 대표자가 안전관리서약서, 자치단체 인준 신청서, 예산안·결산 등을 제출함에 있어 정해진 서식을 사용하지 않거나 마감기한을 위반한 경우 주의에 처한다."}],"num":44,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a45","label":"제45조","title":"자치공간에 대한 유지 및 보수 의무 위반","paras":[{"k":"line","x":"본회 각 기구의 대표자가 해당 기구의 자치공간에 대한 유지 및 보수를 해태하여 매 학기 시행되는 안전점검에서 문제가 발견된 경우 해당 기구의 대표자를 경고 및 사과문 게시에 처한다. 단, 해당 자치공간에 대한 자발적인 유지 및 보수가 불가피한 사정으로 이뤄지지 못한 경우는 징계에 처하지 아니한다."}],"num":45,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a46","label":"제46조","title":"집행위원회의 기록물 관리 의무 위반","paras":[{"k":"line","x":"본회의 집행위원으로서 본회의 기록물을 임의로 수정하거나 훼손·폐기한 경우 보직해임에 처한다. 단, 본회 회칙 제12조 제3항 단서의 각호에 해당하는 경우는 징계하지 아니한다."}],"num":46,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a47","label":"제47조","title":"집행위원회의 수인의무 위반","paras":[{"k":"line","x":"집행위원회가 본회 의결기구 및 징계위원회의 결정 사항 집행을 해태한 경우 경고 및 사과문 게시에 처한다. 이 경우 집행위원회에 대한 징계 공고는 징계위원회에서 담당한다."}],"num":47,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a48","label":"제48조","title":"의결기구에 대한 소집공고 등 위반","paras":[{"k":"line","x":"본회 각 의결기구의 의장으로서 의결기구에 대한 소집공고, 자료의 사전 배포 및 결과공고 등의 기한을 어긴 경우 경고 및 사과문 게시에 처한다. 단, 징계 청구 전에 위반사항에 대한 사과문이 게시된 때에는 징계하지 아니한다."}],"num":48,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a49","label":"제49조","title":"대외활동에 관한 의무 위반","paras":[{"k":"line","x":"학부 학생회장단이 본회 차원의 연대 단체 가입과 대외적 협의, 본회의 재정적 지출을 수반하는 행위나 본회의 회원에게 중대한 영향을 미치는 대외활동에 대해 본회 회칙 제78조에 따른 학부운영위원회 동의를 받지 아니한 경우 경고 및 사과문 게시에 처한다. 단, 본회의 재정적 지출을 수반하거나 자산을 사용한 경우 몰수·추징을 병과할 수 있다."}],"num":49,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a50","label":"제50조","title":"재정의 부적절 운용","paras":[{"k":"hang","x":"① 본회 각 기구의 대표자 또는 재정담당자로서 기구의 재정을 부적법·부적절하게 운용한 경우 본회 회칙 제169조 제4항에 의한 징계에 처한다."},{"k":"hang","x":"② 전항에 해당하는 자가 재차 재정을 부적절하게 운용한 경우 보직해임에 처한다."}],"num":50,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a51","label":"제51조","title":"배임·횡령","paras":[{"k":"hang","x":"① 본회 각 기구의 재정을 사적으로 유용한 경우 자격정지 2개월 이상에 처한다. 또한, 횡령한 금액과 그 금액을 이용하여 증식한 일체의 것을 몰수 및 추징한다."},{"k":"hang","x":"② 본회 각 기구의 재정을 사적으로 유용한 자가 속한 기구에 대해서는 본회 회칙 제169조 제5항에 의한 징계에 처한다."}],"num":51,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a52","label":"제52조","title":"자산 관리 해태","paras":[{"k":"line","x":"본회 각 기구의 자산을 관리하는 자로서 자산 관리를 해태하여 해당 기구에 물적 손해를 입힌 경우 보직해임에 처하며, 경고 및 사과문 게시를 병과한다."}],"num":52,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a53","label":"제53조","title":"문서 위조","paras":[{"k":"line","x":"본회 각 기구의 재정을 증빙하기 위한 서류를 위조한 경우 보직해임에 처하며, 경고 및 사과문 게시를 병과한다."}],"num":53,"sub":null,"bu":false,"bold_title":false}],"note":null}],"current":"jinggye-20211113","title":"고려대학교 자유전공학부 징계세칙"},{"id":"gakjong","cat":"규칙","short":"각종공고 일반규칙","versions":[{"id":"gakjong-20211223","date":"2021.12.23","kind":"제정","title":"각종공고 일반규칙","subtitle":null,"history":[["2021. 12. 23.","제정"]],"pdf":"pdf/gakjong-20211223.pdf","pdfName":"각종공고_일반규칙(2021.12.23_제정).pdf","blocks":[{"t":"art","id":"a1","label":"제1조","title":"각종공고","paras":[{"k":"line","x":"‘각종공고’란 다음 각호의 문서를 의미한다."},{"k":"ho","x":"1. 본회 회칙 제11조, 제12조, 제160조의2에 따라 게시되는 문서"},{"k":"ho","x":"2. 본회 세칙에 따라 공고의 방법으로 게시되는 문서"}],"num":1,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a2","label":"제2조","title":"게시방법","paras":[{"k":"hang","x":"① 본회의 각종공고는 다음 각호의 방법으로 게시함을 원칙으로 한다."},{"k":"ho","x":"1. 온라인의 경우: 자유전공학부 학생회 카페(http://cafe.naver.com/kusis/)에 게시"},{"k":"ho","x":"2. 오프라인의 경우: 구법학관 자유전공학부 게시판에 게시"},{"k":"hang","x":"② 집행기구는 회원이 각종공고를 알기 쉽도록 카카오톡 공지방 등을 활용해야 한다."}],"num":2,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"부칙","bu":true,"id":"bu1"},{"t":"art","id":"b1-1","label":"제1조","title":"","paras":[{"k":"line","x":"집행위원회는 이 규칙 제정 이전에 게시된 각종공고를 다음 각호의 장소에 이전·보존하여야 한다."},{"k":"ho","x":"1. 온라인의 경우: 자유전공학부 학생회 카페(http://cafe.naver.com/kusis/)"},{"k":"ho","x":"2. 오프라인의 경우: 자유전공학부 학생회실 또는 그밖에 적당한 장소"}],"num":1,"sub":null,"bu":true,"bold_title":false}],"note":"제14-2차 학부운영위원회 일반규칙 제정안 공포 공고의 [별첨 1] 신구조문대비표에서 옮긴 본입니다."},{"id":"gakjong-20260126","date":"2026.01.26","kind":"1차 개정","title":"각종공고 일반규칙","subtitle":null,"history":[["2021. 12. 23.","제정"],["2026. 01. 26.","1차 개정"]],"pdf":"pdf/gakjong-20260126.pdf","pdfName":"각종공고_일반규칙(2026.01.26_1차_개정).pdf","blocks":[{"t":"art","id":"a1","label":"제1조","title":"각종공고","paras":[{"k":"line","x":"‘각종공고’란 다음 각호의 문서를 의미한다."},{"k":"ho","x":"1. 본회 회칙 제12조(사무 처리)에 따라 회원에게 알리기 위해 게시되는 문서"},{"k":"ho","x":"2. 본회 세칙 및 규칙에 따라 공고의 방법으로 게시되는 문서"}],"num":1,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a2","label":"제2조","title":"게시방법","paras":[{"k":"hang","x":"① 본회의 각종공고는 다음 각호의 방법으로 게시함을 원칙으로 한다."},{"k":"ho","x":"1. 온라인의 경우, 자유전공학부 학생회 공식 카페(http://cafe.naver.com/kusis/) 또는 학부운영위원회가 지정한 공식 SNS/플랫폼에 게시한다."},{"k":"ho","x":"2. 오프라인의 경우, 본회 회칙 제3조에 따른 자유전공학부 자치공간 내 자유전공학부 학생회 게시판에 게시"},{"k":"hang","x":"② 집행기구는 회원이 각종공고를 알기 쉽도록 카카오톡 공지방 등 모바일 메신저를 적극 활용하여야 한다."}],"num":2,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a3","label":"제3조","title":"기록물 관리","paras":[{"k":"hang","x":"① 게시된 각종공고는 본회 회칙 제13조(기록물 관리)에 따라 임의로 수정, 훼손하거나 폐기할 수 없다."},{"k":"hang","x":"② 공고 기간이 종료된 기록물은 회칙 제13조 제2항에 따라 다음 각호에 명시된 기록물 관리기관으로 이전하여 보존하여야 한다."},{"k":"ho","x":"1. 온라인의 경우: 자유전공학부 학생회 카페 및 디지털 아카이브"},{"k":"ho","x":"2. 오프라인의 경우: 자유전공학부 학생회실 또는 그밖에 적당한 장소"}],"num":3,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"부칙","bu":true,"id":"bu1"},{"t":"art","id":"b1-1","label":"제1조","title":"경과조치","paras":[{"k":"line","x":"집행위원회는 이 규칙 제정 및 개정 이전에 게시된 각종공고를 제3조 2항 각호에 명시된 기록물 관리기관에 이전·보존하여야 한다."}],"num":1,"sub":null,"bu":true,"bold_title":false}],"note":null}],"current":"gakjong-20260126","title":"각종공고 일반규칙"},{"id":"banbaejeong","cat":"규칙","short":"반배정 일반규칙","versions":[{"id":"banbaejeong-20211223","date":"2021.12.23","kind":"제정","title":"반배정 일반규칙","subtitle":null,"history":[["2021. 12. 23.","제정"]],"pdf":"pdf/banbaejeong-20211223.pdf","pdfName":"반배정_일반규칙(2021.12.23_제정).pdf","blocks":[{"t":"art","id":"a1","label":"제1조","title":"신입학에 의한 학적 취득의 경우","paras":[{"k":"hang","x":"① 학번 뒤 세 자리가 001~026인 학생은 A반 소속 학생이 된다."},{"k":"hang","x":"② 학번 뒤 세 자리가 027~052인 학생은 B반 소속 학생이 된다."},{"k":"hang","x":"③ 학번 뒤 세 자리가 053~078인 학생은 C반 소속 학생이 된다."},{"k":"hang","x":"④ 학번 뒤 세 자리가 079~104인 학생은 D반 소속 학생이 된다."},{"k":"hang","x":"⑤ 학번 뒤 세 자리가 105번인 학생부터는 순서대로 돌아가면서 A반, B반, C반, D반에 한 명씩 차례로 배정한다."}],"num":1,"sub":null,"bu":false,"bold_title":false},{"t":"h","lv":2,"text":"부칙","bu":true,"id":"bu1"},{"t":"art","id":"b1-1","label":"제1조","title":"","paras":[{"k":"line","x":"본 규칙 제1조 제5항에도 불구하고 2020학년도 2학기 입학생에 대하여는 다른 방법으로 배정하였음을 확인한다."}],"num":1,"sub":null,"bu":true,"bold_title":false}],"note":"제14-2차 학부운영위원회 일반규칙 제정안 공포 공고의 [별첨 1] 신구조문대비표에서 옮긴 본입니다."}],"current":"banbaejeong-20211223","title":"반배정 일반규칙"},{"id":"samulham","cat":"규칙","short":"신법학관 사물함 이용 규칙","versions":[{"id":"samulham-20160722","date":"2016.07.22","kind":"제정","title":"자유전공학부 학생회 신법학관 사물함 이용규칙","subtitle":"자유전공학부 학생회","history":[["2016.07.22","제정"]],"pdf":"pdf/samulham-20160722.pdf","pdfName":"자유전공학부_학생회_신법학관_사물함_이용규칙(2016.07.22_제정).pdf","blocks":[{"t":"art","id":"s1","label":"1.","title":"관리권한","paras":[{"k":"line","x":"고려대학교 자유전공학부 학생회는 신법학관 B102호와 B103호에 있는 사물함 485개 일체에 대한 관리권한을 가짐. 관리권한이라 함은 사물함대여에 관한 전반적인 업무를 집행할 권한이 있다는 것을 의미함."}],"num":null},{"t":"art","id":"s2","label":"2.","title":"사물함 배정 및 철거 공지","paras":[{"k":"line","x":"사물함 배정 및 철거 공지는 자유전공학부 홈페이지(sis.korea.ac.kr)의 학생회 게시판, 자유전공학부 페이스북 페이지 및 그룹, 학번별 단체카톡방(12~16학번), 오프라인 게시물(신법학관)을 통해 이루어짐."}],"num":null},{"t":"art","id":"s3","label":"3.","title":"사물함 이용기간 및 배정절차","paras":[{"k":"hang","x":"① **입학 기준 1~2년차** 회원은 2학년 2학기 계절학기 종강일 까지.(여기서 ‘X년차’이라 함은 입학 이후 X년차 재적생이라는 것을 의미. 2016년 현재 15학번이 2년차에 해당함. 단 특이한 케이스인 자전 **15학번 외국인 학생**의 경우, 사물함 배정상의 편의를 위해 __이외 회원과 동일한 방법으로 신청해야함__)"},{"k":"hang","x":"② **이외 회원(3년차 이상 및 비회원)**은 매 1학기부터 2학기 계절학기 종강일 까지."},{"k":"hang","x":"③ 사물함 짐 철거 이후 안내된 신청기간에 반드시 재신청해야 함."},{"k":"hang","x":"④ 신규신청은 매학기 받으며, 연장신청은 1년 단위로 받음. (3년차 첫 학기엔 연장신청을 할 수 없음)"}],"num":null},{"t":"art","id":"s4","label":"4.","title":"사물함 자진 철거일","paras":[{"k":"hang","x":"① **2년차 까지**(개인 휴학과 무관하게 입학 후 4학기)는 __2년차 2학기 계절학기 종강일 기준 7일 이내.__"},{"k":"hang","x":"② **3년차 이상**(개인 휴학과 무관하게 입학 후 5학기)은 __매 2학기 계절학기 종강일 기준 7일 이내.__"},{"k":"hang","x":"③ 군 휴학 예정자는 휴학 후 군 입대 전일까지."}],"num":null},{"t":"art","id":"s5","label":"5.","title":"사물함 배정 기준","paras":[{"k":"hang","x":"① 배정 순위 : 자유전공학부 등록생〉 자유전공학부 휴학(수료)생 〉 타과 재학생(공거리) 〉타과 재학생(비공거리) 타과 휴학생"},{"k":"hang","x":"② **자유전공학부 학생회 1, 2년차** 회원에게 총 사물함 97줄(485개) 중 45줄(225개)을 할당하고, 학번 뒤 3자리의 순서대로 사물함을 배정함."},{"k":"hang","x":"③ **이외 회원(3년차 이상 및 비회원)**은 각 배정순위별로 윗줄부터 신청 선착순으로 배정함. 선착순의 기준은 구글독스에 기록된 순서임. (예를 들어, 8월 5일에 “8월 10일 22:00부터 신청을 받겠다고 신청 링크와 함께 공지 올리면, 8월 10일 22:00:00부터 순위를 매겨 배정함. 8월 10일 21:59:59까지 들어온 신청은 **무효**.)"}],"num":null},{"t":"art","id":"s6","label":"6.","title":"사물함 이용자의 의무 및 주의사항","paras":[{"k":"hang","x":"① 사물함 이용자는 정기적으로 자유전공학부 학생회의 공지를 확인할 의무가 있음."},{"k":"hang","x":"② __자진철거기간 내에 반드시 사물함 내용물을 철거해야 함__. __미철거 내용물은 따로 보관하지 않으며, 다음 이용자 재량으로 처분 함.__"},{"k":"hang","x":"③ 개인의 **부주의**로 공지를 확인하지 못했거나 자진철거기간 이후에 철거된 내용물에 대하여 __자유전공학부 학생회는 책임을 지지 않음.__"},{"k":"hang","x":"④ 사물함에 상할 수 있는 음식물이나 폭발 가능성이 있는 물건 등을 보관해서는 안 됨."},{"k":"hang","x":"⑤ 분실 방지를 위해 반드시 __비밀번호를 설정__해야 함. 도난당한 내용물에 대해 __학생회는 책임을 지지 않음.__"},{"k":"hang","x":"⑥ 개인 과실로 인해 사물함이 파손된 경우 학생회로부터 수리비를 청구 받을 수 있음."},{"k":"hang","x":"⑦ 배정 당시 사물함의 파손상태를 확인해야 하며, 문제가 있을 경우 __자유전공학부 학생회로 2주 이내에 연락__하면 무상으로 교체가 가능함."},{"k":"hang","x":"⑧ 사물함 관련 문의사항은 학생회 (가)__이메일__, (나)__페이스북 메시지__, (다)__복지국장 연락처__로 해야 함."}],"num":null}],"note":"게시물 사진을 옮겨 적은 본입니다. 강조(굵게·밑줄)는 사진 기준입니다."},{"id":"samulham-20200313","date":"2020.03.13","kind":"개정","title":"자유전공학부 학생회 신법학관 사물함 이용 규칙","subtitle":"자유전공학부 학생회","history":[["2016. 07. 22","제정"],["2020. 03. 13","개정"]],"pdf":"pdf/samulham-20200313.pdf","pdfName":"자유전공학부_학생회_신법학관_사물함_이용_규칙(2020.03.13_개정).pdf","blocks":[{"t":"art","id":"s1","label":"1.","title":"관리권한","paras":[{"k":"line","x":"고려대학교 자유전공학부 학생회는 신법학관 1층, 2층, 계단 및 지하 1층에 있는 사물함 485개 일체에 대한 관리권한을 가짐. 관리권한이라 함은 사물함 대여에 관한 전반적인 업무를 집행할 권한이 있다는 것을 의미함."}],"num":null},{"t":"art","id":"s2","label":"2.","title":"사물함 배정 및 철거 공지","paras":[{"k":"line","x":"사물함 배정 및 철거 공지는 자유전공학부 홈페이지(sis.korea.ac.kr)의 학생회 게시판, 자유전공학부 페이스북 페이지 및 그룹, 학번별 카카오톡 공지방(12~20학번)을 통해 이루어짐."}],"num":null},{"t":"art","id":"s3","label":"3.","title":"사물함 이용기간 및 배정절차","paras":[{"k":"hang","x":"① 사물함 이용기간은 매 2학기 계절학기 종강일까지."},{"k":"hang","x":"② 겨울방학 중 사물함 이용을 원할 경우 6. ⑩ (가)이메일로 간단한 사유를 적어 제출하여 연장을 신청할 수 있음. (단, 짐을 철거하지 못해서 연장한다는 사유는 받아들이지 않음). 연장하더라도 다음 연도 신규 신청일 전날까지만 연장 가능함."},{"k":"hang","x":"③ 입학 기준 1년차 회원은 자동으로 배정하며, 2년차 이상 회원은 매 1학기 개강 전에 사물함호랑이 사이트(https://www.lockertiger.com/kusis)를 통해 신청함."},{"k":"hang","x":"④ 사물함 짐 철거 이후 안내된 신청기간에 반드시 재신청해야 함."},{"k":"hang","x":"⑤ 2학기 복학 예정자 및 2학기 입학 학우들을 위해 2학기 개강 전에 신청을 한 번 더 받으며 사물함 이용기간은 동일하게 2학기 계절학기 종강일까지."}],"num":null},{"t":"art","id":"s4","label":"4.","title":"사물함 자진 철거일","paras":[{"k":"hang","x":"① 매 2학기 계절학기 종강일 기준 7일 이내"},{"k":"hang","x":"② 군 휴학 예정자는 휴학 후 군입대 전일까지"}],"num":null},{"t":"art","id":"s5","label":"5.","title":"사물함 배정 기준","paras":[{"k":"hang","x":"① 배정 순위: 자유전공학부 학생회원 > 공공거버넌스와 리더십 융합전공생 > 타과생"},{"k":"hang","x":"② 자유전공학부 학생회 1년차 회원은 학번 뒤 3자리의 순서대로 사물함을 배정함."},{"k":"hang","x":"③ 2년차 이상 회원 및 비회원은 각자의 신청 기간에 맞추어 3. ③ 에 기재된 사이트에서 원하는 사물함을 택하여 신청함."}],"num":null},{"t":"art","id":"s6","label":"6.","title":"사물함 이용자의 의무 및 주의사항","paras":[{"k":"hang","x":"① 사물함 이용자는 정기적으로 자유전공학부 학생회의 공지를 확인할 의무가 있음."},{"k":"hang","x":"② __자진철거기간 내에 반드시 사물함 내용물을 철거해야 함. 미철거 내용물은 따로 보관하지 않으며, 다음 이용자 재량으로 처분함.__"},{"k":"hang","x":"③ 개인의 부주의로 공지를 확인하지 못했거나 자진철거기간 이후에 철거된 내용물에 대하여 __자유전공학부 학생회는 책임을 지지 않음.__"},{"k":"hang","x":"④ 사물함에 상할 수 있는 음식물이나 폭발 가능성이 있는 물건 등을 보관해서는 안 됨."},{"k":"hang","x":"⑤ 분실 방지를 위해 반드시 __비밀번호를 설정__해야 함. 도난당한 내용물에 대해 __학생회는 책임을 지지 않음.__"},{"k":"hang","x":"⑥ 개인 과실로 인해 사물함이 파손된 경우 학생회로부터 수리비를 청구 받을 수 있음."},{"k":"hang","x":"⑦ 배정 당시 사물함의 파손 상태를 확인해야 하며, 문제가 있을 경우 __자유전공학부 학생회로 2주 이내에 연락__하면 무상으로 교체가 가능함."},{"k":"hang","x":"⑧ 본인 명의로만 사물함 신청이 가능함. 타인 명의로 사물함을 신청할 수 없으며 __적발 시 신청을 취소함.__"},{"k":"hang","x":"⑨ 무단으로 타인에게 사물함을 판매, 양도해서는 안 됨. 적발 시 신청을 취소하며, __향후 구매 및 판매자의 사물함 이용을 제한함.__"},{"k":"hang","x":"⑩ 사물함 관련 문의사항은 학생회 (가)__이메일__, (나)__페이스북 메시지__, (다)__복지국장 연락처__로 해야 함."}],"num":null}],"note":"게시물 사진을 옮겨 적은 본입니다."},{"id":"samulham-20250126","date":"2025.01.26","kind":"2차 개정","title":"자유전공학부 학생회 신법학관 사물함 이용 규칙","subtitle":null,"history":[["2016. 07. 22.","제정"],["2020. 03. 13.","1차 개정"],["2025. 01. 26.","2차 개정"]],"pdf":"pdf/samulham-20250126.pdf","pdfName":"자유전공학부_학생회_신법학관_사물함_이용_규칙(2025.01.26_2차_개정).pdf","blocks":[{"t":"art","id":"a1","label":"제1조","title":"권한","paras":[{"k":"line","x":"고려대학교 자유전공학부 학생회(이하 “학생회”라 한다)는 신법학관 1층, 2층, 계단 및 지하 1층에 설치된 사물함 일체에 대하여 사물함의 배정, 관리, 회수 및 철거 등 대여에 관한 전반적인 업무를 집행할 권한을 가진다."}],"num":1,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a2","label":"제2조","title":"사물함 배정 및 철거 공지","paras":[{"k":"hang","x":"① 사물함의 배정 및 철거에 관한 공지는 학번별 카카오톡 공지방을 통하여 실시한다."},{"k":"hang","x":"② 학생회는 필요하다고 판단하는 경우 제1항의 공지 방식 외에 추가적인 공지 수단을 병행할 수 있다."}],"num":2,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a3","label":"제3조","title":"사물함 이용기간","paras":[{"k":"hang","x":"① 사물함의 이용기간은 배정일로부터 해당 학년도 제2학기 종강일까지로 한다."},{"k":"hang","x":"② 사물함 이용기간의 연장은 원칙적으로 허용하지 아니한다. 다만, 학생회 사업 수행을 위하여 불가피한 경우에는 학생회의 결정에 따라 예외적으로 연장할 수 있다."},{"k":"hang","x":"③ 사물함 이용자는 제2학기 종강일로부터 7일 이내의 자진철거기간 동안 사물함 내 물품을 철거하여야 한다."}],"num":3,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a4","label":"제4조","title":"사물함 배정 절차","paras":[{"k":"hang","x":"① 사물함 배정은 학생회가 자유전공학부 학생회원 중 신청자를 수합하여 추첨을 통해 실시하는 것을 원칙으로 한다."},{"k":"hang","x":"② 사물함 배정에 있어 1학년 학생을 우선 배정하는 것을 원칙으로 한다."},{"k":"hang","x":"③ 사물함 배정 후 잔여 사물함이 발생한 경우, 학생회는 그 사용 및 처분에 관한 사항을 결정하고 제2조에 따른 방법으로 이를 공지한다."}],"num":4,"sub":null,"bu":false,"bold_title":false},{"t":"art","id":"a5","label":"제5조","title":"사물함 이용자의 의무 및 주의사항","paras":[{"k":"hang","x":"① 사물함 이용자는 학생회가 공지하는 사항을 정기적으로 확인할 의무를 부담한다."},{"k":"hang","x":"② 사물함 이용자는 제3조 제3항에 따른 자진철거기간 내에 사물함 내 물품을 반드시 철거하여야 한다. 이를 이행하지 아니한 경우, 학생회는 해당 물품을 별도로 보관하지 아니하며, 이후 사물함 이용자의 재량에 따라 처분할 수 있다."},{"k":"hang","x":"③ 개인의 부주의로 인하여 공지를 확인하지 못하였거나 자진철거기간 이후에 철거된 물품에 대하여 학생회는 어떠한 책임도 지지 아니한다."},{"k":"hang","x":"④ 사물함에는 부패 또는 변질 우려가 있는 음식물, 폭발 또는 화재의 위험이 있는 물품 등 안전을 해칠 수 있는 물품을 보관하여서는 아니 된다."},{"k":"hang","x":"⑤ 사물함 이용자는 분실 방지를 위하여 반드시 비밀번호를 설정하여야 하며, 도난 또는 분실 사고에 대하여 학생회는 책임을 지지 아니한다."},{"k":"hang","x":"⑥ 사물함 이용자의 과실로 인하여 사물함이 파손된 경우, 학생회는 해당 이용자의 향후 사물함 이용을 제한할 수 있다."},{"k":"hang","x":"⑦ 사물함 이용자는 배정 시 사물함의 파손 여부를 확인하여야 하며, 파손 사실이 확인된 경우 배정일로부터 2주 이내에 학생회에 통보하면 무상 교체를 받을 수 있다."},{"k":"hang","x":"⑧ 사물함 신청은 본인 명의로만 가능하며, 타인 명의로 신청한 사실이 확인될 경우 해당 신청은 취소된다."},{"k":"hang","x":"⑨ 사물함을 무단으로 타인에게 판매하거나 양도하여서는 아니 되며, 이를 위반한 경우 사물함 이용 자격을 취소하고 향후 사물함 이용을 제한할 수 있다."},{"k":"hang","x":"⑩ 사물함 관련 문의사항은 다음 각 호의 연락망을 통하여 할 수 있다."},{"k":"ho","x":"1. 학생회 공식 이메일"},{"k":"ho","x":"2. 학생회 공식 SNS"},{"k":"ho","x":"3. 학생회 학생회장단, 담당 국서 국장 연락처"}],"num":5,"sub":null,"bu":false,"bold_title":false}],"note":null}],"current":"samulham-20250126","title":"자유전공학부 학생회 신법학관 사물함 이용 규칙"},{"id":"pyeongdeung","cat":"자치규약","short":"평등자치규약 및 성평등자치규약","versions":[{"id":"pyeongdeung-20172","date":"2017-2학기","kind":"결의·인준","title":"자유전공학부 평등자치규약 및 성평등자치규약","subtitle":null,"history":[],"pdf":"pdf/pyeongdeung-20172.pdf","pdfName":"자유전공학부_평등자치규약_및_성평등자치규약(2017-2학기).pdf","blocks":[{"t":"intro","paras":["자유전공학부 학생들은 서로 다른 목표와 꿈이 있을 것이고, 개개인들이 갖고 있는 개성, 성격, 성장배경은 다양할 것입니다. 또한 우리 모두 고려대학교 자유전공학부라는 공간을 선택했지만, 그 개인이 이 공간에 부여하는 의미는 모두 다를 것입니다. 하지만 우리는 앞으로 수년간 서로 마주하고, 인연을 같이 할 사람들입니다. 그 시간 동안 우리들은 수많은 관계들과 지위를 맞이하고, 학번과 직책을 뛰어넘어 같이 토론할 것이고, 같이 활동할 것입니다. 또 성과 관련된 기존의 고정관념과 편견을 부수려 노력하는 수많은 학우들을 만날 것이며, 더 다양한 정체성을 접하고 그들과 관계를 맺게 될 것입니다. 그러나 어떠한 정체성도 다른 정체성을 앞지를 수 없습니다. 개인이 모두 개개인의 삶을 존중하는 것, 그것이 우리들이 제일 먼저 가져야 하는 중요한 태도입니다. 학번, 나이, 직위를 떠나서 자신의 의견을 자유롭게 표현하고, 자신의 정체성을 드러내고 그것이 존중받는 공동체, 그리고 약자를 비하하는 무의식적인 발언에 대해 불편해하고 그 불편함을 지적하고 바꿀 수 있는 용기를 가진 공동체, 자유전공학부는 바로 이러한 공동체를 지향해야 합니다.","그러나 우리는 기계적 중립만을 얘기하는 규범들이 실질적인 의미를 갖지 못한 채 기존의 불평등을 존속시키는 모습을 지금껏 수없이 확인해왔습니다. 따라서 평등한 자유전공학부 공동체를 만들기 위해선 일상 속에서 맺어가는 관계들 속에 차별이 있지는 않은지, 그 차별들이 생겨나도록 한 부당한 권력의 차이가 있지는 않은지 고민해야합니다. 그리고는 우리 공동체 안에 존재하는 불평등과 권력의 위계를 냉철히, 철저히 분석하고, 이를 바탕으로 권력체계를 사회적, 제도적으로 바꾸어나감으로써 차별을 지워나가는 것이 바로 우리 자유전공학부 공동체가 평등으로 가는 길일 것입니다.","다음은 2017-2학기 정기 자유전공학부 전체학생대표자회의에서 결의 및 인준된 자치규약입니다."]},{"t":"h","lv":2,"text":"자유전공학부 평등자치규약"},{"t":"art","id":"a1","label":"제1조","title":"고려대학교 자유전공학부 일원은 나이와 학번을 막론하고 누구든지 평등하다.","paras":[{"k":"line","x":"선배와 후배 간 및 연장자와 연소자 간 차별을 행사하지 않습니다. 나이와 학번을 강조하지 않으며 상호 간 존칭을 사용하는 등 서로를 존중합니다."}],"num":1,"sub":null,"bu":false,"bold_title":true},{"t":"art","id":"a2","label":"제2조","title":"고려대학교 자유전공학부 일원은 성별을 막론하고 누구든지 평등하다.","paras":[{"k":"line","x":"성 차별적 언행을 하지 않습니다. 성평등자치규약의 내용을 충분히 숙지하고 준수합니다."}],"num":2,"sub":null,"bu":false,"bold_title":true},{"t":"art","id":"a3","label":"제3조","title":"고려대학교 자유전공학부 일원은 성정체성과 성적 지향을 막론하고 누구든지 평등하다.","paras":[{"k":"line","x":"개개인의 성정체성과 성적 지향에 근거한 차별적 언행을 하지 않습니다. 성평등자치규약의 내용을 충분히 숙지하고 준수합니다."}],"num":3,"sub":null,"bu":false,"bold_title":true},{"t":"art","id":"a4","label":"제4조","title":"고려대학교 자유전공학부 일원은 장애 여부를 막론하고 누구든지 평등하다.","paras":[{"k":"line","x":"장애를 이유로 차별을 행사하지 않습니다. 특히 일상생활에서 ‘병신’, ‘병신샷’ 등의 비하적 표현들을 사용하지 않습니다. 또한 비하의 의도로 ‘장애’, ‘장애인’ 등의 표현을 사용하지 않습니다."}],"num":4,"sub":null,"bu":false,"bold_title":true},{"t":"art","id":"a5","label":"제5조","title":"고려대학교 자유전공학부 일원은 신념과 종교를 막론하고 누구든지 평등하다.","paras":[{"k":"line","x":"각자의 신념과 종교적 가치관을 존중하고, 그에 근거한 차별적인 언행을 하지 않습니다. 타인의 종교에 대해 ‘개독’과 같은 일반화 표현을 사용하지 않으며, 타인의 종교를 비하하기 위해 ‘사이비’ 등의 차별적 표현을 사용하지 않습니다. 또한 자유전공학부 학생사회는 개개인이 자신의 종교 및 채식주의 등의 신념에 따라 자유롭게 행동할 수 있는 환경을 조성하기 위해 노력해야 합니다."}],"num":5,"sub":null,"bu":false,"bold_title":true},{"t":"art","id":"a6","label":"제6조","title":"고려대학교 자유전공학부 일원은 겉모습으로 타인을 판단하거나 평가하지 않는다.","paras":[{"k":"line","x":"동아리 신입회원 선발 등의 일체의 과정에 있어서 외모에 따른 차별을 행하지 않으며, 엠티, 술자리 등의 일상생활에서 외모와 관련된 차별적 표현을 사용하지 않습니다. 또한 타인의 외모를 평가하거나 특정한 외적 특징을 이유로 조롱하지 않는 등, 타인을 객체나 수단이 아닌 인격체로 존중하는 태도를 가집니다."}],"num":6,"sub":null,"bu":false,"bold_title":true},{"t":"art","id":"a7","label":"제7조","title":"고려대학교 자유전공학부 일원은 자신 및 출신가정의 경제적 여건을 막론하고 평등하다.","paras":[{"k":"line","x":"각자의 경제적 여건에 근거한 편견을 갖지 않으며 이와 관련해 타인을 무시하는 언행을 하지 않습니다. 소득분위나 기초생활수급 여부 등을 이유로 선입견을 갖거나 조롱하지 않습니다."}],"num":7,"sub":null,"bu":false,"bold_title":true},{"t":"art","id":"a8","label":"제8조","title":"고려대학교 자유전공학부 일원은 입학전형을 막론하고 누구든지 평등하다.","paras":[{"k":"line","x":"개개인의 입학전형에 근거한 차별을 행사하지 않습니다. 입학전형은 능력의 차이를 드러내지 않습니다. 예를 들어 ‘기균충’, ‘수시충’ 등 특정 전형을 비하하는 표현을 사용하지 않습니다."}],"num":8,"sub":null,"bu":false,"bold_title":true},{"t":"art","id":"a9","label":"제9조","title":"고려대학교 자유전공학부 일원은 국적과 인종을 막론하고 누구든지 평등하다.","paras":[{"k":"line","x":"자유전공학부는 다양한 문화적 배경을 가진 사람들로 구성되어 있으며, 이러한 차이를 차별의 근거로 삼지 않습니다. 선입견을 바탕으로 한 희화화를 지양하고 다양한 배경을 존중합니다."}],"num":9,"sub":null,"bu":false,"bold_title":true},{"t":"art","id":"a10","label":"제10조","title":"고려대학교 자유전공학부 일원은 출신지역을 막론하고 누구든지 평등하다.","paras":[{"k":"line","x":"지역에 대한 고정관념을 근거로 타인을 규정하지 않습니다. 특정 출신지역을 근거로 한 비하표현 및 지역적 특성으로 타인을 지칭하는 표현을 사용하지 않습니다."}],"num":10,"sub":null,"bu":false,"bold_title":true},{"t":"h","lv":2,"text":"자유전공학부 성평등자치규약"},{"t":"art","id":"a1","label":"제1조","title":"고려대학교 자유전공학부 일원은 성적 자기 결정권을 가진다.","paras":[{"k":"line","x":"성적 자기 결정권이란 첫째, 개인이 사회적 관행이나 타인에 의해 성적 행동을 강요받거나 지배받지 않을 권리, 둘째, 타인의 권리를 침해하지 않는 범위 내에서 자율적으로 자신의 성적 행동을 선택할 권리입니다."}],"num":1,"sub":null,"bu":false,"bold_title":true},{"t":"art","id":"a2","label":"제2조","title":"고려대학교 자유전공학부 일원은 성 고정관념으로부터 자유로울 권리를 가진다.","paras":[{"k":"line","x":"사회적으로 요구되는 성 역할을 강요하지 않으며, 개개인의 고유한 특성을 존중합니다."}],"num":2,"sub":null,"bu":false,"bold_title":true},{"t":"art","id":"a3","label":"제3조","title":"고려대학교 자유전공학부 일원은 모두 성적 대상화로부터 자유로울 권리를 가진다.","paras":[{"k":"line","x":"우리 모두는 외모 등 피상적인 조건에 의해 대상화되지 않고 ‘있는 그대로의 한 사람’으로 인정받을 권리가 있습니다."}],"num":3,"sub":null,"bu":false,"bold_title":true},{"t":"art","id":"a4","label":"제4조","title":"고려대학교 자유전공학부 일원은 개인의 성정체성과 성적 지향에 대한 차별로부터 자유로울 권리를 가진다.","paras":[{"k":"line","x":"성정체성과 성적 지향에 관해 ‘정상성’이란 존재하지 않으며, 따라서 일방적으로 ‘정상성’을 규정하거나 ‘정상’과 ‘비정상’을 구분할 수 없습니다. 성소수자에 대한 고정관념이나 특정 성행위를 바탕으로 한 혐오표현을 사용하지 않습니다. 또한 ‘애인’을 무심코 ‘남자친구’, ‘여자친구’로 지칭하는 등 성소수자의 존재를 부정하는 언어습관을 지양합니다."}],"num":4,"sub":null,"bu":false,"bold_title":true},{"t":"art","id":"a5","label":"제5조","title":"성폭력이 발생한 경우 피해자 중심주의에 입각하여 문제를 해결한다.","paras":[{"k":"line","x":"피해자 중심주의란 특정 사건에 대한 조사 및 여타 처리과정에서 피해자에 대한 보호와 2차 피해의 예방에 우선순위를 두는 것을 말합니다. 성폭력 사건이 발생한 경우 성폭력 대책위원회를 구성해야 합니다. 이때 성폭력 대책위원회는 공론화 여부 및 문제해결 방식을 결정함에 있어서 당사자들, 특히 피해자의 의견을 우선적으로 고려하는 한편 그 과정에서 또 다른 폭력이 발생하지 않도록 해야 합니다."}],"num":5,"sub":null,"bu":false,"bold_title":true}],"note":null}],"current":"pyeongdeung-20172","title":"자유전공학부 평등자치규약 및 성평등자치규약"}]};